-- Lighthouse: every database migration, in order.
-- Built from supabase/migrations on 2026-11-25: 172 migration(s), oldest first, each as written.
-- For a NEW, EMPTY database only. The early migrations create tables outright, so on a database that already
-- has them (live does) this stops at the first one. For live, run deploy/pending-migrations.sql instead.
-- Run it whole in the Supabase SQL editor. Not one transaction: each migration takes effect as it runs, so if one
-- fails, the ones before it stay in, and its own section header below names where it stopped.

-- ==============================================================================================================
-- 20260916120000_init.sql
-- ==============================================================================================================

-- =============================================================================
-- Beacon CRM — initial schema
-- Modernized Postgres port of the legacy DCMPower / BeaconApp SQL Server database.
-- Legacy table names are noted in comments next to each table.
-- =============================================================================

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- updated_at helper
-- ---------------------------------------------------------------------------
create or replace function public.set_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

-- =============================================================================
-- LOOKUP TABLES
-- =============================================================================

-- legacy: UserType
create table public.user_types (
  id          bigint generated always as identity primary key,
  code        text not null unique,          -- e.g. ADMIN, AE, AGENT, CLIENT
  description text not null
);

-- legacy: LEADSTATUS
create table public.lead_statuses (
  id    bigint generated always as identity primary key,
  code  text not null unique,                -- appt, survey, hot, xdate, profile, new
  name  text not null
);

-- legacy: AppointmentStatus
create table public.appointment_statuses (
  id   bigint generated always as identity primary key,
  name text not null unique
);

-- legacy: ProjectType
create table public.project_types (
  id          bigint generated always as identity primary key,
  code        text not null unique,          -- DBDV, APPT
  description text not null
);

-- legacy: ProjectStatus
create table public.project_statuses (
  id   bigint generated always as identity primary key,
  name text not null unique
);

-- legacy: NatureOfEnquiryMaster
create table public.nature_of_enquiry (
  id   bigint generated always as identity primary key,
  name text not null unique
);

-- legacy: FBStatusMaster
create table public.fb_statuses (
  id   bigint generated always as identity primary key,
  name text not null unique
);

-- legacy: Timezone
create table public.timezones (
  id   bigint generated always as identity primary key,
  name text not null unique
);

-- legacy: SICMaster
create table public.sic_codes (
  code        text primary key,
  description text
);

-- =============================================================================
-- CORE: organizations, brands, users
-- =============================================================================

-- legacy: CompanyMaster — the client organizations (insurance agencies that buy
-- the lead-gen service). Surfaced in the UI as "Clients".
create table public.companies (
  id            bigint generated always as identity primary key,
  name          text not null,
  phone         text,
  fax           text,
  contact_name  text,
  contact_title text,
  decision_maker text,
  dm_title      text,
  address       text,
  city          text,
  state         text,
  zip           text,
  country       text,
  email         text,
  website       text,
  sic_code      text references public.sic_codes(code),
  logo_url      text,
  status        text not null default 'active' check (status in ('active','inactive')),
  timezone_id   bigint references public.timezones(id),
  subscription_start date,
  subscription_end   date,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

-- legacy: BrandMaster
create table public.brands (
  id         bigint generated always as identity primary key,
  company_id bigint not null references public.companies(id) on delete cascade,
  logo_url   text,
  url        text
);

-- legacy: UserMaster — internal staff and client-portal users.
-- Linked to Supabase Auth via auth_id.
create table public.users (
  id            bigint generated always as identity primary key,
  auth_id       uuid unique references auth.users(id) on delete set null,
  company_id    bigint references public.companies(id) on delete set null,
  user_type_id  bigint references public.user_types(id),
  role          text not null default 'agent' check (role in ('admin','manager','agent','client')),
  salutation    text,
  first_name    text,
  last_name     text,
  email         text not null,
  phone         text,
  mobile        text,
  phone_ext     text,
  address1      text,
  address2      text,
  city          text,
  state         text,
  zip           text,
  country       text,
  username      text,
  status        text not null default 'active' check (status in ('active','invited','disabled')),
  alerts_enabled boolean not null default true,
  ip_locked     boolean not null default false,
  last_login    timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index on public.users (role);
create index on public.users (company_id);

