  name            text not null,
  project_type_id bigint references public.project_types(id),
  status_id       bigint references public.project_statuses(id),
  description     text,
  client_name     text,
  result          text,
  summary         text,
  amount_paid     numeric(18,2),
  contact_name    text,
  contact_title   text,
  email           text,
  address         text,
  city            text,
  state           text,
  zip             text,
  phone           text,
  fax             text,
  website         text,
