-- ==============================================================================================================
-- 20261012100000_coverage_lines.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — Personal Lines on a name's coverage
--
-- As the client asked: the Coverage tab lists Package, Workers Comp, Auto,
-- Group Health and Personal Lines, each with its X-date and carrier, and
-- account managers fill them in on the lead sheet. Personal Lines is new.
--
--   insurance_details.personal_lines_xdate, personal_lines_carrier
-- ---------------------------------------------------------------------------

alter table public.insurance_details
  add column if not exists personal_lines_xdate   date,
  add column if not exists personal_lines_carrier text check (length(personal_lines_carrier) <= 120);

-- ==============================================================================================================
-- 20261013100000_reminders.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — call-back reminders
--
-- As the client asked: on a lead sheet, before moving on, an account
-- manager sets a reminder ("call him back at 2 pm"). At that time a
-- notification arrives (the bell, and the desktop pop-up or push) linking
-- straight to the lead, and the reminder shows in the lead's call history.
--
--   reminders            who, which name, when (the business's clock), a note
--   set_reminder()       for whoever may work the name (can_work_lead())
--   cancel_reminder()    one's own, not yet sent
--   deliver_reminders()  turns each reminder that is due into a notification;
--                        pg_cron runs it every minute
--   notifications.kind   'reminder' added
-- ---------------------------------------------------------------------------

create extension if not exists pg_cron;

alter table public.notifications drop constraint if exists notifications_kind_check;
alter table public.notifications add constraint notifications_kind_check
  check (kind = any (array['message', 'appointment', 'lead', 'feedback', 'import', 'bulletin', 'system', 'reminder']));

create table if not exists public.reminders (
  id               bigint generated always as identity primary key,
  lead_id          bigint not null references public.leads(id) on delete cascade,
  user_id          bigint not null references public.users(id) on delete cascade,
  remind_at        timestamptz not null,
  note             text check (length(note) <= 300),
  created_at       timestamptz not null default now(),
  sent_at          timestamptz,
  notification_id  bigint references public.notifications(id) on delete set null
);
create index if not exists reminders_due_idx on public.reminders (remind_at) where sent_at is null;
create index if not exists reminders_lead_idx on public.reminders (lead_id, created_at desc);

alter table public.reminders enable row level security;

-- Someone's reminders are their own; an administrator sees everyone's.
drop policy if exists reminders_read on public.reminders;
create policy reminders_read on public.reminders
  for select to authenticated
  using (user_id = (select public.app_user_id()) or (select public.is_admin()));
drop policy if exists mfa_required on public.reminders;
create policy mfa_required on public.reminders as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));

-- Written only through the functions below.
revoke all on public.reminders from anon;
revoke insert, update, delete, truncate on public.reminders from authenticated;
grant select on public.reminders to authenticated;

/**
 * Remind me to call this name back: on `p_date` at `p_time` ("2:00 PM"),
 * on the business's clock, with an optional note. Only for whoever may work
 * the name, and only for a time still ahead. Returns the reminder.
 */
create or replace function public.set_reminder(p_lead_id bigint, p_date date, p_time text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  v_time time;
  v_at   timestamptz;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  r      public.reminders;
begin
  if v_me is null or not public.can_work_lead(p_lead_id) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;
  begin
    v_time := to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time;
  exception when others then
    raise exception 'Choose a time like 2:00 PM' using errcode = '22023';
  end;
  if p_date is null or v_time is null then
    raise exception 'Choose the day and time to be reminded' using errcode = '22023';
  end if;
  v_at := (p_date + v_time) at time zone public.business_tz();
  if v_at < now() - interval '1 minute' then
    raise exception 'That time has already passed' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 300 then
    raise exception 'Keep the note under 300 characters' using errcode = '22023';
  end if;
  insert into public.reminders (lead_id, user_id, remind_at, note)
  values (p_lead_id, v_me, v_at, v_note)
  returning * into r;
  return jsonb_build_object('id', r.id, 'remind_at', r.remind_at);
end $$;

/** Cancel one of my reminders that has not gone off yet. */
create or replace function public.cancel_reminder(p_id bigint)
returns void
language sql security definer set search_path = public as $$
  delete from public.reminders
   where id = p_id and user_id = public.app_user_id() and sent_at is null;
$$;

/**
 * Every reminder that is due becomes a notification to its owner: "Call
 * back: <company>", the time and the note, linking to the lead. The
 * notification is pushed like any other. Run every minute by pg_cron.
 */
create or replace function public.deliver_reminders()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r     record;
  v_id  bigint;
  n     integer := 0;
begin
  for r in
    select m.id, m.user_id, m.lead_id, m.note, m.remind_at, l.company_name
      from public.reminders m
      join public.leads l on l.id = m.lead_id
     where m.sent_at is null and m.remind_at <= now()
     order by m.remind_at
     for update of m skip locked
  loop
    insert into public.notifications (user_id, kind, title, body, link)
    values (
      r.user_id, 'reminder',
      left('Call back: ' || coalesce(r.company_name, 'a lead'), 120),
      left(concat_ws(' · ', 'Reminder for ' || to_char(r.remind_at at time zone public.business_tz(), 'FMHH12:MI AM'), r.note), 1000),
      '/leads/' || r.lead_id
    )
    returning id into v_id;
    update public.reminders set sent_at = now(), notification_id = v_id where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;

revoke execute on function public.set_reminder(bigint, date, text, text) from public, anon;
revoke execute on function public.cancel_reminder(bigint) from public, anon;
revoke execute on function public.deliver_reminders() from public, anon, authenticated;
grant execute on function public.set_reminder(bigint, date, text, text) to authenticated;
grant execute on function public.cancel_reminder(bigint) to authenticated;

-- Every minute. Re-running this file replaces the job rather than adding a second.
select cron.unschedule(jobid) from cron.job where jobname = 'deliver-reminders';
select cron.schedule('deliver-reminders', '* * * * *', 'select public.deliver_reminders()');

-- ==============================================================================================================
-- 20261014100000_lead_delivery.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — lead delivery: the lead sheet emailed to the client
--
-- The old system (MailAlert) emailed a lead's sheet to its project's
-- delivery address whenever a call made it a lead or an appointment, or a
-- link to it instead; and an administrator could send it again
-- ("reprocess"). Requirements FR-ALERT-01/03/04/05, FR-CLI-05, FR-LEAD-08.
--
--   call_results.delivers      which results send the sheet: those that
--                              promote a name (Lead, Lead-Hot Lead) or set an
--                              appointment (Appointment, Appointment-Phone),
--                              as the old rules did; adjustable here
--   projects.email             the delivery addresses (already there); a
--                              leading "_" on one sends it a link, as before
--   projects.delivery_link_only  send every address a link, not the sheet
--   lead_deliveries            every sheet sent, to whom, and whether the mail
--                              service took it. Written only by the server.
-- ---------------------------------------------------------------------------

-- Set up once, when the column is added: running this again never changes a
-- result someone has turned on or off since.
do $$
begin
  if not exists (select 1 from information_schema.columns
                  where table_schema = 'public' and table_name = 'call_results' and column_name = 'delivers') then
    alter table public.call_results add column delivers boolean not null default false;
    update public.call_results set delivers = true where effect in ('promote', 'appointment');
  end if;
end $$;

alter table public.projects add column if not exists delivery_link_only boolean not null default false;

create table if not exists public.lead_deliveries (
  id              bigint generated always as identity primary key,
  lead_id         bigint not null references public.leads(id) on delete cascade,
  project_id      bigint references public.projects(id) on delete set null,
  call_record_id  bigint references public.call_records(id) on delete set null,
  result          text check (length(result) <= 80),
  to_address      text not null check (length(to_address) between 3 and 254),
  link_only       boolean not null default false,
  resent          boolean not null default false,              -- sent again by hand, not by a call
  status          text not null check (status in ('sent', 'failed')),
  error           text check (length(error) <= 500),
  message_id      text check (length(message_id) <= 300),
  sent_by         bigint references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists lead_deliveries_lead_idx on public.lead_deliveries (lead_id, created_at desc);

alter table public.lead_deliveries enable row level security;

drop policy if exists lead_deliveries_read on public.lead_deliveries;
create policy lead_deliveries_read on public.lead_deliveries
  for select to authenticated
  using ((select public.is_staff()));
drop policy if exists mfa_required on public.lead_deliveries;
create policy mfa_required on public.lead_deliveries as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));

-- Only the server writes them, after sending (or failing to).
revoke all on public.lead_deliveries from anon;
revoke insert, update, delete, truncate on public.lead_deliveries from authenticated;
grant select on public.lead_deliveries to authenticated;
grant select, insert on public.lead_deliveries to service_role;

-- The server reads what goes on a sheet with its own role (a delivery runs
-- after the call is saved, and a link is opened by someone not signed in).
grant select on public.leads, public.insurance_details, public.projects, public.companies,
  public.call_records, public.call_results, public.appointments, public.users, public.app_settings
  to service_role;

-- ==============================================================================================================
-- 20261015100000_daily_alerts.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the two alert rules that had nothing behind them
--
--   xdate_30d      "X-date 30-day warning": each morning, every rep hears of
--                  the names they hold whose renewal is 30 days out (one
--                  notification: the name itself, or how many and which)
--   appt_reminder  "Appointment reminder": each morning, whoever set them
--                  hears of the day's appointments, and of tomorrow's still
--                  to confirm
--
-- Both go through notify_users(), so switching a rule off on the Alerts page
-- stops it and each send is logged there; and like every notification they
-- reach the bell, the desktop and push. Sent once a day each (alert_sends),
-- at 7 a.m. on the business's clock or the first hour after: pg_cron runs
-- run_daily_alerts() every hour.
-- ---------------------------------------------------------------------------

create table if not exists public.alert_sends (
  rule     text not null,
  key      text not null,
  sent_at  timestamptz not null default now(),
  primary key (rule, key)
);
alter table public.alert_sends enable row level security;   -- no policies: the jobs alone use it
revoke all on public.alert_sends from anon, authenticated;

/** The renewal-in-30-days warnings for the business's day `p_day`. Returns how many people were told. */
create or replace function public.send_xdate_warnings(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r     record;
  n     integer := 0;
  v_due date := p_day + 30;
begin
  for r in
    with due as (
      select l.id, l.company_name, coalesce(l.assigned_user_id, pa.ae_user_id) as rep
        from public.leads l
        join public.insurance_details i on i.lead_id = l.id
        left join public.call_results cr on cr.id = l.result_id
        -- Nobody holds it: whoever is on its project hears instead.
        left join lateral (select a.ae_user_id from public.project_assignments a
                            where a.project_id = l.project_id and l.assigned_user_id is null) pa on true
       where coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                              i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)) = v_due
         and (cr.id is null or cr.viable)          -- still worth a call: not off the list
    )
    select rep, count(*) as total, min(id) as first_id,
           (array_agg(company_name order by company_name))[1:5] as names
      from due where rep is not null
     group by rep
  loop
    if exists (select 1 from public.alert_sends where rule = 'xdate_30d' and key = r.rep || ':' || p_day) then
      continue;
    end if;
    insert into public.alert_sends (rule, key) values ('xdate_30d', r.rep || ':' || p_day);
    n := n + public.notify_users(
      array[r.rep], 'lead',
      case when r.total = 1 then 'X-date in 30 days: ' || r.names[1]
           else r.total || ' X-dates in 30 days' end,
      'Renewing ' || to_char(v_due, 'FMMon FMDD') ||
        case when r.total = 1 then '' else ': ' || array_to_string(r.names, ', ') ||
          case when r.total > 5 then ' and ' || (r.total - 5) || ' more' else '' end end,
      case when r.total = 1 then '/leads/' || r.first_id else '/work' end,
      'xdate_30d');
  end loop;
  return n;
end $$;

/** The appointment reminders for the business's day `p_day`. Returns how many people were told. */
create or replace function public.send_appointment_reminders(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r record;
  n integer := 0;
begin
  for r in
    with live as (
      select a.user_id, a.appt_date, a.appt_time, a.confirmed_at, l.company_name
        from public.appointments a
        join public.leads l on l.id = a.lead_id
        left join public.appointment_statuses s on s.id = a.status_id
       where a.user_id is not null and a.invalid_at is null
         and coalesce(s.name, '') not in ('Cancelled', 'No Show', 'Invalid')
         and a.appt_date in (p_day, p_day + 1)
    )
    select user_id,
           count(*) filter (where appt_date = p_day) as today,
           count(*) filter (where appt_date = p_day + 1 and confirmed_at is null) as to_confirm,
           array_to_string((array_agg(coalesce(appt_time || ' ', '') || company_name order by appt_time)
                             filter (where appt_date = p_day))[1:5], ', ') as today_list,
           array_to_string((array_agg(company_name order by company_name)
                             filter (where appt_date = p_day + 1 and confirmed_at is null))[1:5], ', ') as confirm_list
      from live
     group by user_id
  loop
    if r.today = 0 and r.to_confirm = 0 then continue; end if;
    if exists (select 1 from public.alert_sends where rule = 'appt_reminder' and key = r.user_id || ':' || p_day) then
      continue;
    end if;
    insert into public.alert_sends (rule, key) values ('appt_reminder', r.user_id || ':' || p_day);
    n := n + public.notify_users(
      array[r.user_id], 'appointment',
      concat_ws(', ',
        case when r.today > 0 then r.today || ' appointment' || case when r.today = 1 then '' else 's' end || ' today' end,
        case when r.to_confirm > 0 then r.to_confirm || ' to confirm for tomorrow' end),
      concat_ws(' · ',
        case when r.today > 0 then 'Today: ' || r.today_list end,
        case when r.to_confirm > 0 then 'Confirm: ' || r.confirm_list end),
      '/calendar?view=day&d=' || p_day,
      'appt_reminder');
  end loop;
  return n;
end $$;

/**
 * Every hour: from 7 a.m. on the business's clock, today's X-date warnings
 * and appointment reminders, each to each person once (later runs that day
 * find them sent and send nothing).
 */
create or replace function public.run_daily_alerts()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_now timestamp := now() at time zone public.business_tz();
begin
  if extract(hour from v_now) < 7 then
    return 0;
  end if;
  return public.send_xdate_warnings(v_now::date) + public.send_appointment_reminders(v_now::date);
end $$;

revoke execute on function public.send_xdate_warnings(date) from public, anon, authenticated;
revoke execute on function public.send_appointment_reminders(date) from public, anon, authenticated;
revoke execute on function public.run_daily_alerts() from public, anon, authenticated;

create extension if not exists pg_cron;
select cron.unschedule(jobid) from cron.job where jobname = 'daily-alerts';
select cron.schedule('daily-alerts', '5 * * * *', 'select public.run_daily_alerts()');

-- The Alerts page said these two were not sending yet; now they do.
update public.alert_rules set channel = 'inapp' where trigger in ('xdate_30d', 'appt_reminder');

-- ==============================================================================================================
-- 20261016100000_appointment_links.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — "Open calendar" points at the appointment
--
-- An "Appointment set" or "Appointment confirmed" notification opened the
-- calendar on the right day; its link now also names the appointment
-- (/calendar?view=day&d=<date>&a=<id>), and the calendar highlights it.
-- Notifications already sent get the same, where the appointment can be told
-- from its day and company name.
-- ---------------------------------------------------------------------------

-- New appointments: as before (20260930120000_lead_lifecycle), the link naming the one appointment.
create or replace function public.tg_notify_appointments()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  r record;
  v_to bigint[];
begin
  for r in
    select p.company_id,
           min(co.name) as company,
           count(*) as n,
           min(a.appt_date) as first_date,
           max(a.appt_date) as last_date,
           array_agg(distinct p.id) filter (where p.id is not null) as project_ids,
           array_agg(distinct l.assigned_user_id) filter (where l.assigned_user_id is not null) as reps,
           (array_agg(l.company_name order by a.appt_date, a.id))[1] as lead_name,
           (array_agg(a.appt_time order by a.appt_date, a.id))[1] as first_time,
           (array_agg(a.id order by a.appt_date, a.id))[1] as first_id,
           bool_or(coalesce(a.qa_status, 'passed') = 'passed') as client_may_know
      from new_rows a
      left join public.leads l     on l.id  = a.lead_id
      left join public.projects p  on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
     group by p.company_id
  loop
    v_to := array(
      select id from public.users where role = 'admin'
      union
      select pa.ae_user_id from public.project_assignments pa
       where pa.project_id = any(r.project_ids) and pa.ae_user_id is not null
      union
      select u.id from public.users u
       where r.client_may_know and u.role = 'client' and r.company_id is not null and u.company_id = r.company_id
      union
      select unnest(r.reps)
    );
    perform public.notify_users(
      v_to, 'appointment',
      case when r.n = 1 then 'Appointment set: ' || coalesce(r.lead_name, 'a lead')
           else r.n || ' appointments set' || coalesce(' for ' || r.company, '') end,
      case when r.n = 1
           then concat_ws(' · ',
                  to_char(r.first_date, 'Dy Mon FMDD') || coalesce(' at ' || r.first_time, ''),
                  r.company,
                  'set by ' || public.actor_name())
           else concat_ws(' · ',
                  to_char(r.first_date, 'Mon FMDD') || ' – ' || to_char(r.last_date, 'Mon FMDD'),
                  'set by ' || public.actor_name()) end,
      '/calendar?view=' || case when r.n = 1 then 'day' else 'month' end
        || '&d=' || coalesce(r.first_date, current_date)::text
        || case when r.n = 1 then '&a=' || r.first_id else '' end,
      'appt_created');
  end loop;
  return null;
end $$;

-- The client's notice: as before (20261005110000_audit_fixes), the link naming the appointment.
create or replace function public.notify_client_appointment(p_appointment bigint, p_confirmed boolean, p_first boolean default false)
returns void
language plpgsql security definer set search_path = public as $$
declare
  a record;
  v_confirmed boolean := p_confirmed;
begin
  select ap.appt_date, ap.appt_time, ap.user_id, l.company_name, co.id as company_id, co.name as company
    into a
    from public.appointments ap
    join public.leads l on l.id = ap.lead_id
    left join public.projects p on p.id = l.project_id
    left join public.companies co on co.id = p.company_id
   where ap.id = p_appointment;
  if a.company_id is null then return; end if;
  if p_confirmed and p_first
     and not exists (select 1 from public.alert_rules where trigger = 'appt_confirmed' and enabled) then
    v_confirmed := false;
  end if;
  perform public.notify_users(
    array(select u.id from public.users u where u.role = 'client' and u.company_id = a.company_id),
    'appointment',
    (case when v_confirmed then 'Appointment confirmed: ' else 'Appointment set: ' end) || coalesce(a.company_name, 'a lead'),
    concat_ws(' · ', to_char(a.appt_date, 'Dy Mon FMDD') || coalesce(' at ' || a.appt_time, ''), a.company),
    '/calendar?view=day&d=' || coalesce(a.appt_date, current_date)::text || '&a=' || p_appointment,
    case when v_confirmed then 'appt_confirmed' else 'appt_created' end,
    null,
    a.user_id);
end $$;
revoke execute on function public.notify_client_appointment(bigint, boolean, boolean) from public, anon, authenticated;

-- Notifications already sent: the appointment on that day for that company
-- (the one at the time the notification gives, when there are two).
update public.notifications n
   set link = n.link || '&a=' || m.appt_id
  from (
    select x.id,
           (select ap.id
              from public.appointments ap
              join public.leads l on l.id = ap.lead_id
             where ap.appt_date = substring(x.link from 'd=(\d{4}-\d{2}-\d{2})$')::date
               and l.company_name = regexp_replace(x.title, '^Appointment (set|confirmed): ', '')
             order by (ap.appt_time is not null and position(' at ' || ap.appt_time in x.body) > 0) desc, ap.id
             limit 1) as appt_id
      from public.notifications x
     where x.kind = 'appointment'
       and x.title ~ '^Appointment (set|confirmed): '
       and x.link ~ '^/calendar\?view=day&d=\d{4}-\d{2}-\d{2}$'
  ) m
 where n.id = m.id and m.appt_id is not null;

-- ==============================================================================================================
-- 20261017100000_lead_sheet.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the lead sheet as the client asked (Sean, Oct 2026)
--
--   1. leads.ein (from list imports, typed on the lead) and leads.client_note:
--      what the client is told with the lead sheet, written as the lead or
--      appointment is set. Call notes stay internal.
--   2. Internal notes out of the clients' reach: the lead's own notes
--      (notes_dcm, and notes_client, the old system's notes, which carry its
--      call history) move from leads, which a client may read, to lead_notes,
--      which only staff may. Call records already were staff only.
--   3. Every standard 4-digit SIC code with its description, so a lead shows
--      "1731 – Electrical Work" (OSHA's SIC manual; codes already on file keep
--      their wording).
--   4. record_call_result(): takes the note for the client; and an
--      appointment recorded again at the same day and time is not noted as
--      "moved".
-- ---------------------------------------------------------------------------

alter table public.leads add column if not exists ein text;
alter table public.leads add column if not exists client_note text;

-- ---------------------------------------------------------------------------
-- 2. Internal notes: staff only
-- ---------------------------------------------------------------------------

create table if not exists public.lead_notes (
  lead_id      bigint primary key references public.leads(id) on delete cascade,
  notes_dcm    text,     -- the account managers' notes on the name
  notes_client text      -- the old system's notes (its call history), as imported
);
alter table public.lead_notes enable row level security;

drop policy if exists lead_notes_staff on public.lead_notes;
create policy lead_notes_staff on public.lead_notes
  for all to authenticated
  using ((select public.is_staff())) with check ((select public.is_staff()));
drop policy if exists mfa_required on public.lead_notes;
create policy mfa_required on public.lead_notes as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.lead_notes;
create policy active_account_required on public.lead_notes as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);

revoke all on public.lead_notes from anon;
grant select, insert, update, delete on public.lead_notes to authenticated;
grant all on public.lead_notes to service_role;

-- Moved, then gone from leads: in one step, so nothing is lost or left behind.
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'leads' and column_name = 'notes_dcm') then
    insert into public.lead_notes (lead_id, notes_dcm, notes_client)
    select id, nullif(btrim(notes_dcm), ''), nullif(btrim(notes_client), '')
      from public.leads
     where nullif(btrim(coalesce(notes_dcm, '')), '') is not null or nullif(btrim(coalesce(notes_client, '')), '') is not null
    on conflict (lead_id) do nothing;
    alter table public.leads drop column notes_dcm, drop column notes_client;
  end if;
end $$;

