-- ---------------------------------------------------------------------------
-- 4. record_call_result(): the note for the client; "moved" only when moved
--    (as 20261007100000_call_results.sql otherwise)
-- ---------------------------------------------------------------------------

drop function if exists public.record_call_result(bigint, bigint, text, jsonb, date, date);
drop function if exists public.record_call_result(bigint, bigint, text, jsonb, date, date, text);

create function public.record_call_result(
  p_lead_id bigint,
  p_result_id bigint,
  p_notes text default null,
  p_appointment jsonb default null,
  p_corrected_xdate date default null,
  p_ultimate_xdate date default null,
  p_client_note text default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me       bigint := public.app_user_id();
  v_role     text   := public.app_role();
  v_notes    text   := nullif(btrim(coalesce(p_notes, '')), '');
  l          public.leads;
  r          public.call_results;
  a_r        public.call_results;      -- the appointment-stage twin of a DBDev result
  p          public.projects;          -- the project the call is made on
  v_type     text;
  v_appt     public.appointments;
  v_open     public.appointments;      -- an appointment the name already holds, which this one moves
  v_call     bigint;
  v_status   bigint;
  v_rep      bigint;
  v_old_xdate date;
  v_pay      jsonb := '[]'::jsonb;
  v_date     date;
  v_time     text;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff can record call results' using errcode = '42501';
  end if;
  if length(coalesce(v_notes, '')) > 1000 then
    raise exception 'Keep call notes under 1,000 characters' using errcode = '22023';
  end if;
  if length(coalesce(p_client_note, '')) > 2000 then
    raise exception 'Keep the note for the client under 2,000 characters' using errcode = '22023';
  end if;

  select * into l from public.leads where id = p_lead_id for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select * into r from public.call_results where id = p_result_id;
  if not found then
    raise exception 'Unknown call result' using errcode = '22023';
  end if;
  if r.applies_to = 'report' then
    raise exception '% is recorded automatically, not from a call', r.name using errcode = '22023';
  end if;

  select * into p from public.projects where id = l.project_id;
  if not found then
    raise exception 'This name is not in a project yet' using errcode = '22023';
  end if;
  v_type := public.project_type_code(p.id);

  -- An appointment follow-up acts on the name's open appointment, recorded
  -- against the stage that appointment was set at so each project counts it.
  if r.applies_to = 'appointment' then
    select * into v_appt from public.appointments
     where lead_id = l.id and invalid_at is null
     order by appt_create_date desc, id desc
     limit 1
     for update;
    if not found then
      raise exception 'This name has no appointment to %', case r.effect when 'confirm' then 'confirm' else 'mark invalid' end
        using errcode = '22023';
    end if;
    if r.effect = 'confirm' and v_appt.confirmed_at is not null then
      raise exception 'This appointment is already confirmed' using errcode = '22023';
    end if;
    select * into r from public.call_results
     where name = r.name and project_type = case coalesce(v_appt.set_stage, l.stage) when 'dbdev' then 'DBDV' else 'APPT' end;
  elsif r.project_type <> v_type then
    raise exception '% is not a result for % projects', r.name,
      case v_type when 'DBDV' then 'database-development' else 'appointment' end using errcode = '22023';
  end if;

  if v_role <> 'admin'
     and l.assigned_user_id is distinct from v_me
     and not exists (select 1 from public.project_assignments pa where pa.project_id = l.project_id and pa.ae_user_id = v_me)
     and not (r.applies_to = 'appointment' and v_appt.user_id = v_me) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;

  -- The call itself.
  insert into public.call_records (lead_id, project_id, user_id, call_result, notes, result_id, stage, call_date)
  values (l.id, l.project_id, v_me, r.name, v_notes, r.id, l.stage, now())
  returning id into v_call;

  select id into v_status from public.lead_statuses where code = r.status_code;

  update public.leads set
    result_id        = r.id,
    call_result_dbdv = case when r.project_type = 'DBDV' then r.name else call_result_dbdv end,
    call_result_appt = case when r.project_type = 'APPT' then r.name
                            when r.effect = 'appointment_invalid' and stage = 'appt' then r.name
                            else call_result_appt end,
    call_weight      = call_weight + case when r.applies_to = 'name' then 1 else 0 end,
    date_last_worked = now(),
    status_id        = coalesce(v_status, status_id),
    resolved_at      = case when r.viable then null else coalesce(resolved_at, now()) end,
    assigned_user_id = case when r.effect = 'pending' then null else assigned_user_id end
  where id = l.id;

  -- What the result does.
  if r.effect in ('promote', 'appointment') then
    -- A name becomes a Lead or an Appointment only with its renewal date
    -- confirmed: the Ultimate X-Date, entered (or corrected) with this result,
    -- or already on the record. A date on a policy line alone is a potential
    -- renewal the account manager has not confirmed yet.
    if p_ultimate_xdate is not null then
      update public.insurance_details set ultimate_xdate = p_ultimate_xdate where lead_id = l.id;
      if not found then
        insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_ultimate_xdate);
      end if;
    end if;
    if not exists (select 1 from public.insurance_details i where i.lead_id = l.id and i.ultimate_xdate is not null) then
      raise exception 'Enter the Ultimate X-Date: a name becomes a Lead or an Appointment only with its renewal date'
        using errcode = '22023';
    end if;

    -- What the client is told, with the lead sheet: written as the name is
    -- set (given empty, it is cleared). The call notes stay internal.
    if p_client_note is not null then
      update public.leads set client_note = nullif(btrim(p_client_note), '') where id = l.id;
    end if;

    if r.effect = 'appointment' then
      v_date := nullif(p_appointment->>'date', '')::date;
      v_time := nullif(btrim(coalesce(p_appointment->>'time', '')), '');
      if v_date is null then
        raise exception 'Choose the appointment date' using errcode = '22023';
      end if;
      if v_date < current_date - 1 then
        raise exception 'The appointment date has passed' using errcode = '22023';
      end if;
      if v_time is null then
        raise exception 'Choose the appointment time' using errcode = '22023';
      end if;
      if v_time !~* '^\d{1,2}:\d{2}\s?(AM|PM)$' then
        raise exception 'Give the time like 9:30 AM' using errcode = '22023';
      end if;
    end if;

    -- A name that already holds an appointment still to come, or still
    -- waiting for QA, has that one moved: one appointment, paid once.
    -- (Recording the result again is how a rep reschedules from the sheet.)
    -- One that failed QA does not count: the rep sets a real one instead.
    if r.effect = 'appointment' then
      select * into v_open from public.appointments
       where lead_id = l.id and invalid_at is null and qa_status is distinct from 'failed'
         and (qa_status = 'pending' or appt_date >= (now() at time zone public.business_tz())::date)
       order by appt_create_date desc, id desc
       limit 1
       for update;
    end if;

    if v_open.id is not null then
      update public.appointments set
        appt_date    = v_date,
        appt_time    = v_time,
        duration_min = coalesce(nullif(p_appointment->>'duration', '')::int, duration_min),
        rep_name     = coalesce(nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), rep_name),
        status_id    = case when status_id = (select id from public.appointment_statuses where name = 'Scheduled')
                             and (appt_date, coalesce(appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                            then (select id from public.appointment_statuses where name = 'Rescheduled')
                            else status_id end,
        status_update_date = now()
      where id = v_open.id
      returning * into v_appt;
      -- "Moved" only when the day or the time changed.
      update public.call_records set
        appointment_id = v_appt.id,
        notes = case when (v_open.appt_date, coalesce(v_open.appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                     then concat_ws(E'\n', notes, 'Appointment moved from ' || to_char(v_open.appt_date, 'Mon FMDD')
                            || coalesce(' ' || v_open.appt_time, '') || ' to ' || to_char(v_date, 'Mon FMDD') || coalesce(' ' || v_time, ''))
                     else notes end
      where id = v_call;
    else

      -- From DBDev, the name moves to the linked appointment project.
      if v_type = 'DBDV' then
        if p.appt_project_id is null then
          raise exception 'Link % to an appointment project before promoting its names', p.name using errcode = '22023';
        end if;
        select * into a_r from public.call_results
         where project_type = 'APPT' and name = case r.effect when 'promote' then 'Lead-No Contact' else r.name end;
        -- A new lead goes to the appointment manager with the fewest names; an
        -- appointment stays with the rep who set it, who confirms it.
        v_rep := case r.effect when 'promote' then public.least_loaded_rep(p.appt_project_id) else v_me end;
        update public.leads set
          stage             = 'appt',
          project_id        = p.appt_project_id,
          source_project_id = coalesce(source_project_id, l.project_id),
          dbdv_user_id      = v_me,
          assigned_user_id  = v_rep,
          result_id         = a_r.id,
          call_result_appt  = a_r.name,
          call_weight       = 0,
          promoted_at       = now(),
          resolved_at       = case when a_r.viable then null else now() end
        where id = l.id;
      end if;

      if r.effect = 'appointment' then
        insert into public.appointments
          (lead_id, user_id, rep_name, appt_date, appt_time, duration_min, status_id, list_source,
           call_result_dbdv, project_id, set_project_id, set_stage, call_record_id, qa_status)
        values
          (l.id, v_me, nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), v_date, v_time,
           coalesce(nullif(p_appointment->>'duration', '')::int, 30),
           (select id from public.appointment_statuses where name = 'Scheduled'),
           l.list_source,
           case when v_type = 'DBDV' then r.name end,
           coalesce(p.appt_project_id, p.id), p.id, l.stage, v_call, 'pending')
        returning * into v_appt;
        update public.leads set appt_created_date = now() where id = l.id;
        update public.call_records set appointment_id = v_appt.id where id = v_call;
      end if;

      v_pay := v_pay || public.pay(v_me, p.id, r.pay_kind, l.id, v_appt.id, v_call);

    end if;

  elsif r.effect = 'confirm' then
    update public.appointments set
      status_id    = (select id from public.appointment_statuses where name = 'Confirmed'),
      confirmed_at = now(),
      confirmed_by = v_me,
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := v_pay || public.pay(v_me, coalesce(v_appt.set_project_id, p.id), 'confirmation', l.id, v_appt.id, v_call);
    -- The client hears now only if QA has already let them see it.
    if coalesce(v_appt.qa_status, 'passed') = 'passed' then
      perform public.notify_client_appointment(v_appt.id, true);
    end if;

  elsif r.effect = 'appointment_invalid' then
    update public.appointments set
      invalid_at = now(),
      status_id  = (select id from public.appointment_statuses where name = 'Invalid'),
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := public.charge_back(l.id, v_appt.id, array['appointment', 'confirmation'], v_call, 'Appointment invalid');

  elsif r.effect = 'lead_invalid' then
    update public.leads set call_result_dbdv = 'Lead-Invalid' where id = l.id and source_project_id is not null;
    v_pay := public.charge_back(l.id, null, array['lead'], v_call, 'Lead invalid');
    -- No record of the original payment (an older lead): charge the developer at today's rate.
    if jsonb_array_length(v_pay) = 0 and l.dbdv_user_id is not null and l.source_project_id is not null then
      insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
      select l.dbdv_user_id, l.source_project_id, l.id, v_call, 'lead', -sp.lead_rate, 'Lead invalid (no original payment on record)', v_me
        from public.projects sp where sp.id = l.source_project_id;
      v_pay := jsonb_build_array(jsonb_build_object('user_id', l.dbdv_user_id, 'kind', 'lead',
                 'amount', -(select lead_rate from public.projects where id = l.source_project_id)));
    end if;
    if l.dbdv_user_id is not null then
      perform public.notify_users(
        array[l.dbdv_user_id], 'lead', 'Lead marked invalid: ' || coalesce(l.company_name, 'a lead'),
        concat_ws(' · ', 'Charged back on your production report', 'marked by ' || public.actor_name()),
        '/leads/' || l.id, 'lead_invalid');
    end if;

  elsif r.effect = 'correct_xdate' then
    if p_corrected_xdate is null then
      raise exception 'Enter the corrected renewal date' using errcode = '22023';
    end if;
    v_old_xdate := public.lead_renewal_date(l.id);
    -- The corrected date becomes the lead's ultimate X-date, which is its
    -- renewal; the dates on the individual policy lines are left as recorded.
    update public.insurance_details set ultimate_xdate = p_corrected_xdate where lead_id = l.id;
    if not found then
      insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_corrected_xdate);
    end if;
    update public.leads set original_xdate = coalesce(original_xdate, v_old_xdate) where id = l.id;
    update public.call_records
       set notes = concat_ws(E'\n', notes, 'Renewal corrected from '
                   || coalesce(to_char(v_old_xdate, 'FMMonth YYYY'), 'none') || ' to ' || to_char(p_corrected_xdate, 'FMMonth YYYY'))
     where id = v_call;
  end if;

  select * into l from public.leads where id = l.id;
  return jsonb_build_object(
    'call_record_id', v_call,
    'lead_id',        l.id,
    'result',         r.name,
    'stage',          l.stage,
    'project_id',     l.project_id,
    'promoted',       l.project_id is distinct from p.id,
    'on_list',        (select viable and callable from public.call_results where id = l.result_id) and l.assigned_user_id is not null,
    'appointment_id', v_appt.id,
    'rescheduled',    v_open.id is not null,
    'pay',            v_pay);
end $$;

revoke execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text) from public, anon;
grant execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text) to authenticated;

-- ==============================================================================================================
-- 20261018100000_lead_notes_swap.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a lead's two notes, as the client uses them (Sean, Oct 2026)
--
--   Client notes    leads.client_note: what the client sees (the lead sheet
--                   email, the calendar). The note a list imported as its
--                   "Notes" (lead_notes.notes_dcm, shown as "Internal notes")
--                   is the client's note in their system, so it joins it.
--   Internal notes  lead_notes.notes: staff only, never shown to a client.
--                   What was the old system's notes (lead_notes.notes_client,
--                   its call history).
--
-- Run once; a second run finds nothing left to move.
-- ---------------------------------------------------------------------------

do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'lead_notes' and column_name = 'notes_dcm') then
    -- Into the client notes: after what is there, unless it is there already.
    update public.leads l
       set client_note = case when nullif(btrim(coalesce(l.client_note, '')), '') is null then btrim(n.notes_dcm)
                              else l.client_note || E'\n' || btrim(n.notes_dcm) end
      from public.lead_notes n
     where n.lead_id = l.id
       and nullif(btrim(coalesce(n.notes_dcm, '')), '') is not null
       and position(btrim(n.notes_dcm) in coalesce(l.client_note, '')) = 0;

    alter table public.lead_notes drop column notes_dcm;
    alter table public.lead_notes rename column notes_client to notes;
    delete from public.lead_notes where nullif(btrim(coalesce(notes, '')), '') is null;
  end if;
end $$;

comment on column public.lead_notes.notes is 'Internal notes: staff only, never shown to a client.';
comment on column public.leads.client_note is 'Client notes: what the client sees, in the lead sheet email and on the calendar.';

-- ==============================================================================================================
-- 20261019100000_call_notes_history.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — call notes keep the lead's internal history (Sean, Oct 2026)
--
-- The notes a rep writes on a call ("10/8/26 seanf: spoke with Daniel…") are
-- added to the end of the lead's Internal notes, as the old system kept its
-- running history there; they stay on the call in the call history too.
-- Calls already made in Lighthouse are added once, in the order they were
-- made (a note already there is not added again, so running this twice
-- changes nothing).
-- ---------------------------------------------------------------------------

drop function if exists public.record_call_result(bigint, bigint, text, jsonb, date, date, text);

create function public.record_call_result(
  p_lead_id bigint,
  p_result_id bigint,
  p_notes text default null,
  p_appointment jsonb default null,
  p_corrected_xdate date default null,
  p_ultimate_xdate date default null,
  p_client_note text default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me       bigint := public.app_user_id();
  v_role     text   := public.app_role();
  v_notes    text   := nullif(btrim(coalesce(p_notes, '')), '');
  l          public.leads;
  r          public.call_results;
  a_r        public.call_results;      -- the appointment-stage twin of a DBDev result
  p          public.projects;          -- the project the call is made on
  v_type     text;
  v_appt     public.appointments;
  v_open     public.appointments;      -- an appointment the name already holds, which this one moves
  v_call     bigint;
  v_status   bigint;
  v_rep      bigint;
  v_old_xdate date;
  v_pay      jsonb := '[]'::jsonb;
  v_date     date;
  v_time     text;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff can record call results' using errcode = '42501';
  end if;
  if length(coalesce(v_notes, '')) > 1000 then
    raise exception 'Keep call notes under 1,000 characters' using errcode = '22023';
  end if;
  if length(coalesce(p_client_note, '')) > 2000 then
    raise exception 'Keep the note for the client under 2,000 characters' using errcode = '22023';
  end if;

  select * into l from public.leads where id = p_lead_id for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select * into r from public.call_results where id = p_result_id;
  if not found then
    raise exception 'Unknown call result' using errcode = '22023';
  end if;
  if r.applies_to = 'report' then
    raise exception '% is recorded automatically, not from a call', r.name using errcode = '22023';
  end if;

  select * into p from public.projects where id = l.project_id;
  if not found then
    raise exception 'This name is not in a project yet' using errcode = '22023';
  end if;
  v_type := public.project_type_code(p.id);

  -- An appointment follow-up acts on the name's open appointment, recorded
  -- against the stage that appointment was set at so each project counts it.
  if r.applies_to = 'appointment' then
    select * into v_appt from public.appointments
     where lead_id = l.id and invalid_at is null
     order by appt_create_date desc, id desc
     limit 1
     for update;
    if not found then
      raise exception 'This name has no appointment to %', case r.effect when 'confirm' then 'confirm' else 'mark invalid' end
        using errcode = '22023';
    end if;
    if r.effect = 'confirm' and v_appt.confirmed_at is not null then
      raise exception 'This appointment is already confirmed' using errcode = '22023';
    end if;
    select * into r from public.call_results
     where name = r.name and project_type = case coalesce(v_appt.set_stage, l.stage) when 'dbdev' then 'DBDV' else 'APPT' end;
  elsif r.project_type <> v_type then
    raise exception '% is not a result for % projects', r.name,
      case v_type when 'DBDV' then 'database-development' else 'appointment' end using errcode = '22023';
  end if;

  if v_role <> 'admin'
     and l.assigned_user_id is distinct from v_me
     and not exists (select 1 from public.project_assignments pa where pa.project_id = l.project_id and pa.ae_user_id = v_me)
     and not (r.applies_to = 'appointment' and v_appt.user_id = v_me) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;

  -- The call itself.
  insert into public.call_records (lead_id, project_id, user_id, call_result, notes, result_id, stage, call_date)
  values (l.id, l.project_id, v_me, r.name, v_notes, r.id, l.stage, now())
  returning id into v_call;

  select id into v_status from public.lead_statuses where code = r.status_code;

  update public.leads set
    result_id        = r.id,
    call_result_dbdv = case when r.project_type = 'DBDV' then r.name else call_result_dbdv end,
    call_result_appt = case when r.project_type = 'APPT' then r.name
                            when r.effect = 'appointment_invalid' and stage = 'appt' then r.name
                            else call_result_appt end,
    call_weight      = call_weight + case when r.applies_to = 'name' then 1 else 0 end,
    date_last_worked = now(),
    status_id        = coalesce(v_status, status_id),
    resolved_at      = case when r.viable then null else coalesce(resolved_at, now()) end,
    assigned_user_id = case when r.effect = 'pending' then null else assigned_user_id end
  where id = l.id;

  -- What the result does.
  if r.effect in ('promote', 'appointment') then
    -- A name becomes a Lead or an Appointment only with its renewal date
    -- confirmed: the Ultimate X-Date, entered (or corrected) with this result,
    -- or already on the record. A date on a policy line alone is a potential
    -- renewal the account manager has not confirmed yet.
    if p_ultimate_xdate is not null then
      update public.insurance_details set ultimate_xdate = p_ultimate_xdate where lead_id = l.id;
      if not found then
        insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_ultimate_xdate);
      end if;
    end if;
    if not exists (select 1 from public.insurance_details i where i.lead_id = l.id and i.ultimate_xdate is not null) then
      raise exception 'Enter the Ultimate X-Date: a name becomes a Lead or an Appointment only with its renewal date'
        using errcode = '22023';
    end if;

    -- What the client is told, with the lead sheet: written as the name is
    -- set (given empty, it is cleared). The call notes stay internal.
    if p_client_note is not null then
      update public.leads set client_note = nullif(btrim(p_client_note), '') where id = l.id;
    end if;

    if r.effect = 'appointment' then
      v_date := nullif(p_appointment->>'date', '')::date;
      v_time := nullif(btrim(coalesce(p_appointment->>'time', '')), '');
      if v_date is null then
        raise exception 'Choose the appointment date' using errcode = '22023';
      end if;
      if v_date < current_date - 1 then
        raise exception 'The appointment date has passed' using errcode = '22023';
      end if;
      if v_time is null then
        raise exception 'Choose the appointment time' using errcode = '22023';
      end if;
      if v_time !~* '^\d{1,2}:\d{2}\s?(AM|PM)$' then
        raise exception 'Give the time like 9:30 AM' using errcode = '22023';
      end if;
    end if;

    -- A name that already holds an appointment still to come, or still
    -- waiting for QA, has that one moved: one appointment, paid once.
    -- (Recording the result again is how a rep reschedules from the sheet.)
    -- One that failed QA does not count: the rep sets a real one instead.
    if r.effect = 'appointment' then
      select * into v_open from public.appointments
       where lead_id = l.id and invalid_at is null and qa_status is distinct from 'failed'
         and (qa_status = 'pending' or appt_date >= (now() at time zone public.business_tz())::date)
       order by appt_create_date desc, id desc
       limit 1
       for update;
    end if;

    if v_open.id is not null then
      update public.appointments set
        appt_date    = v_date,
        appt_time    = v_time,
        duration_min = coalesce(nullif(p_appointment->>'duration', '')::int, duration_min),
        rep_name     = coalesce(nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), rep_name),
        status_id    = case when status_id = (select id from public.appointment_statuses where name = 'Scheduled')
                             and (appt_date, coalesce(appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                            then (select id from public.appointment_statuses where name = 'Rescheduled')
                            else status_id end,
        status_update_date = now()
      where id = v_open.id
      returning * into v_appt;
      -- "Moved" only when the day or the time changed.
      update public.call_records set
        appointment_id = v_appt.id,
        notes = case when (v_open.appt_date, coalesce(v_open.appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                     then concat_ws(E'\n', notes, 'Appointment moved from ' || to_char(v_open.appt_date, 'Mon FMDD')
                            || coalesce(' ' || v_open.appt_time, '') || ' to ' || to_char(v_date, 'Mon FMDD') || coalesce(' ' || v_time, ''))
                     else notes end
      where id = v_call;
    else

      -- From DBDev, the name moves to the linked appointment project.
      if v_type = 'DBDV' then
        if p.appt_project_id is null then
          raise exception 'Link % to an appointment project before promoting its names', p.name using errcode = '22023';
        end if;
        select * into a_r from public.call_results
         where project_type = 'APPT' and name = case r.effect when 'promote' then 'Lead-No Contact' else r.name end;
        -- A new lead goes to the appointment manager with the fewest names; an
        -- appointment stays with the rep who set it, who confirms it.
        v_rep := case r.effect when 'promote' then public.least_loaded_rep(p.appt_project_id) else v_me end;
        update public.leads set
          stage             = 'appt',
          project_id        = p.appt_project_id,
          source_project_id = coalesce(source_project_id, l.project_id),
          dbdv_user_id      = v_me,
          assigned_user_id  = v_rep,
          result_id         = a_r.id,
          call_result_appt  = a_r.name,
          call_weight       = 0,
          promoted_at       = now(),
          resolved_at       = case when a_r.viable then null else now() end
        where id = l.id;
      end if;

      if r.effect = 'appointment' then
        insert into public.appointments
          (lead_id, user_id, rep_name, appt_date, appt_time, duration_min, status_id, list_source,
           call_result_dbdv, project_id, set_project_id, set_stage, call_record_id, qa_status)
        values
          (l.id, v_me, nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), v_date, v_time,
           coalesce(nullif(p_appointment->>'duration', '')::int, 30),
           (select id from public.appointment_statuses where name = 'Scheduled'),
           l.list_source,
           case when v_type = 'DBDV' then r.name end,
           coalesce(p.appt_project_id, p.id), p.id, l.stage, v_call, 'pending')
        returning * into v_appt;
        update public.leads set appt_created_date = now() where id = l.id;
        update public.call_records set appointment_id = v_appt.id where id = v_call;
      end if;

      v_pay := v_pay || public.pay(v_me, p.id, r.pay_kind, l.id, v_appt.id, v_call);

    end if;

  elsif r.effect = 'confirm' then
    update public.appointments set
      status_id    = (select id from public.appointment_statuses where name = 'Confirmed'),
      confirmed_at = now(),
      confirmed_by = v_me,
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := v_pay || public.pay(v_me, coalesce(v_appt.set_project_id, p.id), 'confirmation', l.id, v_appt.id, v_call);
    -- The client hears now only if QA has already let them see it.
    if coalesce(v_appt.qa_status, 'passed') = 'passed' then
      perform public.notify_client_appointment(v_appt.id, true);
    end if;

  elsif r.effect = 'appointment_invalid' then
    update public.appointments set
      invalid_at = now(),
      status_id  = (select id from public.appointment_statuses where name = 'Invalid'),
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := public.charge_back(l.id, v_appt.id, array['appointment', 'confirmation'], v_call, 'Appointment invalid');

  elsif r.effect = 'lead_invalid' then
    update public.leads set call_result_dbdv = 'Lead-Invalid' where id = l.id and source_project_id is not null;
    v_pay := public.charge_back(l.id, null, array['lead'], v_call, 'Lead invalid');
    -- No record of the original payment (an older lead): charge the developer at today's rate.
    if jsonb_array_length(v_pay) = 0 and l.dbdv_user_id is not null and l.source_project_id is not null then
      insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
      select l.dbdv_user_id, l.source_project_id, l.id, v_call, 'lead', -sp.lead_rate, 'Lead invalid (no original payment on record)', v_me
        from public.projects sp where sp.id = l.source_project_id;
      v_pay := jsonb_build_array(jsonb_build_object('user_id', l.dbdv_user_id, 'kind', 'lead',
                 'amount', -(select lead_rate from public.projects where id = l.source_project_id)));
    end if;
    if l.dbdv_user_id is not null then
      perform public.notify_users(
        array[l.dbdv_user_id], 'lead', 'Lead marked invalid: ' || coalesce(l.company_name, 'a lead'),
        concat_ws(' · ', 'Charged back on your production report', 'marked by ' || public.actor_name()),
        '/leads/' || l.id, 'lead_invalid');
    end if;

  elsif r.effect = 'correct_xdate' then
    if p_corrected_xdate is null then
      raise exception 'Enter the corrected renewal date' using errcode = '22023';
    end if;
    v_old_xdate := public.lead_renewal_date(l.id);
    -- The corrected date becomes the lead's ultimate X-date, which is its
    -- renewal; the dates on the individual policy lines are left as recorded.
    update public.insurance_details set ultimate_xdate = p_corrected_xdate where lead_id = l.id;
    if not found then
      insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_corrected_xdate);
    end if;
    update public.leads set original_xdate = coalesce(original_xdate, v_old_xdate) where id = l.id;
    update public.call_records
       set notes = concat_ws(E'\n', notes, 'Renewal corrected from '
                   || coalesce(to_char(v_old_xdate, 'FMMonth YYYY'), 'none') || ' to ' || to_char(p_corrected_xdate, 'FMMonth YYYY'))
     where id = v_call;
  end if;

  -- What was said on the call joins the lead's internal notes, their running
  -- history (as the old system kept them), stamped as the rep wrote it.
  if v_notes is not null then
    insert into public.lead_notes (lead_id, notes)
    select l.id, btrim(c.notes) from public.call_records c where c.id = v_call
    on conflict (lead_id) do update
      set notes = concat_ws(E'\n', nullif(btrim(public.lead_notes.notes), ''), excluded.notes);
  end if;

  select * into l from public.leads where id = l.id;
  return jsonb_build_object(
    'call_record_id', v_call,
    'lead_id',        l.id,
    'result',         r.name,
    'stage',          l.stage,
    'project_id',     l.project_id,
    'promoted',       l.project_id is distinct from p.id,
    'on_list',        (select viable and callable from public.call_results where id = l.result_id) and l.assigned_user_id is not null,
    'appointment_id', v_appt.id,
    'rescheduled',    v_open.id is not null,
    'pay',            v_pay);
end $$;

revoke execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text) from public, anon;
grant execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text) to authenticated;

-- The calls made so far.
with calls as (
  select c.lead_id, string_agg(btrim(c.notes), E'\n' order by c.call_date, c.id) as notes
    from public.call_records c
    left join public.lead_notes n on n.lead_id = c.lead_id
   where nullif(btrim(coalesce(c.notes, '')), '') is not null
     and position(btrim(c.notes) in coalesce(n.notes, '')) = 0
   group by c.lead_id
)
insert into public.lead_notes (lead_id, notes)
select lead_id, notes from calls
on conflict (lead_id) do update
  set notes = concat_ws(E'\n', nullif(btrim(public.lead_notes.notes), ''), excluded.notes);

-- ==============================================================================================================
-- 20261020100000_internal_notes_managers.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — internal notes for administrators and managers only
-- (Sean, Oct 2026: "Agents should only see client notes")
--
--   lead_notes          a lead's internal notes: administrators and account
--                       managers read and write them; agents and clients
--                       neither.
--   call_records.notes  what was said on a call: no one signed in reads the
--                       column directly any more (agents still read the
--                       calls themselves, for QA and the history);
--                       administrators and managers read it through
--                       call_notes(). record_call_result() still writes it.
-- ---------------------------------------------------------------------------

/** Administrators and account managers: those who see a lead's internal notes and its call notes. */
create or replace function public.sees_internal_notes()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce(public.app_role() in ('admin', 'manager'), false);
$$;
revoke execute on function public.sees_internal_notes() from public, anon;
grant execute on function public.sees_internal_notes() to authenticated;

drop policy if exists lead_notes_staff on public.lead_notes;
drop policy if exists lead_notes_managers on public.lead_notes;
create policy lead_notes_managers on public.lead_notes
  for all to authenticated
  using ((select public.sees_internal_notes())) with check ((select public.sees_internal_notes()));

-- Call records: every column but the notes.
revoke select on public.call_records from anon, authenticated;
do $$
declare
  v_cols text;
begin
  select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols
    from information_schema.columns
   where table_schema = 'public' and table_name = 'call_records' and column_name <> 'notes';
  execute format('grant select (%s) on public.call_records to authenticated', v_cols);
end $$;
comment on column public.call_records.notes is
  'What was said on the call: internal. Not readable directly; administrators and managers read it through call_notes(). A column added to call_records must be granted: grant select (<column>) on public.call_records to authenticated.';

/** The notes on a lead's calls, for administrators and managers; nothing for anyone else. */
create or replace function public.call_notes(p_lead_id bigint)
returns table (id bigint, notes text)
language sql stable security definer set search_path = public as $$
  select c.id, c.notes
    from public.call_records c
   where c.lead_id = p_lead_id and c.notes is not null and public.sees_internal_notes();
$$;
revoke execute on function public.call_notes(bigint) from public, anon;
grant execute on function public.call_notes(bigint) to authenticated;

-- ==============================================================================================================
-- 20261021100000_pay_periods.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a pay period schedule (Sean, Oct 2026)
--
-- The business plans its pay periods for the year, staggered (9/30–10/13,
-- 10/14–10/28, …), each with its pay date and the days it is closed or
-- optional. An administrator enters them in Settings; with "Custom schedule"
-- chosen as the pay period, Pay & Hours follows them, and every account
-- manager sees the year's schedule there.
--
--   pay_periods   one row a period: its first and last day, when it is paid,
--                 the closed days (not counted as work days) and the optional
--                 ones, each set with what it is ("New Years", "MLK Day").
--                 Periods never overlap.
-- ---------------------------------------------------------------------------

create table if not exists public.pay_periods (
  id              bigint generated always as identity primary key,
  starts_on       date not null,
  ends_on         date not null,
  pay_date        date,
  closed_dates    date[] not null default '{}',
  closed_label    text,
  optional_dates  date[] not null default '{}',
  optional_label  text,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint pay_periods_in_order check (ends_on >= starts_on and ends_on - starts_on <= 62),
  constraint pay_periods_labels check (length(coalesce(closed_label, '')) <= 80 and length(coalesce(optional_label, '')) <= 80),
  constraint pay_periods_no_overlap exclude using gist (daterange(starts_on, ends_on, '[]') with &&)
);
create index if not exists pay_periods_starts on public.pay_periods (starts_on);

alter table public.pay_periods enable row level security;

drop policy if exists pay_periods_read on public.pay_periods;
create policy pay_periods_read on public.pay_periods
  for select to authenticated using ((select public.is_staff()));
drop policy if exists pay_periods_write on public.pay_periods;
create policy pay_periods_write on public.pay_periods
  for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists mfa_required on public.pay_periods;
create policy mfa_required on public.pay_periods as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.pay_periods;
create policy active_account_required on public.pay_periods as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);

revoke all on public.pay_periods from anon;
grant select, insert, update, delete on public.pay_periods to authenticated;
grant all on public.pay_periods to service_role;

-- ==============================================================================================================
-- 20261022100000_manager_dashboard.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the account manager's dashboard (Sean, Oct 2026)
--
--   daily_goals               the leads and appointments a manager means to
--                             develop today, set as they start their day; the
--                             dashboard tracks the % reached.
--   project_assignment_log    each project assignment made or removed, so
--                             "Active Projects" can say what changed in the
--                             last 30 days (assignments carry no dates).
--   daily_production(day)     per person and day: when they started using
--                             Lighthouse, their calls, leads and appointments
--                             (as the production report counts them), the
--                             minutes worked, and their goals. Everyone for an
--                             administrator; anyone else, themselves.
-- ---------------------------------------------------------------------------

create table if not exists public.daily_goals (
  user_id     bigint not null references public.users(id) on delete cascade,
  day         date not null,
  leads_goal  int check (leads_goal between 0 and 1000),
  appts_goal  int check (appts_goal between 0 and 1000),
  updated_at  timestamptz not null default now(),
  primary key (user_id, day)
);
alter table public.daily_goals enable row level security;

drop policy if exists daily_goals_read on public.daily_goals;
create policy daily_goals_read on public.daily_goals
  for select to authenticated
  using ((select public.is_admin()) or user_id = (select public.app_user_id()));
drop policy if exists daily_goals_write on public.daily_goals;
create policy daily_goals_write on public.daily_goals
  for all to authenticated
  using (user_id = (select public.app_user_id()) and (select public.is_staff()))
  with check (user_id = (select public.app_user_id()) and (select public.is_staff()));
drop policy if exists mfa_required on public.daily_goals;
create policy mfa_required on public.daily_goals as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.daily_goals;
create policy active_account_required on public.daily_goals as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.daily_goals from anon;
grant select, insert, update, delete on public.daily_goals to authenticated;
grant all on public.daily_goals to service_role;

-- Each assignment made (+1) or removed (-1), for whom and when.
create table if not exists public.project_assignment_log (
  id          bigint generated always as identity primary key,
  user_id     bigint not null,
  project_id  bigint not null,
  change      smallint not null check (change in (-1, 1)),
  at          timestamptz not null default now()
);
create index if not exists project_assignment_log_user on public.project_assignment_log (user_id, at desc);
alter table public.project_assignment_log enable row level security;
drop policy if exists project_assignment_log_read on public.project_assignment_log;
create policy project_assignment_log_read on public.project_assignment_log
  for select to authenticated
  using ((select public.is_admin()) or user_id = (select public.app_user_id()));
drop policy if exists mfa_required on public.project_assignment_log;
create policy mfa_required on public.project_assignment_log as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
revoke all on public.project_assignment_log from anon;
revoke insert, update, delete on public.project_assignment_log from authenticated;
grant select on public.project_assignment_log to authenticated;
grant all on public.project_assignment_log to service_role;

create or replace function public.tg_log_project_assignment()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if tg_op in ('UPDATE', 'DELETE') and old.ae_user_id is not null
     and (tg_op = 'DELETE' or old.ae_user_id is distinct from new.ae_user_id or old.project_id is distinct from new.project_id) then
    insert into public.project_assignment_log (user_id, project_id, change) values (old.ae_user_id, old.project_id, -1);
  end if;
  if tg_op in ('INSERT', 'UPDATE') and new.ae_user_id is not null
     and (tg_op = 'INSERT' or old.ae_user_id is distinct from new.ae_user_id or old.project_id is distinct from new.project_id) then
    insert into public.project_assignment_log (user_id, project_id, change) values (new.ae_user_id, new.project_id, 1);
  end if;
  return null;
end $$;
drop trigger if exists project_assignments_log on public.project_assignments;
create trigger project_assignments_log
  after insert or update or delete on public.project_assignments
  for each row execute function public.tg_log_project_assignment();

/**
 * One day's production per person (the business's day; today by default):
 * account managers, and agents who worked that day. When they first used
 * Lighthouse, their calls, leads and appointments (the production report's
 * counts), minutes worked and paid (Pay & Hours'), and the goals they set.
 * Row Level Security decides whose: everyone's for an administrator.
 */
create or replace function public.daily_production(p_day date default null)
returns table (
  user_id bigint, first_name text, last_name text, role text,
  started_at timestamptz, calls bigint, leads bigint, appointments bigint,
  worked_minutes int, paid_minutes int, leads_goal int, appts_goal int
)
language sql stable security invoker set search_path = public as $$
  with d as (
    select coalesce(p_day, (now() at time zone public.business_tz())::date) as day, public.business_tz() as tz
  ), pr as (
    select p.user_id, sum(p.calls) as calls, sum(p.leads) as leads, sum(p.appointments) as appts
      from d, public.production_report(d.day, d.day) p
     group by 1
  ), wd as (
    select w.user_id, w.worked, w.paid from d, public.work_days(d.day, d.day) w
  ), st as (
    select a.user_id, min(a.minute) as started
      from public.work_activity a, d
     where a.minute >= (d.day::timestamp at time zone d.tz) and a.minute < ((d.day + 1)::timestamp at time zone d.tz)
     group by 1
  ), people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where u.status = 'active'
       and (public.is_admin() or u.id = public.app_user_id())
       and (u.role = 'manager'
            or u.id in (select st.user_id from st) or u.id in (select pr.user_id from pr))
  )
  select p.id, p.first_name, p.last_name, p.role, st.started,
         coalesce(pr.calls, 0), coalesce(pr.leads, 0), coalesce(pr.appts, 0),
         coalesce(wd.worked, 0), coalesce(wd.paid, 0), g.leads_goal, g.appts_goal
    from people p
    cross join d
    left join pr on pr.user_id = p.id
    left join wd on wd.user_id = p.id
    left join st on st.user_id = p.id
    left join public.daily_goals g on g.user_id = p.id and g.day = d.day
   order by p.first_name, p.last_name, p.id;
$$;
revoke execute on function public.daily_production(date) from public, anon;
grant execute on function public.daily_production(date) to authenticated;

-- ==============================================================================================================
-- 20261022110000_temporary_passwords.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — temporary passwords (Sean, Oct 2026)
--
-- An administrator can create an account with a temporary password, or give
-- an existing one a new temporary password, instead of an emailed link.
-- Passwords themselves are never stored readable (Supabase keeps a one-way
-- hash): nobody can look one up. What is stored is that the password is
-- temporary, so the person is taken to set their own at their next sign-in.
--
--   users.must_change_password   set by an administrator with a temporary
--                                password; cleared when the person sets
--                                their own (clear_temporary_password()).
-- ---------------------------------------------------------------------------

alter table public.users add column if not exists must_change_password boolean not null default false;

-- The guard on what people may change in their own row: as before, and the
-- temporary-password flag too (only an administrator sets it; the person
-- clears it by setting a password, through clear_temporary_password()).
create or replace function public.tg_users_guard_protected_columns()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user <> 'authenticated' then
    return new;
  end if;
  if public.is_admin() then
    return new;
  end if;
  if (new.role, new.status, new.company_id, new.auth_id, new.email, new.user_type_id, new.must_change_password)
     is distinct from
     (old.role, old.status, old.company_id, old.auth_id, old.email, old.user_type_id, old.must_change_password) then
    raise exception 'Only an administrator can change a user''s role, status, client account or sign-in identity'
      using errcode = '42501';
  end if;
  return new;
end $$;

/** The signed-in person has set their own password: their temporary one is gone. */
create or replace function public.clear_temporary_password()
returns boolean
language plpgsql security definer set search_path = public as $$
declare v_rows int;
begin
  update public.users set must_change_password = false, updated_at = now()
   where auth_id = auth.uid() and must_change_password;
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end $$;
revoke execute on function public.clear_temporary_password() from public, anon;
grant execute on function public.clear_temporary_password() to authenticated;

-- ==============================================================================================================
-- 20261023100000_manager_dashboard_rows.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the account manager's dashboard, rows two and three
-- (Sean, Oct 2026)
--
--   production_days(from, to)   each person's production day by day over a
--                               range (a day, a week, a pay period, a month):
--                               when they started using Lighthouse, calls,
--                               leads, appointments, minutes worked, goals.
--                               Everyone's for an administrator; anyone
--                               else, their own.
--   team_production(day)        every active account manager's leads and
--                               appointments for the day, for the Daily Team
--                               Production list every manager sees. Counts
--                               only: no pay, hours or calls.
--   move_appointment()          the person who set an appointment (or an
--                               administrator) moves it to another day or
--                               time, from the dashboard's calendar.
--   move_reminder()             one's own call-back reminder, not yet gone
--                               off, moved to another day or time.
-- ---------------------------------------------------------------------------

/**
 * Production per person and day from `p_from` to `p_to` (the business's
 * days): account managers always, and anyone else who worked or set a goal
 * in the range. A person with nothing in the range has one row with a null
 * day, so they are still listed. Counts as daily_production() does.
 */
create or replace function public.production_days(p_from date, p_to date)
returns table (
  user_id bigint, first_name text, last_name text, role text, day date,
  started_at timestamptz, calls bigint, leads bigint, appointments bigint,
  worked_minutes int, paid_minutes int, leads_goal int, appts_goal int
)
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), pr as (
    select p.user_id, p.day, sum(p.calls) as calls, sum(p.leads) as leads, sum(p.appointments) as appts
      from public.production_report(p_from, p_to) p
     group by 1, 2
  ), wd as (
    select w.user_id, w.day, w.worked, w.paid from public.work_days(p_from, p_to) w
  ), st as (
    select a.user_id, (a.minute at time zone z.tz)::date as day, min(a.minute) as started
      from public.work_activity a, z
     where a.minute >= (p_from::timestamp at time zone z.tz) and a.minute < ((p_to + 1)::timestamp at time zone z.tz)
     group by 1, 2
  ), g as (
    select g.user_id, g.day, g.leads_goal, g.appts_goal
      from public.daily_goals g
     where g.day between p_from and p_to
  ), days as (
    select pr.user_id, pr.day from pr
    union select wd.user_id, wd.day from wd
    union select st.user_id, st.day from st
    union select g.user_id, g.day from g
  ), people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where u.status = 'active'
       and (public.is_admin() or u.id = public.app_user_id())
       and (u.role = 'manager' or u.id in (select days.user_id from days))
  )
  select p.id, p.first_name, p.last_name, p.role, x.day, st.started,
         coalesce(pr.calls, 0), coalesce(pr.leads, 0), coalesce(pr.appts, 0),
         coalesce(wd.worked, 0), coalesce(wd.paid, 0), g.leads_goal, g.appts_goal
    from people p
    left join days x on x.user_id = p.id
    left join pr on pr.user_id = p.id and pr.day = x.day
    left join wd on wd.user_id = p.id and wd.day = x.day
    left join st on st.user_id = p.id and st.day = x.day
    left join g  on g.user_id  = p.id and g.day  = x.day
   order by p.first_name, p.last_name, p.id, x.day;
$$;
revoke execute on function public.production_days(date, date) from public, anon;
grant execute on function public.production_days(date, date) to authenticated;

/**
 * Every active account manager's leads and appointments developed on the
 * day (the business's; today by default), as the production report counts
 * them, for staff: the Daily Team Production list. Counts only.
 */
create or replace function public.team_production(p_day date default null)
returns table (user_id bigint, first_name text, last_name text, leads bigint, appointments bigint)
language sql stable security definer set search_path = public as $$
  with d as (
    select coalesce(p_day, (now() at time zone public.business_tz())::date) as day, public.business_tz() as tz
  )
  select u.id, u.first_name, u.last_name,
         count(pe.id) filter (where pe.kind = 'lead'),
         count(pe.id) filter (where pe.kind = 'appointment')
    from d
    cross join public.users u
    left join public.pay_events pe
      on pe.user_id = u.id and pe.kind in ('lead', 'appointment') and not pe.is_chargeback
     and pe.created_at >= (d.day::timestamp at time zone d.tz)
     and pe.created_at <  ((d.day + 1)::timestamp at time zone d.tz)
   where public.is_staff() and public.mfa_satisfied()
     and u.role = 'manager' and u.status = 'active'
   group by u.id, u.first_name, u.last_name
   order by u.first_name, u.last_name, u.id;
$$;
revoke execute on function public.team_production(date) from public, anon;
grant execute on function public.team_production(date) to authenticated;

/** "9:30 am" -> "9:30 AM", or an error saying what a time looks like. */
create or replace function public.parse_clock_time(p_time text)
returns time
language plpgsql immutable set search_path = public as $$
begin
  if p_time is null or upper(btrim(p_time)) !~ '^(1[0-2]|0?[1-9]):[0-5]\d\s?(AM|PM)$' then
    raise exception 'Choose a time like 2:00 PM' using errcode = '22023';
  end if;
  return to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time;
end $$;

/**
 * Move an appointment to another day and time ("2:00 PM", the business's
 * clock): the person who set it, or an administrator. Not one marked
 * invalid or already past, and not to a day already gone. A Scheduled one
 * becomes Rescheduled, as when it is moved from a call.
 */
create or replace function public.move_appointment(p_id bigint, p_date date, p_time text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me    bigint := public.app_user_id();
  v_today date := (now() at time zone public.business_tz())::date;
  v_time  text;
  a       public.appointments;
begin
  select * into a from public.appointments where id = p_id for update;
  if a.id is null or v_me is null or not (a.user_id = v_me or public.is_admin()) then
    raise exception 'Only the person who set this appointment can move it' using errcode = '42501';
  end if;
  if a.invalid_at is not null then
    raise exception 'This appointment was marked invalid' using errcode = '22023';
  end if;
  if a.appt_date < v_today then
    raise exception 'This appointment has already passed' using errcode = '22023';
  end if;
  if p_date is null or p_date < v_today then
    raise exception 'Choose a day from today on' using errcode = '22023';
  end if;
  v_time := to_char(public.parse_clock_time(coalesce(p_time, a.appt_time)), 'FMHH12:MI AM');

  update public.appointments set
    appt_date = p_date,
    appt_time = v_time,
    status_id = case when status_id = (select id from public.appointment_statuses where name = 'Scheduled')
                      and (appt_date, coalesce(appt_time, '')) is distinct from (p_date, v_time)
                     then (select id from public.appointment_statuses where name = 'Rescheduled')
                     else status_id end,
    status_update_date = now()
  where id = a.id
  returning * into a;
  return jsonb_build_object('id', a.id, 'appt_date', a.appt_date, 'appt_time', a.appt_time);
end $$;
revoke execute on function public.move_appointment(bigint, date, text) from public, anon;
grant execute on function public.move_appointment(bigint, date, text) to authenticated;

/**
 * Move one of my call-back reminders that has not gone off to another day
 * and time ("2:00 PM", the business's clock), still ahead.
 */
create or replace function public.move_reminder(p_id bigint, p_date date, p_time text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_at timestamptz;
  r    public.reminders;
begin
  if p_date is null then
    raise exception 'Choose the day to be reminded' using errcode = '22023';
  end if;
  v_at := (p_date + public.parse_clock_time(p_time)) at time zone public.business_tz();
  if v_at < now() - interval '1 minute' then
    raise exception 'That time has already passed' using errcode = '22023';
  end if;
  select * into r from public.reminders where id = p_id and user_id = public.app_user_id() for update;
  if r.id is null then
    raise exception 'This is not one of your reminders' using errcode = '42501';
  end if;
  if r.sent_at is not null then
    raise exception 'This reminder has already gone off' using errcode = '22023';
  end if;
  update public.reminders set remind_at = v_at where id = r.id returning * into r;
  return jsonb_build_object('id', r.id, 'remind_at', r.remind_at);
end $$;
revoke execute on function public.move_reminder(bigint, date, text) from public, anon;
grant execute on function public.move_reminder(bigint, date, text) to authenticated;

-- ==============================================================================================================
-- 20261025100000_project_type_restage.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a project's type and its names' stage stay together
-- (Sean, Oct 2026)
--
-- A name's stage (DB dev or appointment) and the call results its sheet
-- offers follow its project's type. The stage was set when a name was
-- loaded or moved to another project, but not when the project's own type
-- was changed: names loaded into a Database Development project that was
-- later set to Appointment Setting stayed at the DB dev stage, with a DB dev
-- result (Viable-CallBack), while their sheet offered the appointment
-- results.
--
--   tg_projects_restage    changing a project's type moves its names to that
--                          type's stage; a result from the other stage's list
--                          starts again at the stage's first (tg_leads_stage)
-- ---------------------------------------------------------------------------

create or replace function public.tg_projects_restage()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_stage text := case public.project_type_code(new.id) when 'APPT' then 'appt' else 'dbdev' end;
begin
  if new.project_type_id is distinct from old.project_type_id and new.project_type_id is not null then
    -- Naming result_id runs tg_leads_stage, which starts a result from the other stage's list afresh.
    update public.leads set stage = v_stage, result_id = result_id
     where project_id = new.id and stage is distinct from v_stage;
  end if;
  return null;
end $$;

drop trigger if exists projects_restage on public.projects;
create trigger projects_restage
  after update of project_type_id on public.projects
  for each row execute function public.tg_projects_restage();

-- ==============================================================================================================
-- 20261026100000_call_list_filters.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — filtering a call list (Sean, Oct 2026)
--
-- An account manager working a project narrows their call list to the names
-- most worth calling now: those renewing in a window of the year (Nov 1 –
-- Jan 31, any year, or one month at a time), in given cities, ZIP codes or
-- counties, in given industries (SIC), with given carriers, developed in a
-- given year or by given managers, or with given call results — each one
-- included or excluded. Only names still to call come up, as before.
--
-- The filter is the manager's own, kept per project, so everything that
-- walks their list follows it: the list itself, Start calling, Skip, and the
-- next name after a result is saved.
--
--   call_list_filters        the filter each person keeps for each project
--   call_list_criterion()    one criterion against one value (include/exclude)
--   call_list_renews_in()    a renewal date against a window of the year
--   lead_carrier_keys()      every carrier a name has (agency, each line)
--   call_list_options()      what the filter offers: the values found among
--                            the names on the list, with how many of each
--   call_list()              as before, through the caller's filter for the
--                            project (p_filtered => false to ignore it)
--
-- Criteria (jsonb), each optional:
--   renewal    { from: "MM-DD", to: "MM-DD", exclude }   (to before from wraps the year)
--   city, zip, county, sic, carrier, year, developer, result
--              { values: [text], exclude }
-- ---------------------------------------------------------------------------

create table if not exists public.call_list_filters (
  user_id     bigint not null references public.users(id) on delete cascade,
  project_id  bigint not null references public.projects(id) on delete cascade,
  criteria    jsonb not null default '{}'::jsonb check (jsonb_typeof(criteria) = 'object' and length(criteria::text) <= 20000),
  updated_at  timestamptz not null default now(),
  primary key (user_id, project_id)
);
alter table public.call_list_filters enable row level security;
drop policy if exists call_list_filters_own on public.call_list_filters;
create policy call_list_filters_own on public.call_list_filters
  for all to authenticated
  using (user_id = (select public.app_user_id()) and (select public.is_staff()))
  with check (user_id = (select public.app_user_id()) and (select public.is_staff()));
drop policy if exists mfa_required on public.call_list_filters;
create policy mfa_required on public.call_list_filters as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.call_list_filters;
create policy active_account_required on public.call_list_filters as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.call_list_filters from anon;
grant select, insert, update, delete on public.call_list_filters to authenticated;
grant all on public.call_list_filters to service_role;

/**
 * One criterion ({ values, exclude }) against a name's values: with no
 * values chosen, anything; included, one of its values is chosen;
 * excluded, none is (a name with no value at all stays).
 */
create or replace function public.call_list_criterion(c jsonb, v text[])
returns boolean
language sql immutable parallel safe set search_path = public as $$
  select c is null or jsonb_typeof(c -> 'values') is distinct from 'array' or jsonb_array_length(c -> 'values') = 0
      or (coalesce(v && array(select jsonb_array_elements_text(c -> 'values')), false)
          <> coalesce((c ->> 'exclude')::boolean, false));
$$;

/**
 * A renewal date against a window of the year ({ from: "MM-DD", to:
 * "MM-DD", exclude }), whatever the year: Nov 1 – Jan 31 runs over the new
 * year. A name with no renewal date is not in any window.
 */
create or replace function public.call_list_renews_in(c jsonb, d date)
returns boolean
language sql immutable parallel safe set search_path = public as $$
  select c is null or coalesce(c ->> 'from', '') !~ '^\d\d-\d\d$' or coalesce(c ->> 'to', '') !~ '^\d\d-\d\d$'
      or (coalesce(
            case when c ->> 'from' <= c ->> 'to'
                 then to_char(d, 'MM-DD') between c ->> 'from' and c ->> 'to'
                 else to_char(d, 'MM-DD') >= c ->> 'from' or to_char(d, 'MM-DD') <= c ->> 'to' end,
            false)
          <> coalesce((c ->> 'exclude')::boolean, false));
$$;

/** Every carrier a name has, as carrier_key()s: its agency's, and each policy line's. */
create or replace function public.lead_carrier_keys(p_lead bigint)
returns text[]
language sql stable set search_path = public as $$
  select coalesce(array_agg(distinct k) filter (where k is not null), '{}')
    from (
      select public.carrier_key(a.name) as k
        from public.leads l join public.agencies a on a.id = l.agency_id where l.id = p_lead
      union all
      select public.carrier_key(x)
        from public.insurance_details i,
             unnest(array[i.agency_name, i.pkg_carrier, i.wc_carrier, i.auto_carrier, i.health_carrier, i.dental_provider,
                          i.vision_provider, i.prof_liab_carrier, i.do_carrier, i.eo_carrier, i.homeowner_carrier,
                          i.personal_auto_carrier, i.personal_lines_carrier]) as x
       where i.lead_id = p_lead
    ) s;
$$;

/** A name's values for each criterion, as call_list_criterion() compares them. */
create or replace function public.call_list_matches(l public.leads, p_renewal date, p_carriers text[], c jsonb)
returns boolean
language sql stable set search_path = public as $$
  select c is null or c = '{}'::jsonb or (
        public.call_list_renews_in(c -> 'renewal', p_renewal)
    and public.call_list_criterion(c -> 'city', array[lower(btrim(l.city))])
    and public.call_list_criterion(c -> 'zip', array[left(btrim(l.zip), 5)])
    and public.call_list_criterion(c -> 'county', array[lower(btrim(l.county))])
    and public.call_list_criterion(c -> 'sic', array[btrim(l.sic_code)])
    and public.call_list_criterion(c -> 'carrier', p_carriers)
    and public.call_list_criterion(c -> 'year', array[extract(year from l.promoted_at at time zone public.business_tz())::int::text])
    and public.call_list_criterion(c -> 'developer', array[l.dbdv_user_id::text])
    and public.call_list_criterion(c -> 'result', array[l.result_id::text]));
$$;

drop function if exists public.call_list(bigint, bigint, int, int, text);

/**
 * A rep's call list, as before (names still to call, least-called first,
 * searched word by word), through the caller's filter for the project
 * unless `p_filtered` is false. `total` counts the names that pass it.
 */
create or replace function public.call_list(p_project_id bigint, p_rep bigint default null,
                                            p_limit int default 50, p_offset int default 0,
                                            p_search text default null, p_filtered boolean default true)
returns table (
  id bigint, company_name text, contact_name text, phone text, city text, state text,
  result text, call_weight int, sort_last boolean, date_last_worked timestamptz,
  renewal_date date, total bigint
)
language plpgsql stable security invoker set search_path = public, extensions as $$
declare
  v_rep   bigint := coalesce(p_rep, public.app_user_id());
  v_words text[] := public.search_words(p_search);
  v_pats  text[] := public.search_patterns(v_words);
  v_first text   := public.search_lead_pattern(v_words);
  v_c     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  if coalesce(p_filtered, true) then
    select f.criteria into v_c from public.call_list_filters f
     where f.user_id = public.app_user_id() and f.project_id = p_project_id;
  end if;
  return query
    select l.id, l.company_name, l.contact_name, l.phone, l.city, l.state,
           r.name, l.call_weight, r.sort_last, l.date_last_worked,
           x.renewal, count(*) over ()
      from public.leads l
      join public.call_results r on r.id = l.result_id
      cross join lateral (select public.lead_renewal_date(l.id) as renewal) x
     where l.project_id = p_project_id
       and l.assigned_user_id = v_rep
       and r.viable and r.callable
       and (v_first is null or (l.search_text like v_first and l.search_text like all (v_pats)))
       and (v_c is null or v_c = '{}'::jsonb
            or public.call_list_matches(l, x.renewal,
                 case when v_c ? 'carrier' then public.lead_carrier_keys(l.id) else '{}'::text[] end, v_c))
     order by r.sort_last, l.call_weight, l.date_last_worked nulls first, l.id
     limit greatest(least(coalesce(p_limit, 50), 500), 1)
    offset greatest(coalesce(p_offset, 0), 0);
end $$;
revoke execute on function public.call_list(bigint, bigint, int, int, text, boolean) from public, anon;
grant execute on function public.call_list(bigint, bigint, int, int, text, boolean) to authenticated;

/**
 * What a call list's filter can offer: among the rep's names still to call
 * on the project, each city, ZIP, county, industry, carrier, year
 * developed, developer and call result, with how many names have it.
 * Values are as call_list_matches() compares them; labels as people read them.
 */
create or replace function public.call_list_options(p_project_id bigint, p_rep bigint default null)
returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  v_rep bigint := coalesce(p_rep, public.app_user_id());
  v     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  with base as (
    select l.* from public.leads l join public.call_results r on r.id = l.result_id
     where l.project_id = p_project_id and l.assigned_user_id = v_rep and r.viable and r.callable
  ), opts as (
    -- Labels as written, a capitalised spelling first ("Phoenix" over "phoenix").
    select 'city' as k, lower(btrim(city)) as value,
           coalesce(min(btrim(city)) filter (where btrim(city) ~ '^[A-Z]'), min(btrim(city))) as label, count(*) as n
      from base where nullif(btrim(city), '') is not null group by 2
    union all
    select 'zip', left(btrim(zip), 5), left(btrim(zip), 5), count(*) from base where nullif(btrim(zip), '') is not null group by 2
    union all
    select 'county', lower(btrim(county)),
           coalesce(min(btrim(county)) filter (where btrim(county) ~ '^[A-Z]'), min(btrim(county))), count(*)
      from base where nullif(btrim(county), '') is not null group by 2
    union all
    select 'sic', btrim(b.sic_code), btrim(b.sic_code) || coalesce(' – ' || min(s.description), ''), count(*)
      from base b left join public.sic_codes s on s.code = btrim(b.sic_code)
     where nullif(btrim(b.sic_code), '') is not null group by 2
    union all
    select 'carrier', k, min(initcap(k)), count(distinct b.id) from base b, unnest(public.lead_carrier_keys(b.id)) k group by 2
    union all
    select 'year', extract(year from promoted_at at time zone public.business_tz())::int::text,
           extract(year from promoted_at at time zone public.business_tz())::int::text, count(*)
      from base where promoted_at is not null group by 2
    union all
    select 'developer', b.dbdv_user_id::text,
           min(coalesce(nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email)), count(*)
      from base b join public.users u on u.id = b.dbdv_user_id group by 2
    union all
    select 'result', b.result_id::text, min(r.name), count(*)
      from base b join public.call_results r on r.id = b.result_id group by 2
  )
  select coalesce(jsonb_object_agg(k, items), '{}'::jsonb) into v
    from (select k, jsonb_agg(jsonb_build_object('value', value, 'label', label, 'count', n) order by label) as items
            from opts group by k) g;
  return v;
end $$;
revoke execute on function public.call_list_options(bigint, bigint) from public, anon;
grant execute on function public.call_list_options(bigint, bigint) to authenticated;

-- ==============================================================================================================
-- 20261027100000_call_list_filter_daily.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a call list's filter lasts the day (Sean, Oct 2026)
--
-- A manager's filter for a project's call list stays through the day (a
-- lunch break, a restart) and is set aside the next morning, when the list
-- starts again in full; Clear all ends it sooner.
--
--   call_list()    as before, through the caller's filter only if it was set
--                  (or changed) today, on the business's clock
--   call_list_filters_touch   every save stamps updated_at
-- ---------------------------------------------------------------------------

/**
 * A rep's call list, as before (names still to call, least-called first,
 * searched word by word), through the caller's filter for the project,
 * if they set it today (the business's day), unless `p_filtered` is false.
 * `total` counts the names that pass it.
 */
create or replace function public.call_list(p_project_id bigint, p_rep bigint default null,
                                            p_limit int default 50, p_offset int default 0,
                                            p_search text default null, p_filtered boolean default true)
returns table (
  id bigint, company_name text, contact_name text, phone text, city text, state text,
  result text, call_weight int, sort_last boolean, date_last_worked timestamptz,
  renewal_date date, total bigint
)
language plpgsql stable security invoker set search_path = public, extensions as $$
declare
  v_rep   bigint := coalesce(p_rep, public.app_user_id());
  v_words text[] := public.search_words(p_search);
  v_pats  text[] := public.search_patterns(v_words);
  v_first text   := public.search_lead_pattern(v_words);
  v_c     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  if coalesce(p_filtered, true) then
    -- Today's only: each morning the list starts again in full.
    select f.criteria into v_c from public.call_list_filters f
     where f.user_id = public.app_user_id() and f.project_id = p_project_id
       and (f.updated_at at time zone public.business_tz())::date = (now() at time zone public.business_tz())::date;
  end if;
  return query
    select l.id, l.company_name, l.contact_name, l.phone, l.city, l.state,
           r.name, l.call_weight, r.sort_last, l.date_last_worked,
           x.renewal, count(*) over ()
      from public.leads l
      join public.call_results r on r.id = l.result_id
      cross join lateral (select public.lead_renewal_date(l.id) as renewal) x
     where l.project_id = p_project_id
       and l.assigned_user_id = v_rep
       and r.viable and r.callable
       and (v_first is null or (l.search_text like v_first and l.search_text like all (v_pats)))
       and (v_c is null or v_c = '{}'::jsonb
            or public.call_list_matches(l, x.renewal,
                 case when v_c ? 'carrier' then public.lead_carrier_keys(l.id) else '{}'::text[] end, v_c))
     order by r.sort_last, l.call_weight, l.date_last_worked nulls first, l.id
     limit greatest(least(coalesce(p_limit, 50), 500), 1)
    offset greatest(coalesce(p_offset, 0), 0);
end $$;
revoke execute on function public.call_list(bigint, bigint, int, int, text, boolean) from public, anon;
grant execute on function public.call_list(bigint, bigint, int, int, text, boolean) to authenticated;

-- Saved is saved today: every change stamps the time, whoever writes it.
create or replace function public.tg_call_list_filters_touch()
returns trigger
language plpgsql set search_path = public as $$
begin
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists call_list_filters_touch on public.call_list_filters;
create trigger call_list_filters_touch
  before insert or update on public.call_list_filters
  for each row execute function public.tg_call_list_filters_touch();

-- ==============================================================================================================
-- 20261028100000_renewal_lines_and_coverage.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — renewals on any policy line; coverage as the 9/24 sheet
-- has it (Sean, Oct 2026)
--
-- A call list's renewal window now looks at every X-date a name has — the
-- Ultimate X-Date and each policy line's (liability/package, workers comp,
-- auto, health, personal lines, dental, vision, professional liability, D&O,
-- E&O) — or at one line chosen. Lead managers filter their DB dev (cold)
-- lists the same way, and by the list a name came from.
--
--   insurance_details.agency_years   years with the agency named
--   lead_xdates(lead, line)          a name's X-dates: all, or one line's
--   call_list_renews_in(c, dates)    any of them in the window of the year
--   call_list_matches()              as before, with every X-date, and the
--                                    list source (criterion "source")
--   lead_xdate_in(lead, c)           which X-date put a name in the window
--   call_list(), call_list_options() as before, with the above; call_list()
--                                    also says which date matched
--
-- Criterion renewal: { from: "MM-DD", to: "MM-DD", line?, exclude }, where
-- line is "ultimate" or a policy line's key (pkg, wc, auto, health,
-- personal, dental, vision, prof, do, eo); none means any of them.
-- ---------------------------------------------------------------------------

alter table public.insurance_details add column if not exists agency_years int
  check (agency_years between 0 and 150);

/** A name's X-dates: the Ultimate X-Date and every policy line's, or only `p_line`'s. */
create or replace function public.lead_xdates(p_lead bigint, p_line text default null)
returns date[]
language sql stable set search_path = public as $$
  select coalesce(array_agg(v.d) filter (where v.d is not null), '{}')
    from public.insurance_details i,
         lateral (values ('ultimate', i.ultimate_xdate), ('pkg', i.pkg_xdate), ('wc', i.wc_xdate), ('auto', i.auto_xdate),
                         ('health', i.health_xdate), ('personal', i.personal_lines_xdate), ('dental', i.dental_xdate),
                         ('vision', i.vision_xdate), ('prof', i.prof_liab_xdate), ('do', i.do_xdate), ('eo', i.eo_xdate)) as v(line, d)
   where i.lead_id = p_lead and (nullif(p_line, '') is null or v.line = p_line);
$$;

/**
 * Any of a name's X-dates against a window of the year ({ from: "MM-DD",
 * to: "MM-DD", exclude }), whatever the year (Nov 1 – Jan 31 runs over the
 * new year). Excluded, none of them is in it; a name with no X-date is in
 * no window.
 */
create or replace function public.call_list_renews_in(c jsonb, ds date[])
returns boolean
language sql immutable parallel safe set search_path = public as $$
  select c is null or coalesce(c ->> 'from', '') !~ '^\d\d-\d\d$' or coalesce(c ->> 'to', '') !~ '^\d\d-\d\d$'
      or (coalesce((select bool_or(
            case when c ->> 'from' <= c ->> 'to'
                 then to_char(d, 'MM-DD') between c ->> 'from' and c ->> 'to'
                 else to_char(d, 'MM-DD') >= c ->> 'from' or to_char(d, 'MM-DD') <= c ->> 'to' end)
             from unnest(ds) as d), false)
          <> coalesce((c ->> 'exclude')::boolean, false));
$$;

/**
 * The X-date that puts a name in a renewal window ({ from, to, line? }):
 * { line, date } of the first in the sheet's order (the Ultimate, then each
 * line), or null.
 */
create or replace function public.lead_xdate_in(p_lead bigint, c jsonb)
returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object('line', v.line, 'date', v.d)
    from public.insurance_details i,
         lateral (values (1, 'ultimate', i.ultimate_xdate), (2, 'pkg', i.pkg_xdate), (3, 'wc', i.wc_xdate), (4, 'auto', i.auto_xdate),
                         (5, 'health', i.health_xdate), (6, 'personal', i.personal_lines_xdate), (7, 'dental', i.dental_xdate),
                         (8, 'vision', i.vision_xdate), (9, 'prof', i.prof_liab_xdate), (10, 'do', i.do_xdate), (11, 'eo', i.eo_xdate)) as v(n, line, d)
   where i.lead_id = p_lead and v.d is not null
     and (nullif(c ->> 'line', '') is null or v.line = c ->> 'line')
     and public.call_list_renews_in(c - 'exclude', array[v.d])
   order by v.n
   limit 1;
$$;

drop function if exists public.call_list_matches(public.leads, date, text[], jsonb);
drop function if exists public.call_list_renews_in(jsonb, date);

/** A name's values for each criterion, as call_list_criterion() compares them. */
create or replace function public.call_list_matches(l public.leads, p_xdates date[], p_carriers text[], c jsonb)
returns boolean
language sql stable set search_path = public as $$
  select c is null or c = '{}'::jsonb or (
        public.call_list_renews_in(c -> 'renewal', p_xdates)
    and public.call_list_criterion(c -> 'city', array[lower(btrim(l.city))])
    and public.call_list_criterion(c -> 'zip', array[left(btrim(l.zip), 5)])
    and public.call_list_criterion(c -> 'county', array[lower(btrim(l.county))])
    and public.call_list_criterion(c -> 'sic', array[btrim(l.sic_code)])
    and public.call_list_criterion(c -> 'carrier', p_carriers)
    and public.call_list_criterion(c -> 'year', array[extract(year from l.promoted_at at time zone public.business_tz())::int::text])
    and public.call_list_criterion(c -> 'developer', array[l.dbdv_user_id::text])
    and public.call_list_criterion(c -> 'result', array[l.result_id::text])
    and public.call_list_criterion(c -> 'source', array[lower(btrim(l.list_source))]));
$$;

drop function if exists public.call_list(bigint, bigint, int, int, text, boolean);

/**
 * A rep's call list, as before (names still to call, least-called first,
 * searched word by word), through the caller's filter for the project,
 * if they set it today (the business's day), unless `p_filtered` is false.
 * `total` counts the names that pass it.
 */
create or replace function public.call_list(p_project_id bigint, p_rep bigint default null,
                                            p_limit int default 50, p_offset int default 0,
                                            p_search text default null, p_filtered boolean default true)
returns table (
  id bigint, company_name text, contact_name text, phone text, city text, state text,
  result text, call_weight int, sort_last boolean, date_last_worked timestamptz,
  renewal_date date, total bigint, renewal_match jsonb
)
language plpgsql stable security invoker set search_path = public, extensions as $$
declare
  v_rep   bigint := coalesce(p_rep, public.app_user_id());
  v_words text[] := public.search_words(p_search);
  v_pats  text[] := public.search_patterns(v_words);
  v_first text   := public.search_lead_pattern(v_words);
  v_c     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  if coalesce(p_filtered, true) then
    -- Today's only: each morning the list starts again in full.
    select f.criteria into v_c from public.call_list_filters f
     where f.user_id = public.app_user_id() and f.project_id = p_project_id
       and (f.updated_at at time zone public.business_tz())::date = (now() at time zone public.business_tz())::date;
  end if;
  return query
    select l.id, l.company_name, l.contact_name, l.phone, l.city, l.state,
           r.name, l.call_weight, r.sort_last, l.date_last_worked,
           x.renewal, count(*) over (),
           -- With a renewal window (not excluded): the X-date that put the name in it.
           case when v_c ? 'renewal' and not coalesce((v_c -> 'renewal' ->> 'exclude')::boolean, false)
                then public.lead_xdate_in(l.id, v_c -> 'renewal') end
      from public.leads l
      join public.call_results r on r.id = l.result_id
      cross join lateral (select public.lead_renewal_date(l.id) as renewal) x
     where l.project_id = p_project_id
       and l.assigned_user_id = v_rep
       and r.viable and r.callable
       and (v_first is null or (l.search_text like v_first and l.search_text like all (v_pats)))
       and (v_c is null or v_c = '{}'::jsonb
            or public.call_list_matches(l,
                 case when v_c ? 'renewal' then public.lead_xdates(l.id, v_c -> 'renewal' ->> 'line') else '{}'::date[] end,
                 case when v_c ? 'carrier' then public.lead_carrier_keys(l.id) else '{}'::text[] end, v_c))
     order by r.sort_last, l.call_weight, l.date_last_worked nulls first, l.id
     limit greatest(least(coalesce(p_limit, 50), 500), 1)
    offset greatest(coalesce(p_offset, 0), 0);
end $$;
revoke execute on function public.call_list(bigint, bigint, int, int, text, boolean) from public, anon;
grant execute on function public.call_list(bigint, bigint, int, int, text, boolean) to authenticated;

/**
 * What a call list's filter can offer: among the rep's names still to call
 * on the project, each city, ZIP, county, industry, carrier, year
 * developed, developer, call result and list source, with how many names
 * have it.
 * Values are as call_list_matches() compares them; labels as people read them.
 */
create or replace function public.call_list_options(p_project_id bigint, p_rep bigint default null)
returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  v_rep bigint := coalesce(p_rep, public.app_user_id());
  v     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  with base as (
    select l.* from public.leads l join public.call_results r on r.id = l.result_id
     where l.project_id = p_project_id and l.assigned_user_id = v_rep and r.viable and r.callable
  ), opts as (
    -- Labels as written, a capitalised spelling first ("Phoenix" over "phoenix").
    select 'city' as k, lower(btrim(city)) as value,
           coalesce(min(btrim(city)) filter (where btrim(city) ~ '^[A-Z]'), min(btrim(city))) as label, count(*) as n
      from base where nullif(btrim(city), '') is not null group by 2
    union all
    select 'zip', left(btrim(zip), 5), left(btrim(zip), 5), count(*) from base where nullif(btrim(zip), '') is not null group by 2
    union all
    select 'county', lower(btrim(county)),
           coalesce(min(btrim(county)) filter (where btrim(county) ~ '^[A-Z]'), min(btrim(county))), count(*)
      from base where nullif(btrim(county), '') is not null group by 2
    union all
    select 'sic', btrim(b.sic_code), btrim(b.sic_code) || coalesce(' – ' || min(s.description), ''), count(*)
      from base b left join public.sic_codes s on s.code = btrim(b.sic_code)
     where nullif(btrim(b.sic_code), '') is not null group by 2
    union all
    select 'carrier', k, min(initcap(k)), count(distinct b.id) from base b, unnest(public.lead_carrier_keys(b.id)) k group by 2
    union all
    select 'year', extract(year from promoted_at at time zone public.business_tz())::int::text,
           extract(year from promoted_at at time zone public.business_tz())::int::text, count(*)
      from base where promoted_at is not null group by 2
    union all
    select 'developer', b.dbdv_user_id::text,
           min(coalesce(nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email)), count(*)
      from base b join public.users u on u.id = b.dbdv_user_id group by 2
    union all
    select 'result', b.result_id::text, min(r.name), count(*)
      from base b join public.call_results r on r.id = b.result_id group by 2
    union all
    select 'source', lower(btrim(b.list_source)), min(btrim(b.list_source)), count(*)
      from base b where nullif(btrim(b.list_source), '') is not null group by 2
  )
  select coalesce(jsonb_object_agg(k, items), '{}'::jsonb) into v
    from (select k, jsonb_agg(jsonb_build_object('value', value, 'label', label, 'count', n) order by label) as items
            from opts group by k) g;
  return v;
end $$;
revoke execute on function public.call_list_options(bigint, bigint) from public, anon;
grant execute on function public.call_list_options(bigint, bigint) to authenticated;

-- ==============================================================================================================
-- 20261029100000_production_chart.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the administrator's production chart (Sean, Oct 2026)
--
-- In place of Lead Volume (every lead loaded, a client's own lists too):
-- the leads and appointments the team developed, over a day (by the hour,
-- 5 AM – 6 PM) or a range, with the hours worked behind them, so the chart
-- can say how many of each were developed per hour, and against the monthly
-- goals administrators set. Company-wide, or one manager's, or one project's.
--
-- Hours are split by the kind of project they went to: a person's minutes
-- on a day are shared out over the projects they called that day, by their
-- calls (with no calls, over the projects they are assigned to), so lead
-- managers' (DB dev) and appointment managers' hours count apart, as
-- leads per hour and appointments per hour need. An appointment set on a
-- DB dev project still counts as an appointment.
--
--   production_goals     a month's goals: leads, appointments, and the rates
--                        per hour aimed for
--   production_chart()   per day (and, for one day, per hour): leads and
--                        appointments developed (pay events, as the
--                        production report counts them), minutes worked on
--                        lead projects and on appointment projects
-- ---------------------------------------------------------------------------

create table if not exists public.production_goals (
  month           date primary key check (extract(day from month) = 1),
  leads_goal      int check (leads_goal between 0 and 1000000),
  appts_goal      int check (appts_goal between 0 and 1000000),
  leads_per_hour  numeric(5, 2) check (leads_per_hour between 0 and 100),
  appts_per_hour  numeric(5, 2) check (appts_per_hour between 0 and 100),
  updated_by      bigint references public.users(id) on delete set null,
  updated_at      timestamptz not null default now()
);
alter table public.production_goals enable row level security;
drop policy if exists production_goals_admin on public.production_goals;
create policy production_goals_admin on public.production_goals
  for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists mfa_required on public.production_goals;
create policy mfa_required on public.production_goals as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
revoke all on public.production_goals from anon;
grant select, insert, update, delete on public.production_goals to authenticated;
grant all on public.production_goals to service_role;

/**
 * The team's production from `p_from` to `p_to` (the business's days), for
 * an administrator: everyone's, or one person's (`p_user`), or one
 * project's (`p_project`). Returns
 *   { days:  [{ day, leads, appts, lead_minutes, appt_minutes }],
 *     hours: [{ hour, leads, appts }]   (one day only) }
 */
create or replace function public.production_chart(p_from date, p_to date, p_user bigint default null, p_project bigint default null)
returns jsonb
language plpgsql stable security invoker set search_path = public as $$
declare
  v_tz  text := public.business_tz();
  v_lo  timestamptz;
  v_hi  timestamptz;
  v     jsonb;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator sees the team''s production' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then
    raise exception 'Choose up to two years' using errcode = '22023';
  end if;
  v_lo := p_from::timestamp at time zone v_tz;
  v_hi := (p_to + 1)::timestamp at time zone v_tz;

  with ev as (
    select (pe.created_at at time zone v_tz)::date as d, extract(hour from pe.created_at at time zone v_tz)::int as h, pe.kind
      from public.pay_events pe
     where pe.kind in ('lead', 'appointment') and not pe.is_chargeback
       and pe.created_at >= v_lo and pe.created_at < v_hi
       and (p_user is null or pe.user_id = p_user)
       and (p_project is null or pe.project_id = p_project)
  ), wm as (
    select w.user_id, w.day, sum(w.minutes)::numeric as m
      from public.work_minutes(p_from, p_to, p_user) w
     group by 1, 2
  ), calls as (
    select c.user_id, (c.call_date at time zone v_tz)::date as d, c.project_id, count(*)::numeric as n
      from public.call_records c
     where c.call_date >= v_lo and c.call_date < v_hi and c.project_id is not null
       and (p_user is null or c.user_id = p_user)
     group by 1, 2, 3
  ), kinds as (
    select p.id, t.code from public.projects p join public.project_types t on t.id = p.project_type_id
  ), share as (
    -- Each person-day's minutes, over the projects called that day by their calls…
    select wm.day, c.project_id, wm.m * c.n / sum(c.n) over (partition by wm.user_id, wm.day) as mins
      from wm join calls c on c.user_id = wm.user_id and c.d = wm.day
    union all
    -- …or, with no calls that day, over the projects they are assigned to.
    select wm.day, pa.project_id, wm.m / count(*) over (partition by wm.user_id, wm.day)
      from wm join public.project_assignments pa on pa.ae_user_id = wm.user_id
     where not exists (select 1 from calls c where c.user_id = wm.user_id and c.d = wm.day)
  ), worked as (
    select s.day,
           sum(s.mins) filter (where k.code = 'DBDV') as lead_minutes,
           sum(s.mins) filter (where k.code = 'APPT') as appt_minutes
      from share s join kinds k on k.id = s.project_id
     where p_project is null or s.project_id = p_project
     group by 1
  ), days as (
    select d from ev union select day from worked
  )
  select jsonb_build_object(
    'days', coalesce((
      select jsonb_agg(jsonb_build_object(
               'day', x.d,
               'leads', (select count(*) from ev where ev.d = x.d and ev.kind = 'lead'),
               'appts', (select count(*) from ev where ev.d = x.d and ev.kind = 'appointment'),
               'lead_minutes', round(coalesce(w.lead_minutes, 0)),
               'appt_minutes', round(coalesce(w.appt_minutes, 0))) order by x.d)
        from days x left join worked w on w.day = x.d), '[]'::jsonb),
    'hours', case when p_from = p_to then coalesce((
      select jsonb_agg(jsonb_build_object('hour', h, 'leads', l, 'appts', a) order by h)
        from (select h, count(*) filter (where kind = 'lead') as l, count(*) filter (where kind = 'appointment') as a
                from ev group by h) q), '[]'::jsonb) end)
  into v;
  return v;
end $$;
revoke execute on function public.production_chart(date, date, bigint, bigint) from public, anon;
grant execute on function public.production_chart(date, date, bigint, bigint) to authenticated;

-- ==============================================================================================================
-- 20261030100000_appt_disco_result.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — Lead-Disco# on appointment projects (Sean, Oct 2026)
--
-- A disconnected number found while calling an appointment project's names:
-- "Removed from Appt project call lists", as DB dev's Disco# does there.
-- Old-system lists that say XD-Disco# (or disconnected) import as it.
-- ---------------------------------------------------------------------------

insert into public.call_results
  (project_type, name, sort_order, viable, callable, sort_last, effect, pay_kind, applies_to, status_code, action, aliases)
values
  ('APPT', 'Lead-Disco#', 115, false, true, false, 'none', null, 'name', 'disconnected',
   'Removed from Appt project call lists',
   array['xd-disco#', 'xd-disco', 'xd-disconnected', 'lead-disco#', 'lead-disco', 'disco#', 'disco', 'disconnected', 'disconnected #'])
on conflict (project_type, name) do update set
  sort_order = excluded.sort_order, viable = excluded.viable, callable = excluded.callable,
  sort_last = excluded.sort_last, effect = excluded.effect, pay_kind = excluded.pay_kind,
  applies_to = excluded.applies_to, status_code = excluded.status_code,
  action = excluded.action, aliases = excluded.aliases;

-- ==============================================================================================================
-- 20261031100000_appt_client_results.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — appointment call results: Lead-CurrentClient and
-- Lead-ClientList (Sean, Oct 2026)
--
--   Lead-Client        is now Lead-CurrentClient: the same result (still
--                      "Removed from Appt project call lists"), renamed, so
--                      names that already have it and their call history
--                      read the new name. Lists that say Lead-Client or
--                      XD-Client still import as it.
--   Lead-ClientList    new: "Stays on active Appt project call lists
--                      (tracked by # of calls made to each name/weighted).
--                      Viewable results stays as titled".
-- ---------------------------------------------------------------------------

-- The rename, once: where a result's name is written out, it follows.
update public.leads l set call_result_appt = 'Lead-CurrentClient'
  from public.call_results r
 where r.project_type = 'APPT' and r.name = 'Lead-Client' and l.result_id = r.id and l.call_result_appt = 'Lead-Client';
update public.call_records c set call_result = 'Lead-CurrentClient'
  from public.call_results r
 where r.project_type = 'APPT' and r.name = 'Lead-Client' and c.result_id = r.id and c.call_result = 'Lead-Client';
update public.call_results set name = 'Lead-CurrentClient'
 where project_type = 'APPT' and name = 'Lead-Client';
update public.call_results
   set aliases = array['xd-client', 'lead-client', 'xd-current client', 'xd-currentclient', 'lead-current client', 'current client']
 where project_type = 'APPT' and name = 'Lead-CurrentClient';

insert into public.call_results
  (project_type, name, sort_order, viable, callable, sort_last, effect, pay_kind, applies_to, status_code, action, aliases)
values
  ('APPT', 'Lead-ClientList', 35, true, true, false, 'none', null, 'name', 'xdate',
   'Stays on active Appt project call lists (tracked by # of calls made to each name/weighted). Viewable results stays as titled',
   array['xd-client list', 'xd-clientlist', 'lead-client list', 'client list', 'clientlist'])
on conflict (project_type, name) do update set
  sort_order = excluded.sort_order, viable = excluded.viable, callable = excluded.callable,
  sort_last = excluded.sort_last, effect = excluded.effect, pay_kind = excluded.pay_kind,
  applies_to = excluded.applies_to, status_code = excluded.status_code,
  action = excluded.action, aliases = excluded.aliases;

-- ==============================================================================================================
-- 20261101100000_client_project_stats.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — client and project figures, counted by call result
-- (Sean, Oct 2026)
--
-- The Clients and Project pages counted every name loaded as a "lead" and
-- every record with an appointment date as an "appointment". They now count
-- by where each name stands, its call result:
--
--   names            every record loaded
--   names left       DB dev names still to call (Viable-…, Pending)
--   leads            names at the appointment stage: active (a viable
--                    result: Lead-No Contact, -Left Message, -Email,
--                    -ClientList, -Not Shopping, -Corrected) or resolved
--                    (any other: an appointment, removed, invalid…)
--   developed        names DB dev made a lead or an appointment (DB dev
--                    result Lead, Lead-Hot Lead, Appointment…, Lead-Invalid,
--                    Appointment-Invalid), whatever became of them
--   appointments     names whose result is Appointment, Appointment-Phone
--                    or Appointment-Confirmed (either list)
--   invalid          names whose result is Appointment-Invalid
--
--   lead_classes         each name with its result's kind, and its DB dev
--                        result read from what was recorded or imported
--   lead_stats()         the counts for a client (each project, and the
--                        client's total with each name once) or one project
--   result_breakdown()   a project's names by call result, for its graph
--
-- A DB dev project counts the names it was loaded with wherever they are
-- now: those still on it, and those it sent on to its appointment project.
-- ---------------------------------------------------------------------------

create or replace view public.lead_classes with (security_invoker = true) as
  select l.id, l.project_id, l.source_project_id, l.stage,
         r.name as result, r.project_type as result_type, r.viable, r.callable, r.effect, r.sort_order,
         d.name as dbdv_result,
         -- DB dev developed it: it came on from a DB dev project, or its DB dev result says so.
         ((l.stage = 'appt' and l.source_project_id is not null and l.source_project_id <> l.project_id)
           or coalesce(d.effect in ('promote', 'appointment', 'confirm', 'appointment_invalid') or d.name = 'Lead-Invalid', false)) as developed
    from public.leads l
    join public.call_results r on r.id = l.result_id
    left join lateral (
      select cr.name, cr.effect
        from public.call_results cr
       where cr.project_type = 'DBDV' and nullif(btrim(l.call_result_dbdv), '') is not null
         and (lower(cr.name) = lower(btrim(l.call_result_dbdv)) or lower(btrim(l.call_result_dbdv)) = any (cr.aliases))
       order by cr.sort_order
       limit 1
    ) d on true;
revoke all on public.lead_classes from anon;
grant select on public.lead_classes to authenticated;

/**
 * The counts for one project (`p_project_id`), or for a client: a row for
 * each of its projects and one with a null project for the client as a
 * whole, each name once. Staff only (Row Level Security on leads).
 */
create or replace function public.lead_stats(p_company_id bigint default null, p_project_id bigint default null)
returns table (
  project_id bigint, names bigint, names_left bigint, leads_active bigint, leads_resolved bigint,
  developed bigint, appointments bigint, invalid_appointments bigint
)
language sql stable security invoker set search_path = public as $$
  with ps as (
    select p.id from public.projects p
     where (p_project_id is not null and p.id = p_project_id)
        or (p_project_id is null and p_company_id is not null and p.company_id = p_company_id)
  ), scoped as (
    -- A project's names: those on it, and those it sent on to another.
    select ps.id as pid, c.*, (c.project_id = ps.id) as here
      from ps join public.lead_classes c
        on c.project_id = ps.id or (c.source_project_id = ps.id and c.source_project_id <> c.project_id)
  ), per as (
    select pid,
           count(*) as names,
           count(*) filter (where here and stage = 'dbdev' and viable) as names_left,
           count(*) filter (where stage = 'appt' and viable) as leads_active,
           count(*) filter (where stage = 'appt' and not viable) as leads_resolved,
           count(*) filter (where developed) as developed,
           count(*) filter (where effect in ('appointment', 'confirm')) as appointments,
           count(*) filter (where effect = 'appointment_invalid') as invalid_appointments
      from scoped group by pid
  )
  select ps.id, coalesce(per.names, 0), coalesce(per.names_left, 0), coalesce(per.leads_active, 0), coalesce(per.leads_resolved, 0),
         coalesce(per.developed, 0), coalesce(per.appointments, 0), coalesce(per.invalid_appointments, 0)
    from ps left join per on per.pid = ps.id
  union all
  select null, count(*),
         count(*) filter (where c.stage = 'dbdev' and c.viable),
         count(*) filter (where c.stage = 'appt' and c.viable),
         count(*) filter (where c.stage = 'appt' and not c.viable),
         count(*) filter (where c.developed),
         count(*) filter (where c.effect in ('appointment', 'confirm')),
         count(*) filter (where c.effect = 'appointment_invalid')
    from public.lead_classes c
   where p_project_id is null and p_company_id is not null and c.project_id in (select id from ps)
  -- The client's total only when a client was asked for (an aggregate otherwise still answers, with zeros).
  having p_project_id is null and p_company_id is not null;
$$;
revoke execute on function public.lead_stats(bigint, bigint) from public, anon;
grant execute on function public.lead_stats(bigint, bigint) to authenticated;

/**
 * A project's names by call result, most first: a DB dev project by DB dev
 * result (the names it sent on by the result that sent them), an
 * appointment project by appointment result. `kind`: viable (still to
 * call), won (a lead or an appointment) or resolved.
 */
create or replace function public.result_breakdown(p_project_id bigint)
returns table (result text, names bigint, kind text)
language sql stable security invoker set search_path = public as $$
  with p as (
    select pr.id, public.project_type_code(pr.id) as type from public.projects pr where pr.id = p_project_id
  ), named as (
    select case when p.type = 'DBDV' and c.stage <> 'dbdev' then coalesce(c.dbdv_result, 'Lead') else c.result end as result
      from p join public.lead_classes c
        on c.project_id = p.id or (p.type = 'DBDV' and c.source_project_id = p.id and c.source_project_id <> c.project_id)
  )
  select n.result, count(*),
         coalesce((select case when r.viable then 'viable'
                               when r.effect in ('promote', 'appointment', 'confirm') then 'won'
                               else 'resolved' end
                     from public.call_results r, p
                    where r.name = n.result order by (r.project_type = p.type) desc limit 1), 'resolved')
    from named n
   group by n.result
   order by 2 desc, 1;
$$;
revoke execute on function public.result_breakdown(bigint) from public, anon;
grant execute on function public.result_breakdown(bigint) to authenticated;

-- ==============================================================================================================
-- 20261102100000_calendar_blocks.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — time blocked out on a project's calendar (Sean, Oct 2026)
--
-- A client or agent blocks out whole days, or a time of day (10 AM – 1 PM),
-- on a project's calendar: when they are not available for appointments.
-- Blocked time shows on the calendar, and a manager booking over it is
-- warned (not stopped). Managers, agents, administrators and the client's
-- own people can all add and remove it.
--
-- A project's calendar is its appointment project's: a DB dev project's
-- appointments are kept on the project it promotes to, so blocked time
-- added from a DB dev project goes there too (one calendar for the pair).
--
--   calendar_blocks                 from a day to a day, all day or between
--                                   two times each day, with a note
--   calendar_project(project)       the project whose calendar it is
-- ---------------------------------------------------------------------------

create or replace function public.calendar_project(p_project_id bigint)
returns bigint
language sql stable security definer set search_path = public as $$
  select coalesce(p.appt_project_id, p.id) from public.projects p where p.id = p_project_id;
$$;
revoke execute on function public.calendar_project(bigint) from public, anon;
grant execute on function public.calendar_project(bigint) to authenticated;

create table if not exists public.calendar_blocks (
  id          bigint generated always as identity primary key,
  project_id  bigint not null references public.projects(id) on delete cascade,
  starts_on   date not null,
  ends_on     date not null,
  start_time  time,
  end_time    time,
  note        text check (length(note) <= 200),
  created_by  bigint references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  check (ends_on >= starts_on and ends_on - starts_on <= 366),
  -- All day (no times), or both times with the end after the start.
  check ((start_time is null and end_time is null) or (start_time is not null and end_time is not null and end_time > start_time))
);
create index if not exists calendar_blocks_project on public.calendar_blocks (project_id, starts_on, ends_on);

-- Kept on the calendar's own project, and signed by whoever added it.
create or replace function public.tg_calendar_blocks_place()
returns trigger
language plpgsql set search_path = public as $$
begin
  new.project_id := coalesce(public.calendar_project(new.project_id), new.project_id);
  if current_user = 'authenticated' then
    new.created_by := public.app_user_id();
    new.created_at := now();
  end if;
  return new;
end $$;
drop trigger if exists calendar_blocks_place on public.calendar_blocks;
create trigger calendar_blocks_place
  before insert on public.calendar_blocks
  for each row execute function public.tg_calendar_blocks_place();

alter table public.calendar_blocks enable row level security;
-- Staff, and a client's people for their own projects: to see it, add it and take it off.
drop policy if exists calendar_blocks_all on public.calendar_blocks;
create policy calendar_blocks_all on public.calendar_blocks
  for all to authenticated
  using ((select public.is_staff()) or project_id in (select public.client_project_ids()))
  with check ((select public.is_staff())
              or (project_id in (select public.client_project_ids())
                  and public.calendar_project(project_id) in (select public.client_project_ids())));
drop policy if exists mfa_required on public.calendar_blocks;
create policy mfa_required on public.calendar_blocks as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.calendar_blocks;
create policy active_account_required on public.calendar_blocks as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.calendar_blocks from anon;
grant select, insert, delete on public.calendar_blocks to authenticated;
grant all on public.calendar_blocks to service_role;

-- ==============================================================================================================
-- 20261103100000_calendar_feeds.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a personal calendar's busy times on a project's calendar
-- (Sean, Oct 2026)
--
-- A client, agent or manager connects their own calendar (Google, Outlook
-- or iCloud, by its private link) to a project's calendar. The app reads
-- when they are busy, and nothing else, and keeps it as blocked time
-- there: shown on the calendar, and warned about when a manager books over
-- it, like time blocked out by hand.
--
--   calendar_feeds            the calendar a person connected to a
--                             project's calendar: its link (theirs alone to
--                             read), when it was last read, how it went
--   calendar_blocks.feed_id   blocked time that came from one; it goes when
--                             the calendar is disconnected
--
-- The link gives whoever holds it the person's calendar, so nobody but its
-- owner can read it, an administrator included. The server reads the link
-- itself (the service role), never a browser: when it is connected, when
-- its owner asks, and when the project's calendar is opened and the last
-- read is more than fifteen minutes old.
-- ---------------------------------------------------------------------------

create table if not exists public.calendar_feeds (
  id              bigint generated always as identity primary key,
  user_id         bigint not null references public.users(id) on delete cascade,
  project_id      bigint not null references public.projects(id) on delete cascade,
  url             text not null check (url ~ '^https://' and length(url) <= 1000),
  provider        text not null check (length(provider) <= 40),
  busy_count      int not null default 0,
  last_synced_at  timestamptz,
  last_error      text check (length(last_error) <= 300),
  created_at      timestamptz not null default now(),
  unique (user_id, project_id)
);
create index if not exists calendar_feeds_project on public.calendar_feeds (project_id);

-- Kept on the calendar's own project, and its owner's.
create or replace function public.tg_calendar_feeds_place()
returns trigger
language plpgsql set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    new.project_id := coalesce(public.calendar_project(new.project_id), new.project_id);
  end if;
  if current_user = 'authenticated' then
    new.user_id := public.app_user_id();
    if tg_op = 'UPDATE' then
      new.project_id := old.project_id;
    end if;
  end if;
  return new;
end $$;
drop trigger if exists calendar_feeds_place on public.calendar_feeds;
create trigger calendar_feeds_place
  before insert or update on public.calendar_feeds
  for each row execute function public.tg_calendar_feeds_place();

alter table public.calendar_feeds enable row level security;
-- One's own, on a calendar one can see: nobody else reads the link.
drop policy if exists calendar_feeds_own on public.calendar_feeds;
create policy calendar_feeds_own on public.calendar_feeds
  for all to authenticated
  using (user_id = (select public.app_user_id()))
  with check (user_id = (select public.app_user_id())
              and ((select public.is_staff()) or project_id in (select public.client_project_ids())));
drop policy if exists mfa_required on public.calendar_feeds;
create policy mfa_required on public.calendar_feeds as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.calendar_feeds;
create policy active_account_required on public.calendar_feeds as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.calendar_feeds from anon;
grant select, insert, update, delete on public.calendar_feeds to authenticated;
grant all on public.calendar_feeds to service_role;

-- Blocked time read from a connected calendar. It is the server's to write:
-- a block added by hand never carries one.
alter table public.calendar_blocks add column if not exists feed_id bigint references public.calendar_feeds(id) on delete cascade;
create index if not exists calendar_blocks_feed on public.calendar_blocks (feed_id) where feed_id is not null;

create or replace function public.tg_calendar_blocks_place()
returns trigger
language plpgsql set search_path = public as $$
begin
  new.project_id := coalesce(public.calendar_project(new.project_id), new.project_id);
  if current_user = 'authenticated' then
    new.created_by := public.app_user_id();
    new.created_at := now();
    new.feed_id := null;
  end if;
  return new;
end $$;

-- A connected calendar's busy times go with the calendar, not one by one.
drop policy if exists calendar_blocks_synced_kept on public.calendar_blocks;
create policy calendar_blocks_synced_kept on public.calendar_blocks as restrictive
  for delete to authenticated
  using (feed_id is null);

-- The server writes synced busy times with the service role, and placing a
-- block asks which calendar a project's is.
grant execute on function public.calendar_project(bigint) to service_role;

-- ==============================================================================================================
-- 20261104100000_soft_delete.sql
-- ==============================================================================================================

-- Deleting sets a flag: nothing a person deletes in Lighthouse is removed
-- from the database.
--
-- A client, a project, a lead, an appointment, an insurance company, a
-- document, a bulletin post or a user that is deleted keeps its row, marked
-- with when and by whom (deleted_at, deleted_by). From then on it is hidden
-- from everyone signed in, by Row Level Security: every list, search, call
-- list, calendar, count and report reads through it, so none of them needs
-- to know. An administrator sees what was deleted under Settings and can
-- bring it back.
--
-- What goes with what, and comes back with it (deleted_via names the record
-- that took it): a client's projects; a project's leads; a lead's
-- appointments. Calls made, pay earned and notes are left as they are.
--
-- The delete itself is unchanged for the app's roles: the same people may
-- delete the same things (the tables' own policies decide). A trigger turns
-- their DELETE into the flag. The database's own roles (migrations, the SQL
-- editor, the reset script, the server's service role) still remove rows.
--
-- Safe to run again.

-- --- 1. The flag ----------------------------------------------------------
-- deleted_by has no foreign key on purpose: a second link between a table
-- and users would make the API's joins between the two ambiguous.
do $$
declare
  t text;
begin
  foreach t in array array['companies', 'projects', 'leads', 'appointments', 'agencies', 'documents', 'bulletin_board', 'users'] loop
    execute format('alter table public.%I add column if not exists deleted_at timestamptz, add column if not exists deleted_by bigint, add column if not exists deleted_via text', t);
    execute format('create index if not exists %I on public.%I (deleted_at) where deleted_at is not null', t || '_deleted_idx', t);
    execute format('create index if not exists %I on public.%I (deleted_via) where deleted_via is not null', t || '_deleted_via_idx', t);
  end loop;
end $$;

-- --- 2. Deleting sets it --------------------------------------------------
create or replace function public.tg_soft_delete()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_me    bigint := public.app_user_id();
  v_now   timestamptz := now();
  v_via   text := tg_table_name || ':' || old.id;
  v_other text;
begin
  if old.deleted_at is not null then
    return null;
  end if;

  if tg_table_name = 'projects' then
    -- Leads promoted from a DB dev project would land on a project nobody can see.
    select p.name into v_other from public.projects p
     where p.appt_project_id = old.id and p.id <> old.id and p.deleted_at is null limit 1;
    if v_other is not null then
      raise exception '% promotes its leads to this project. Delete that project first, or have it promote to another.', v_other
        using errcode = '23503';
    end if;
    update public.appointments a set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where a.deleted_at is null
       and a.lead_id in (select l.id from public.leads l where l.project_id = old.id and l.deleted_at is null);
    update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where project_id = old.id and deleted_at is null;
    update public.projects set deleted_at = v_now, deleted_by = v_me, deleted_via = null where id = old.id;

  elsif tg_table_name = 'companies' then
    update public.appointments a set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where a.deleted_at is null
       and a.lead_id in (select l.id from public.leads l join public.projects p on p.id = l.project_id
                          where p.company_id = old.id and p.deleted_at is null and l.deleted_at is null);
    update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where deleted_at is null
       and project_id in (select p.id from public.projects p where p.company_id = old.id and p.deleted_at is null);
    update public.projects set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where company_id = old.id and deleted_at is null;
    update public.companies set deleted_at = v_now, deleted_by = v_me, deleted_via = null where id = old.id;

  elsif tg_table_name = 'leads' then
    update public.appointments set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where lead_id = old.id and deleted_at is null;
    update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = null where id = old.id;

  elsif tg_table_name = 'users' then
    -- The account no longer counts as active anywhere; its sign-in is removed by the app.
    update public.users set deleted_at = v_now, deleted_by = v_me, deleted_via = null, status = 'disabled' where id = old.id;

  else
    execute format('update public.%I set deleted_at = $1, deleted_by = $2, deleted_via = null where id = $3', tg_table_name)
      using v_now, v_me, old.id;
  end if;

  -- The row stays.
  return null;
end $$;
revoke execute on function public.tg_soft_delete() from public, anon, authenticated;

-- --- 3. Deleted is hidden; a delete becomes the flag ------------------------
do $$
declare
  t text;
begin
  foreach t in array array['companies', 'projects', 'leads', 'appointments', 'agencies', 'documents', 'bulletin_board', 'users'] loop
    execute format('drop policy if exists not_deleted on public.%I', t);
    execute format('create policy not_deleted on public.%I as restrictive for select to authenticated using (deleted_at is null)', t);
    execute format('drop trigger if exists soft_delete on public.%I', t);
    execute format('create trigger soft_delete before delete on public.%I for each row when (current_user = ''authenticated'') execute function public.tg_soft_delete()', t);
  end loop;
end $$;

-- --- 4. Deleting from the app ---------------------------------------------
-- A delete that only sets a flag returns no rows, as one Row Level Security
-- refused does. This says which: true when the record was there to see and
-- no longer is. Runs as the caller, so their own rights decide.
create or replace function public.remove_record(p_table text, p_id bigint)
returns boolean
language plpgsql set search_path = public as $$
declare
  v_seen boolean;
begin
  if p_table not in ('companies', 'projects', 'leads', 'appointments', 'agencies', 'documents', 'bulletin_board', 'users') then
    raise exception 'Not a kind of record that can be deleted this way' using errcode = '22023';
  end if;
  execute format('select exists (select 1 from public.%I where id = $1)', p_table) into v_seen using p_id;
  if not v_seen then
    return false;
  end if;
  execute format('delete from public.%I where id = $1', p_table) using p_id;
  execute format('select exists (select 1 from public.%I where id = $1)', p_table) into v_seen using p_id;
  return not v_seen;
end $$;
revoke execute on function public.remove_record(text, bigint) from public, anon;
grant execute on function public.remove_record(text, bigint) to authenticated;

-- --- 5. What was deleted, and bringing it back (administrators) -----------
-- The records deleted in their own right, newest first: not what went with
-- them (`also` counts those). Nothing for anyone but an administrator.
create or replace function public.deleted_records()
returns table (kind text, id bigint, name text, detail text, deleted_at timestamptz, deleted_by text, also bigint)
language sql stable security definer set search_path = public as $$
  with d as (
    select 'companies' as kind, c.id, c.name, null::text as detail, c.deleted_at, c.deleted_by from public.companies c
     where c.deleted_at is not null and c.deleted_via is null
    union all
    select 'projects', p.id, p.name, (select c.name from public.companies c where c.id = p.company_id), p.deleted_at, p.deleted_by from public.projects p
     where p.deleted_at is not null and p.deleted_via is null
    union all
    select 'leads', l.id, l.company_name, (select p.name from public.projects p where p.id = l.project_id), l.deleted_at, l.deleted_by from public.leads l
     where l.deleted_at is not null and l.deleted_via is null
    union all
    select 'appointments', a.id, coalesce((select l.company_name from public.leads l where l.id = a.lead_id), 'Appointment'),
           concat_ws(' at ', to_char(a.appt_date, 'Mon FMDD, YYYY'), a.appt_time), a.deleted_at, a.deleted_by from public.appointments a
     where a.deleted_at is not null and a.deleted_via is null
    union all
    select 'agencies', g.id, g.name, null, g.deleted_at, g.deleted_by from public.agencies g
     where g.deleted_at is not null and g.deleted_via is null
    union all
    select 'documents', f.id, f.name, f.file_type, f.deleted_at, f.deleted_by from public.documents f
     where f.deleted_at is not null and f.deleted_via is null
    union all
    select 'bulletin_board', b.id, left(b.message, 80), b.message_type, b.deleted_at, b.deleted_by from public.bulletin_board b
     where b.deleted_at is not null and b.deleted_via is null
    union all
    select 'users', u.id, nullif(concat_ws(' ', u.first_name, u.last_name), ''), u.email, u.deleted_at, u.deleted_by from public.users u
     where u.deleted_at is not null and u.deleted_via is null
  )
  select d.kind, d.id, d.name, d.detail, d.deleted_at,
         (select nullif(concat_ws(' ', u.first_name, u.last_name), '') from public.users u where u.id = d.deleted_by),
         (select count(*) from public.projects p where p.deleted_via = d.kind || ':' || d.id)
       + (select count(*) from public.leads l where l.deleted_via = d.kind || ':' || d.id)
       + (select count(*) from public.appointments a where a.deleted_via = d.kind || ':' || d.id)
    from d
   where public.is_admin()
   order by d.deleted_at desc, d.kind, d.id
   limit 500;
$$;
revoke execute on function public.deleted_records() from public, anon;
grant execute on function public.deleted_records() to authenticated;

-- Bring a deleted record back, with whatever went with it. Not while what
-- it belongs to is still deleted: that comes back first.
create or replace function public.restore_record(p_table text, p_id bigint)
returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_via  text := p_table || ':' || p_id;
  v_n    integer;
  v_held text;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can restore a deleted record' using errcode = '42501';
  end if;
  if p_table not in ('companies', 'projects', 'leads', 'appointments', 'agencies', 'documents', 'bulletin_board', 'users') then
    raise exception 'Not a kind of record that can be restored' using errcode = '22023';
  end if;

  if p_table = 'projects' then
    select c.name into v_held from public.projects p join public.companies c on c.id = p.company_id
     where p.id = p_id and c.deleted_at is not null;
    if v_held is not null then
      raise exception 'Its client, %, is deleted. Restore the client first.', v_held using errcode = '23503';
    end if;
  elsif p_table = 'leads' then
    select p.name into v_held from public.leads l join public.projects p on p.id = l.project_id
     where l.id = p_id and p.deleted_at is not null;
    if v_held is not null then
      raise exception 'Its project, %, is deleted. Restore the project first.', v_held using errcode = '23503';
    end if;
  elsif p_table = 'appointments' then
    select l.company_name into v_held from public.appointments a join public.leads l on l.id = a.lead_id
     where a.id = p_id and l.deleted_at is not null;
    if v_held is not null then
      raise exception 'Its lead, %, is deleted. Restore the lead first.', v_held using errcode = '23503';
    end if;
  end if;

  -- Only what was deleted in its own right: what went with something comes back with that.
  execute format('update public.%I set deleted_at = null, deleted_by = null where id = $1 and deleted_at is not null and deleted_via is null', p_table)
    using p_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then
    return false;
  end if;

  update public.projects set deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  update public.leads set deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  update public.appointments set deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  return true;
end $$;
revoke execute on function public.restore_record(text, bigint) from public, anon;
grant execute on function public.restore_record(text, bigint) to authenticated;

-- --- 6. What reads past Row Level Security leaves the deleted out too ------
-- These run with the database's own rights (who may work a lead, a client's
-- projects, the scheduled reminders and alerts, sharing names out), so the
-- policy above does not reach them. Each is as it was, but for the flag.

-- A deleted lead is nobody's to work.
CREATE OR REPLACE FUNCTION public.can_work_lead(p_lead_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((
    select case
             when public.app_role() = 'admin' then true
             when public.app_role() in ('manager', 'agent') then
                  l.assigned_user_id = public.app_user_id()
               or exists (select 1 from public.project_assignments pa
                           where pa.project_id = l.project_id and pa.ae_user_id = public.app_user_id())
               or (select a.user_id from public.appointments a
                    where a.lead_id = l.id and a.invalid_at is null and a.deleted_at is null
                    order by a.appt_create_date desc, a.id desc
                    limit 1) = public.app_user_id()
           end
      from public.leads l
     where l.id = p_lead_id and l.deleted_at is null), false);
$function$;

-- A client's projects: not the deleted ones.
CREATE OR REPLACE FUNCTION public.client_project_ids()
 RETURNS SETOF bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.id from public.projects p
  where p.company_id = public.app_company_id() and p.deleted_at is null
  union
  select pa.project_id from public.project_assignments pa
  where pa.cl_user_id = public.app_user_id()
    and exists (select 1 from public.projects p where p.id = pa.project_id and p.deleted_at is null);
$function$;

-- A rep's load counts the names still there.
CREATE OR REPLACE FUNCTION public.least_loaded_rep(p_project bigint)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select pa.ae_user_id
    from public.project_assignments pa
    join public.users u on u.id = pa.ae_user_id and u.status = 'active'
   where pa.project_id = p_project
   order by (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
              where l.project_id = p_project and l.assigned_user_id = pa.ae_user_id and r.viable and r.callable and l.deleted_at is null),
            pa.ae_user_id
   limit 1;
$function$;

-- No call-back reminder for a deleted lead (it waits, and is delivered if the lead is restored).
CREATE OR REPLACE FUNCTION public.deliver_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r     record;
  v_id  bigint;
  n     integer := 0;
begin
  for r in
    select m.id, m.user_id, m.lead_id, m.note, m.remind_at, l.company_name
      from public.reminders m
      join public.leads l on l.id = m.lead_id and l.deleted_at is null
     where m.sent_at is null and m.remind_at <= now()
     order by m.remind_at
     for update of m skip locked
  loop
    insert into public.notifications (user_id, kind, title, body, link)
    values (
      r.user_id, 'reminder',
      left('Call back: ' || coalesce(r.company_name, 'a lead'), 120),
      left(concat_ws(' · ', 'Reminder for ' || to_char(r.remind_at at time zone public.business_tz(), 'FMHH12:MI AM'), r.note), 1000),
      '/leads/' || r.lead_id
    )
    returning id into v_id;
    update public.reminders set sent_at = now(), notification_id = v_id where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $function$;

-- The morning's appointment reminders: not for deleted appointments or leads.
CREATE OR REPLACE FUNCTION public.send_appointment_reminders(p_day date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  n integer := 0;
begin
  for r in
    with live as (
      select a.user_id, a.appt_date, a.appt_time, a.confirmed_at, l.company_name
        from public.appointments a
        join public.leads l on l.id = a.lead_id and l.deleted_at is null
        left join public.appointment_statuses s on s.id = a.status_id
       where a.user_id is not null and a.invalid_at is null and a.deleted_at is null
         and coalesce(s.name, '') not in ('Cancelled', 'No Show', 'Invalid')
         and a.appt_date in (p_day, p_day + 1)
    )
    select user_id,
           count(*) filter (where appt_date = p_day) as today,
           count(*) filter (where appt_date = p_day + 1 and confirmed_at is null) as to_confirm,
           array_to_string((array_agg(coalesce(appt_time || ' ', '') || company_name order by appt_time)
                             filter (where appt_date = p_day))[1:5], ', ') as today_list,
           array_to_string((array_agg(company_name order by company_name)
                             filter (where appt_date = p_day + 1 and confirmed_at is null))[1:5], ', ') as confirm_list
      from live
     group by user_id
  loop
    if r.today = 0 and r.to_confirm = 0 then continue; end if;
    if exists (select 1 from public.alert_sends where rule = 'appt_reminder' and key = r.user_id || ':' || p_day) then
      continue;
    end if;
    insert into public.alert_sends (rule, key) values ('appt_reminder', r.user_id || ':' || p_day);
    n := n + public.notify_users(
      array[r.user_id], 'appointment',
      concat_ws(', ',
        case when r.today > 0 then r.today || ' appointment' || case when r.today = 1 then '' else 's' end || ' today' end,
        case when r.to_confirm > 0 then r.to_confirm || ' to confirm for tomorrow' end),
      concat_ws(' · ',
        case when r.today > 0 then 'Today: ' || r.today_list end,
        case when r.to_confirm > 0 then 'Confirm: ' || r.confirm_list end),
      '/calendar?view=day&d=' || p_day,
      'appt_reminder');
  end loop;
  return n;
end $function$;

-- X-date warnings: not for deleted leads.
CREATE OR REPLACE FUNCTION public.send_xdate_warnings(p_day date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r     record;
  n     integer := 0;
  v_due date := p_day + 30;
begin
  for r in
    with due as (
      select l.id, l.company_name, coalesce(l.assigned_user_id, pa.ae_user_id) as rep
        from public.leads l
        join public.insurance_details i on i.lead_id = l.id
        left join public.call_results cr on cr.id = l.result_id
        -- Nobody holds it: whoever is on its project hears instead.
        left join lateral (select a.ae_user_id from public.project_assignments a
                            where a.project_id = l.project_id and l.assigned_user_id is null) pa on true
       where l.deleted_at is null
         and coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                              i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)) = v_due
         and (cr.id is null or cr.viable)          -- still worth a call: not off the list
    )
    select rep, count(*) as total, min(id) as first_id,
           (array_agg(company_name order by company_name))[1:5] as names
      from due where rep is not null
     group by rep
  loop
    if exists (select 1 from public.alert_sends where rule = 'xdate_30d' and key = r.rep || ':' || p_day) then
      continue;
    end if;
    insert into public.alert_sends (rule, key) values ('xdate_30d', r.rep || ':' || p_day);
    n := n + public.notify_users(
      array[r.rep], 'lead',
      case when r.total = 1 then 'X-date in 30 days: ' || r.names[1]
           else r.total || ' X-dates in 30 days' end,
      'Renewing ' || to_char(v_due, 'FMMon FMDD') ||
        case when r.total = 1 then '' else ': ' || array_to_string(r.names, ', ') ||
          case when r.total > 5 then ' and ' || (r.total - 5) || ' more' else '' end end,
      case when r.total = 1 then '/leads/' || r.first_id else '/work' end,
      'xdate_30d');
  end loop;
  return n;
end $function$;

-- Sharing a project's names out: only the names still there.
CREATE OR REPLACE FUNCTION public.distribute_names(p_project_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reps   bigint[];
  v_k      int;
  v_total  int;
  v_base   int;
  v_extra  int;
  rep      record;
  v_target int;
  v_before jsonb;
  v_moved  int := 0;
  v_n      int;
begin
  perform 1 from public.projects where id = p_project_id for update;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(pa.ae_user_id order by pa.ae_user_id), '{}')
    into v_reps
    from public.project_assignments pa
    join public.users u on u.id = pa.ae_user_id and u.status = 'active'
   where pa.project_id = p_project_id;
  v_k := coalesce(array_length(v_reps, 1), 0);

  -- Names held by anyone no longer on the project go back in the pool.
  update public.leads l set assigned_user_id = null
    from public.call_results r
   where r.id = l.result_id and r.viable and r.callable
     and l.project_id = p_project_id and l.deleted_at is null
     and l.assigned_user_id is not null
     and not (l.assigned_user_id = any(v_reps));

  select coalesce(jsonb_object_agg(uid, n), '{}') into v_before
    from (select l.assigned_user_id as uid, count(*) as n
            from public.leads l join public.call_results r on r.id = l.result_id
           where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable and l.assigned_user_id is not null
           group by 1) c;

  if v_k = 0 then
    return jsonb_build_object('project_id', p_project_id, 'reps', 0, 'moved', 0,
                              'message', 'Nobody is assigned to this project yet');
  end if;

  select count(*) into v_total
    from public.leads l join public.call_results r on r.id = l.result_id
   where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable;
  v_base  := v_total / v_k;
  v_extra := v_total % v_k;

  -- Whoever holds most keeps the larger shares, so the fewest names move.
  for rep in
    select u.uid, row_number() over (order by coalesce(c.n, 0) desc, u.uid) as rank_no, coalesce(c.n, 0) as held
      from unnest(v_reps) as u(uid)
      left join (select l.assigned_user_id as uid, count(*) as n
                   from public.leads l join public.call_results r on r.id = l.result_id
                  where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable
                  group by 1) c on c.uid = u.uid
  loop
    v_target := v_base + case when rep.rank_no <= v_extra then 1 else 0 end;
    if rep.held > v_target then
      update public.leads set assigned_user_id = null
       where id in (select l.id from public.leads l join public.call_results r on r.id = l.result_id
                     where l.project_id = p_project_id and l.deleted_at is null and l.assigned_user_id = rep.uid and r.viable and r.callable
                     order by l.call_weight, l.date_last_worked nulls first, l.id desc
                     limit rep.held - v_target);
      get diagnostics v_n = row_count;
      v_moved := v_moved + v_n;
    end if;
  end loop;

  for rep in
    select u.uid, row_number() over (order by coalesce(c.n, 0) desc, u.uid) as rank_no, coalesce(c.n, 0) as held
      from unnest(v_reps) as u(uid)
      left join (select l.assigned_user_id as uid, count(*) as n
                   from public.leads l join public.call_results r on r.id = l.result_id
                  where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable
                  group by 1) c on c.uid = u.uid
  loop
    v_target := v_base + case when rep.rank_no <= v_extra then 1 else 0 end;
    if rep.held < v_target then
      update public.leads set assigned_user_id = rep.uid
       where id in (select l.id from public.leads l join public.call_results r on r.id = l.result_id
                     where l.project_id = p_project_id and l.deleted_at is null and l.assigned_user_id is null and r.viable and r.callable
                     order by l.id
                     limit v_target - rep.held);
    end if;
  end loop;

  return jsonb_build_object(
    'project_id', p_project_id,
    'names', v_total,
    'reps', v_k,
    'moved', v_moved,
    'before', v_before,
    'after', (select coalesce(jsonb_object_agg(uid, n), '{}')
                from (select l.assigned_user_id as uid, count(*) as n
                        from public.leads l join public.call_results r on r.id = l.result_id
                       where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable and l.assigned_user_id is not null
                       group by 1) c));
end $function$;

-- ==============================================================================================================
-- 20261105100000_client_agency_group.sql
-- ==============================================================================================================

-- A client's agency group (Sean, Oct 2026): the national carrier group a
-- client belongs to, chosen from the insurance companies list, so clients
-- and their projects can be shown and filtered by group in reports.
--
-- One group a client, or none. Taking an insurance company off the list
-- leaves its clients without a group rather than removing them.
--
-- Safe to run again.

alter table public.companies
  add column if not exists agency_group_id bigint references public.agencies(id) on delete set null;

create index if not exists companies_agency_group_idx on public.companies (agency_group_id) where agency_group_id is not null;

comment on column public.companies.agency_group_id is 'The carrier group this client belongs to (agencies.id), for reports.';

-- ==============================================================================================================
-- 20261106100000_remove_session_takeover.sql
-- ==============================================================================================================

-- Taking a session over was started and abandoned (Oct 2026): its migration
-- was never part of the app, but where it was run it left pieces behind that
-- break things. The worst: a second link from the activity log to users,
-- which made "whose activity is this" ambiguous to the API, so My Security
-- (where a temporary password or an invitation sends people) would not open.
--
-- This removes every piece and puts back the three functions it replaced,
-- exactly as migrations 20260929100000 and 20261006100000 define them. Where
-- that migration was never run, this changes nothing.
--
-- Safe to run again.

-- --- The activity log: one link to users, and its stamp as it was -----------
alter table public.activity_log drop column if exists acting_admin_id;

create or replace function public.tg_activity_log_stamp()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user = 'authenticated' then
    new.user_id := public.app_user_id();
    new.created_at := now();
  end if;
  return new;
end $$;

-- --- Two-factor: satisfied by a second factor, or by having none enrolled ---
create or replace function public.mfa_satisfied()
returns boolean
language sql stable security definer set search_path = public, auth as $$
  select coalesce((select auth.jwt() ->> 'aal') = 'aal2', false)
      or not exists (
        select 1 from auth.mfa_factors f
         where f.user_id = auth.uid() and f.status = 'verified'
      );
$$;
revoke execute on function public.mfa_satisfied() from public, anon;
grant execute on function public.mfa_satisfied() to authenticated;

-- --- Time worked: recorded for the person signed in -------------------------
create or replace function public.track_activity(p_kind text default 'use', p_lead bigint default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();   -- null for an inactive account or one short of two-factor
  v_lead bigint;
begin
  if v_me is null or public.app_role() not in ('admin', 'manager', 'agent') then
    return;
  end if;
  if p_kind = 'call' and p_lead is not null then
    select l.id into v_lead from public.leads l where l.id = p_lead;
  end if;
  if v_lead is not null then
    insert into public.work_activity (user_id, minute, kind, lead_id)
    values (v_me, date_trunc('minute', now()), 'call', v_lead)
    on conflict do nothing;
  end if;
  insert into public.work_activity (user_id, minute, kind)
  values (v_me, date_trunc('minute', now()), 'use')
  on conflict do nothing;
end $$;
revoke execute on function public.track_activity(text, bigint) from public, anon;
grant execute on function public.track_activity(text, bigint) to authenticated;

-- --- What it added ----------------------------------------------------------
drop function if exists public.request_takeover(bigint, int, text);
drop function if exists public.answer_takeover(bigint, boolean);
drop function if exists public.takeover_details(bigint);
drop function if exists public.prepare_takeover(bigint);
drop function if exists public.start_takeover(bigint, bigint, uuid);
drop function if exists public.end_takeover(bigint, text);
drop function if exists public.my_takeover();
drop function if exists public.user_display_name(bigint);
drop function if exists public.jwt_session_id();
drop table if exists public.session_takeovers;

-- The API reads the tables' links from its cache: have it read them again.
notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261107100000_clients_page.sql
-- ==============================================================================================================

-- The Clients page (Sean, Oct 2026): clients listed in rows with their state,
-- time zone, start and end dates and a status of Active, Paused or
-- Completed; and tiles for the active clients' leads and appointments, each
-- with a chart over time.
--
--   companies.status     active, paused or completed (inactive becomes paused)
--   clients_totals()     the active clients' leads and appointments, counted
--                        by call result as a client's own page counts them
--   clients_chart()      leads and appointments developed for active clients,
--                        by the day (and by the hour for a single day)
--
-- A client's time zone, start date and end date were already columns
-- (timezone_id, subscription_start, subscription_end): the form now fills them.
--
-- Safe to run again.

-- --- Status: Active, Paused, Completed --------------------------------------
-- 'inactive' stays allowed until the app that still offers it is replaced.
alter table public.companies drop constraint if exists companies_status_check;
update public.companies set status = 'paused' where status = 'inactive';
alter table public.companies add constraint companies_status_check
  check (status in ('active', 'paused', 'completed', 'inactive'));

-- --- The active clients' leads and appointments, by call result -------------
-- Runs as the person asking: Row Level Security hides what is deleted, and
-- staff see every client.
create or replace function public.clients_totals()
returns table (leads_active bigint, leads_resolved bigint, appointments bigint, invalid_appointments bigint)
language sql stable security invoker set search_path = public as $$
  select count(*) filter (where c.stage = 'appt' and c.viable),
         count(*) filter (where c.stage = 'appt' and not c.viable),
         count(*) filter (where c.effect in ('appointment', 'confirm')),
         count(*) filter (where c.effect = 'appointment_invalid')
    from public.lead_classes c
    join public.projects p on p.id = c.project_id
    join public.companies co on co.id = p.company_id
   where co.status = 'active';
$$;
revoke execute on function public.clients_totals() from public, anon;
grant execute on function public.clients_totals() to authenticated;

-- --- Leads and appointments developed for active clients, over time ---------
-- What the team's production chart counts (a lead or an appointment paid
-- for, not charged back), for the projects of active clients. A manager's
-- own pay events are all Row Level Security shows them, so this reads with
-- the database's rights, for administrators and managers only, and leaves
-- deleted clients and projects out itself.
create or replace function public.clients_chart(p_from date, p_to date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz text := public.business_tz();
  v_lo timestamptz;
  v_hi timestamptz;
  v    jsonb;
begin
  if not public.is_manager() then
    raise exception 'Only administrators and managers see every client''s production' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then
    raise exception 'Choose up to two years' using errcode = '22023';
  end if;
  v_lo := p_from::timestamp at time zone v_tz;
  v_hi := (p_to + 1)::timestamp at time zone v_tz;

  with ev as (
    select (pe.created_at at time zone v_tz)::date as d, extract(hour from pe.created_at at time zone v_tz)::int as h, pe.kind
      from public.pay_events pe
      join public.projects p on p.id = pe.project_id and p.deleted_at is null
      join public.companies co on co.id = p.company_id and co.deleted_at is null and co.status = 'active'
     where pe.kind in ('lead', 'appointment') and not pe.is_chargeback
       and pe.created_at >= v_lo and pe.created_at < v_hi
  )
  select jsonb_build_object(
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', d, 'leads', l, 'appts', a) order by d)
        from (select d, count(*) filter (where kind = 'lead') as l, count(*) filter (where kind = 'appointment') as a
                from ev group by d) q), '[]'::jsonb),
    'hours', case when p_from = p_to then coalesce((
      select jsonb_agg(jsonb_build_object('hour', h, 'leads', l, 'appts', a) order by h)
        from (select h, count(*) filter (where kind = 'lead') as l, count(*) filter (where kind = 'appointment') as a
                from ev group by h) q), '[]'::jsonb) end)
  into v;
  return v;
end $$;
revoke execute on function public.clients_chart(date, date) from public, anon;
grant execute on function public.clients_chart(date, date) to authenticated;

-- ==============================================================================================================
-- 20261108100000_agency_group_explorer.sql
-- ==============================================================================================================

-- The Lead Explorer by agency group (Sean, Oct 2026): a criterion for the
-- carrier group a lead's client belongs to (companies.agency_group_id), with
-- the group on each row for the list and the CSV.
--
--   lead_explore()          criteria.groups (insurance company ids): leads
--                           whose client is in one of them; each row carries
--                           agency_group, its client's group by name
--   lead_explore_options()  groups: the agency groups clients are in, with
--                           how many clients each has
--
-- Each is as it was but for that. Run after 20261105100000 (the column).
--
-- Safe to run again.

CREATE OR REPLACE FUNCTION public.lead_explore(criteria jsonb DEFAULT '{}'::jsonb, page integer DEFAULT 1, per_page integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with c as (
    select
      array(select jsonb_array_elements_text(coalesce(criteria->'sic',       '[]'::jsonb)))          as sic,
      array(select jsonb_array_elements_text(coalesce(criteria->'states',    '[]'::jsonb)))          as states,
      array(select jsonb_array_elements_text(coalesce(criteria->'zips',      '[]'::jsonb)))          as zips,
      array(select jsonb_array_elements_text(coalesce(criteria->'counties',  '[]'::jsonb)))          as counties,
      array(select jsonb_array_elements_text(coalesce(criteria->'statuses',  '[]'::jsonb)))          as statuses,
      array(select (jsonb_array_elements_text(coalesce(criteria->'months',   '[]'::jsonb)))::int)    as months,
      array(select (jsonb_array_elements_text(coalesce(criteria->'clients',  '[]'::jsonb)))::bigint) as clients,
      array(select (jsonb_array_elements_text(coalesce(criteria->'groups',   '[]'::jsonb)))::bigint) as groups,
      array(select jsonb_array_elements_text(coalesce(criteria->'carriers',  '[]'::jsonb)))          as carriers,
      array(select (jsonb_array_elements_text(coalesce(criteria->'reps',     '[]'::jsonb)))::bigint) as reps,
      public.search_patterns(public.search_words(criteria->>'q'))    as pats,
      public.search_lead_pattern(public.search_words(criteria->>'q')) as first_pat
  ),
  carrier_keys as (
    select coalesce(array_agg(distinct k) filter (where k is not null), '{}') as keys
      from (
        select public.carrier_key(v) as k from c, unnest(c.carriers) v where v !~ '^[0-9]+$'
        union all
        select public.carrier_key(a.name) from public.agencies a, c
         where a.id::text = any(array(select v from unnest(c.carriers) v where v ~ '^[0-9]{1,18}$'))
      ) t
  ),
  m as (
    select l.id, l.company_name, l.contact_name, l.contact_title, l.phone, l.contact_mobile, l.email,
           l.decision_maker, l.dm_title, l.dm_phone, l.dm_mobile, l.dm_email,
           l.contact2_name, l.contact2_title, l.contact2_phone, l.contact2_mobile, l.contact2_email, l.producer_name,
           l.city, l.state, l.zip, l.county, l.sic_code, l.lead_date,
           ins.ultimate_xdate,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name, grp.name as agency_group,
           coalesce(ag.name, nullif(btrim(ins.agency_name), '')) as carrier_name,
           st.code as status_code, st.name as status_name,
           nullif(concat_ws(' ', u.first_name, u.last_name), '') as rep_name
      from public.leads l
      cross join c
      cross join carrier_keys ck
      left join public.insurance_details ins on ins.lead_id = l.id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies grp on grp.id = co.agency_group_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.lead_statuses st on st.id = l.status_id
      left join public.users u      on u.id  = l.assigned_user_id
     where (cardinality(c.sic)      = 0 or l.sic_code         = any(c.sic))
       and (cardinality(c.states)   = 0 or l.state            = any(c.states))
       and (cardinality(c.zips)     = 0 or left(l.zip, 5)     = any(c.zips))
       and (cardinality(c.counties) = 0 or l.county           = any(c.counties))
       and (cardinality(c.statuses) = 0 or st.code            = any(c.statuses))
       and (cardinality(c.clients)  = 0 or co.id              = any(c.clients))
       and (cardinality(c.groups)   = 0 or co.agency_group_id = any(c.groups))
       and (cardinality(c.carriers) = 0 or public.carrier_key(coalesce(ag.name, ins.agency_name)) = any(ck.keys))
       and (cardinality(c.reps)     = 0 or l.assigned_user_id = any(c.reps))
       and (cardinality(c.months)   = 0 or extract(month from coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate,
              ins.health_xdate, ins.dental_xdate, ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)))::int = any(c.months))
       -- The longest word first, which the trigram index can answer; then every word.
       and (cardinality(c.pats)     = 0 or (l.search_text like c.first_pat and l.search_text like all (c.pats)))
  ),
  win as (
    select * from m
     order by lead_date desc nulls last, id desc
     limit greatest(least(coalesce(per_page, 10), 10000), 1)
    offset least(greatest(coalesce(page, 1) - 1, 0)::bigint * greatest(least(coalesce(per_page, 10), 10000), 1), 1000000000)
  )
  select jsonb_build_object(
    'total',    (select count(*) from m),
    'rows',     (select coalesce(jsonb_agg(to_jsonb(win)), '[]'::jsonb) from win),
    'by_client', (select coalesce(jsonb_agg(jsonb_build_object('id', t.client_id, 'label', coalesce(t.client_name, 'Unassigned'), 'count', t.n)
                                            order by t.n desc, coalesce(t.client_name, 'zzz')), '[]'::jsonb)
                    from (select client_id, client_name, count(*) as n from m group by client_id, client_name) t),
    'by_state',  (select coalesce(jsonb_agg(jsonb_build_object('label', coalesce(t.state, '—'), 'count', t.n)
                                            order by t.n desc, coalesce(t.state, 'zz')), '[]'::jsonb)
                    from (select state, count(*) as n from m group by state) t),
    'by_month',  (select coalesce(jsonb_agg(jsonb_build_object('month', t.mon, 'label', to_char(to_date(t.mon::text, 'MM'), 'Mon'), 'count', t.n)
                                            order by t.mon), '[]'::jsonb)
                    from (select extract(month from renewal_date)::int as mon, count(*) as n
                            from m where renewal_date is not null group by 1) t),
    'by_industry', (select coalesce(jsonb_agg(jsonb_build_object('code', t.sic_code, 'label', coalesce(s.description, t.sic_code, '—'), 'count', t.n)
                                              order by t.n desc), '[]'::jsonb)
                      from (select sic_code, count(*) as n from m group by sic_code) t
                      left join public.sic_codes s on s.code = t.sic_code),
    'by_status', (select coalesce(jsonb_agg(jsonb_build_object('code', t.status_code, 'label', coalesce(t.status_name, '—'), 'count', t.n)
                                            order by t.n desc), '[]'::jsonb)
                    from (select status_code, status_name, count(*) as n from m group by status_code, status_name) t),
    'clients_touched', (select count(distinct client_id) from m where client_id is not null),
    'with_xdate',      (select count(*) from m where renewal_date is not null)
  );
$function$;

CREATE OR REPLACE FUNCTION public.lead_explore_options()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'industries', (select coalesce(jsonb_agg(jsonb_build_object('value', t.sic_code, 'label', coalesce(s.description, t.sic_code), 'count', t.n)
                                             order by t.n desc), '[]'::jsonb)
                     from (select sic_code, count(*) as n from public.leads where sic_code is not null group by sic_code) t
                     left join public.sic_codes s on s.code = t.sic_code),
    'states',     (select coalesce(jsonb_agg(jsonb_build_object('value', t.state, 'label', t.state, 'count', t.n)
                                             order by t.state), '[]'::jsonb)
                     from (select state, count(*) as n from public.leads where state is not null group by state) t),
    'counties',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.county, 'label', t.county, 'count', t.n)
                                             order by t.county), '[]'::jsonb)
                     from (select county, count(*) as n from public.leads where county is not null group by county) t),
    'statuses',   (select coalesce(jsonb_agg(jsonb_build_object('value', code, 'label', name) order by id), '[]'::jsonb)
                     from public.lead_statuses),
    'clients',    (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', name) order by name), '[]'::jsonb)
                     from public.companies),
    'groups',     (select coalesce(jsonb_agg(jsonb_build_object('value', g.id, 'label', g.name, 'count', t.n) order by g.name), '[]'::jsonb)
                     from (select agency_group_id, count(*) as n from public.companies where agency_group_id is not null group by 1) t
                     join public.agencies g on g.id = t.agency_group_id),
    'carriers',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.k, 'label', t.label, 'count', t.n) order by t.k), '[]'::jsonb)
                     from (select k, (array_agg(label order by rec desc, label))[1] as label, sum(n)::bigint as n
                             from (select public.carrier_key(a.name) as k, btrim(a.name) as label, true as rec, 0 as n
                                     from public.agencies a
                                   union all
                                   select public.carrier_key(coalesce(ag.name, ins.agency_name)), btrim(coalesce(ag.name, ins.agency_name)), false, 1
                                     from public.leads l
                                     left join public.agencies ag on ag.id = l.agency_id
                                     left join public.insurance_details ins on ins.lead_id = l.id) x
                            where k is not null
                            group by k) t),
    'reps',       (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', nullif(concat_ws(' ', first_name, last_name), '')) order by first_name, last_name), '[]'::jsonb)
                     from public.users where role in ('admin', 'manager', 'agent'))
  );
$function$;

-- ==============================================================================================================
-- 20261109100000_lead_page_rework.sql
-- ==============================================================================================================

-- The lead page as Sean laid it out (Oct 2026).
--
--   1. The Business tab's details: the location building (owned or leased,
--      its age, stories and acres), employees full-time and part-time,
--      sub-contractors as a share, the kinds of vehicles and how far they
--      travel. Locations, employees, autos, professionals and covered
--      employees were already columns.
--   2. Where a name stands is its call result: the reports count leads by
--      call result, not by the old system's statuses.
--   3. A hot lead with nobody on the appointment project to take it: the
--      administrators are told (it went to nobody, and nobody heard).
--   4. send_lead(): hand a lead to another manager with a note and a time to
--      call; they are told once, and a call-back reminder is set for them.
--   5. Policy files: a private bucket for files kept with a lead, who may add
--      and open them, and who hears of a new one.
--
-- Safe to run again.

-- --- 1. The Business tab ----------------------------------------------------
alter table public.leads
  add column if not exists location_ownership text check (location_ownership in ('own', 'lease')),
  add column if not exists building_age integer check (building_age between 0 and 500),
  add column if not exists building_stories integer check (building_stories between 0 and 300),
  add column if not exists building_acres numeric(10, 2) check (building_acres >= 0 and building_acres < 100000),
  add column if not exists employees_full_time integer check (employees_full_time between 0 and 1000000),
  add column if not exists employees_part_time integer check (employees_part_time between 0 and 1000000),
  add column if not exists subcontractors_pct numeric(5, 2) check (subcontractors_pct between 0 and 100),
  add column if not exists auto_types text[] check (auto_types <@ array['cars', 'vans', 'delivery_trucks', 'big_rigs', 'tow_trucks']::text[]),
  add column if not exists travel_radius text check (travel_radius in ('25', '50', '100', '250', '300', '500+'));

comment on column public.leads.location_ownership is 'The location building: own or lease.';
comment on column public.leads.subcontractors_pct is 'Sub-contractors, as a % of the work force.';
comment on column public.leads.auto_types is 'Kinds of vehicles: cars, vans, delivery_trucks, big_rigs, tow_trucks.';
comment on column public.leads.travel_radius is 'How far the vehicles travel, in miles: 25, 50, 100, 250, 300 or 500+.';

-- --- 2. Reports by call result ----------------------------------------------
CREATE OR REPLACE FUNCTION public.report_stats()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with z as (
    select public.business_tz() as tz
  ), l as (
    select state, status_id, result_id, to_char(coalesce(lead_date, created_at) at time zone z.tz, 'YYYY-MM') as ym from public.leads, z
  ), a as (
    select status_id, to_char(appt_date, 'YYYY-MM') as ym from public.appointments where invalid_at is null
  ), f as (
    select rating, to_char(created_at at time zone z.tz, 'YYYY-MM') as ym from public.feedback, z where rating is not null
  ), months as (
    select i, date_trunc('month', now() at time zone z.tz) - (i * interval '1 month') as m
      from generate_series(0, 5) as i, z
  )
  select jsonb_build_object(
    'leads',          (select count(*) from l),
    'appts',          (select count(*) from a),
    'projects',       (select count(*) from public.projects),
    'held',           (select count(*) from a join public.appointment_statuses s on s.id = a.status_id where s.name = 'Held'),
    'ratings',        (select jsonb_build_object('count', count(rating), 'avg', coalesce(avg(rating), 0)) from f),
    -- Where the names stand, by call result (by name: the two stages share some).
    'by_status',      (select coalesce(jsonb_object_agg(c.name, c.n), '{}'::jsonb)
                         from (select r.name, count(*) as n from l join public.call_results r on r.id = l.result_id group by r.name) c),
    'by_state',       (select coalesce(jsonb_agg(jsonb_build_array(t.state, t.n) order by t.n desc, t.state), '[]'::jsonb)
                         from (select state, count(*) as n from l where state is not null group by state order by n desc, state limit 8) t),
    'appt_by_status', (select coalesce(jsonb_object_agg(s.name, c.n), '{}'::jsonb)
                         from (select status_id, count(*) as n from a group by status_id) c
                         join public.appointment_statuses s on s.id = c.status_id),
    'months',         (select jsonb_agg(jsonb_build_object(
                          'key',    to_char(m.m, 'YYYY-MM'),
                          'label',  to_char(m.m, 'Mon'),
                          'leads',  (select count(*) from l where l.ym = to_char(m.m, 'YYYY-MM')),
                          'appts',  (select count(*) from a where a.ym = to_char(m.m, 'YYYY-MM')),
                          'rating', (select round(avg(f.rating), 1) from f where f.ym = to_char(m.m, 'YYYY-MM'))
                        ) order by m.i desc) from months m)
  );
$function$;

-- --- 3. A hot lead with nobody to take it -----------------------------------
-- A new lead goes to the appointment manager on the appointment project with
-- the fewest names. With nobody on that project it went to nobody, and
-- nobody heard. Now the administrators do. As it was but for that.
CREATE OR REPLACE FUNCTION public.record_call_result(p_lead_id bigint, p_result_id bigint, p_notes text DEFAULT NULL::text, p_appointment jsonb DEFAULT NULL::jsonb, p_corrected_xdate date DEFAULT NULL::date, p_ultimate_xdate date DEFAULT NULL::date, p_client_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me       bigint := public.app_user_id();
  v_role     text   := public.app_role();
  v_notes    text   := nullif(btrim(coalesce(p_notes, '')), '');
  l          public.leads;
  r          public.call_results;
  a_r        public.call_results;      -- the appointment-stage twin of a DBDev result
  p          public.projects;          -- the project the call is made on
  v_type     text;
  v_appt     public.appointments;
  v_open     public.appointments;      -- an appointment the name already holds, which this one moves
  v_call     bigint;
  v_status   bigint;
  v_rep      bigint;
  v_old_xdate date;
  v_pay      jsonb := '[]'::jsonb;
  v_date     date;
  v_time     text;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff can record call results' using errcode = '42501';
  end if;
  if length(coalesce(v_notes, '')) > 1000 then
    raise exception 'Keep call notes under 1,000 characters' using errcode = '22023';
  end if;
  if length(coalesce(p_client_note, '')) > 2000 then
    raise exception 'Keep the note for the client under 2,000 characters' using errcode = '22023';
  end if;

  select * into l from public.leads where id = p_lead_id for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select * into r from public.call_results where id = p_result_id;
  if not found then
    raise exception 'Unknown call result' using errcode = '22023';
  end if;
  if r.applies_to = 'report' then
    raise exception '% is recorded automatically, not from a call', r.name using errcode = '22023';
  end if;

  select * into p from public.projects where id = l.project_id;
  if not found then
    raise exception 'This name is not in a project yet' using errcode = '22023';
  end if;
  v_type := public.project_type_code(p.id);

  -- An appointment follow-up acts on the name's open appointment, recorded
  -- against the stage that appointment was set at so each project counts it.
  if r.applies_to = 'appointment' then
    select * into v_appt from public.appointments
     where lead_id = l.id and invalid_at is null
     order by appt_create_date desc, id desc
     limit 1
     for update;
    if not found then
      raise exception 'This name has no appointment to %', case r.effect when 'confirm' then 'confirm' else 'mark invalid' end
        using errcode = '22023';
    end if;
    if r.effect = 'confirm' and v_appt.confirmed_at is not null then
      raise exception 'This appointment is already confirmed' using errcode = '22023';
    end if;
    select * into r from public.call_results
     where name = r.name and project_type = case coalesce(v_appt.set_stage, l.stage) when 'dbdev' then 'DBDV' else 'APPT' end;
  elsif r.project_type <> v_type then
    raise exception '% is not a result for % projects', r.name,
      case v_type when 'DBDV' then 'database-development' else 'appointment' end using errcode = '22023';
  end if;

  if v_role <> 'admin'
     and l.assigned_user_id is distinct from v_me
     and not exists (select 1 from public.project_assignments pa where pa.project_id = l.project_id and pa.ae_user_id = v_me)
     and not (r.applies_to = 'appointment' and v_appt.user_id = v_me) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;

  -- The call itself.
  insert into public.call_records (lead_id, project_id, user_id, call_result, notes, result_id, stage, call_date)
  values (l.id, l.project_id, v_me, r.name, v_notes, r.id, l.stage, now())
  returning id into v_call;

  select id into v_status from public.lead_statuses where code = r.status_code;

  update public.leads set
    result_id        = r.id,
    call_result_dbdv = case when r.project_type = 'DBDV' then r.name else call_result_dbdv end,
    call_result_appt = case when r.project_type = 'APPT' then r.name
                            when r.effect = 'appointment_invalid' and stage = 'appt' then r.name
                            else call_result_appt end,
    call_weight      = call_weight + case when r.applies_to = 'name' then 1 else 0 end,
    date_last_worked = now(),
    status_id        = coalesce(v_status, status_id),
    resolved_at      = case when r.viable then null else coalesce(resolved_at, now()) end,
    assigned_user_id = case when r.effect = 'pending' then null else assigned_user_id end
  where id = l.id;

  -- What the result does.
  if r.effect in ('promote', 'appointment') then
    -- A name becomes a Lead or an Appointment only with its renewal date
    -- confirmed: the Ultimate X-Date, entered (or corrected) with this result,
    -- or already on the record. A date on a policy line alone is a potential
    -- renewal the account manager has not confirmed yet.
    if p_ultimate_xdate is not null then
      update public.insurance_details set ultimate_xdate = p_ultimate_xdate where lead_id = l.id;
      if not found then
        insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_ultimate_xdate);
      end if;
    end if;
    if not exists (select 1 from public.insurance_details i where i.lead_id = l.id and i.ultimate_xdate is not null) then
      raise exception 'Enter the Ultimate X-Date: a name becomes a Lead or an Appointment only with its renewal date'
        using errcode = '22023';
    end if;

    -- What the client is told, with the lead sheet: written as the name is
    -- set (given empty, it is cleared). The call notes stay internal.
    if p_client_note is not null then
      update public.leads set client_note = nullif(btrim(p_client_note), '') where id = l.id;
    end if;

    if r.effect = 'appointment' then
      v_date := nullif(p_appointment->>'date', '')::date;
      v_time := nullif(btrim(coalesce(p_appointment->>'time', '')), '');
      if v_date is null then
        raise exception 'Choose the appointment date' using errcode = '22023';
      end if;
      if v_date < current_date - 1 then
        raise exception 'The appointment date has passed' using errcode = '22023';
      end if;
      if v_time is null then
        raise exception 'Choose the appointment time' using errcode = '22023';
      end if;
      if v_time !~* '^\d{1,2}:\d{2}\s?(AM|PM)$' then
        raise exception 'Give the time like 9:30 AM' using errcode = '22023';
      end if;
    end if;

    -- A name that already holds an appointment still to come, or still
    -- waiting for QA, has that one moved: one appointment, paid once.
    -- (Recording the result again is how a rep reschedules from the sheet.)
    -- One that failed QA does not count: the rep sets a real one instead.
    if r.effect = 'appointment' then
      select * into v_open from public.appointments
       where lead_id = l.id and invalid_at is null and qa_status is distinct from 'failed'
         and (qa_status = 'pending' or appt_date >= (now() at time zone public.business_tz())::date)
       order by appt_create_date desc, id desc
       limit 1
       for update;
    end if;

    if v_open.id is not null then
      update public.appointments set
        appt_date    = v_date,
        appt_time    = v_time,
        duration_min = coalesce(nullif(p_appointment->>'duration', '')::int, duration_min),
        rep_name     = coalesce(nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), rep_name),
        status_id    = case when status_id = (select id from public.appointment_statuses where name = 'Scheduled')
                             and (appt_date, coalesce(appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                            then (select id from public.appointment_statuses where name = 'Rescheduled')
                            else status_id end,
        status_update_date = now()
      where id = v_open.id
      returning * into v_appt;
      -- "Moved" only when the day or the time changed.
      update public.call_records set
        appointment_id = v_appt.id,
        notes = case when (v_open.appt_date, coalesce(v_open.appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                     then concat_ws(E'\n', notes, 'Appointment moved from ' || to_char(v_open.appt_date, 'Mon FMDD')
                            || coalesce(' ' || v_open.appt_time, '') || ' to ' || to_char(v_date, 'Mon FMDD') || coalesce(' ' || v_time, ''))
                     else notes end
      where id = v_call;
    else

      -- From DBDev, the name moves to the linked appointment project.
      if v_type = 'DBDV' then
        if p.appt_project_id is null then
          raise exception 'Link % to an appointment project before promoting its names', p.name using errcode = '22023';
        end if;
        select * into a_r from public.call_results
         where project_type = 'APPT' and name = case r.effect when 'promote' then 'Lead-No Contact' else r.name end;
        -- A new lead goes to the appointment manager with the fewest names; an
        -- appointment stays with the rep who set it, who confirms it.
        v_rep := case r.effect when 'promote' then public.least_loaded_rep(p.appt_project_id) else v_me end;
        update public.leads set
          stage             = 'appt',
          project_id        = p.appt_project_id,
          source_project_id = coalesce(source_project_id, l.project_id),
          dbdv_user_id      = v_me,
          assigned_user_id  = v_rep,
          result_id         = a_r.id,
          call_result_appt  = a_r.name,
          call_weight       = 0,
          promoted_at       = now(),
          resolved_at       = case when a_r.viable then null else now() end
        where id = l.id;
        -- Nobody is on the appointment project to take a new lead: the administrators
        -- hear of it, so a hot lead never waits unseen (Sean, Oct 2026).
        if r.effect = 'promote' and v_rep is null then
          perform public.notify_users(
            array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null),
            'lead',
            left(case when r.status_code = 'hot' then 'Hot lead waiting: ' else 'Lead waiting: ' end || coalesce(l.company_name, 'a lead'), 160),
            'Nobody is assigned to ' || coalesce((select pp.name from public.projects pp where pp.id = p.appt_project_id), 'its appointment project')
              || ' to take it. Add an appointment manager to that project, or send the lead to one.',
            '/leads/' || l.id,
            case when r.status_code = 'hot' then 'hot_lead' else 'lead_assigned' end);
        end if;
      end if;

      if r.effect = 'appointment' then
        insert into public.appointments
          (lead_id, user_id, rep_name, appt_date, appt_time, duration_min, status_id, list_source,
           call_result_dbdv, project_id, set_project_id, set_stage, call_record_id, qa_status)
        values
          (l.id, v_me, nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), v_date, v_time,
           coalesce(nullif(p_appointment->>'duration', '')::int, 30),
           (select id from public.appointment_statuses where name = 'Scheduled'),
           l.list_source,
           case when v_type = 'DBDV' then r.name end,
           coalesce(p.appt_project_id, p.id), p.id, l.stage, v_call, 'pending')
        returning * into v_appt;
        update public.leads set appt_created_date = now() where id = l.id;
        update public.call_records set appointment_id = v_appt.id where id = v_call;
      end if;

      v_pay := v_pay || public.pay(v_me, p.id, r.pay_kind, l.id, v_appt.id, v_call);

    end if;

  elsif r.effect = 'confirm' then
    update public.appointments set
      status_id    = (select id from public.appointment_statuses where name = 'Confirmed'),
      confirmed_at = now(),
      confirmed_by = v_me,
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := v_pay || public.pay(v_me, coalesce(v_appt.set_project_id, p.id), 'confirmation', l.id, v_appt.id, v_call);
    -- The client hears now only if QA has already let them see it.
    if coalesce(v_appt.qa_status, 'passed') = 'passed' then
      perform public.notify_client_appointment(v_appt.id, true);
    end if;

  elsif r.effect = 'appointment_invalid' then
    update public.appointments set
      invalid_at = now(),
      status_id  = (select id from public.appointment_statuses where name = 'Invalid'),
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := public.charge_back(l.id, v_appt.id, array['appointment', 'confirmation'], v_call, 'Appointment invalid');

  elsif r.effect = 'lead_invalid' then
    update public.leads set call_result_dbdv = 'Lead-Invalid' where id = l.id and source_project_id is not null;
    v_pay := public.charge_back(l.id, null, array['lead'], v_call, 'Lead invalid');
    -- No record of the original payment (an older lead): charge the developer at today's rate.
    if jsonb_array_length(v_pay) = 0 and l.dbdv_user_id is not null and l.source_project_id is not null then
      insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
      select l.dbdv_user_id, l.source_project_id, l.id, v_call, 'lead', -sp.lead_rate, 'Lead invalid (no original payment on record)', v_me
        from public.projects sp where sp.id = l.source_project_id;
      v_pay := jsonb_build_array(jsonb_build_object('user_id', l.dbdv_user_id, 'kind', 'lead',
                 'amount', -(select lead_rate from public.projects where id = l.source_project_id)));
    end if;
    if l.dbdv_user_id is not null then
      perform public.notify_users(
        array[l.dbdv_user_id], 'lead', 'Lead marked invalid: ' || coalesce(l.company_name, 'a lead'),
        concat_ws(' · ', 'Charged back on your production report', 'marked by ' || public.actor_name()),
        '/leads/' || l.id, 'lead_invalid');
    end if;

  elsif r.effect = 'correct_xdate' then
    if p_corrected_xdate is null then
      raise exception 'Enter the corrected renewal date' using errcode = '22023';
    end if;
    v_old_xdate := public.lead_renewal_date(l.id);
    -- The corrected date becomes the lead's ultimate X-date, which is its
    -- renewal; the dates on the individual policy lines are left as recorded.
    update public.insurance_details set ultimate_xdate = p_corrected_xdate where lead_id = l.id;
    if not found then
      insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_corrected_xdate);
    end if;
    update public.leads set original_xdate = coalesce(original_xdate, v_old_xdate) where id = l.id;
    update public.call_records
       set notes = concat_ws(E'\n', notes, 'Renewal corrected from '
                   || coalesce(to_char(v_old_xdate, 'FMMonth YYYY'), 'none') || ' to ' || to_char(p_corrected_xdate, 'FMMonth YYYY'))
     where id = v_call;
  end if;

  -- What was said on the call joins the lead's internal notes, their running
  -- history (as the old system kept them), stamped as the rep wrote it.
  if v_notes is not null then
    insert into public.lead_notes (lead_id, notes)
    select l.id, btrim(c.notes) from public.call_records c where c.id = v_call
    on conflict (lead_id) do update
      set notes = concat_ws(E'\n', nullif(btrim(public.lead_notes.notes), ''), excluded.notes);
  end if;

  select * into l from public.leads where id = l.id;
  return jsonb_build_object(
    'call_record_id', v_call,
    'lead_id',        l.id,
    'result',         r.name,
    'stage',          l.stage,
    'project_id',     l.project_id,
    'promoted',       l.project_id is distinct from p.id,
    'on_list',        (select viable and callable from public.call_results where id = l.result_id) and l.assigned_user_id is not null,
    'appointment_id', v_appt.id,
    'rescheduled',    v_open.id is not null,
    'pay',            v_pay);
end $function$;

-- --- 4. Sending a lead to someone to call -----------------------------------
-- An administrator or manager hands a lead to another manager (or agent)
-- with a note and, if they like, a time to call: it is theirs to work, they
-- are told once (with the note), and a call-back reminder for them is set.
CREATE OR REPLACE FUNCTION public.tg_notify_leads_assigned()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
begin
  -- A lead sent to someone with a note (send_lead()) says so itself, once.
  if current_setting('lighthouse.quiet_assign', true) = 'on' then
    return null;
  end if;
  if tg_op = 'INSERT' then
    for r in
      select n.assigned_user_id as uid, n.project_id as pid, coalesce(st.code = 'hot', false) as hot, count(*) as n,
             (array_agg(n.id order by n.id))[1] as lead_id,
             (array_agg(n.company_name order by n.id))[1] as lead_name
        from new_rows n
        left join public.lead_statuses st on st.id = n.status_id
       where n.assigned_user_id is not null
       group by 1, 2, 3
    loop
      perform public.notify_lead_assignment(r.uid, r.hot, r.n, r.lead_id, r.lead_name, r.pid);
    end loop;
  else
    for r in
      select n.assigned_user_id as uid, n.project_id as pid, coalesce(st.code = 'hot', false) as hot, count(*) as n,
             (array_agg(n.id order by n.id))[1] as lead_id,
             (array_agg(n.company_name order by n.id))[1] as lead_name
        from new_rows n
        join old_rows o on o.id = n.id
        left join public.lead_statuses st on st.id = n.status_id
       where n.assigned_user_id is not null
         and n.assigned_user_id is distinct from o.assigned_user_id
         -- The rep who set an appointment keeps it; that is not a new assignment.
         and n.assigned_user_id is distinct from public.app_user_id()
       group by 1, 2, 3
    loop
      perform public.notify_lead_assignment(r.uid, r.hot, r.n, r.lead_id, r.lead_name, r.pid);
    end loop;
  end if;
  return null;
end $function$;

drop function if exists public.send_lead(bigint, bigint, text, timestamptz, boolean);
create or replace function public.send_lead(p_lead bigint, p_to bigint, p_note text default null, p_date date default null, p_time text default null, p_assign boolean default true)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  v_lead public.leads;
  v_to   public.users;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_tz   text := public.business_tz();
  v_time time;
  v_at   timestamptz;
begin
  if v_me is null or public.app_role() not in ('admin', 'manager') then
    raise exception 'Only administrators and managers send a lead to someone' using errcode = '42501';
  end if;
  select * into v_lead from public.leads where id = p_lead and deleted_at is null;
  if v_lead.id is null then
    raise exception 'That lead is no longer there' using errcode = 'P0002';
  end if;
  select * into v_to from public.users
   where id = p_to and status = 'active' and deleted_at is null and role in ('admin', 'manager', 'agent');
  if v_to.id is null then
    raise exception 'Choose someone on the team to send it to' using errcode = '22023';
  end if;
  if v_to.id = v_me then
    raise exception 'Choose someone other than yourself' using errcode = '22023';
  end if;
  if length(v_note) > 1000 then
    raise exception 'Keep the note under 1,000 characters' using errcode = '22023';
  end if;
  -- A time to call, on the business's clock, as a call-back reminder reads one.
  if p_date is not null or nullif(btrim(coalesce(p_time, '')), '') is not null then
    begin
      v_time := to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time;
    exception when others then
      raise exception 'Choose a time like 2:00 PM' using errcode = '22023';
    end;
    if p_date is null or v_time is null then
      raise exception 'Choose both the day and the time to call' using errcode = '22023';
    end if;
    v_at := (p_date + v_time) at time zone v_tz;
    if v_at < now() - interval '1 minute' then
      raise exception 'That time has already passed' using errcode = '22023';
    end if;
  end if;

  if p_assign and v_lead.assigned_user_id is distinct from v_to.id then
    perform set_config('lighthouse.quiet_assign', 'on', true);
    update public.leads set assigned_user_id = v_to.id where id = v_lead.id;
    perform set_config('lighthouse.quiet_assign', 'off', true);
  end if;
  if v_at is not null then
    insert into public.reminders (lead_id, user_id, remind_at, note)
    values (v_lead.id, v_to.id, v_at, left(coalesce(v_note, 'Sent by ' || coalesce(public.actor_name(), 'a manager')), 300));
  end if;
  perform public.notify_users(
    array[v_to.id], 'lead',
    left('Lead to call: ' || coalesce(v_lead.company_name, 'a lead'), 160),
    left(concat_ws(' · ',
      'From ' || coalesce(public.actor_name(), 'a manager'),
      case when p_assign then 'It is yours to work' end,
      case when v_at is not null then 'Call ' || to_char(v_at at time zone v_tz, 'Dy MM/DD/YYYY FMHH12:MI AM') end,
      v_note), 1000),
    '/leads/' || v_lead.id,
    'lead_assigned');
  return jsonb_build_object('lead', v_lead.id, 'to', v_to.id, 'assigned', p_assign, 'remind_at', v_at);
end $$;
revoke execute on function public.send_lead(bigint, bigint, text, date, text, boolean) from public, anon;
grant execute on function public.send_lead(bigint, bigint, text, date, text, boolean) to authenticated;

-- --- 5. Policy files on a lead ------------------------------------------------
-- Files a prospect sends (policies, dec pages, photos), kept with the lead:
-- in a private bucket under lead/<lead id>/, with a documents row each. Anyone
-- who can see the lead (administrators, managers, agents, and the client's
-- own people for their projects' leads) adds and opens them; Row Level
-- Security on leads decides who that is. Deleting one sets the delete flag.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('lead-files', 'lead-files', false, 26214400,
        array['application/pdf', 'image/*', 'text/plain', 'text/csv', 'message/rfc822', 'application/vnd.ms-outlook',
              'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
              'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists lead_files_insert on storage.objects;
create policy lead_files_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'lead-files' and (storage.foldername(name))[1] = 'lead'
              and public.app_user_id() is not null
              and exists (select 1 from public.leads l where l.id::text = (storage.foldername(name))[2]));
drop policy if exists lead_files_read on storage.objects;
create policy lead_files_read on storage.objects for select to authenticated
  using (bucket_id = 'lead-files' and (storage.foldername(name))[1] = 'lead'
         and public.app_user_id() is not null
         and exists (select 1 from public.leads l where l.id::text = (storage.foldername(name))[2]));

-- A file on a lead belongs to the lead's project and client, and to whoever added it.
create or replace function public.tg_documents_from_lead()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.lead_id is not null then
    select l.project_id, p.company_id into new.project_id, new.company_id
      from public.leads l left join public.projects p on p.id = l.project_id
     where l.id = new.lead_id;
  end if;
  -- Whoever is signed in added it; the server's own role keeps what it was given.
  new.uploaded_by := coalesce(public.app_user_id(), new.uploaded_by);
  return new;
end $$;
revoke execute on function public.tg_documents_from_lead() from public, anon, authenticated;
drop trigger if exists documents_from_lead on public.documents;
create trigger documents_from_lead before insert on public.documents
  for each row execute function public.tg_documents_from_lead();

-- The client's own people add files to their projects' leads (staff already may).
drop policy if exists documents_lead_insert on public.documents;
create policy documents_lead_insert on public.documents for insert to authenticated
  with check (lead_id is not null
              and storage_path like 'lead/' || lead_id || '/%'
              and exists (select 1 from public.leads l where l.id = lead_id));

-- Who hears of a new file: when the client's people add one, the lead's manager
-- and whoever set its appointment; when staff add one to a lead with an
-- appointment the client can see, the client's people, pointed at the appointment.
create or replace function public.tg_documents_notify()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  l       public.leads;
  a       public.appointments;
  v_role  text;
  v_to    bigint[];
begin
  if new.lead_id is null then
    return null;
  end if;
  select * into l from public.leads where id = new.lead_id;
  select * into a from public.appointments
   where lead_id = new.lead_id and invalid_at is null and deleted_at is null
   order by appt_create_date desc, id desc limit 1;
  select role into v_role from public.users where id = new.uploaded_by;

  if v_role = 'client' then
    v_to := array_remove(array[l.assigned_user_id, a.user_id], null);
    perform public.notify_users(v_to, 'lead',
      left('Policy file added: ' || coalesce(l.company_name, 'a lead'), 160),
      left(new.name || ' · from ' || coalesce(public.actor_name(), 'the client'), 1000),
      '/leads/' || l.id || '?tab=files', null);
  elsif a.id is not null and coalesce(a.qa_status, 'passed') = 'passed' then
    select array_agg(u.id) into v_to from public.users u join public.projects p on p.company_id = u.company_id
     where p.id = l.project_id and u.role = 'client' and u.status = 'active' and u.deleted_at is null;
    perform public.notify_users(coalesce(v_to, '{}'), 'appointment',
      left('Policy file added: ' || coalesce(l.company_name, 'an appointment'), 160),
      left(new.name || ' · for the appointment on ' || to_char(a.appt_date, 'Dy MM/DD/YYYY') || coalesce(' ' || a.appt_time, ''), 1000),
      '/calendar?view=day&d=' || a.appt_date || '&a=' || a.id, null);
  end if;
  return null;
end $$;
revoke execute on function public.tg_documents_notify() from public, anon, authenticated;
drop trigger if exists documents_notify on public.documents;
create trigger documents_notify after insert on public.documents
  for each row execute function public.tg_documents_notify();

-- ==============================================================================================================
-- 20261110100000_business_more_fields.sql
-- ==============================================================================================================

-- More of what a business is, on the lead's Business tab (Sean, Oct 2026):
--
--   annual_payroll      beside sales volume, as written ("$1.2M")
--   dot_number          the US DOT number its vehicles run under
--   cargo               what its vehicles carry, picked from the cargo list
--   claims_3yrs         whether it has had claims in the last three years
--
--   cargo_types         the cargo list administrators load (Settings), for
--                       the Cargo field to pick from. A lead keeps the words
--                       picked, so taking one off the list changes no lead.

alter table public.leads
  add column if not exists annual_payroll text check (char_length(annual_payroll) <= 30),
  add column if not exists dot_number text check (dot_number ~ '^\d{1,10}$'),
  add column if not exists cargo text check (char_length(cargo) <= 100),
  add column if not exists claims_3yrs boolean;

create table if not exists public.cargo_types (
  id         bigint generated always as identity primary key,
  name       text not null check (char_length(btrim(name)) between 1 and 100),
  created_at timestamptz not null default now()
);
create unique index if not exists cargo_types_name on public.cargo_types (lower(name));

-- Readable by any signed-in user, kept by administrators, as the other lookup lists are.
alter table public.cargo_types enable row level security;
drop policy if exists cargo_types_read on public.cargo_types;
create policy cargo_types_read on public.cargo_types for select to authenticated using (true);
drop policy if exists cargo_types_write on public.cargo_types;
create policy cargo_types_write on public.cargo_types for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists mfa_required on public.cargo_types;
create policy mfa_required on public.cargo_types as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.cargo_types;
create policy active_account_required on public.cargo_types as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.cargo_types from anon;
grant select, insert, delete on public.cargo_types to authenticated;
grant all on public.cargo_types to service_role;

-- ==============================================================================================================
-- 20261111100000_explorer_appt_results.sql
-- ==============================================================================================================

-- The Lead Explorer reads leads promoted to appointment projects, by their
-- call results (Sean, Oct 2026). A name still being developed is not a lead
-- yet, whatever renewal dates it carries, so it no longer turns up in the
-- results, the breakdowns or the pickers' counts. The old system's statuses
-- give way to the call result:
--
--   lead_explore          only leads at the appointment stage; criteria
--                         'results' (call result names, "Not called yet" for
--                         none) in place of 'statuses'; each row's result_id,
--                         result_name and result_viable; 'by_result' in place
--                         of 'by_status'
--   lead_explore_options  its pickers' values and counts from those leads;
--                         'results' in place of 'statuses'
--
-- Both are as the local database had them (20261108100000), with only these
-- changes.

CREATE OR REPLACE FUNCTION public.lead_explore(criteria jsonb DEFAULT '{}'::jsonb, page integer DEFAULT 1, per_page integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with c as (
    select
      array(select jsonb_array_elements_text(coalesce(criteria->'sic',       '[]'::jsonb)))          as sic,
      array(select jsonb_array_elements_text(coalesce(criteria->'states',    '[]'::jsonb)))          as states,
      array(select jsonb_array_elements_text(coalesce(criteria->'zips',      '[]'::jsonb)))          as zips,
      array(select jsonb_array_elements_text(coalesce(criteria->'counties',  '[]'::jsonb)))          as counties,
      array(select jsonb_array_elements_text(coalesce(criteria->'results',   '[]'::jsonb)))          as results,
      array(select (jsonb_array_elements_text(coalesce(criteria->'months',   '[]'::jsonb)))::int)    as months,
      array(select (jsonb_array_elements_text(coalesce(criteria->'clients',  '[]'::jsonb)))::bigint) as clients,
      array(select (jsonb_array_elements_text(coalesce(criteria->'groups',   '[]'::jsonb)))::bigint) as groups,
      array(select jsonb_array_elements_text(coalesce(criteria->'carriers',  '[]'::jsonb)))          as carriers,
      array(select (jsonb_array_elements_text(coalesce(criteria->'reps',     '[]'::jsonb)))::bigint) as reps,
      public.search_patterns(public.search_words(criteria->>'q'))    as pats,
      public.search_lead_pattern(public.search_words(criteria->>'q')) as first_pat
  ),
  carrier_keys as (
    select coalesce(array_agg(distinct k) filter (where k is not null), '{}') as keys
      from (
        select public.carrier_key(v) as k from c, unnest(c.carriers) v where v !~ '^[0-9]+$'
        union all
        select public.carrier_key(a.name) from public.agencies a, c
         where a.id::text = any(array(select v from unnest(c.carriers) v where v ~ '^[0-9]{1,18}$'))
      ) t
  ),
  m as (
    select l.id, l.company_name, l.contact_name, l.contact_title, l.phone, l.contact_mobile, l.email,
           l.decision_maker, l.dm_title, l.dm_phone, l.dm_mobile, l.dm_email,
           l.contact2_name, l.contact2_title, l.contact2_phone, l.contact2_mobile, l.contact2_email, l.producer_name,
           l.city, l.state, l.zip, l.county, l.sic_code, l.lead_date,
           ins.ultimate_xdate,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name, grp.name as agency_group,
           coalesce(ag.name, nullif(btrim(ins.agency_name), '')) as carrier_name,
           r.id as result_id, r.name as result_name, r.viable as result_viable,
           nullif(concat_ws(' ', u.first_name, u.last_name), '') as rep_name
      from public.leads l
      cross join c
      cross join carrier_keys ck
      left join public.insurance_details ins on ins.lead_id = l.id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies grp on grp.id = co.agency_group_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.call_results r on r.id = l.result_id
      left join public.users u      on u.id  = l.assigned_user_id
     -- Leads that have been promoted to an appointment project: a name still being developed is not one yet,
     -- whatever renewal dates it carries.
     where l.stage = 'appt'
       and (cardinality(c.sic)      = 0 or l.sic_code         = any(c.sic))
       and (cardinality(c.states)   = 0 or l.state            = any(c.states))
       and (cardinality(c.zips)     = 0 or left(l.zip, 5)     = any(c.zips))
       and (cardinality(c.counties) = 0 or l.county           = any(c.counties))
       and (cardinality(c.results)  = 0 or coalesce(r.name, 'Not called yet') = any(c.results))
       and (cardinality(c.clients)  = 0 or co.id              = any(c.clients))
       and (cardinality(c.groups)   = 0 or co.agency_group_id = any(c.groups))
       and (cardinality(c.carriers) = 0 or public.carrier_key(coalesce(ag.name, ins.agency_name)) = any(ck.keys))
       and (cardinality(c.reps)     = 0 or l.assigned_user_id = any(c.reps))
       and (cardinality(c.months)   = 0 or extract(month from coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate,
              ins.health_xdate, ins.dental_xdate, ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)))::int = any(c.months))
       -- The longest word first, which the trigram index can answer; then every word.
       and (cardinality(c.pats)     = 0 or (l.search_text like c.first_pat and l.search_text like all (c.pats)))
  ),
  win as (
    select * from m
     order by lead_date desc nulls last, id desc
     limit greatest(least(coalesce(per_page, 10), 10000), 1)
    offset least(greatest(coalesce(page, 1) - 1, 0)::bigint * greatest(least(coalesce(per_page, 10), 10000), 1), 1000000000)
  )
  select jsonb_build_object(
    'total',    (select count(*) from m),
    'rows',     (select coalesce(jsonb_agg(to_jsonb(win)), '[]'::jsonb) from win),
    'by_client', (select coalesce(jsonb_agg(jsonb_build_object('id', t.client_id, 'label', coalesce(t.client_name, 'Unassigned'), 'count', t.n)
                                            order by t.n desc, coalesce(t.client_name, 'zzz')), '[]'::jsonb)
                    from (select client_id, client_name, count(*) as n from m group by client_id, client_name) t),
    'by_state',  (select coalesce(jsonb_agg(jsonb_build_object('label', coalesce(t.state, '—'), 'count', t.n)
                                            order by t.n desc, coalesce(t.state, 'zz')), '[]'::jsonb)
                    from (select state, count(*) as n from m group by state) t),
    'by_month',  (select coalesce(jsonb_agg(jsonb_build_object('month', t.mon, 'label', to_char(to_date(t.mon::text, 'MM'), 'Mon'), 'count', t.n)
                                            order by t.mon), '[]'::jsonb)
                    from (select extract(month from renewal_date)::int as mon, count(*) as n
                            from m where renewal_date is not null group by 1) t),
    'by_industry', (select coalesce(jsonb_agg(jsonb_build_object('code', t.sic_code, 'label', coalesce(s.description, t.sic_code, '—'), 'count', t.n)
                                              order by t.n desc), '[]'::jsonb)
                      from (select sic_code, count(*) as n from m group by sic_code) t
                      left join public.sic_codes s on s.code = t.sic_code),
    'by_result', (select coalesce(jsonb_agg(jsonb_build_object('label', t.label, 'count', t.n)
                                            order by t.n desc, t.label), '[]'::jsonb)
                    from (select coalesce(result_name, 'Not called yet') as label, count(*) as n from m group by 1) t),
    'clients_touched', (select count(distinct client_id) from m where client_id is not null),
    'with_xdate',      (select count(*) from m where renewal_date is not null)
  );
$function$;

CREATE OR REPLACE FUNCTION public.lead_explore_options()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'industries', (select coalesce(jsonb_agg(jsonb_build_object('value', t.sic_code, 'label', coalesce(s.description, t.sic_code), 'count', t.n)
                                             order by t.n desc), '[]'::jsonb)
                     from (select sic_code, count(*) as n from public.leads where stage = 'appt' and sic_code is not null group by sic_code) t
                     left join public.sic_codes s on s.code = t.sic_code),
    'states',     (select coalesce(jsonb_agg(jsonb_build_object('value', t.state, 'label', t.state, 'count', t.n)
                                             order by t.state), '[]'::jsonb)
                     from (select state, count(*) as n from public.leads where stage = 'appt' and state is not null group by state) t),
    'counties',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.county, 'label', t.county, 'count', t.n)
                                             order by t.county), '[]'::jsonb)
                     from (select county, count(*) as n from public.leads where stage = 'appt' and county is not null group by county) t),
    'results',    (select coalesce(jsonb_agg(jsonb_build_object('value', t.label, 'label', t.label, 'count', t.n) order by t.n desc, t.label), '[]'::jsonb)
                     from (select coalesce(r.name, 'Not called yet') as label, count(*) as n
                             from public.leads l left join public.call_results r on r.id = l.result_id
                            where l.stage = 'appt' group by 1) t),
    'clients',    (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', name) order by name), '[]'::jsonb)
                     from public.companies),
    'groups',     (select coalesce(jsonb_agg(jsonb_build_object('value', g.id, 'label', g.name, 'count', t.n) order by g.name), '[]'::jsonb)
                     from (select agency_group_id, count(*) as n from public.companies where agency_group_id is not null group by 1) t
                     join public.agencies g on g.id = t.agency_group_id),
    'carriers',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.k, 'label', t.label, 'count', t.n) order by t.k), '[]'::jsonb)
                     from (select k, (array_agg(label order by rec desc, label))[1] as label, sum(n)::bigint as n
                             from (select public.carrier_key(a.name) as k, btrim(a.name) as label, true as rec, 0 as n
                                     from public.agencies a
                                   union all
                                   select public.carrier_key(coalesce(ag.name, ins.agency_name)), btrim(coalesce(ag.name, ins.agency_name)), false, 1
                                     from public.leads l
                                     left join public.agencies ag on ag.id = l.agency_id
                                     left join public.insurance_details ins on ins.lead_id = l.id
                                    where l.stage = 'appt') x
                            where k is not null
                            group by k) t),
    'reps',       (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', nullif(concat_ws(' ', first_name, last_name), '')) order by first_name, last_name), '[]'::jsonb)
                     from public.users where role in ('admin', 'manager', 'agent'))
  );
$function$;

-- ==============================================================================================================
-- 20261113100000_explorer_projects_viable.sql
-- ==============================================================================================================

-- The Lead Explorer (Sean, Oct 2026): a Project criterion, how many of the
-- leads are still viable to call for an appointment, and when each was last
-- worked.
--
--   lead_explore          criteria 'projects' (project ids); each row's
--                         project_id, project_name and last_worked (the later
--                         of its last call and its last change); 'viable', the
--                         matching leads whose call result leaves them viable
--   lead_explore_options  'projects': the projects with leads promoted to
--                         them, each with how many
--
-- Both are as the local database had them (20261111100000), with only these
-- changes.

CREATE OR REPLACE FUNCTION public.lead_explore(criteria jsonb DEFAULT '{}'::jsonb, page integer DEFAULT 1, per_page integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with c as (
    select
      array(select jsonb_array_elements_text(coalesce(criteria->'sic',       '[]'::jsonb)))          as sic,
      array(select jsonb_array_elements_text(coalesce(criteria->'states',    '[]'::jsonb)))          as states,
      array(select jsonb_array_elements_text(coalesce(criteria->'zips',      '[]'::jsonb)))          as zips,
      array(select jsonb_array_elements_text(coalesce(criteria->'counties',  '[]'::jsonb)))          as counties,
      array(select jsonb_array_elements_text(coalesce(criteria->'results',   '[]'::jsonb)))          as results,
      array(select (jsonb_array_elements_text(coalesce(criteria->'months',   '[]'::jsonb)))::int)    as months,
      array(select (jsonb_array_elements_text(coalesce(criteria->'clients',  '[]'::jsonb)))::bigint) as clients,
      array(select (jsonb_array_elements_text(coalesce(criteria->'projects', '[]'::jsonb)))::bigint) as projects,
      array(select (jsonb_array_elements_text(coalesce(criteria->'groups',   '[]'::jsonb)))::bigint) as groups,
      array(select jsonb_array_elements_text(coalesce(criteria->'carriers',  '[]'::jsonb)))          as carriers,
      array(select (jsonb_array_elements_text(coalesce(criteria->'reps',     '[]'::jsonb)))::bigint) as reps,
      public.search_patterns(public.search_words(criteria->>'q'))    as pats,
      public.search_lead_pattern(public.search_words(criteria->>'q')) as first_pat
  ),
  carrier_keys as (
    select coalesce(array_agg(distinct k) filter (where k is not null), '{}') as keys
      from (
        select public.carrier_key(v) as k from c, unnest(c.carriers) v where v !~ '^[0-9]+$'
        union all
        select public.carrier_key(a.name) from public.agencies a, c
         where a.id::text = any(array(select v from unnest(c.carriers) v where v ~ '^[0-9]{1,18}$'))
      ) t
  ),
  m as (
    select l.id, l.company_name, l.contact_name, l.contact_title, l.phone, l.contact_mobile, l.email,
           l.decision_maker, l.dm_title, l.dm_phone, l.dm_mobile, l.dm_email,
           l.contact2_name, l.contact2_title, l.contact2_phone, l.contact2_mobile, l.contact2_email, l.producer_name,
           l.city, l.state, l.zip, l.county, l.sic_code, l.lead_date,
           ins.ultimate_xdate,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name, grp.name as agency_group,
           coalesce(ag.name, nullif(btrim(ins.agency_name), '')) as carrier_name,
           r.id as result_id, r.name as result_name, r.viable as result_viable,
           l.project_id, p.name as project_name,
           -- When it was last called or changed.
           greatest(l.date_last_worked, l.updated_at) as last_worked,
           nullif(concat_ws(' ', u.first_name, u.last_name), '') as rep_name
      from public.leads l
      cross join c
      cross join carrier_keys ck
      left join public.insurance_details ins on ins.lead_id = l.id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies grp on grp.id = co.agency_group_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.call_results r on r.id = l.result_id
      left join public.users u      on u.id  = l.assigned_user_id
     -- Leads that have been promoted to an appointment project: a name still being developed is not one yet,
     -- whatever renewal dates it carries.
     where l.stage = 'appt'
       and (cardinality(c.sic)      = 0 or l.sic_code         = any(c.sic))
       and (cardinality(c.states)   = 0 or l.state            = any(c.states))
       and (cardinality(c.zips)     = 0 or left(l.zip, 5)     = any(c.zips))
       and (cardinality(c.counties) = 0 or l.county           = any(c.counties))
       and (cardinality(c.results)  = 0 or coalesce(r.name, 'Not called yet') = any(c.results))
       and (cardinality(c.clients)  = 0 or co.id              = any(c.clients))
       and (cardinality(c.projects) = 0 or l.project_id       = any(c.projects))
       and (cardinality(c.groups)   = 0 or co.agency_group_id = any(c.groups))
       and (cardinality(c.carriers) = 0 or public.carrier_key(coalesce(ag.name, ins.agency_name)) = any(ck.keys))
       and (cardinality(c.reps)     = 0 or l.assigned_user_id = any(c.reps))
       and (cardinality(c.months)   = 0 or extract(month from coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate,
              ins.health_xdate, ins.dental_xdate, ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)))::int = any(c.months))
       -- The longest word first, which the trigram index can answer; then every word.
       and (cardinality(c.pats)     = 0 or (l.search_text like c.first_pat and l.search_text like all (c.pats)))
  ),
  win as (
    select * from m
     order by lead_date desc nulls last, id desc
     limit greatest(least(coalesce(per_page, 10), 10000), 1)
    offset least(greatest(coalesce(page, 1) - 1, 0)::bigint * greatest(least(coalesce(per_page, 10), 10000), 1), 1000000000)
  )
  select jsonb_build_object(
    'total',    (select count(*) from m),
    'rows',     (select coalesce(jsonb_agg(to_jsonb(win)), '[]'::jsonb) from win),
    'by_client', (select coalesce(jsonb_agg(jsonb_build_object('id', t.client_id, 'label', coalesce(t.client_name, 'Unassigned'), 'count', t.n)
                                            order by t.n desc, coalesce(t.client_name, 'zzz')), '[]'::jsonb)
                    from (select client_id, client_name, count(*) as n from m group by client_id, client_name) t),
    'by_state',  (select coalesce(jsonb_agg(jsonb_build_object('label', coalesce(t.state, '—'), 'count', t.n)
                                            order by t.n desc, coalesce(t.state, 'zz')), '[]'::jsonb)
                    from (select state, count(*) as n from m group by state) t),
    'by_month',  (select coalesce(jsonb_agg(jsonb_build_object('month', t.mon, 'label', to_char(to_date(t.mon::text, 'MM'), 'Mon'), 'count', t.n)
                                            order by t.mon), '[]'::jsonb)
                    from (select extract(month from renewal_date)::int as mon, count(*) as n
                            from m where renewal_date is not null group by 1) t),
    'by_industry', (select coalesce(jsonb_agg(jsonb_build_object('code', t.sic_code, 'label', coalesce(s.description, t.sic_code, '—'), 'count', t.n)
                                              order by t.n desc), '[]'::jsonb)
                      from (select sic_code, count(*) as n from m group by sic_code) t
                      left join public.sic_codes s on s.code = t.sic_code),
    'by_result', (select coalesce(jsonb_agg(jsonb_build_object('label', t.label, 'count', t.n)
                                            order by t.n desc, t.label), '[]'::jsonb)
                    from (select coalesce(result_name, 'Not called yet') as label, count(*) as n from m group by 1) t),
    'clients_touched', (select count(distinct client_id) from m where client_id is not null),
    'with_xdate',      (select count(*) from m where renewal_date is not null),
    -- Still to call for an appointment: a call result that leaves the lead viable (none yet counts).
    'viable',          (select count(*) from m where coalesce(result_viable, true))
  );
$function$;

CREATE OR REPLACE FUNCTION public.lead_explore_options()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'industries', (select coalesce(jsonb_agg(jsonb_build_object('value', t.sic_code, 'label', coalesce(s.description, t.sic_code), 'count', t.n)
                                             order by t.n desc), '[]'::jsonb)
                     from (select sic_code, count(*) as n from public.leads where stage = 'appt' and sic_code is not null group by sic_code) t
                     left join public.sic_codes s on s.code = t.sic_code),
    'states',     (select coalesce(jsonb_agg(jsonb_build_object('value', t.state, 'label', t.state, 'count', t.n)
                                             order by t.state), '[]'::jsonb)
                     from (select state, count(*) as n from public.leads where stage = 'appt' and state is not null group by state) t),
    'counties',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.county, 'label', t.county, 'count', t.n)
                                             order by t.county), '[]'::jsonb)
                     from (select county, count(*) as n from public.leads where stage = 'appt' and county is not null group by county) t),
    'results',    (select coalesce(jsonb_agg(jsonb_build_object('value', t.label, 'label', t.label, 'count', t.n) order by t.n desc, t.label), '[]'::jsonb)
                     from (select coalesce(r.name, 'Not called yet') as label, count(*) as n
                             from public.leads l left join public.call_results r on r.id = l.result_id
                            where l.stage = 'appt' group by 1) t),
    'clients',    (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', name) order by name), '[]'::jsonb)
                     from public.companies),
    'projects',   (select coalesce(jsonb_agg(jsonb_build_object('value', p.id, 'label', p.name, 'count', t.n) order by p.name), '[]'::jsonb)
                     from (select project_id, count(*) as n from public.leads where stage = 'appt' and project_id is not null group by 1) t
                     join public.projects p on p.id = t.project_id),
    'groups',     (select coalesce(jsonb_agg(jsonb_build_object('value', g.id, 'label', g.name, 'count', t.n) order by g.name), '[]'::jsonb)
                     from (select agency_group_id, count(*) as n from public.companies where agency_group_id is not null group by 1) t
                     join public.agencies g on g.id = t.agency_group_id),
    'carriers',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.k, 'label', t.label, 'count', t.n) order by t.k), '[]'::jsonb)
                     from (select k, (array_agg(label order by rec desc, label))[1] as label, sum(n)::bigint as n
                             from (select public.carrier_key(a.name) as k, btrim(a.name) as label, true as rec, 0 as n
                                     from public.agencies a
                                   union all
                                   select public.carrier_key(coalesce(ag.name, ins.agency_name)), btrim(coalesce(ag.name, ins.agency_name)), false, 1
                                     from public.leads l
                                     left join public.agencies ag on ag.id = l.agency_id
                                     left join public.insurance_details ins on ins.lead_id = l.id
                                    where l.stage = 'appt') x
                            where k is not null
                            group by k) t),
    'reps',       (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', nullif(concat_ws(' ', first_name, last_name), '')) order by first_name, last_name), '[]'::jsonb)
                     from public.users where role in ('admin', 'manager', 'agent'))
  );
$function$;

-- ==============================================================================================================
-- 20261114100000_counts_profiles_celebrations.sql
-- ==============================================================================================================

-- Lighthouse CRM — counting leads as leads, more on each person, and their
-- birthdays and work anniversaries (Sean, Oct 2026).
--
--   projects_lead_stats()   every project's figures at once, as lead_stats()
--                           counts one: its leads (an appointment project's
--                           own; a DB dev project's, those it developed and
--                           sent on), what is still to call (names on a DB
--                           dev project, leads on an appointment project),
--                           and a total row (project_id null), each lead
--                           once. The Projects page's tiles and Leads column
--                           counted every name loaded instead.
--   user_workload           adds names_left (DB dev names a person holds,
--                           still to call) and leads_held (leads they hold);
--                           lead_count, every record held, stays as it was.
--   users                   timezone_id, birth_date and start_date (the day
--                           they started: a manager's hire date).
--   send_celebrations()     each morning, every active manager and
--                           administrator hears of a colleague's birthday or
--                           work anniversary that day ("Happy 5 yr work
--                           anniversary Kristy W"). Run by run_daily_alerts()
--                           (pg_cron, hourly from 7 a.m.), once a day each;
--                           switched off with its rule on the Alerts page.

create or replace function public.projects_lead_stats()
returns table(project_id bigint, names bigint, names_left bigint, leads bigint, leads_active bigint, developed bigint)
language sql stable set search_path = public as $$
  with scoped as (
    -- A project's names: those on it, and those it sent on to another (as lead_stats() has them).
    select p.id as pid, c.*, (c.project_id = p.id) as here
      from public.projects p join public.lead_classes c
        on c.project_id = p.id or (c.source_project_id = p.id and c.source_project_id <> c.project_id)
  )
  select pid, count(*),
         count(*) filter (where here and stage = 'dbdev' and viable),
         count(*) filter (where stage = 'appt'),
         count(*) filter (where stage = 'appt' and viable),
         count(*) filter (where developed)
    from scoped group by pid
  union all
  -- Every lead once, whichever projects it passed through.
  select null, count(*),
         count(*) filter (where stage = 'dbdev' and viable),
         count(*) filter (where stage = 'appt'),
         count(*) filter (where stage = 'appt' and viable),
         count(*) filter (where developed)
    from public.lead_classes;
$$;
revoke execute on function public.projects_lead_stats() from public, anon;
grant execute on function public.projects_lead_stats() to authenticated;

-- Added at the end: a view keeps its columns in order when it is replaced.
create or replace view public.user_workload with (security_invoker = true) as
  select u.id as user_id,
    (select count(*) from public.leads l where l.assigned_user_id = u.id) as lead_count,
    (select count(*) from public.appointments a where a.user_id = u.id and a.invalid_at is null) as appt_count,
    (select count(*) from public.lead_classes c join public.leads l on l.id = c.id
      where l.assigned_user_id = u.id and c.stage = 'dbdev' and c.viable) as names_left,
    (select count(*) from public.leads l where l.assigned_user_id = u.id and l.stage = 'appt') as leads_held
  from public.users u;
grant select on public.user_workload to authenticated;

alter table public.users
  add column if not exists timezone_id bigint references public.timezones(id),
  add column if not exists birth_date date check (birth_date between date '1900-01-01' and date '2100-01-01'),
  add column if not exists start_date date check (start_date between date '1950-01-01' and date '2100-01-01');

insert into public.alert_rules (name, trigger, channel)
select 'Birthdays and work anniversaries', 'celebrations', 'inapp'
 where not exists (select 1 from public.alert_rules where trigger = 'celebrations');

/**
 * The day's birthdays and work anniversaries (`p_day`, the business's day):
 * one notification each to every active manager and administrator, the one
 * celebrated too. A birthday on Feb 29 is kept on Feb 28 in other years.
 * Returns how many were told.
 */
create or replace function public.send_celebrations(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r      record;
  n      integer := 0;
  v_team bigint[];
  v_leap boolean := extract(month from p_day) = 2 and extract(day from p_day) = 28
                    and not (extract(year from p_day)::int % 4 = 0 and (extract(year from p_day)::int % 100 <> 0 or extract(year from p_day)::int % 400 = 0));
begin
  select coalesce(array_agg(id), '{}') into v_team
    from public.users where role in ('admin', 'manager') and status = 'active' and deleted_at is null;
  if cardinality(v_team) = 0 then
    return 0;
  end if;
  for r in
    select u.id, 'birthday' as what, null::int as years,
           concat_ws(' ', u.first_name, left(nullif(u.last_name, ''), 1)) as who
      from public.users u
     where u.role in ('admin', 'manager') and u.status = 'active' and u.deleted_at is null and u.birth_date is not null
       and ((extract(month from u.birth_date) = extract(month from p_day) and extract(day from u.birth_date) = extract(day from p_day))
            or (v_leap and extract(month from u.birth_date) = 2 and extract(day from u.birth_date) = 29))
    union all
    select u.id, 'anniversary', extract(year from p_day)::int - extract(year from u.start_date)::int,
           concat_ws(' ', u.first_name, left(nullif(u.last_name, ''), 1))
      from public.users u
     where u.role in ('admin', 'manager') and u.status = 'active' and u.deleted_at is null and u.start_date is not null
       and u.start_date < p_day
       and ((extract(month from u.start_date) = extract(month from p_day) and extract(day from u.start_date) = extract(day from p_day))
            or (v_leap and extract(month from u.start_date) = 2 and extract(day from u.start_date) = 29))
  loop
    if exists (select 1 from public.alert_sends where rule = 'celebrations' and key = r.what || ':' || r.id || ':' || p_day) then
      continue;
    end if;
    insert into public.alert_sends (rule, key) values ('celebrations', r.what || ':' || r.id || ':' || p_day);
    n := n + public.notify_users(
      v_team, 'system',
      case when r.what = 'birthday' then 'Happy Birthday ' || r.who || '!'
           else 'Happy ' || r.years || ' yr work anniversary ' || r.who || '!' end,
      case when r.what = 'birthday' then 'Wish them a happy birthday today.'
           else r.years || case when r.years = 1 then ' year' else ' years' end || ' with the team today.' end,
      null, 'celebrations');
  end loop;
  return n;
end $$;
revoke execute on function public.send_celebrations(date) from public, anon, authenticated;

create or replace function public.run_daily_alerts()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_now timestamp := now() at time zone public.business_tz();
begin
  if extract(hour from v_now) < 7 then
    return 0;
  end if;
  return public.send_xdate_warnings(v_now::date) + public.send_appointment_reminders(v_now::date)
       + public.send_celebrations(v_now::date);
end $$;
revoke execute on function public.run_daily_alerts() from public, anon, authenticated;

-- ==============================================================================================================
-- 20261115100000_call_list_speed.sql
-- ==============================================================================================================

-- The call list, fast on a list of thousands (Oct 2026). A manager holding
-- ~3,400 names timed out opening a project (statement timeout): the list's
-- filter choices read each name's carriers one name at a time
-- (lead_carrier_keys()), and with a filter saved for the day the list read
-- each name's X-dates and carriers the same way, every lookup checking again
-- who may see the name. Seconds each, past the limit under load.
--
--   call_list_options   carriers read in one pass over the names' agencies
--                       and policies
--   call_list           renewal dates, X-dates and carriers read in one pass;
--                       the X-date that matched a renewal filter only for the
--                       names on the page. Same names, order, counts and
--                       filters as before.
--
-- Both are as the local database had them (20261028100000), with only these
-- changes.

CREATE OR REPLACE FUNCTION public.call_list(p_project_id bigint, p_rep bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_search text DEFAULT NULL::text, p_filtered boolean DEFAULT true)
 RETURNS TABLE(id bigint, company_name text, contact_name text, phone text, city text, state text, result text, call_weight integer, sort_last boolean, date_last_worked timestamp with time zone, renewal_date date, total bigint, renewal_match jsonb)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
#variable_conflict use_column
declare
  v_rep     bigint := coalesce(p_rep, public.app_user_id());
  v_words   text[] := public.search_words(p_search);
  v_pats    text[] := public.search_patterns(v_words);
  v_first   text   := public.search_lead_pattern(v_words);
  v_c       jsonb;
  v_renew   boolean;
  v_carrier boolean;
  v_line    text;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  if coalesce(p_filtered, true) then
    -- Today's only: each morning the list starts again in full.
    select f.criteria into v_c from public.call_list_filters f
     where f.user_id = public.app_user_id() and f.project_id = p_project_id
       and (f.updated_at at time zone public.business_tz())::date = (now() at time zone public.business_tz())::date;
  end if;
  v_renew   := coalesce(v_c ? 'renewal', false);
  v_carrier := coalesce(v_c ? 'carrier', false);
  v_line    := nullif(v_c -> 'renewal' ->> 'line', '');
  -- Each name's renewal date, X-dates and carriers read in one pass over the policies (a lookup a name,
  -- each checking who may see it again, took seconds on a list of thousands); the matching X-date only
  -- for the names on the page.
  return query
    with mine as (
      select l as lr, r.name as r_name, r.sort_last as r_sort_last
        from public.leads l
        join public.call_results r on r.id = l.result_id
       where l.project_id = p_project_id
         and l.assigned_user_id = v_rep
         and r.viable and r.callable
         and (v_first is null or (l.search_text like v_first and l.search_text like all (v_pats)))
    ), ins as (
      select i.lead_id,
             min(coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                                  i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate))) as renewal
        from public.insurance_details i
       where i.lead_id in (select (m.lr).id from mine m)
       group by i.lead_id
    ), xd as (
      select i.lead_id, array_agg(v.d) as xdates
        from public.insurance_details i,
             lateral (values ('ultimate', i.ultimate_xdate), ('pkg', i.pkg_xdate), ('wc', i.wc_xdate), ('auto', i.auto_xdate),
                             ('health', i.health_xdate), ('personal', i.personal_lines_xdate), ('dental', i.dental_xdate),
                             ('vision', i.vision_xdate), ('prof', i.prof_liab_xdate), ('do', i.do_xdate), ('eo', i.eo_xdate)) as v(line, d)
       where v_renew and i.lead_id in (select (m.lr).id from mine m)
         and v.d is not null and (v_line is null or v.line = v_line)
       group by i.lead_id
    ), ck as (
      select s.lead_id, array_agg(distinct s.k) as keys
        from (select (m.lr).id as lead_id, public.carrier_key(a.name) as k
                from mine m join public.agencies a on a.id = (m.lr).agency_id
               where v_carrier
              union all
              select i.lead_id, public.carrier_key(x)
                from public.insurance_details i,
                     unnest(array[i.agency_name, i.pkg_carrier, i.wc_carrier, i.auto_carrier, i.health_carrier, i.dental_provider,
                                  i.vision_provider, i.prof_liab_carrier, i.do_carrier, i.eo_carrier, i.homeowner_carrier,
                                  i.personal_auto_carrier, i.personal_lines_carrier]) as x
               where v_carrier and i.lead_id in (select (m.lr).id from mine m)) s
       where s.k is not null
       group by s.lead_id
    ), q as (
      select (m.lr).id as q_id, (m.lr).company_name as q_company, (m.lr).contact_name as q_contact, (m.lr).phone as q_phone,
             (m.lr).city as q_city, (m.lr).state as q_state, m.r_name as q_result, (m.lr).call_weight as q_weight,
             m.r_sort_last as q_sort_last, (m.lr).date_last_worked as q_worked, ins.renewal as q_renewal,
             count(*) over () as q_total
        from mine m
        left join ins on ins.lead_id = (m.lr).id
        left join xd  on xd.lead_id  = (m.lr).id
        left join ck  on ck.lead_id  = (m.lr).id
       where (v_c is null or v_c = '{}'::jsonb
              or public.call_list_matches(m.lr, coalesce(xd.xdates, '{}'::date[]), coalesce(ck.keys, '{}'::text[]), v_c))
       order by m.r_sort_last, (m.lr).call_weight, (m.lr).date_last_worked nulls first, (m.lr).id
       limit greatest(least(coalesce(p_limit, 50), 500), 1)
      offset greatest(coalesce(p_offset, 0), 0)
    )
    select q.q_id, q.q_company, q.q_contact, q.q_phone, q.q_city, q.q_state, q.q_result, q.q_weight, q.q_sort_last, q.q_worked,
           q.q_renewal, q.q_total,
           -- With a renewal window (not excluded): the X-date that put the name in it.
           case when v_renew and not coalesce((v_c -> 'renewal' ->> 'exclude')::boolean, false)
                then public.lead_xdate_in(q.q_id, v_c -> 'renewal') end
      from q
     order by q.q_sort_last, q.q_weight, q.q_worked nulls first, q.q_id;
end $function$;

CREATE OR REPLACE FUNCTION public.call_list_options(p_project_id bigint, p_rep bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_rep bigint := coalesce(p_rep, public.app_user_id());
  v     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  with base as (
    select l.* from public.leads l join public.call_results r on r.id = l.result_id
     where l.project_id = p_project_id and l.assigned_user_id = v_rep and r.viable and r.callable
  ), opts as (
    -- Labels as written, a capitalised spelling first ("Phoenix" over "phoenix").
    select 'city' as k, lower(btrim(city)) as value,
           coalesce(min(btrim(city)) filter (where btrim(city) ~ '^[A-Z]'), min(btrim(city))) as label, count(*) as n
      from base where nullif(btrim(city), '') is not null group by 2
    union all
    select 'zip', left(btrim(zip), 5), left(btrim(zip), 5), count(*) from base where nullif(btrim(zip), '') is not null group by 2
    union all
    select 'county', lower(btrim(county)),
           coalesce(min(btrim(county)) filter (where btrim(county) ~ '^[A-Z]'), min(btrim(county))), count(*)
      from base where nullif(btrim(county), '') is not null group by 2
    union all
    select 'sic', btrim(b.sic_code), btrim(b.sic_code) || coalesce(' – ' || min(s.description), ''), count(*)
      from base b left join public.sic_codes s on s.code = btrim(b.sic_code)
     where nullif(btrim(b.sic_code), '') is not null group by 2
    union all
    -- Read in one pass over the names' agencies and policies: one lookup a name (lead_carrier_keys()),
    -- each checking who may see it again, took seconds on a call list of thousands.
    select 'carrier', s.k, min(initcap(s.k)), count(distinct s.id)
      from (select b.id, public.carrier_key(a.name) as k from base b join public.agencies a on a.id = b.agency_id
            union all
            select b.id, public.carrier_key(x)
              from base b join public.insurance_details i on i.lead_id = b.id,
                   unnest(array[i.agency_name, i.pkg_carrier, i.wc_carrier, i.auto_carrier, i.health_carrier, i.dental_provider,
                                i.vision_provider, i.prof_liab_carrier, i.do_carrier, i.eo_carrier, i.homeowner_carrier,
                                i.personal_auto_carrier, i.personal_lines_carrier]) as x) s
     where s.k is not null group by 2
    union all
    select 'year', extract(year from promoted_at at time zone public.business_tz())::int::text,
           extract(year from promoted_at at time zone public.business_tz())::int::text, count(*)
      from base where promoted_at is not null group by 2
    union all
    select 'developer', b.dbdv_user_id::text,
           min(coalesce(nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email)), count(*)
      from base b join public.users u on u.id = b.dbdv_user_id group by 2
    union all
    select 'result', b.result_id::text, min(r.name), count(*)
      from base b join public.call_results r on r.id = b.result_id group by 2
    union all
    select 'source', lower(btrim(b.list_source)), min(btrim(b.list_source)), count(*)
      from base b where nullif(btrim(b.list_source), '') is not null group by 2
  )
  select coalesce(jsonb_object_agg(k, items), '{}'::jsonb) into v
    from (select k, jsonb_agg(jsonb_build_object('value', value, 'label', label, 'count', n) order by label) as items
            from opts group by k) g;
  return v;
end $function$;

-- ==============================================================================================================
-- 20261116100000_project_info.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — Project Info: the client profile sheet (Sean, Oct 2026)
--
-- What a client tells Signature Marketing when they come on board (the
-- Client Profile Questionnaire, typed into the old system's project profile
-- by hand): the agent and their office, the states they are licensed in, up
-- to five producers taking appointments (and which of them get each lead and
-- appointment by email), the carriers they place with and those they can't
-- compete with, the weekdays to keep appointments off, and what an
-- appointment needs to qualify. Managers read it on every lead sheet (the
-- Project Info tab); administrators and the client's own people change it,
-- the client from their own sign-in or from a private link sent when they
-- come on board.
--
-- The agent's name, phone and address are the project's office (projects:
-- contact_name, phone, address, city, state, zip), as the project form has
-- them; the rest is here, one row a project. A DB dev project shares the
-- Project Info of the appointment project it promotes to, as it shares that
-- project's calendar.
--
-- Staff read it, and a client's people read their own projects'. Only the
-- server writes it, once it has checked who is asking: an administrator,
-- the client's own person, or a private link whose key is still the row's.
--
--   project_profiles      one row a project
--     producers           [{ first, last, email, leads }], at most five;
--                         `leads`: emailed each lead and appointment
--     avoid_days          weekdays (0 Sunday … 6 Saturday) blocked out on
--                         the project's calendar, every week
--     link_key            the private link's key: a new one ends the links
--                         sent before it
-- ---------------------------------------------------------------------------

create table if not exists public.project_profiles (
  project_id         bigint primary key references public.projects(id) on delete cascade,
  agent_mobile       text check (length(agent_mobile) <= 40),
  agent_email        text check (length(agent_email) <= 254),
  states_licensed    text[] not null default '{}' check (cardinality(states_licensed) <= 60),
  producers          jsonb not null default '[]'::jsonb
                     check (jsonb_typeof(producers) = 'array' and jsonb_array_length(producers) <= 5),
  top_carriers       text[] not null default '{}' check (cardinality(top_carriers) <= 200),
  avoid_carriers     text[] not null default '{}' check (cardinality(avoid_carriers) <= 200),
  avoid_days         smallint[] not null default '{}' check (avoid_days <@ '{0,1,2,3,4,5,6}'::smallint[]),
  special_programs   text check (length(special_programs) <= 4000),
  personal_lines     boolean,
  min_employees      smallint check (min_employees between 0 and 250),
  quote_time         text check (length(quote_time) <= 40),
  quote_min_time     text check (length(quote_min_time) <= 40),
  wc_mono            boolean,
  wc_min_employees   integer check (wc_min_employees between 0 and 1000000),
  auto_mono          boolean,
  auto_min_autos     integer check (auto_min_autos between 0 and 1000000),
  health_only        boolean,
  health_min_lives   integer check (health_min_lives between 0 and 1000000),
  value_added        text check (length(value_added) <= 4000),
  exclusive_program  text check (length(exclusive_program) <= 4000),
  industry_notes     text check (length(industry_notes) <= 4000),
  link_key           text check (length(link_key) <= 64),
  updated_at         timestamptz not null default now(),
  updated_by         bigint references public.users(id) on delete set null,
  updated_via        text check (updated_via in ('app', 'link'))
);

alter table public.project_profiles enable row level security;
drop policy if exists project_profiles_read on public.project_profiles;
create policy project_profiles_read on public.project_profiles
  for select to authenticated
  using ((select public.is_staff()) or project_id in (select public.client_project_ids()));
drop policy if exists mfa_required on public.project_profiles;
create policy mfa_required on public.project_profiles as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.project_profiles;
create policy active_account_required on public.project_profiles as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.project_profiles from anon;
revoke insert, update, delete, truncate on public.project_profiles from authenticated;
grant select on public.project_profiles to authenticated;
grant all on public.project_profiles to service_role;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261117100000_manager_period_stats.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the Account Managers page over days of the administrator's
-- choosing (Sean, Oct 2026)
--
-- What production_report() does not count, by manager and the business's day,
-- from p_from to p_to (both days kept):
--   leads_called    leads at the appointment-setting stage the manager called,
--                   each once
--   appts_invalid   appointments the manager set that were marked invalid
--   leads_invalid   leads the manager developed (DB dev) that were marked
--                   invalid (a Lead-Invalid result, charged back to them)
-- and a row per manager with day null for all the days together, where a lead
-- called on several of them counts once.
--
-- For administrators: it reads with the server's own rights (security
-- definer) after checking, as the per-row access checks would make it slow
-- over thousands of calls.
-- ---------------------------------------------------------------------------

create or replace function public.manager_period_stats(p_from date, p_to date)
returns table (day date, user_id bigint, leads_called bigint, appts_invalid bigint, leads_invalid bigint)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare
  v_tz    text := public.business_tz();
  v_start timestamptz := (p_from::timestamp at time zone v_tz);
  v_end   timestamptz := ((p_to + 1)::timestamp at time zone v_tz);
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can see the team''s figures' using errcode = '42501';
  end if;
  if p_to < p_from or p_to - p_from > 400 then
    raise exception 'Choose up to a year of days' using errcode = '22023';
  end if;
  return query
  with called as (
    select (c.call_date at time zone v_tz)::date as d, c.user_id as u, c.lead_id as lead
      from public.call_records c
     where c.call_date >= v_start and c.call_date < v_end and c.stage = 'appt' and c.user_id is not null
  ),
  bad_appts as (
    select (a.invalid_at at time zone v_tz)::date as d, a.user_id as u
      from public.appointments a
     where a.invalid_at >= v_start and a.invalid_at < v_end and a.user_id is not null and a.deleted_at is null
  ),
  bad_leads as (
    select (c.call_date at time zone v_tz)::date as d, l.dbdv_user_id as u
      from public.call_records c
      join public.call_results r on r.id = c.result_id and r.effect = 'lead_invalid'
      join public.leads l on l.id = c.lead_id
     where c.call_date >= v_start and c.call_date < v_end and l.dbdv_user_id is not null
  )
  select t.d, t.u, sum(t.n_called)::bigint, sum(t.n_appts)::bigint, sum(t.n_leads)::bigint
    from (
      select d, u, count(distinct lead) as n_called, 0::bigint as n_appts, 0::bigint as n_leads from called group by d, u
      union all select d, u, 0, count(*), 0 from bad_appts group by d, u
      union all select d, u, 0, 0, count(*) from bad_leads group by d, u
    ) t
   group by t.d, t.u
  union all
  select null::date, t.u, sum(t.n_called)::bigint, sum(t.n_appts)::bigint, sum(t.n_leads)::bigint
    from (
      select u, count(distinct lead) as n_called, 0::bigint as n_appts, 0::bigint as n_leads from called group by u
      union all select u, 0, count(*), 0 from bad_appts group by u
      union all select u, 0, 0, count(*) from bad_leads group by u
    ) t
   group by t.u;
end $$;

revoke execute on function public.manager_period_stats(date, date) from public, anon;
grant execute on function public.manager_period_stats(date, date) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261118100000_delivery_holds.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — leads and appointments held in QA before they go to the
-- client (Sean, Oct 2026)
--
-- Settings › Delivery (app_settings 'delivery') says, for leads and for
-- appointments apart, whether a call that makes one emails the client
-- straight away, as before, or holds it here. Held ones go when an
-- administrator sends them from the QA page (one, some or all), or when the
-- schedule clears them (every few hours, 8 AM to 6 PM Pacific to begin with).
-- One an administrator fails stays unsent, its manager told why; once the
-- manager marks it fixed it waits again, for the next clearing or an
-- administrator. Sending an appointment passes its QA, so the client is told
-- of it in Lighthouse then too.
--
--   delivery_holds          one a lead or appointment held
--     status                held · failed · sending · sent
--   release_appointment_qa  passes a held appointment's QA as it is sent
--                           (the server's role only)
--   flush_held_deliveries   on the hour (pg_cron): asks the app to clear what
--                           is held, at the push address's sibling
--                           /api/delivery/flush with the push secret (Vault)
-- ---------------------------------------------------------------------------

create table if not exists public.delivery_holds (
  id              bigint generated always as identity primary key,
  lead_id         bigint not null references public.leads(id) on delete cascade,
  call_record_id  bigint references public.call_records(id) on delete set null,
  appointment_id  bigint references public.appointments(id) on delete set null,
  kind            text not null check (kind in ('lead', 'appointment')),
  label           text check (length(label) <= 80),
  user_id         bigint references public.users(id) on delete set null,
  project_id      bigint references public.projects(id) on delete set null,
  status          text not null default 'held' check (status in ('held', 'failed', 'sending', 'sent')),
  note            text check (length(note) <= 500),
  failed_by       bigint references public.users(id) on delete set null,
  failed_at       timestamptz,
  fixed_at        timestamptz,
  sent_at         timestamptz,
  sent_by         bigint references public.users(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists delivery_holds_open on public.delivery_holds (status, created_at) where status in ('held', 'failed', 'sending');
create index if not exists delivery_holds_lead on public.delivery_holds (lead_id);

alter table public.delivery_holds enable row level security;
-- Administrators see them all; a manager, their own (the lead sheet says when one is held back).
drop policy if exists delivery_holds_read on public.delivery_holds;
create policy delivery_holds_read on public.delivery_holds
  for select to authenticated
  using ((select public.is_admin()) or user_id = (select public.app_user_id()));
drop policy if exists mfa_required on public.delivery_holds;
create policy mfa_required on public.delivery_holds as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.delivery_holds;
create policy active_account_required on public.delivery_holds as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.delivery_holds from anon;
revoke insert, update, delete, truncate on public.delivery_holds from authenticated;
grant select on public.delivery_holds to authenticated;
grant all on public.delivery_holds to service_role;

-- A held appointment, sent: passed QA (by `p_by`, none for the schedule), and the client told in Lighthouse.
create or replace function public.release_appointment_qa(p_appointment_id bigint, p_by bigint default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_appt public.appointments;
begin
  select * into v_appt from public.appointments where id = p_appointment_id for update;
  if not found or v_appt.qa_status is distinct from 'pending' then return; end if;
  update public.appointments set qa_status = 'passed', qa_by = p_by, qa_at = now() where id = v_appt.id;
  update public.call_records set qa_result = 'Passed', qa_date = now() where id = v_appt.call_record_id;
  perform public.notify_client_appointment(v_appt.id, v_appt.confirmed_at is not null, true);
end $$;
revoke execute on function public.release_appointment_qa(bigint, bigint) from public, anon, authenticated;
grant execute on function public.release_appointment_qa(bigint, bigint) to service_role;

-- The server tells a manager when one of theirs is held back (as review_appointment_qa does for an appointment).
-- Whatever its arguments are on this database, so the grant never stops the rest.
do $$
declare f regprocedure;
begin
  for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid = p.pronamespace
            where n.nspname = 'public' and p.proname = 'notify_users' loop
    execute format('grant execute on function %s to service_role', f);
  end loop;
end $$;

-- On the hour: when something is held, ask the app to clear it (it sends only in a clearing hour).
create or replace function public.flush_held_deliveries()
returns void
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_url text;
  v_secret text;
begin
  if not exists (select 1 from public.delivery_holds where status = 'held') then return; end if;
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'push_deliver_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_deliver_secret';
  if v_url is null or v_secret is null or v_url not like '%/api/push/deliver' then return; end if;
  perform net.http_post(
    url := replace(v_url, '/api/push/deliver', '/api/delivery/flush'),
    body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
    timeout_milliseconds := 60000
  );
exception when others then
  raise warning 'held deliveries: % (%)', sqlerrm, sqlstate;
end $$;
revoke execute on function public.flush_held_deliveries() from public, anon, authenticated;

-- Scheduled where pg_cron is on; without it, held ones still go when an administrator sends them.
do $$
begin
  if to_regclass('cron.job') is null then
    raise notice 'pg_cron is not enabled: held deliveries are not cleared on a schedule';
    return;
  end if;
  if exists (select 1 from cron.job where jobname = 'flush-held-deliveries') then
    perform cron.unschedule('flush-held-deliveries');
  end if;
  perform cron.schedule('flush-held-deliveries', '0 * * * *', 'select public.flush_held_deliveries()');
end $$;

notify pgrst, 'reload schema';

