-- 20261119100000_project_info_own.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a tied DB dev project's Project Info: shared, or its own
-- (Sean, Oct 2026)
--
-- A DB dev project tied to an appointment project shows and edits that
-- project's Project Info, one sheet for them all (migration 20261116100000).
-- When one needs to differ, it keeps its own instead:
--
--   project_profiles.own    on a tied DB dev project's row: its own Project
--                           Info, not the appointment project's
-- ---------------------------------------------------------------------------

alter table public.project_profiles add column if not exists own boolean not null default false;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261120100000_speed.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — speed (Oct 2026)
--
-- Measured on a copy with 100,000 names, 400,000 calls and 8,000
-- appointments, these were what made pages slow; each returns exactly what
-- it did before:
--
--   work_projects()      My Projects, a call list, a lead sheet: 27 s (over
--                        the API's 8 s limit, so the page failed). The
--                        caller's id was looked up again for every name and
--                        every call counted; it is now read once. And an
--                        index for a manager's last call on a project.
--   xdates_by_month(),   the X-dates report and a project's renewal chart:
--   xdate_month_leads()  38 s for the whole book. Each name's renewal date
--                        came from a function called once a name; it is now
--                        read in the same pass, from its index.
--   the leads list       newest first: 1.9 s. Without an index in that order
--                        the database joined every name's project, result,
--                        manager and coverage before keeping a page of them.
--
-- Indexes and functions only: no data changes. Safe to run again.
-- ---------------------------------------------------------------------------

-- The leads list and a project's names, newest first (deleted names are never listed).
create index if not exists leads_lead_date_idx
  on public.leads (lead_date desc nulls last, id desc) where deleted_at is null;

-- A manager's last call on a project (My Projects' "last worked").
create index if not exists call_records_project_user_date
  on public.call_records (project_id, user_id, call_date desc);

-- My Projects. `me` is materialized: read once, not again for each row counted.
create or replace function public.work_projects()
returns table (
  id bigint, name text, client text, company_id bigint, type text, timezone text,
  state text, status text, appt_project_id bigint,
  names_left bigint,       -- the caller's names still to call
  names_left_all bigint,   -- everyone's (what an administrator watches)
  follow_ups bigint,       -- the caller's upcoming appointments waiting to be confirmed
  last_worked timestamptz  -- the caller's last call on the project
)
language sql stable security invoker set search_path = public as $$
  with me as materialized (select public.app_user_id() as uid, coalesce(public.is_admin(), false) as admin)
  select p.id, p.name, co.name, p.company_id, t.code, tz.name, p.state, ps.name, p.appt_project_id,
         (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
           where l.project_id = p.id and l.assigned_user_id = me.uid and r.viable and r.callable),
         (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
           where l.project_id = p.id and r.viable and r.callable),
         (select count(*) from public.appointments a
           where a.set_project_id = p.id and a.user_id = me.uid and a.confirmed_at is null and a.invalid_at is null
             and a.appt_date >= current_date - 1),
         (select max(c.call_date) from public.call_records c where c.project_id = p.id and c.user_id = me.uid)
    from public.projects p
    cross join me
    left join public.companies co        on co.id = p.company_id
    left join public.project_types t     on t.id = p.project_type_id
    left join public.timezones tz        on tz.id = p.timezone_id
    left join public.project_statuses ps on ps.id = p.status_id
   where me.uid is not null
     and (me.admin or exists (select 1 from public.project_assignments pa
                               where pa.project_id = p.id and pa.ae_user_id = me.uid))
   order by p.name;
$$;
grant execute on function public.work_projects() to authenticated;

-- X-dates by month: lead_renewal_date() and lead_xdate_bucket() written in place, so they run in the same pass.
create or replace function public.xdates_by_month(p_project_id bigint default null, p_company_id bigint default null)
returns table (month int, total bigint, appointments bigint, off_list bigint, viable_left bigint)
language sql stable security invoker set search_path = public as $$
  with x as (
    select coalesce(extract(month from ren.renewal)::int, 0) as m,
           case when r.effect in ('appointment', 'confirm') then 'appointment'
                when r.viable then 'viable'
                else 'off' end as bucket
      from public.leads l
      join public.call_results r on r.id = l.result_id
      left join public.projects p on p.id = l.project_id
      left join lateral (
        select min(coalesce(i.ultimate_xdate,
                            least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                  i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate))) as renewal
          from public.insurance_details i where i.lead_id = l.id
      ) ren on true
     where (p_project_id is null or l.project_id = p_project_id)
       and (p_company_id is null or p.company_id = p_company_id)
  )
  select m, count(*),
         count(*) filter (where bucket = 'appointment'),
         count(*) filter (where bucket = 'off'),
         count(*) filter (where bucket = 'viable')
    from x
   group by m
   order by m;
$$;
revoke execute on function public.xdates_by_month(bigint, bigint) from public, anon;
grant execute on function public.xdates_by_month(bigint, bigint) to authenticated;

-- One page of the names behind a number in xdates_by_month(); p_bucket null means all of them.
create or replace function public.xdate_month_leads(
  p_month int, p_bucket text default null, p_project_id bigint default null, p_company_id bigint default null,
  p_limit int default 20, p_offset int default 0
)
returns table (
  id bigint, company_name text, contact_name text, phone text, city text, state text,
  project text, result text, renewal_date date, rep_first text, rep_last text, rep_email text, total bigint
)
language sql stable security invoker set search_path = public as $$
  select l.id, l.company_name, l.contact_name, l.phone, l.city, l.state,
         p.name, r.name, x.renewal, u.first_name, u.last_name, u.email, count(*) over ()
    from public.leads l
    join public.call_results r on r.id = l.result_id
    left join public.projects p on p.id = l.project_id
    left join public.users u on u.id = l.assigned_user_id
    left join lateral (
      select min(coalesce(i.ultimate_xdate,
                          least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate))) as renewal
        from public.insurance_details i where i.lead_id = l.id
    ) x on true
   where (p_project_id is null or l.project_id = p_project_id)
     and (p_company_id is null or p.company_id = p_company_id)
     and coalesce(extract(month from x.renewal)::int, 0) = p_month
     and (p_bucket is null or (case when r.effect in ('appointment', 'confirm') then 'appointment'
                                    when r.viable then 'viable'
                                    else 'off' end) = p_bucket)
   order by extract(day from x.renewal) nulls last, l.company_name, l.id
   limit greatest(least(coalesce(p_limit, 20), 100), 1)
  offset greatest(coalesce(p_offset, 0), 0);
$$;
revoke execute on function public.xdate_month_leads(int, text, bigint, bigint, int, int) from public, anon;
grant execute on function public.xdate_month_leads(int, text, bigint, bigint, int, int) to authenticated;

analyze public.leads;
analyze public.call_records;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261121100000_drivers_xmod_employees.sql
-- ==============================================================================================================

-- Drivers and XMOD on the Business tab, and filtering by employees and XMOD
-- (Sean, Oct 2026):
--
--   drivers             how many drivers run the autos, a whole number (the
--                       Autos section, before Travel radius)
--   xmod                the business's experience MOD on work comp, as
--                       written: .85, 1.50. Over 1 it pays more for work comp.
--
--   employee_count()    a lead's employees (text, as lists write it: "1,200")
--                       as a number, or null for none
--   employees_in()      employees against a range ({ min, max, exclude })
--   call_list_xmod()    XMOD over or under 1 ({ side: "over" | "under" })
--   call_list_matches() as before, with criteria "employees" and "xmod"
--   call_list_options() as before, with how many names have an XMOD over 1
--                       and under it, and the fewest and most employees
--   lead_explore()      as before, with criteria emp_min, emp_max and
--                       emp_not ("1": not in the range)
--
-- call_list_options() and lead_explore() are as the local database had them
-- (20261115100000, 20261113100000), with only these changes.

alter table public.leads
  add column if not exists drivers integer check (drivers between 0 and 100000),
  add column if not exists xmod numeric(4, 2) check (xmod > 0 and xmod < 10);

comment on column public.leads.drivers is 'How many drivers run the business''s autos.';
comment on column public.leads.xmod is 'The experience MOD on work comp (.85, 1.50): over 1 pays more than the rate.';

/** A lead's employees as a number ("1,200" is 1200); null for none or anything that is not a count. */
create or replace function public.employee_count(v text)
returns int
language sql immutable parallel safe set search_path = public as $$
  select case when regexp_replace(coalesce(v, ''), '[\s,]', '', 'g') ~ '^\d{1,7}$'
              then regexp_replace(v, '[\s,]', '', 'g')::int end;
$$;

/**
 * Employees against a range ({ min, max, exclude }, either end left open):
 * with neither end, anything; included, a count in the range; excluded,
 * not in it (a name with no count stays, as with the other criteria).
 */
create or replace function public.employees_in(c jsonb, v text)
returns boolean
language sql immutable parallel safe set search_path = public as $$
  select c is null
      or (coalesce(c ->> 'min', '') !~ '^\d{1,7}$' and coalesce(c ->> 'max', '') !~ '^\d{1,7}$')
      or (coalesce(public.employee_count(v)
                     between case when c ->> 'min' ~ '^\d{1,7}$' then (c ->> 'min')::int else 0 end
                         and case when c ->> 'max' ~ '^\d{1,7}$' then (c ->> 'max')::int else 2147483647 end,
                   false)
          <> coalesce((c ->> 'exclude')::boolean, false));
$$;

/** XMOD over 1 or under it ({ side }); a name with no XMOD is neither. */
create or replace function public.call_list_xmod(c jsonb, v numeric)
returns boolean
language sql immutable parallel safe set search_path = public as $$
  select c is null or coalesce(c ->> 'side', '') not in ('over', 'under')
      or coalesce(case c ->> 'side' when 'over' then v > 1 else v < 1 end, false);
$$;

/** A name's values for each criterion, as call_list_criterion() compares them. */
create or replace function public.call_list_matches(l public.leads, p_xdates date[], p_carriers text[], c jsonb)
returns boolean
language sql stable set search_path = public as $$
  select c is null or c = '{}'::jsonb or (
        public.call_list_renews_in(c -> 'renewal', p_xdates)
    and public.call_list_criterion(c -> 'city', array[lower(btrim(l.city))])
    and public.call_list_criterion(c -> 'zip', array[left(btrim(l.zip), 5)])
    and public.call_list_criterion(c -> 'county', array[lower(btrim(l.county))])
    and public.call_list_criterion(c -> 'sic', array[btrim(l.sic_code)])
    and public.call_list_criterion(c -> 'carrier', p_carriers)
    and public.call_list_criterion(c -> 'year', array[extract(year from l.promoted_at at time zone public.business_tz())::int::text])
    and public.call_list_criterion(c -> 'developer', array[l.dbdv_user_id::text])
    and public.call_list_criterion(c -> 'result', array[l.result_id::text])
    and public.call_list_criterion(c -> 'source', array[lower(btrim(l.list_source))])
    and public.employees_in(c -> 'employees', l.employees)
    and public.call_list_xmod(c -> 'xmod', l.xmod));
$$;

CREATE OR REPLACE FUNCTION public.call_list_options(p_project_id bigint, p_rep bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_rep bigint := coalesce(p_rep, public.app_user_id());
  v     jsonb;
begin
  if v_rep is distinct from public.app_user_id() and not public.is_manager() then
    raise exception 'You can only open your own call list' using errcode = '42501';
  end if;
  with base as (
    select l.* from public.leads l join public.call_results r on r.id = l.result_id
     where l.project_id = p_project_id and l.assigned_user_id = v_rep and r.viable and r.callable
  ), opts as (
    -- Labels as written, a capitalised spelling first ("Phoenix" over "phoenix").
    select 'city' as k, lower(btrim(city)) as value,
           coalesce(min(btrim(city)) filter (where btrim(city) ~ '^[A-Z]'), min(btrim(city))) as label, count(*) as n
      from base where nullif(btrim(city), '') is not null group by 2
    union all
    select 'zip', left(btrim(zip), 5), left(btrim(zip), 5), count(*) from base where nullif(btrim(zip), '') is not null group by 2
    union all
    select 'county', lower(btrim(county)),
           coalesce(min(btrim(county)) filter (where btrim(county) ~ '^[A-Z]'), min(btrim(county))), count(*)
      from base where nullif(btrim(county), '') is not null group by 2
    union all
    select 'sic', btrim(b.sic_code), btrim(b.sic_code) || coalesce(' – ' || min(s.description), ''), count(*)
      from base b left join public.sic_codes s on s.code = btrim(b.sic_code)
     where nullif(btrim(b.sic_code), '') is not null group by 2
    union all
    -- Read in one pass over the names' agencies and policies: one lookup a name (lead_carrier_keys()),
    -- each checking who may see it again, took seconds on a call list of thousands.
    select 'carrier', s.k, min(initcap(s.k)), count(distinct s.id)
      from (select b.id, public.carrier_key(a.name) as k from base b join public.agencies a on a.id = b.agency_id
            union all
            select b.id, public.carrier_key(x)
              from base b join public.insurance_details i on i.lead_id = b.id,
                   unnest(array[i.agency_name, i.pkg_carrier, i.wc_carrier, i.auto_carrier, i.health_carrier, i.dental_provider,
                                i.vision_provider, i.prof_liab_carrier, i.do_carrier, i.eo_carrier, i.homeowner_carrier,
                                i.personal_auto_carrier, i.personal_lines_carrier]) as x) s
     where s.k is not null group by 2
    union all
    select 'year', extract(year from promoted_at at time zone public.business_tz())::int::text,
           extract(year from promoted_at at time zone public.business_tz())::int::text, count(*)
      from base where promoted_at is not null group by 2
    union all
    select 'developer', b.dbdv_user_id::text,
           min(coalesce(nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.email)), count(*)
      from base b join public.users u on u.id = b.dbdv_user_id group by 2
    union all
    select 'result', b.result_id::text, min(r.name), count(*)
      from base b join public.call_results r on r.id = b.result_id group by 2
    union all
    select 'source', lower(btrim(b.list_source)), min(btrim(b.list_source)), count(*)
      from base b where nullif(btrim(b.list_source), '') is not null group by 2
    union all
    -- How many names have an XMOD over 1, and under it.
    select 'xmod', s.side, case s.side when 'over' then 'Over 1.00' else 'Under 1.00' end, count(*)
      from (select case when b.xmod > 1 then 'over' when b.xmod < 1 then 'under' end as side from base b) s
     where s.side is not null group by s.side
    union all
    -- The fewest and most employees on the list, as one item: "3–250".
    select 'employees', min(e.n)::text || '-' || max(e.n)::text, min(e.n)::text || '–' || max(e.n)::text, count(*)
      from (select public.employee_count(b.employees) as n from base b) e
     where e.n is not null having count(*) > 0
  )
  select coalesce(jsonb_object_agg(k, items), '{}'::jsonb) into v
    from (select k, jsonb_agg(jsonb_build_object('value', value, 'label', label, 'count', n) order by label) as items
            from opts group by k) g;
  return v;
end $function$;

CREATE OR REPLACE FUNCTION public.lead_explore(criteria jsonb DEFAULT '{}'::jsonb, page integer DEFAULT 1, per_page integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with c as (
    select
      array(select jsonb_array_elements_text(coalesce(criteria->'sic',       '[]'::jsonb)))          as sic,
      array(select jsonb_array_elements_text(coalesce(criteria->'states',    '[]'::jsonb)))          as states,
      array(select jsonb_array_elements_text(coalesce(criteria->'zips',      '[]'::jsonb)))          as zips,
      array(select jsonb_array_elements_text(coalesce(criteria->'counties',  '[]'::jsonb)))          as counties,
      array(select jsonb_array_elements_text(coalesce(criteria->'results',   '[]'::jsonb)))          as results,
      array(select (jsonb_array_elements_text(coalesce(criteria->'months',   '[]'::jsonb)))::int)    as months,
      array(select (jsonb_array_elements_text(coalesce(criteria->'clients',  '[]'::jsonb)))::bigint) as clients,
      array(select (jsonb_array_elements_text(coalesce(criteria->'projects', '[]'::jsonb)))::bigint) as projects,
      array(select (jsonb_array_elements_text(coalesce(criteria->'groups',   '[]'::jsonb)))::bigint) as groups,
      array(select jsonb_array_elements_text(coalesce(criteria->'carriers',  '[]'::jsonb)))          as carriers,
      array(select (jsonb_array_elements_text(coalesce(criteria->'reps',     '[]'::jsonb)))::bigint) as reps,
      case when criteria->>'emp_min' ~ '^\d{1,7}$' then (criteria->>'emp_min')::int end           as emp_min,
      case when criteria->>'emp_max' ~ '^\d{1,7}$' then (criteria->>'emp_max')::int end           as emp_max,
      coalesce(criteria->>'emp_not', '') = '1'                                                  as emp_not,
      public.search_patterns(public.search_words(criteria->>'q'))    as pats,
      public.search_lead_pattern(public.search_words(criteria->>'q')) as first_pat
  ),
  carrier_keys as (
    select coalesce(array_agg(distinct k) filter (where k is not null), '{}') as keys
      from (
        select public.carrier_key(v) as k from c, unnest(c.carriers) v where v !~ '^[0-9]+$'
        union all
        select public.carrier_key(a.name) from public.agencies a, c
         where a.id::text = any(array(select v from unnest(c.carriers) v where v ~ '^[0-9]{1,18}$'))
      ) t
  ),
  m as (
    select l.id, l.company_name, l.contact_name, l.contact_title, l.phone, l.contact_mobile, l.email,
           l.decision_maker, l.dm_title, l.dm_phone, l.dm_mobile, l.dm_email,
           l.contact2_name, l.contact2_title, l.contact2_phone, l.contact2_mobile, l.contact2_email, l.producer_name,
           l.city, l.state, l.zip, l.county, l.sic_code, l.lead_date,
           ins.ultimate_xdate,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name, grp.name as agency_group,
           coalesce(ag.name, nullif(btrim(ins.agency_name), '')) as carrier_name,
           r.id as result_id, r.name as result_name, r.viable as result_viable,
           l.project_id, p.name as project_name,
           -- When it was last called or changed.
           greatest(l.date_last_worked, l.updated_at) as last_worked,
           nullif(concat_ws(' ', u.first_name, u.last_name), '') as rep_name
      from public.leads l
      cross join c
      cross join carrier_keys ck
      left join public.insurance_details ins on ins.lead_id = l.id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies grp on grp.id = co.agency_group_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.call_results r on r.id = l.result_id
      left join public.users u      on u.id  = l.assigned_user_id
     -- Leads that have been promoted to an appointment project: a name still being developed is not one yet,
     -- whatever renewal dates it carries.
     where l.stage = 'appt'
       and (cardinality(c.sic)      = 0 or l.sic_code         = any(c.sic))
       and (cardinality(c.states)   = 0 or l.state            = any(c.states))
       and (cardinality(c.zips)     = 0 or left(l.zip, 5)     = any(c.zips))
       and (cardinality(c.counties) = 0 or l.county           = any(c.counties))
       and (cardinality(c.results)  = 0 or coalesce(r.name, 'Not called yet') = any(c.results))
       and (cardinality(c.clients)  = 0 or co.id              = any(c.clients))
       and (cardinality(c.projects) = 0 or l.project_id       = any(c.projects))
       and (cardinality(c.groups)   = 0 or co.agency_group_id = any(c.groups))
       and (cardinality(c.carriers) = 0 or public.carrier_key(coalesce(ag.name, ins.agency_name)) = any(ck.keys))
       and (cardinality(c.reps)     = 0 or l.assigned_user_id = any(c.reps))
       -- Employees (the total) in a range, or not in it; a lead with no count is in no range.
       and public.employees_in(jsonb_build_object('min', c.emp_min, 'max', c.emp_max, 'exclude', c.emp_not), l.employees)
       and (cardinality(c.months)   = 0 or extract(month from coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate,
              ins.health_xdate, ins.dental_xdate, ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)))::int = any(c.months))
       -- The longest word first, which the trigram index can answer; then every word.
       and (cardinality(c.pats)     = 0 or (l.search_text like c.first_pat and l.search_text like all (c.pats)))
  ),
  win as (
    select * from m
     order by lead_date desc nulls last, id desc
     limit greatest(least(coalesce(per_page, 10), 10000), 1)
    offset least(greatest(coalesce(page, 1) - 1, 0)::bigint * greatest(least(coalesce(per_page, 10), 10000), 1), 1000000000)
  )
  select jsonb_build_object(
    'total',    (select count(*) from m),
    'rows',     (select coalesce(jsonb_agg(to_jsonb(win)), '[]'::jsonb) from win),
    'by_client', (select coalesce(jsonb_agg(jsonb_build_object('id', t.client_id, 'label', coalesce(t.client_name, 'Unassigned'), 'count', t.n)
                                            order by t.n desc, coalesce(t.client_name, 'zzz')), '[]'::jsonb)
                    from (select client_id, client_name, count(*) as n from m group by client_id, client_name) t),
    'by_state',  (select coalesce(jsonb_agg(jsonb_build_object('label', coalesce(t.state, '—'), 'count', t.n)
                                            order by t.n desc, coalesce(t.state, 'zz')), '[]'::jsonb)
                    from (select state, count(*) as n from m group by state) t),
    'by_month',  (select coalesce(jsonb_agg(jsonb_build_object('month', t.mon, 'label', to_char(to_date(t.mon::text, 'MM'), 'Mon'), 'count', t.n)
                                            order by t.mon), '[]'::jsonb)
                    from (select extract(month from renewal_date)::int as mon, count(*) as n
                            from m where renewal_date is not null group by 1) t),
    'by_industry', (select coalesce(jsonb_agg(jsonb_build_object('code', t.sic_code, 'label', coalesce(s.description, t.sic_code, '—'), 'count', t.n)
                                              order by t.n desc), '[]'::jsonb)
                      from (select sic_code, count(*) as n from m group by sic_code) t
                      left join public.sic_codes s on s.code = t.sic_code),
    'by_result', (select coalesce(jsonb_agg(jsonb_build_object('label', t.label, 'count', t.n)
                                            order by t.n desc, t.label), '[]'::jsonb)
                    from (select coalesce(result_name, 'Not called yet') as label, count(*) as n from m group by 1) t),
    'clients_touched', (select count(distinct client_id) from m where client_id is not null),
    'with_xdate',      (select count(*) from m where renewal_date is not null),
    -- Still to call for an appointment: a call result that leaves the lead viable (none yet counts).
    'viable',          (select count(*) from m where coalesce(result_viable, true))
  );
$function$;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261122100000_appointment_confirm_reminders.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a reminder the day before to confirm an appointment
-- (Sean, Oct 2026)
--
-- A manager calls the business back the day before an appointment to confirm
-- it. Each appointment they set now brings its own reminder: at 9:00 AM (the
-- business's time) the day before, a notification "Confirm tomorrow's
-- appointment: <company>", also on their own calendar like any reminder.
-- Moved with the appointment, gone once it is confirmed, found invalid or
-- deleted; none when that morning has already passed (set this afternoon for
-- tomorrow: they have just spoken).
--
--   reminders.appointment_id   the appointment a reminder is for (null: a
--                              call-back reminder a person set)
--   appointment_confirm_reminder()   keeps it in step (trigger)
--   deliver_reminders()        as before, with the confirm reminder's wording
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

alter table public.reminders
  add column if not exists appointment_id bigint references public.appointments(id) on delete cascade;
create unique index if not exists reminders_appointment_unsent
  on public.reminders (appointment_id) where appointment_id is not null and sent_at is null;

/** The appointment's confirm reminder, as it now stands: removed, then set again if it should be. */
create or replace function public.appointment_confirm_reminder()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_tz  text := public.business_tz();
  v_at  timestamptz;
begin
  delete from public.reminders where appointment_id = new.id and sent_at is null;
  if new.user_id is null or new.lead_id is null or new.appt_date is null
     or new.confirmed_at is not null or new.invalid_at is not null or new.deleted_at is not null then
    return new;
  end if;
  v_at := ((new.appt_date - 1)::timestamp + time '09:00') at time zone v_tz;
  if v_at <= now() then
    return new;
  end if;
  insert into public.reminders (lead_id, user_id, remind_at, note, appointment_id)
  values (new.lead_id, new.user_id, v_at,
          left('Appointment ' || to_char(new.appt_date, 'FMDy, Mon FMDD') || coalesce(' at ' || new.appt_time, '')
               || ': call the business to confirm it', 300),
          new.id);
  return new;
end $$;
revoke execute on function public.appointment_confirm_reminder() from public, anon, authenticated;

drop trigger if exists appointment_confirm_reminder on public.appointments;
create trigger appointment_confirm_reminder
  after insert or update of appt_date, appt_time, user_id, lead_id, confirmed_at, invalid_at, deleted_at
  on public.appointments
  for each row execute function public.appointment_confirm_reminder();

/** Due reminders become notifications: a call-back's as before; an appointment's asks to confirm it. */
create or replace function public.deliver_reminders()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r     record;
  v_id  bigint;
  n     integer := 0;
begin
  for r in
    select m.id, m.user_id, m.lead_id, m.note, m.remind_at, m.appointment_id, l.company_name
      from public.reminders m
      join public.leads l on l.id = m.lead_id and l.deleted_at is null
     where m.sent_at is null and m.remind_at <= now()
     order by m.remind_at
     for update of m skip locked
  loop
    insert into public.notifications (user_id, kind, title, body, link)
    values (
      r.user_id, 'reminder',
      left(case when r.appointment_id is not null then 'Confirm tomorrow''s appointment: ' else 'Call back: ' end
           || coalesce(r.company_name, 'a lead'), 120),
      left(case when r.appointment_id is not null then coalesce(r.note, '')
                else concat_ws(' · ', 'Reminder for ' || to_char(r.remind_at at time zone public.business_tz(), 'FMHH12:MI AM'), r.note) end, 1000),
      '/leads/' || r.lead_id
    )
    returning id into v_id;
    update public.reminders set sent_at = now(), notification_id = v_id where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke execute on function public.deliver_reminders() from public, anon, authenticated;

-- The appointments already set and still to confirm get theirs.
insert into public.reminders (lead_id, user_id, remind_at, note, appointment_id)
select a.lead_id, a.user_id, ((a.appt_date - 1)::timestamp + time '09:00') at time zone public.business_tz(),
       left('Appointment ' || to_char(a.appt_date, 'FMDy, Mon FMDD') || coalesce(' at ' || a.appt_time, '')
            || ': call the business to confirm it', 300),
       a.id
  from public.appointments a
 where a.user_id is not null and a.lead_id is not null and a.appt_date is not null
   and a.confirmed_at is null and a.invalid_at is null and a.deleted_at is null
   and ((a.appt_date - 1)::timestamp + time '09:00') at time zone public.business_tz() > now()
   and not exists (select 1 from public.reminders m where m.appointment_id = a.id and m.sent_at is null);

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261123100000_client_dashboard.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the client's dashboard, top row (Sean, Oct 2026)
--
--   1  Leads Developed      every name on their projects (whatever its call
--                           result), over 1 week, 1/3/6 months or all time,
--                           and how many on each project
--   2  Appointments Set     over the same days, as a share of those leads
--   3  Appointment Results  each appointment's outcome as the client records
--                           it: Pending (until they do), Quoting, Quoted-Not
--                           Sold, Valid-Not Quoting, Invalid Appointment, Sold
--   4  Upcoming Pipeline    viable names renewing in each of the next 3 or 6
--                           months (not the one we are in)
--
-- Row two, 1  Sale Pipeline   what the client records from our appointments:
--                              premium written (sold, this year), in the pipe
--                              (quoted on those still quoting), their annual
--                              goal, and their close ratio (sold of pending,
--                              quoting, quoted-not sold and sold), with the
--                              premium written month by month, like a ticker
--
-- Administrators see 3 and 4, and the Sale Pipeline, on a client's page: the
-- same figures, for that client.
--
--   appointments.client_result     the client's outcome (null: Pending)
--   appointments.client_result_at  when they recorded it, and who:
--   appointments.client_result_by
--   client_dashboard(p_from, p_company_id)   tiles 1 to 3
--   client_pipeline(p_months, p_company_id)  tile 4
--   appointments.quoted_premium    the premium quoted, and written (sold), as
--   appointments.written_premium   the client records them
--   client_goals                   each client's premium goal for a year
--   set_client_goal(p_company_id, p_year, p_goal)   the client's, or an administrator's
--   client_sales(p_company_id)     the Sale Pipeline
--   client_activity(...)           row three, Recent Activity: the leads and
--                                  appointments developed on their projects,
--                                  as the client may see them (no pay)
--
-- Both read as the person asking (a client sees only their own projects, and
-- only the appointments QA let through). Safe to run again.
-- ---------------------------------------------------------------------------

alter table public.appointments
  add column if not exists client_result text
    check (client_result in ('pending', 'quoting', 'quoted_not_sold', 'valid_not_quoting', 'invalid', 'sold')),
  add column if not exists client_result_at timestamptz,
  add column if not exists client_result_by bigint references public.users(id) on delete set null;

alter table public.appointments
  add column if not exists quoted_premium numeric(12, 2) check (quoted_premium >= 0),
  add column if not exists written_premium numeric(12, 2) check (written_premium >= 0);

comment on column public.appointments.client_result is
  'The appointment''s outcome as the client records it: pending (or null), quoting, quoted_not_sold, valid_not_quoting, invalid, sold.';

/** Tiles 1 to 3: leads, appointments and their results since p_from (null: all time), for one client or all the caller sees. */
create or replace function public.client_dashboard(p_from date default null, p_company_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), p as (
    select pr.id, pr.name from public.projects pr
     where pr.deleted_at is null and (p_company_id is null or pr.company_id = p_company_id)
  ), l as (
    select le.project_id from public.leads le, z
     where le.project_id in (select id from p)
       and (p_from is null or coalesce(le.lead_date, le.created_at) >= (p_from::timestamp at time zone z.tz))
  ), a as (
    -- As the client sees them: through QA, not invalid.
    select coalesce(ap.client_result, 'pending') as result from public.appointments ap, z
     where coalesce(ap.project_id, ap.set_project_id) in (select id from p)
       and ap.invalid_at is null and coalesce(ap.qa_status, 'passed') = 'passed'
       and (p_from is null or ap.created_at >= (p_from::timestamp at time zone z.tz))
  )
  select jsonb_build_object(
    'leads', (select count(*) from l),
    'projects', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'leads', coalesce(c.n, 0))
                                           order by coalesce(c.n, 0) desc, p.name), '[]'::jsonb)
                   from p left join (select project_id, count(*) as n from l group by project_id) c on c.project_id = p.id),
    'appts', (select count(*) from a),
    'results', (select jsonb_build_object(
                  'pending', count(*) filter (where result = 'pending'),
                  'quoting', count(*) filter (where result = 'quoting'),
                  'quoted_not_sold', count(*) filter (where result = 'quoted_not_sold'),
                  'valid_not_quoting', count(*) filter (where result = 'valid_not_quoting'),
                  'invalid', count(*) filter (where result = 'invalid'),
                  'sold', count(*) filter (where result = 'sold')) from a)
  );
$$;
revoke execute on function public.client_dashboard(date, bigint) from public, anon;
grant execute on function public.client_dashboard(date, bigint) to authenticated;

/**
 * Tile 4: the viable names (still to call) renewing in each of the next p_months months, the month
 * we are in left out. A renewal date is a month of the year (they come round every year).
 */
create or replace function public.client_pipeline(p_months int default 3, p_company_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), m as (
    select i, (date_trunc('month', now() at time zone z.tz) + (i * interval '1 month'))::date as first
      from z, generate_series(1, greatest(least(coalesce(p_months, 3), 12), 1)) as i
  ), v as (
    select extract(month from ren.renewal)::int as month
      from public.leads le
      join public.call_results r on r.id = le.result_id and r.viable
      join public.projects pr on pr.id = le.project_id and pr.deleted_at is null
      left join lateral (
        select min(coalesce(i.ultimate_xdate,
                            least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                  i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate))) as renewal
          from public.insurance_details i where i.lead_id = le.id
      ) ren on true
     where (p_company_id is null or pr.company_id = p_company_id) and ren.renewal is not null
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'key', to_char(m.first, 'YYYY-MM'), 'label', to_char(m.first, 'Mon'),
           'leads', (select count(*) from v where v.month = extract(month from m.first)::int)
         ) order by m.i), '[]'::jsonb)
    from m;
$$;
revoke execute on function public.client_pipeline(int, bigint) from public, anon;
grant execute on function public.client_pipeline(int, bigint) to authenticated;

-- Each client's premium goal for a year (from our appointments).
create table if not exists public.client_goals (
  company_id   bigint not null references public.companies(id) on delete cascade,
  year         int not null check (year between 2000 and 2100),
  premium_goal numeric(14, 2) not null check (premium_goal >= 0),
  updated_at   timestamptz not null default now(),
  updated_by   bigint references public.users(id) on delete set null,
  primary key (company_id, year)
);
alter table public.client_goals enable row level security;
revoke all on public.client_goals from anon;
revoke insert, update, delete, truncate on public.client_goals from authenticated;
grant select on public.client_goals to authenticated;
drop policy if exists client_goals_read on public.client_goals;
create policy client_goals_read on public.client_goals for select to authenticated
  using ((select public.is_staff()) or company_id = (select public.app_company_id()));
drop policy if exists active_account_required on public.client_goals;
create policy active_account_required on public.client_goals as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null);
drop policy if exists mfa_required on public.client_goals;
create policy mfa_required on public.client_goals as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));

/** A client's premium goal for a year: their own (a client), or any client's (an administrator). */
create or replace function public.set_client_goal(p_company_id bigint, p_year int, p_goal numeric)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
begin
  if v_me is null or not (public.is_admin() or p_company_id = public.app_company_id()) then
    raise exception 'Only the client or an administrator can set this goal' using errcode = '42501';
  end if;
  if p_goal is null or p_goal < 0 or p_goal > 999999999999 then
    raise exception 'Enter the goal as an amount' using errcode = '22023';
  end if;
  insert into public.client_goals (company_id, year, premium_goal, updated_at, updated_by)
  values (p_company_id, p_year, round(p_goal, 2), now(), v_me)
  on conflict (company_id, year) do update set premium_goal = excluded.premium_goal, updated_at = now(), updated_by = v_me;
end $$;
revoke execute on function public.set_client_goal(bigint, int, numeric) from public, anon;
grant execute on function public.set_client_goal(bigint, int, numeric) to authenticated;

/**
 * The Sale Pipeline for one client (an administrator) or the caller's own (a client): premium
 * written this year (sold, by when they marked it), in the pipe (quoted, on those still quoting),
 * the year's goal, the close ratio (sold of pending, quoting, quoted-not sold and sold), and the
 * premium written in each month of the year.
 */
create or replace function public.client_sales(p_company_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz, extract(year from now() at time zone public.business_tz())::int as yr
  ), co as (
    select coalesce(p_company_id, public.app_company_id()) as id
  ), a as (
    select coalesce(ap.client_result, 'pending') as result, ap.quoted_premium, ap.written_premium,
           (ap.client_result_at at time zone z.tz) as at
      from public.appointments ap
      join public.projects pr on pr.id = coalesce(ap.project_id, ap.set_project_id) and pr.deleted_at is null, z, co
     where pr.company_id = co.id
       and ap.invalid_at is null and coalesce(ap.qa_status, 'passed') = 'passed'
  ), sold as (
    select a.written_premium, a.at from a, z where a.result = 'sold' and extract(year from a.at)::int = z.yr
  )
  select jsonb_build_object(
    'year', (select yr from z),
    'written', (select coalesce(sum(written_premium), 0) from sold),
    'pipe', (select coalesce(sum(quoted_premium), 0) from a where result = 'quoting'),
    'goal', (select g.premium_goal from public.client_goals g, co, z where g.company_id = co.id and g.year = z.yr),
    'sold', (select count(*) from a where result = 'sold'),
    'considered', (select count(*) from a where result in ('pending', 'quoting', 'quoted_not_sold', 'sold')),
    'months', (select jsonb_agg(jsonb_build_object(
                 'month', m, 'label', to_char(make_date(z.yr, m, 1), 'Mon'),
                 'written', (select coalesce(sum(written_premium), 0) from sold where extract(month from sold.at)::int = m)
               ) order by m) from z, generate_series(1, 12) m)
  );
$$;
revoke execute on function public.client_sales(bigint) from public, anon;
grant execute on function public.client_sales(bigint) to authenticated;

/**
 * Recent Activity (Sean, Oct 2026): the leads and appointments developed on the caller's projects
 * (a client's; an administrator's: any, or p_company_id's) from p_from to p_to (the business's days),
 * newest first: the name, its project, the agent, when, what it was (Lead; an appointment as
 * Appointment, Appointment-Confirmed or Appointment-Invalid), its X-date and the manager. Read from
 * what developed them, without what it paid; an appointment only once QA has let it through.
 */
create or replace function public.client_activity(p_from date, p_to date, p_project_id bigint default null,
  p_kind text default null, p_company_id bigint default null)
returns table (id bigint, at timestamptz, kind text, result text, lead_id bigint, company text, city text, state text,
  project_id bigint, project text, agent text, manager text, xdate date)
language sql stable security definer set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), mine as (
    select p.id from public.projects p
     where p.deleted_at is null
       and (case when public.is_staff() then (p_company_id is null or p.company_id = p_company_id)
                 else p.id in (select public.client_project_ids()) end)
       and (p_project_id is null or p.id = p_project_id)
  )
  select e.id, e.created_at, e.kind,
         case when e.kind = 'lead' then 'Lead'
              when ap.invalid_at is not null then 'Appointment-Invalid'
              when ap.confirmed_at is not null then 'Appointment-Confirmed'
              else 'Appointment' end,
         l.id, l.company_name, l.city, l.state, pr.id, pr.name,
         coalesce(nullif(btrim(ap.rep_name), ''), nullif(btrim(pr.contact_name), '')),
         nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''),
         (select min(coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                                      i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)))
            from public.insurance_details i where i.lead_id = l.id)
    from public.pay_events e
    join public.leads l on l.id = e.lead_id and l.deleted_at is null
    join public.projects pr on pr.id = coalesce(e.project_id, l.project_id)
    left join public.appointments ap on ap.id = e.appointment_id
    left join public.users u on u.id = e.user_id, z
   where public.app_user_id() is not null
     and pr.id in (select id from mine)
     and e.kind in ('lead', 'appointment') and not e.is_chargeback
     and (p_kind is null or e.kind = p_kind)
     and e.created_at >= (p_from::timestamp at time zone z.tz)
     and e.created_at < ((p_to + 1)::timestamp at time zone z.tz)
     and (e.kind = 'lead' or coalesce(ap.qa_status, 'passed') = 'passed')
   order by e.created_at desc, e.id desc
   limit 1000;
$$;
revoke execute on function public.client_activity(date, date, bigint, text, bigint) from public, anon;
grant execute on function public.client_activity(date, date, bigint, text, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261124100000_client_dashboard_leads.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the client's Leads Developed counts leads (Sean, Oct 2026)
--
-- Tile 1 counted every name on a client's projects, so a DB dev list read as
-- its names still to call (6,911) rather than the leads it developed. Now:
--
--   leads     the names that became leads on their projects (at the
--             appointment stage, active or resolved: what lead_stats() calls
--             a project's leads), over the days chosen by when each became one
--   projects  their DB dev projects only, each with the leads it developed
--             (the names it sent on, and any at the appointment stage on it)
--
--   appts     the names whose result is an appointment (set, confirmed or
--             invalid), once each however often it was moved or set again:
--             what the client's projects show as their appointments (257)
--   results   for each of those names, its latest appointment's outcome as the
--             client records it (Pending until then); Invalid when the name's
--             result is Appointment-Invalid
--
--   client_pipeline()   tile 4 reads the viable names (not appointments) by
--                       renewal month, as the X-Dates report's Viable left
--   client_activity()   with the manager's id, to message them
--   message_manager()   Recent Activity: a client sends the manager who
--                       developed a lead a note about it, as a message
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

create or replace function public.client_dashboard(p_from date default null, p_company_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), p as (
    select pr.id, pr.name, t.code as type from public.projects pr
      left join public.project_types t on t.id = pr.project_type_id
     where pr.deleted_at is null and (p_company_id is null or pr.company_id = p_company_id)
  ), l as (
    -- A lead: a name at the appointment stage, dated by when it became one.
    select le.id, le.project_id, le.source_project_id, r.effect, le.appt_created_date, le.promoted_at, le.lead_date, le.created_at
      from public.leads le join public.call_results r on r.id = le.result_id
     where le.stage = 'appt'
       and (le.project_id in (select id from p) or le.source_project_id in (select id from p))
  ), lp as (
    select l.* from l, z
     where p_from is null or coalesce(l.promoted_at, l.lead_date, l.created_at) >= (p_from::timestamp at time zone z.tz)
  ), a as (
    -- An appointment: a name whose result is one (set, confirmed or invalid), once each, dated by when it was set.
    select l.id, l.effect,
           (select ap.client_result from public.appointments ap where ap.lead_id = l.id order by ap.created_at desc, ap.id desc limit 1) as client_result
      from l, z
     where l.project_id in (select id from p)
       and l.effect in ('appointment', 'confirm', 'appointment_invalid')
       and (p_from is null or coalesce(l.appt_created_date, l.promoted_at, l.lead_date, l.created_at) >= (p_from::timestamp at time zone z.tz))
  ), ar as (
    select case when effect = 'appointment_invalid' then 'invalid' else coalesce(client_result, 'pending') end as result from a
  )
  select jsonb_build_object(
    'leads', (select count(*) from lp where lp.project_id in (select id from p)),
    'projects', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name,
                                   'leads', (select count(*) from lp where lp.source_project_id = p.id or lp.project_id = p.id))
                                 order by p.name), '[]'::jsonb)
                   from p where p.type = 'DBDV'),
    'appts', (select count(*) from a),
    'results', (select jsonb_build_object(
                  'pending', count(*) filter (where result = 'pending'),
                  'quoting', count(*) filter (where result = 'quoting'),
                  'quoted_not_sold', count(*) filter (where result = 'quoted_not_sold'),
                  'valid_not_quoting', count(*) filter (where result = 'valid_not_quoting'),
                  'invalid', count(*) filter (where result = 'invalid'),
                  'sold', count(*) filter (where result = 'sold')) from ar)
  );
$$;
revoke execute on function public.client_dashboard(date, bigint) from public, anon;
grant execute on function public.client_dashboard(date, bigint) to authenticated;

/**
 * Tile 4: the viable names renewing in each of the next p_months months (not this one), counted as
 * the X-Dates report counts its Viable left: a viable result that is not an appointment, on every
 * project of theirs (the names still to call and the leads alike).
 */
create or replace function public.client_pipeline(p_months int default 3, p_company_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), m as (
    select i, (date_trunc('month', now() at time zone z.tz) + (i * interval '1 month'))::date as first
      from z, generate_series(1, greatest(least(coalesce(p_months, 3), 12), 1)) as i
  ), x as (
    select * from public.xdates_by_month(null, p_company_id)
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'key', to_char(m.first, 'YYYY-MM'), 'label', to_char(m.first, 'Mon'),
           'leads', coalesce((select x.viable_left from x where x.month = extract(month from m.first)::int), 0)
         ) order by m.i), '[]'::jsonb)
    from m;
$$;
revoke execute on function public.client_pipeline(int, bigint) from public, anon;
grant execute on function public.client_pipeline(int, bigint) to authenticated;

-- Recent Activity, with the manager's id (the row it returns changes, so it is made again).
drop function if exists public.client_activity(date, date, bigint, text, bigint);
create function public.client_activity(p_from date, p_to date, p_project_id bigint default null,
  p_kind text default null, p_company_id bigint default null)
returns table (id bigint, at timestamptz, kind text, result text, lead_id bigint, company text, city text, state text,
  project_id bigint, project text, agent text, manager text, xdate date, manager_id bigint)
language sql stable security definer set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), mine as (
    select p.id from public.projects p
     where p.deleted_at is null
       and (case when public.is_staff() then (p_company_id is null or p.company_id = p_company_id)
                 else p.id in (select public.client_project_ids()) end)
       and (p_project_id is null or p.id = p_project_id)
  )
  select e.id, e.created_at, e.kind,
         case when e.kind = 'lead' then 'Lead'
              when ap.invalid_at is not null then 'Appointment-Invalid'
              when ap.confirmed_at is not null then 'Appointment-Confirmed'
              else 'Appointment' end,
         l.id, l.company_name, l.city, l.state, pr.id, pr.name,
         coalesce(nullif(btrim(ap.rep_name), ''), nullif(btrim(pr.contact_name), '')),
         nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''),
         (select min(coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                                      i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)))
            from public.insurance_details i where i.lead_id = l.id),
         case when u.status = 'active' then u.id end
    from public.pay_events e
    join public.leads l on l.id = e.lead_id and l.deleted_at is null
    join public.projects pr on pr.id = coalesce(e.project_id, l.project_id)
    left join public.appointments ap on ap.id = e.appointment_id
    left join public.users u on u.id = e.user_id, z
   where public.app_user_id() is not null
     and pr.id in (select id from mine)
     and e.kind in ('lead', 'appointment') and not e.is_chargeback
     and (p_kind is null or e.kind = p_kind)
     and e.created_at >= (p_from::timestamp at time zone z.tz)
     and e.created_at < ((p_to + 1)::timestamp at time zone z.tz)
     and (e.kind = 'lead' or coalesce(ap.qa_status, 'passed') = 'passed')
   order by e.created_at desc, e.id desc
   limit 1000;
$$;
revoke execute on function public.client_activity(date, date, bigint, text, bigint) from public, anon;
grant execute on function public.client_activity(date, date, bigint, text, bigint) to authenticated;

/**
 * A note about a lead to the manager who developed it (Recent Activity, Sean, Oct 2026): from a
 * client, on a name of their own projects, to a manager who developed it or works its list; as a
 * message in the manager's notifications, linked to the lead, that they can reply to.
 */
create or replace function public.message_manager(p_lead_id bigint, p_manager_id bigint, p_body text)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me    public.users;
  v_body  text := btrim(coalesce(p_body, ''));
  v_lead  public.leads;
  v_sent  int;
begin
  select * into v_me from public.users where id = public.app_user_id();
  if v_me.id is null then
    raise exception 'Sign in to send a message' using errcode = '42501';
  end if;
  if length(v_body) = 0 then
    raise exception 'Write your message first' using errcode = '22023';
  end if;
  if length(v_body) > 1000 then
    raise exception 'Keep a message under 1,000 characters' using errcode = '22023';
  end if;
  select * into v_lead from public.leads where id = p_lead_id and deleted_at is null;
  if v_lead.id is null or not (public.is_staff() or v_lead.project_id in (select public.client_project_ids())
                                 or v_lead.source_project_id in (select public.client_project_ids())) then
    raise exception 'That lead is not on your projects' using errcode = '42501';
  end if;
  if not exists (select 1 from public.users u where u.id = p_manager_id and u.status = 'active' and u.role in ('admin', 'manager', 'agent'))
     or not (exists (select 1 from public.pay_events e where e.lead_id = p_lead_id and e.user_id = p_manager_id)
             or p_manager_id in (v_lead.assigned_user_id, v_lead.dbdv_user_id)) then
    raise exception 'That manager did not work this lead' using errcode = '42501';
  end if;
  -- One a minute or so is plenty: not a way to flood a manager.
  if (select count(*) from public.notifications where sender_id = v_me.id and kind = 'message' and created_at > now() - interval '1 minute') >= 5 then
    raise exception 'You are sending messages too quickly. Wait a moment and try again.' using errcode = '22023';
  end if;
  v_sent := public.notify_users(array[p_manager_id], 'message',
    left('Message from ' || coalesce(nullif(btrim(concat_ws(' ', v_me.first_name, v_me.last_name)), ''), v_me.email) || ': ' || coalesce(v_lead.company_name, 'a lead'), 160),
    v_body, '/leads/' || v_lead.id, null, gen_random_uuid(), v_me.id);
  return v_sent;
end $$;
revoke execute on function public.message_manager(bigint, bigint, text) from public, anon;
grant execute on function public.message_manager(bigint, bigint, text) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261125100000_team_branding_goals.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — what the old system had that was still to come (Sean, Oct 2026)
--
--   public-images        a public bucket for pictures anyone signed in may see:
--                        staff photos (user/<id>/…) and client logos
--                        (company/<id>/…); each person adds their own photo,
--                        a client's people their company's logo, an
--                        administrator any
--   users                photo_path and a line about themselves (bio), for
--                        Meet the Team
--   companies            logo_path: the client's logo, shown in their workspace
--   team_directory()     Meet the Team: the active staff, with their photos;
--                        for a client, those who work their projects first
--   set_company_branding()  a client's people set their logo and website
--   projects             lead_goal and appt_goal: what the project is to
--                        deliver between its start and end dates
--   hourly_progress()    one person's day by the hour: calls, leads and
--                        appointments; with the month so far
--   calendar_notes       a note on a time of day on a project's calendar
--                        ("Hour Text" in the old system): it says something
--                        about the time, without blocking it
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

-- --- Pictures ----------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('public-images', 'public-images', true, 2097152, array['image/png', 'image/jpeg', 'image/webp'])
on conflict (id) do update set public = true, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- Whose a path is: user/<id>/… is that person's; company/<id>/… that client's people's. Administrators, any.
create or replace function public.can_write_image(p_name text)
returns boolean
language sql stable security definer set search_path = public as $$
  select public.app_user_id() is not null and (
    public.is_admin()
    or ((storage.foldername(p_name))[1] = 'user' and (storage.foldername(p_name))[2] = public.app_user_id()::text)
    or ((storage.foldername(p_name))[1] = 'company' and public.app_role() = 'client'
        and (storage.foldername(p_name))[2] = public.app_company_id()::text));
$$;
revoke execute on function public.can_write_image(text) from public, anon;
grant execute on function public.can_write_image(text) to authenticated;

drop policy if exists public_images_read on storage.objects;
create policy public_images_read on storage.objects for select to authenticated
  using (bucket_id = 'public-images');
drop policy if exists public_images_insert on storage.objects;
create policy public_images_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'public-images' and public.can_write_image(name));
drop policy if exists public_images_update on storage.objects;
create policy public_images_update on storage.objects for update to authenticated
  using (bucket_id = 'public-images' and public.can_write_image(name))
  with check (bucket_id = 'public-images' and public.can_write_image(name));
drop policy if exists public_images_delete on storage.objects;
create policy public_images_delete on storage.objects for delete to authenticated
  using (bucket_id = 'public-images' and public.can_write_image(name));

-- A photo and a line about themselves. Kept as the path in the bucket, never any address.
alter table public.users add column if not exists photo_path text;
alter table public.users add column if not exists bio text;
alter table public.users drop constraint if exists users_photo_path_check;
alter table public.users add constraint users_photo_path_check
  check (photo_path is null or photo_path ~ ('^user/' || id || '/[A-Za-z0-9._-]{1,80}$'));
alter table public.users drop constraint if exists users_bio_check;
alter table public.users add constraint users_bio_check check (bio is null or length(bio) <= 280);

alter table public.companies add column if not exists logo_path text;
alter table public.companies drop constraint if exists companies_logo_path_check;
alter table public.companies add constraint companies_logo_path_check
  check (logo_path is null or logo_path ~ ('^company/' || id || '/[A-Za-z0-9._-]{1,80}$'));

/**
 * Meet the Team: everyone on staff who is active, with their photo and a line
 * about themselves; no email or phone. For a client, `mine` marks those who
 * have worked their projects (developed a lead or set an appointment on them,
 * are assigned to them, or have names on them to call), shown first.
 */
create or replace function public.team_directory()
returns table (id bigint, name text, role text, photo_path text, bio text, mine boolean)
language sql stable security definer set search_path = public as $$
  with me as (
    select public.app_user_id() as uid, public.app_role() as role
  ), theirs as (
    select distinct x.user_id from (
      select e.user_id from public.pay_events e
       where e.project_id in (select public.client_project_ids()) and not e.is_chargeback
      union all
      select pa.ae_user_id from public.project_assignments pa
       where pa.project_id in (select public.client_project_ids())
    ) x, me
     where me.role = 'client' and x.user_id is not null
  )
  select u.id, nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.role, u.photo_path, u.bio,
         u.id in (select user_id from theirs)
    from public.users u, me
   where me.uid is not null
     and u.role in ('admin', 'manager', 'agent') and u.status = 'active' and u.deleted_at is null
   order by 6 desc, u.first_name, u.last_name;
$$;
revoke execute on function public.team_directory() from public, anon;
grant execute on function public.team_directory() to authenticated;

/**
 * A client's people set their company's logo (a picture they put in the
 * bucket under company/<their company>/) and website. Either may be cleared;
 * an administrator does the same for any client from its page.
 */
create or replace function public.set_company_branding(p_logo_path text, p_website text, p_company_id bigint default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_company bigint := case when public.is_admin() then coalesce(p_company_id, public.app_company_id()) else public.app_company_id() end;
  v_site    text := nullif(btrim(coalesce(p_website, '')), '');
  v_logo    text := nullif(btrim(coalesce(p_logo_path, '')), '');
begin
  if public.app_user_id() is null or v_company is null or not (public.is_admin() or public.app_role() = 'client') then
    raise exception 'Only a client''s own people, or an administrator, can change its branding' using errcode = '42501';
  end if;
  if v_site is not null then
    if v_site !~* '^https?://' then
      v_site := 'https://' || v_site;
    end if;
    if length(v_site) > 200 or v_site !~* '^https?://[a-z0-9-]+(\.[a-z0-9-]+)+(:[0-9]+)?(/[^\s<>"]*)?$' then
      raise exception 'That website does not look right: try www.yourcompany.com' using errcode = '22023';
    end if;
  end if;
  if v_logo is not null and v_logo !~ ('^company/' || v_company || '/[A-Za-z0-9._-]{1,80}$') then
    raise exception 'That logo is not this client''s' using errcode = '42501';
  end if;
  update public.companies set logo_path = v_logo, website = v_site, updated_at = now() where id = v_company;
  return jsonb_build_object('company_id', v_company, 'logo_path', v_logo, 'website', v_site);
end $$;
revoke execute on function public.set_company_branding(text, text, bigint) from public, anon;
grant execute on function public.set_company_branding(text, text, bigint) to authenticated;

-- --- Project goals -------------------------------------------------------------
alter table public.projects add column if not exists lead_goal int;
alter table public.projects add column if not exists appt_goal int;
alter table public.projects drop constraint if exists projects_lead_goal_check;
alter table public.projects add constraint projects_lead_goal_check check (lead_goal is null or lead_goal between 0 and 1000000);
alter table public.projects drop constraint if exists projects_appt_goal_check;
alter table public.projects add constraint projects_appt_goal_check check (appt_goal is null or appt_goal between 0 and 1000000);

-- --- Hourly progress -------------------------------------------------------------
/**
 * One person's day by the hour (business time): calls made, leads developed
 * and appointments set, as the production report counts them; their first and
 * last call; and the month so far. Administrators and managers see anyone's,
 * agents their own.
 */
create or replace function public.hourly_progress(p_user_id bigint, p_day date)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz   text := public.business_tz();
  v_lo   timestamptz := p_day::timestamp at time zone v_tz;
  v_hi   timestamptz := (p_day + 1)::timestamp at time zone v_tz;
  v_mlo  timestamptz := date_trunc('month', p_day)::timestamp at time zone v_tz;
  v      jsonb;
begin
  if public.app_user_id() is null or not public.is_staff() then
    raise exception 'Only staff see hourly progress' using errcode = '42501';
  end if;
  if not public.is_manager() and p_user_id is distinct from public.app_user_id() then
    raise exception 'You can see your own hourly progress' using errcode = '42501';
  end if;
  if p_day is null then
    raise exception 'Choose a day' using errcode = '22023';
  end if;

  with c as (
    select extract(hour from c.call_date at time zone v_tz)::int as h, c.call_date
      from public.call_records c
     where c.user_id = p_user_id and c.call_date >= v_lo and c.call_date < v_hi
  ), e as (
    select extract(hour from e.created_at at time zone v_tz)::int as h, e.kind
      from public.pay_events e
     where e.user_id = p_user_id and e.kind in ('lead', 'appointment') and not e.is_chargeback
       and e.created_at >= v_lo and e.created_at < v_hi
  ), hours as (
    select h from c union select h from e
  )
  select jsonb_build_object(
    'hours', coalesce((select jsonb_agg(jsonb_build_object(
                'hour', hours.h,
                'calls', (select count(*) from c where c.h = hours.h),
                'leads', (select count(*) from e where e.h = hours.h and e.kind = 'lead'),
                'appointments', (select count(*) from e where e.h = hours.h and e.kind = 'appointment'))
              order by hours.h) from hours), '[]'::jsonb),
    'first', (select min(call_date) from c),
    'last', (select max(call_date) from c),
    'month', jsonb_build_object(
      'calls', (select count(*) from public.call_records c2
                 where c2.user_id = p_user_id and c2.call_date >= v_mlo and c2.call_date < v_hi),
      'leads', (select count(*) from public.pay_events e2
                 where e2.user_id = p_user_id and e2.kind = 'lead' and not e2.is_chargeback and e2.created_at >= v_mlo and e2.created_at < v_hi),
      'appointments', (select count(*) from public.pay_events e2
                 where e2.user_id = p_user_id and e2.kind = 'appointment' and not e2.is_chargeback and e2.created_at >= v_mlo and e2.created_at < v_hi))
  ) into v;
  return v;
end $$;
revoke execute on function public.hourly_progress(bigint, date) from public, anon;
grant execute on function public.hourly_progress(bigint, date) to authenticated;

-- --- Notes on a calendar's times ---------------------------------------------------
create table if not exists public.calendar_notes (
  id          bigint generated always as identity primary key,
  project_id  bigint not null references public.projects(id) on delete cascade,
  on_date     date not null,
  at_time     time not null,
  body        text not null check (length(btrim(body)) between 1 and 300),
  created_by  bigint references public.users(id) on delete set null,
  created_at  timestamptz not null default now()
);
create index if not exists calendar_notes_project on public.calendar_notes (project_id, on_date);

-- Kept on the calendar's own project (a DB dev project shares its appointment project's), and signed.
create or replace function public.tg_calendar_notes_place()
returns trigger
language plpgsql set search_path = public as $$
begin
  new.project_id := coalesce(public.calendar_project(new.project_id), new.project_id);
  if current_user = 'authenticated' then
    new.created_by := public.app_user_id();
    new.created_at := now();
  end if;
  return new;
end $$;
drop trigger if exists calendar_notes_place on public.calendar_notes;
create trigger calendar_notes_place
  before insert on public.calendar_notes
  for each row execute function public.tg_calendar_notes_place();

alter table public.calendar_notes enable row level security;
-- As blocked time: staff, and a client's people on their own projects' calendars.
drop policy if exists calendar_notes_all on public.calendar_notes;
create policy calendar_notes_all on public.calendar_notes
  for all to authenticated
  using ((select public.is_staff()) or project_id in (select public.client_project_ids()))
  with check ((select public.is_staff())
              or (project_id in (select public.client_project_ids())
                  and public.calendar_project(project_id) in (select public.client_project_ids())));
drop policy if exists mfa_required on public.calendar_notes;
create policy mfa_required on public.calendar_notes as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.calendar_notes;
create policy active_account_required on public.calendar_notes as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.calendar_notes from anon;
grant select, insert, delete on public.calendar_notes to authenticated;
grant all on public.calendar_notes to service_role;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261126100000_appointment_updates.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — clients update their appointments (Sean, Oct 2026)
--
-- The client's people say how each appointment went, from Appointments (and
-- the lead page): one of nine statuses, a note, a potential premium while
-- quoting, and for a sold account the premium and carrier on each policy line.
-- Every update is kept, for administrators and managers to read on the lead;
-- each one tells the administrators and the manager who set the appointment.
--
--   appointments.client_result   the status the client gave it (null: none yet)
--     pending_appointment  Pending Appointment   valid_not_quoting  Valid-Not Quoting
--     no_status            No Status             quoted_not_sold    Quoted-Not Sold
--     valid                Valid Appointment     sold               Sold Account
--     valid_quoting        Valid-Quoting         invalid            Invalid
--                                                reschedule         Please Reschedule
--   appointment_update_status(result, date, time)  what it shows: with none
--                         given (or Pending Appointment), Pending Appointment
--                         until the appointment's time, No Status after
--   appointments.quoted_premium   the potential premium while quoting
--   appointments.sold_lines       a sold account's lines: [{line, premium, carrier}]
--   appointments.written_premium  their total (Premium Written)
--   appointment_updates           every update: who, when, what, the note
--   update_appointment_status()   the client's (or an administrator's) update
--   update_due_on(date)           5 business days after the appointment: the
--                                 last day to update it (an invalid one is
--                                 credited only if said by then)
--   client_appointments()         Appointments, as the client's list shows them
--   appointment_nudges            the reminders to update: on the 2nd and 4th
--                                 business day after an appointment still at
--                                 No Status, a notification and an email to
--                                 the client's people (the app sends the email)
--   client_sales(company, project)  the Sale Pipeline, from the project's start
--                                 month, for one project or all of a client's
--   client_dashboard()            Appointment Results in these statuses
--   set_reminder()                a client's people set reminders on their leads
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

-- --- The statuses ------------------------------------------------------------
-- From the first list (pending, quoting, …): pending is now "none given yet", quoting is Valid-Quoting.
do $$
declare c record;
begin
  for c in select conname from pg_constraint
            where conrelid = 'public.appointments'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%client_result%'
  loop
    execute format('alter table public.appointments drop constraint %I', c.conname);
  end loop;
end $$;
update public.appointments set client_result = null where client_result = 'pending';
update public.appointments set client_result = 'valid_quoting' where client_result = 'quoting';
alter table public.appointments add constraint appointments_client_result_check
  check (client_result in ('pending_appointment', 'no_status', 'valid', 'valid_quoting', 'valid_not_quoting',
                           'quoted_not_sold', 'sold', 'invalid', 'reschedule'));
alter table public.appointments add column if not exists sold_lines jsonb;
alter table public.appointments add column if not exists update_nudge_1_at timestamptz;
alter table public.appointments add column if not exists update_nudge_2_at timestamptz;

create or replace function public.appointment_update_label(p_status text)
returns text
language sql immutable set search_path = public as $$
  select case p_status
    when 'pending_appointment' then 'Pending Appointment' when 'no_status' then 'No Status'
    when 'valid' then 'Valid Appointment' when 'valid_quoting' then 'Valid-Quoting'
    when 'valid_not_quoting' then 'Valid-Not Quoting' when 'quoted_not_sold' then 'Quoted-Not Sold'
    when 'sold' then 'Sold Account' when 'invalid' then 'Invalid' when 'reschedule' then 'Please Reschedule'
    else p_status end;
$$;
grant execute on function public.appointment_update_label(text) to authenticated, service_role;

/** When an appointment starts, on the business's clock: its day at its time ("10:00 AM"), or the start of the day. */
create or replace function public.appointment_starts_at(p_date date, p_time text)
returns timestamptz
language sql stable set search_path = public as $$
  select (p_date + case when coalesce(p_time, '') ~* '^\s*(1[0-2]|0?[1-9]):[0-5][0-9]\s*(AM|PM)\s*$'
                        then to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time else time '00:00' end)
         at time zone public.business_tz();
$$;
grant execute on function public.appointment_starts_at(date, text) to authenticated, service_role;

/** What an appointment shows: the status given, or with none (or Pending Appointment) Pending until its time, then No Status. */
create or replace function public.appointment_update_status(p_result text, p_date date, p_time text)
returns text
language sql stable set search_path = public as $$
  select case
    when p_result is not null and p_result <> 'pending_appointment' then p_result
    when p_date is null or public.appointment_starts_at(p_date, p_time) > now() then 'pending_appointment'
    else 'no_status' end;
$$;
grant execute on function public.appointment_update_status(text, date, text) to authenticated, service_role;

/** `p_days` business days (Monday to Friday) after `p_date`. */
create or replace function public.business_days_after(p_date date, p_days int)
returns date
language sql immutable set search_path = public as $$
  select max(d) from (
    select g::date as d from generate_series(p_date + 1, p_date + p_days * 2 + 7, interval '1 day') g
     where extract(isodow from g) < 6 order by g limit p_days
  ) b;
$$;
grant execute on function public.business_days_after(date, int) to authenticated, service_role;

/** The last day to update an appointment: 5 business days after it. */
create or replace function public.update_due_on(p_date date)
returns date
language sql immutable set search_path = public as $$
  select public.business_days_after(p_date, 5);
$$;
grant execute on function public.update_due_on(date) to authenticated, service_role;

-- --- Every update, kept ----------------------------------------------------------
create table if not exists public.appointment_updates (
  id                 bigint generated always as identity primary key,
  appointment_id     bigint not null references public.appointments(id) on delete cascade,
  lead_id            bigint references public.leads(id) on delete cascade,
  project_id         bigint references public.projects(id) on delete set null,
  company_id         bigint references public.companies(id) on delete set null,
  status             text not null,
  previous_status    text,
  note               text check (length(note) <= 2000),
  potential_premium  numeric(12, 2) check (potential_premium >= 0),
  sold_lines         jsonb,
  total_premium      numeric(12, 2) check (total_premium >= 0),
  created_by         bigint references public.users(id) on delete set null,
  created_at         timestamptz not null default now()
);
create index if not exists appointment_updates_appt on public.appointment_updates (appointment_id, created_at desc);
create index if not exists appointment_updates_lead on public.appointment_updates (lead_id, created_at desc);
create index if not exists appointment_updates_at on public.appointment_updates (created_at desc);

alter table public.appointment_updates enable row level security;
-- Staff read every update; a client's people, their own company's. Written only by update_appointment_status().
drop policy if exists appointment_updates_read on public.appointment_updates;
create policy appointment_updates_read on public.appointment_updates for select to authenticated
  using ((select public.is_staff()) or company_id = (select public.app_company_id()));
drop policy if exists mfa_required on public.appointment_updates;
create policy mfa_required on public.appointment_updates as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.appointment_updates;
create policy active_account_required on public.appointment_updates as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.appointment_updates from anon;
revoke insert, update, delete, truncate on public.appointment_updates from authenticated;
grant select on public.appointment_updates to authenticated;
grant all on public.appointment_updates to service_role;

/**
 * The client's update to an appointment (or an administrator's, for them): one status, a note,
 * the potential premium while Valid-Quoting, and for Sold Account its policy lines
 * ([{line, premium, carrier}], the total written). Kept in appointment_updates; the
 * administrators and the manager who set it are told.
 */
create or replace function public.update_appointment_status(p_appointment_id bigint, p_status text, p_note text default null,
  p_potential_premium numeric default null, p_sold_lines jsonb default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me      public.users;
  a         public.appointments;
  l         public.leads;
  v_company bigint;
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_lines   jsonb := '[]'::jsonb;
  v_total   numeric := null;
  v_line    jsonb;
  v_prem    numeric;
  v_carrier text;
  v_prev    text;
  v_label   text;
  v_to      bigint[];
  v_id      bigint;
begin
  select * into v_me from public.users where id = public.app_user_id();
  if v_me.id is null then
    raise exception 'Sign in to update an appointment' using errcode = '42501';
  end if;
  select * into a from public.appointments where id = p_appointment_id and deleted_at is null;
  if a.id is null then
    raise exception 'That appointment is no longer there' using errcode = '22023';
  end if;
  select company_id into v_company from public.projects where id = coalesce(a.project_id, a.set_project_id);
  if not (public.is_admin()
          or (v_me.role = 'client' and coalesce(a.project_id, a.set_project_id) in (select public.client_project_ids())
              and coalesce(a.qa_status, 'passed') = 'passed')) then
    raise exception 'That appointment is not yours to update' using errcode = '42501';
  end if;
  if p_status not in ('pending_appointment', 'no_status', 'valid', 'valid_quoting', 'valid_not_quoting',
                      'quoted_not_sold', 'sold', 'invalid', 'reschedule') then
    raise exception 'Choose one of the statuses' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 2000 then
    raise exception 'Keep the note under 2,000 characters' using errcode = '22023';
  end if;
  if p_status = 'valid_quoting' and p_potential_premium is not null and (p_potential_premium < 0 or p_potential_premium > 999999999) then
    raise exception 'Enter the potential premium as an amount' using errcode = '22023';
  end if;
  if p_status = 'sold' then
    if p_sold_lines is null or jsonb_typeof(p_sold_lines) <> 'array' then
      raise exception 'Enter the premium on each policy line sold' using errcode = '22023';
    end if;
    for v_line in select * from jsonb_array_elements(p_sold_lines) loop
      if coalesce(v_line->>'line', '') not in ('liability', 'work_comp', 'auto', 'umbrella', 'eo', 'personal', 'health') then
        raise exception 'That is not one of the policy lines' using errcode = '22023';
      end if;
      begin
        v_prem := nullif(v_line->>'premium', '')::numeric;
      exception when others then
        raise exception 'Enter each premium as an amount' using errcode = '22023';
      end;
      continue when v_prem is null or v_prem = 0;
      if v_prem < 0 or v_prem > 999999999 then
        raise exception 'Enter each premium as an amount' using errcode = '22023';
      end if;
      v_carrier := nullif(btrim(coalesce(v_line->>'carrier', '')), '');
      if v_carrier is null then
        raise exception 'Choose the carrier each line was placed with' using errcode = '22023';
      end if;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('line', v_line->>'line', 'premium', round(v_prem, 2), 'carrier', left(v_carrier, 120)));
      v_total := coalesce(v_total, 0) + round(v_prem, 2);
    end loop;
    if v_total is null then
      raise exception 'Enter the premium on at least one policy line' using errcode = '22023';
    end if;
  end if;

  v_prev := public.appointment_update_status(a.client_result, a.appt_date, a.appt_time);
  update public.appointments set
    client_result = p_status,
    client_result_at = now(),
    client_result_by = v_me.id,
    quoted_premium = case when p_status = 'valid_quoting' then round(p_potential_premium, 2) else quoted_premium end,
    sold_lines = case when p_status = 'sold' then v_lines else null end,
    written_premium = case when p_status = 'sold' then v_total else null end
  where id = a.id;
  insert into public.appointment_updates (appointment_id, lead_id, project_id, company_id, status, previous_status, note,
    potential_premium, sold_lines, total_premium, created_by)
  values (a.id, a.lead_id, coalesce(a.project_id, a.set_project_id), v_company, p_status, v_prev, v_note,
    case when p_status = 'valid_quoting' then round(p_potential_premium, 2) end,
    case when p_status = 'sold' then v_lines end, v_total, v_me.id)
  returning id into v_id;

  -- The administrators, and the manager who set it, hear of it.
  select * into l from public.leads where id = a.lead_id;
  v_label := public.appointment_update_label(p_status);
  select array_agg(distinct u.id) into v_to from public.users u
   where u.status = 'active' and u.id <> v_me.id and (u.role = 'admin' or u.id = a.user_id);
  if v_to is not null then
    perform public.notify_users(v_to, 'appointment',
      left('Appointment update: ' || v_label || ' · ' || coalesce(l.company_name, 'an appointment'), 160),
      left(concat_ws(' · ',
        coalesce(nullif(btrim(concat_ws(' ', v_me.first_name, v_me.last_name)), ''), v_me.email),
        'Appointment ' || to_char(a.appt_date, 'FMMM/FMDD/YYYY'),
        case when p_status = 'valid_quoting' and p_potential_premium is not null then 'Potential premium $' || to_char(p_potential_premium, 'FM999,999,999,990.00') end,
        case when p_status = 'sold' then 'Total premium $' || to_char(v_total, 'FM999,999,999,990.00') end,
        v_note), 1000),
      '/leads/' || a.lead_id || '?tab=updates', null, gen_random_uuid(), v_me.id);
  end if;
  return jsonb_build_object('id', v_id, 'status', p_status, 'label', v_label, 'total', v_total);
end $$;
revoke execute on function public.update_appointment_status(bigint, text, text, numeric, jsonb) from public, anon;
grant execute on function public.update_appointment_status(bigint, text, text, numeric, jsonb) to authenticated;

/**
 * Appointments as a client's list shows them (Sean, Oct 2026): the caller's (a client: their
 * projects', through QA; staff: any, or p_company_id's) with their day from p_from to p_to, by the
 * appointment's day: the company, project, agent, when it was developed, its day and time, what it
 * is (Appointment, -Confirmed, -Invalid), its X-date, the manager who set it, and the update: the
 * status it shows, when and by whom, its potential or total premium, and the day it is due by.
 * With p_lead_id: that lead's appointments, whatever their day.
 */
drop function if exists public.client_appointments(date, date, bigint, text, bigint);
drop function if exists public.client_appointments(date, date, bigint, text, bigint, bigint);
create function public.client_appointments(p_from date, p_to date, p_project_id bigint default null,
  p_status text default null, p_company_id bigint default null, p_lead_id bigint default null)
returns table (id bigint, lead_id bigint, company text, city text, state text, project_id bigint, project text,
  agent text, developed_at timestamptz, appt_date date, appt_time text, status text, xdate date, manager text,
  manager_id bigint, update_status text, update_label text, update_at timestamptz, update_by text,
  potential_premium numeric, total_premium numeric, sold_lines jsonb, due_on date, last_note text)
language sql stable security definer set search_path = public as $$
  with mine as (
    select p.id from public.projects p
     where p.deleted_at is null
       and (case when public.is_staff() then (p_company_id is null or p.company_id = p_company_id)
                 else p.id in (select public.client_project_ids()) end)
       and (p_project_id is null or p.id = p_project_id)
  ), rows as (
    select ap.*, public.appointment_update_status(ap.client_result, ap.appt_date, ap.appt_time) as shown
      from public.appointments ap
     where public.app_user_id() is not null
       and ap.deleted_at is null
       and coalesce(ap.project_id, ap.set_project_id) in (select id from mine)
       and (public.is_staff() or coalesce(ap.qa_status, 'passed') = 'passed')
       and (case when p_lead_id is not null then ap.lead_id = p_lead_id else ap.appt_date between p_from and p_to end)
  )
  select r.id, l.id, l.company_name, l.city, l.state, pr.id, pr.name,
         coalesce(nullif(btrim(r.rep_name), ''), nullif(btrim(pr.contact_name), '')),
         coalesce((select min(e.created_at) from public.pay_events e where e.appointment_id = r.id and e.kind = 'appointment' and not e.is_chargeback),
                  r.appt_create_date, r.created_at),
         r.appt_date, r.appt_time,
         case when r.invalid_at is not null then 'Appointment-Invalid'
              when r.confirmed_at is not null then 'Appointment-Confirmed' else 'Appointment' end,
         (select min(coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                                      i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)))
            from public.insurance_details i where i.lead_id = l.id),
         nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.id,
         r.shown, public.appointment_update_label(r.shown), r.client_result_at,
         nullif(btrim(concat_ws(' ', b.first_name, b.last_name)), ''),
         r.quoted_premium, r.written_premium, r.sold_lines, public.update_due_on(r.appt_date),
         (select x.note from public.appointment_updates x where x.appointment_id = r.id and x.note is not null order by x.created_at desc, x.id desc limit 1)
    from rows r
    join public.leads l on l.id = r.lead_id and l.deleted_at is null
    join public.projects pr on pr.id = coalesce(r.project_id, r.set_project_id)
    left join public.users u on u.id = r.user_id
    left join public.users b on b.id = r.client_result_by
   where p_status is null or r.shown = p_status
   order by r.appt_date desc, public.appointment_starts_at(r.appt_date, r.appt_time) desc, r.id desc
   limit 2000;
$$;
revoke execute on function public.client_appointments(date, date, bigint, text, bigint, bigint) from public, anon;
grant execute on function public.client_appointments(date, date, bigint, text, bigint, bigint) to authenticated;

/** The updates made from p_from to p_to (the business's days), as the caller may read them: Appointment Updates. */
create or replace function public.appointment_updates_between(p_from date, p_to date)
returns setof public.appointment_updates
language sql stable security invoker set search_path = public as $$
  select * from public.appointment_updates
   where created_at >= (p_from::timestamp at time zone public.business_tz())
     and created_at < ((p_to + 1)::timestamp at time zone public.business_tz());
$$;
revoke execute on function public.appointment_updates_between(date, date) from public, anon;
grant execute on function public.appointment_updates_between(date, date) to authenticated;

-- --- Reminders to update ---------------------------------------------------------
-- The emails the app is to send: one row for each person told, sent (or failed) by /api/appointments/nudge.
create table if not exists public.appointment_nudges (
  id              bigint generated always as identity primary key,
  appointment_id  bigint not null references public.appointments(id) on delete cascade,
  nudge           int not null check (nudge in (1, 2)),
  user_id         bigint references public.users(id) on delete cascade,
  email           text not null,
  subject         text not null,
  body            text not null,
  link            text not null,
  created_at      timestamptz not null default now(),
  sent_at         timestamptz,
  error           text
);
create index if not exists appointment_nudges_unsent on public.appointment_nudges (created_at) where sent_at is null and error is null;
alter table public.appointment_nudges enable row level security;
revoke all on public.appointment_nudges from anon, authenticated;
grant all on public.appointment_nudges to service_role;

/**
 * On a business day's working hours: each appointment still at No Status on the 2nd business day
 * after it, and again on the 4th, gets the client's people a notification, and an email queued for
 * the app to send (then the app is asked to send them). Each reminder goes once. `p_now`: the
 * time to act as of (the schedule's own; a test's).
 */
drop function if exists public.nudge_appointment_updates();
create or replace function public.nudge_appointment_updates(p_now timestamptz default now())
returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_tz     text := public.business_tz();
  v_today  date := (p_now at time zone v_tz)::date;
  v_hour   int := extract(hour from p_now at time zone v_tz)::int;
  r        record;
  v_n      int;
  v_title  text;
  v_body   text;
  v_link   text;
  v_to     bigint[];
  v_count  int := 0;
  v_url    text;
  v_secret text;
begin
  if extract(isodow from v_today) > 5 or v_hour < 8 or v_hour >= 18 then
    return 0;
  end if;
  for r in
    select a.id, a.lead_id, a.appt_date, a.update_nudge_1_at, a.update_nudge_2_at, l.company_name, p.company_id
      from public.appointments a
      join public.leads l on l.id = a.lead_id and l.deleted_at is null
      join public.projects p on p.id = coalesce(a.project_id, a.set_project_id) and p.deleted_at is null
     where a.deleted_at is null and a.invalid_at is null and coalesce(a.qa_status, 'passed') = 'passed'
       and public.appointment_update_status(a.client_result, a.appt_date, a.appt_time) = 'no_status'
       and a.appt_date >= v_today - 30
       and (a.update_nudge_2_at is null)
       and v_today >= public.business_days_after(a.appt_date, 2)
     for update of a skip locked
  loop
    v_n := case when v_today >= public.business_days_after(r.appt_date, 4) then 2
                when r.update_nudge_1_at is null then 1 else null end;
    continue when v_n is null;
    v_link := '/appointments?update=' || r.id;
    if v_n = 1 then
      v_title := left('How did your appointment with ' || coalesce(r.company_name, 'the business') || ' go?', 160);
      v_body := 'How did your Appointment with ' || coalesce(r.company_name, 'the business') || ' work out on '
        || to_char(r.appt_date, 'FMMM/FMDD/YYYY') || '? Please update the status of the Appointment in Lighthouse so we can let our team know how they did.';
    else
      v_title := left('Reminder: update your appointment with ' || coalesce(r.company_name, 'the business'), 160);
      v_body := 'Reminder to update the status of your Appointment with ' || coalesce(r.company_name, 'the business') || ' that was on '
        || to_char(r.appt_date, 'FMMM/FMDD/YYYY') || ' by tomorrow in order to receive credit if it was invalid.';
    end if;
    select array_agg(u.id) into v_to from public.users u
     where u.company_id = r.company_id and u.role = 'client' and u.status = 'active' and u.deleted_at is null;
    if v_to is not null then
      perform public.notify_users(v_to, 'appointment', v_title, v_body, v_link, null, gen_random_uuid(), null);
      insert into public.appointment_nudges (appointment_id, nudge, user_id, email, subject, body, link)
      select r.id, v_n, u.id, u.email, v_title, v_body, v_link
        from public.users u where u.id = any(v_to) and nullif(btrim(u.email), '') is not null;
    end if;
    -- The 4th day's reminder stands for the 2nd too, when the first went unsent (the job was off).
    update public.appointments set update_nudge_1_at = coalesce(update_nudge_1_at, now()),
                                   update_nudge_2_at = case when v_n = 2 then now() else update_nudge_2_at end
     where id = r.id;
    v_count := v_count + 1;
  end loop;

  -- The emails go from the app: ask it, as the hourly deliveries are asked.
  if exists (select 1 from public.appointment_nudges where sent_at is null and error is null) then
    begin
      select decrypted_secret into v_url from vault.decrypted_secrets where name = 'push_deliver_url';
      select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_deliver_secret';
      if v_url like '%/api/push/deliver' and v_secret is not null then
        perform net.http_post(
          url := replace(v_url, '/api/push/deliver', '/api/appointments/nudge'),
          body := '{}'::jsonb,
          headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
          timeout_milliseconds := 60000);
      end if;
    exception when others then
      raise warning 'appointment nudges: % (%)', sqlerrm, sqlstate;
    end;
  end if;
  return v_count;
end $$;
revoke execute on function public.nudge_appointment_updates(timestamptz) from public, anon, authenticated;
grant execute on function public.nudge_appointment_updates(timestamptz) to service_role;

do $$
begin
  if to_regclass('cron.job') is null then
    raise notice 'pg_cron is not enabled: appointment update reminders are not sent on a schedule';
    return;
  end if;
  if exists (select 1 from cron.job where jobname = 'nudge-appointment-updates') then
    perform cron.unschedule('nudge-appointment-updates');
  end if;
  perform cron.schedule('nudge-appointment-updates', '5 * * * *', 'select public.nudge_appointment_updates()');
end $$;

-- --- The Sale Pipeline, from the campaign's start ------------------------------------
drop function if exists public.client_sales(bigint);
/**
 * The Sale Pipeline for a client (an administrator's p_company_id, or the caller's own) or one of
 * its projects: twelve months from the month its campaign started (the project's start date; for
 * all its projects, the earliest; January without one), moved on by whole years to the year we are
 * in. Premium written in them (Sold Account, by when it was marked), in the pipe (potential premium
 * on those Valid-Quoting), the goal for the year it began in, and the close ratio: sold of the valid
 * appointments (Valid, Valid-Quoting, Valid-Not Quoting, Quoted-Not Sold, Sold).
 */
create or replace function public.client_sales(p_company_id bigint default null, p_project_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz, (now() at time zone public.business_tz())::date as today
  ), co as (
    select coalesce(p_company_id, public.app_company_id()) as id
  ), p as (
    select pr.id, pr.start_date from public.projects pr, co
     where pr.company_id = co.id and pr.deleted_at is null and (p_project_id is null or pr.id = p_project_id)
  ), s0 as (
    select coalesce(date_trunc('month', (select min(start_date) from p))::date, date_trunc('year', z.today)::date) as first, z.today from z
  ), s as (
    -- Moved on by whole years until it holds today (a start still ahead stays where it is).
    select (first + make_interval(years => greatest(0, floor(((extract(year from today) - extract(year from first)) * 12
             + extract(month from today) - extract(month from first)) / 12)::int)))::date as first, today from s0
  ), a as (
    select public.appointment_update_status(ap.client_result, ap.appt_date, ap.appt_time) as result,
           ap.quoted_premium, ap.written_premium, (ap.client_result_at at time zone z.tz)::date as at
      from public.appointments ap, z
     where coalesce(ap.project_id, ap.set_project_id) in (select id from p)
       and ap.deleted_at is null and ap.invalid_at is null and coalesce(ap.qa_status, 'passed') = 'passed'
  ), sold as (
    select a.written_premium, a.at from a, s where a.result = 'sold' and a.at >= s.first and a.at < (s.first + interval '12 months')::date
  )
  select jsonb_build_object(
    'year', (select extract(year from first)::int from s),
    'start', (select first from s),
    'started', (select min(start_date) from p),
    'written', (select coalesce(sum(written_premium), 0) from sold),
    'pipe', (select coalesce(sum(quoted_premium), 0) from a where result = 'valid_quoting'),
    'goal', (select g.premium_goal from public.client_goals g, co, s where g.company_id = co.id and g.year = extract(year from s.first)::int),
    'sold', (select count(*) from a where result = 'sold'),
    'considered', (select count(*) from a where result in ('valid', 'valid_quoting', 'valid_not_quoting', 'quoted_not_sold', 'sold')),
    'current', (select ((extract(year from today) - extract(year from first)) * 12 + extract(month from today) - extract(month from first))::int + 1 from s),
    'months', (select jsonb_agg(jsonb_build_object(
                 'month', i, 'key', to_char((s.first + make_interval(months => i - 1))::date, 'YYYY-MM'),
                 'label', to_char((s.first + make_interval(months => i - 1))::date, 'Mon'),
                 'written', (select coalesce(sum(written_premium), 0) from sold
                              where date_trunc('month', sold.at) = date_trunc('month', s.first + make_interval(months => i - 1)))
               ) order by i) from s, generate_series(1, 12) i)
  );
$$;
revoke execute on function public.client_sales(bigint, bigint) from public, anon;
grant execute on function public.client_sales(bigint, bigint) to authenticated;

-- --- Appointment Results, in the new statuses ----------------------------------------
create or replace function public.client_dashboard(p_from date default null, p_company_id bigint default null)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), p as (
    select pr.id, pr.name, t.code as type from public.projects pr
      left join public.project_types t on t.id = pr.project_type_id
     where pr.deleted_at is null and (p_company_id is null or pr.company_id = p_company_id)
  ), l as (
    -- A lead: a name at the appointment stage, dated by when it became one.
    select le.id, le.project_id, le.source_project_id, r.effect, le.appt_created_date, le.promoted_at, le.lead_date, le.created_at
      from public.leads le join public.call_results r on r.id = le.result_id
     where le.stage = 'appt'
       and (le.project_id in (select id from p) or le.source_project_id in (select id from p))
  ), lp as (
    select l.* from l, z
     where p_from is null or coalesce(l.promoted_at, l.lead_date, l.created_at) >= (p_from::timestamp at time zone z.tz)
  ), a as (
    -- An appointment: a name whose result is one (set, confirmed or invalid), once each, dated by when it was set.
    select l.id, l.effect,
           (select public.appointment_update_status(ap.client_result, ap.appt_date, ap.appt_time) from public.appointments ap
             where ap.lead_id = l.id and ap.deleted_at is null order by ap.created_at desc, ap.id desc limit 1) as shown
      from l, z
     where l.project_id in (select id from p)
       and l.effect in ('appointment', 'confirm', 'appointment_invalid')
       and (p_from is null or coalesce(l.appt_created_date, l.promoted_at, l.lead_date, l.created_at) >= (p_from::timestamp at time zone z.tz))
  ), ar as (
    select case when effect = 'appointment_invalid' then 'invalid' else coalesce(shown, 'pending_appointment') end as result from a
  )
  select jsonb_build_object(
    'leads', (select count(*) from lp where lp.project_id in (select id from p)),
    'projects', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name,
                                   'leads', (select count(*) from lp where lp.source_project_id = p.id or lp.project_id = p.id))
                                 order by p.name), '[]'::jsonb)
                   from p where p.type = 'DBDV'),
    'appts', (select count(*) from a),
    'results', (select jsonb_object_agg(k, (select count(*) from ar where ar.result = k))
                  from unnest(array['pending_appointment', 'no_status', 'valid', 'valid_quoting', 'valid_not_quoting',
                                    'quoted_not_sold', 'sold', 'invalid', 'reschedule']) k)
  );
$$;
revoke execute on function public.client_dashboard(date, bigint) from public, anon;
grant execute on function public.client_dashboard(date, bigint) to authenticated;

-- --- A client's people set reminders on their own leads ----------------------------------
create or replace function public.set_reminder(p_lead_id bigint, p_date date, p_time text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  v_time time;
  v_at   timestamptz;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  r      public.reminders;
begin
  if v_me is null or not (public.can_work_lead(p_lead_id)
       or (public.app_role() = 'client' and exists (select 1 from public.leads l where l.id = p_lead_id and l.deleted_at is null
             and (l.project_id in (select public.client_project_ids()) or l.source_project_id in (select public.client_project_ids()))))) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;
  begin
    v_time := to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time;
  exception when others then
    raise exception 'Choose a time like 2:00 PM' using errcode = '22023';
  end;
  if p_date is null or v_time is null then
    raise exception 'Choose the day and time to be reminded' using errcode = '22023';
  end if;
  v_at := (p_date + v_time) at time zone public.business_tz();
  if v_at < now() - interval '1 minute' then
    raise exception 'That time has already passed' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 300 then
    raise exception 'Keep the note under 300 characters' using errcode = '22023';
  end if;
  insert into public.reminders (lead_id, user_id, remind_at, note)
  values (p_lead_id, v_me, v_at, v_note)
  returning * into r;
  return jsonb_build_object('id', r.id, 'remind_at', r.remind_at);
end $$;
revoke execute on function public.set_reminder(bigint, date, text, text) from public, anon;
grant execute on function public.set_reminder(bigint, date, text, text) to authenticated;

-- A client's reminder says "Reminder", not "Call back".
create or replace function public.deliver_reminders()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r     record;
  v_id  bigint;
  n     integer := 0;
begin
  for r in
    select m.id, m.user_id, m.lead_id, m.note, m.remind_at, m.appointment_id, l.company_name, u.role
      from public.reminders m
      join public.leads l on l.id = m.lead_id and l.deleted_at is null
      left join public.users u on u.id = m.user_id
     where m.sent_at is null and m.remind_at <= now()
     order by m.remind_at
     for update of m skip locked
  loop
    insert into public.notifications (user_id, kind, title, body, link)
    values (
      r.user_id, 'reminder',
      left(case when r.appointment_id is not null then 'Confirm tomorrow''s appointment: '
                when r.role = 'client' then 'Reminder: ' else 'Call back: ' end
           || coalesce(r.company_name, 'a lead'), 120),
      left(case when r.appointment_id is not null then coalesce(r.note, '')
                else concat_ws(' · ', 'Reminder for ' || to_char(r.remind_at at time zone public.business_tz(), 'FMHH12:MI AM'), r.note) end, 1000),
      '/leads/' || r.lead_id
    )
    returning id into v_id;
    update public.reminders set sent_at = now(), notification_id = v_id where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke execute on function public.deliver_reminders() from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261127100000_team_page.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — Meet the Team, more than a gallery (Oct 2026)
--
--   users.birthday           month and day (the year is not kept: stored in 2000)
--   team_directory()         each member with what they do (lead development,
--                            appointment setting), since when, whether they are
--                            on the phones now, active today or away, their
--                            thank-yous, today's birthday and its gifts, and for
--                            a client what they developed for them (counts only)
--   team_member_recent(id)   the latest leads and appointments they developed
--                            (for a client: on its projects), to open
--   team_spotlight()         this week's top: appointments, leads and calls
--   message_team_member()    a note to a member, as a message they can answer
--                            (a client: to those who work its projects)
--   kudos                    thank-yous and birthday gifts: who, to whom, the
--                            gift and a note; the member hears of each
--   send_kudos()             send one
--   app_settings 'team'      { spotlight: false } hides the spotlight
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

alter table public.users add column if not exists birthday date;
alter table public.users drop constraint if exists users_birthday_check;
alter table public.users add constraint users_birthday_check check (birthday is null or extract(year from birthday) = 2000);

/** Whether a birthday (month and day) falls on `p_day`; a 29 February one on the 28th in other years. */
create or replace function public.birthday_on(p_birthday date, p_day date)
returns boolean
language sql immutable set search_path = public as $$
  select p_birthday is not null and (
    (extract(month from p_birthday), extract(day from p_birthday)) = (extract(month from p_day), extract(day from p_day))
    or (extract(month from p_birthday) = 2 and extract(day from p_birthday) = 29 and extract(month from p_day) = 2 and extract(day from p_day) = 28
        and extract(day from (date_trunc('year', p_day) + interval '1 month 28 days')::date) <> 29));
$$;
grant execute on function public.birthday_on(date, date) to authenticated, service_role;

-- --- Thank-yous and gifts ---------------------------------------------------------
create table if not exists public.kudos (
  id          bigint generated always as identity primary key,
  to_user     bigint not null references public.users(id) on delete cascade,
  from_user   bigint references public.users(id) on delete set null,
  kind        text not null check (kind in ('thanks', 'birthday')),
  gift        text check (gift in ('flowers', 'cake', 'balloons', 'coffee', 'chocolates', 'present', 'pizza', 'trophy', 'party')),
  note        text check (length(note) <= 300),
  created_at  timestamptz not null default now()
);
create index if not exists kudos_to on public.kudos (to_user, created_at desc);
alter table public.kudos enable row level security;
drop policy if exists kudos_read on public.kudos;
create policy kudos_read on public.kudos for select to authenticated
  using (to_user = (select public.app_user_id()) or from_user = (select public.app_user_id()) or (select public.is_admin()));
drop policy if exists mfa_required on public.kudos;
create policy mfa_required on public.kudos as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.kudos;
create policy active_account_required on public.kudos as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.kudos from anon;
revoke insert, update, delete, truncate on public.kudos from authenticated;
grant select on public.kudos to authenticated;
grant all on public.kudos to service_role;

-- Who a client works with: the staff who developed or set something on its projects, or are assigned to them.
create or replace function public.works_with_client(p_user_id bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.pay_events e where e.user_id = p_user_id and not e.is_chargeback
                    and e.project_id in (select public.client_project_ids()))
      or exists (select 1 from public.project_assignments pa where pa.ae_user_id = p_user_id
                    and pa.project_id in (select public.client_project_ids()));
$$;
revoke execute on function public.works_with_client(bigint) from public, anon;
grant execute on function public.works_with_client(bigint) to authenticated;

drop function if exists public.team_directory();
/**
 * Meet the Team: everyone on staff who is active. For each: their photo, line and role; what they
 * do (lead development, appointment setting or both, by the projects they work); since when; their
 * status (on the phones: a call in the last 15 minutes; active today: a call or a sign-in today;
 * else away) and their last call today; the thank-yous they have had; whether today is their
 * birthday, and the gifts it has brought. For a client, `mine` (they work its projects, shown first)
 * and the leads and appointments they developed for it this month and in all; for staff, this
 * month's across the business. Never pay, email or phone.
 */
create function public.team_directory()
returns table (id bigint, name text, role text, photo_path text, bio text, mine boolean, does text,
  since date, status text, last_call timestamptz, kudos bigint, birthday_today boolean, gifts_today bigint,
  leads_month bigint, appts_month bigint, leads_total bigint, appts_total bigint)
language sql stable security definer set search_path = public as $$
  with me as (
    select public.app_user_id() as uid, public.app_role() as role, public.business_tz() as tz
  ), day as (
    select (now() at time zone me.tz)::date as today, date_trunc('month', now() at time zone me.tz) as month_start, me.tz from me
  ), staff as (
    select u.* from public.users u, me
     where me.uid is not null and u.role in ('admin', 'manager', 'agent') and u.status = 'active' and u.deleted_at is null
  ), theirs as (
    select p.id from public.projects p, me where me.role = 'client' and p.id in (select public.client_project_ids())
  ), kinds as (
    select pa.ae_user_id as uid, bool_or(t.code = 'DBDV') as dbdv, bool_or(t.code = 'APPT') as appt
      from public.project_assignments pa join public.projects p on p.id = pa.project_id and p.deleted_at is null
      join public.project_types t on t.id = p.project_type_id
     group by 1
  ), calls as (
    select c.user_id, max(c.call_date) as last_call from public.call_records c, day
     where c.call_date >= (day.today::timestamp at time zone day.tz) group by 1
  ), dev as (
    select e.user_id,
           count(*) filter (where e.kind = 'lead' and e.created_at >= (day.month_start at time zone day.tz)) as leads_month,
           count(*) filter (where e.kind = 'appointment' and e.created_at >= (day.month_start at time zone day.tz)) as appts_month,
           count(*) filter (where e.kind = 'lead') as leads_total,
           count(*) filter (where e.kind = 'appointment') as appts_total
      from public.pay_events e, day, me
     where e.kind in ('lead', 'appointment') and not e.is_chargeback
       and (me.role <> 'client' or e.project_id in (select id from theirs))
       and (me.role = 'client' or e.created_at >= (day.month_start at time zone day.tz))
     group by 1
  ), k as (
    select to_user, count(*) filter (where kind = 'thanks') as thanks,
           count(*) filter (where kind = 'birthday' and created_at >= (day.today::timestamp at time zone day.tz)) as gifts_today
      from public.kudos, day group by 1
  )
  select s.id, nullif(btrim(concat_ws(' ', s.first_name, s.last_name)), ''), s.role, s.photo_path, s.bio,
         (me.role = 'client' and public.works_with_client(s.id)),
         case when s.role = 'admin' then 'Administration'
              when kd.dbdv and kd.appt then 'Lead development & appointment setting'
              when kd.appt then 'Appointment setting' when kd.dbdv then 'Lead development' end,
         s.created_at::date,
         case when c.last_call > now() - interval '15 minutes' then 'calling'
              when c.last_call is not null or (s.last_login at time zone day.tz)::date = day.today then 'active'
              else 'away' end,
         c.last_call, coalesce(k.thanks, 0), public.birthday_on(s.birthday, day.today), coalesce(k.gifts_today, 0),
         coalesce(d.leads_month, 0), coalesce(d.appts_month, 0),
         case when me.role = 'client' then coalesce(d.leads_total, 0) end,
         case when me.role = 'client' then coalesce(d.appts_total, 0) end
    from staff s cross join me cross join day
    left join kinds kd on kd.uid = s.id
    left join calls c on c.user_id = s.id
    left join dev d on d.user_id = s.id
    left join k on k.to_user = s.id
   order by 6 desc, 12 desc, s.first_name, s.last_name;
$$;
revoke execute on function public.team_directory() from public, anon;
grant execute on function public.team_directory() to authenticated;

/** The latest leads and appointments a member developed (for a client: on its projects), newest first. */
create or replace function public.team_member_recent(p_user_id bigint, p_limit int default 5)
returns table (lead_id bigint, company text, kind text, at timestamptz, project text)
language sql stable security definer set search_path = public as $$
  select l.id, l.company_name, e.kind, e.created_at, p.name
    from public.pay_events e
    join public.leads l on l.id = e.lead_id and l.deleted_at is null
    join public.projects p on p.id = e.project_id
   where public.app_user_id() is not null
     and e.user_id = p_user_id and e.kind in ('lead', 'appointment') and not e.is_chargeback
     and (public.is_staff() or e.project_id in (select public.client_project_ids()))
   order by e.created_at desc
   limit least(greatest(coalesce(p_limit, 5), 1), 20);
$$;
revoke execute on function public.team_member_recent(bigint, int) from public, anon;
grant execute on function public.team_member_recent(bigint, int) to authenticated;

/**
 * This week's spotlight (Monday on, business time): who set the most appointments, developed the
 * most leads and made the most calls. Null when an administrator has turned it off.
 */
create or replace function public.team_spotlight()
returns jsonb
language sql stable security definer set search_path = public as $$
  with z as (
    select public.business_tz() as tz,
           (date_trunc('week', now() at time zone public.business_tz()))::timestamp at time zone public.business_tz() as since
  ), people as (
    select u.id, nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), '') as name, u.photo_path
      from public.users u where u.role in ('admin', 'manager', 'agent') and u.status = 'active' and u.deleted_at is null
  ), ev as (
    select e.user_id, count(*) filter (where e.kind = 'appointment') as appts, count(*) filter (where e.kind = 'lead') as leads
      from public.pay_events e, z where e.created_at >= z.since and not e.is_chargeback and e.kind in ('lead', 'appointment')
     group by 1
  ), ca as (
    select c.user_id, count(*) as calls from public.call_records c, z where c.call_date >= z.since group by 1
  ), top as (
    select 'appointments' as what, p.id, p.name, p.photo_path, ev.appts as n from ev join people p on p.id = ev.user_id where ev.appts > 0
    union all
    select 'leads', p.id, p.name, p.photo_path, ev.leads from ev join people p on p.id = ev.user_id where ev.leads > 0
    union all
    select 'calls', p.id, p.name, p.photo_path, ca.calls from ca join people p on p.id = ca.user_id where ca.calls > 0
  ), best as (
    select distinct on (what) what, id, name, photo_path, n from top order by what, n desc, name
  )
  select case when coalesce((select (value->>'spotlight')::boolean from public.app_settings where key = 'team'), true) is false then null
              when public.app_user_id() is null then null
              else coalesce((select jsonb_object_agg(what, jsonb_build_object('id', id, 'name', name, 'photo', photo_path, 'count', n)) from best), '{}'::jsonb) end;
$$;
revoke execute on function public.team_spotlight() from public, anon;
grant execute on function public.team_spotlight() to authenticated;

/**
 * A note to a member of the team, as a message in their notifications they can answer. A client
 * may write to those who work its projects; staff to anyone on the team. Five a minute at most.
 */
create or replace function public.message_team_member(p_to bigint, p_body text)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me    public.users;
  v_body  text := btrim(coalesce(p_body, ''));
begin
  select * into v_me from public.users where id = public.app_user_id();
  if v_me.id is null then
    raise exception 'Sign in to send a message' using errcode = '42501';
  end if;
  if length(v_body) = 0 then
    raise exception 'Write your message first' using errcode = '22023';
  end if;
  if length(v_body) > 1000 then
    raise exception 'Keep a message under 1,000 characters' using errcode = '22023';
  end if;
  if p_to = v_me.id or not exists (select 1 from public.users u where u.id = p_to and u.status = 'active' and u.deleted_at is null
                                      and u.role in ('admin', 'manager', 'agent')) then
    raise exception 'That person is not on the team' using errcode = '22023';
  end if;
  if v_me.role = 'client' and not public.works_with_client(p_to) then
    raise exception 'You can message the people who work your projects' using errcode = '42501';
  end if;
  if (select count(*) from public.notifications where sender_id = v_me.id and kind = 'message' and created_at > now() - interval '1 minute') >= 5 then
    raise exception 'You are sending messages too quickly. Wait a moment and try again.' using errcode = '22023';
  end if;
  return public.notify_users(array[p_to], 'message',
    left('Message from ' || coalesce(nullif(btrim(concat_ws(' ', v_me.first_name, v_me.last_name)), ''), v_me.email)
         || case when v_me.role = 'client' then coalesce(': ' || (select c.name from public.companies c where c.id = v_me.company_id), '') else '' end, 160),
    v_body, '/team', null, gen_random_uuid(), v_me.id);
end $$;
revoke execute on function public.message_team_member(bigint, text) from public, anon;
grant execute on function public.message_team_member(bigint, text) to authenticated;

/**
 * A thank-you (or, on their birthday, a gift) for a member of the team, with a note: kept, and
 * the member told. A gift only on their birthday; one thank-you a day from each person to each.
 */
create or replace function public.send_kudos(p_to bigint, p_kind text, p_gift text default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me    public.users;
  v_to    public.users;
  v_note  text := nullif(btrim(coalesce(p_note, '')), '');
  v_name  text;
  v_gift  text;
  v_id    bigint;
  v_today date := (now() at time zone public.business_tz())::date;
begin
  select * into v_me from public.users where id = public.app_user_id();
  select * into v_to from public.users where id = p_to and status = 'active' and deleted_at is null and role in ('admin', 'manager', 'agent');
  if v_me.id is null then
    raise exception 'Sign in to send that' using errcode = '42501';
  end if;
  if v_to.id is null or v_to.id = v_me.id then
    raise exception 'That person is not on the team' using errcode = '22023';
  end if;
  if p_kind not in ('thanks', 'birthday') then
    raise exception 'Send a thank-you or a gift' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 300 then
    raise exception 'Keep the note under 300 characters' using errcode = '22023';
  end if;
  if p_kind = 'birthday' then
    if not public.birthday_on(v_to.birthday, v_today) then
      raise exception 'Gifts are for their birthday' using errcode = '22023';
    end if;
    if p_gift not in ('flowers', 'cake', 'balloons', 'coffee', 'chocolates', 'present', 'pizza', 'trophy', 'party') then
      raise exception 'Choose a gift' using errcode = '22023';
    end if;
  elsif exists (select 1 from public.kudos where from_user = v_me.id and to_user = v_to.id and kind = 'thanks'
                   and created_at >= (v_today::timestamp at time zone public.business_tz())) then
    raise exception 'You have thanked them today already' using errcode = '22023';
  end if;
  insert into public.kudos (to_user, from_user, kind, gift, note)
  values (v_to.id, v_me.id, p_kind, case when p_kind = 'birthday' then p_gift end, v_note)
  returning id into v_id;

  v_name := coalesce(nullif(btrim(concat_ws(' ', v_me.first_name, v_me.last_name)), ''), v_me.email)
    || case when v_me.role = 'client' then coalesce(' (' || (select c.name from public.companies c where c.id = v_me.company_id) || ')', '') else '' end;
  v_gift := case p_gift when 'flowers' then '💐 Flowers' when 'cake' then '🎂 A birthday cake' when 'balloons' then '🎈 Balloons'
    when 'coffee' then '☕ A coffee' when 'chocolates' then '🍫 Chocolates' when 'present' then '🎁 A present'
    when 'pizza' then '🍕 A pizza party' when 'trophy' then '🏆 A trophy' when 'party' then '🎉 A party' end;
  perform public.notify_users(array[v_to.id], 'message',
    left(case when p_kind = 'birthday' then v_gift || ' from ' || v_name || ': happy birthday!'
              else '🙌 ' || v_name || ' says thank you' end, 160),
    coalesce(v_note, case when p_kind = 'birthday' then 'Happy birthday!' else 'Thank you for your work.' end),
    '/team', null, gen_random_uuid(), v_me.id);
  return jsonb_build_object('id', v_id);
end $$;
revoke execute on function public.send_kudos(bigint, text, text, text) from public, anon;
grant execute on function public.send_kudos(bigint, text, text, text) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261128100000_client_updates_emails.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — appointment updates on the lead for the client too, and by email (Sean, Oct 2026)
--
--   lead_client_updates(lead)   every update made to a lead's appointments,
--                               with who and when: the lead page's Appointment
--                               Updates tab, for administrators and managers and
--                               now the client's people too
--   email_outbox                emails for the app to send (and say how each
--                               went): appointment updates to the
--                               administrators and the manager who set it, and
--                               the reminders to update to the client's people
--                               and the project's agent (its Project Info)
--   update_appointment_status() and nudge_appointment_updates(): by email too
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

create table if not exists public.email_outbox (
  id          bigint generated always as identity primary key,
  kind        text not null,
  user_id     bigint references public.users(id) on delete cascade,
  email       text not null,
  subject     text not null,
  body        text not null,
  link        text,
  created_at  timestamptz not null default now(),
  sent_at     timestamptz,
  error       text
);
create index if not exists email_outbox_unsent on public.email_outbox (created_at) where sent_at is null and error is null;
alter table public.email_outbox enable row level security;
revoke all on public.email_outbox from anon, authenticated;
grant all on public.email_outbox to service_role;

-- The reminders queued before, not yet sent, go out from here.
insert into public.email_outbox (kind, user_id, email, subject, body, link, created_at)
select 'appointment_nudge', n.user_id, n.email, n.subject, n.body, n.link, n.created_at
  from public.appointment_nudges n
 where n.sent_at is null and n.error is null
   and not exists (select 1 from public.email_outbox o where o.kind = 'appointment_nudge' and o.email = n.email and o.link = n.link);
update public.appointment_nudges set error = 'Moved to email_outbox' where sent_at is null and error is null;

/**
 * Appointment Updates on a lead's page: every update made to its appointments, newest first, with who
 * made it (and whether a client), the appointment's day and time, the status and the one before,
 * the note and the premium. Staff read any lead's; a client's people, their own company's.
 */
create or replace function public.lead_client_updates(p_lead_id bigint)
returns table (id bigint, appointment_id bigint, status text, previous_status text, note text,
  potential_premium numeric, sold_lines jsonb, total_premium numeric, created_at timestamptz,
  by_name text, by_client boolean, appt_date date, appt_time text)
language sql stable security definer set search_path = public as $$
  select x.id, x.appointment_id, x.status, x.previous_status, x.note, x.potential_premium, x.sold_lines, x.total_premium, x.created_at,
         nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.role = 'client', a.appt_date, a.appt_time
    from public.appointment_updates x
    left join public.users u on u.id = x.created_by
    left join public.appointments a on a.id = x.appointment_id
   where x.lead_id = p_lead_id
     and public.app_user_id() is not null
     and (public.is_staff() or x.company_id = public.app_company_id())
   order by x.created_at desc, x.id desc
   limit 300;
$$;
revoke execute on function public.lead_client_updates(bigint) from public, anon;
grant execute on function public.lead_client_updates(bigint) to authenticated;

create or replace function public.update_appointment_status(p_appointment_id bigint, p_status text, p_note text default null,
  p_potential_premium numeric default null, p_sold_lines jsonb default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me      public.users;
  a         public.appointments;
  l         public.leads;
  v_company bigint;
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_lines   jsonb := '[]'::jsonb;
  v_total   numeric := null;
  v_line    jsonb;
  v_prem    numeric;
  v_carrier text;
  v_prev    text;
  v_label   text;
  v_to      bigint[];
  v_id      bigint;
  v_subject text;
  v_text    text;
begin
  select * into v_me from public.users where id = public.app_user_id();
  if v_me.id is null then
    raise exception 'Sign in to update an appointment' using errcode = '42501';
  end if;
  select * into a from public.appointments where id = p_appointment_id and deleted_at is null;
  if a.id is null then
    raise exception 'That appointment is no longer there' using errcode = '22023';
  end if;
  select company_id into v_company from public.projects where id = coalesce(a.project_id, a.set_project_id);
  if not (public.is_admin()
          or (v_me.role = 'client' and coalesce(a.project_id, a.set_project_id) in (select public.client_project_ids())
              and coalesce(a.qa_status, 'passed') = 'passed')) then
    raise exception 'That appointment is not yours to update' using errcode = '42501';
  end if;
  if p_status not in ('pending_appointment', 'no_status', 'valid', 'valid_quoting', 'valid_not_quoting',
                      'quoted_not_sold', 'sold', 'invalid', 'reschedule') then
    raise exception 'Choose one of the statuses' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 2000 then
    raise exception 'Keep the note under 2,000 characters' using errcode = '22023';
  end if;
  if p_status = 'valid_quoting' and p_potential_premium is not null and (p_potential_premium < 0 or p_potential_premium > 999999999) then
    raise exception 'Enter the potential premium as an amount' using errcode = '22023';
  end if;
  if p_status = 'sold' then
    if p_sold_lines is null or jsonb_typeof(p_sold_lines) <> 'array' then
      raise exception 'Enter the premium on each policy line sold' using errcode = '22023';
    end if;
    for v_line in select * from jsonb_array_elements(p_sold_lines) loop
      if coalesce(v_line->>'line', '') not in ('liability', 'work_comp', 'auto', 'umbrella', 'eo', 'personal', 'health') then
        raise exception 'That is not one of the policy lines' using errcode = '22023';
      end if;
      begin
        v_prem := nullif(v_line->>'premium', '')::numeric;
      exception when others then
        raise exception 'Enter each premium as an amount' using errcode = '22023';
      end;
      continue when v_prem is null or v_prem = 0;
      if v_prem < 0 or v_prem > 999999999 then
        raise exception 'Enter each premium as an amount' using errcode = '22023';
      end if;
      v_carrier := nullif(btrim(coalesce(v_line->>'carrier', '')), '');
      if v_carrier is null then
        raise exception 'Choose the carrier each line was placed with' using errcode = '22023';
      end if;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('line', v_line->>'line', 'premium', round(v_prem, 2), 'carrier', left(v_carrier, 120)));
      v_total := coalesce(v_total, 0) + round(v_prem, 2);
    end loop;
    if v_total is null then
      raise exception 'Enter the premium on at least one policy line' using errcode = '22023';
    end if;
  end if;

  v_prev := public.appointment_update_status(a.client_result, a.appt_date, a.appt_time);
  update public.appointments set
    client_result = p_status,
    client_result_at = now(),
    client_result_by = v_me.id,
    quoted_premium = case when p_status = 'valid_quoting' then round(p_potential_premium, 2) else quoted_premium end,
    sold_lines = case when p_status = 'sold' then v_lines else null end,
    written_premium = case when p_status = 'sold' then v_total else null end
  where id = a.id;
  insert into public.appointment_updates (appointment_id, lead_id, project_id, company_id, status, previous_status, note,
    potential_premium, sold_lines, total_premium, created_by)
  values (a.id, a.lead_id, coalesce(a.project_id, a.set_project_id), v_company, p_status, v_prev, v_note,
    case when p_status = 'valid_quoting' then round(p_potential_premium, 2) end,
    case when p_status = 'sold' then v_lines end, v_total, v_me.id)
  returning id into v_id;

  -- The administrators, and the manager who set it, hear of it.
  select * into l from public.leads where id = a.lead_id;
  v_label := public.appointment_update_label(p_status);
  select array_agg(distinct u.id) into v_to from public.users u
   where u.status = 'active' and u.id <> v_me.id and (u.role = 'admin' or u.id = a.user_id);
  if v_to is not null then
    v_subject := left('Appointment update: ' || v_label || ' · ' || coalesce(l.company_name, 'an appointment'), 160);
    v_text := left(concat_ws(' · ',
        coalesce(nullif(btrim(concat_ws(' ', v_me.first_name, v_me.last_name)), ''), v_me.email),
        'Appointment ' || to_char(a.appt_date, 'FMMM/FMDD/YYYY'),
        case when p_status = 'valid_quoting' and p_potential_premium is not null then 'Potential premium $' || to_char(p_potential_premium, 'FM999,999,999,990.00') end,
        case when p_status = 'sold' then 'Total premium $' || to_char(v_total, 'FM999,999,999,990.00') end,
        v_note), 1000);
    perform public.notify_users(v_to, 'appointment', v_subject, v_text,
      '/leads/' || a.lead_id || '?tab=updates', null, gen_random_uuid(), v_me.id);
    -- And by email (Sean, Oct 2026): to each of them who takes alerts, for the app to send.
    insert into public.email_outbox (kind, user_id, email, subject, body, link)
    select 'appointment_update', u.id, u.email, v_subject, v_text, '/leads/' || a.lead_id || '?tab=updates'
      from public.users u
     where u.id = any(v_to) and coalesce(u.alerts_enabled, true) and nullif(btrim(u.email), '') is not null;
  end if;
  return jsonb_build_object('id', v_id, 'status', p_status, 'label', v_label, 'total', v_total);
end $$;

revoke execute on function public.update_appointment_status(bigint, text, text, numeric, jsonb) from public, anon;
grant execute on function public.update_appointment_status(bigint, text, text, numeric, jsonb) to authenticated;

create or replace function public.nudge_appointment_updates(p_now timestamptz default now())
returns integer
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_tz     text := public.business_tz();
  v_today  date := (p_now at time zone v_tz)::date;
  v_hour   int := extract(hour from p_now at time zone v_tz)::int;
  r        record;
  v_n      int;
  v_title  text;
  v_body   text;
  v_link   text;
  v_to     bigint[];
  v_count  int := 0;
  v_url    text;
  v_secret text;
begin
  if extract(isodow from v_today) > 5 or v_hour < 8 or v_hour >= 18 then
    return 0;
  end if;
  for r in
    select a.id, a.lead_id, a.appt_date, a.update_nudge_1_at, a.update_nudge_2_at, l.company_name, p.company_id, p.id as project_id
      from public.appointments a
      join public.leads l on l.id = a.lead_id and l.deleted_at is null
      join public.projects p on p.id = coalesce(a.project_id, a.set_project_id) and p.deleted_at is null
     where a.deleted_at is null and a.invalid_at is null and coalesce(a.qa_status, 'passed') = 'passed'
       and public.appointment_update_status(a.client_result, a.appt_date, a.appt_time) = 'no_status'
       and a.appt_date >= v_today - 30
       and (a.update_nudge_2_at is null)
       and v_today >= public.business_days_after(a.appt_date, 2)
     for update of a skip locked
  loop
    v_n := case when v_today >= public.business_days_after(r.appt_date, 4) then 2
                when r.update_nudge_1_at is null then 1 else null end;
    continue when v_n is null;
    v_link := '/appointments?update=' || r.id;
    if v_n = 1 then
      v_title := left('How did your appointment with ' || coalesce(r.company_name, 'the business') || ' go?', 160);
      v_body := 'How did your Appointment with ' || coalesce(r.company_name, 'the business') || ' work out on '
        || to_char(r.appt_date, 'FMMM/FMDD/YYYY') || '? Please update the status of the Appointment in Lighthouse so we can let our team know how they did.';
    else
      v_title := left('Reminder: update your appointment with ' || coalesce(r.company_name, 'the business'), 160);
      v_body := 'Reminder to update the status of your Appointment with ' || coalesce(r.company_name, 'the business') || ' that was on '
        || to_char(r.appt_date, 'FMMM/FMDD/YYYY') || ' by tomorrow in order to receive credit if it was invalid.';
    end if;
    select array_agg(u.id) into v_to from public.users u
     where u.company_id = r.company_id and u.role = 'client' and u.status = 'active' and u.deleted_at is null;
    if v_to is not null then
      perform public.notify_users(v_to, 'appointment', v_title, v_body, v_link, null, gen_random_uuid(), null);
    end if;
    -- By email too (Sean, Oct 2026): the client's people, and the project's agent (its Project Info), once each.
    insert into public.email_outbox (kind, user_id, email, subject, body, link)
    select distinct on (lower(btrim(x.email))) 'appointment_nudge', x.user_id, btrim(x.email), v_title, v_body, v_link
      from (
        select u.id as user_id, u.email from public.users u where u.id = any(coalesce(v_to, '{}'))
        union all
        select null, pp.agent_email from public.project_profiles pp where pp.project_id = r.project_id
      ) x
     where x.email ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'
     order by lower(btrim(x.email)), x.user_id nulls last;
    -- The 4th day's reminder stands for the 2nd too, when the first went unsent (the job was off).
    update public.appointments set update_nudge_1_at = coalesce(update_nudge_1_at, now()),
                                   update_nudge_2_at = case when v_n = 2 then now() else update_nudge_2_at end
     where id = r.id;
    v_count := v_count + 1;
  end loop;

  -- The emails go from the app: ask it, as the hourly deliveries are asked.
  if exists (select 1 from public.email_outbox where sent_at is null and error is null) then
    begin
      select decrypted_secret into v_url from vault.decrypted_secrets where name = 'push_deliver_url';
      select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_deliver_secret';
      if v_url like '%/api/push/deliver' and v_secret is not null then
        perform net.http_post(
          url := replace(v_url, '/api/push/deliver', '/api/appointments/nudge'),
          body := '{}'::jsonb,
          headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
          timeout_milliseconds := 60000);
      end if;
    exception when others then
      raise warning 'appointment nudges: % (%)', sqlerrm, sqlstate;
    end;
  end if;
  return v_count;
end $$;

revoke execute on function public.nudge_appointment_updates(timestamptz) from public, anon, authenticated;
grant execute on function public.nudge_appointment_updates(timestamptz) to service_role;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261129100000_monthly_goals.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a project's goals per month (Sean, Oct 2026)
--
-- A client wants, say, 5 appointments a month: the project keeps that as
-- its monthly goal, its overall goal following from it (5 × 12 = 60) unless
-- one is set. Project pages and Project Goals show the project's average per
-- month against it, and this month's so far.
--
--   projects.lead_goal_month, appt_goal_month   the goals per month
--   project_month_counts(projects)   this month's leads and appointments
--                                    developed on each (business time)
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

alter table public.projects add column if not exists lead_goal_month int;
alter table public.projects add column if not exists appt_goal_month int;
alter table public.projects drop constraint if exists projects_lead_goal_month_check;
alter table public.projects add constraint projects_lead_goal_month_check check (lead_goal_month is null or lead_goal_month between 0 and 100000);
alter table public.projects drop constraint if exists projects_appt_goal_month_check;
alter table public.projects add constraint projects_appt_goal_month_check check (appt_goal_month is null or appt_goal_month between 0 and 100000);

/** This month's leads and appointments developed on each project asked for (administrators and managers). */
create or replace function public.project_month_counts(p_project_ids bigint[])
returns table (project_id bigint, leads bigint, appointments bigint)
language sql stable security definer set search_path = public as $$
  select e.project_id, count(*) filter (where e.kind = 'lead'), count(*) filter (where e.kind = 'appointment')
    from public.pay_events e
   where public.is_manager()
     and e.project_id = any(p_project_ids) and not e.is_chargeback and e.kind in ('lead', 'appointment')
     and e.created_at >= (date_trunc('month', now() at time zone public.business_tz()) at time zone public.business_tz())
   group by 1;
$$;
revoke execute on function public.project_month_counts(bigint[]) from public, anon;
grant execute on function public.project_month_counts(bigint[]) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261130100000_sales_rep_watchers.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — a client's Sales Rep, and who hears about the client (Sean, Oct 2026)
--
--   companies.sales_rep_id    the administrator or manager who owns the client
--                             (and so all its projects)
--   client_watchers           who gets the notifications about a client and its
--                             projects, each by notification alone or by email
--                             too; with nobody chosen, its Sales Rep (notification)
--   client_watchers_of(company)              the people, as above
--   notify_client_watchers(company, …)       tell them (and queue the emails)
--   appointments set, the client's appointment updates (update_appointment_status),
--   client feedback and files the client adds: their watchers are told too
--   email_outbox             an insert asks the app to send at once (through
--                            pg_net, as push notifications are), not on the hour
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

alter table public.companies add column if not exists sales_rep_id bigint references public.users(id) on delete set null;
create index if not exists companies_sales_rep on public.companies (sales_rep_id);

create table if not exists public.client_watchers (
  company_id  bigint not null references public.companies(id) on delete cascade,
  user_id     bigint not null references public.users(id) on delete cascade,
  by_email    boolean not null default false,
  primary key (company_id, user_id)
);
alter table public.client_watchers enable row level security;
drop policy if exists client_watchers_read on public.client_watchers;
create policy client_watchers_read on public.client_watchers for select to authenticated using ((select public.is_staff()));
drop policy if exists client_watchers_write on public.client_watchers;
create policy client_watchers_write on public.client_watchers for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists mfa_required on public.client_watchers;
create policy mfa_required on public.client_watchers as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.client_watchers;
create policy active_account_required on public.client_watchers as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.client_watchers from anon;
grant select, insert, update, delete on public.client_watchers to authenticated;
grant all on public.client_watchers to service_role;

/** Who hears about a client: those chosen (active), or with nobody chosen its Sales Rep, by notification. */
create or replace function public.client_watchers_of(p_company_id bigint)
returns table (user_id bigint, by_email boolean)
language sql stable security definer set search_path = public as $$
  with chosen as (
    select w.user_id, w.by_email from public.client_watchers w
      join public.users u on u.id = w.user_id and u.status = 'active' and u.deleted_at is null
     where w.company_id = p_company_id
  )
  select * from chosen
  union all
  select c.sales_rep_id, false from public.companies c
    join public.users u on u.id = c.sales_rep_id and u.status = 'active' and u.deleted_at is null
   where c.id = p_company_id and not exists (select 1 from chosen);
$$;
revoke execute on function public.client_watchers_of(bigint) from public, anon, authenticated;
grant execute on function public.client_watchers_of(bigint) to service_role;

/**
 * Tell a client's watchers: a notification to each not in `p_already` (told already by the event's
 * own rules), and an email to each who takes them by email.
 */
create or replace function public.notify_client_watchers(p_company_id bigint, p_kind text, p_title text, p_body text,
  p_link text, p_already bigint[] default '{}', p_sender bigint default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_to bigint[];
begin
  if p_company_id is null then return; end if;
  select array_agg(w.user_id) into v_to from public.client_watchers_of(p_company_id) w
   where not (w.user_id = any(coalesce(p_already, '{}'))) and w.user_id is distinct from p_sender;
  if v_to is not null then
    perform public.notify_users(v_to, p_kind, p_title, p_body, p_link, null, gen_random_uuid(), p_sender);
  end if;
  insert into public.email_outbox (kind, user_id, email, subject, body, link)
  select 'client_' || p_kind, u.id, u.email, left(p_title, 200), left(coalesce(p_body, ''), 2000), p_link
    from public.client_watchers_of(p_company_id) w join public.users u on u.id = w.user_id
   where w.by_email and w.user_id is distinct from p_sender and nullif(btrim(u.email), '') is not null;
end $$;
revoke execute on function public.notify_client_watchers(bigint, text, text, text, text, bigint[], bigint) from public, anon, authenticated;
grant execute on function public.notify_client_watchers(bigint, text, text, text, text, bigint[], bigint) to service_role;

-- --- Appointments set: the client's watchers too ---------------------------------------
create or replace function public.tg_notify_appointments()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  r record;
  v_to bigint[];
  v_title text;
  v_body text;
  v_link text;
begin
  for r in
    select p.company_id,
           min(co.name) as company,
           count(*) as n,
           min(a.appt_date) as first_date,
           max(a.appt_date) as last_date,
           array_agg(distinct p.id) filter (where p.id is not null) as project_ids,
           array_agg(distinct l.assigned_user_id) filter (where l.assigned_user_id is not null) as reps,
           (array_agg(l.company_name order by a.appt_date, a.id))[1] as lead_name,
           (array_agg(a.appt_time order by a.appt_date, a.id))[1] as first_time,
           (array_agg(a.id order by a.appt_date, a.id))[1] as first_id,
           bool_or(coalesce(a.qa_status, 'passed') = 'passed') as client_may_know
      from new_rows a
      left join public.leads l     on l.id  = a.lead_id
      left join public.projects p  on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
     group by p.company_id
  loop
    v_to := array(
      select id from public.users where role = 'admin'
      union
      select pa.ae_user_id from public.project_assignments pa
       where pa.project_id = any(r.project_ids) and pa.ae_user_id is not null
      union
      select u.id from public.users u
       where r.client_may_know and u.role = 'client' and r.company_id is not null and u.company_id = r.company_id
      union
      select unnest(r.reps)
    );
    v_title := case when r.n = 1 then 'Appointment set: ' || coalesce(r.lead_name, 'a lead')
                    else r.n || ' appointments set' || coalesce(' for ' || r.company, '') end;
    v_body := case when r.n = 1
                   then concat_ws(' · ', to_char(r.first_date, 'Dy Mon FMDD') || coalesce(' at ' || r.first_time, ''), r.company, 'set by ' || public.actor_name())
                   else concat_ws(' · ', to_char(r.first_date, 'Mon FMDD') || ' – ' || to_char(r.last_date, 'Mon FMDD'), 'set by ' || public.actor_name()) end;
    v_link := '/calendar?view=' || case when r.n = 1 then 'day' else 'month' end
        || '&d=' || coalesce(r.first_date, current_date)::text
        || case when r.n = 1 then '&a=' || r.first_id else '' end;
    perform public.notify_users(v_to, 'appointment', v_title, v_body, v_link, 'appt_created');
    -- The client's watchers (Sales Rep, or those chosen; Sean, Oct 2026), by email too when they asked.
    perform public.notify_client_watchers(r.company_id, 'appointment', v_title, v_body, v_link, v_to);
  end loop;
  return null;
end $$;

-- --- Client feedback: the client's watchers too -------------------------------------------
create or replace function public.tg_notify_feedback()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_company text;
  v_company_id bigint;
  v_admins bigint[] := array(select id from public.users where role = 'admin');
  v_title text;
  v_body text;
begin
  select co.name, co.id into v_company, v_company_id
    from public.leads l
    join public.projects p   on p.id  = l.project_id
    join public.companies co on co.id = p.company_id
   where l.id = new.lead_id;
  v_title := 'New client feedback' || coalesce(' from ' || v_company, '');
  v_body := concat_ws(' · ', case when new.rating is not null then repeat('★', new.rating) || repeat('☆', 5 - new.rating) end, left(new.content, 140));
  perform public.notify_users(v_admins, 'feedback', v_title, v_body, '/feedback', 'feedback_new');
  perform public.notify_client_watchers(v_company_id, 'feedback', v_title, v_body, '/feedback', v_admins);
  return null;
end $$;

-- --- Files the client adds: the client's watchers too ---------------------------------------
create or replace function public.tg_documents_notify()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  l       public.leads;
  a       public.appointments;
  v_role  text;
  v_to    bigint[];
  v_company bigint;
begin
  if new.lead_id is null then
    return null;
  end if;
  select * into l from public.leads where id = new.lead_id;
  select * into a from public.appointments
   where lead_id = new.lead_id and invalid_at is null and deleted_at is null
   order by appt_create_date desc, id desc limit 1;
  select role into v_role from public.users where id = new.uploaded_by;

  if v_role = 'client' then
    v_to := array_remove(array[l.assigned_user_id, a.user_id], null);
    perform public.notify_users(v_to, 'lead',
      left('Policy file added: ' || coalesce(l.company_name, 'a lead'), 160),
      left(new.name || ' · from ' || coalesce(public.actor_name(), 'the client'), 1000),
      '/leads/' || l.id || '?tab=files', null);
    select company_id into v_company from public.projects where id = l.project_id;
    perform public.notify_client_watchers(v_company, 'lead',
      left('Policy file added: ' || coalesce(l.company_name, 'a lead'), 160),
      left(new.name || ' · from ' || coalesce(public.actor_name(), 'the client'), 1000),
      '/leads/' || l.id || '?tab=files', v_to, new.uploaded_by);
  elsif a.id is not null and coalesce(a.qa_status, 'passed') = 'passed' then
    select array_agg(u.id) into v_to from public.users u join public.projects p on p.company_id = u.company_id
     where p.id = l.project_id and u.role = 'client' and u.status = 'active' and u.deleted_at is null;
    perform public.notify_users(coalesce(v_to, '{}'), 'appointment',
      left('Policy file added: ' || coalesce(l.company_name, 'an appointment'), 160),
      left(new.name || ' · for the appointment on ' || to_char(a.appt_date, 'Dy MM/DD/YYYY') || coalesce(' ' || a.appt_time, ''), 1000),
      '/calendar?view=day&d=' || a.appt_date || '&a=' || a.id, null);
  end if;
  return null;
end $$;

-- --- The client's appointment updates: its watchers too ---------------------------------------
create or replace function public.update_appointment_status(p_appointment_id bigint, p_status text, p_note text default null,
  p_potential_premium numeric default null, p_sold_lines jsonb default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me      public.users;
  a         public.appointments;
  l         public.leads;
  v_company bigint;
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_lines   jsonb := '[]'::jsonb;
  v_total   numeric := null;
  v_line    jsonb;
  v_prem    numeric;
  v_carrier text;
  v_prev    text;
  v_label   text;
  v_to      bigint[];
  v_id      bigint;
  v_subject text;
  v_text    text;
begin
  select * into v_me from public.users where id = public.app_user_id();
  if v_me.id is null then
    raise exception 'Sign in to update an appointment' using errcode = '42501';
  end if;
  select * into a from public.appointments where id = p_appointment_id and deleted_at is null;
  if a.id is null then
    raise exception 'That appointment is no longer there' using errcode = '22023';
  end if;
  select company_id into v_company from public.projects where id = coalesce(a.project_id, a.set_project_id);
  if not (public.is_admin()
          or (v_me.role = 'client' and coalesce(a.project_id, a.set_project_id) in (select public.client_project_ids())
              and coalesce(a.qa_status, 'passed') = 'passed')) then
    raise exception 'That appointment is not yours to update' using errcode = '42501';
  end if;
  if p_status not in ('pending_appointment', 'no_status', 'valid', 'valid_quoting', 'valid_not_quoting',
                      'quoted_not_sold', 'sold', 'invalid', 'reschedule') then
    raise exception 'Choose one of the statuses' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 2000 then
    raise exception 'Keep the note under 2,000 characters' using errcode = '22023';
  end if;
  if p_status = 'valid_quoting' and p_potential_premium is not null and (p_potential_premium < 0 or p_potential_premium > 999999999) then
    raise exception 'Enter the potential premium as an amount' using errcode = '22023';
  end if;
  if p_status = 'sold' then
    if p_sold_lines is null or jsonb_typeof(p_sold_lines) <> 'array' then
      raise exception 'Enter the premium on each policy line sold' using errcode = '22023';
    end if;
    for v_line in select * from jsonb_array_elements(p_sold_lines) loop
      if coalesce(v_line->>'line', '') not in ('liability', 'work_comp', 'auto', 'umbrella', 'eo', 'personal', 'health') then
        raise exception 'That is not one of the policy lines' using errcode = '22023';
      end if;
      begin
        v_prem := nullif(v_line->>'premium', '')::numeric;
      exception when others then
        raise exception 'Enter each premium as an amount' using errcode = '22023';
      end;
      continue when v_prem is null or v_prem = 0;
      if v_prem < 0 or v_prem > 999999999 then
        raise exception 'Enter each premium as an amount' using errcode = '22023';
      end if;
      v_carrier := nullif(btrim(coalesce(v_line->>'carrier', '')), '');
      if v_carrier is null then
        raise exception 'Choose the carrier each line was placed with' using errcode = '22023';
      end if;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('line', v_line->>'line', 'premium', round(v_prem, 2), 'carrier', left(v_carrier, 120)));
      v_total := coalesce(v_total, 0) + round(v_prem, 2);
    end loop;
    if v_total is null then
      raise exception 'Enter the premium on at least one policy line' using errcode = '22023';
    end if;
  end if;

  v_prev := public.appointment_update_status(a.client_result, a.appt_date, a.appt_time);
  update public.appointments set
    client_result = p_status,
    client_result_at = now(),
    client_result_by = v_me.id,
    quoted_premium = case when p_status = 'valid_quoting' then round(p_potential_premium, 2) else quoted_premium end,
    sold_lines = case when p_status = 'sold' then v_lines else null end,
    written_premium = case when p_status = 'sold' then v_total else null end
  where id = a.id;
  insert into public.appointment_updates (appointment_id, lead_id, project_id, company_id, status, previous_status, note,
    potential_premium, sold_lines, total_premium, created_by)
  values (a.id, a.lead_id, coalesce(a.project_id, a.set_project_id), v_company, p_status, v_prev, v_note,
    case when p_status = 'valid_quoting' then round(p_potential_premium, 2) end,
    case when p_status = 'sold' then v_lines end, v_total, v_me.id)
  returning id into v_id;

  -- The administrators, and the manager who set it, hear of it.
  select * into l from public.leads where id = a.lead_id;
  v_label := public.appointment_update_label(p_status);
  select array_agg(distinct u.id) into v_to from public.users u
   where u.status = 'active' and u.id <> v_me.id and (u.role = 'admin' or u.id = a.user_id);
  if v_to is not null then
    v_subject := left('Appointment update: ' || v_label || ' · ' || coalesce(l.company_name, 'an appointment'), 160);
    v_text := left(concat_ws(' · ',
        coalesce(nullif(btrim(concat_ws(' ', v_me.first_name, v_me.last_name)), ''), v_me.email),
        'Appointment ' || to_char(a.appt_date, 'FMMM/FMDD/YYYY'),
        case when p_status = 'valid_quoting' and p_potential_premium is not null then 'Potential premium $' || to_char(p_potential_premium, 'FM999,999,999,990.00') end,
        case when p_status = 'sold' then 'Total premium $' || to_char(v_total, 'FM999,999,999,990.00') end,
        v_note), 1000);
    perform public.notify_users(v_to, 'appointment', v_subject, v_text,
      '/leads/' || a.lead_id || '?tab=updates', null, gen_random_uuid(), v_me.id);
    -- And by email (Sean, Oct 2026): to each of them who takes alerts, for the app to send.
    insert into public.email_outbox (kind, user_id, email, subject, body, link)
    select 'appointment_update', u.id, u.email, v_subject, v_text, '/leads/' || a.lead_id || '?tab=updates'
      from public.users u
     where u.id = any(v_to) and coalesce(u.alerts_enabled, true) and nullif(btrim(u.email), '') is not null;
  end if;
  -- The client's watchers (its Sales Rep, or those chosen; Sean, Oct 2026), by email too when they asked.
  perform public.notify_client_watchers(v_company,  'appointment',
    left('Appointment update: ' || v_label || ' · ' || coalesce(l.company_name, 'an appointment'), 160),
    coalesce(v_text, ''), '/leads/' || a.lead_id || '?tab=updates', coalesce(v_to, '{}'), v_me.id);
  return jsonb_build_object('id', v_id, 'status', p_status, 'label', v_label, 'total', v_total);
end $$;
revoke execute on function public.update_appointment_status(bigint, text, text, numeric, jsonb) from public, anon;
grant execute on function public.update_appointment_status(bigint, text, text, numeric, jsonb) to authenticated;

-- --- Emails go at once ---------------------------------------------------------------------
-- Whatever queues an email asks the app to send it now (the same call the hourly job makes).
create or replace function public.tg_email_outbox_send()
returns trigger
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_url text;
  v_secret text;
begin
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'push_deliver_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_deliver_secret';
  if v_url like '%/api/push/deliver' and v_secret is not null then
    perform net.http_post(
      url := replace(v_url, '/api/push/deliver', '/api/appointments/nudge'),
      body := '{}'::jsonb,
      headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
      timeout_milliseconds := 60000);
  end if;
  return null;
exception when others then
  raise warning 'email outbox: % (%)', sqlerrm, sqlstate;
  return null;
end $$;
revoke execute on function public.tg_email_outbox_send() from public, anon, authenticated;
drop trigger if exists email_outbox_send on public.email_outbox;
create trigger email_outbox_send after insert on public.email_outbox
  for each statement execute function public.tg_email_outbox_send();

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261201100000_campaign_filter.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — Recent Activity by campaign (Sean, Oct 2026)
--
-- A client's Recent Activity filtered by project now takes a campaign: the
-- project chosen with those tied to it (a DB dev project and the
-- appointment project it promotes to), so the leads developed and the
-- appointments set on them show together.
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

-- Recent Activity, as before; its project now a campaign (the row it returns is the same, but made again to be sure).
drop function if exists public.client_activity(date, date, bigint, text, bigint);
create function public.client_activity(p_from date, p_to date, p_project_id bigint default null,
  p_kind text default null, p_company_id bigint default null)
returns table (id bigint, at timestamptz, kind text, result text, lead_id bigint, company text, city text, state text,
  project_id bigint, project text, agent text, manager text, xdate date, manager_id bigint)
language sql stable security definer set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), mine as (
    select p.id from public.projects p
     where p.deleted_at is null
       and (case when public.is_staff() then (p_company_id is null or p.company_id = p_company_id)
                 else p.id in (select public.client_project_ids()) end)
       -- A campaign (Sean, Oct 2026): the project chosen and those tied to it, a DB dev project and the
       -- appointment project it promotes to, either way round.
       and (p_project_id is null or p.id = p_project_id or p.appt_project_id = p_project_id
            or p.id = (select x.appt_project_id from public.projects x where x.id = p_project_id))
  )
  select e.id, e.created_at, e.kind,
         case when e.kind = 'lead' then 'Lead'
              when ap.invalid_at is not null then 'Appointment-Invalid'
              when ap.confirmed_at is not null then 'Appointment-Confirmed'
              else 'Appointment' end,
         l.id, l.company_name, l.city, l.state, pr.id, pr.name,
         coalesce(nullif(btrim(ap.rep_name), ''), nullif(btrim(pr.contact_name), '')),
         nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''),
         (select min(coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                                      i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)))
            from public.insurance_details i where i.lead_id = l.id),
         case when u.status = 'active' then u.id end
    from public.pay_events e
    join public.leads l on l.id = e.lead_id and l.deleted_at is null
    join public.projects pr on pr.id = coalesce(e.project_id, l.project_id)
    left join public.appointments ap on ap.id = e.appointment_id
    left join public.users u on u.id = e.user_id, z
   where public.app_user_id() is not null
     and pr.id in (select id from mine)
     and e.kind in ('lead', 'appointment') and not e.is_chargeback
     and (p_kind is null or e.kind = p_kind)
     and e.created_at >= (p_from::timestamp at time zone z.tz)
     and e.created_at < ((p_to + 1)::timestamp at time zone z.tz)
     and (e.kind = 'lead' or coalesce(ap.qa_status, 'passed') = 'passed')
   order by e.created_at desc, e.id desc
   limit 1000;
$$;
revoke execute on function public.client_activity(date, date, bigint, text, bigint) from public, anon;
grant execute on function public.client_activity(date, date, bigint, text, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261202100000_client_projects.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — clients see their own projects (Sean, Oct 2026)
--
-- A client's people open Projects for their own projects. The project's
-- figures count its calls, which they cannot read one by one: they get the
-- times of the calls on their own projects (no caller, no lead), enough for
-- Calls This Month and its last two weeks.
--
--   project_call_dates(project)   when each call on it was made (staff: any
--                                 project; a client: their own)
--   project_overview()            counts the calls through it
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

create or replace function public.project_call_dates(p_project_id bigint)
returns table (call_date timestamptz)
language sql stable security definer set search_path = public as $$
  select c.call_date from public.call_records c
   where c.project_id = p_project_id
     and public.app_user_id() is not null
     and (public.is_staff() or p_project_id in (select public.client_project_ids()));
$$;
revoke execute on function public.project_call_dates(bigint) from public, anon;
grant execute on function public.project_call_dates(bigint) to authenticated;

create or replace function public.project_overview(p_project_id bigint)
returns jsonb
language sql stable security invoker set search_path = public as $$
  with b as (select * from public.business_bounds()),
  l as (
    select l.assigned_user_id, r.viable, r.callable
      from public.leads l join public.call_results r on r.id = l.result_id
     where l.project_id = p_project_id
  ),
  a as (
    select a.qa_status, a.appt_create_date from public.appointments a
     where (a.project_id = p_project_id or a.set_project_id = p_project_id) and a.invalid_at is null
  ),
  -- Through project_call_dates(): a client's people may count the calls on their own project too.
  c as (select c.call_date from public.project_call_dates(p_project_id) c),
  days as (
    select generate_series(0, 13) as ago
  )
  select jsonb_build_object(
    'leads',        (select count(*) from l),
    'viable_left',  (select count(*) from l where viable and callable),
    'unassigned',   (select count(*) from l where viable and callable and assigned_user_id is null),
    'pending',      (select count(*) from l where viable and not callable),
    'off_list',     (select count(*) from l where not viable),
    'appointments', (select count(*) from a),
    'appts_month',  (select count(*) from a, b where a.appt_create_date >= b.month_start),
    'qa_pending',   (select count(*) from a where a.qa_status = 'pending'),
    'calls_today',  (select count(*) from c, b where c.call_date >= b.day_start),
    'calls_month',  (select count(*) from c, b where c.call_date >= b.month_start),
    'last_worked',  (select max(c.call_date) from c),
    -- Calls per day for the last two weeks, oldest first (the tile sparkline).
    'calls_14d',    (select coalesce(jsonb_agg(n order by ago desc), '[]'::jsonb)
                       from (select d.ago, (select count(*) from c, b
                                             where c.call_date >= b.day_start - make_interval(days => d.ago)
                                               and c.call_date <  b.day_start - make_interval(days => d.ago - 1)) as n
                               from days d) t)
  );
$$;
revoke execute on function public.project_overview(bigint) from public, anon;
grant execute on function public.project_overview(bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261203100000_email_dedupe.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — one email per person per event (Sean, Oct 2026)
--
-- An administrator who also watches a client (by email) got a client's
-- appointment update twice: once as an administrator, once as a watcher.
-- The notification was told once already; now the email is too: a watcher's
-- email is not queued when the same one (same person, subject and link) was
-- queued a moment before.
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

create or replace function public.notify_client_watchers(p_company_id bigint, p_kind text, p_title text, p_body text,
  p_link text, p_already bigint[] default '{}', p_sender bigint default null)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_to bigint[];
begin
  if p_company_id is null then return; end if;
  select array_agg(w.user_id) into v_to from public.client_watchers_of(p_company_id) w
   where not (w.user_id = any(coalesce(p_already, '{}'))) and w.user_id is distinct from p_sender;
  if v_to is not null then
    perform public.notify_users(v_to, p_kind, p_title, p_body, p_link, null, gen_random_uuid(), p_sender);
  end if;
  -- By email to those who asked, unless the event has emailed them the same already.
  insert into public.email_outbox (kind, user_id, email, subject, body, link)
  select 'client_' || p_kind, u.id, u.email, left(p_title, 200), left(coalesce(p_body, ''), 2000), p_link
    from public.client_watchers_of(p_company_id) w join public.users u on u.id = w.user_id
   where w.by_email and w.user_id is distinct from p_sender and nullif(btrim(u.email), '') is not null
     and not exists (select 1 from public.email_outbox o
                      where o.user_id = u.id and o.subject = left(p_title, 200) and o.link is not distinct from p_link
                        and o.created_at > now() - interval '5 minutes');
end $$;
revoke execute on function public.notify_client_watchers(bigint, text, text, text, text, bigint[], bigint) from public, anon, authenticated;
grant execute on function public.notify_client_watchers(bigint, text, text, text, text, bigint[], bigint) to service_role;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261204100000_client_rep_names.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — the manager on a client's leads (Sean, Oct 2026)
--
-- A client's people cannot read the staff, so the manager assigned to their
-- leads read as "Unassigned" (Leads on this project, X-Dates by Month's
-- names). They get the name of whoever works each of their own leads.
--
--   lead_rep_names(leads)   each lead's assigned manager's name, for the
--                           leads the caller may see (staff: any; a client:
--                           those on their projects)
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

create or replace function public.lead_rep_names(p_lead_ids bigint[])
returns table (lead_id bigint, first_name text, last_name text, email text)
language sql stable security definer set search_path = public as $$
  select l.id, u.first_name, u.last_name, u.email
    from public.leads l
    join public.users u on u.id = l.assigned_user_id
   where l.id = any(p_lead_ids)
     and public.app_user_id() is not null
     and (public.is_staff() or l.project_id in (select public.client_project_ids())
          or l.source_project_id in (select public.client_project_ids()));
$$;
revoke execute on function public.lead_rep_names(bigint[]) from public, anon;
grant execute on function public.lead_rep_names(bigint[]) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261205100000_pipeline_report.sql
-- ==============================================================================================================

-- ---------------------------------------------------------------------------
-- Lighthouse CRM — X-Dates filters and the Pipeline Report (Sean, Oct 2026)
--
-- X-Dates by Month filters by project (several), client, its Sales Rep, DB dev
-- or appointment projects, and the managers the names are assigned to; and
-- shows the Pipeline Report: for each project and manager, the names renewing
-- in the months chosen (the next three to begin with), split as the chart
-- splits them (appointments, off the list, viable left), with the manager's
-- last appointment set and last call on it, this month's calls, the
-- project's pay, the client's Sales Rep and the other managers on it.
-- Managers get the report too (Data & Insights), on their own projects.
--
--   xdate_names(…filters)        each name: its project, manager, renewal
--                                month and bucket (as the caller may read)
--   xdates_filtered(…filters)    xdates_by_month(), filtered
--   xdate_month_leads_filtered() xdate_month_leads(), filtered
--   pipeline_report(months, …filters)   the report (administrators: every
--                                project; managers and agents: those they
--                                are assigned to)
--
-- Safe to run again.
-- ---------------------------------------------------------------------------

/**
 * Every name the caller may read (Row Level Security) on the projects asked for, with its project,
 * manager (assigned_user_id), renewal (its soonest X-date, as everywhere), renewal month (0: none)
 * and bucket: appointment, viable (left to work) or off (the list).
 */
create or replace function public.xdate_names(p_project_ids bigint[] default null, p_company_id bigint default null,
  p_type text default null, p_rep_id bigint default null, p_user_ids bigint[] default null)
returns table (lead_id bigint, project_id bigint, user_id bigint, renewal date, month int, bucket text)
language sql stable security invoker set search_path = public as $$
  select l.id, l.project_id, l.assigned_user_id, ren.renewal, coalesce(extract(month from ren.renewal)::int, 0),
         case when r.effect in ('appointment', 'confirm') then 'appointment' when r.viable then 'viable' else 'off' end
    from public.leads l
    join public.call_results r on r.id = l.result_id
    join public.projects p on p.id = l.project_id and p.deleted_at is null
    left join public.project_types t on t.id = p.project_type_id
    left join public.companies c on c.id = p.company_id
    left join lateral (
      select min(coalesce(i.ultimate_xdate,
                          least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate))) as renewal
        from public.insurance_details i where i.lead_id = l.id
    ) ren on true
   where l.deleted_at is null
     and (p_project_ids is null or l.project_id = any(p_project_ids))
     and (p_company_id is null or p.company_id = p_company_id)
     and (p_type is null or t.code = p_type)
     and (p_rep_id is null or c.sales_rep_id = p_rep_id)
     and (p_user_ids is null or l.assigned_user_id = any(p_user_ids));
$$;
revoke execute on function public.xdate_names(bigint[], bigint, text, bigint, bigint[]) from public, anon;
grant execute on function public.xdate_names(bigint[], bigint, text, bigint, bigint[]) to authenticated;

/** X-Dates by Month's chart, filtered: each renewal month's names, by bucket. */
create or replace function public.xdates_filtered(p_project_ids bigint[] default null, p_company_id bigint default null,
  p_type text default null, p_rep_id bigint default null, p_user_ids bigint[] default null)
returns table (month int, total bigint, appointments bigint, off_list bigint, viable_left bigint)
language sql stable security invoker set search_path = public as $$
  select x.month, count(*), count(*) filter (where x.bucket = 'appointment'), count(*) filter (where x.bucket = 'off'),
         count(*) filter (where x.bucket = 'viable')
    from public.xdate_names(p_project_ids, p_company_id, p_type, p_rep_id, p_user_ids) x
   group by x.month
   order by x.month;
$$;
revoke execute on function public.xdates_filtered(bigint[], bigint, text, bigint, bigint[]) from public, anon;
grant execute on function public.xdates_filtered(bigint[], bigint, text, bigint, bigint[]) to authenticated;

/** One page of the names behind a number in xdates_filtered(); p_bucket null means all of them. */
create or replace function public.xdate_month_leads_filtered(p_month int, p_bucket text default null,
  p_project_ids bigint[] default null, p_company_id bigint default null, p_type text default null,
  p_rep_id bigint default null, p_user_ids bigint[] default null, p_limit int default 20, p_offset int default 0)
returns table (
  id bigint, company_name text, contact_name text, phone text, city text, state text,
  project text, result text, renewal_date date, rep_first text, rep_last text, rep_email text, total bigint
)
language sql stable security invoker set search_path = public as $$
  select l.id, l.company_name, l.contact_name, l.phone, l.city, l.state,
         p.name, r.name, x.renewal, u.first_name, u.last_name, u.email, count(*) over ()
    from public.xdate_names(p_project_ids, p_company_id, p_type, p_rep_id, p_user_ids) x
    join public.leads l on l.id = x.lead_id
    join public.call_results r on r.id = l.result_id
    left join public.projects p on p.id = l.project_id
    left join public.users u on u.id = l.assigned_user_id
   where x.month = p_month and (p_bucket is null or x.bucket = p_bucket)
   order by extract(day from x.renewal) nulls last, l.company_name, l.id
   limit greatest(least(coalesce(p_limit, 20), 100), 1)
  offset greatest(coalesce(p_offset, 0), 0);
$$;
revoke execute on function public.xdate_month_leads_filtered(int, text, bigint[], bigint, text, bigint, bigint[], int, int) from public, anon;
grant execute on function public.xdate_month_leads_filtered(int, text, bigint[], bigint, text, bigint, bigint[], int, int) to authenticated;

/**
 * The Pipeline Report: a row for each project and manager with names renewing in p_months (the
 * next three months when none are given), each month's count, the total and its buckets, the
 * manager's last appointment set (its day) and last call on the project, their calls on it this
 * month, the project's pay (an appointment's, a lead's on a DB dev project) and special pay (a
 * confirmation's), the client's Sales Rep, and the other managers assigned to it. An administrator
 * reads every project; anyone else on staff, the projects they are assigned to.
 */
create or replace function public.pipeline_report(p_months int[] default null, p_project_ids bigint[] default null,
  p_company_id bigint default null, p_type text default null, p_rep_id bigint default null, p_user_ids bigint[] default null)
returns table (project_id bigint, project text, project_type text, time_zone text, state text,
  manager_id bigint, manager_first text, manager_last text, last_appt_set date, last_worked timestamptz, calls bigint,
  months jsonb, total bigint, appts bigint, off_list bigint, viable_left bigint,
  pay numeric, special_pay numeric, sales_rep_first text, sales_rep_last text, shared_with jsonb)
language plpgsql stable security definer set search_path = public as $$
declare
  v_me     bigint := public.app_user_id();
  v_tz     text := public.business_tz();
  v_today  date := (now() at time zone public.business_tz())::date;
  v_months int[] := p_months;
  v_allowed bigint[];
begin
  if v_me is null or not public.is_staff() then
    raise exception 'The Pipeline Report is for staff' using errcode = '42501';
  end if;
  if v_months is null or cardinality(v_months) = 0 then
    v_months := array(select ((extract(month from v_today)::int - 1 + i) % 12) + 1 from generate_series(1, 3) i);
  end if;
  -- The projects this person may read: every one (an administrator), or those they are assigned to.
  if public.is_admin() then
    v_allowed := p_project_ids;
  else
    v_allowed := array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = v_me
                        and (p_project_ids is null or pa.project_id = any(p_project_ids)));
  end if;

  return query
  with names as (
    select x.project_id as pid, x.user_id as uid, x.month as m, x.bucket
      from public.xdate_names(v_allowed, p_company_id, p_type, p_rep_id, p_user_ids) x
     where x.month = any(v_months) and x.user_id is not null
  ), per_month as (
    select n.pid, n.uid, n.m, count(*) as c from names n group by 1, 2, 3
  ), per_row as (
    select n.pid, n.uid, count(*) as total,
           count(*) filter (where n.bucket = 'appointment') as appts,
           count(*) filter (where n.bucket = 'off') as off_list,
           count(*) filter (where n.bucket = 'viable') as viable_left
      from names n group by 1, 2
  )
  select pr.id, pr.name, t.code,
         coalesce(tz.name, ctz.name), coalesce(nullif(pr.state, ''), c.state),
         u.id, u.first_name, u.last_name,
         (select max((coalesce(a.appt_create_date, a.created_at) at time zone v_tz)::date) from public.appointments a
           where a.user_id = r.uid and coalesce(a.set_project_id, a.project_id) = r.pid and a.deleted_at is null),
         (select max(cr.call_date) from public.call_records cr where cr.user_id = r.uid and cr.project_id = r.pid),
         (select count(*) from public.call_records cr where cr.user_id = r.uid and cr.project_id = r.pid
             and cr.call_date >= (date_trunc('month', v_today)::timestamp at time zone v_tz)),
         (select jsonb_object_agg(pm.m, pm.c) from per_month pm where pm.pid = r.pid and pm.uid = r.uid),
         r.total, r.appts, r.off_list, r.viable_left,
         case when t.code = 'DBDV' then pr.lead_rate else pr.appointment_rate end, pr.confirmation_rate,
         sr.first_name, sr.last_name,
         coalesce((select jsonb_agg(jsonb_build_object('first', o.first_name, 'last', o.last_name) order by o.first_name, o.last_name)
                     from public.project_assignments pa join public.users o on o.id = pa.ae_user_id
                    where pa.project_id = r.pid and pa.ae_user_id <> r.uid and o.status = 'active' and o.deleted_at is null), '[]'::jsonb)
    from per_row r
    join public.projects pr on pr.id = r.pid
    join public.users u on u.id = r.uid
    left join public.project_types t on t.id = pr.project_type_id
    left join public.companies c on c.id = pr.company_id
    left join public.timezones tz on tz.id = pr.timezone_id
    left join public.timezones ctz on ctz.id = c.timezone_id
    left join public.users sr on sr.id = c.sales_rep_id;
end $$;
revoke execute on function public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]) from public, anon;
grant execute on function public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]) to authenticated;

/** The people the Pipeline Report's Manager filter offers: those with names on the projects the caller may read. */
create or replace function public.pipeline_managers()
returns table (id bigint, first_name text, last_name text)
language sql stable security definer set search_path = public as $$
  select distinct u.id, u.first_name, u.last_name
    from public.project_assignments pa join public.users u on u.id = pa.ae_user_id
   where public.is_staff() and u.status = 'active' and u.deleted_at is null
     and (public.is_admin() or pa.project_id in (select x.project_id from public.project_assignments x where x.ae_user_id = public.app_user_id()))
   order by u.first_name, u.last_name;
$$;
revoke execute on function public.pipeline_managers() from public, anon;
grant execute on function public.pipeline_managers() to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20261206100000_special_pay.sql
-- ==============================================================================================================

-- =============================================================================
-- Special Pay for DB dev leads (Sean, Oct 2026)
--
-- A DB dev project can set a goal: so many leads by one rep on it in a pay
-- period (5 or 10, say), and a Special Pay for each (an extra $1 a lead).
-- When a rep's leads on the project that pay period reach the goal, each of
-- them earns the Special Pay, and so does each lead after it that period; the
-- rep is told when they hit it. It is paid as pay events of its own kind, so
-- it is in every pay total, and shown as Special Pay on the pay summary and
-- the production report. A lead charged back (Lead-Invalid) takes its Special
-- Pay back with it.
--
-- What was called "special pay" until now, the pay for confirming an
-- appointment (confirmation_rate), is called Confirmation pay from here on.
--
--   projects.special_goal / special_rate   the goal and the pay, set by an administrator
--   pay_period_of(day)                     the pay period a day falls in, as the app works it out
--   award_special_pay(user, project)       pays Special Pay once the goal is hit (from pay())
--   pay_report / production_report         + Special Pay, and Confirmation pay by its own name
--   pipeline_report                        the project's own time zone; a DB dev project's Special Pay
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. The goal and the pay, on a project
-- ---------------------------------------------------------------------------

alter table public.projects add column if not exists special_goal int;
alter table public.projects add column if not exists special_rate numeric(10,2) not null default 0;
alter table public.projects drop constraint if exists projects_special_pay_check;
alter table public.projects add constraint projects_special_pay_check
  check ((special_goal is null or special_goal between 1 and 1000) and special_rate between 0 and 1000);

comment on column public.projects.special_goal is 'Special Pay: leads one rep develops on this DB dev project in a pay period to earn it (null: none)';
comment on column public.projects.special_rate is 'Special Pay: USD more for each of those leads, once the goal is hit';

-- Pay events of the new kind.
alter table public.pay_events drop constraint if exists pay_events_kind_check;
alter table public.pay_events add constraint pay_events_kind_check
  check (kind in ('lead', 'appointment', 'confirmation', 'special'));

-- Only administrators set pay: the rates, and now the Special Pay goal and amount.
create or replace function public.tg_projects_lifecycle_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user = 'authenticated' and not public.is_admin()
     and (tg_op = 'INSERT' and (new.lead_rate, new.appointment_rate, new.confirmation_rate, new.special_rate, coalesce(new.special_goal, 0))
                               is distinct from (0::numeric, 0::numeric, 0::numeric, 0::numeric, 0)
          or tg_op = 'UPDATE' and (new.lead_rate, new.appointment_rate, new.confirmation_rate, new.special_rate, new.special_goal)
                                   is distinct from (old.lead_rate, old.appointment_rate, old.confirmation_rate, old.special_rate, old.special_goal)) then
    raise exception 'Only an administrator can set pay rates' using errcode = '42501';
  end if;
  if new.appt_project_id is not null then
    if new.appt_project_id = new.id then
      raise exception 'A project cannot promote to itself' using errcode = '23514';
    end if;
    if (select t.code from public.project_types t where t.id = new.project_type_id) is distinct from 'DBDV' then
      raise exception 'Only a database-development project promotes leads to an appointment project' using errcode = '23514';
    end if;
    if not exists (select 1 from public.projects a join public.project_types t on t.id = a.project_type_id
                    where a.id = new.appt_project_id and t.code = 'APPT' and a.company_id is not distinct from new.company_id) then
      raise exception 'Leads can only be promoted to an appointment project for the same client' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

/** An administrator sets a DB dev project's Special Pay: the goal (leads a pay period) and the pay a lead; both null/0 for none. */
create or replace function public.set_project_special_pay(p_project_id bigint, p_goal int, p_rate numeric)
returns jsonb
language plpgsql security invoker set search_path = public as $$
declare
  v_type text;
  v_row  public.projects;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can set pay rates' using errcode = '42501';
  end if;
  select t.code into v_type from public.projects p left join public.project_types t on t.id = p.project_type_id where p.id = p_project_id;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  if p_goal is not null and (p_goal < 1 or p_goal > 1000) then
    raise exception 'Special Pay goal: a number of leads from 1 to 1,000' using errcode = '22023';
  end if;
  if coalesce(p_rate, 0) < 0 or coalesce(p_rate, 0) > 1000 then
    raise exception 'Special Pay must be between $0.00 and $1,000.00 a lead' using errcode = '22023';
  end if;
  if (p_goal is null) <> (coalesce(p_rate, 0) = 0) then
    raise exception 'Special Pay needs both a goal and an amount a lead (or neither)' using errcode = '22023';
  end if;
  if p_goal is not null and v_type is distinct from 'DBDV' then
    raise exception 'Special Pay is for DB dev projects' using errcode = '22023';
  end if;
  update public.projects set special_goal = p_goal, special_rate = round(coalesce(p_rate, 0), 2)
   where id = p_project_id
  returning * into v_row;
  return jsonb_build_object('id', v_row.id, 'special_goal', v_row.special_goal, 'special_rate', v_row.special_rate);
end $$;
revoke execute on function public.set_project_special_pay(bigint, int, numeric) from public, anon;
grant execute on function public.set_project_special_pay(bigint, int, numeric) to authenticated;

-- The confirmation's pay by its new name in the range check's message.
create or replace function public.set_project_rates(p_project_id bigint, p_lead numeric, p_appointment numeric, p_confirmation numeric)
returns jsonb
language plpgsql security invoker set search_path = public as $$
declare
  v_old   public.projects;
  v_row   public.projects;
  v_rates jsonb := public.pay_rules()->'rates';
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can set pay rates' using errcode = '42501';
  end if;
  select * into v_old from public.projects where id = p_project_id;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  perform public.check_pay_rate('Lead pay', coalesce(p_lead, 0), v_old.lead_rate, v_rates->'lead');
  perform public.check_pay_rate('Appointment pay', coalesce(p_appointment, 0), v_old.appointment_rate, v_rates->'appointment');
  perform public.check_pay_rate('Confirmation pay', coalesce(p_confirmation, 0), v_old.confirmation_rate, v_rates->'special');

  update public.projects
     set lead_rate = round(coalesce(p_lead, 0), 2),
         appointment_rate = round(coalesce(p_appointment, 0), 2),
         confirmation_rate = round(coalesce(p_confirmation, 0), 2)
   where id = p_project_id
  returning * into v_row;
  return jsonb_build_object('id', v_row.id, 'lead_rate', v_row.lead_rate,
                            'appointment_rate', v_row.appointment_rate, 'confirmation_rate', v_row.confirmation_rate);
end $$;
revoke execute on function public.set_project_rates(bigint, numeric, numeric, numeric) from public, anon;
grant execute on function public.set_project_rates(bigint, numeric, numeric, numeric) to authenticated;

-- ---------------------------------------------------------------------------
-- 2. The pay period a day is in
-- ---------------------------------------------------------------------------

/**
 * The pay period containing p_day (today by default), exactly as the app's
 * payPeriod() in src/lib/pay.js works it out from Settings › Pay & time:
 * weeks or two weeks counted from period_start, halves of the month, months,
 * or the business's own schedule (a day between its periods, or after the
 * last, in the latest begun; before the first, the first; none yet: two weeks).
 */
create or replace function public.pay_period_of(p_day date default null, out starts_on date, out ends_on date)
language plpgsql stable security invoker set search_path = public as $$
declare
  v_day    date := coalesce(p_day, (now() at time zone public.business_tz())::date);
  v_time   jsonb := coalesce((select s.value from public.app_settings s where s.key = 'time_tracking'), '{}'::jsonb);
  v_kind   text := coalesce(v_time->>'pay_period', 'weekly');
  v_anchor date;
  v_len    int;
  v_month  date := date_trunc('month', v_day)::date;
begin
  if v_kind = 'custom' then
    select p.starts_on, p.ends_on into starts_on, ends_on from public.pay_periods p
     where p.starts_on <= v_day order by p.starts_on desc limit 1;
    if found then return; end if;
    select p.starts_on, p.ends_on into starts_on, ends_on from public.pay_periods p order by p.starts_on limit 1;
    if found then return; end if;
    v_kind := 'biweekly';
  end if;
  if v_kind in ('weekly', 'biweekly') then
    v_len := case when v_kind = 'weekly' then 7 else 14 end;
    begin
      v_anchor := coalesce((v_time->>'period_start')::date, date '2026-10-05');
    exception when others then
      v_anchor := date '2026-10-05';
    end;
    starts_on := v_anchor + (floor((v_day - v_anchor)::numeric / v_len)::int * v_len);
    ends_on := starts_on + v_len - 1;
  elsif v_kind = 'semimonthly' then
    if extract(day from v_day) <= 15 then
      starts_on := v_month; ends_on := v_month + 14;
    else
      starts_on := v_month + 15; ends_on := (v_month + interval '1 month')::date - 1;
    end if;
  else
    starts_on := v_month; ends_on := (v_month + interval '1 month')::date - 1;
  end if;
end $$;
revoke execute on function public.pay_period_of(date) from public, anon;
grant execute on function public.pay_period_of(date) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Paying it
-- ---------------------------------------------------------------------------

insert into public.alert_rules (name, trigger, channel, recipients, enabled)
select 'Special Pay goal hit', 'special_pay', 'inapp', null, true
 where not exists (select 1 from public.alert_rules r where r.trigger = 'special_pay');

/**
 * After a lead is paid: if the rep's leads on this DB dev project this pay
 * period (less any charged back) have reached its Special Pay goal, each of
 * them that has not had it earns the Special Pay. The rep is told the first
 * time in the period (by themselves, so not through notify_users(), which
 * leaves out whoever acted). Returns how many leads were paid it.
 */
create or replace function public.award_special_pay(p_user bigint, p_project bigint)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_tz    text := public.business_tz();
  v_goal  int;
  v_rate  numeric(10,2);
  v_name  text;
  v_type  text;
  v_from  date;
  v_to    date;
  v_leads bigint[];
  v_had   int;
  v_new   int;
  v_rule  bigint;
  v_on    boolean;
begin
  select p.special_goal, p.special_rate, p.name, t.code into v_goal, v_rate, v_name, v_type
    from public.projects p left join public.project_types t on t.id = p.project_type_id
   where p.id = p_project;
  if p_user is null or v_type is distinct from 'DBDV' or coalesce(v_goal, 0) < 1 or coalesce(v_rate, 0) <= 0 then
    return 0;
  end if;
  -- One rep and project at a time, so two leads saved together never pay one lead twice.
  perform pg_advisory_xact_lock(hashtextextended(format('special_pay:%s:%s', p_user, p_project), 0));
  select pp.starts_on, pp.ends_on into v_from, v_to from public.pay_period_of((now() at time zone v_tz)::date) pp;

  -- Their leads on it this period, any charged back left out.
  select array_agg(pe.lead_id order by pe.id) into v_leads
    from public.pay_events pe
   where pe.user_id = p_user and pe.project_id = p_project and pe.kind = 'lead' and not pe.is_chargeback
     and not exists (select 1 from public.pay_events r where r.reverses_id = pe.id)
     and pe.created_at >= (v_from::timestamp at time zone v_tz)
     and pe.created_at <  ((v_to + 1)::timestamp at time zone v_tz);
  if coalesce(cardinality(v_leads), 0) < v_goal then
    return 0;
  end if;

  -- Already hit this period? (Then this is one lead more, and no second message.)
  select count(*) into v_had
    from public.pay_events b
   where b.user_id = p_user and b.project_id = p_project and b.kind = 'special' and not b.is_chargeback
     and not exists (select 1 from public.pay_events r where r.reverses_id = b.id)
     and b.created_at >= (v_from::timestamp at time zone v_tz)
     and b.created_at <  ((v_to + 1)::timestamp at time zone v_tz);

  insert into public.pay_events (user_id, project_id, lead_id, kind, amount, note, created_by)
  select p_user, p_project, l.id, 'special', v_rate,
         format('Special Pay: %s leads on this project in the pay period %s – %s', v_goal, to_char(v_from, 'FMMM/FMDD'), to_char(v_to, 'FMMM/FMDD')),
         public.app_user_id()
    from unnest(v_leads) as l(id)
   where l.id is not null
     and not exists (select 1 from public.pay_events b
                      where b.kind = 'special' and b.lead_id = l.id and b.user_id = p_user and not b.is_chargeback
                        and not exists (select 1 from public.pay_events r where r.reverses_id = b.id));
  get diagnostics v_new = row_count;

  if v_new > 0 and v_had = 0 then
    select r.id, r.enabled into v_rule, v_on from public.alert_rules r where r.trigger = 'special_pay' order by r.id limit 1;
    if v_rule is null or v_on then
      insert into public.notifications (user_id, kind, title, body, link)
      select u.id, 'lead',
             left(format('Special Pay: you hit %s leads on %s', v_goal, v_name), 160),
             left(format('That is %s more for each of your %s leads there this pay period (%s so far), and for each lead after it until %s. It is on your pay summary as Special Pay.',
                         to_char(v_rate, 'FM$999,990.00'), cardinality(v_leads), to_char(v_rate * v_new, 'FM$999,990.00'), to_char(v_to, 'FMMM/FMDD')), 1000),
             '/reports/pay'
        from public.users u where u.id = p_user and u.status = 'active';
      if found and v_rule is not null then
        insert into public.alert_log (rule_id, subject, detail, status)
        values (v_rule, left(format('Special Pay: %s leads on %s', v_goal, v_name), 200), 'In-app to 1 person', 'sent');
      end if;
    end if;
  end if;
  return v_new;
end $$;
revoke execute on function public.award_special_pay(bigint, bigint) from public, anon, authenticated;

-- pay(): as before, then Special Pay once a lead is paid.
create or replace function public.pay(p_user bigint, p_project bigint, p_kind text, p_lead bigint,
                                      p_appointment bigint, p_call bigint, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_amount numeric(10,2);
  v_id bigint;
begin
  -- A lead is developed once: no second payment for it unless the first was
  -- charged back (a lead moved back to its DBDev project and promoted again).
  if p_kind = 'lead' and exists (
       select 1 from public.pay_events pe
        where pe.lead_id = p_lead and pe.kind = 'lead' and not pe.is_chargeback
          and not exists (select 1 from public.pay_events r where r.reverses_id = pe.id)) then
    return '[]'::jsonb;
  end if;
  select case p_kind when 'lead' then lead_rate when 'appointment' then appointment_rate else confirmation_rate end
    into v_amount from public.projects where id = p_project;
  insert into public.pay_events (user_id, project_id, lead_id, appointment_id, call_record_id, kind, amount, note, created_by)
  values (p_user, p_project, p_lead, p_appointment, p_call, p_kind, coalesce(v_amount, 0), p_note, public.app_user_id())
  returning id into v_id;
  if p_kind = 'lead' then
    perform public.award_special_pay(p_user, p_project);
  end if;
  return jsonb_build_object('id', v_id, 'user_id', p_user, 'kind', p_kind, 'amount', coalesce(v_amount, 0));
end $$;
revoke execute on function public.pay(bigint, bigint, text, bigint, bigint, bigint, text) from public, anon, authenticated;

-- charge_back(): as before; a lead's chargeback takes its Special Pay back too.
create or replace function public.charge_back(p_lead bigint, p_appointment bigint, p_kinds text[], p_call bigint, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e record;
  v_out jsonb := '[]'::jsonb;
  v_id bigint;
  v_kinds text[] := case when 'lead' = any(p_kinds) then p_kinds || array['special'] else p_kinds end;
begin
  for e in
    select pe.* from public.pay_events pe
     where pe.kind = any(v_kinds)
       and pe.reverses_id is null
       and (p_lead is null or pe.lead_id = p_lead)
       and (p_appointment is null or pe.appointment_id = p_appointment)
       and not exists (select 1 from public.pay_events x where x.reverses_id = pe.id)
     order by pe.id
     for update
  loop
    insert into public.pay_events (user_id, project_id, lead_id, appointment_id, call_record_id, kind, amount, reverses_id, note, created_by)
    values (e.user_id, e.project_id, e.lead_id, e.appointment_id, p_call, e.kind, -e.amount, e.id, p_note, public.app_user_id())
    returning id into v_id;
    v_out := v_out || jsonb_build_object('id', v_id, 'user_id', e.user_id, 'kind', e.kind, 'amount', -e.amount, 'reverses', e.id);
  end loop;
  return v_out;
end $$;
revoke execute on function public.charge_back(bigint, bigint, text[], bigint, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. The reports: Special Pay of its own, Confirmation pay by its name
-- ---------------------------------------------------------------------------

drop function if exists public.pay_report(date, date, bigint);

/**
 * As before, with each person's Special Pay, any charged back taken off
 * (specials: the leads it is paid on; special_goal_pay: what it comes to),
 * which is in their commission.
 */
create function public.pay_report(p_from date, p_to date, p_user bigint default null)
returns table (
  user_id bigint, first_name text, last_name text, email text, role text,
  pay_model text, hourly_rate numeric,
  worked_minutes int, paid_minutes int,
  hourly_pay numeric, commission numeric, pay numeric,
  calls bigint, leads bigint, appointments bigint, confirmations bigint, chargebacks bigint,
  specials bigint, special_goal_pay numeric
)
language plpgsql stable security invoker set search_path = public as $$
#variable_conflict use_column
declare
  v_tz   text   := public.business_tz();
  v_user bigint := case when public.is_admin() then p_user else public.app_user_id() end;
begin
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'Choose a start date on or before the end date' using errcode = '22023';
  end if;
  if p_to - p_from > 366 then
    raise exception 'Choose a range of a year or less' using errcode = '22023';
  end if;
  if v_user is null and not public.is_admin() then
    return;
  end if;

  return query
  with t as (
    select wd.user_id as uid, sum(wd.worked)::int as worked, sum(wd.paid)::int as paid
      from public.work_days(p_from, p_to, v_user) wd
     group by 1
  ), m as (
    select pe.user_id as uid,
           sum(pe.amount) as commission,
           count(*) filter (where pe.kind = 'lead'         and not pe.is_chargeback) as leads,
           count(*) filter (where pe.kind = 'appointment'  and not pe.is_chargeback) as appts,
           count(*) filter (where pe.kind = 'confirmation' and not pe.is_chargeback) as confirms,
           count(*) filter (where pe.is_chargeback) as backs,
           -- Special Pay net of any charged back: the leads it is still paid on, and what it comes to.
           count(*) filter (where pe.kind = 'special' and not pe.is_chargeback) - count(*) filter (where pe.kind = 'special' and pe.is_chargeback) as specials,
           sum(pe.amount) filter (where pe.kind = 'special') as special_amt
      from public.pay_events pe
     where pe.created_at >= (p_from::timestamp at time zone v_tz)
       and pe.created_at <  ((p_to + 1)::timestamp at time zone v_tz)
       and pe.user_id is not null
       and (v_user is null or pe.user_id = v_user)
     group by 1
  ), c as (
    select cr.user_id as uid, count(*) as n
      from public.call_records cr
     where cr.call_date >= (p_from::timestamp at time zone v_tz)
       and cr.call_date <  ((p_to + 1)::timestamp at time zone v_tz)
       and cr.user_id is not null
       and (v_user is null or cr.user_id = v_user)
     group by 1
  ), people as (
    select u.id
      from public.users u
     where (v_user is null or u.id = v_user)
       and ((u.role in ('manager', 'agent') and u.status = 'active')
            or u.id in (select t.uid from t) or u.id in (select m.uid from m) or u.id in (select c.uid from c))
  ), figures as (
    select u.id, u.first_name, u.last_name, u.email, u.role,
           coalesce(pp.pay_model, 'commission') as model, pp.hourly_rate as rate,
           coalesce(t.worked, 0) as worked, coalesce(t.paid, 0) as paid,
           round(coalesce(t.paid, 0) / 60.0 * coalesce(pp.hourly_rate, 0), 2) as hourly,
           round(coalesce(m.commission, 0), 2) as commission,
           coalesce(c.n, 0) as calls, coalesce(m.leads, 0) as leads, coalesce(m.appts, 0) as appts,
           coalesce(m.confirms, 0) as confirms, coalesce(m.backs, 0) as backs,
           coalesce(m.specials, 0) as specials, round(coalesce(m.special_amt, 0), 2) as special_amt
      from people pl
      join public.users u on u.id = pl.id
      left join public.pay_profiles pp on pp.user_id = u.id
      left join t on t.uid = u.id
      left join m on m.uid = u.id
      left join c on c.uid = u.id
  )
  select f.id, f.first_name, f.last_name, f.email, f.role, f.model, f.rate::numeric,
         f.worked, f.paid, f.hourly, f.commission,
         case when f.model = 'hybrid' then greatest(f.hourly, f.commission) else f.commission end,
         f.calls, f.leads, f.appts, f.confirms, f.backs, f.specials, f.special_amt
    from figures f
   order by f.first_name, f.last_name, f.id;
end $$;
revoke execute on function public.pay_report(date, date, bigint) from public, anon;
grant execute on function public.pay_report(date, date, bigint) to authenticated;

drop function if exists public.production_report(date, date, bigint, bigint);

/**
 * Per day (in the business's time zone), rep and project: calls made, the
 * paid events, and what they came to by kind (lead pay, appointment pay,
 * confirmation pay, Special Pay, chargebacks) and in total. Anyone but an
 * administrator sees only their own rows, whatever p_user_id says.
 * special_pay is confirmation_pay's old name, kept while the app deployed
 * before this still reads it; a later migration drops it.
 */
create function public.production_report(p_from date, p_to date,
                                         p_project_id bigint default null, p_user_id bigint default null)
returns table (
  day date, user_id bigint, first_name text, last_name text, email text,
  project_id bigint, project text, client_id bigint, client text,
  calls bigint, leads bigint, appointments bigint, confirmations bigint, chargebacks bigint,
  lead_pay numeric, appointment_pay numeric, special_pay numeric, chargeback_amount numeric,
  amount numeric, confirmation_pay numeric, specials bigint, special_goal_pay numeric
)
language plpgsql stable security invoker set search_path = public as $$
declare
  v_tz   text   := public.business_tz();
  v_user bigint := case when public.is_admin() then p_user_id else public.app_user_id() end;
begin
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'Choose a start date on or before the end date' using errcode = '22023';
  end if;
  if p_to - p_from > 366 then
    raise exception 'Choose a range of a year or less' using errcode = '22023';
  end if;

  return query
  with c as (
    select (cr.call_date at time zone v_tz)::date as d, cr.user_id as uid, cr.project_id as pid, count(*) as n
      from public.call_records cr
     where cr.call_date >= (p_from::timestamp at time zone v_tz)
       and cr.call_date <  ((p_to + 1)::timestamp at time zone v_tz)
       and cr.user_id is not null
       and (v_user is null or cr.user_id = v_user)
       and (p_project_id is null or cr.project_id = p_project_id)
     group by 1, 2, 3
  ),
  e as (
    select (pe.created_at at time zone v_tz)::date as d, pe.user_id as uid, pe.project_id as pid,
           count(*) filter (where pe.kind = 'lead'         and not pe.is_chargeback) as leads,
           count(*) filter (where pe.kind = 'appointment'  and not pe.is_chargeback) as appts,
           count(*) filter (where pe.kind = 'confirmation' and not pe.is_chargeback) as confirms,
           count(*) filter (where pe.is_chargeback) as backs,
           count(*) filter (where pe.kind = 'special'      and not pe.is_chargeback) as specials,
           sum(pe.amount) filter (where pe.kind = 'lead'         and not pe.is_chargeback) as lead_amt,
           sum(pe.amount) filter (where pe.kind = 'appointment'  and not pe.is_chargeback) as appt_amt,
           sum(pe.amount) filter (where pe.kind = 'confirmation' and not pe.is_chargeback) as confirm_amt,
           sum(pe.amount) filter (where pe.kind = 'special'      and not pe.is_chargeback) as special_amt,
           sum(pe.amount) filter (where pe.is_chargeback) as back_amt,
           sum(pe.amount) as amount
      from public.pay_events pe
     where pe.created_at >= (p_from::timestamp at time zone v_tz)
       and pe.created_at <  ((p_to + 1)::timestamp at time zone v_tz)
       and pe.user_id is not null
       and (v_user is null or pe.user_id = v_user)
       and (p_project_id is null or pe.project_id = p_project_id)
     group by 1, 2, 3
  ),
  k as (select c.d, c.uid, c.pid from c union select e.d, e.uid, e.pid from e)
  select k.d, k.uid, u.first_name, u.last_name, u.email, k.pid, p.name, co.id, co.name,
         coalesce(c.n, 0), coalesce(e.leads, 0), coalesce(e.appts, 0), coalesce(e.confirms, 0), coalesce(e.backs, 0),
         coalesce(e.lead_amt, 0)::numeric, coalesce(e.appt_amt, 0)::numeric, coalesce(e.confirm_amt, 0)::numeric,
         coalesce(e.back_amt, 0)::numeric, coalesce(e.amount, 0)::numeric,
         coalesce(e.confirm_amt, 0)::numeric, coalesce(e.specials, 0), coalesce(e.special_amt, 0)::numeric
    from k
    left join c on c.d = k.d and c.uid = k.uid and c.pid is not distinct from k.pid
    left join e on e.d = k.d and e.uid = k.uid and e.pid is not distinct from k.pid
    left join public.users u on u.id = k.uid
    left join public.projects p on p.id = k.pid
    left join public.companies co on co.id = p.company_id
   order by k.d desc, u.first_name, u.last_name, p.name;
end $$;
revoke execute on function public.production_report(date, date, bigint, bigint) from public, anon;
grant execute on function public.production_report(date, date, bigint, bigint) to authenticated;

-- ---------------------------------------------------------------------------
-- 5. The Pipeline Report: the project's own time zone; a DB dev project's Special Pay
-- ---------------------------------------------------------------------------

drop function if exists public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]);

/**
 * As before, except: the time zone is the project's own (none set: none), and
 * special_pay is a DB dev project's Special Pay a lead (special_goal: the
 * leads a pay period it takes), an appointment project's its confirmation pay.
 */
create function public.pipeline_report(p_months int[] default null, p_project_ids bigint[] default null,
  p_company_id bigint default null, p_type text default null, p_rep_id bigint default null, p_user_ids bigint[] default null)
returns table (project_id bigint, project text, project_type text, time_zone text, state text,
  manager_id bigint, manager_first text, manager_last text, last_appt_set date, last_worked timestamptz, calls bigint,
  months jsonb, total bigint, appts bigint, off_list bigint, viable_left bigint,
  pay numeric, special_pay numeric, sales_rep_first text, sales_rep_last text, shared_with jsonb, special_goal int)
language plpgsql stable security definer set search_path = public as $$
declare
  v_me     bigint := public.app_user_id();
  v_tz     text := public.business_tz();
  v_today  date := (now() at time zone public.business_tz())::date;
  v_months int[] := p_months;
  v_allowed bigint[];
begin
  if v_me is null or not public.is_staff() then
    raise exception 'The Pipeline Report is for staff' using errcode = '42501';
  end if;
  if v_months is null or cardinality(v_months) = 0 then
    v_months := array(select ((extract(month from v_today)::int - 1 + i) % 12) + 1 from generate_series(1, 3) i);
  end if;
  -- The projects this person may read: every one (an administrator), or those they are assigned to.
  if public.is_admin() then
    v_allowed := p_project_ids;
  else
    v_allowed := array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = v_me
                        and (p_project_ids is null or pa.project_id = any(p_project_ids)));
  end if;

  return query
  with names as (
    select x.project_id as pid, x.user_id as uid, x.month as m, x.bucket
      from public.xdate_names(v_allowed, p_company_id, p_type, p_rep_id, p_user_ids) x
     where x.month = any(v_months) and x.user_id is not null
  ), per_month as (
    select n.pid, n.uid, n.m, count(*) as c from names n group by 1, 2, 3
  ), per_row as (
    select n.pid, n.uid, count(*) as total,
           count(*) filter (where n.bucket = 'appointment') as appts,
           count(*) filter (where n.bucket = 'off') as off_list,
           count(*) filter (where n.bucket = 'viable') as viable_left
      from names n group by 1, 2
  )
  select pr.id, pr.name, t.code,
         tz.name, coalesce(nullif(pr.state, ''), c.state),
         u.id, u.first_name, u.last_name,
         (select max((coalesce(a.appt_create_date, a.created_at) at time zone v_tz)::date) from public.appointments a
           where a.user_id = r.uid and coalesce(a.set_project_id, a.project_id) = r.pid and a.deleted_at is null),
         (select max(cr.call_date) from public.call_records cr where cr.user_id = r.uid and cr.project_id = r.pid),
         (select count(*) from public.call_records cr where cr.user_id = r.uid and cr.project_id = r.pid
             and cr.call_date >= (date_trunc('month', v_today)::timestamp at time zone v_tz)),
         (select jsonb_object_agg(pm.m, pm.c) from per_month pm where pm.pid = r.pid and pm.uid = r.uid),
         r.total, r.appts, r.off_list, r.viable_left,
         case when t.code = 'DBDV' then pr.lead_rate else pr.appointment_rate end,
         case when t.code = 'DBDV' then pr.special_rate else pr.confirmation_rate end,
         sr.first_name, sr.last_name,
         coalesce((select jsonb_agg(jsonb_build_object('first', o.first_name, 'last', o.last_name) order by o.first_name, o.last_name)
                     from public.project_assignments pa join public.users o on o.id = pa.ae_user_id
                    where pa.project_id = r.pid and pa.ae_user_id <> r.uid and o.status = 'active' and o.deleted_at is null), '[]'::jsonb),
         case when t.code = 'DBDV' then pr.special_goal end
    from per_row r
    join public.projects pr on pr.id = r.pid
    join public.users u on u.id = r.uid
    left join public.project_types t on t.id = pr.project_type_id
    left join public.companies c on c.id = pr.company_id
    left join public.timezones tz on tz.id = pr.timezone_id
    left join public.users sr on sr.id = c.sales_rep_id;
end $$;
revoke execute on function public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]) from public, anon;
grant execute on function public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]) to authenticated;

-- ==============================================================================================================
-- 20261207100000_calendar_note_range.sql
-- ==============================================================================================================

-- =============================================================================
-- A calendar note over a stretch of time (Oct 2026): dragging across the hours
-- of the calendar's day or week opens a note for that time, from and until.
-- until_time is optional: a note on a single time (as before) has none.
-- =============================================================================

alter table public.calendar_notes add column if not exists until_time time;
alter table public.calendar_notes drop constraint if exists calendar_notes_until_after;
alter table public.calendar_notes add constraint calendar_notes_until_after check (until_time is null or until_time > at_time);
comment on column public.calendar_notes.until_time is 'Where the note''s time ends (null: a note on its one time, at_time)';

-- ==============================================================================================================
-- 20261208100000_list_builder.sql
-- ==============================================================================================================

-- =============================================================================
-- List Builder (Sean, Oct 2026): the businesses a client (or a prospect) wants
-- to target, picked as our list vendor's software has them: industries from
-- the SIC tree (a sector such as 15-17 Construction, its 2-digit groups, each
-- group's 4-digit codes, and 6-digit codes under those when loaded), the
-- employee size for each 2-digit group (from and to), and the territory
-- (states, counties, cities, ZIP codes, a radius around a ZIP), each with
-- what to leave out. A request is kept with its client (or, from a prospect,
-- with who they are), so what a client has targeted before shows next time;
-- it exports with the codes one to a line, to paste into the vendor's site.
--
-- A prospect fills one in from a link we send (no sign-in): the link carries
-- the Sales Rep it came from. A request in tells the client's (or the link's)
-- Sales Rep and the administrators.
--
--   list_sic             the tree: sectors, groups, codes (from sic_codes; an administrator can load a sheet)
--   list_requests        each request: who for, its criteria, notes, where it stands
--   list_request_links   links for prospects, each with its Sales Rep; can be turned off
--   submit_list_request  a prospect's request, through a link
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 1. The SIC tree
-- ---------------------------------------------------------------------------

create table if not exists public.list_sic (
  code    text primary key,                     -- "15-17", "15", "1521", "152101"
  name    text not null,
  kind    text not null check (kind in ('sector', 'group', 'industry', 'detail')),
  parent  text references public.list_sic(code) on delete cascade,
  sort    int not null default 0
);
create index if not exists list_sic_parent on public.list_sic (parent, sort);
alter table public.list_sic enable row level security;
drop policy if exists list_sic_read on public.list_sic;
create policy list_sic_read on public.list_sic for select using (true);
drop policy if exists list_sic_write on public.list_sic;
create policy list_sic_write on public.list_sic for all to authenticated using (public.is_admin()) with check (public.is_admin());
-- The prospect's page reads the tree before anyone signs in: it is the public SIC list.
grant select on public.list_sic to anon, authenticated;
grant insert, update, delete on public.list_sic to authenticated;

