  ('9229', 'Public Order & Safety NEC', 'industry', '92', 1021, 'Public Administration'),
  ('93', 'Public Finance & Taxation Policy', 'group', '91-95', 1022, null),
  ('9311', 'Public Finance & Taxation Policy', 'industry', '93', 1023, 'Public Administration'),
  ('94', 'Administration-Human Resource Programs', 'group', '91-95', 1024, null),
  ('9411', 'Administration of Educational Programs', 'industry', '94', 1025, 'Public Administration'),
  ('9431', 'Administration-Public Health Programs', 'industry', '94', 1026, 'Public Administration'),
  ('9441', 'Admin-Social & Human Resource Programs', 'industry', '94', 1027, 'Public Administration'),
  ('9451', 'Administration of Veteras Affairs', 'industry', '94', 1028, 'Public Administration'),
  ('95', 'Admin-Environmental Quality Programs', 'group', '91-95', 1029, null),
  ('9511', 'Air Water & Solid Waste Management', 'industry', '95', 1030, 'Public Administration'),
  ('9512', 'Land Mineral & Wildlife Conservation', 'industry', '95', 1031, 'Public Administration'),
  ('9531', 'Administration of Housing Programs', 'industry', '95', 1032, 'Public Administration'),
  ('9532', 'Administration of Urban Planning', 'industry', '95', 1033, 'Public Administration');

-- Parents first, so each one is there for what sits under it.
insert into public.list_sic (code, name, kind, parent, sort, class)
select s.code, s.name, s.kind, null, s.sort, s.class from sheet s
on conflict (code) do update set name = excluded.name, kind = excluded.kind, sort = excluded.sort, class = excluded.class;
update public.list_sic l set parent = s.parent from sheet s where s.code = l.code and l.parent is distinct from s.parent;
delete from public.list_sic l where not exists (select 1 from sheet s where s.code = l.code);
drop table if exists pg_temp.sheet;

-- ==============================================================================================================
-- 20261210100000_sic_leading_zeros.sql
-- ==============================================================================================================

-- SIC codes keep their leading zero (Sean, Oct 2026): the agricultural codes
-- (01-09) lost it in a spreadsheet, so the master list held "111" where a
-- lead (and the vendor) has "0111", and the lead page found no description;
-- "11101" read as 1110's. A code with an odd number of digits has lost its
-- zero: "1" is 01, "111" is 0111, "11101" is 011101, "111-01" is 0111-01.
--
--   1. sic_pad(code): the code with its zero back.
--   2. The codes on file put right: the master list (a padded code taking the
--      description when it has none), the leads and the clients; the unpadded
--      ones then go. Triggers are off while it runs, so no lead reads as
--      updated and nobody is told of anything.
--   3. From now on, whatever writes a code (an import, a form, SQL) has its
--      zero put back as it is saved.
--
-- Safe to run more than once. Run it in the SQL Editor before the code that
-- goes with it is pushed (the code works with either).

create or replace function public.sic_pad(c text) returns text
language sql immutable parallel safe set search_path = '' as $$
  select case
    when c ~ '^(\d|\d{3}|\d{5}|\d{7})$' then '0' || c
    when c ~ '^\d{3}-\d{2}$' then '0' || c
    else c
  end
$$;

begin;
set local session_replication_role = replica;

insert into public.sic_codes (code, description)
select public.sic_pad(code), description from public.sic_codes where public.sic_pad(code) <> code
on conflict (code) do update set description = coalesce(public.sic_codes.description, excluded.description);

update public.leads set sic_code = public.sic_pad(sic_code) where sic_code is not null and public.sic_pad(sic_code) <> sic_code;
update public.companies set sic_code = public.sic_pad(sic_code) where sic_code is not null and public.sic_pad(sic_code) <> sic_code;

delete from public.sic_codes where public.sic_pad(code) <> code;
commit;

create or replace function public.tg_sic_pad() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_table_name = 'sic_codes' then
    new.code := public.sic_pad(new.code);
  else
    new.sic_code := public.sic_pad(new.sic_code);
  end if;
  return new;
end
$$;

drop trigger if exists sic_pad on public.sic_codes;
create trigger sic_pad before insert or update of code on public.sic_codes
  for each row execute function public.tg_sic_pad();
drop trigger if exists sic_pad on public.leads;
create trigger sic_pad before insert or update of sic_code on public.leads
  for each row execute function public.tg_sic_pad();
drop trigger if exists sic_pad on public.companies;
create trigger sic_pad before insert or update of sic_code on public.companies
  for each row execute function public.tg_sic_pad();

-- ==============================================================================================================
-- 20261211100000_share_names_by_month.sql
-- ==============================================================================================================

-- Share names evenly, month by month (Sean, Oct 2026): two reps on a
-- project held 631 names each, but one had 57 of its December renewals and
-- the other 1. Sharing out took the least-called names from whoever held
-- most, and the names being called now are the ones renewing soonest, so
-- each month's renewals stayed with whoever had been working them.
--
-- Now each renewal month (the name's renewal date: the Ultimate X-Date, else
-- its first line's; names with none as one more group) is shared out on its
-- own: everyone gets an even share of every month, and the totals still come
-- out even (a month's odd names go to whoever has fewest so far). Within a
-- month, whoever holds most keeps the larger share and gives up the names
-- they have called least, so the fewest names move.
--
-- Safe to run more than once. Nothing else changes; the next "Share names
-- evenly" (or a rep added or taken off) shares the names out this way.

CREATE OR REPLACE FUNCTION public.distribute_names(p_project_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reps   bigint[];
  v_k      int;
  v_total  int;
  v_before jsonb;
  v_moved  int := 0;
  v_n      int;
  b        record;
  rep      record;
begin
  perform 1 from public.projects where id = p_project_id for update;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;

  select coalesce(array_agg(pa.ae_user_id order by pa.ae_user_id), '{}')
    into v_reps
    from public.project_assignments pa
    join public.users u on u.id = pa.ae_user_id and u.status = 'active'
   where pa.project_id = p_project_id;
  v_k := coalesce(array_length(v_reps, 1), 0);

  -- Names held by anyone no longer on the project go back in the pool.
  update public.leads l set assigned_user_id = null
    from public.call_results r
   where r.id = l.result_id and r.viable and r.callable
     and l.project_id = p_project_id and l.deleted_at is null
     and l.assigned_user_id is not null
     and not (l.assigned_user_id = any(v_reps));

  select coalesce(jsonb_object_agg(uid, n), '{}') into v_before
    from (select l.assigned_user_id as uid, count(*) as n
            from public.leads l join public.call_results r on r.id = l.result_id
           where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable and l.assigned_user_id is not null
           group by 1) c;

  if v_k = 0 then
    return jsonb_build_object('project_id', p_project_id, 'reps', 0, 'moved', 0,
                              'message', 'Nobody is assigned to this project yet');
  end if;

  -- The names to share, each with its renewal month (0: none).
  drop table if exists pg_temp.share_names;
  create temp table share_names as
    select l.id, l.assigned_user_id as uid, l.call_weight, l.date_last_worked,
           coalesce(extract(month from coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate,
             i.dental_xdate, i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate)))::int, 0) as mon
      from public.leads l
      join public.call_results r on r.id = l.result_id
      -- One coverage row a name (its latest), so no name is counted twice.
      left join lateral (select * from public.insurance_details x where x.lead_id = l.id order by x.id desc limit 1) i on true
     where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable;
  select count(*) into v_total from share_names;

  -- Each rep's share of each month, and of all the names so far.
  drop table if exists pg_temp.share_targets;
  create temp table share_targets (uid bigint, mon int, target int, primary key (uid, mon));
  drop table if exists pg_temp.share_running;
  create temp table share_running as select u.uid, 0 as total from unnest(v_reps) as u(uid);

  for b in select mon, count(*)::int as n from share_names group by mon order by mon loop
    -- An even share each; the month's odd names to whoever has fewest so far
    -- (then whoever holds most of this month already, so fewer move).
    insert into share_targets (uid, mon, target)
    select s.uid, b.mon, b.n / v_k + case when s.rank_no <= b.n % v_k then 1 else 0 end
      from (select sr.uid, row_number() over (order by sr.total, coalesce(h.n, 0) desc, sr.uid) as rank_no
              from share_running sr
              left join (select uid, count(*) as n from share_names where mon = b.mon group by uid) h on h.uid = sr.uid) s;
    update share_running sr set total = sr.total + t.target
      from share_targets t where t.uid = sr.uid and t.mon = b.mon;
  end loop;

  -- Over a month's share: the names called least go back in the pool.
  for rep in
    select t.uid, t.mon, t.target, count(s.id)::int as held
      from share_targets t join share_names s on s.uid = t.uid and s.mon = t.mon
     group by t.uid, t.mon, t.target
    having count(s.id) > t.target
  loop
    with gone as (
      select id from share_names
       where uid = rep.uid and mon = rep.mon
       order by call_weight, date_last_worked nulls first, id desc
       limit rep.held - rep.target)
    update share_names s set uid = null from gone where s.id = gone.id;
    get diagnostics v_n = row_count;
    v_moved := v_moved + v_n;
  end loop;

  -- Under a month's share: names from that month's pool.
  for rep in
    select t.uid, t.mon, t.target, (select count(*)::int from share_names s where s.uid = t.uid and s.mon = t.mon) as held
      from share_targets t
  loop
    if rep.held < rep.target then
      with given as (
        select id from share_names where uid is null and mon = rep.mon order by id limit rep.target - rep.held)
      update share_names s set uid = rep.uid from given where s.id = given.id;
    end if;
  end loop;

  update public.leads l set assigned_user_id = s.uid
    from share_names s
   where s.id = l.id and l.assigned_user_id is distinct from s.uid;

  drop table if exists pg_temp.share_names;
  drop table if exists pg_temp.share_targets;
  drop table if exists pg_temp.share_running;

  return jsonb_build_object(
    'project_id', p_project_id,
    'names', v_total,
    'reps', v_k,
    'moved', v_moved,
    'before', v_before,
    'after', (select coalesce(jsonb_object_agg(uid, n), '{}')
                from (select l.assigned_user_id as uid, count(*) as n
                        from public.leads l join public.call_results r on r.id = l.result_id
                       where l.project_id = p_project_id and l.deleted_at is null and r.viable and r.callable and l.assigned_user_id is not null
                       group by 1) c));
end $function$;
revoke execute on function public.distribute_names(bigint) from public, anon, authenticated;

-- ==============================================================================================================
-- 20261212100000_transfer_names.sql
-- ==============================================================================================================

-- Giving a lead to another client, and moving names between projects
-- (Sean, Oct 2026). Before, a lead a client couldn't use was typed over a
-- spare record on another client's list, and names were moved by exporting
-- them and importing them again.
--
--   transfer_lead(lead, project, into)  one lead to another client's Appt
--     project: a copy of it there as Lead-No Contact (or, `into`, a record of
--     the same business already on that list, put back on it), the client
--     notes of the original in its internal notes; the original marked
--     Lead-Removed (Removed for a DB dev name). No pay: a transferred lead is
--     not a new lead.
--   move_names(ids, project, result)    many names to another project of the
--     same kind: copies there with the result chosen, shared out evenly among
--     its reps; the originals marked Removed / Lead-Removed, so the first
--     client's reports stay as they were. A name whose phone is already on
--     that project is left where it is (counted).
--
-- Administrators and account managers. Safe to run more than once.

/** Ten digits of a phone, to tell the same business by: "(480) 555-0142" and "480.555.0142" are one. */
create or replace function public.phone_key(p text) returns text
language sql immutable parallel safe set search_path = '' as $$
  select nullif(right(regexp_replace(coalesce(p, ''), '\D', '', 'g'), 10), '')
$$;

/** A copy of a name on another project: its details, coverage and notes. The new record's id. */
create or replace function public.copy_name(p_lead bigint, p_project bigint, p_result bigint, p_rep bigint, p_note text)
returns bigint
language plpgsql security definer set search_path = public as $$
declare
  v_id   bigint;
  v_type text := public.project_type_code(p_project);
begin
  insert into public.leads (
    project_id, result_id, assigned_user_id, status_id, call_weight, promoted_at,
    agency_id, dbdv_user_id, company_name, contact_name, contact_title, decision_maker, phone, email, website, address, city,
    state, zip, county, territory, sic_code, description, list_source, producer_name, broker, employees, covered_employees,
    autos, sales_volume, years_in_business, estimated_annual_premium, reason_to_change, dec_sheet_received, location,
    lead_date, import_date, shopping_date, fax, dm_title, professionals, source_project_id, original_xdate, contact_mobile,
    dm_phone, dm_mobile, dm_email, contact2_name, contact2_title, contact2_phone, contact2_mobile, contact2_email, ein,
    location_ownership, building_age, building_stories, building_acres, employees_full_time, employees_part_time,
    subcontractors_pct, auto_types, travel_radius, annual_payroll, dot_number, cargo, claims_3yrs, drivers, xmod)
  select
    p_project, p_result, p_rep,
    coalesce((select s.id from public.lead_statuses s join public.call_results r on r.status_code = s.code where r.id = p_result), l.status_id),
    0, case when v_type = 'APPT' then now() end,
    agency_id, dbdv_user_id, company_name, contact_name, contact_title, decision_maker, phone, email, website, address, city,
    state, zip, county, territory, sic_code, description, list_source, producer_name, broker, employees, covered_employees,
    autos, sales_volume, years_in_business, estimated_annual_premium, reason_to_change, dec_sheet_received, location,
    lead_date, import_date, shopping_date, fax, dm_title, professionals, source_project_id, original_xdate, contact_mobile,
    dm_phone, dm_mobile, dm_email, contact2_name, contact2_title, contact2_phone, contact2_mobile, contact2_email, ein,
    location_ownership, building_age, building_stories, building_acres, employees_full_time, employees_part_time,
    subcontractors_pct, auto_types, travel_radius, annual_payroll, dot_number, cargo, claims_3yrs, drivers, xmod
    from public.leads l where l.id = p_lead
  returning id into v_id;

  -- Its coverage and X-dates (the latest sheet of them).
  insert into public.insurance_details (
    lead_id, agency_name, ultimate_xdate, pkg_xdate, pkg_carrier, wc_xdate, wc_carrier, auto_xdate, auto_carrier, health_xdate,
    health_carrier, dental_xdate, dental_provider, vision_xdate, vision_provider, prof_liab_xdate, prof_liab_carrier, do_xdate,
    do_carrier, eo_xdate, eo_carrier, homeowner_xdate, homeowner_carrier, personal_auto_xdate, personal_auto_carrier,
    inception_401k, participants_401k, covered_employees, autos, personal_lines_xdate, personal_lines_carrier, agency_years)
  select v_id, agency_name, ultimate_xdate, pkg_xdate, pkg_carrier, wc_xdate, wc_carrier, auto_xdate, auto_carrier, health_xdate,
    health_carrier, dental_xdate, dental_provider, vision_xdate, vision_provider, prof_liab_xdate, prof_liab_carrier, do_xdate,
    do_carrier, eo_xdate, eo_carrier, homeowner_xdate, homeowner_carrier, personal_auto_xdate, personal_auto_carrier,
    inception_401k, participants_401k, covered_employees, autos, personal_lines_xdate, personal_lines_carrier, agency_years
    from public.insurance_details where lead_id = p_lead order by id desc limit 1;

  -- Its internal notes: where it came from, the original's own, and the client notes it had (to write
  -- the new client's afresh, in the client notes box).
  insert into public.lead_notes (lead_id, notes)
  select v_id, concat_ws(E'\n\n', p_note, nullif(btrim(n.notes), ''),
                         case when nullif(btrim(l.client_note), '') is not null then 'Client notes from that record:' || E'\n' || btrim(l.client_note) end)
    from public.leads l left join public.lead_notes n on n.lead_id = l.id
   where l.id = p_lead;
  return v_id;
end $$;
revoke execute on function public.copy_name(bigint, bigint, bigint, bigint, text) from public, anon, authenticated;

/** A line added to a name's internal notes. */
create or replace function public.add_name_note(p_lead bigint, p_line text)
returns void
language sql security definer set search_path = public as $$
  insert into public.lead_notes (lead_id, notes) values (p_lead, p_line)
  on conflict (lead_id) do update
    set notes = case when nullif(btrim(public.lead_notes.notes), '') is null then excluded.notes
                     else rtrim(public.lead_notes.notes) || E'\n' || excluded.notes end;
$$;
revoke execute on function public.add_name_note(bigint, text) from public, anon, authenticated;

/** The note stamp the note boxes write ("10/27/26 seanf:"). */
create or replace function public.note_stamp() returns text
language sql stable set search_path = public as $$
  select to_char((now() at time zone public.business_tz())::date, 'FMMM/FMDD/YY') || ' ' ||
         lower(regexp_replace(coalesce(nullif(u.username, ''), coalesce(u.first_name, '') || left(coalesce(u.last_name, ''), 1), 'me'), '\s+', '', 'g')) || ':'
    from public.users u where u.id = public.app_user_id()
$$;

/** "Client · Project", to name a project in a note. */
create or replace function public.project_label(p_project bigint) returns text
language sql stable set search_path = public as $$
  select concat_ws(' · ', nullif(btrim(c.name), ''), p.name) from public.projects p left join public.companies c on c.id = p.company_id where p.id = p_project
$$;

/** The rep on a project to give a name to: the one who asked, when they are on it; else whoever has fewest names to call. */
create or replace function public.rep_for_name(p_project bigint) returns bigint
language sql stable set search_path = public as $$
  select coalesce(
    (select pa.ae_user_id from public.project_assignments pa where pa.project_id = p_project and pa.ae_user_id = public.app_user_id()),
    (select pa.ae_user_id from public.project_assignments pa join public.users u on u.id = pa.ae_user_id and u.status = 'active'
      where pa.project_id = p_project
      order by (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
                 where l.project_id = p_project and l.assigned_user_id = pa.ae_user_id and l.deleted_at is null and r.viable and r.callable),
               pa.ae_user_id
      limit 1))
$$;

create or replace function public.transfer_lead(p_lead bigint, p_project bigint, p_into bigint default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_lead    public.leads;
  v_into    public.leads;
  v_target  public.projects;
  v_new     bigint;
  v_contact bigint := public.call_result_from_text('APPT', 'Lead-No Contact');
  v_stamp   text := public.note_stamp();
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can transfer a lead' using errcode = '42501';
  end if;
  select * into v_lead from public.leads where id = p_lead and deleted_at is null for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select * into v_target from public.projects where id = p_project and deleted_at is null;
  if not found or public.project_type_code(p_project) is distinct from 'APPT' then
    raise exception 'Choose an appointment project to give the lead to' using errcode = '22023';
  end if;
  if v_target.status_id is distinct from (select id from public.project_statuses where name = 'Active') then
    raise exception 'That project is not active' using errcode = '22023';
  end if;
  if p_project = v_lead.project_id then
    raise exception 'The lead is already on that project' using errcode = '22023';
  end if;

  if p_into is not null then
    -- The same business already on that client's list: put back on it.
    select * into v_into from public.leads where id = p_into and project_id = p_project and deleted_at is null for update;
    if not found then
      raise exception 'That record is no longer on that project' using errcode = 'P0002';
    end if;
    update public.leads
       set result_id = v_contact, resolved_at = null,
           assigned_user_id = coalesce(case when assigned_user_id in (select ae_user_id from public.project_assignments where project_id = p_project)
                                            then assigned_user_id end, public.rep_for_name(p_project))
     where id = p_into;
    perform public.add_name_note(p_into, concat_ws(E'\n', v_stamp || ' Transferred here from ' || public.project_label(v_lead.project_id) || '.',
      case when nullif(btrim(v_lead.client_note), '') is not null then 'Client notes from that record:' || E'\n' || btrim(v_lead.client_note) end));
    v_new := p_into;
  else
    if exists (select 1 from public.leads where project_id = p_project and deleted_at is null
                and public.phone_key(phone) is not null and public.phone_key(phone) = public.phone_key(v_lead.phone)) then
      raise exception 'That business is already on that project''s list: choose it from the matches' using errcode = '23505';
    end if;
    v_new := public.copy_name(p_lead, p_project, v_contact, public.rep_for_name(p_project),
      v_stamp || ' Transferred here from ' || public.project_label(v_lead.project_id) || '.');
  end if;

  update public.leads
     set result_id = public.call_result_from_text(case v_lead.stage when 'appt' then 'APPT' else 'DBDV' end,
                                                  case v_lead.stage when 'appt' then 'Lead-Removed' else 'Removed' end),
         resolved_at = now()
   where id = p_lead;
  perform public.add_name_note(p_lead, v_stamp || ' Transferred to ' || public.project_label(p_project) || '.');
  return jsonb_build_object('id', v_new, 'project_id', p_project, 'from', p_lead, 'existing', p_into is not null);
end $$;
revoke execute on function public.transfer_lead(bigint, bigint, bigint) from public, anon;
grant execute on function public.transfer_lead(bigint, bigint, bigint) to authenticated;

create or replace function public.move_names(p_ids bigint[], p_project bigint, p_result bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_type    text := public.project_type_code(p_project);
  v_target  public.projects;
  v_result  public.call_results;
  v_removed bigint;
  v_stamp   text := public.note_stamp();
  v_label   text := public.project_label(p_project);
  l         public.leads;
  v_moved   int := 0;
  v_skipped int := 0;
  v_have    text[];
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can move names' using errcode = '42501';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Choose the names to move' using errcode = '22023';
  end if;
  if array_length(p_ids, 1) > 5000 then
    raise exception 'Move up to 5,000 names at a time' using errcode = '22023';
  end if;
  select * into v_target from public.projects where id = p_project and deleted_at is null;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  if v_target.status_id is distinct from (select id from public.project_statuses where name = 'Active') then
    raise exception 'That project is not active' using errcode = '22023';
  end if;
  select * into v_result from public.call_results where id = p_result;
  if not found or v_result.project_type is distinct from v_type or v_result.applies_to is distinct from 'name' then
    raise exception 'Choose a call result of that project''s kind' using errcode = '22023';
  end if;
  v_removed := public.call_result_from_text(v_type, case v_type when 'APPT' then 'Lead-Removed' else 'Removed' end);

  -- The phones already on that project: a name there already isn't put there twice.
  select coalesce(array_agg(distinct public.phone_key(phone)) filter (where public.phone_key(phone) is not null), '{}') into v_have
    from public.leads where project_id = p_project and deleted_at is null;

  for l in select * from public.leads where id = any(p_ids) and deleted_at is null order by id for update loop
    if l.project_id = p_project then
      continue;
    end if;
    if public.project_type_code(l.project_id) is distinct from v_type then
      raise exception '% is on a different kind of project: move viable names to a DB dev project, leads to an appointment project', l.company_name
        using errcode = '22023';
    end if;
    if public.phone_key(l.phone) is not null and public.phone_key(l.phone) = any(v_have) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    perform public.copy_name(l.id, p_project, p_result, null, v_stamp || ' Moved here from ' || public.project_label(l.project_id) || '.');
    update public.leads set result_id = v_removed, resolved_at = now() where id = l.id;
    perform public.add_name_note(l.id, v_stamp || ' Moved to ' || v_label || '.');
    if public.phone_key(l.phone) is not null then
      v_have := v_have || public.phone_key(l.phone);
    end if;
    v_moved := v_moved + 1;
  end loop;

  -- Shared out evenly among that project's reps, as an import is.
  if v_moved > 0 then
    perform public.distribute_names(p_project);
  end if;
  return jsonb_build_object('moved', v_moved, 'skipped', v_skipped, 'project_id', p_project);
end $$;
revoke execute on function public.move_names(bigint[], bigint, bigint) from public, anon;
grant execute on function public.move_names(bigint[], bigint, bigint) to authenticated;

/**
 * The same business on another active client's appointment list, for a
 * transfer: the same phone, or the same name in the same ZIP or city.
 */
create or replace function public.transfer_matches(p_lead bigint)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_lead public.leads;
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can transfer a lead' using errcode = '42501';
  end if;
  select * into v_lead from public.leads where id = p_lead and deleted_at is null;
  if not found then
    return '[]'::jsonb;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', m.id, 'company', m.company_name, 'city', m.city, 'state', m.state, 'phone', m.phone,
                                        'project_id', m.project_id, 'project', public.project_label(m.project_id), 'result', r.name,
                                        'by', case when public.phone_key(m.phone) = public.phone_key(v_lead.phone) then 'phone' else 'name' end)
                     order by public.project_label(m.project_id), m.id)
      from (select * from public.leads x
             where x.deleted_at is null and x.id <> v_lead.id and x.project_id is distinct from v_lead.project_id
               and ((public.phone_key(v_lead.phone) is not null and public.phone_key(x.phone) = public.phone_key(v_lead.phone))
                 or (lower(btrim(x.company_name)) = lower(btrim(v_lead.company_name))
                     and (left(btrim(x.zip), 5) = left(btrim(v_lead.zip), 5) or lower(btrim(x.city)) = lower(btrim(v_lead.city)))))
             limit 50) m
      join public.projects p on p.id = m.project_id and p.deleted_at is null
                            and p.status_id = (select id from public.project_statuses where name = 'Active')
      join public.call_results r on r.id = m.result_id
     where public.project_type_code(m.project_id) = 'APPT'), '[]'::jsonb);
end $$;
revoke execute on function public.transfer_matches(bigint) from public, anon;
grant execute on function public.transfer_matches(bigint) to authenticated;

/** Every active project of a kind, to give names to: its name, its client's, and the office ZIP and city (the project's, else its client's). */
create or replace function public.transfer_projects(p_type text default 'APPT')
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can transfer a lead' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name, 'client', c.name,
                                        'zip', left(btrim(coalesce(nullif(btrim(p.zip), ''), c.zip)), 5),
                                        'city', coalesce(nullif(btrim(p.city), ''), c.city), 'state', coalesce(nullif(btrim(p.state), ''), c.state))
                     order by c.name, p.name)
      from public.projects p left join public.companies c on c.id = p.company_id
     where p.deleted_at is null and public.project_type_code(p.id) = p_type
       and p.status_id = (select id from public.project_statuses where name = 'Active')), '[]'::jsonb);
end $$;
revoke execute on function public.transfer_projects(text) from public, anon;
grant execute on function public.transfer_projects(text) to authenticated;

-- Finding a business on other lists by its phone, quickly.
create index if not exists leads_phone_key on public.leads (public.phone_key(phone)) where deleted_at is null;

-- ==============================================================================================================
-- 20261213100000_chat_extras.sql
-- ==============================================================================================================

-- Chat as other apps have it (Darcy, Oct 2026): reactions, replying to one
-- message, voice messages and GIFs, in the conversations under Notifications.
--
--   notifications.quote_id     the message a reply answers (shown above it)
--   notifications.attachment   { kind: 'voice', path, seconds } or
--                              { kind: 'gif', url, still, width, height, title }
--   message_reactions          an emoji each person put on a message
--   toggle_reaction()          put one on, or take it off
--   reply_to_notification()    now with the message it answers and an
--                              attachment (a voice message or GIF needs no text)
--   notification_thread()      each message with its quote, attachment and reactions
--   storage 'chat-voice'       voice messages, private: under voice/<sender>/,
--                              heard only by the two people in the conversation
--
-- Safe to run more than once. Run it before the code that uses it is pushed
-- (the code before it keeps working with it).

alter table public.notifications add column if not exists quote_id bigint references public.notifications(id) on delete set null;
alter table public.notifications add column if not exists attachment jsonb;
create index if not exists notifications_voice_path on public.notifications ((attachment ->> 'path')) where attachment is not null;

/** Whether the signed-in person sent or received a message. */
create or replace function public.in_message(p_id bigint) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.notifications n
                  where n.id = p_id and n.kind = 'message'
                    and public.app_user_id() in (n.user_id, n.sender_id))
$$;
revoke execute on function public.in_message(bigint) from public, anon;
grant execute on function public.in_message(bigint) to authenticated;

create table if not exists public.message_reactions (
  message_id bigint not null references public.notifications(id) on delete cascade,
  user_id    bigint not null references public.users(id) on delete cascade,
  emoji      text not null check (char_length(emoji) between 1 and 16),
  created_at timestamptz not null default now(),
  primary key (message_id, user_id, emoji)
);
alter table public.message_reactions enable row level security;
-- A reaction taken off reaches the other person live with what it was on.
alter table public.message_reactions replica identity full;
drop policy if exists message_reactions_read on public.message_reactions;
create policy message_reactions_read on public.message_reactions for select to authenticated
  using ((select public.in_message(message_id)));
grant select on public.message_reactions to authenticated;
do $$
begin
  execute 'drop policy if exists mfa_required on public.message_reactions';
  execute 'create policy mfa_required on public.message_reactions as restrictive for all to authenticated using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()))';
  execute 'drop policy if exists active_account_required on public.message_reactions';
  execute 'create policy active_account_required on public.message_reactions as restrictive for all to authenticated using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null)';
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'message_reactions') then
    execute 'alter publication supabase_realtime add table public.message_reactions';
  end if;
end $$;

/** Put an emoji on a message, or take it off again. The message's reactions after. */
create or replace function public.toggle_reaction(p_message bigint, p_emoji text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me    bigint := public.app_user_id();
  v_emoji text := btrim(coalesce(p_emoji, ''));
begin
  if v_me is null or not public.in_message(p_message) then
    raise exception 'That message is not in your conversations' using errcode = '42501';
  end if;
  if v_emoji = '' or char_length(v_emoji) > 16 or v_emoji ~ '[A-Za-z0-9<>\s]' then
    raise exception 'Choose an emoji' using errcode = '22023';
  end if;
  if exists (select 1 from public.message_reactions where message_id = p_message and user_id = v_me and emoji = v_emoji) then
    delete from public.message_reactions where message_id = p_message and user_id = v_me and emoji = v_emoji;
  else
    if (select count(*) from public.message_reactions where message_id = p_message and user_id = v_me) >= 12 then
      raise exception 'That''s plenty of reactions on one message' using errcode = '22023';
    end if;
    insert into public.message_reactions (message_id, user_id, emoji) values (p_message, v_me, v_emoji);
  end if;
  return coalesce((select jsonb_agg(jsonb_build_object('emoji', emoji, 'user_id', user_id) order by created_at)
                     from public.message_reactions where message_id = p_message), '[]'::jsonb);
end $$;
revoke execute on function public.toggle_reaction(bigint, text) from public, anon;
grant execute on function public.toggle_reaction(bigint, text) to authenticated;

/** A message as a conversation shows it: what it says, its attachment, the message it answers, and its reactions. */
create or replace function public.message_json(m public.notifications, p_me bigint) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', m.id, 'mine', m.sender_id = p_me, 'title', m.title, 'body', m.body, 'reply_to', m.reply_to,
    'read_at', m.read_at, 'created_at', m.created_at, 'quote_id', m.quote_id, 'attachment', m.attachment,
    'quote', (select jsonb_build_object('id', q.id, 'mine', q.sender_id = p_me, 'body', q.body, 'title', q.title, 'kind', q.attachment ->> 'kind')
                from public.notifications q where q.id = m.quote_id),
    'reactions', coalesce((select jsonb_agg(jsonb_build_object('emoji', r.emoji, 'user_id', r.user_id) order by r.created_at)
                             from public.message_reactions r where r.message_id = m.id), '[]'::jsonb))
$$;
revoke execute on function public.message_json(public.notifications, bigint) from public, anon, authenticated;

create or replace function public.notification_thread(p_id bigint, p_limit int default 100)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me       bigint := public.app_user_id();
  v_limit    int := least(greatest(coalesce(p_limit, 100), 1), 500);
  n          public.notifications;
  v_person   jsonb;
  v_messages jsonb := '[]'::jsonb;
begin
  if v_me is null then
    return null;
  end if;

  select * into n from public.notifications where id = p_id and user_id = v_me;
  if not found then
    return null;
  end if;

  if n.sender_id is not null then
    select jsonb_build_object(
             'id',     u.id,
             'name',   coalesce(nullif(concat_ws(' ', u.first_name, u.last_name), ''), 'Lighthouse user'),
             'role',   u.role,
             'active', u.status = 'active')
      into v_person
      from public.users u
     where u.id = n.sender_id;

    select coalesce(jsonb_agg(public.message_json(t, v_me) order by t.created_at, t.id), '[]'::jsonb)
      into v_messages
      from (
        select m.*
          from public.notifications m
         where m.kind = 'message'
           and ((m.user_id = v_me and m.sender_id = n.sender_id)
             or (m.user_id = n.sender_id and m.sender_id = v_me))
         order by m.created_at desc, m.id desc
         limit v_limit
      ) t;
  end if;

  return jsonb_build_object(
    'notification', jsonb_build_object(
       'id', n.id, 'kind', n.kind, 'title', n.title, 'body', n.body, 'link', n.link,
       'read_at', n.read_at, 'created_at', n.created_at, 'reply_to', n.reply_to),
    'person',   v_person,
    'messages', v_messages);
end $$;
revoke execute on function public.notification_thread(bigint, int) from public, anon;
grant execute on function public.notification_thread(bigint, int) to authenticated;

-- A reply, now with the message it answers and an attachment. (The old two-argument
-- one goes: with both, a call naming only p_id and p_body could not tell them apart.)
drop function if exists public.reply_to_notification(bigint, text);
create or replace function public.reply_to_notification(p_id bigint, p_body text, p_quote bigint default null, p_attachment jsonb default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me    bigint := public.app_user_id();
  v_body  text := btrim(coalesce(p_body, ''));
  v_att   jsonb;
  v_kind  text := p_attachment ->> 'kind';
  n       public.notifications;
  v_to    public.users;
  v_row   public.notifications;
begin
  if v_me is null then
    raise exception 'Sign in to reply' using errcode = '42501';
  end if;
  if length(v_body) > 1000 then
    raise exception 'Keep a reply under 1,000 characters' using errcode = '22023';
  end if;

  -- Only a notification in your own inbox, and only one a person sent.
  select * into n from public.notifications where id = p_id and user_id = v_me;
  if not found then
    raise exception 'That notification is not in your inbox' using errcode = '42501';
  end if;
  if n.sender_id is null then
    raise exception 'This notification came from Lighthouse itself, so there is no one to reply to'
      using errcode = '22023';
  end if;

  select * into v_to from public.users where id = n.sender_id;
  if not found or v_to.status <> 'active' then
    raise exception '% can no longer receive messages',
      coalesce(nullif(concat_ws(' ', v_to.first_name, v_to.last_name), ''), 'That person')
      using errcode = '22023';
  end if;

  -- A voice message: one the sender put in their own folder, two minutes at most.
  if v_kind = 'voice' then
    if coalesce(p_attachment ->> 'path', '') !~ ('^voice/' || v_me || '/[0-9a-f-]{36}\.(webm|ogg|m4a|mp4|mp3)$')
       or not exists (select 1 from storage.objects o where o.bucket_id = 'chat-voice' and o.name = p_attachment ->> 'path') then
      raise exception 'That voice message didn''t upload. Record it again.' using errcode = '22023';
    end if;
    v_att := jsonb_build_object('kind', 'voice', 'path', p_attachment ->> 'path',
                                'seconds', least(greatest(coalesce((p_attachment ->> 'seconds')::numeric, 0), 0), 120));
  -- A GIF from GIPHY: only their own addresses.
  elsif v_kind = 'gif' then
    if length(coalesce(p_attachment ->> 'url', '')) > 500 or length(coalesce(p_attachment ->> 'still', '')) > 500
       or coalesce(p_attachment ->> 'url', '') !~ '^https://(media[0-9]*|i)\.giphy\.com/[A-Za-z0-9/_.?=&-]+$'
       or (p_attachment ->> 'still' is not null and p_attachment ->> 'still' !~ '^https://(media[0-9]*|i)\.giphy\.com/[A-Za-z0-9/_.?=&-]+$') then
      raise exception 'That GIF can''t be sent' using errcode = '22023';
    end if;
    v_att := jsonb_build_object('kind', 'gif', 'url', p_attachment ->> 'url', 'still', p_attachment ->> 'still',
                                'width', least(greatest(coalesce((p_attachment ->> 'width')::int, 200), 1), 2000),
                                'height', least(greatest(coalesce((p_attachment ->> 'height')::int, 200), 1), 2000),
                                'title', left(coalesce(p_attachment ->> 'title', ''), 140));
  elsif p_attachment is not null then
    raise exception 'That can''t be sent' using errcode = '22023';
  end if;
  if length(v_body) = 0 and v_att is null then
    raise exception 'Write a reply first' using errcode = '22023';
  end if;

  -- The message it answers: one in this conversation.
  if p_quote is not null and not exists (
       select 1 from public.notifications q
        where q.id = p_quote and q.kind = 'message'
          and ((q.user_id = v_me and q.sender_id = v_to.id) or (q.user_id = v_to.id and q.sender_id = v_me))) then
    raise exception 'That message isn''t in this conversation' using errcode = '22023';
  end if;

  -- A person typing will not hit this; a script sending in a loop will.
  if (select count(*) from public.notifications
       where sender_id = v_me and reply_to is not null
         and created_at > now() - interval '1 minute') >= 20 then
    raise exception 'You are sending replies too quickly. Wait a moment and try again.'
      using errcode = '54000';
  end if;

  -- A batch id like any direct message, so the sender can read it back (notifications_read).
  -- With no text, what it is, for the bell and desktop notifications.
  insert into public.notifications (user_id, sender_id, batch_id, kind, title, body, reply_to, quote_id, attachment)
  values (v_to.id, v_me, gen_random_uuid(), 'message',
          left('Re: ' || regexp_replace(n.title, '^\s*(re:\s*)+', '', 'i'), 160),
          coalesce(nullif(v_body, ''), case v_kind when 'voice' then '🎤 Voice message' when 'gif' then 'GIF' end),
          n.id, p_quote, v_att)
  returning * into v_row;

  update public.notifications set read_at = now() where id = n.id and read_at is null;

  return public.message_json(v_row, v_me);
end $$;
revoke execute on function public.reply_to_notification(bigint, text, bigint, jsonb) from public, anon;
grant execute on function public.reply_to_notification(bigint, text, bigint, jsonb) to authenticated;

-- Voice messages: private, five megabytes at most (two minutes is well under).
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('chat-voice', 'chat-voice', false, 5242880, array['audio/webm', 'audio/ogg', 'audio/mp4', 'audio/mpeg', 'audio/aac', 'audio/x-m4a'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists chat_voice_insert on storage.objects;
create policy chat_voice_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'chat-voice' and (storage.foldername(name))[1] = 'voice'
              and (storage.foldername(name))[2] = public.app_user_id()::text);
-- Heard by whoever recorded it, and by the two people in a conversation it was sent in.
drop policy if exists chat_voice_read on storage.objects;
create policy chat_voice_read on storage.objects for select to authenticated
  using (bucket_id = 'chat-voice' and public.app_user_id() is not null
         and ((storage.foldername(name))[2] = public.app_user_id()::text
              or exists (select 1 from public.notifications n
                          where n.attachment ->> 'path' = storage.objects.name
                            and public.app_user_id() in (n.user_id, n.sender_id))));
-- One recorded and not sent is taken away again.
drop policy if exists chat_voice_delete on storage.objects;
create policy chat_voice_delete on storage.objects for delete to authenticated
  using (bucket_id = 'chat-voice' and (storage.foldername(name))[2] = public.app_user_id()::text
         and not exists (select 1 from public.notifications n where n.attachment ->> 'path' = storage.objects.name));

-- ==============================================================================================================
-- 20261214100000_result_change.sql
-- ==============================================================================================================

-- Changing call results in bulk (Sean, Oct 2026), as the old system's
-- Result Change tools did: a group of names on a project from one result to
-- another (names marked Removed back to Viable), or names picked by what
-- they are (a client wants no leads under 5 employees: those Removed).
--
--   employee_n(lead)       a name's employees as a number, to filter and sort
--                          a project's list by (a computed field: no column
--                          added, nothing rewritten)
--   change_results(ids, result)   the names given that result: no call is
--                          recorded and no pay; a note on each says what it
--                          was; names callable again are shared out to the
--                          project's reps
--
-- Administrators and account managers. Safe to run more than once.

create or replace function public.employee_n(public.leads) returns int
language sql immutable parallel safe set search_path = public as $$
  select public.employee_count($1.employees)
$$;
grant execute on function public.employee_n(public.leads) to authenticated;

create or replace function public.change_results(p_ids bigint[], p_result bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_result  public.call_results;
  v_status  bigint;
  v_stamp   text := public.note_stamp();
  l         record;
  v_changed int := 0;
  v_same    int := 0;
  v_projects bigint[] := '{}';
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can change call results' using errcode = '42501';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Choose the names to change' using errcode = '22023';
  end if;
  if array_length(p_ids, 1) > 5000 then
    raise exception 'Change up to 5,000 names at a time' using errcode = '22023';
  end if;
  select * into v_result from public.call_results where id = p_result;
  -- Only results that are a name's standing: one that promotes, books an appointment
  -- or charges back pay goes through a call, not here.
  if not found or v_result.applies_to is distinct from 'name' or v_result.effect not in ('none', 'pending') then
    raise exception 'Choose a call result that names can be changed to' using errcode = '22023';
  end if;
  select s.id into v_status from public.lead_statuses s where s.code = v_result.status_code;

  for l in
    select x.id, x.project_id, x.result_id, r.name as was
      from public.leads x join public.call_results r on r.id = x.result_id
     where x.id = any(p_ids) and x.deleted_at is null
     order by x.id
       for update of x
  loop
    if public.project_type_code(l.project_id) is distinct from v_result.project_type then
      raise exception '% is for % projects; these names are on a different kind', v_result.name,
        case v_result.project_type when 'APPT' then 'appointment' else 'DB dev' end using errcode = '22023';
    end if;
    if l.result_id = p_result then
      v_same := v_same + 1;
      continue;
    end if;
    update public.leads
       set result_id = p_result,
           status_id = coalesce(v_status, status_id),
           resolved_at = case when v_result.viable then null else coalesce(resolved_at, now()) end
     where id = l.id;
    perform public.add_name_note(l.id, v_stamp || ' Call result changed from ' || l.was || ' to ' || v_result.name || '.');
    v_changed := v_changed + 1;
    if not (l.project_id = any(v_projects)) then
      v_projects := v_projects || l.project_id;
    end if;
  end loop;

  -- Names back on the call lists go to the project's reps, evenly.
  if v_changed > 0 and v_result.viable and v_result.callable then
    for l in select unnest(v_projects) as project_id loop
      perform public.distribute_names(l.project_id);
    end loop;
  end if;
  return jsonb_build_object('changed', v_changed, 'same', v_same, 'result', v_result.name);
end $$;
revoke execute on function public.change_results(bigint[], bigint) from public, anon;
grant execute on function public.change_results(bigint[], bigint) to authenticated;

-- ==============================================================================================================
-- 20261215100000_message_rules.sql
-- ==============================================================================================================

-- Who may message whom (Sean, Oct 2026): sending to everyone in a role (all
-- clients, all agents…) is an administrator's alone; an account manager sends
-- to the projects they are on (the client's people and the project's reps)
-- and to particular people (any administrator or manager, and the clients and
-- agents on their own projects); and the administrators get a copy of
-- whatever a manager sends to clients or agents.
--
--   project_people(project)      who is on a project: its client's people and its reps
--   message_projects()           the projects the caller may send to, each with its people
--   send_notification(…, p_projects)   checks the above, and sends the copies
--
-- Administrators and account managers. Safe to run more than once. Run it
-- before the code that goes with it is pushed (the code before it keeps
-- working with it).

create or replace function public.project_people(p_project bigint) returns setof bigint
language sql stable security definer set search_path = public as $$
  select u.id from public.users u
   where u.status = 'active'
     and ((u.role = 'client' and u.company_id is not null
           and u.company_id = (select p.company_id from public.projects p where p.id = p_project and p.deleted_at is null))
       or u.id in (select pa.ae_user_id from public.project_assignments pa where pa.project_id = p_project
                   union select pa.cl_user_id from public.project_assignments pa where pa.project_id = p_project))
$$;
revoke execute on function public.project_people(bigint) from public, anon, authenticated;

/** The projects the caller may send a message to (every active one for an administrator, a manager's own), with who is on each. */
create or replace function public.message_projects() returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_me    bigint := public.app_user_id();
  v_admin boolean := public.app_role() = 'admin';
begin
  if not public.is_manager() then
    return '[]'::jsonb;
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', p.id, 'label', public.project_label(p.id),
                                        'people', coalesce((select jsonb_agg(x) from public.project_people(p.id) x where x <> v_me), '[]'::jsonb))
                     order by public.project_label(p.id))
      from public.projects p
     where p.deleted_at is null
       and p.status_id = (select id from public.project_statuses where name = 'Active')
       and (v_admin or exists (select 1 from public.project_assignments pa where pa.project_id = p.id and pa.ae_user_id = v_me))), '[]'::jsonb);
end $$;
revoke execute on function public.message_projects() from public, anon;
grant execute on function public.message_projects() to authenticated;

drop function if exists public.send_notification(bigint[], text[], text, text, text);
create or replace function public.send_notification(
  p_user_ids bigint[],
  p_roles    text[],
  p_title    text,
  p_body     text,
  p_link     text default null,
  p_projects bigint[] default null
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me     bigint := public.app_user_id();
  v_admin  boolean := public.app_role() = 'admin';
  v_batch  uuid := gen_random_uuid();
  v_sent   int;
  v_title  text := btrim(coalesce(p_title, ''));
  v_body   text := nullif(btrim(coalesce(p_body, '')), '');
  v_link   text := nullif(btrim(coalesce(p_link, '')), '');
  v_to     bigint[];
  v_names  text;
  v_n      int;
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can send notifications'
      using errcode = '42501';
  end if;
  if length(v_title) = 0 then
    raise exception 'A title is required' using errcode = '22023';
  end if;
  if v_link is not null and v_link !~ '^/([^/\\[:space:][:cntrl:]][^[:space:][:cntrl:]]*)?$' then
    raise exception 'Links must point inside Lighthouse, like /leads/123' using errcode = '22023';
  end if;
  if cardinality(coalesce(p_roles, '{}')) > 0 and not v_admin then
    raise exception 'Only administrators can send to everyone in a role' using errcode = '42501';
  end if;
  if not v_admin and exists (
       select 1 from unnest(coalesce(p_projects, '{}')) as pid
        where not exists (select 1 from public.project_assignments pa where pa.project_id = pid and pa.ae_user_id = v_me)) then
    raise exception 'You can send to the projects you are on only' using errcode = '42501';
  end if;
  -- A manager's clients and agents are those on their own projects.
  if not v_admin and exists (
       select 1 from public.users u
        where u.id = any(coalesce(p_user_ids, '{}')) and u.role in ('client', 'agent')
          and u.id not in (select public.project_people(pa.project_id) from public.project_assignments pa where pa.ae_user_id = v_me)) then
    raise exception 'You can message the clients and agents on your own projects only' using errcode = '42501';
  end if;

  v_to := array(
    select distinct x from (
      select u.id as x from public.users u where u.id = any(coalesce(p_user_ids, '{}')) or u.role = any(coalesce(p_roles, '{}'))
      union
      select public.project_people(pid) from unnest(coalesce(p_projects, '{}')) as pid
    ) t where x is not null);

  v_sent := public.notify_users(v_to, 'message', v_title, v_body, v_link, null, v_batch);

  -- A manager's message to clients or agents: a copy to each administrator, saying who it went to.
  if not v_admin and v_sent > 0 and exists (select 1 from public.users u where u.id = any(v_to) and u.role in ('client', 'agent') and u.id <> v_me) then
    select string_agg(nm, ', '), count(*) into v_names, v_n
      from (select coalesce(nullif(concat_ws(' ', u.first_name, u.last_name), ''), u.email) as nm
              from public.users u where u.id = any(v_to) and u.id <> v_me and u.status = 'active'
             order by u.first_name, u.last_name limit 12) s;
    v_n := (select count(*) from public.users u where u.id = any(v_to) and u.id <> v_me and u.status = 'active');
    perform public.notify_users(
      array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and not (u.id = any(v_to))),
      'message', left('[Copy] ' || v_title, 160),
      left('Sent to ' || v_names || case when v_n > 12 then ' and ' || (v_n - 12) || ' more' else '' end || '.'
           || coalesce(E'\n\n' || v_body, ''), 1000),
      v_link, null, null);
  end if;

  return jsonb_build_object('batch', v_batch, 'sent', v_sent);
end $$;
revoke execute on function public.send_notification(bigint[], text[], text, text, text, bigint[]) from public, anon;
grant execute on function public.send_notification(bigint[], text[], text, text, text, bigint[]) to authenticated;

-- ==============================================================================================================
-- 20261216100000_client_removals.sql
-- ==============================================================================================================

-- Each client's removal list (Oct 2026): the names a client doesn't want,
-- kept for the lists they pull later, so a new list comes in already
-- cleaned of them and the client doesn't scrub the same names again.
--
--   client_removals            one row per business taken off, for a client
--                              (companies.id), with why:
--                                deletion          the client doesn't want it, or
--                                                  a duplicate left off an import
--                                dont_call         do not call
--                                current_customer  already the client's customer
--   call_results.client_removal  the results that put a name on the list:
--                              Removed / Lead-Removed (deletion), DoNotCall /
--                              Lead-DoNotCall, Client / Lead-CurrentClient.
--                              However the result is given (a call, Result
--                              Change, the client's own marking, an import of
--                              an old list), the trigger remembers it; a name
--                              given another result is forgotten again.
--   mark_names(ids, reason, note)  a client's people (or staff) taking names
--                              off: the result for the reason, a note on each.
--
-- A name marked Removed because it was moved to another project of the same
-- client (move_names) is not a removal: it is still being called there.
--
-- Leads already on those results are put on their client's list once, here.
-- Safe to run more than once.

alter table public.call_results add column if not exists client_removal text
  check (client_removal in ('deletion', 'dont_call', 'current_customer'));
update public.call_results set client_removal = case
    when name in ('Removed', 'Lead-Removed') then 'deletion'
    when name in ('DoNotCall', 'Lead-DoNotCall') then 'dont_call'
    when name in ('Client', 'Lead-CurrentClient') then 'current_customer'
  end
 where applies_to = 'name' and name in ('Removed', 'Lead-Removed', 'DoNotCall', 'Lead-DoNotCall', 'Client', 'Lead-CurrentClient');

create table if not exists public.client_removals (
  id            bigint generated always as identity primary key,
  company_id    bigint not null references public.companies(id) on delete cascade,
  reason        text not null check (reason in ('deletion', 'dont_call', 'current_customer')),
  -- lead: a name on one of the client's lists given the result; import: a duplicate left off a list.
  source        text not null default 'lead' check (source in ('lead', 'import')),
  lead_id       bigint references public.leads(id) on delete set null,
  -- The business as it was, to know it again on a new list.
  company_name  text not null,
  contact_name  text,
  phone         text,
  ein           text,
  address       text,
  city          text,
  state         text,
  zip           text,
  note          text,
  removed_by    bigint references public.users(id) on delete set null,
  created_at    timestamptz not null default now()
);
create unique index if not exists client_removals_lead on public.client_removals (lead_id) where lead_id is not null;
create index if not exists client_removals_company on public.client_removals (company_id, created_at desc);

alter table public.client_removals enable row level security;
-- Staff read every client's list; a client's people read their own.
drop policy if exists client_removals_read on public.client_removals;
create policy client_removals_read on public.client_removals for select
  using ((select public.is_staff()) or company_id = (select public.app_company_id()));
-- Administrators add duplicates left off an import, and take names off a list.
drop policy if exists client_removals_admin on public.client_removals;
create policy client_removals_admin on public.client_removals for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
grant select, insert, update, delete on public.client_removals to authenticated;

-- An import says what it left off.
alter table public.import_batches add column if not exists duplicate_count int not null default 0;
alter table public.import_batches add column if not exists removed_count int not null default 0;

/**
 * Whether a lead given a Deletion result was only moved: the same business
 * (phone) still being called on another project of the same client.
 */
create or replace function public.moved_within_client(p_lead public.leads, p_company bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select public.phone_key(p_lead.phone) is not null and exists (
    select 1
      from public.leads x
      join public.projects p on p.id = x.project_id and p.deleted_at is null
      join public.call_results r on r.id = x.result_id
     where public.phone_key(x.phone) = public.phone_key(p_lead.phone)
       and x.deleted_at is null and x.id <> p_lead.id and x.project_id is distinct from p_lead.project_id
       and p.company_id = p_company and r.viable)
$$;
revoke execute on function public.moved_within_client(public.leads, bigint) from public, anon, authenticated;

/** A lead's result put it on (or took it off) its client's removal list. */
create or replace function public.remember_removal()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_reason  text;
  v_company bigint;
begin
  if tg_op = 'UPDATE' and new.result_id is not distinct from old.result_id and new.project_id is not distinct from old.project_id then
    return null;
  end if;
  select client_removal into v_reason from public.call_results where id = new.result_id;
  select company_id into v_company from public.projects where id = new.project_id;
  if v_reason is null or v_company is null or new.company_name is null
     or (v_reason = 'deletion' and public.moved_within_client(new, v_company)) then
    -- Given another result (a mistake put right): no longer a removal.
    if tg_op = 'UPDATE' then
      delete from public.client_removals where lead_id = new.id and source = 'lead';
    end if;
    return null;
  end if;
  insert into public.client_removals (company_id, reason, source, lead_id, company_name, contact_name, phone, ein, address, city, state, zip, removed_by)
  values (v_company, v_reason, 'lead', new.id, new.company_name, new.contact_name, new.phone, new.ein, new.address, new.city, new.state, new.zip,
          public.app_user_id())
  on conflict (lead_id) where lead_id is not null do update
    set company_id = excluded.company_id, reason = excluded.reason, company_name = excluded.company_name,
        contact_name = excluded.contact_name, phone = excluded.phone, ein = excluded.ein, address = excluded.address,
        city = excluded.city, state = excluded.state, zip = excluded.zip,
        removed_by = coalesce(excluded.removed_by, public.client_removals.removed_by), created_at = now();
  return null;
end $$;
revoke execute on function public.remember_removal() from public, anon, authenticated;

drop trigger if exists remember_removal on public.leads;
create trigger remember_removal after insert or update of result_id, project_id on public.leads
  for each row execute function public.remember_removal();

/**
 * Names taken off a client's lists, with why: a client's people for their
 * own projects' names (they can't record calls), staff for any. Each takes
 * the result for the reason on its kind of project; a note on each says who
 * and why, and the note given is kept on the list. Names with an appointment
 * or made a lead (promoted) are left as they are and counted: those go
 * through the people who set them.
 */
create or replace function public.mark_names(p_ids bigint[], p_reason text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role    text := public.app_role();
  v_company bigint := public.app_company_id();
  v_me      bigint := public.app_user_id();
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_label   text := case p_reason when 'deletion' then 'Deletion' when 'dont_call' then 'Don''t call' else 'Current customer' end;
  v_stamp   text := public.note_stamp();
  v_by      text;
  r         public.call_results;
  l         record;
  v_marked  int := 0;
  v_kept    int := 0;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'client') then
    raise exception 'Only a client''s people, administrators and account managers can take names off' using errcode = '42501';
  end if;
  if p_reason is null or p_reason not in ('deletion', 'dont_call', 'current_customer') then
    raise exception 'Choose why these names come off' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Choose the names to take off' using errcode = '22023';
  end if;
  if array_length(p_ids, 1) > 5000 then
    raise exception 'Take off up to 5,000 names at a time' using errcode = '22023';
  end if;
  select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''), email) into v_by from public.users where id = v_me;

  for l in
    select x.id, x.project_id, x.result_id, p.company_id, public.project_type_code(x.project_id) as kind, cr.effect
      from public.leads x
      join public.projects p on p.id = x.project_id
      join public.call_results cr on cr.id = x.result_id
     where x.id = any(p_ids) and x.deleted_at is null
     order by x.id
       for update of x
  loop
    if v_role = 'client' and l.company_id is distinct from v_company then
      raise exception 'Those names are not on your lists' using errcode = '42501';
    end if;
    if l.effect not in ('none', 'pending') then
      v_kept := v_kept + 1;
      continue;
    end if;
    select * into r from public.call_results
     where project_type = l.kind and applies_to = 'name' and client_removal = p_reason
     order by sort_order limit 1;
    if not found then
      raise exception 'No call result to mark these names with' using errcode = 'P0002';
    end if;
    if l.result_id is distinct from r.id then
      update public.leads
         set result_id = r.id,
             status_id = coalesce((select s.id from public.lead_statuses s where s.code = r.status_code), status_id),
             resolved_at = coalesce(resolved_at, now())
       where id = l.id;
    end if;
    perform public.add_name_note(l.id, v_stamp || ' Taken off the list by ' || coalesce(v_by, 'the client') || ': ' || v_label
                                      || coalesce(' (' || v_note || ')', '') || '.');
    update public.client_removals
       set reason = p_reason, note = coalesce(v_note, note), removed_by = v_me
     where lead_id = l.id;
    v_marked := v_marked + 1;
  end loop;
  return jsonb_build_object('marked', v_marked, 'kept', v_kept, 'reason', v_label);
end $$;
revoke execute on function public.mark_names(bigint[], text, text) from public, anon;
grant execute on function public.mark_names(bigint[], text, text) to authenticated;

-- The names already on those results, onto their client's list (Sean's client, Oct 2026: "Perfect!").
insert into public.client_removals (company_id, reason, source, lead_id, company_name, contact_name, phone, ein, address, city, state, zip, created_at)
select p.company_id, r.client_removal, 'lead', l.id, l.company_name, l.contact_name, l.phone, l.ein, l.address, l.city, l.state, l.zip,
       coalesce(l.resolved_at, l.updated_at, now())
  from public.leads l
  join public.projects p on p.id = l.project_id
  join public.call_results r on r.id = l.result_id
 where r.client_removal is not null and p.company_id is not null and l.company_name is not null and l.deleted_at is null
   and not (r.client_removal = 'deletion' and public.moved_within_client(l, p.company_id))
on conflict (lead_id) where lead_id is not null do nothing;

-- ==============================================================================================================
-- 20261217100000_project_renewal.sql
-- ==============================================================================================================

-- Renewing a lead project (Oct 2026). A client's 6-12 month program ends
-- with names still worth calling: the renewal is a new lead project
-- (ProjectB) on the same appointment project (the "parent project" of all
-- the client's lead projects), carrying over all or some of the viable names
-- and closing the old one, without loading anything again.
--
--   call results Moved / Lead-Moved  a name carried to another of the same
--                              client's projects: still being called there,
--                              so not a removal, and counted once in the
--                              client's totals (on the project it went to)
--   projects.renewed_from_id   the project a renewal carries on from
--   renew_project(...)         ProjectB from ProjectA: its settings, rates,
--                              appointment project and office; the managers
--                              chosen; a new goal and dates; the viable names
--                              chosen (each keeps its call result, notes,
--                              coverage and X-dates), the originals marked
--                              Moved; ProjectA Completed if asked
--   move_names()               names moved within a client are Moved too
--
-- A client takes a lead in their pipeline off too: an X-date corrected is still a lead
-- (mark_names), and comes off as Lead-Removed, still in the reports.
--
-- And managers told (the client asked whether they are): a project put in
-- their hands, a project of theirs paused, completed or active again, and
-- names shared out to them now say which project.
--
-- Safe to run more than once.

-- ---------------------------------------------------------------------------
-- 1. Moved
-- ---------------------------------------------------------------------------

insert into public.call_results (project_type, name, sort_order, viable, callable, sort_last, effect, pay_kind, applies_to, status_code, action, aliases, delivers)
select v.project_type, v.name, v.sort_order, false, true, false, 'none', null, 'name', 'removed', v.action, v.aliases, false
  from (values
    ('DBDV', 'Moved', 131, 'Carried over to another of the client''s projects (a renewal, or names moved): called there, and counted there in the client''s totals', array['moved']),
    ('APPT', 'Lead-Moved', 101, 'Carried over to another of the client''s appointment projects: called there', array['lead-moved', 'moved'])
  ) as v(project_type, name, sort_order, action, aliases)
 where not exists (select 1 from public.call_results r where r.project_type = v.project_type and r.name = v.name);

-- An import says how many of its names were already on the project or its family.
alter table public.import_batches add column if not exists existing_count int not null default 0;

alter table public.projects add column if not exists renewed_from_id bigint references public.projects(id) on delete set null;
create index if not exists projects_renewed_from on public.projects (renewed_from_id) where renewed_from_id is not null;

/** The Moved result of a kind of project. */
create or replace function public.moved_result(p_type text)
returns bigint
language sql stable set search_path = public as $$
  select id from public.call_results
   where project_type = p_type and name = case p_type when 'APPT' then 'Lead-Moved' else 'Moved' end
   limit 1
$$;

-- A client's totals: a name carried over is counted on the project it went to, not twice.
create or replace function public.lead_stats(p_company_id bigint default null, p_project_id bigint default null)
returns table(project_id bigint, names bigint, names_left bigint, leads_active bigint, leads_resolved bigint, developed bigint, appointments bigint, invalid_appointments bigint)
language sql stable set search_path = public as $$
  with ps as (
    select p.id from public.projects p
     where (p_project_id is not null and p.id = p_project_id)
        or (p_project_id is null and p_company_id is not null and p.company_id = p_company_id)
  ), scoped as (
    -- A project's names: those on it, and those it sent on to another.
    select ps.id as pid, c.*, (c.project_id = ps.id) as here
      from ps join public.lead_classes c
        on c.project_id = ps.id or (c.source_project_id = ps.id and c.source_project_id <> c.project_id)
  ), per as (
    select pid,
           count(*) as names,
           count(*) filter (where here and stage = 'dbdev' and viable) as names_left,
           count(*) filter (where stage = 'appt' and viable) as leads_active,
           count(*) filter (where stage = 'appt' and not viable) as leads_resolved,
           count(*) filter (where developed) as developed,
           count(*) filter (where effect in ('appointment', 'confirm')) as appointments,
           count(*) filter (where effect = 'appointment_invalid') as invalid_appointments
      from scoped group by pid
  )
  select ps.id, coalesce(per.names, 0), coalesce(per.names_left, 0), coalesce(per.leads_active, 0), coalesce(per.leads_resolved, 0),
         coalesce(per.developed, 0), coalesce(per.appointments, 0), coalesce(per.invalid_appointments, 0)
    from ps left join per on per.pid = ps.id
  union all
  select null, count(*),
         count(*) filter (where c.stage = 'dbdev' and c.viable),
         count(*) filter (where c.stage = 'appt' and c.viable),
         count(*) filter (where c.stage = 'appt' and not c.viable),
         count(*) filter (where c.developed),
         count(*) filter (where c.effect in ('appointment', 'confirm')),
         count(*) filter (where c.effect = 'appointment_invalid')
    from public.lead_classes c
   where p_project_id is null and p_company_id is not null and c.project_id in (select id from ps)
     and c.result not in ('Moved', 'Lead-Moved')
  -- The client's total only when a client was asked for (an aggregate otherwise still answers, with zeros).
  having p_project_id is null and p_company_id is not null;
$$;

-- ---------------------------------------------------------------------------
-- 2. Moving names: within a client, Moved
-- ---------------------------------------------------------------------------

create or replace function public.move_names(p_ids bigint[], p_project bigint, p_result bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_type    text := public.project_type_code(p_project);
  v_target  public.projects;
  v_result  public.call_results;
  v_removed bigint;
  v_moved_r bigint;
  v_stamp   text := public.note_stamp();
  v_label   text := public.project_label(p_project);
  l         public.leads;
  v_moved   int := 0;
  v_skipped int := 0;
  v_have    text[];
  v_new     bigint;
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can move names' using errcode = '42501';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Choose the names to move' using errcode = '22023';
  end if;
  if array_length(p_ids, 1) > 5000 then
    raise exception 'Move up to 5,000 names at a time' using errcode = '22023';
  end if;
  select * into v_target from public.projects where id = p_project and deleted_at is null;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  if v_target.status_id is distinct from (select id from public.project_statuses where name = 'Active') then
    raise exception 'That project is not active' using errcode = '22023';
  end if;
  select * into v_result from public.call_results where id = p_result;
  if not found or v_result.project_type is distinct from v_type or v_result.applies_to is distinct from 'name' then
    raise exception 'Choose a call result of that project''s kind' using errcode = '22023';
  end if;
  v_removed := public.call_result_from_text(v_type, case v_type when 'APPT' then 'Lead-Removed' else 'Removed' end);
  v_moved_r := public.moved_result(v_type);

  -- The phones already on that project: a name there already isn't put there twice.
  select coalesce(array_agg(distinct public.phone_key(phone)) filter (where public.phone_key(phone) is not null), '{}') into v_have
    from public.leads where project_id = p_project and deleted_at is null;

  for l in select * from public.leads where id = any(p_ids) and deleted_at is null order by id for update loop
    if l.project_id = p_project then
      continue;
    end if;
    if public.project_type_code(l.project_id) is distinct from v_type then
      raise exception '% is on a different kind of project: move viable names to a DB dev project, leads to an appointment project', l.company_name
        using errcode = '22023';
    end if;
    if public.phone_key(l.phone) is not null and public.phone_key(l.phone) = any(v_have) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    v_new := public.copy_name(l.id, p_project, p_result, null, v_stamp || ' Moved here from ' || public.project_label(l.project_id) || '.');
    -- A name moved to another lead project is that project's: the leads it makes count there, not where it came from.
    if v_type = 'DBDV' then
      update public.leads set source_project_id = p_project where id = v_new;
    end if;
    -- Still the client's (another of their projects): Moved, not a removal.
    update public.leads
       set result_id = case when (select company_id from public.projects where id = l.project_id) is not distinct from v_target.company_id
                            then coalesce(v_moved_r, v_removed) else v_removed end,
           resolved_at = now()
     where id = l.id;
    perform public.add_name_note(l.id, v_stamp || ' Moved to ' || v_label || '.');
    if public.phone_key(l.phone) is not null then
      v_have := v_have || public.phone_key(l.phone);
    end if;
    v_moved := v_moved + 1;
  end loop;

  -- Shared out evenly among that project's reps, as an import is.
  if v_moved > 0 then
    perform public.distribute_names(p_project);
  end if;
  return jsonb_build_object('moved', v_moved, 'skipped', v_skipped, 'project_id', p_project);
end $$;
revoke execute on function public.move_names(bigint[], bigint, bigint) from public, anon;
grant execute on function public.move_names(bigint[], bigint, bigint) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. Renewing a lead project
-- ---------------------------------------------------------------------------

/**
 * ProjectB from ProjectA (administrators). p_names: 'all' carries every
 * viable name still on ProjectA (Viable-No Contact, -Staged, -Left Message,
 * -Email, Pending), 'picked' only p_ids among them, 'none' starts with no
 * names (a new list to import). Each name keeps its call result; the
 * original is marked Moved, with a note. p_managers are put on ProjectB
 * and the names shared out among them. ProjectA is marked Completed when
 * p_complete. Returns { project_id, moved, skipped }.
 */
create or replace function public.renew_project(
  p_project    bigint,
  p_name       text,
  p_lead_goal  int default null,
  p_lead_goal_month int default null,
  p_start      date default null,
  p_end        date default null,
  p_managers   bigint[] default '{}',
  p_names      text default 'all',
  p_ids        bigint[] default '{}',
  p_complete   boolean default true
)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  a         public.projects;
  v_id      bigint;
  v_active  bigint := (select id from public.project_statuses where name = 'Active');
  v_done    bigint := (select id from public.project_statuses where name = 'Completed');
  v_moved_r bigint := public.moved_result('DBDV');
  v_stamp   text := public.note_stamp();
  v_name    text := nullif(btrim(coalesce(p_name, '')), '');
  v_label   text;
  v_from    text;
  l         public.leads;
  v_new     bigint;
  v_moved   int := 0;
  v_skipped int := 0;
  v_user    public.users;
begin
  if not public.is_admin() then
    raise exception 'Only administrators renew projects' using errcode = '42501';
  end if;
  select * into a from public.projects where id = p_project and deleted_at is null for update;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  if public.project_type_code(a.id) is distinct from 'DBDV' then
    raise exception 'Only a lead (DB dev) project is renewed; its appointment project carries on as it is' using errcode = '22023';
  end if;
  if v_name is null then
    raise exception 'Name the new project' using errcode = '22023';
  end if;
  if length(v_name) > 120 then
    raise exception 'A project name is 120 characters at most' using errcode = '22023';
  end if;
  if p_names not in ('all', 'picked', 'none') then
    raise exception 'Choose which names to carry over' using errcode = '22023';
  end if;
  if p_names = 'picked' and coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Pick the names to carry over' using errcode = '22023';
  end if;
  if p_lead_goal is not null and p_lead_goal < 0 or p_lead_goal_month is not null and p_lead_goal_month < 0 then
    raise exception 'A goal is a number of leads' using errcode = '22023';
  end if;
  if p_start is not null and p_end is not null and p_end < p_start then
    raise exception 'The end date is before the start date' using errcode = '22023';
  end if;

  -- Everything ProjectA was set up with, but its name, dates, goals and status.
  insert into public.projects (
    company_id, name, project_type_id, status_id, description, client_name, contact_name, contact_title, email,
    address, city, state, zip, phone, fax, website, timezone_id, start_date, end_date, appt_project_id,
    lead_rate, appointment_rate, confirmation_rate, delivery_link_only, special_goal, special_rate,
    lead_goal, lead_goal_month, renewed_from_id)
  values (
    a.company_id, v_name, a.project_type_id, v_active, a.description, a.client_name, a.contact_name, a.contact_title, a.email,
    a.address, a.city, a.state, a.zip, a.phone, a.fax, a.website, a.timezone_id, coalesce(p_start, current_date), p_end, a.appt_project_id,
    a.lead_rate, a.appointment_rate, a.confirmation_rate, a.delivery_link_only, a.special_goal, a.special_rate,
    p_lead_goal, p_lead_goal_month, a.id)
  returning id into v_id;

  -- Its client's people on it, as on ProjectA.
  insert into public.project_assignments (project_id, cl_user_id)
  select distinct v_id, cl_user_id from public.project_assignments where project_id = a.id and cl_user_id is not null;

  v_label := public.project_label(v_id);
  v_from := public.project_label(a.id);
  -- The viable names still to call on ProjectA: each keeps its call result there.
  for l in
    select x.* from public.leads x join public.call_results r on r.id = x.result_id
     where x.project_id = a.id and x.deleted_at is null and x.stage = 'dbdev' and r.viable
       and (p_names = 'all' or (p_names = 'picked' and x.id = any(p_ids)))
     order by x.id
       for update of x
  loop
    v_new := public.copy_name(l.id, v_id, l.result_id, null, v_stamp || ' Carried over from ' || v_from || ' (renewal).');
    -- ProjectB's own from here: the leads it makes count for ProjectB, not ProjectA.
    update public.leads set source_project_id = v_id where id = v_new;
    update public.leads set result_id = v_moved_r, resolved_at = now() where id = l.id;
    perform public.add_name_note(l.id, v_stamp || ' Moved to ' || v_label || ' (renewal).');
    v_moved := v_moved + 1;
  end loop;
  if p_names = 'picked' then
    v_skipped := (select count(distinct x) from unnest(p_ids) x) - v_moved;
  end if;

  -- The managers chosen, once the names are there: each is told the project and how many names it has.
  for v_user in select * from public.users where id = any(coalesce(p_managers, '{}')) loop
    if v_user.role not in ('admin', 'manager', 'agent') or v_user.status is distinct from 'active' then
      raise exception '% can''t work a project', coalesce(nullif(concat_ws(' ', v_user.first_name, v_user.last_name), ''), v_user.email)
        using errcode = '22023';
    end if;
    insert into public.project_assignments (project_id, ae_user_id) values (v_id, v_user.id);
  end loop;

  if v_moved > 0 then
    perform public.distribute_names(v_id);
  end if;
  if p_complete then
    update public.projects set status_id = v_done where id = a.id;
  end if;
  return jsonb_build_object('project_id', v_id, 'moved', v_moved, 'skipped', v_skipped, 'completed', p_complete);
end $$;
revoke execute on function public.renew_project(bigint, text, int, int, date, date, bigint[], text, bigint[], boolean) from public, anon;
grant execute on function public.renew_project(bigint, text, int, int, date, date, bigint[], text, bigint[], boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- 4. Managers told
-- ---------------------------------------------------------------------------

insert into public.alert_rules (name, trigger, channel, recipients, enabled)
select v.name, v.trigger, 'inapp', null, true
  from (values ('Project assigned to you', 'project_assigned'), ('Project paused or completed', 'project_status')) v(name, trigger)
 where not exists (select 1 from public.alert_rules r where r.trigger = v.trigger);

/** How many names on a project are still to call. */
create or replace function public.names_to_call(p_project bigint)
returns bigint
language sql stable security definer set search_path = public as $$
  select count(*) from public.leads x join public.call_results r on r.id = x.result_id
   where x.project_id = p_project and x.deleted_at is null and r.viable
$$;
revoke execute on function public.names_to_call(bigint) from public, anon, authenticated;

/** A manager put on a project: which one, and how many names it has to call. */
create or replace function public.tg_project_assignment_notify()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.ae_user_id is null or (tg_op = 'UPDATE' and new.ae_user_id is not distinct from old.ae_user_id) then
    return null;
  end if;
  perform public.notify_users(
    array[new.ae_user_id], 'system',
    'Project assigned to you: ' || coalesce(public.project_label(new.project_id), 'a project'),
    format('%s names to call%s', to_char(public.names_to_call(new.project_id), 'FM999,999,990'),
           coalesce(' · Assigned by ' || public.actor_name(), '')),
    '/projects/' || new.project_id,
    'project_assigned');
  return null;
end $$;
revoke execute on function public.tg_project_assignment_notify() from public, anon, authenticated;
drop trigger if exists project_assignment_notify on public.project_assignments;
create trigger project_assignment_notify after insert or update of ae_user_id on public.project_assignments
  for each row execute function public.tg_project_assignment_notify();

/** A project paused, completed or active again: its managers are told. */
create or replace function public.tg_project_status_notify()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_status text := (select name from public.project_statuses where id = new.status_id);
  v_was    text := (select name from public.project_statuses where id = old.status_id);
begin
  if new.status_id is not distinct from old.status_id or new.deleted_at is not null
     or v_status not in ('Paused', 'Completed', 'Active') or (v_status = 'Active' and v_was = 'Draft') then
    return null;
  end if;
  perform public.notify_users(
    array(select distinct ae_user_id from public.project_assignments where project_id = new.id and ae_user_id is not null),
    'system',
    format('Project %s: %s', case v_status when 'Active' then 'active again' else lower(v_status) end, public.project_label(new.id)),
    concat_ws(' · ',
      case v_status when 'Paused' then 'Its names are off your call lists until it is active again'
                    when 'Completed' then 'Its names are off your call lists'
                    else format('%s names to call', to_char(public.names_to_call(new.id), 'FM999,999,990')) end,
      'By ' || public.actor_name()),
    '/projects/' || new.id,
    'project_status');
  return null;
end $$;
revoke execute on function public.tg_project_status_notify() from public, anon, authenticated;
drop trigger if exists project_status_notify on public.projects;
create trigger project_status_notify after update of status_id on public.projects
  for each row execute function public.tg_project_status_notify();

-- Names shared out to a manager say which project.
create or replace function public.notify_lead_assignment(p_user bigint, p_hot boolean, p_n bigint, p_lead bigint, p_name text, p_project bigint)
returns void
language plpgsql security definer set search_path = public as $$
begin
  perform public.notify_users(
    array[p_user], 'lead',
    case when p_n = 1 then (case when p_hot then 'Hot lead assigned to you: ' else 'Lead assigned to you: ' end) || coalesce(p_name, 'a lead')
         else p_n || case when p_hot then ' hot leads' else ' leads' end || ' assigned to you' end,
    concat_ws(' · ', 'On ' || public.project_label(p_project), coalesce('Assigned by ' || public.actor_name(), 'Assigned automatically')),
    case when p_n = 1 then '/leads/' || p_lead || coalesce('?project=' || p_project, '')
         when p_project is not null then '/work/' || p_project
         else '/work' end,
    case when p_hot then 'hot_lead' else 'lead_assigned' end);
end $$;

-- ---------------------------------------------------------------------------
-- 5. A lead with its X-date corrected comes off a client's list too
-- ---------------------------------------------------------------------------

/**
 * Names taken off a client's lists, with why: a client's people for their
 * own projects' names (they can't record calls), staff for any. Each takes
 * the result for the reason on its kind of project; a note on each says who
 * and why, and the note given is kept on the list. A lead in the pipeline
 * (on the appointment project, an X-date corrected or not) comes off as
 * Lead-Removed, still in the reports (Sean's client, Oct 2026: scrubbing the
 * leads they no longer want called for appointments). Names with an
 * appointment, or made a lead on a DB dev project with no appointment
 * project, are left as they are and counted: those go through the people
 * who set them.
 */
create or replace function public.mark_names(p_ids bigint[], p_reason text, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_role    text := public.app_role();
  v_company bigint := public.app_company_id();
  v_me      bigint := public.app_user_id();
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_label   text := case p_reason when 'deletion' then 'Deletion' when 'dont_call' then 'Don''t call' else 'Current customer' end;
  v_stamp   text := public.note_stamp();
  v_by      text;
  r         public.call_results;
  l         record;
  v_marked  int := 0;
  v_kept    int := 0;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'client') then
    raise exception 'Only a client''s people, administrators and account managers can take names off' using errcode = '42501';
  end if;
  if p_reason is null or p_reason not in ('deletion', 'dont_call', 'current_customer') then
    raise exception 'Choose why these names come off' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Choose the names to take off' using errcode = '22023';
  end if;
  if array_length(p_ids, 1) > 5000 then
    raise exception 'Take off up to 5,000 names at a time' using errcode = '22023';
  end if;
  select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''), email) into v_by from public.users where id = v_me;

  for l in
    select x.id, x.project_id, x.result_id, p.company_id, public.project_type_code(x.project_id) as kind, cr.effect
      from public.leads x
      join public.projects p on p.id = x.project_id
      join public.call_results cr on cr.id = x.result_id
     where x.id = any(p_ids) and x.deleted_at is null
     order by x.id
       for update of x
  loop
    if v_role = 'client' and l.company_id is distinct from v_company then
      raise exception 'Those names are not on your lists' using errcode = '42501';
    end if;
    if l.effect not in ('none', 'pending', 'correct_xdate') then
      v_kept := v_kept + 1;
      continue;
    end if;
    select * into r from public.call_results
     where project_type = l.kind and applies_to = 'name' and client_removal = p_reason
     order by sort_order limit 1;
    if not found then
      raise exception 'No call result to mark these names with' using errcode = 'P0002';
    end if;
    if l.result_id is distinct from r.id then
      update public.leads
         set result_id = r.id,
             status_id = coalesce((select s.id from public.lead_statuses s where s.code = r.status_code), status_id),
             resolved_at = coalesce(resolved_at, now())
       where id = l.id;
    end if;
    perform public.add_name_note(l.id, v_stamp || ' Taken off the list by ' || coalesce(v_by, 'the client') || ': ' || v_label
                                      || coalesce(' (' || v_note || ')', '') || '.');
    update public.client_removals
       set reason = p_reason, note = coalesce(v_note, note), removed_by = v_me
     where lead_id = l.id;
    v_marked := v_marked + 1;
  end loop;
  return jsonb_build_object('marked', v_marked, 'kept', v_kept, 'reason', v_label);
end $$;
revoke execute on function public.mark_names(bigint[], text, text) from public, anon;
grant execute on function public.mark_names(bigint[], text, text) to authenticated;

-- ==============================================================================================================
-- 20261218100000_sic_six_digit.sql
-- ==============================================================================================================

-- One form for a 6-digit SIC code (Oct 2026). The client's SIC sheets (the
-- old one, and the 2-, 4- and 6-digit tabs they mean to load now) write
-- 422505; SalesGenie writes 4225-05. Both are one code, so a lead from a
-- SalesGenie list finds its description in the list, and the list doesn't
-- gain a dashed copy of every code an import brings. The code is kept
-- without its dash, as the client's sheets have it.
--
--   1. sic_pad(code): also "4225-05" is 422505, and "111-01" (a lost zero) 011101.
--   2. The codes on file put right, as the leading zeros were: the master list
--      (the dashless code taking the description when it has none), the leads
--      and the clients; the dashed ones then go. Triggers are off while it
--      runs, so no lead reads as updated and nobody is told of anything.
--
-- The triggers that call sic_pad() on every write are already there
-- (…_sic_leading_zeros.sql). Safe to run more than once.

create or replace function public.sic_pad(c text) returns text
language sql immutable parallel safe set search_path = '' as $$
  select case
    when c ~ '^\d{4}-\d{2}$' then replace(c, '-', '')
    when c ~ '^\d{3}-\d{2}$' then '0' || replace(c, '-', '')
    when c ~ '^(\d|\d{3}|\d{5}|\d{7})$' then '0' || c
    else c
  end
$$;

begin;
set local session_replication_role = replica;

insert into public.sic_codes (code, description)
select distinct on (public.sic_pad(code)) public.sic_pad(code), description
  from public.sic_codes where public.sic_pad(code) <> code
 order by public.sic_pad(code), description nulls last
on conflict (code) do update set description = coalesce(public.sic_codes.description, excluded.description);

update public.leads set sic_code = public.sic_pad(sic_code) where sic_code is not null and public.sic_pad(sic_code) <> sic_code;
update public.companies set sic_code = public.sic_pad(sic_code) where sic_code is not null and public.sic_pad(sic_code) <> sic_code;

delete from public.sic_codes where public.sic_pad(code) <> code;
commit;

-- An import says how many of its names were on the other clients' projects it was checked against
-- (Oct 2026: an Agency Group's clients in a territory, chosen on the import).
alter table public.import_batches add column if not exists other_count int not null default 0;

-- ==============================================================================================================
-- 20261219100000_clients_tiles_by_rep.sql
-- ==============================================================================================================

-- The Clients page's tiles for one Sales Rep's clients (Oct 2026): picking a
-- Sales Rep in the Client Accounts list counts the Leads and Appointments
-- tiles (totals and charts) for the clients tied to that rep.
--
--   clients_totals(p_companies)        as before, for those clients only
--   clients_chart(p_from, p_to, p_companies)   when given; all active ones when null
--
-- The old signatures go (a call with fewer arguments takes the default).
-- Safe to run more than once.

drop function if exists public.clients_totals();
create or replace function public.clients_totals(p_companies bigint[] default null)
returns table(leads_active bigint, leads_resolved bigint, appointments bigint, invalid_appointments bigint)
language sql stable set search_path = public as $$
  select count(*) filter (where c.stage = 'appt' and c.viable),
         count(*) filter (where c.stage = 'appt' and not c.viable),
         count(*) filter (where c.effect in ('appointment', 'confirm')),
         count(*) filter (where c.effect = 'appointment_invalid')
    from public.lead_classes c
    join public.projects p on p.id = c.project_id
    join public.companies co on co.id = p.company_id
   where co.status = 'active'
     and (p_companies is null or co.id = any(p_companies));
$$;
revoke execute on function public.clients_totals(bigint[]) from public, anon;
grant execute on function public.clients_totals(bigint[]) to authenticated;

drop function if exists public.clients_chart(date, date);
create or replace function public.clients_chart(p_from date, p_to date, p_companies bigint[] default null)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz text := public.business_tz();
  v_lo timestamptz;
  v_hi timestamptz;
  v    jsonb;
begin
  if not public.is_manager() then
    raise exception 'Only administrators and managers see every client''s production' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 731 then
    raise exception 'Choose up to two years' using errcode = '22023';
  end if;
  v_lo := p_from::timestamp at time zone v_tz;
  v_hi := (p_to + 1)::timestamp at time zone v_tz;

  with ev as (
    select (pe.created_at at time zone v_tz)::date as d, extract(hour from pe.created_at at time zone v_tz)::int as h, pe.kind
      from public.pay_events pe
      join public.projects p on p.id = pe.project_id and p.deleted_at is null
      join public.companies co on co.id = p.company_id and co.deleted_at is null and co.status = 'active'
     where pe.kind in ('lead', 'appointment') and not pe.is_chargeback
       and pe.created_at >= v_lo and pe.created_at < v_hi
       and (p_companies is null or co.id = any(p_companies))
  )
  select jsonb_build_object(
    'days', coalesce((
      select jsonb_agg(jsonb_build_object('day', d, 'leads', l, 'appts', a) order by d)
        from (select d, count(*) filter (where kind = 'lead') as l, count(*) filter (where kind = 'appointment') as a
                from ev group by d) q), '[]'::jsonb),
    'hours', case when p_from = p_to then coalesce((
      select jsonb_agg(jsonb_build_object('hour', h, 'leads', l, 'appts', a) order by h)
        from (select h, count(*) filter (where kind = 'lead') as l, count(*) filter (where kind = 'appointment') as a
                from ev group by h) q), '[]'::jsonb) end)
  into v;
  return v;
end $$;
revoke execute on function public.clients_chart(date, date, bigint[]) from public, anon;
grant execute on function public.clients_chart(date, date, bigint[]) to authenticated;

-- ==============================================================================================================
-- 20261220100000_projects_tiles_by_rep.sql
-- ==============================================================================================================

-- The Projects page's tiles for the clients picked on its list (Oct 2026):
-- a Sales Rep (or a client, or an Agency Group) counts the tiles for those
-- clients' projects, as the Clients page's tiles follow its Sales Rep.
--
--   projects_lead_stats(p_companies)   as before, for those clients'
--                                      projects only; every project when null
--
-- The old signature goes (a call with no arguments takes the default).
-- Safe to run more than once.

drop function if exists public.projects_lead_stats();
create or replace function public.projects_lead_stats(p_companies bigint[] default null)
returns table(project_id bigint, names bigint, names_left bigint, leads bigint, leads_active bigint, developed bigint)
language sql stable set search_path = public as $$
  with ps as (
    select p.id from public.projects p where p_companies is null or p.company_id = any(p_companies)
  ), scoped as (
    -- A project's names: those on it, and those it sent on to another (as lead_stats() has them).
    select ps.id as pid, c.*, (c.project_id = ps.id) as here
      from ps join public.lead_classes c
        on c.project_id = ps.id or (c.source_project_id = ps.id and c.source_project_id <> c.project_id)
  )
  select pid, count(*),
         count(*) filter (where here and stage = 'dbdev' and viable),
         count(*) filter (where stage = 'appt'),
         count(*) filter (where stage = 'appt' and viable),
         count(*) filter (where developed)
    from scoped group by pid
  union all
  -- Every lead once, whichever projects it passed through (of those clients, when given).
  select null, count(*),
         count(*) filter (where stage = 'dbdev' and viable),
         count(*) filter (where stage = 'appt'),
         count(*) filter (where stage = 'appt' and viable),
         count(*) filter (where developed)
    from public.lead_classes c
   where p_companies is null or c.project_id in (select id from ps);
$$;
revoke execute on function public.projects_lead_stats(bigint[]) from public, anon;
grant execute on function public.projects_lead_stats(bigint[]) to authenticated;

-- ==============================================================================================================
-- 20261221100000_message_links.sql
-- ==============================================================================================================

-- A message's link in the conversation (Oct 2026): a question about an
-- appointment (and any message sent with a link, such as an appointment
-- update) links to its lead, and the inbox showed it, but a conversation's
-- messages left the link out, so the chat showed the message with nothing to
-- open. message_json() now carries it; the chat shows it under the message.
--
-- Safe to run more than once.

create or replace function public.message_json(m public.notifications, p_me bigint) returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'id', m.id, 'mine', m.sender_id = p_me, 'title', m.title, 'body', m.body, 'link', m.link, 'reply_to', m.reply_to,
    'read_at', m.read_at, 'created_at', m.created_at, 'quote_id', m.quote_id, 'attachment', m.attachment,
    'quote', (select jsonb_build_object('id', q.id, 'mine', q.sender_id = p_me, 'body', q.body, 'title', q.title, 'kind', q.attachment ->> 'kind')
                from public.notifications q where q.id = m.quote_id),
    'reactions', coalesce((select jsonb_agg(jsonb_build_object('emoji', r.emoji, 'user_id', r.user_id) order by r.created_at)
                             from public.message_reactions r where r.message_id = m.id), '[]'::jsonb))
$$;
revoke execute on function public.message_json(public.notifications, bigint) from public, anon, authenticated;

-- ==============================================================================================================
-- 20261222100000_invalid_appointment_callback.sql
-- ==============================================================================================================

-- An invalid appointment, and a call back next year (Oct 2026, the client's
-- scenario): a manager's appointment turns out invalid when confirmed (the
-- prospect has no time this year, call next year). It is marked
-- Appointment-Invalid: the appointment is invalid, the manager's pay charged
-- back, the client not billed. The name should come up again next year
-- without undoing this year's figures.
--
--   1. The reports count an invalid appointment from the appointment itself
--      (appointments.invalid_at), not from the lead's latest call result, so
--      the lead's result can move on: lead_classes.appt_invalid, used by
--      lead_stats(), clients_totals() and client_dashboard(). (The client's
--      appointment list, activity, production and pay read the appointment
--      or the pay already.)
--   2. leads.call_back_on: a name kept off the call lists until that day
--      (call_list(), call_list_options(), work_projects()); given another
--      result in the meantime, it is called as usual again.
--   3. call_back_later(lead, day, note): an invalid appointment's name back
--      on its project's list on that day, as Lead-Not Shopping, a call
--      recorded with why (no pay), and a reminder to its account manager.
--
-- Safe to run more than once.

alter table public.leads add column if not exists call_back_on date;
create index if not exists leads_call_back_on on public.leads (call_back_on) where call_back_on is not null;
create index if not exists appointments_invalid_lead on public.appointments (lead_id) where invalid_at is not null;

-- ---------------------------------------------------------------------------
-- 1. An invalid appointment counted from the appointment
-- ---------------------------------------------------------------------------

create or replace view public.lead_classes with (security_invoker = true) as
  select l.id, l.project_id, l.source_project_id, l.stage,
         r.name as result, r.project_type as result_type, r.viable, r.callable, r.effect, r.sort_order,
         d.name as dbdv_result,
         -- DB dev developed it: it came on from a DB dev project, or its DB dev result says so.
         ((l.stage = 'appt' and l.source_project_id is not null and l.source_project_id <> l.project_id)
           or coalesce(d.effect in ('promote', 'appointment', 'confirm', 'appointment_invalid') or d.name = 'Lead-Invalid', false)) as developed,
         -- It had an appointment that was invalid: its result says so, or (its result moved on since) the appointment does.
         (r.effect = 'appointment_invalid'
           or exists (select 1 from public.appointments ap where ap.lead_id = l.id and ap.invalid_at is not null and ap.deleted_at is null)) as appt_invalid
    from public.leads l
    join public.call_results r on r.id = l.result_id
    left join lateral (
      select cr.name, cr.effect
        from public.call_results cr
       where cr.project_type = 'DBDV' and nullif(btrim(l.call_result_dbdv), '') is not null
         and (lower(cr.name) = lower(btrim(l.call_result_dbdv)) or lower(btrim(l.call_result_dbdv)) = any (cr.aliases))
       order by cr.sort_order
       limit 1
    ) d on true;
revoke all on public.lead_classes from anon;
grant select on public.lead_classes to authenticated;

create or replace function public.lead_stats(p_company_id bigint default null, p_project_id bigint default null)
returns table(project_id bigint, names bigint, names_left bigint, leads_active bigint, leads_resolved bigint, developed bigint, appointments bigint, invalid_appointments bigint)
language sql stable set search_path = public as $$
  with ps as (
    select p.id from public.projects p
     where (p_project_id is not null and p.id = p_project_id)
        or (p_project_id is null and p_company_id is not null and p.company_id = p_company_id)
  ), scoped as (
    -- A project's names: those on it, and those it sent on to another.
    select ps.id as pid, c.*, (c.project_id = ps.id) as here
      from ps join public.lead_classes c
        on c.project_id = ps.id or (c.source_project_id = ps.id and c.source_project_id <> c.project_id)
  ), per as (
    select pid,
           count(*) as names,
           count(*) filter (where here and stage = 'dbdev' and viable) as names_left,
           count(*) filter (where stage = 'appt' and viable) as leads_active,
           count(*) filter (where stage = 'appt' and not viable) as leads_resolved,
           count(*) filter (where developed) as developed,
           count(*) filter (where effect in ('appointment', 'confirm')) as appointments,
           count(*) filter (where appt_invalid) as invalid_appointments
      from scoped group by pid
  )
  select ps.id, coalesce(per.names, 0), coalesce(per.names_left, 0), coalesce(per.leads_active, 0), coalesce(per.leads_resolved, 0),
         coalesce(per.developed, 0), coalesce(per.appointments, 0), coalesce(per.invalid_appointments, 0)
    from ps left join per on per.pid = ps.id
  union all
  select null, count(*),
         count(*) filter (where c.stage = 'dbdev' and c.viable),
         count(*) filter (where c.stage = 'appt' and c.viable),
         count(*) filter (where c.stage = 'appt' and not c.viable),
         count(*) filter (where c.developed),
         count(*) filter (where c.effect in ('appointment', 'confirm')),
         count(*) filter (where c.appt_invalid)
    from public.lead_classes c
   where p_project_id is null and p_company_id is not null and c.project_id in (select id from ps)
     and c.result not in ('Moved', 'Lead-Moved')
  -- The client's total only when a client was asked for (an aggregate otherwise still answers, with zeros).
  having p_project_id is null and p_company_id is not null;
$$;

create or replace function public.clients_totals(p_companies bigint[] default null)
returns table(leads_active bigint, leads_resolved bigint, appointments bigint, invalid_appointments bigint)
language sql stable set search_path = public as $$
  select count(*) filter (where c.stage = 'appt' and c.viable),
         count(*) filter (where c.stage = 'appt' and not c.viable),
         count(*) filter (where c.effect in ('appointment', 'confirm')),
         count(*) filter (where c.appt_invalid)
    from public.lead_classes c
    join public.projects p on p.id = c.project_id
    join public.companies co on co.id = p.company_id
   where co.status = 'active'
     and (p_companies is null or co.id = any(p_companies));
$$;
revoke execute on function public.clients_totals(bigint[]) from public, anon;
grant execute on function public.clients_totals(bigint[]) to authenticated;

create or replace function public.client_dashboard(p_from date default null, p_company_id bigint default null)
returns jsonb
language sql stable set search_path = public as $$
  with z as (
    select public.business_tz() as tz
  ), p as (
    select pr.id, pr.name, t.code as type from public.projects pr
      left join public.project_types t on t.id = pr.project_type_id
     where pr.deleted_at is null and (p_company_id is null or pr.company_id = p_company_id)
  ), l as (
    -- A lead: a name at the appointment stage, dated by when it became one; and whether it had an appointment found invalid.
    select le.id, le.project_id, le.source_project_id, r.effect, le.appt_created_date, le.promoted_at, le.lead_date, le.created_at,
           exists (select 1 from public.appointments ap where ap.lead_id = le.id and ap.invalid_at is not null and ap.deleted_at is null) as had_invalid
      from public.leads le join public.call_results r on r.id = le.result_id
     where le.stage = 'appt'
       and (le.project_id in (select id from p) or le.source_project_id in (select id from p))
  ), lp as (
    select l.* from l, z
     where p_from is null or coalesce(l.promoted_at, l.lead_date, l.created_at) >= (p_from::timestamp at time zone z.tz)
  ), a as (
    -- An appointment: a name whose result is one (set, confirmed or invalid), or whose appointment was found invalid
    -- (its result moved on since: called back next year), once each, dated by when it was set.
    select l.id, l.effect, l.had_invalid,
           (select public.appointment_update_status(ap.client_result, ap.appt_date, ap.appt_time) from public.appointments ap
             where ap.lead_id = l.id and ap.deleted_at is null order by ap.created_at desc, ap.id desc limit 1) as shown
      from l, z
     where l.project_id in (select id from p)
       and (l.effect in ('appointment', 'confirm', 'appointment_invalid') or l.had_invalid)
       and (p_from is null or coalesce(l.appt_created_date, l.promoted_at, l.lead_date, l.created_at) >= (p_from::timestamp at time zone z.tz))
  ), ar as (
    select case when effect = 'appointment_invalid' or (had_invalid and effect not in ('appointment', 'confirm')) then 'invalid'
                else coalesce(shown, 'pending_appointment') end as result from a
  )
  select jsonb_build_object(
    'leads', (select count(*) from lp where lp.project_id in (select id from p)),
    'projects', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.name,
                                   'leads', (select count(*) from lp where lp.source_project_id = p.id or lp.project_id = p.id))
                                 order by p.name), '[]'::jsonb)
                   from p where p.type = 'DBDV'),
    'appts', (select count(*) from a),
    'results', (select jsonb_object_agg(k, (select count(*) from ar where ar.result = k))
                  from unnest(array['pending_appointment', 'no_status', 'valid', 'valid_quoting', 'valid_not_quoting',
                                    'quoted_not_sold', 'sold', 'invalid', 'reschedule']) k)
  );
$$;

-- ---------------------------------------------------------------------------
-- 2. Kept off the call lists until the day to call back
-- ---------------------------------------------------------------------------

/** The business's today: what "until the day" is measured by. */
create or replace function public.business_today() returns date
language sql stable set search_path = public as $$
  select (now() at time zone public.business_tz())::date
$$;
grant execute on function public.business_today() to authenticated;

-- The call lists and their counts leave out a name until its call-back day. Each of these functions picks the names
-- to call as "r.viable and r.callable"; that is widened here, once, wherever it appears in them.
do $$
declare
  f text;
  def text;
begin
  foreach f in array array['call_list', 'call_list_options', 'work_projects'] loop
    select pg_get_functiondef(p.oid) into def from pg_proc p where p.proname = f and p.pronamespace = 'public'::regnamespace;
    if def is null or def like '%call_back_on%' then
      continue;
    end if;
    execute replace(def, 'r.viable and r.callable', 'r.viable and r.callable and (l.call_back_on is null or l.call_back_on <= public.business_today())');
  end loop;
end $$;

-- Given another result in the meantime (a call, Result Change), the name is called as usual again.
create or replace function public.tg_leads_call_back() returns trigger
language plpgsql set search_path = public as $$
begin
  if new.result_id is distinct from old.result_id and new.call_back_on is not distinct from old.call_back_on then
    new.call_back_on := null;
  end if;
  return new;
end $$;
drop trigger if exists leads_call_back on public.leads;
create trigger leads_call_back before update of result_id on public.leads
  for each row execute function public.tg_leads_call_back();

-- ---------------------------------------------------------------------------
-- 3. Call back next year
-- ---------------------------------------------------------------------------

/**
 * An invalid appointment's name back on its project's call list on `p_on`
 * (next year, say): as Lead-Not Shopping, a call recorded with why (no pay:
 * the appointment stays invalid, its pay charged back, in this year's
 * figures), a line in its notes, and a reminder to its account manager that
 * morning. Those who can work the name, administrators and managers.
 */
create or replace function public.call_back_later(p_lead bigint, p_on date, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me    bigint := public.app_user_id();
  l       public.leads;
  r       public.call_results;
  v_note  text := nullif(btrim(coalesce(p_note, '')), '');
  v_today date := public.business_today();
  v_line  text;
begin
  if v_me is null or not (public.is_manager() or public.can_work_lead(p_lead)) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;
  select * into l from public.leads where id = p_lead and deleted_at is null for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  if l.stage is distinct from 'appt'
     or not exists (select 1 from public.appointments ap where ap.lead_id = l.id and ap.invalid_at is not null and ap.deleted_at is null) then
    raise exception 'Only a lead whose appointment was found invalid is called back this way' using errcode = '22023';
  end if;
  if exists (select 1 from public.appointments ap where ap.lead_id = l.id and ap.invalid_at is null and ap.deleted_at is null and ap.appt_date >= v_today) then
    raise exception 'This lead has an appointment still to come' using errcode = '22023';
  end if;
  if p_on is null or p_on <= v_today then
    raise exception 'Choose a day after today to call back' using errcode = '22023';
  end if;
  if p_on > v_today + 731 then
    raise exception 'Choose a day within two years' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 300 then
    raise exception 'Keep the note under 300 characters' using errcode = '22023';
  end if;
  select * into r from public.call_results where id = public.call_result_from_text('APPT', 'Lead-Not Shopping');
  if not found then
    raise exception 'No call result to give it' using errcode = 'P0002';
  end if;

  v_line := 'Call back on ' || to_char(p_on, 'FMMon FMDD, YYYY') || coalesce(': ' || v_note, '') || ' (the appointment stays invalid).';
  insert into public.call_records (lead_id, project_id, user_id, call_result, notes, result_id, stage, call_date)
  values (l.id, l.project_id, v_me, r.name, v_line, r.id, l.stage, now());
  update public.leads set
    result_id        = r.id,
    call_result_appt = r.name,
    status_id        = coalesce((select s.id from public.lead_statuses s where s.code = r.status_code), status_id),
    resolved_at      = null,
    call_back_on     = p_on,
    date_last_worked = now()
  where id = l.id;
  perform public.add_name_note(l.id, public.note_stamp() || ' ' || v_line);
  -- Its account manager reminded that morning (whoever has the name then, else who asked).
  insert into public.reminders (lead_id, user_id, remind_at, note)
  values (l.id, coalesce(l.assigned_user_id, v_me), (p_on + time '09:00') at time zone public.business_tz(),
          left('Call back: ' || coalesce(v_note, 'their appointment was invalid last time'), 300));
  return jsonb_build_object('call_back_on', p_on, 'result', r.name);
end $$;
revoke execute on function public.call_back_later(bigint, date, text) from public, anon;
grant execute on function public.call_back_later(bigint, date, text) to authenticated;

-- ==============================================================================================================
-- 20261223100000_list_builder_six_digit.sql
-- ==============================================================================================================

-- List Builder: the 6-digit codes (Sean, Oct 2026). The SIC list now holds
-- the client's 6-digit sheet; the List Builder's tree opens each industry
-- (4 digits) into its 6-digit codes from it, for clients, staff and the
-- prospects who fill in a request from a link (no sign-in). One call, read
-- after the page is up.
--
--   sic_details()   [[code, description], …]: every 6-digit code in the SIC list
--
-- Safe to run more than once.

create or replace function public.sic_details()
returns jsonb
language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_array(s.code, btrim(s.description)) order by s.code), '[]'::jsonb)
    from public.sic_codes s
   where s.code ~ '^\d{6}$' and nullif(btrim(s.description), '') is not null;
$$;
revoke execute on function public.sic_details() from public;
grant execute on function public.sic_details() to anon, authenticated;

-- ==============================================================================================================
-- 20261224100000_lead_viable.sql
-- ==============================================================================================================

-- Lead-Viable (Sean, Oct 2026): "Lead-No Contact" read to clients as if the
-- business had never been called for them. A lead now starts at Lead-No
-- Contact and, once a manager has called it and it has not become an
-- appointment or been resolved, it is Lead-Viable: the leads called at least
-- once told from those not called yet, for clients, administrators and the
-- managers' call list filters.
--
--   Lead-Viable          new appointment-setting result: stays on the call
--                        lists, as Lead-No Contact does. Not a button: given
--                        by the call.
--   leads_lead_viable    a call recorded as Lead-No Contact, Lead-Left
--                        Message or Lead-Email (what happened on it, kept in
--                        the call history) leaves the lead at Lead-Viable.
--                        Results that say something of their own
--                        (Lead-ClientList, Lead-Not Shopping, Lead-Corrected)
--                        stay as titled; a result set without a call (Result
--                        Change, an import, a promotion, a transfer) is left
--                        as it is.
--   The leads already called: those at Lead-Left Message or Lead-Email, and
--   those at Lead-No Contact with a call on them at appointment setting,
--   become Lead-Viable (once).
--
-- Safe to run more than once.

insert into public.call_results
  (project_type, name, sort_order, viable, callable, sort_last, effect, pay_kind, applies_to, status_code, action, aliases)
values
  ('APPT', 'Lead-Viable', 15, true, true, false, 'none', null, 'report', 'xdate',
   'Called at least once, not yet an appointment or resolved. Stays on active Appt project call lists (tracked by # of calls made to each name/weighted)',
   array['lead viable', 'xd-viable'])
on conflict (project_type, name) do update set
  sort_order = excluded.sort_order, viable = excluded.viable, callable = excluded.callable,
  sort_last = excluded.sort_last, effect = excluded.effect, pay_kind = excluded.pay_kind,
  applies_to = excluded.applies_to, status_code = excluded.status_code,
  action = excluded.action, aliases = excluded.aliases;

/** A lead called and still to work: a call recorded as No Contact, Left Message or Email leaves it at Lead-Viable. */
create or replace function public.tg_leads_lead_viable() returns trigger
language plpgsql set search_path = public as $$
declare
  v_viable bigint;
begin
  if new.stage is distinct from 'appt' then
    return new;
  end if;
  if not exists (select 1 from public.call_results r
                  where r.id = new.result_id and r.project_type = 'APPT' and r.name in ('Lead-No Contact', 'Lead-Left Message', 'Lead-Email')) then
    return new;
  end if;
  -- Given by a call: record_call_result() records it, in this same transaction, before it sets the result.
  if not exists (select 1 from public.call_records c
                  where c.lead_id = new.id and c.result_id = new.result_id and c.stage = 'appt' and c.call_date = now()) then
    return new;
  end if;
  select id into v_viable from public.call_results where project_type = 'APPT' and name = 'Lead-Viable';
  if v_viable is not null then
    new.result_id := v_viable;
    new.call_result_appt := 'Lead-Viable';
  end if;
  return new;
end $$;
drop trigger if exists leads_lead_viable on public.leads;
create trigger leads_lead_viable before update of result_id on public.leads
  for each row execute function public.tg_leads_lead_viable();

-- The leads already called.
update public.leads l set
  result_id = v.id,
  call_result_appt = 'Lead-Viable'
  from public.call_results r, public.call_results v
 where l.result_id = r.id and l.stage = 'appt'
   and v.project_type = 'APPT' and v.name = 'Lead-Viable'
   and r.project_type = 'APPT'
   and (r.name in ('Lead-Left Message', 'Lead-Email')
        or (r.name = 'Lead-No Contact'
            and (l.call_weight > 0 or exists (select 1 from public.call_records c where c.lead_id = l.id and c.stage = 'appt'))));

-- ==============================================================================================================
-- 20261225100000_calendar_block_repeats.sql
-- ==============================================================================================================

-- Blocked time that repeats every week (Sean, Oct 2026): a client blocks
-- out, say, every Tuesday and Thursday for the next two months (all day, or
-- a time of day), as one block, for those who don't sync a calendar.
--
--   calendar_blocks.weekdays   the days of the week it applies on (0 Sunday
--                              to 6 Saturday), from its first day to its
--                              last; none: every day between them
--
-- Safe to run more than once.

alter table public.calendar_blocks add column if not exists weekdays smallint[];
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'calendar_blocks_weekdays_check') then
    alter table public.calendar_blocks add constraint calendar_blocks_weekdays_check
      check (weekdays is null or (cardinality(weekdays) between 1 and 7 and weekdays <@ array[0, 1, 2, 3, 4, 5, 6]::smallint[]));
  end if;
end $$;

-- ==============================================================================================================
-- 20261226100000_hand_over_work.sql
-- ==============================================================================================================

-- Handing over a manager's work (Sean, Oct 2026): a manager leaves; their
-- account is disabled, nothing of theirs erased. What they did stays theirs
-- (the calls they made, the leads they developed, the appointments they set,
-- their pay and production); what was still to do goes to another manager
-- in one step.
--
--   appointments.follow_up_user_id   who follows an appointment up now (its
--                                    confirmation, the client's updates, moving
--                                    it), when not the manager who set it; the
--                                    setter (user_id) stays as it was, for the
--                                    figures and the history
--   The appointment's follow-up (confirmation alerts, To Confirm counts, who
--   may move it, work its lead, and hears of its QA, its client's updates and
--   its policy files) goes to that manager: can_work_lead, move_appointment,
--   send_appointment_reminders, work_projects, review_appointment_qa,
--   update_appointment_status, record_call_result, tg_documents_notify.
--   hand_over_work(from, to)         an administrator's hand-over: their projects
--                                    (in their place), their open names, the
--                                    appointments to follow up (to come, or in
--                                    the last 30 days), their reminders still to
--                                    go off, the clients they are Sales Rep or a
--                                    watcher for, and their prospects' links (to
--                                    an administrator or manager);
--                                    their own synced calendars come off. With
--                                    no `to`, only what they hold, counted.
--
-- Safe to run more than once.

alter table public.appointments add column if not exists follow_up_user_id bigint references public.users(id) on delete set null;
create index if not exists appointments_follow_up on public.appointments (follow_up_user_id) where follow_up_user_id is not null;

-- The follow-up: whoever was handed it, else the manager who set it. Widened in each
-- function where it says who that is, once; a function not as expected is said, not stopped.
do $$
declare
  c record;
  def text;
  fixed text;
begin
  for c in
    select * from (values
      ('can_work_lead', 'or (select a.user_id from public.appointments a', 'or (select coalesce(a.follow_up_user_id, a.user_id) from public.appointments a'),
      ('move_appointment', 'not (a.user_id = v_me or public.is_admin())', 'not (coalesce(a.follow_up_user_id, a.user_id) = v_me or public.is_admin())'),
      ('send_appointment_reminders', 'select a.user_id, a.appt_date', 'select coalesce(a.follow_up_user_id, a.user_id) as user_id, a.appt_date'),
      ('send_appointment_reminders', 'where a.user_id is not null and a.invalid_at is null', 'where coalesce(a.follow_up_user_id, a.user_id) is not null and a.invalid_at is null'),
      ('work_projects', 'a.set_project_id = p.id and a.user_id = me.uid and a.confirmed_at is null', 'a.set_project_id = p.id and coalesce(a.follow_up_user_id, a.user_id) = me.uid and a.confirmed_at is null'),
      ('review_appointment_qa', 'elsif v_appt.user_id is not null then', 'elsif coalesce(v_appt.follow_up_user_id, v_appt.user_id) is not null then'),
      ('review_appointment_qa', 'array[v_appt.user_id], ', 'array[coalesce(v_appt.follow_up_user_id, v_appt.user_id)], '),
      ('update_appointment_status', '(u.role = ''admin'' or u.id = a.user_id)', '(u.role = ''admin'' or u.id = coalesce(a.follow_up_user_id, a.user_id))'),
      ('record_call_result', '(r.applies_to = ''appointment'' and v_appt.user_id = v_me)', '(r.applies_to = ''appointment'' and coalesce(v_appt.follow_up_user_id, v_appt.user_id) = v_me)'),
      ('tg_documents_notify', 'array[l.assigned_user_id, a.user_id]', 'array[l.assigned_user_id, coalesce(a.follow_up_user_id, a.user_id)]')
    ) as t(fn, old_text, new_text)
  loop
    for def in select pg_get_functiondef(p.oid) from pg_proc p where p.proname = c.fn and p.pronamespace = 'public'::regnamespace loop
      if position(c.new_text in def) > 0 then
        continue;
      end if;
      if position(c.old_text in def) = 0 then
        raise warning 'hand-over: % does not say "%"; its follow-up is left to the manager who set the appointment', c.fn, c.old_text;
        continue;
      end if;
      fixed := replace(def, c.old_text, c.new_text);
      execute fixed;
    end loop;
  end loop;
end $$;

/**
 * Hand over a staff member's work to another (an administrator's): with no
 * `p_to`, only what they hold, counted. Returns { projects, names,
 * appointments, reminders, clients, watching, links, calendars }.
 */
create or replace function public.hand_over_work(p_from bigint, p_to bigint default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_from public.users;
  v_to   public.users;
  v_name text;
  v_since date := public.business_today() - 30;
  v_out  jsonb;
  n      int;
  v_projects int := 0;
  v_names int := 0;
  v_appts int := 0;
  v_reminders int := 0;
  v_clients int := 0;
  v_watching int := 0;
  v_links int := 0;
  v_calendars int := 0;
begin
  if not public.is_admin() then
    raise exception 'Only administrators hand over work' using errcode = '42501';
  end if;
  select * into v_from from public.users where id = p_from;
  if not found or v_from.role not in ('admin', 'manager', 'agent') then
    raise exception 'Choose a member of staff to hand over from' using errcode = '22023';
  end if;
  v_name := coalesce(nullif(btrim(concat_ws(' ', v_from.first_name, v_from.last_name)), ''), v_from.email);

  if p_to is null then
    return jsonb_build_object(
      'projects', (select count(distinct project_id) from public.project_assignments where ae_user_id = p_from),
      'names', (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
                 where l.assigned_user_id = p_from and l.deleted_at is null and (r.viable or r.effect in ('appointment', 'confirm'))),
      'appointments', (select count(*) from public.appointments a
                        where coalesce(a.follow_up_user_id, a.user_id) = p_from and a.invalid_at is null and a.deleted_at is null and a.appt_date >= v_since),
      'reminders', (select count(*) from public.reminders where user_id = p_from and sent_at is null),
      'clients', (select count(*) from public.companies where sales_rep_id = p_from and deleted_at is null),
      'watching', (select count(*) from public.client_watchers where user_id = p_from),
      'links', (select count(*) from public.list_request_links where sales_rep_id = p_from),
      'calendars', (select count(*) from public.calendar_feeds where user_id = p_from));
  end if;

  select * into v_to from public.users where id = p_to;
  if not found or v_to.role not in ('admin', 'manager', 'agent') then
    raise exception 'Choose a member of staff to hand the work to' using errcode = '22023';
  end if;
  if p_to = p_from then
    raise exception 'Choose someone else to hand the work to' using errcode = '22023';
  end if;
  if v_to.status is distinct from 'active' or v_to.deleted_at is not null then
    raise exception '% cannot take over work until their account is active',
      coalesce(nullif(btrim(concat_ws(' ', v_to.first_name, v_to.last_name)), ''), v_to.email) using errcode = '22023';
  end if;

  -- Their projects, in their place (a project the other is on already keeps just them; a client contact's link stays).
  select count(distinct project_id) into v_projects from public.project_assignments where ae_user_id = p_from;
  update public.project_assignments set ae_user_id = null
   where ae_user_id = p_from and cl_user_id is not null
     and project_id in (select project_id from public.project_assignments where ae_user_id = p_to);
  delete from public.project_assignments
   where ae_user_id = p_from and project_id in (select project_id from public.project_assignments where ae_user_id = p_to);
  update public.project_assignments set ae_user_id = p_to where ae_user_id = p_from;

  -- Their open names: still to work, or an appointment still to follow up. Resolved names keep who held them.
  update public.leads l set assigned_user_id = p_to
    from public.call_results r
   where r.id = l.result_id and l.assigned_user_id = p_from and l.deleted_at is null
     and (r.viable or r.effect in ('appointment', 'confirm'));
  get diagnostics v_names = row_count;

  -- The appointments to follow up: still to come, or in the last 30 days (the client's update, its reminders). Set by them still.
  update public.appointments a set follow_up_user_id = p_to
   where coalesce(a.follow_up_user_id, a.user_id) = p_from and a.invalid_at is null and a.deleted_at is null and a.appt_date >= v_since;
  get diagnostics v_appts = row_count;

  -- Their reminders still to go off.
  update public.reminders set user_id = p_to where user_id = p_from and sent_at is null;
  get diagnostics v_reminders = row_count;

  -- The clients they look after: to an administrator or manager (a client's Sales Rep is one); with an agent, they stay to be given out.
  if v_to.role in ('admin', 'manager') then
    update public.companies set sales_rep_id = p_to where sales_rep_id = p_from and deleted_at is null;
    get diagnostics v_clients = row_count;
    insert into public.client_watchers (company_id, user_id, by_email)
    select company_id, p_to, by_email from public.client_watchers where user_id = p_from
    on conflict (company_id, user_id) do nothing;
    delete from public.client_watchers where user_id = p_from;
    get diagnostics v_watching = row_count;
    update public.list_request_links set sales_rep_id = p_to where sales_rep_id = p_from;
    get diagnostics v_links = row_count;
  end if;

  -- Their own calendars, synced into the projects': their busy times no longer keep appointments off.
  delete from public.calendar_feeds where user_id = p_from;
  get diagnostics v_calendars = row_count;

  v_out := jsonb_build_object('projects', v_projects, 'names', v_names, 'appointments', v_appts, 'reminders', v_reminders,
    'clients', v_clients, 'watching', v_watching, 'links', v_links, 'calendars', v_calendars);

  -- The one taking over hears what is now theirs.
  if v_projects + v_names + v_appts + v_reminders + v_clients + v_watching + v_links > 0 then
    perform public.notify_users(array[p_to], 'lead', left('You have taken over ' || v_name || '''s work', 160),
      left(concat_ws(' · ',
        case when v_projects > 0 then v_projects || ' project' || case when v_projects = 1 then '' else 's' end end,
        case when v_names > 0 then v_names || ' name' || case when v_names = 1 then '' else 's' end end,
        case when v_appts > 0 then v_appts || ' appointment' || case when v_appts = 1 then '' else 's' end || ' to follow up' end,
        case when v_reminders > 0 then v_reminders || ' reminder' || case when v_reminders = 1 then '' else 's' end end,
        case when v_clients > 0 then v_clients || ' client' || case when v_clients = 1 then '' else 's' end || ' as Sales Rep' end), 1000),
      '/work', null, gen_random_uuid(), public.app_user_id());
  end if;
  return v_out;
end $$;
revoke execute on function public.hand_over_work(bigint, bigint) from public, anon;
grant execute on function public.hand_over_work(bigint, bigint) to authenticated;

-- ==============================================================================================================
-- 20261227100000_contact_phone.sql
-- ==============================================================================================================

-- The contact's own phone (Sean, Oct 2026): the lead page lists each person
-- with their email, phone and mobile ("Contact Phone" beside Contact Email
-- and Contact Mobile), and the contact had only a mobile. The business's
-- main number stays the lead's phone.
--
--   leads.contact_phone   the contact's direct line
--   copy_name()           a lead copied to another project (a transfer, a
--                         move) takes it with it
--
-- Safe to run more than once.

alter table public.leads add column if not exists contact_phone text;

-- copy_name() lists the columns it copies: the new one goes beside the contact's mobile, once.
do $$
declare
  def text;
begin
  select pg_get_functiondef(p.oid) into def from pg_proc p where p.proname = 'copy_name' and p.pronamespace = 'public'::regnamespace;
  if def is null or def like '%contact_phone%' then
    return;
  end if;
  if (length(def) - length(replace(def, 'original_xdate, contact_mobile,', ''))) / length('original_xdate, contact_mobile,') <> 2 then
    raise warning 'contact phone: copy_name() is not as expected; a copied lead will not take the contact''s phone';
    return;
  end if;
  execute replace(def, 'original_xdate, contact_mobile,', 'original_xdate, contact_mobile, contact_phone,');
end $$;

-- ==============================================================================================================
-- 20261228100000_projected_conversion.sql
-- ==============================================================================================================

-- A project's projected appointment rate (Sean, Nov 2026): the Pipeline by
-- Month on a project's page projects appointments from each month's leads
-- at 20% unless an administrator sets the client's own rate.
--
--   projects.projected_conversion   the % of a month's leads expected to
--                                   become appointments; none: 20%
--
-- Safe to run more than once.

alter table public.projects add column if not exists projected_conversion numeric(5, 2);
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'projects_projected_conversion_check') then
    alter table public.projects add constraint projects_projected_conversion_check
      check (projected_conversion is null or (projected_conversion >= 0 and projected_conversion <= 100));
  end if;
end $$;

-- ==============================================================================================================
-- 20261229100000_admin_reports.sql
-- ==============================================================================================================

-- The administrators' Reports (Sean, Nov 2026): the leads and appointments of
-- a period (the current month, or the last three or six), by project, client,
-- Sales Rep and manager; and a billing listing for a date range, each figure
-- opening the names behind it.
--
--   projects.bill_lead_rate, bill_appointment_rate   what the client is billed
--                     for each lead and each appointment (the pay rates,
--                     lead_rate and appointment_rate, are what a manager is paid)
--
--   A lead counts in the month it was developed (promoted_at), on the project
--   that developed it, to the manager who did; invalid once marked Lead-Invalid.
--   An appointment counts in the month it was set, on the project that set it,
--   to the manager who set it: confirmed, or pending (neither confirmed nor
--   invalid), or invalid; rescheduled when moved.
--
--   report_counts(from, to)   by month, project and manager: leads (not
--                     invalid), invalid leads, appointments (not invalid),
--                     confirmed, pending, invalid, rescheduled
--   billing_report(from, to, sales rep)   each project of the active clients:
--                     those, the names called, and the cost (the managers' pay
--                     on it, chargebacks taken off), with the billing rates
--   report_items(from, to, project, kind)   the names behind one of those figures
--
-- Administrators only. Safe to run more than once.

alter table public.projects add column if not exists bill_lead_rate numeric(10, 2);
alter table public.projects add column if not exists bill_appointment_rate numeric(10, 2);
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'projects_bill_rates_check') then
    alter table public.projects add constraint projects_bill_rates_check
      check (coalesce(bill_lead_rate, 0) >= 0 and coalesce(bill_appointment_rate, 0) >= 0);
  end if;
end $$;

-- The leads developed and the appointments set from `p_from` to `p_to`, a row each, with what each became.
create or replace function public.report_events(p_from date, p_to date)
returns table (kind text, at date, project_id bigint, user_id bigint, lead_id bigint, appointment_id bigint,
               invalid boolean, confirmed boolean, rescheduled boolean)
language sql stable security definer set search_path = public as $$
  with z as (select public.business_tz() as tz)
  select 'lead', (l.promoted_at at time zone z.tz)::date, coalesce(l.source_project_id, l.project_id), l.dbdv_user_id, l.id, null::bigint,
         (l.call_result_dbdv = 'Lead-Invalid' or r.effect = 'lead_invalid'), false, false
    from public.leads l
    cross join z
    left join public.call_results r on r.id = l.result_id
   where l.deleted_at is null and l.promoted_at is not null
     and l.promoted_at >= (p_from::timestamp at time zone z.tz) and l.promoted_at < ((p_to + 1)::timestamp at time zone z.tz)
  union all
  select 'appointment', (coalesce(a.appt_create_date, a.created_at) at time zone z.tz)::date, coalesce(a.set_project_id, a.project_id), a.user_id, a.lead_id, a.id,
         a.invalid_at is not null, a.confirmed_at is not null and a.invalid_at is null,
         a.invalid_at is null and s.name = 'Rescheduled'
    from public.appointments a
    cross join z
    join public.leads l on l.id = a.lead_id and l.deleted_at is null
    left join public.appointment_statuses s on s.id = a.status_id
   where a.deleted_at is null
     and coalesce(a.appt_create_date, a.created_at) >= (p_from::timestamp at time zone z.tz)
     and coalesce(a.appt_create_date, a.created_at) < ((p_to + 1)::timestamp at time zone z.tz);
$$;
revoke execute on function public.report_events(date, date) from public, anon, authenticated;

create or replace function public.report_counts(p_from date, p_to date)
returns table (ym text, project_id bigint, user_id bigint, leads bigint, invalid_leads bigint, appts bigint,
               confirmed bigint, pending bigint, invalid_appts bigint, rescheduled bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'Reports are for administrators' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    raise exception 'Choose a range of a year or less' using errcode = '22023';
  end if;
  return query
  select to_char(e.at, 'YYYY-MM'), e.project_id, e.user_id,
         count(*) filter (where e.kind = 'lead' and not e.invalid),
         count(*) filter (where e.kind = 'lead' and e.invalid),
         count(*) filter (where e.kind = 'appointment' and not e.invalid),
         count(*) filter (where e.kind = 'appointment' and e.confirmed),
         count(*) filter (where e.kind = 'appointment' and not e.invalid and not e.confirmed),
         count(*) filter (where e.kind = 'appointment' and e.invalid),
         count(*) filter (where e.kind = 'appointment' and e.rescheduled)
    from public.report_events(p_from, p_to) e
   group by 1, 2, 3;
end $$;
revoke execute on function public.report_counts(date, date) from public, anon;
grant execute on function public.report_counts(date, date) to authenticated;

create or replace function public.billing_report(p_from date, p_to date, p_rep bigint default null)
returns table (company_id bigint, client text, sales_rep text, project_id bigint, project text, project_type text,
               leads bigint, invalid_leads bigint, appts bigint, confirmed bigint, pending bigint, invalid_appts bigint,
               names_called bigint, cost numeric, bill_lead_rate numeric, bill_appointment_rate numeric)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz text := public.business_tz();
begin
  if not public.is_admin() then
    raise exception 'Reports are for administrators' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    raise exception 'Choose a range of a year or less' using errcode = '22023';
  end if;
  return query
  with e as (
    select e.project_id,
           count(*) filter (where e.kind = 'lead' and not e.invalid) as leads,
           count(*) filter (where e.kind = 'lead' and e.invalid) as invalid_leads,
           count(*) filter (where e.kind = 'appointment' and not e.invalid) as appts,
           count(*) filter (where e.kind = 'appointment' and e.confirmed) as confirmed,
           count(*) filter (where e.kind = 'appointment' and not e.invalid and not e.confirmed) as pending,
           count(*) filter (where e.kind = 'appointment' and e.invalid) as invalid_appts
      from public.report_events(p_from, p_to) e group by 1
  ), c as (
    select cr.project_id, count(distinct cr.lead_id) as n
      from public.call_records cr
     where cr.call_date >= (p_from::timestamp at time zone v_tz) and cr.call_date < ((p_to + 1)::timestamp at time zone v_tz)
     group by 1
  ), pay as (
    select pe.project_id, sum(pe.amount) as amount
      from public.pay_events pe
     where pe.created_at >= (p_from::timestamp at time zone v_tz) and pe.created_at < ((p_to + 1)::timestamp at time zone v_tz)
     group by 1
  )
  select co.id, co.name, nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), p.id, p.name, t.code,
         coalesce(e.leads, 0), coalesce(e.invalid_leads, 0), coalesce(e.appts, 0), coalesce(e.confirmed, 0),
         coalesce(e.pending, 0), coalesce(e.invalid_appts, 0), coalesce(c.n, 0), coalesce(pay.amount, 0)::numeric,
         p.bill_lead_rate, p.bill_appointment_rate
    from public.projects p
    join public.companies co on co.id = p.company_id and co.deleted_at is null and co.status = 'active'
    left join public.project_types t on t.id = p.project_type_id
    left join public.project_statuses ps on ps.id = p.status_id
    left join public.users u on u.id = co.sales_rep_id
    left join e on e.project_id = p.id
    left join c on c.project_id = p.id
    left join pay on pay.project_id = p.id
   where p.deleted_at is null
     and (p_rep is null or co.sales_rep_id = p_rep)
     -- Its active projects, and any other with something in the range.
     and (ps.name = 'Active' or e.project_id is not null or c.project_id is not null or pay.project_id is not null)
   order by co.name, p.name;
end $$;
revoke execute on function public.billing_report(date, date, bigint) from public, anon;
grant execute on function public.billing_report(date, date, bigint) to authenticated;

create or replace function public.report_items(p_from date, p_to date, p_project bigint, p_kind text)
returns table (lead_id bigint, appointment_id bigint, company text, at date, appt_date date, appt_time text,
               manager text, cost numeric, sales_rep text, project text, status text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'Reports are for administrators' using errcode = '42501';
  end if;
  if p_kind not in ('leads', 'invalid_leads', 'appts', 'confirmed', 'pending', 'invalid_appts') then
    raise exception 'Unknown figure' using errcode = '22023';
  end if;
  if p_from is null or p_to is null or p_to < p_from or p_to - p_from > 400 then
    raise exception 'Choose a range of a year or less' using errcode = '22023';
  end if;
  return query
  select e.lead_id, e.appointment_id, l.company_name, e.at, a.appt_date, a.appt_time,
         nullif(btrim(concat_ws(' ', m.first_name, m.last_name)), ''),
         -- What the manager was paid for it (chargebacks taken off): the lead's lead pay, or the appointment's own.
         coalesce((select sum(pe.amount) from public.pay_events pe
                    where pe.lead_id = e.lead_id
                      and (case when e.kind = 'lead' then pe.kind = 'lead' and pe.appointment_id is null else pe.appointment_id = e.appointment_id end)), 0)::numeric,
         nullif(btrim(concat_ws(' ', r.first_name, r.last_name)), ''), p.name,
         case when e.kind = 'lead' then case when e.invalid then 'Invalid' else 'Developed' end
              when e.invalid then 'Invalid' when e.confirmed then 'Confirmed' else 'Pending' end
    from public.report_events(p_from, p_to) e
    join public.leads l on l.id = e.lead_id
    join public.projects p on p.id = e.project_id
    left join public.companies co on co.id = p.company_id
    left join public.users r on r.id = co.sales_rep_id
    left join public.users m on m.id = e.user_id
    left join public.appointments a on a.id = e.appointment_id
   where e.project_id = p_project
     and case p_kind
           when 'leads' then e.kind = 'lead' and not e.invalid
           when 'invalid_leads' then e.kind = 'lead' and e.invalid
           when 'appts' then e.kind = 'appointment' and not e.invalid
           when 'confirmed' then e.kind = 'appointment' and e.confirmed
           when 'pending' then e.kind = 'appointment' and not e.invalid and not e.confirmed
           else e.kind = 'appointment' and e.invalid
         end
   order by e.at, l.company_name;
end $$;
revoke execute on function public.report_items(date, date, bigint, text) from public, anon;
grant execute on function public.report_items(date, date, bigint, text) to authenticated;

-- ==============================================================================================================
-- 20261230100000_carrier_footprint.sql
-- ==============================================================================================================

-- The Insurance Companies list (Sean, Nov 2026): for each carrier, the states
-- its leads are in, how many leads (X-dates) it has there, and how many
-- clients those leads belong to, from the carrier fields on our leads; for
-- every state, or the states picked.
--
--   A lead's carriers are those its policy lines name (the carrier fields and
--   the dental and vision providers, as a call list's carrier filter reads
--   them; not its agency), matched to the list by carrier_key(), and the
--   carrier its agency_id names.
--
--   carrier_footprint(states)   a row a carrier with leads: its states, its
--                     leads (a lead once, whichever of its policy lines name
--                     the carrier, or the lead's own agency_id), its clients
--
-- Administrators only. Safe to run more than once.

create or replace function public.carrier_footprint(p_states text[] default null)
returns table (agency_id bigint, states text[], leads bigint, clients bigint)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'The carriers'' figures are for administrators' using errcode = '42501';
  end if;
  return query
  with names as (
    select a.id, public.carrier_key(a.name) as k from public.agencies a
     where a.deleted_at is null and public.carrier_key(a.name) is not null
  ), keyed as (
    -- Each name written on the leads, matched to its carrier once (a few hundred names, not a key a lead).
    select w.name, n.id
      from (select distinct v.name
              from public.insurance_details d
             cross join lateral (values (d.pkg_carrier), (d.wc_carrier), (d.auto_carrier), (d.health_carrier), (d.dental_provider), (d.vision_provider),
                                        (d.prof_liab_carrier), (d.do_carrier), (d.eo_carrier), (d.homeowner_carrier), (d.personal_auto_carrier),
                                        (d.personal_lines_carrier)) v(name)
             where v.name is not null) w
      join names n on n.k = public.carrier_key(w.name)
  ), lead_carriers as (
    select d.lead_id, k.id as agency_id
      from public.insurance_details d
     cross join lateral (values (d.pkg_carrier), (d.wc_carrier), (d.auto_carrier), (d.health_carrier), (d.dental_provider), (d.vision_provider),
                                (d.prof_liab_carrier), (d.do_carrier), (d.eo_carrier), (d.homeowner_carrier), (d.personal_auto_carrier),
                                (d.personal_lines_carrier)) v(name)
      join keyed k on k.name = v.name
    union
    select l.id, l.agency_id from public.leads l where l.agency_id is not null and l.deleted_at is null
  )
  select lc.agency_id,
         coalesce(array_agg(distinct upper(btrim(l.state))) filter (where nullif(btrim(l.state), '') is not null), '{}'),
         count(distinct l.id),
         count(distinct p.company_id)
    from lead_carriers lc
    join public.leads l on l.id = lc.lead_id and l.deleted_at is null
    left join public.projects p on p.id = l.project_id
   where p_states is null or cardinality(p_states) = 0 or upper(btrim(l.state)) = any(p_states)
   group by lc.agency_id;
end $$;
revoke execute on function public.carrier_footprint(text[]) from public, anon;
grant execute on function public.carrier_footprint(text[]) to authenticated;

-- ==============================================================================================================
-- 20261231100000_reports_by_managers.sql
-- ==============================================================================================================

-- The administrators' Reports count only what our managers did (Sean, Nov 2026):
-- a lead developed by one of our staff (leads.dbdv_user_id), an appointment set
-- by one (appointments.user_id) — not the names loaded onto a project, the
-- appointments a list or a client brought, or anything with no one behind it.
-- Every card and the billing listing read report_events(), so all follow.
--
-- A list from the old system gives the dates and the managers (Date Developed,
-- Developed By, Appt Create Date, Set By), read on import, so migrated leads
-- and appointments count in the months they were developed and set.
--
-- Safe to run more than once.

create or replace function public.report_events(p_from date, p_to date)
returns table (kind text, at date, project_id bigint, user_id bigint, lead_id bigint, appointment_id bigint,
               invalid boolean, confirmed boolean, rescheduled boolean)
language sql stable security definer set search_path = public as $$
  with z as (select public.business_tz() as tz)
  select 'lead', (l.promoted_at at time zone z.tz)::date, coalesce(l.source_project_id, l.project_id), l.dbdv_user_id, l.id, null::bigint,
         (l.call_result_dbdv = 'Lead-Invalid' or r.effect = 'lead_invalid'), false, false
    from public.leads l
    cross join z
    join public.users u on u.id = l.dbdv_user_id and u.role in ('admin', 'manager', 'agent')
    left join public.call_results r on r.id = l.result_id
   where l.deleted_at is null and l.promoted_at is not null
     and l.promoted_at >= (p_from::timestamp at time zone z.tz) and l.promoted_at < ((p_to + 1)::timestamp at time zone z.tz)
  union all
  select 'appointment', (coalesce(a.appt_create_date, a.created_at) at time zone z.tz)::date, coalesce(a.set_project_id, a.project_id), a.user_id, a.lead_id, a.id,
         a.invalid_at is not null, a.confirmed_at is not null and a.invalid_at is null,
         a.invalid_at is null and s.name = 'Rescheduled'
    from public.appointments a
    cross join z
    join public.users u on u.id = a.user_id and u.role in ('admin', 'manager', 'agent')
    join public.leads l on l.id = a.lead_id and l.deleted_at is null
    left join public.appointment_statuses s on s.id = a.status_id
   where a.deleted_at is null
     and coalesce(a.appt_create_date, a.created_at) >= (p_from::timestamp at time zone z.tz)
     and coalesce(a.appt_create_date, a.created_at) < ((p_to + 1)::timestamp at time zone z.tz);
$$;
revoke execute on function public.report_events(date, date) from public, anon, authenticated;

-- ==============================================================================================================
-- 20270101100000_xdate_resolved_bucket.sql
-- ==============================================================================================================

-- X-Dates by Month (Sean, Nov 2026): "Off the list" counts the appointments too, as the Pipeline by
-- Month does (the names resolved: appointments, invalid ones and the rest), so its names are those of
-- a new bucket, 'resolved': 'off' and 'appointment' together. The other buckets are as they were.
--
-- Safe to run more than once.

do $$
declare
  v_def text;
begin
  v_def := pg_get_functiondef('public.xdate_month_leads_filtered(integer,text,bigint[],bigint,text,bigint,bigint[],integer,integer)'::regprocedure);
  if position('''resolved''' in v_def) = 0 then
    if position('p_bucket is null or x.bucket = p_bucket)' in v_def) = 0 then
      raise exception 'xdate_month_leads_filtered is not as expected';
    end if;
    execute replace(v_def, 'p_bucket is null or x.bucket = p_bucket)',
                    'p_bucket is null or x.bucket = p_bucket or (p_bucket = ''resolved'' and x.bucket in (''off'', ''appointment'')))');
  end if;

  v_def := pg_get_functiondef('public.xdate_month_leads(integer,text,bigint,bigint,integer,integer)'::regprocedure);
  if position('''resolved''' in v_def) = 0 then
    if position('else ''off'' end) = p_bucket)' in v_def) = 0 then
      raise exception 'xdate_month_leads is not as expected';
    end if;
    execute replace(v_def, 'else ''off'' end) = p_bucket)',
                    'else ''off'' end) = any(case when p_bucket = ''resolved'' then array[''off'', ''appointment''] else array[p_bucket] end))');
  end if;
end $$;

-- ==============================================================================================================
-- 20270102100000_twilio_phone.sql
-- ==============================================================================================================

-- The phone's Twilio line (Nov 2026): who has Lighthouse open with the phone ready to take a call, so a
-- call coming in to the Twilio number rings them. The server stamps a person's row each time their
-- browser fetches its calling token (app/api/phone/token, every few minutes while a tab is open), and
-- reads the fresh ones when a call comes in (app/api/twilio/voice). Only the server's own key reads or
-- writes it; nobody's browser sees who else is online.
--
-- Safe to run more than once.

create table if not exists public.phone_presence (
  user_id  bigint primary key references public.users(id) on delete cascade,
  seen_at  timestamptz not null default now()
);

create index if not exists phone_presence_seen_idx on public.phone_presence (seen_at desc);

alter table public.phone_presence enable row level security;

revoke all on public.phone_presence from anon, authenticated;
grant select, insert, update, delete on public.phone_presence to service_role;

-- A voicemail left on the Twilio number: a notice to each active administrator (pushed to their desktop
-- like any other), from app/api/twilio/voice once Twilio says a message was recorded. The server's own
-- key only. Returns how many were told.
create or replace function public.phone_voicemail_notice(p_title text, p_body text, p_link text)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  insert into public.notifications (user_id, kind, title, body, link)
  select u.id, 'system', left(p_title, 200), left(p_body, 2000), p_link
  from public.users u
  where u.role = 'admin' and u.status = 'active';
  get diagnostics v_count = row_count;
  return v_count;
end $$;

revoke execute on function public.phone_voicemail_notice(text, text, text) from public, anon, authenticated;
grant execute on function public.phone_voicemail_notice(text, text, text) to service_role;

-- ==============================================================================================================
-- 20270103100000_carrier_report.sql
-- ==============================================================================================================

-- The Insurance Companies list and a report a carrier (Sean, Nov 2026):
--
--   carrier_leads(agency)   each lead's carriers: those its policy lines name
--                     (matched by carrier_key()), and its agency_id; one carrier's alone when given
--   carrier_top_clients()   the clients each carrier is a Top Carrier of, on
--                     their projects' Project Info, and the projects that say so
--   carrier_footprint(states)   now: a carrier's states with its leads in each,
--                     its leads, and its clients counted from Top Carriers;
--                     a row for every carrier with leads or listed by a client
--   carrier_clients(agency, states)   a carrier's clients (Top Carriers), each
--                     with its leads (X-dates) naming the carrier and their states
--   carrier_client_leads(agency, client, states)   those leads: the business,
--                     where it is, its project, renewals and carriers, when created
--
-- Administrators only. Safe to run more than once.

create or replace function public.carrier_leads(p_agency bigint default null)
returns table (lead_id bigint, agency_id bigint)
language sql stable security definer set search_path = public set work_mem = '64MB' as $$
  with names as materialized (
    select a.id, public.carrier_key(a.name) as k from public.agencies a
     where a.deleted_at is null and (p_agency is null or a.id = p_agency)
  ), written as (
    select d.lead_id, v.name
      from public.insurance_details d
     cross join lateral (values (d.pkg_carrier), (d.wc_carrier), (d.auto_carrier), (d.health_carrier), (d.dental_provider), (d.vision_provider),
                                (d.prof_liab_carrier), (d.do_carrier), (d.eo_carrier), (d.homeowner_carrier), (d.personal_auto_carrier),
                                (d.personal_lines_carrier)) v(name)
     where v.name is not null
  ), keyed as materialized (
    -- Each name written on the leads matched to its carrier once (a few hundred names, not a key a lead).
    select w.name, n.id from (select name, public.carrier_key(name) as k from (select distinct name from written) x) w join names n on n.k = w.k
  )
  select w.lead_id, k.id from written w join keyed k on k.name = w.name
  union
  select l.id, l.agency_id from public.leads l
   where l.agency_id is not null and l.deleted_at is null and (p_agency is null or l.agency_id = p_agency);
$$;
revoke execute on function public.carrier_leads(bigint) from public, anon, authenticated;

create or replace function public.carrier_top_clients()
returns table (agency_id bigint, company_id bigint, projects text[])
language sql stable security definer set search_path = public as $$
  select a.id, p.company_id, array_agg(distinct p.name order by p.name)
    from public.project_profiles pp
    join public.projects p on p.id = pp.project_id and p.deleted_at is null
    join public.companies co on co.id = p.company_id and co.deleted_at is null
   cross join lateral unnest(pp.top_carriers) t(name)
    join public.agencies a on a.deleted_at is null and public.carrier_key(a.name) = public.carrier_key(t.name)
   group by 1, 2;
$$;
revoke execute on function public.carrier_top_clients() from public, anon, authenticated;

drop function if exists public.carrier_footprint(text[]);
create function public.carrier_footprint(p_states text[] default null)
returns table (agency_id bigint, states text[], by_state jsonb, leads bigint, clients bigint)
language plpgsql stable security definer set search_path = public set work_mem = '64MB' as $$
begin
  if not public.is_admin() then
    raise exception 'The carriers'' figures are for administrators' using errcode = '42501';
  end if;
  return query
  with per as (
    select lc.agency_id, nullif(upper(btrim(l.state)), '') as state, count(*) as n
      from public.carrier_leads() lc
      join public.leads l on l.id = lc.lead_id and l.deleted_at is null
     where p_states is null or cardinality(p_states) = 0 or upper(btrim(l.state)) = any(p_states)
     group by 1, 2
  ), f as (
    select per.agency_id,
           coalesce(array_agg(per.state order by per.state) filter (where per.state is not null), '{}') as states,
           coalesce(jsonb_object_agg(per.state, per.n) filter (where per.state is not null), '{}') as by_state,
           sum(per.n)::bigint as leads
      from per group by 1
  ), c as (
    select tc.agency_id, count(*) as clients from public.carrier_top_clients() tc group by 1
  )
  select coalesce(f.agency_id, c.agency_id), coalesce(f.states, '{}'), coalesce(f.by_state, '{}'), coalesce(f.leads, 0), coalesce(c.clients, 0)
    from f full join c on c.agency_id = f.agency_id;
end $$;
revoke execute on function public.carrier_footprint(text[]) from public, anon;
grant execute on function public.carrier_footprint(text[]) to authenticated;

create or replace function public.carrier_clients(p_agency bigint, p_states text[] default null)
returns table (company_id bigint, client text, projects text[], xdates bigint, states text[])
language plpgsql stable security definer set search_path = public set work_mem = '64MB' as $$
begin
  if not public.is_admin() then
    raise exception 'The carriers'' figures are for administrators' using errcode = '42501';
  end if;
  return query
  with mine as (
    select l.id, nullif(upper(btrim(l.state)), '') as state, p.company_id
      from public.carrier_leads(p_agency) lc
      join public.leads l on l.id = lc.lead_id and l.deleted_at is null
      join public.projects p on p.id = l.project_id
     where p_states is null or cardinality(p_states) = 0 or upper(btrim(l.state)) = any(p_states)
  )
  select tc.company_id, co.name, tc.projects, count(distinct m.id),
         coalesce(array_agg(distinct m.state) filter (where m.state is not null), '{}')
    from public.carrier_top_clients() tc
    join public.companies co on co.id = tc.company_id
    left join mine m on m.company_id = tc.company_id
   where tc.agency_id = p_agency
   group by 1, 2, 3
   order by co.name;
end $$;
revoke execute on function public.carrier_clients(bigint, text[]) from public, anon;
grant execute on function public.carrier_clients(bigint, text[]) to authenticated;

create or replace function public.carrier_client_leads(p_agency bigint, p_company bigint, p_states text[] default null)
returns table (lead_id bigint, company text, city text, state text, zip text, phone text, project text,
               ultimate_xdate date, lines jsonb, created date)
language plpgsql stable security definer set search_path = public set work_mem = '64MB' as $$
declare
  v_key text := (select public.carrier_key(a.name) from public.agencies a where a.id = p_agency);
begin
  if not public.is_admin() then
    raise exception 'The carriers'' figures are for administrators' using errcode = '42501';
  end if;
  return query
  select l.id, l.company_name, l.city, l.state, l.zip, l.phone, p.name, d.ultimate_xdate,
         -- Each policy line with something on it: its X-date, its carrier, and whether that is this one.
         coalesce((select jsonb_agg(jsonb_build_object('key', v.k, 'xdate', v.x, 'carrier', v.c, 'mine', public.carrier_key(v.c) = v_key) order by v.o)
                     from (values (1, 'pkg', d.pkg_xdate, d.pkg_carrier), (2, 'wc', d.wc_xdate, d.wc_carrier), (3, 'auto', d.auto_xdate, d.auto_carrier),
                                  (4, 'health', d.health_xdate, d.health_carrier), (5, 'personal', d.personal_lines_xdate, d.personal_lines_carrier),
                                  (6, 'prof', d.prof_liab_xdate, d.prof_liab_carrier), (7, 'do', d.do_xdate, d.do_carrier), (8, 'eo', d.eo_xdate, d.eo_carrier),
                                  (9, 'dental', d.dental_xdate, d.dental_provider), (10, 'vision', d.vision_xdate, d.vision_provider),
                                  (11, 'homeowner', d.homeowner_xdate, d.homeowner_carrier), (12, 'personal_auto', d.personal_auto_xdate, d.personal_auto_carrier)) v(o, k, x, c)
                    where v.x is not null or nullif(btrim(v.c), '') is not null), '[]'),
         (coalesce(l.lead_date, l.created_at) at time zone public.business_tz())::date
    from (select distinct lc.lead_id from public.carrier_leads(p_agency) lc) lc
    join public.leads l on l.id = lc.lead_id and l.deleted_at is null
    join public.projects p on p.id = l.project_id and p.company_id = p_company
    left join public.insurance_details d on d.lead_id = l.id
   where p_states is null or cardinality(p_states) = 0 or upper(btrim(l.state)) = any(p_states)
   order by coalesce(d.ultimate_xdate, '9999-12-31'), l.company_name, l.id;
end $$;
revoke execute on function public.carrier_client_leads(bigint, bigint, text[]) from public, anon;
grant execute on function public.carrier_client_leads(bigint, bigint, text[]) to authenticated;

-- ==============================================================================================================
-- 20270104100000_match_tool.sql
-- ==============================================================================================================

-- The Match Tool (Sean, Nov 2026). A match is a name on a project's list (the
-- client's import) that we already have elsewhere in the system, with a renewal
-- date: on another client's project, an old or completed one, any list. The
-- same business by its phone, or by its name in the same place (its ZIP, or
-- its city and state); not by SIC code or size, which two records of one
-- business often disagree on. Bringing a match in copies its renewal dates:
--
--   to DB Dev    onto the name's Liability / Work comp / Auto (and any other)
--                lines, its Ultimate X-date left blank, at Viable-Staged, for
--                the lead managers to call in renewal order
--   to Appts     a lead on the linked appointment project with all of it,
--                Ultimate X-date too, at Lead-No Contact, to the appointment
--                manager with the fewest names
--
-- Either way the lead is marked matched (leads.matched_at, matched_from_lead_id,
-- matched_by): it counts toward the project's lead goal, as a client sees it,
-- but no report counts it as developed (no manager on it: report_events counts
-- a lead to the staff member who developed it) and nobody is paid for it.
--
--   business_key(name)   a business name as the import compares them (dedupe.js nameKey)
--   project_matches(project)   a project's matches: each name, the record matched and how, its renewal
--   match_summary()   each active project's figures for the Match report
--   add_matches(project, leads, to)   bring the matches picked in
--
-- Administrators only. Safe to run more than once.

alter table public.leads add column if not exists matched_at timestamptz;
alter table public.leads add column if not exists matched_from_lead_id bigint references public.leads(id) on delete set null;
alter table public.leads add column if not exists matched_by bigint references public.users(id) on delete set null;
create index if not exists leads_matched on public.leads (coalesce(source_project_id, project_id), matched_at) where matched_at is not null;

-- "Acme Plumbing, Inc." is "acmeplumbing", "The Acme Co" is "acme": as the import's duplicate check reads a name.
create or replace function public.business_key(p_name text)
returns text language plpgsql immutable parallel safe set search_path = '' as $$
declare
  w text[] := array_remove(regexp_split_to_array(replace(lower(coalesce(p_name, '')), '&', ' and '), '[^a-z0-9]+'), '');
begin
  while cardinality(w) > 1 and w[cardinality(w)] = any (array['inc', 'incorporated', 'llc', 'ltd', 'limited', 'co', 'corp', 'corporation', 'company', 'pllc', 'llp', 'lp', 'pc', 'the']) loop
    w := w[1:cardinality(w) - 1];
  end loop;
  if cardinality(w) > 1 and w[1] = 'the' then
    w := w[2:cardinality(w)];
  end if;
  return nullif(array_to_string(w, ''), '');
end $$;
create index if not exists leads_business_key on public.leads (public.business_key(company_name)) where deleted_at is null;

-- A renewal day's next time round, on or after `p_today`: 2025-03-01 is 2027-03-01 on 2026-11-05 (Feb 29 as Feb 28).
create or replace function public.next_renewal(p_day date, p_today date)
returns date language plpgsql immutable parallel safe set search_path = '' as $$
declare
  d date;
begin
  if p_day is null then return null; end if;
  d := (p_day + make_interval(years => extract(year from p_today)::int - extract(year from p_day)::int))::date;
  return case when d >= p_today then d else (p_day + make_interval(years => extract(year from p_today)::int + 1 - extract(year from p_day)::int))::date end;
end $$;

-- A project's matches. Its names: on the project, not deleted, still viable,
-- never matched, with no renewal date of their own. Their match: the record
-- elsewhere (not on the project or its linked one) with a renewal date, found
-- by phone first, else by name in the same ZIP or city and state; the one with
-- an Ultimate X-date, then the latest worked, when there are several.
create or replace function public.project_matches_raw(p_project bigint, p_today date)
returns table (lead_id bigint, company text, city text, state text, zip text, phone text,
               source_lead_id bigint, source_project text, source_client text, matched_by text,
               renewal date, lines jsonb)
language sql stable security definer set search_path = public set work_mem = '64MB' as $$
  with p as (
    select pr.id, pr.appt_project_id from public.projects pr where pr.id = p_project
  ), family as (
    select p.id from p
    union select p.appt_project_id from p where p.appt_project_id is not null
    union select pr.id from public.projects pr, p where pr.appt_project_id = p.id
  ), targets as (
    select l.id, l.company_name, l.city, l.state, l.zip, l.phone,
           public.phone_key(l.phone) as pk, public.business_key(l.company_name) as nk,
           left(btrim(l.zip), 5) as z5, lower(btrim(l.city)) as ck, upper(btrim(l.state)) as sk
      from public.leads l
      join public.call_results r on r.id = l.result_id and r.viable
     where l.project_id = p_project and l.deleted_at is null and l.matched_at is null
       and not exists (select 1 from public.insurance_details i where i.lead_id = l.id
                        and coalesce(i.ultimate_xdate, i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate, i.vision_xdate,
                                     i.prof_liab_xdate, i.do_xdate, i.eo_xdate, i.homeowner_xdate, i.personal_auto_xdate, i.personal_lines_xdate) is not null)
  )
  select t.id, t.company_name, t.city, t.state, t.zip, t.phone,
         m.id, m.project, m.client, m.how,
         public.next_renewal(m.renewal, p_today),
         m.lines
    from targets t
    cross join lateral (
      select s.id, sp.name as project, co.name as client, c.how, c.renewal, c.lines
        from (
          select s.id, 'phone' as how from public.leads s
           where t.pk is not null and public.phone_key(s.phone) = t.pk and s.deleted_at is null
          union
          select s.id, 'name' from public.leads s
           where t.nk is not null and public.business_key(s.company_name) = t.nk and s.deleted_at is null
             and ((t.z5 <> '' and left(btrim(s.zip), 5) = t.z5)
                  or (t.ck <> '' and lower(btrim(s.city)) = t.ck and upper(btrim(s.state)) = t.sk))
        ) hit
        join public.leads s on s.id = hit.id
        join public.projects sp on sp.id = s.project_id
        left join public.companies co on co.id = sp.company_id
        join public.insurance_details i on i.lead_id = s.id
        cross join lateral (
          select hit.how,
                 coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate, i.vision_xdate,
                                                  i.prof_liab_xdate, i.do_xdate, i.eo_xdate, i.homeowner_xdate, i.personal_auto_xdate, i.personal_lines_xdate)) as renewal,
                 jsonb_strip_nulls(jsonb_build_object(
                   'ultimate_xdate', i.ultimate_xdate,
                   'pkg_xdate', i.pkg_xdate, 'pkg_carrier', i.pkg_carrier, 'wc_xdate', i.wc_xdate, 'wc_carrier', i.wc_carrier,
                   'auto_xdate', i.auto_xdate, 'auto_carrier', i.auto_carrier, 'health_xdate', i.health_xdate, 'health_carrier', i.health_carrier,
                   'dental_xdate', i.dental_xdate, 'dental_provider', i.dental_provider, 'vision_xdate', i.vision_xdate, 'vision_provider', i.vision_provider,
                   'prof_liab_xdate', i.prof_liab_xdate, 'prof_liab_carrier', i.prof_liab_carrier, 'do_xdate', i.do_xdate, 'do_carrier', i.do_carrier,
                   'eo_xdate', i.eo_xdate, 'eo_carrier', i.eo_carrier, 'homeowner_xdate', i.homeowner_xdate, 'homeowner_carrier', i.homeowner_carrier,
                   'personal_auto_xdate', i.personal_auto_xdate, 'personal_auto_carrier', i.personal_auto_carrier,
                   'personal_lines_xdate', i.personal_lines_xdate, 'personal_lines_carrier', i.personal_lines_carrier,
                   'agency_name', i.agency_name)) as lines
        ) c
       where s.project_id not in (select id from family) and c.renewal is not null
       order by (hit.how = 'phone') desc, (i.ultimate_xdate is not null) desc, s.updated_at desc, s.id desc
       limit 1
    ) m;
$$;
revoke execute on function public.project_matches_raw(bigint, date) from public, anon, authenticated;

create or replace function public.project_matches(p_project bigint)
returns table (lead_id bigint, company text, city text, state text, zip text, phone text,
               source_lead_id bigint, source_project text, source_client text, matched_by text,
               renewal date, lines jsonb)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'The Match Tool is for administrators' using errcode = '42501';
  end if;
  return query select * from public.project_matches_raw(p_project, (now() at time zone public.business_tz())::date) m
   order by m.renewal, m.company, m.lead_id;
end $$;
revoke execute on function public.project_matches(bigint) from public, anon;
grant execute on function public.project_matches(bigint) to authenticated;

-- Each active project's figures: its lead goal, leads in (every lead it sent
-- on or brought in), those our managers developed and the matches added since
-- its start date, and its matches waiting, by renewal month.
create or replace function public.match_summary()
returns table (project_id bigint, project text, type text, client text, status text, start_date date, due_date date,
               lead_goal int, leads bigint, developed bigint, matched bigint, matches bigint, by_month jsonb)
language plpgsql stable security definer set search_path = public set work_mem = '64MB' as $$
declare
  v_today date := (now() at time zone public.business_tz())::date;
begin
  if not public.is_admin() then
    raise exception 'The Match Tool is for administrators' using errcode = '42501';
  end if;
  return query
  with pr as (
    select p.id, p.name, t.code, co.name as client, ps.name as status, p.start_date, p.end_date, p.lead_goal
      from public.projects p
      join public.project_statuses ps on ps.id = p.status_id and ps.name = 'Active'
      left join public.project_types t on t.id = p.project_type_id
      left join public.companies co on co.id = p.company_id
     where p.deleted_at is null and (co.id is null or co.deleted_at is null)
  ), counts as (
    -- A lead counts to the project it was developed on (its DB Dev project once sent on).
    select coalesce(l.source_project_id, l.project_id) as pid,
           count(*) filter (where l.promoted_at is not null or (l.matched_at is not null and l.stage = 'appt')) as leads
      from public.leads l
     where l.deleted_at is null and coalesce(l.source_project_id, l.project_id) in (select id from pr)
     group by 1
  ), since as (
    select pr.id,
           (select count(*) from public.leads l
             where l.deleted_at is null and coalesce(l.source_project_id, l.project_id) = pr.id
               and l.promoted_at is not null and l.matched_at is null and l.dbdv_user_id is not null
               and (pr.start_date is null or l.promoted_at >= (pr.start_date::timestamp at time zone public.business_tz()))) as developed,
           (select count(*) from public.leads l
             where l.deleted_at is null and coalesce(l.source_project_id, l.project_id) = pr.id and l.matched_at is not null
               and (pr.start_date is null or l.matched_at >= (pr.start_date::timestamp at time zone public.business_tz()))) as matched
      from pr
  ), m as (
    select pr.id, count(x.*) as n,
           coalesce(jsonb_object_agg(x.mon, x.k) filter (where x.mon is not null), '{}') as by_month
      from pr
      left join lateral (
        select extract(month from mm.renewal)::int as mon, count(*) as k
          from public.project_matches_raw(pr.id, v_today) mm group by 1
      ) x on true
     group by pr.id
  )
  select pr.id, pr.name, pr.code, pr.client, pr.status, pr.start_date, pr.end_date, pr.lead_goal,
         coalesce(c.leads, 0), s.developed, s.matched,
         coalesce((select sum(v::bigint) from jsonb_each_text(m.by_month) e(k, v)), 0)::bigint, m.by_month
    from pr
    join since s on s.id = pr.id
    join m on m.id = pr.id
    left join counts c on c.pid = pr.id
   order by pr.client, pr.name;
end $$;
revoke execute on function public.match_summary() from public, anon;
grant execute on function public.match_summary() to authenticated;

-- Bring matches in: `p_leads` (names on the project its matches named) to 'dbdev' or 'appt'. Each found again
-- now, so a name matched since, or no longer a match, is skipped. The count brought in.
create or replace function public.add_matches(p_project bigint, p_leads bigint[], p_to text)
returns int
language plpgsql volatile security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
  v_today date := (now() at time zone public.business_tz())::date;
  p public.projects%rowtype;
  v_type text;
  v_staged bigint;
  v_lead_result public.call_results%rowtype;
  m record;
  n int := 0;
begin
  if not public.is_admin() then
    raise exception 'The Match Tool is for administrators' using errcode = '42501';
  end if;
  if p_to not in ('dbdev', 'appt') then
    raise exception 'Bring matches to the DB Dev or the appointment project' using errcode = '22023';
  end if;
  select * into p from public.projects where id = p_project and deleted_at is null;
  if p.id is null then
    raise exception 'That project no longer exists' using errcode = '22023';
  end if;
  v_type := public.project_type_code(p.id);
  if p_to = 'dbdev' and v_type <> 'DBDV' then
    raise exception '% is not a DB Dev project', p.name using errcode = '22023';
  end if;
  if p_to = 'appt' and v_type = 'DBDV' and p.appt_project_id is null then
    raise exception 'Link % to an appointment project before sending it leads', p.name using errcode = '22023';
  end if;
  select id into v_staged from public.call_results where project_type = 'DBDV' and name = 'Viable-Staged';
  select * into v_lead_result from public.call_results where project_type = 'APPT' and name = 'Lead-No Contact';

  for m in select * from public.project_matches_raw(p.id, v_today) mm where mm.lead_id = any (p_leads) loop
    -- The record's renewal dates, each brought round to its next time, and its carriers.
    if not exists (select 1 from public.insurance_details where lead_id = m.lead_id) then
      insert into public.insurance_details (lead_id) values (m.lead_id);
    end if;
    update public.insurance_details i set
      pkg_xdate = public.next_renewal((m.lines->>'pkg_xdate')::date, v_today), pkg_carrier = coalesce(i.pkg_carrier, m.lines->>'pkg_carrier'),
      wc_xdate = public.next_renewal((m.lines->>'wc_xdate')::date, v_today), wc_carrier = coalesce(i.wc_carrier, m.lines->>'wc_carrier'),
      auto_xdate = public.next_renewal((m.lines->>'auto_xdate')::date, v_today), auto_carrier = coalesce(i.auto_carrier, m.lines->>'auto_carrier'),
      health_xdate = public.next_renewal((m.lines->>'health_xdate')::date, v_today), health_carrier = coalesce(i.health_carrier, m.lines->>'health_carrier'),
      dental_xdate = public.next_renewal((m.lines->>'dental_xdate')::date, v_today), dental_provider = coalesce(i.dental_provider, m.lines->>'dental_provider'),
      vision_xdate = public.next_renewal((m.lines->>'vision_xdate')::date, v_today), vision_provider = coalesce(i.vision_provider, m.lines->>'vision_provider'),
      prof_liab_xdate = public.next_renewal((m.lines->>'prof_liab_xdate')::date, v_today), prof_liab_carrier = coalesce(i.prof_liab_carrier, m.lines->>'prof_liab_carrier'),
      do_xdate = public.next_renewal((m.lines->>'do_xdate')::date, v_today), do_carrier = coalesce(i.do_carrier, m.lines->>'do_carrier'),
      eo_xdate = public.next_renewal((m.lines->>'eo_xdate')::date, v_today), eo_carrier = coalesce(i.eo_carrier, m.lines->>'eo_carrier'),
      homeowner_xdate = public.next_renewal((m.lines->>'homeowner_xdate')::date, v_today), homeowner_carrier = coalesce(i.homeowner_carrier, m.lines->>'homeowner_carrier'),
      personal_auto_xdate = public.next_renewal((m.lines->>'personal_auto_xdate')::date, v_today), personal_auto_carrier = coalesce(i.personal_auto_carrier, m.lines->>'personal_auto_carrier'),
      personal_lines_xdate = public.next_renewal((m.lines->>'personal_lines_xdate')::date, v_today), personal_lines_carrier = coalesce(i.personal_lines_carrier, m.lines->>'personal_lines_carrier'),
      agency_name = coalesce(i.agency_name, m.lines->>'agency_name'),
      -- Its Ultimate X-date: on DB Dev left blank, for the lead managers to set; on the appointment project, the renewal.
      ultimate_xdate = case when p_to = 'appt' then m.renewal else null end
    where i.lead_id = m.lead_id;

    if p_to = 'dbdev' then
      update public.leads set result_id = v_staged, call_result_dbdv = 'Viable-Staged', call_weight = 0, resolved_at = null,
             matched_at = now(), matched_from_lead_id = m.source_lead_id, matched_by = v_me
       where id = m.lead_id;
    elsif v_type = 'DBDV' then
      -- On to the appointment project as a lead, nobody's developed one.
      update public.leads set
        stage = 'appt', project_id = p.appt_project_id, source_project_id = coalesce(source_project_id, p.id),
        dbdv_user_id = null, assigned_user_id = public.least_loaded_rep(p.appt_project_id),
        result_id = v_lead_result.id, call_result_appt = v_lead_result.name, call_weight = 0,
        promoted_at = now(), resolved_at = null,
        matched_at = now(), matched_from_lead_id = m.source_lead_id, matched_by = v_me
       where id = m.lead_id;
    else
      -- Already on an appointment project: a lead there now.
      update public.leads set result_id = v_lead_result.id, call_result_appt = v_lead_result.name, call_weight = 0, resolved_at = null,
             matched_at = now(), matched_from_lead_id = m.source_lead_id, matched_by = v_me
       where id = m.lead_id;
    end if;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke execute on function public.add_matches(bigint, bigint[], text) from public, anon;
grant execute on function public.add_matches(bigint, bigint[], text) to authenticated;

-- ==============================================================================================================
-- 20270104100000_phone_calls.sql
-- ==============================================================================================================

-- Call Activity (Nov 2026): the calls made and taken on the phone's Twilio line, by person, as the
-- Streams call report had them, on the administrators' and account managers' dashboards as the day goes.
--
--   phone_calls            one row per person per call: Twilio says how each leg went
--                          (app/api/twilio/voice?step=status) as it rings, is answered and ends
--   phone_call_event()     what the server writes them with (the server's own key)
--   phone_call_report()    each person's calls over some days, for the dashboard's card
--
-- A call out is the leg to the number dialed; a call in, one leg for each browser it rang (the first to
-- answer takes it), and one row for the call in itself, with no one's name, its call_sid its parent_sid:
-- counted missed by no one in particular when it rang nobody (no one had the phone open).
--
-- Safe to run more than once.

create table if not exists public.phone_calls (
  id            bigint generated always as identity primary key,
  call_sid      text not null unique,
  parent_sid    text,
  user_id       bigint references public.users(id) on delete set null,
  direction     text not null check (direction in ('out', 'in')),
  number        text,
  status        text not null,
  started_at    timestamptz not null default now(),
  rang_at       timestamptz,
  answered_at   timestamptz,
  ended_at      timestamptz,
  talk_seconds  integer not null default 0 check (talk_seconds >= 0)
);

create index if not exists phone_calls_started_idx on public.phone_calls (started_at);
create index if not exists phone_calls_user_idx on public.phone_calls (user_id, started_at);
create index if not exists phone_calls_parent_idx on public.phone_calls (parent_sid);

alter table public.phone_calls enable row level security;
revoke all on public.phone_calls from anon, authenticated;
grant select on public.phone_calls to service_role;

/**
 * A leg's news from Twilio: its status (initiated, ringing, in-progress, then completed, busy,
 * no-answer, failed or canceled) and, once completed, how long it was answered for. The news can
 * come in any order, more than once: a leg that has ended stays as it ended.
 */
create or replace function public.phone_call_event(
  p_sid text, p_parent text, p_user bigint, p_direction text, p_number text, p_status text, p_duration integer
) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_ended  boolean := p_status in ('completed', 'busy', 'no-answer', 'failed', 'canceled');
  v_talk   integer := case when p_status = 'completed' then greatest(coalesce(p_duration, 0), 0) else 0 end;
begin
  insert into public.phone_calls as c (call_sid, parent_sid, user_id, direction, number, status, rang_at, answered_at, ended_at, talk_seconds)
  values (
    p_sid, p_parent, p_user, p_direction, p_number, p_status,
    case when p_status in ('ringing', 'in-progress', 'completed') then now() end,
    case when p_status = 'in-progress' then now() when p_status = 'completed' then now() - make_interval(secs => v_talk) end,
    case when v_ended then now() end,
    v_talk
  )
  on conflict (call_sid) do update set
    parent_sid   = coalesce(c.parent_sid, excluded.parent_sid),
    user_id      = coalesce(c.user_id, excluded.user_id),
    number       = coalesce(c.number, excluded.number),
    status       = case when c.ended_at is null then excluded.status else c.status end,
    rang_at      = coalesce(c.rang_at, excluded.rang_at),
    answered_at  = coalesce(c.answered_at, excluded.answered_at),
    ended_at     = coalesce(c.ended_at, excluded.ended_at),
    talk_seconds = case when c.ended_at is null then excluded.talk_seconds else c.talk_seconds end;
end $$;

revoke execute on function public.phone_call_event(text, text, bigint, text, text, text, integer) from public, anon, authenticated;
grant execute on function public.phone_call_event(text, text, bigint, text, text, text, integer) to service_role;

/**
 * Each person's calls over the business's days p_from..p_to, as the Streams report counts them:
 *   out_handled    calls out answered            out_cancelled  calls out not answered (busy, no answer, hung up first)
 *   in_handled     calls in they answered        missed         calls in that rang them and nobody answered
 *   talk_seconds   time on calls answered        on_call        on an answered call now
 * total is the four together. Every active account manager, with calls or not, and anyone else with
 * calls; then, with no one's name, the calls in that rang nobody at all. Administrators and managers.
 */
create or replace function public.phone_call_report(p_from date, p_to date)
returns table (
  user_id bigint, first_name text, last_name text, role text,
  total bigint, out_handled bigint, out_cancelled bigint, in_handled bigint, missed bigint,
  talk_seconds bigint, on_call boolean
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz text := public.business_tz();
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only administrators and account managers see call activity' using errcode = '42501';
  end if;
  return query
  with c as (
    select pc.user_id, pc.call_sid, pc.parent_sid, pc.talk_seconds, pc.answered_at, pc.ended_at, pc.started_at,
           case
             when pc.direction = 'out' then
               case when pc.answered_at is not null then 'out_handled' when pc.ended_at is not null then 'out_cancelled' end
             -- The call in itself (no one's): missed by no one in particular when it ended having rung nobody.
             when pc.user_id is null then
               case when pc.call_sid = pc.parent_sid and pc.ended_at is not null
                     and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.call_sid and s.call_sid <> pc.call_sid and s.rang_at is not null)
                 then 'missed' end
             when pc.answered_at is not null then 'in_handled'
             -- A person's leg: missed when it rang them and nobody took the call.
             when pc.ended_at is not null and pc.rang_at is not null
                  and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.parent_sid and s.answered_at is not null)
               then 'missed'
           end as kind
      from public.phone_calls pc
     where pc.started_at >= (p_from::timestamp at time zone v_tz)
       and pc.started_at <  ((p_to + 1)::timestamp at time zone v_tz)
  ),
  people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where (u.role = 'manager' and u.status = 'active')
        or u.id in (select c.user_id from c where c.kind is not null)
  )
  select p.id, p.first_name, p.last_name, p.role,
         count(c.kind),
         count(*) filter (where c.kind = 'out_handled'),
         count(*) filter (where c.kind = 'out_cancelled'),
         count(*) filter (where c.kind = 'in_handled'),
         count(*) filter (where c.kind = 'missed'),
         coalesce(sum(c.talk_seconds) filter (where c.kind in ('out_handled', 'in_handled')), 0)::bigint,
         coalesce(bool_or(c.answered_at is not null and c.ended_at is null and c.started_at > now() - interval '4 hours'), false)
    from people p
    left join c on c.user_id = p.id
   group by p.id, p.first_name, p.last_name, p.role
  union all
  select null, null, null, null, count(*), 0, 0, 0, count(*), 0, false
    from c
   where c.user_id is null and c.call_sid = c.parent_sid and c.kind = 'missed'
  having count(*) > 0;
end $$;

revoke execute on function public.phone_call_report(date, date) from public, anon;
grant execute on function public.phone_call_report(date, date) to authenticated;

-- ==============================================================================================================
-- 20270105100000_match_results.sql
-- ==============================================================================================================

-- The Match Tool (Sean, Nov 2026): a record elsewhere is a match's source only when its own call
-- result qualifies; Lead-Disco#, Out of Business and invalid ones don't. The results left out are an
-- administrator's choice on the Match Tool page (app_settings 'match_results': { "exclude": [names] }),
-- a result's name standing for it on both DB Dev and Appt lists; until chosen, those below.
--
-- match_summary() counts each project's matches by the month and year of their next renewal
-- ("2026-11"), not the month alone: the rest of this November and next November a year off are
-- two months, so "the next three months" are those three.
--
-- Safe to run more than once.

create or replace function public.match_excluded_results()
returns text[] language sql stable security definer set search_path = public as $$
  select coalesce(
    (select array(select jsonb_array_elements_text(s.value->'exclude')) from public.app_settings s where s.key = 'match_results'),
    array['Disco#', 'Lead-Disco#', 'Out of Business', 'Lead-Out of Business', 'Lead-Invalid', 'Appointment-Invalid']);
$$;
revoke execute on function public.match_excluded_results() from public, anon;
grant execute on function public.match_excluded_results() to authenticated;

create or replace function public.project_matches_raw(p_project bigint, p_today date)
returns table (lead_id bigint, company text, city text, state text, zip text, phone text,
               source_lead_id bigint, source_project text, source_client text, matched_by text,
               renewal date, lines jsonb)
language sql stable security definer set search_path = public set work_mem = '64MB' as $$
  with p as (
    select pr.id, pr.appt_project_id from public.projects pr where pr.id = p_project
  ), family as (
    select p.id from p
    union select p.appt_project_id from p where p.appt_project_id is not null
    union select pr.id from public.projects pr, p where pr.appt_project_id = p.id
  ), targets as (
    select l.id, l.company_name, l.city, l.state, l.zip, l.phone,
           public.phone_key(l.phone) as pk, public.business_key(l.company_name) as nk,
           left(btrim(l.zip), 5) as z5, lower(btrim(l.city)) as ck, upper(btrim(l.state)) as sk
      from public.leads l
      join public.call_results r on r.id = l.result_id and r.viable
     where l.project_id = p_project and l.deleted_at is null and l.matched_at is null
       and not exists (select 1 from public.insurance_details i where i.lead_id = l.id
                        and coalesce(i.ultimate_xdate, i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate, i.vision_xdate,
                                     i.prof_liab_xdate, i.do_xdate, i.eo_xdate, i.homeowner_xdate, i.personal_auto_xdate, i.personal_lines_xdate) is not null)
  )
  select t.id, t.company_name, t.city, t.state, t.zip, t.phone,
         m.id, m.project, m.client, m.how,
         public.next_renewal(m.renewal, p_today),
         m.lines
    from targets t
    cross join lateral (
      select s.id, sp.name as project, co.name as client, c.how, c.renewal, c.lines
        from (
          select s.id, 'phone' as how from public.leads s
           where t.pk is not null and public.phone_key(s.phone) = t.pk and s.deleted_at is null
          union
          select s.id, 'name' from public.leads s
           where t.nk is not null and public.business_key(s.company_name) = t.nk and s.deleted_at is null
             and ((t.z5 <> '' and left(btrim(s.zip), 5) = t.z5)
                  or (t.ck <> '' and lower(btrim(s.city)) = t.ck and upper(btrim(s.state)) = t.sk))
        ) hit
        join public.leads s on s.id = hit.id
        -- Not a record whose own call result says it's no use (Lead-Disco#, invalid…: Sean, Nov 2026).
        join public.call_results sr on sr.id = s.result_id and sr.name <> all (public.match_excluded_results())
        join public.projects sp on sp.id = s.project_id
        left join public.companies co on co.id = sp.company_id
        join public.insurance_details i on i.lead_id = s.id
        cross join lateral (
          select hit.how,
                 coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate, i.vision_xdate,
                                                  i.prof_liab_xdate, i.do_xdate, i.eo_xdate, i.homeowner_xdate, i.personal_auto_xdate, i.personal_lines_xdate)) as renewal,
                 jsonb_strip_nulls(jsonb_build_object(
                   'ultimate_xdate', i.ultimate_xdate,
                   'pkg_xdate', i.pkg_xdate, 'pkg_carrier', i.pkg_carrier, 'wc_xdate', i.wc_xdate, 'wc_carrier', i.wc_carrier,
                   'auto_xdate', i.auto_xdate, 'auto_carrier', i.auto_carrier, 'health_xdate', i.health_xdate, 'health_carrier', i.health_carrier,
                   'dental_xdate', i.dental_xdate, 'dental_provider', i.dental_provider, 'vision_xdate', i.vision_xdate, 'vision_provider', i.vision_provider,
                   'prof_liab_xdate', i.prof_liab_xdate, 'prof_liab_carrier', i.prof_liab_carrier, 'do_xdate', i.do_xdate, 'do_carrier', i.do_carrier,
                   'eo_xdate', i.eo_xdate, 'eo_carrier', i.eo_carrier, 'homeowner_xdate', i.homeowner_xdate, 'homeowner_carrier', i.homeowner_carrier,
                   'personal_auto_xdate', i.personal_auto_xdate, 'personal_auto_carrier', i.personal_auto_carrier,
                   'personal_lines_xdate', i.personal_lines_xdate, 'personal_lines_carrier', i.personal_lines_carrier,
                   'agency_name', i.agency_name)) as lines
        ) c
       where s.project_id not in (select id from family) and c.renewal is not null
       order by (hit.how = 'phone') desc, (i.ultimate_xdate is not null) desc, s.updated_at desc, s.id desc
       limit 1
    ) m;
$$;
revoke execute on function public.project_matches_raw(bigint, date) from public, anon, authenticated;

create or replace function public.match_summary()
returns table (project_id bigint, project text, type text, client text, status text, start_date date, due_date date,
               lead_goal int, leads bigint, developed bigint, matched bigint, matches bigint, by_month jsonb)
language plpgsql stable security definer set search_path = public set work_mem = '64MB' as $$
declare
  v_today date := (now() at time zone public.business_tz())::date;
begin
  if not public.is_admin() then
    raise exception 'The Match Tool is for administrators' using errcode = '42501';
  end if;
  return query
  with pr as (
    select p.id, p.name, t.code, co.name as client, ps.name as status, p.start_date, p.end_date, p.lead_goal
      from public.projects p
      join public.project_statuses ps on ps.id = p.status_id and ps.name = 'Active'
      left join public.project_types t on t.id = p.project_type_id
      left join public.companies co on co.id = p.company_id
     where p.deleted_at is null and (co.id is null or co.deleted_at is null)
  ), counts as (
    -- A lead counts to the project it was developed on (its DB Dev project once sent on).
    select coalesce(l.source_project_id, l.project_id) as pid,
           count(*) filter (where l.promoted_at is not null or (l.matched_at is not null and l.stage = 'appt')) as leads
      from public.leads l
     where l.deleted_at is null and coalesce(l.source_project_id, l.project_id) in (select id from pr)
     group by 1
  ), since as (
    select pr.id,
           (select count(*) from public.leads l
             where l.deleted_at is null and coalesce(l.source_project_id, l.project_id) = pr.id
               and l.promoted_at is not null and l.matched_at is null and l.dbdv_user_id is not null
               and (pr.start_date is null or l.promoted_at >= (pr.start_date::timestamp at time zone public.business_tz()))) as developed,
           (select count(*) from public.leads l
             where l.deleted_at is null and coalesce(l.source_project_id, l.project_id) = pr.id and l.matched_at is not null
               and (pr.start_date is null or l.matched_at >= (pr.start_date::timestamp at time zone public.business_tz()))) as matched
      from pr
  ), m as (
    select pr.id, count(x.*) as n,
           coalesce(jsonb_object_agg(x.mon, x.k) filter (where x.mon is not null), '{}') as by_month
      from pr
      left join lateral (
        select to_char(mm.renewal, 'YYYY-MM') as mon, count(*) as k
          from public.project_matches_raw(pr.id, v_today) mm group by 1
      ) x on true
     group by pr.id
  )
  select pr.id, pr.name, pr.code, pr.client, pr.status, pr.start_date, pr.end_date, pr.lead_goal,
         coalesce(c.leads, 0), s.developed, s.matched,
         coalesce((select sum(v::bigint) from jsonb_each_text(m.by_month) e(k, v)), 0)::bigint, m.by_month
    from pr
    join since s on s.id = pr.id
    join m on m.id = pr.id
    left join counts c on c.pid = pr.id
   order by pr.client, pr.name;
end $$;
revoke execute on function public.match_summary() from public, anon;
grant execute on function public.match_summary() to authenticated;

-- ==============================================================================================================
-- 20270105100000_voicemail_transcripts.sql
-- ==============================================================================================================

-- A voicemail's transcript (Nov 2026): Twilio writes out what was said in a voicemail on the phone's
-- number (app/api/twilio/voice?step=transcribed), a minute or so after it was left, and it is added to
-- the voicemail's notifications ("Transcript: …", a line of its own at the end), where the notification
-- page shows it under the recording. Once only; the server's own key only.
--
-- Safe to run more than once.

create or replace function public.phone_voicemail_transcript(p_recording text, p_text text)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer;
begin
  if p_recording !~ '^RE[0-9a-fA-F]{32}$' or nullif(btrim(p_text), '') is null then
    return 0;
  end if;
  update public.notifications
     set body = left(body || E'\nTranscript: ' || btrim(p_text), 6000)
   where kind = 'system'
     and title like 'Voicemail from %'
     and strpos(body, '/api/phone/recordings/' || p_recording) > 0
     and strpos(body, E'\nTranscript: ') = 0;
  get diagnostics v_count = row_count;
  return v_count;
end $$;

revoke execute on function public.phone_voicemail_transcript(text, text) from public, anon, authenticated;
grant execute on function public.phone_voicemail_transcript(text, text) to service_role;

-- ==============================================================================================================
-- 20270106100000_xdate_warning_any_year.sql
-- ==============================================================================================================

-- The X-date 30-day warning, whatever year the X-date carries (Sean, Nov 2026). The team goes by
-- the month and day: a rep may type 2027 for a December renewal developed today, and old records
-- keep a past year. Every other part of the app reads a renewal by its month (and day) already;
-- this warning matched the whole date, so it missed those. It now matches the month and day, a
-- Feb 29 renewal warned of on Feb 28 in a year without one.
--
--   renews_on(xdate, day)   whether an X-date falls on `day`'s month and day, any year
--
-- Safe to run more than once.

create or replace function public.renews_on(p_xdate date, p_day date)
returns boolean language sql immutable parallel safe set search_path = '' as $$
  select p_xdate is not null and (
    to_char(p_xdate, 'MM-DD') = to_char(p_day, 'MM-DD')
    -- Feb 28 in a year without a 29th stands for the 29th too.
    or (to_char(p_day, 'MM-DD') = '02-28' and to_char(p_day + 1, 'MM-DD') = '03-01' and to_char(p_xdate, 'MM-DD') = '02-29'))
$$;

do $$
declare
  v_def text := pg_get_functiondef('public.send_xdate_warnings(date)'::regprocedure);
begin
  if position('renews_on' in v_def) = 0 then
    if position('and coalesce(i.ultimate_xdate, least(' in v_def) = 0 or position('i.eo_xdate)) = v_due' in v_def) = 0 then
      raise exception 'send_xdate_warnings is not as expected';
    end if;
    v_def := replace(v_def, 'and coalesce(i.ultimate_xdate, least(', 'and public.renews_on(coalesce(i.ultimate_xdate, least(');
    v_def := replace(v_def, 'i.eo_xdate)) = v_due', 'i.eo_xdate)), v_due)');
    execute v_def;
  end if;
end $$;

-- ==============================================================================================================
-- 20270107100000_search_capped_counts.sql
-- ==============================================================================================================

-- Search, faster (Nov 2026). The leads are found by search_lead_hits() below, newest first, and
-- not counted past the few shown (the palette says "5+"); every other kind of record is counted to
-- 101 at most ("100+"). So a common word ("Phoenix", "Inc") no longer reads every lead it is on.

create index if not exists leads_newest on public.leads (lead_date desc nulls last, id desc) where deleted_at is null;
--
-- Safe to run more than once.

-- The leads' part, in a function of its own. Row Level Security keeps Postgres from using the
-- trigram index on leads.search_text (LIKE is not "leakproof", so it may not run before the policy),
-- which made every lead search read the whole table: 0.5 ms with the index, 170-250 ms without it
-- on 300,000 leads. This runs as its owner, with the policy's own rule written into the query
-- (signed in, past the authenticator check, and staff or one of a client's own projects), so the
-- index is used and the same leads are found. Planned with the words themselves (not parameters),
-- so a rare word goes by the trigram index and a common one walks leads_newest to its fifth.
create or replace function public.search_lead_hits(p_first text, p_pats text[], p_n int)
returns table (total bigint, items jsonb)
language plpgsql stable security definer set search_path = public, extensions as $$
declare
  v_seen text := '(select public.app_user_id()) is not null and (select public.mfa_satisfied())
                  and ((select public.is_staff()) or l.project_id in (select public.client_project_ids()))';
begin
  execute format($q$
    select coalesce(jsonb_agg(x order by x.lead_date desc nulls last, x.id desc), '[]'::jsonb) from (
      select l.id, l.lead_date, l.company_name as title, l.contact_name as contact,
             nullif(concat_ws(', ', l.city, l.state), '') as place, l.phone,
             co.name as client, s.name as status
        from (select l.* from public.leads l
               where l.deleted_at is null and %s and l.search_text like %L and l.search_text like all (%L::text[])
               order by l.lead_date desc nulls last, l.id desc
               limit %s) l
        left join public.projects p on p.id = l.project_id
        left join public.companies co on co.id = p.company_id
        left join public.lead_statuses s on s.id = l.status_id) x$q$, v_seen, p_first, p_pats, greatest(least(coalesce(p_n, 5), 20), 1))
    into items;
  -- Not counted beyond them (Nov 2026): counting a common word's matches cost far more than finding
  -- the newest few. Fewer than asked for are all there are; otherwise "more" (null), and the Leads list counts them.
  total := case when jsonb_array_length(items) < greatest(least(coalesce(p_n, 5), 20), 1) then jsonb_array_length(items) end;
  return next;
end $$;
revoke execute on function public.search_lead_hits(text, text[], int) from public, anon;
grant execute on function public.search_lead_hits(text, text[], int) to authenticated;

CREATE OR REPLACE FUNCTION public.global_search(q text, per_group integer DEFAULT 5, groups text[] DEFAULT ARRAY['leads'::text, 'clients'::text, 'projects'::text, 'users'::text, 'documents'::text, 'carriers'::text])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_words text[] := public.search_words(q);
  v_pats  text[] := public.search_patterns(v_words);
  v_first text   := public.search_lead_pattern(v_words);
  v_n     int    := greatest(least(coalesce(per_group, 5), 20), 1);
  v_out   jsonb  := '{}'::jsonb;
  v_items jsonb;
  v_total bigint;
begin
  if cardinality(v_words) = 0 then
    return v_out;
  end if;

  if 'leads' = any(groups) then
    -- The leads through search_lead_hits(), which can use the trigram index (see above).
    select h.total, h.items into v_total, v_items from public.search_lead_hits(v_first, v_pats, v_n) h;
    v_out := v_out || jsonb_build_object('leads', jsonb_build_object('total', v_total, 'items', v_items));
  end if;

  if 'clients' = any(groups) then
    with hits as (
      select c.* from public.companies c
       where public.search_doc(concat_ws(' ', c.name, c.contact_name, c.city, c.state)) like all (v_pats)
    )
    select (select count(*) from (select 1 from hits limit 101) capped), (select coalesce(jsonb_agg(x order by x.title), '[]'::jsonb) from (
             select h.id, h.name as title, h.contact_name as contact, nullif(concat_ws(', ', h.city, h.state), '') as place,
                    (select count(*) from public.projects p where p.company_id = h.id) as projects
               from hits h order by h.name limit v_n) x)
      into v_total, v_items;
    v_out := v_out || jsonb_build_object('clients', jsonb_build_object('total', v_total, 'items', v_items));
  end if;

  if 'projects' = any(groups) then
    with hits as (
      select p.id, p.name, coalesce(c.name, p.client_name) as client, ps.name as status, t.code as type
        from public.projects p
        left join public.companies c on c.id = p.company_id
        left join public.project_statuses ps on ps.id = p.status_id
        left join public.project_types t on t.id = p.project_type_id
       where public.search_doc(concat_ws(' ', p.name, p.client_name, c.name)) like all (v_pats)
    )
    select (select count(*) from (select 1 from hits limit 101) capped), (select coalesce(jsonb_agg(x order by x.title), '[]'::jsonb) from (
             select h.id, h.name as title, h.client, h.status, h.type from hits h order by h.name limit v_n) x)
      into v_total, v_items;
    v_out := v_out || jsonb_build_object('projects', jsonb_build_object('total', v_total, 'items', v_items));
  end if;

  if 'users' = any(groups) then
    with hits as (
      select u.* from public.users u
       where public.search_doc(concat_ws(' ', u.first_name, u.last_name, u.email)) like all (v_pats)
    )
    select (select count(*) from (select 1 from hits limit 101) capped), (select coalesce(jsonb_agg(x order by x.title), '[]'::jsonb) from (
             select h.id, coalesce(nullif(concat_ws(' ', h.first_name, h.last_name), ''), h.email) as title,
                    h.email, h.role, h.status
               from hits h order by h.first_name, h.last_name limit v_n) x)
      into v_total, v_items;
    v_out := v_out || jsonb_build_object('users', jsonb_build_object('total', v_total, 'items', v_items));
  end if;

  if 'documents' = any(groups) then
    with hits as (
      select d.id, d.name, d.file_type, d.created_at, c.name as client
        from public.documents d
        left join public.companies c on c.id = d.company_id
       where public.search_doc(concat_ws(' ', d.name, c.name)) like all (v_pats)
    )
    select (select count(*) from (select 1 from hits limit 101) capped), (select coalesce(jsonb_agg(x order by x.created_at desc), '[]'::jsonb) from (
             select h.id, h.name as title, h.file_type, h.client, h.created_at from hits h order by h.created_at desc limit v_n) x)
      into v_total, v_items;
    v_out := v_out || jsonb_build_object('documents', jsonb_build_object('total', v_total, 'items', v_items));
  end if;

  if 'carriers' = any(groups) then
    with hits as (
      select a.* from public.agencies a
       where public.search_doc(concat_ws(' ', a.name, a.association)) like all (v_pats)
    )
    select (select count(*) from (select 1 from hits limit 101) capped), (select coalesce(jsonb_agg(x order by x.title), '[]'::jsonb) from (
             select h.id, h.name as title, h.association from hits h order by h.name limit v_n) x)
      into v_total, v_items;
    v_out := v_out || jsonb_build_object('carriers', jsonb_build_object('total', v_total, 'items', v_items));
  end if;

  return v_out;
end $function$;

-- ==============================================================================================================
-- 20270108100000_lead_search_view.sql
-- ==============================================================================================================

-- Searching the lists of leads, faster (Nov 2026). Row Level Security keeps Postgres from using
-- the trigram index on leads.search_text: LIKE is not "leakproof", so it may not run before the
-- policy, and every search of the Leads list, a project's leads or a picker read the whole table
-- (170-250 ms on 300,000 leads, against under 1 ms with the index; and the count read it again).
--
--   leads_searchable   the leads a person may see, as the policy has them (signed in, past the
--                      authenticator check, and staff or one of a client's own projects; not
--                      deleted), read as its owner so the index is used. Read-only. The app reads
--                      it in place of leads when something is typed in a search box, with every
--                      other filter, the related records, the order, the page and the count as before.
--
-- Not a security barrier, so filters reach the index: a person's filters are the API's own
-- comparisons on these columns, which leak nothing; the rows that come back are only those the
-- rule lets them see. Every column of leads is theirs to read already (no column grants).
--
-- Safe to run more than once.

create or replace view public.leads_searchable as
  select l.*
    from public.leads l
   where l.deleted_at is null
     and (select public.app_user_id()) is not null
     and (select public.mfa_satisfied())
     and ((select public.is_staff()) or l.project_id in (select public.client_project_ids()));

revoke all on public.leads_searchable from public, anon;
grant select on public.leads_searchable to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270109100000_last_worked_is_called.sql
-- ==============================================================================================================

-- Last worked is last called (Sean, Nov 2026): the Lead Explorer's Last worked (lead_explore's
-- last_worked) was the later of a lead's last call and its last change, so a list just imported, or
-- names brought over from the Match Tool, read as worked the day they came, while the lead's own page
-- said "Not yet". It is the last call only, as the lead's page and the Leads list have it: imported,
-- transferred or edited is not worked. Nothing else in lead_explore changes.
--
-- Safe to run more than once.

do $$
declare
  v_def text;
begin
  v_def := pg_get_functiondef('public.lead_explore(jsonb,integer,integer)'::regprocedure);
  if position('greatest(l.date_last_worked, l.updated_at) as last_worked' in v_def) > 0 then
    execute replace(v_def, 'greatest(l.date_last_worked, l.updated_at) as last_worked', 'l.date_last_worked as last_worked');
  elsif position('l.date_last_worked as last_worked' in v_def) = 0 then
    raise exception 'lead_explore is not as expected: its last_worked is neither the later of call and change nor the last call';
  end if;
end $$;

-- ==============================================================================================================
-- 20270110100000_reports_results_by_stage.sql
-- ==============================================================================================================

-- Reports: the call results by stage (client, Nov 2026).
--
-- The Reports tile listed every call result in one list, the appointment
-- stage's and DB Dev's mixed together, and the list grew so long it
-- stretched the 6-month chart beside it down the page. The tile now shows
-- one stage at a time; by_result counts each stage's results apart:
-- { "APPT": { "Appointment": 177, ... }, "DBDV": { "Lead-No Contact": 2515, ... } }.
-- by_status stays as it was, for the Command Center tile.
--
-- Safe to run again.

CREATE OR REPLACE FUNCTION public.report_stats()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with z as (
    select public.business_tz() as tz
  ), l as (
    select state, status_id, result_id, to_char(coalesce(lead_date, created_at) at time zone z.tz, 'YYYY-MM') as ym from public.leads, z
  ), a as (
    select status_id, to_char(appt_date, 'YYYY-MM') as ym from public.appointments where invalid_at is null
  ), f as (
    select rating, to_char(created_at at time zone z.tz, 'YYYY-MM') as ym from public.feedback, z where rating is not null
  ), months as (
    select i, date_trunc('month', now() at time zone z.tz) - (i * interval '1 month') as m
      from generate_series(0, 5) as i, z
  )
  select jsonb_build_object(
    'leads',          (select count(*) from l),
    'appts',          (select count(*) from a),
    'projects',       (select count(*) from public.projects),
    'held',           (select count(*) from a join public.appointment_statuses s on s.id = a.status_id where s.name = 'Held'),
    'ratings',        (select jsonb_build_object('count', count(rating), 'avg', coalesce(avg(rating), 0)) from f),
    -- Where the names stand, by call result (by name: the two stages share some).
    'by_status',      (select coalesce(jsonb_object_agg(c.name, c.n), '{}'::jsonb)
                         from (select r.name, count(*) as n from l join public.call_results r on r.id = l.result_id group by r.name) c),
    -- The same, each stage's results apart: { "APPT": {name: n}, "DBDV": {name: n} }.
    'by_result',      (select coalesce(jsonb_object_agg(t.project_type, t.results), '{}'::jsonb)
                         from (select c.project_type, jsonb_object_agg(c.name, c.n) as results
                                 from (select r.project_type, r.name, count(*) as n
                                         from l join public.call_results r on r.id = l.result_id
                                        group by r.project_type, r.name) c
                                group by c.project_type) t),
    'by_state',       (select coalesce(jsonb_agg(jsonb_build_array(t.state, t.n) order by t.n desc, t.state), '[]'::jsonb)
                         from (select state, count(*) as n from l where state is not null group by state order by n desc, state limit 8) t),
    'appt_by_status', (select coalesce(jsonb_object_agg(s.name, c.n), '{}'::jsonb)
                         from (select status_id, count(*) as n from a group by status_id) c
                         join public.appointment_statuses s on s.id = c.status_id),
    'months',         (select jsonb_agg(jsonb_build_object(
                          'key',    to_char(m.m, 'YYYY-MM'),
                          'label',  to_char(m.m, 'Mon'),
                          'leads',  (select count(*) from l where l.ym = to_char(m.m, 'YYYY-MM')),
                          'appts',  (select count(*) from a where a.ym = to_char(m.m, 'YYYY-MM')),
                          'rating', (select round(avg(f.rating), 1) from f where f.ym = to_char(m.m, 'YYYY-MM'))
                        ) order by m.i desc) from months m)
  );
$function$;

-- ==============================================================================================================
-- 20270111100000_explorer_managers_own_projects.sql
-- ==============================================================================================================

-- Lead Explorer for account managers (client, Nov 2026): only the projects they
-- are assigned to (project_assignments; a project they share counts), its
-- counts and its pickers too, and no more than a page at a time. They can't
-- export from it (the export route is the administrators' alone). Everyone
-- else as before. lead_explore and lead_explore_options as they were but for that.
--
-- Safe to run again.

CREATE OR REPLACE FUNCTION public.lead_explore(criteria jsonb DEFAULT '{}'::jsonb, page integer DEFAULT 1, per_page integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with seen as (
    -- A manager sees only the projects they are assigned to, shared ones too (client, Nov 2026); everyone else every project.
    select public.app_role() = 'manager' as limited,
           array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = public.app_user_id()) as ids
  ),
  c as (
    select
      array(select jsonb_array_elements_text(coalesce(criteria->'sic',       '[]'::jsonb)))          as sic,
      array(select jsonb_array_elements_text(coalesce(criteria->'states',    '[]'::jsonb)))          as states,
      array(select jsonb_array_elements_text(coalesce(criteria->'zips',      '[]'::jsonb)))          as zips,
      array(select jsonb_array_elements_text(coalesce(criteria->'counties',  '[]'::jsonb)))          as counties,
      array(select jsonb_array_elements_text(coalesce(criteria->'results',   '[]'::jsonb)))          as results,
      array(select (jsonb_array_elements_text(coalesce(criteria->'months',   '[]'::jsonb)))::int)    as months,
      array(select (jsonb_array_elements_text(coalesce(criteria->'clients',  '[]'::jsonb)))::bigint) as clients,
      array(select (jsonb_array_elements_text(coalesce(criteria->'projects', '[]'::jsonb)))::bigint) as projects,
      array(select (jsonb_array_elements_text(coalesce(criteria->'groups',   '[]'::jsonb)))::bigint) as groups,
      array(select jsonb_array_elements_text(coalesce(criteria->'carriers',  '[]'::jsonb)))          as carriers,
      array(select (jsonb_array_elements_text(coalesce(criteria->'reps',     '[]'::jsonb)))::bigint) as reps,
      case when criteria->>'emp_min' ~ '^\d{1,7}$' then (criteria->>'emp_min')::int end           as emp_min,
      case when criteria->>'emp_max' ~ '^\d{1,7}$' then (criteria->>'emp_max')::int end           as emp_max,
      coalesce(criteria->>'emp_not', '') = '1'                                                  as emp_not,
      public.search_patterns(public.search_words(criteria->>'q'))    as pats,
      public.search_lead_pattern(public.search_words(criteria->>'q')) as first_pat
  ),
  carrier_keys as (
    select coalesce(array_agg(distinct k) filter (where k is not null), '{}') as keys
      from (
        select public.carrier_key(v) as k from c, unnest(c.carriers) v where v !~ '^[0-9]+$'
        union all
        select public.carrier_key(a.name) from public.agencies a, c
         where a.id::text = any(array(select v from unnest(c.carriers) v where v ~ '^[0-9]{1,18}$'))
      ) t
  ),
  m as (
    select l.id, l.company_name, l.contact_name, l.contact_title, l.phone, l.contact_mobile, l.email,
           l.decision_maker, l.dm_title, l.dm_phone, l.dm_mobile, l.dm_email,
           l.contact2_name, l.contact2_title, l.contact2_phone, l.contact2_mobile, l.contact2_email, l.producer_name,
           l.city, l.state, l.zip, l.county, l.sic_code, l.lead_date,
           ins.ultimate_xdate,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name, grp.name as agency_group,
           coalesce(ag.name, nullif(btrim(ins.agency_name), '')) as carrier_name,
           r.id as result_id, r.name as result_name, r.viable as result_viable,
           l.project_id, p.name as project_name,
           -- When it was last called or changed.
           l.date_last_worked as last_worked,
           nullif(concat_ws(' ', u.first_name, u.last_name), '') as rep_name
      from public.leads l
      cross join c
      cross join carrier_keys ck
      cross join seen
      left join public.insurance_details ins on ins.lead_id = l.id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies grp on grp.id = co.agency_group_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.call_results r on r.id = l.result_id
      left join public.users u      on u.id  = l.assigned_user_id
     -- Leads that have been promoted to an appointment project: a name still being developed is not one yet,
     -- whatever renewal dates it carries.
     where l.stage = 'appt'
       and (not seen.limited or l.project_id = any(seen.ids))
       and (cardinality(c.sic)      = 0 or l.sic_code         = any(c.sic))
       and (cardinality(c.states)   = 0 or l.state            = any(c.states))
       and (cardinality(c.zips)     = 0 or left(l.zip, 5)     = any(c.zips))
       and (cardinality(c.counties) = 0 or l.county           = any(c.counties))
       and (cardinality(c.results)  = 0 or coalesce(r.name, 'Not called yet') = any(c.results))
       and (cardinality(c.clients)  = 0 or co.id              = any(c.clients))
       and (cardinality(c.projects) = 0 or l.project_id       = any(c.projects))
       and (cardinality(c.groups)   = 0 or co.agency_group_id = any(c.groups))
       and (cardinality(c.carriers) = 0 or public.carrier_key(coalesce(ag.name, ins.agency_name)) = any(ck.keys))
       and (cardinality(c.reps)     = 0 or l.assigned_user_id = any(c.reps))
       -- Employees (the total) in a range, or not in it; a lead with no count is in no range.
       and public.employees_in(jsonb_build_object('min', c.emp_min, 'max', c.emp_max, 'exclude', c.emp_not), l.employees)
       and (cardinality(c.months)   = 0 or extract(month from coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate,
              ins.health_xdate, ins.dental_xdate, ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)))::int = any(c.months))
       -- The longest word first, which the trigram index can answer; then every word.
       and (cardinality(c.pats)     = 0 or (l.search_text like c.first_pat and l.search_text like all (c.pats)))
  ),
  win as (
    select * from m
     order by lead_date desc nulls last, id desc
     limit greatest(least(coalesce(per_page, 10), (select case when limited then 100 else 10000 end from seen)), 1)
    offset least(greatest(coalesce(page, 1) - 1, 0)::bigint * greatest(least(coalesce(per_page, 10), (select case when limited then 100 else 10000 end from seen)), 1), 1000000000)
  )
  select jsonb_build_object(
    'total',    (select count(*) from m),
    'rows',     (select coalesce(jsonb_agg(to_jsonb(win)), '[]'::jsonb) from win),
    'by_client', (select coalesce(jsonb_agg(jsonb_build_object('id', t.client_id, 'label', coalesce(t.client_name, 'Unassigned'), 'count', t.n)
                                            order by t.n desc, coalesce(t.client_name, 'zzz')), '[]'::jsonb)
                    from (select client_id, client_name, count(*) as n from m group by client_id, client_name) t),
    'by_state',  (select coalesce(jsonb_agg(jsonb_build_object('label', coalesce(t.state, '—'), 'count', t.n)
                                            order by t.n desc, coalesce(t.state, 'zz')), '[]'::jsonb)
                    from (select state, count(*) as n from m group by state) t),
    'by_month',  (select coalesce(jsonb_agg(jsonb_build_object('month', t.mon, 'label', to_char(to_date(t.mon::text, 'MM'), 'Mon'), 'count', t.n)
                                            order by t.mon), '[]'::jsonb)
                    from (select extract(month from renewal_date)::int as mon, count(*) as n
                            from m where renewal_date is not null group by 1) t),
    'by_industry', (select coalesce(jsonb_agg(jsonb_build_object('code', t.sic_code, 'label', coalesce(s.description, t.sic_code, '—'), 'count', t.n)
                                              order by t.n desc), '[]'::jsonb)
                      from (select sic_code, count(*) as n from m group by sic_code) t
                      left join public.sic_codes s on s.code = t.sic_code),
    'by_result', (select coalesce(jsonb_agg(jsonb_build_object('label', t.label, 'count', t.n)
                                            order by t.n desc, t.label), '[]'::jsonb)
                    from (select coalesce(result_name, 'Not called yet') as label, count(*) as n from m group by 1) t),
    'clients_touched', (select count(distinct client_id) from m where client_id is not null),
    'with_xdate',      (select count(*) from m where renewal_date is not null),
    -- Still to call for an appointment: a call result that leaves the lead viable (none yet counts).
    'viable',          (select count(*) from m where coalesce(result_viable, true))
  );
$function$;

CREATE OR REPLACE FUNCTION public.lead_explore_options()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with seen as (
    -- A manager sees only the projects they are assigned to, shared ones too (client, Nov 2026); everyone else every project.
    select public.app_role() = 'manager' as limited,
           array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = public.app_user_id()) as ids
  ),
  l as (
    select l.* from public.leads l, seen where l.stage = 'appt' and (not seen.limited or l.project_id = any(seen.ids))
  ),
  co as (
    select c.* from public.companies c, seen
     where not seen.limited or c.id in (select p.company_id from public.projects p where p.id = any(seen.ids))
  )
  select jsonb_build_object(
    'industries', (select coalesce(jsonb_agg(jsonb_build_object('value', t.sic_code, 'label', coalesce(s.description, t.sic_code), 'count', t.n)
                                             order by t.n desc), '[]'::jsonb)
                     from (select sic_code, count(*) as n from l where sic_code is not null group by sic_code) t
                     left join public.sic_codes s on s.code = t.sic_code),
    'states',     (select coalesce(jsonb_agg(jsonb_build_object('value', t.state, 'label', t.state, 'count', t.n)
                                             order by t.state), '[]'::jsonb)
                     from (select state, count(*) as n from l where state is not null group by state) t),
    'counties',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.county, 'label', t.county, 'count', t.n)
                                             order by t.county), '[]'::jsonb)
                     from (select county, count(*) as n from l where county is not null group by county) t),
    'results',    (select coalesce(jsonb_agg(jsonb_build_object('value', t.label, 'label', t.label, 'count', t.n) order by t.n desc, t.label), '[]'::jsonb)
                     from (select coalesce(r.name, 'Not called yet') as label, count(*) as n
                             from l left join public.call_results r on r.id = l.result_id
                            group by 1) t),
    'clients',    (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', name) order by name), '[]'::jsonb)
                     from co),
    'projects',   (select coalesce(jsonb_agg(jsonb_build_object('value', p.id, 'label', p.name, 'count', t.n) order by p.name), '[]'::jsonb)
                     from (select project_id, count(*) as n from l where project_id is not null group by 1) t
                     join public.projects p on p.id = t.project_id),
    'groups',     (select coalesce(jsonb_agg(jsonb_build_object('value', g.id, 'label', g.name, 'count', t.n) order by g.name), '[]'::jsonb)
                     from (select agency_group_id, count(*) as n from co where agency_group_id is not null group by 1) t
                     join public.agencies g on g.id = t.agency_group_id),
    'carriers',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.k, 'label', t.label, 'count', t.n) order by t.k), '[]'::jsonb)
                     from (select k, (array_agg(label order by rec desc, label))[1] as label, sum(n)::bigint as n
                             from (select public.carrier_key(a.name) as k, btrim(a.name) as label, true as rec, 0 as n
                                     from public.agencies a
                                   union all
                                   select public.carrier_key(coalesce(ag.name, ins.agency_name)), btrim(coalesce(ag.name, ins.agency_name)), false, 1
                                     from l
                                     left join public.agencies ag on ag.id = l.agency_id
                                     left join public.insurance_details ins on ins.lead_id = l.id) x
                            where k is not null
                            group by k) t),
    'reps',       (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', nullif(concat_ws(' ', first_name, last_name), '')) order by first_name, last_name), '[]'::jsonb)
                     from public.users where role in ('admin', 'manager', 'agent'))
  );
$function$;

-- ==============================================================================================================
-- 20270112100000_list_builder_admins_clients.sql
-- ==============================================================================================================

-- List Builder for administrators and clients only (client, Nov 2026): account
-- managers (and agents, who never had the page) no longer read, make or change
-- list requests, nor make the links prospects fill in. A client still reads and
-- makes its own; a prospect's link still works (through its own function).
--
-- A request's Sales Rep is told of it only when they are an administrator: a
-- manager could not open it. The administrators are told, as before.
--
-- Safe to run again.

drop policy if exists list_requests_read on public.list_requests;
create policy list_requests_read on public.list_requests for select to authenticated
  using (public.is_admin() or (company_id is not null and company_id = public.app_company_id()));
drop policy if exists list_requests_insert on public.list_requests;
create policy list_requests_insert on public.list_requests for insert to authenticated
  with check (public.is_admin() or (source = 'client' and company_id = public.app_company_id()));
drop policy if exists list_requests_update on public.list_requests;
create policy list_requests_update on public.list_requests for update to authenticated
  using (public.is_admin() or (company_id = public.app_company_id() and status = 'new'))
  with check (public.is_admin() or (company_id = public.app_company_id() and status = 'new'));

drop policy if exists list_request_links_staff on public.list_request_links;
create policy list_request_links_staff on public.list_request_links for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create or replace function public.tg_list_requests_notify()
returns trigger
language plpgsql security definer set search_path = public as $$
declare
  v_who text := coalesce(
    (select c.name from public.companies c where c.id = new.company_id),
    nullif(btrim(concat_ws(' · ', new.prospect->>'company', new.prospect->>'name')), ''),
    'A prospect');
  -- The administrators (a Sales Rep among them told with them); a manager Sales Rep is not, having no List Builder.
  v_to bigint[] := array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null);
begin
  perform public.notify_users(
    v_to,
    'system',
    left(format('List request: %s', v_who), 160),
    concat_ws(' · ', coalesce(new.title, 'Industries and territory to target'),
      case new.source when 'prospect' then 'from a prospect''s link' when 'client' then 'from the client' else null end),
    '/list-builder/' || new.id,
    'list_request');
  return new;
end $$;

-- ==============================================================================================================
-- 20270113100000_program_funding.sql
-- ==============================================================================================================

-- Program Funding (client, Nov 2026): how a client pays for a project's program,
-- and the payments it makes: kept here, recorded in QuickBooks apart (for now).
--
--   project_funding   the plan (lib/funding.js): billed monthly for what we produce,
--                     installments (the first the first block of leads with the setup and
--                     list fees, the rest split evenly), or paid in advance; the leads and
--                     appointments bought, the fees, the payments and their day
--   project_payments  its payments: the installments (worked out by the app from the plan,
--                     saved with save_project_funding()), and each month's bill for what was
--                     produced (bill_project_months(), on the 1st: the month's leads and valid
--                     appointments at the project's rates, where the plan bills them monthly)
--
-- Seen by the administrators and the client's Sales Rep, who marks a payment paid
-- (set_payment_paid()). The Sales Rep is told 5 days before a payment is due, with how the
-- project is doing (send_payment_reminders(), with the daily alerts); the client is sent a
-- reminder only by them, and only when the client has payment reminders on
-- (companies.payment_reminders).
--
-- Safe to run again.

alter table public.companies
  add column if not exists payment_reminders boolean not null default false;
comment on column public.companies.payment_reminders is 'The Sales Rep may email this client reminders of payments due (Program Funding).';

create table if not exists public.project_funding (
  project_id     bigint primary key references public.projects(id) on delete cascade,
  plan           text not null default 'monthly' check (plan in ('monthly', 'installments', 'advance')),
  leads          integer not null default 0 check (leads between 0 and 10000000),
  appts          integer not null default 0 check (appts between 0 and 10000000),
  appts_included boolean not null default false,
  setup_fee      numeric(12, 2) not null default 0 check (setup_fee between 0 and 10000000),
  list_fee       numeric(12, 2) not null default 0 check (list_fee between 0 and 10000000),
  payments       integer not null default 1 check (payments between 1 and 36),
  first_leads    integer check (first_leads between 0 and 10000000),
  first_due      date,
  due_day        integer check (due_day between 1 and 28),
  updated_at     timestamptz not null default now(),
  updated_by     bigint references public.users(id) on delete set null
);

create table if not exists public.project_payments (
  id                 bigint generated always as identity primary key,
  project_id         bigint not null references public.projects(id) on delete cascade,
  kind               text not null check (kind in ('installment', 'monthly')),
  seq                integer,          -- an installment's place
  period             date,             -- a monthly bill's month (its first day)
  label              text not null,
  due_date           date,
  amount             numeric(12, 2) not null check (amount >= 0),
  leads              integer not null default 0,
  appts              integer not null default 0,
  fees               numeric(12, 2) not null default 0,
  paid_at            timestamptz,
  paid_by            bigint references public.users(id) on delete set null,
  rep_reminded_at    timestamptz,
  client_reminded_at timestamptz,
  created_at         timestamptz not null default now(),
  check ((kind = 'installment' and seq is not null) or (kind = 'monthly' and period is not null))
);
create unique index if not exists project_payments_installment on public.project_payments (project_id, seq) where kind = 'installment';
create unique index if not exists project_payments_month on public.project_payments (project_id, period) where kind = 'monthly';
create index if not exists project_payments_due on public.project_payments (due_date) where paid_at is null;

-- Who sees a project's funding: the administrators, and its client's Sales Rep.
create or replace function public.sees_project_funding(p_project bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (
    select 1 from public.projects p join public.companies c on c.id = p.company_id
     where p.id = p_project and c.sales_rep_id is not null and c.sales_rep_id = public.app_user_id());
$$;
revoke execute on function public.sees_project_funding(bigint) from public, anon;
grant execute on function public.sees_project_funding(bigint) to authenticated;

alter table public.project_funding enable row level security;
drop policy if exists project_funding_read on public.project_funding;
create policy project_funding_read on public.project_funding for select to authenticated using (public.sees_project_funding(project_id));
grant select on public.project_funding to authenticated;

alter table public.project_payments enable row level security;
drop policy if exists project_payments_read on public.project_payments;
create policy project_payments_read on public.project_payments for select to authenticated using (public.sees_project_funding(project_id));
grant select on public.project_payments to authenticated;

-- An administrator saves a project's plan and its installments (worked out by the app). Payments
-- already paid stay as they were; the rest take the new schedule (a reminder already sent kept
-- while the date and amount are the same); installments past the new count, unpaid, go.
create or replace function public.save_project_funding(p_project bigint, p_funding jsonb, p_payments jsonb)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
  v_count integer := 0;
  r jsonb;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator sets a program''s funding' using errcode = '42501';
  end if;
  if not exists (select 1 from public.projects where id = p_project) then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;

  insert into public.project_funding as f (project_id, plan, leads, appts, appts_included, setup_fee, list_fee, payments, first_leads, first_due, due_day, updated_at, updated_by)
  values (p_project, coalesce(p_funding->>'plan', 'monthly'), coalesce((p_funding->>'leads')::int, 0), coalesce((p_funding->>'appts')::int, 0),
          coalesce((p_funding->>'appts_included')::boolean, false), coalesce((p_funding->>'setup_fee')::numeric, 0), coalesce((p_funding->>'list_fee')::numeric, 0),
          coalesce((p_funding->>'payments')::int, 1), (p_funding->>'first_leads')::int, (p_funding->>'first_due')::date, (p_funding->>'due_day')::int, now(), v_me)
  on conflict (project_id) do update set
    plan = excluded.plan, leads = excluded.leads, appts = excluded.appts, appts_included = excluded.appts_included,
    setup_fee = excluded.setup_fee, list_fee = excluded.list_fee, payments = excluded.payments, first_leads = excluded.first_leads,
    first_due = excluded.first_due, due_day = excluded.due_day, updated_at = now(), updated_by = v_me;

  for r in select * from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) loop
    insert into public.project_payments as p (project_id, kind, seq, label, due_date, amount, leads, appts, fees)
    values (p_project, 'installment', (r->>'seq')::int, left(coalesce(r->>'label', 'Payment'), 80), (r->>'due')::date,
            (r->>'amount')::numeric, coalesce((r->>'leads')::int, 0), coalesce((r->>'appts')::int, 0), coalesce((r->>'fees')::numeric, 0))
    on conflict (project_id, seq) where kind = 'installment' do update set
      label = excluded.label, due_date = excluded.due_date, amount = excluded.amount, leads = excluded.leads,
      appts = excluded.appts, fees = excluded.fees,
      rep_reminded_at = case when p.due_date is not distinct from excluded.due_date and p.amount = excluded.amount then p.rep_reminded_at end,
      client_reminded_at = case when p.due_date is not distinct from excluded.due_date and p.amount = excluded.amount then p.client_reminded_at end
    where p.paid_at is null;
    v_count := v_count + 1;
  end loop;
  delete from public.project_payments
   where project_id = p_project and kind = 'installment' and paid_at is null
     and seq not in (select (x->>'seq')::int from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) x);
  return v_count;
end $$;
revoke execute on function public.save_project_funding(bigint, jsonb, jsonb) from public, anon;
grant execute on function public.save_project_funding(bigint, jsonb, jsonb) to authenticated;

-- Paid, or not after all: an administrator or the client's Sales Rep.
create or replace function public.set_payment_paid(p_payment bigint, p_paid boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v public.project_payments;
begin
  select * into v from public.project_payments where id = p_payment for update;
  if not found then
    raise exception 'That payment no longer exists' using errcode = 'P0002';
  end if;
  if not public.sees_project_funding(v.project_id) then
    raise exception 'Only an administrator or the client''s Sales Rep marks a payment paid' using errcode = '42501';
  end if;
  update public.project_payments
     set paid_at = case when p_paid then coalesce(paid_at, now()) end,
         paid_by = case when p_paid then coalesce(paid_by, public.app_user_id()) end
   where id = p_payment
  returning * into v;
  return jsonb_build_object('id', v.id, 'paid_at', v.paid_at);
end $$;
revoke execute on function public.set_payment_paid(bigint, boolean) from public, anon;
grant execute on function public.set_payment_paid(bigint, boolean) to authenticated;

-- A payment's details for a reminder to the client (its people's addresses), by an administrator
-- or the Sales Rep, only for a client with payment reminders on; and, once sent, marked so.
create or replace function public.payment_reminder(p_payment bigint, p_sent boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v public.project_payments;
  v_out jsonb;
begin
  select * into v from public.project_payments where id = p_payment;
  if not found then
    raise exception 'That payment no longer exists' using errcode = 'P0002';
  end if;
  if not public.sees_project_funding(v.project_id) then
    raise exception 'Only an administrator or the client''s Sales Rep sends a payment reminder' using errcode = '42501';
  end if;
  if p_sent then
    update public.project_payments set client_reminded_at = now() where id = p_payment;
    return jsonb_build_object('id', p_payment);
  end if;
  select jsonb_build_object(
           'id', v.id, 'label', v.label, 'amount', v.amount, 'due', v.due_date, 'paid', v.paid_at is not null,
           'project', p.name, 'client', c.name, 'on', c.payment_reminders,
           'to', coalesce((select jsonb_agg(jsonb_build_object('name', nullif(concat_ws(' ', u.first_name, u.last_name), ''), 'email', u.email) order by u.id)
                             from public.users u
                            where u.company_id = c.id and u.role = 'client' and u.status = 'active' and u.deleted_at is null and u.email is not null), '[]'::jsonb))
    into v_out
    from public.projects p join public.companies c on c.id = p.company_id
   where p.id = v.project_id;
  return v_out;
end $$;
revoke execute on function public.payment_reminder(bigint, boolean) from public, anon;
grant execute on function public.payment_reminder(bigint, boolean) to authenticated;

-- What a project has delivered so far: its leads (not invalid) and valid appointments, counted as the billing report counts them.
create or replace function public.project_delivered(p_project bigint)
returns table (leads bigint, appts bigint)
language sql stable security definer set search_path = public as $$
  select
    (select count(*) from public.leads l left join public.call_results r on r.id = l.result_id
      where coalesce(l.source_project_id, l.project_id) = p_project and l.deleted_at is null and l.promoted_at is not null
        and not (coalesce(l.call_result_dbdv = 'Lead-Invalid', false) or coalesce(r.effect = 'lead_invalid', false))),
    (select count(*) from public.appointments a join public.leads l on l.id = a.lead_id and l.deleted_at is null
      where coalesce(a.set_project_id, a.project_id) = p_project and a.deleted_at is null and a.invalid_at is null);
$$;
revoke execute on function public.project_delivered(bigint) from public, anon, authenticated;

-- Each month's bill for what was produced (on the 1st, for the month just ended): its leads and
-- valid appointments at the project's rates, where the plan bills them monthly (all of a monthly
-- plan; the appointments of one that leaves them out of its installments). From the month the
-- program starts to the one it ends; nothing billed, no bill. Due on its due day this month.
create or replace function public.bill_project_months(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_from date := (date_trunc('month', p_day) - interval '1 month')::date;
  v_to date := (date_trunc('month', p_day) - interval '1 day')::date;
  v_count integer := 0;
  r record;
begin
  for r in
    with ev as (
      select e.project_id, count(*) filter (where e.kind = 'lead' and e.invalid is not true) as leads,
             count(*) filter (where e.kind = 'appointment' and e.invalid is not true) as appts
        from public.report_events(v_from, v_to) e group by e.project_id
    )
    select f.project_id, f.plan, f.appts_included, f.due_day, f.first_due,
           coalesce(p.bill_lead_rate, 0) as lead_rate, coalesce(p.bill_appointment_rate, 0) as appt_rate,
           case when f.plan = 'monthly' then coalesce(ev.leads, 0) else 0 end as leads,
           case when f.plan = 'monthly' or not f.appts_included then coalesce(ev.appts, 0) else 0 end as appts
      from public.project_funding f
      join public.projects p on p.id = f.project_id and p.deleted_at is null
      left join ev on ev.project_id = f.project_id
     where v_from >= date_trunc('month', coalesce(f.first_due, p.start_date, v_from))::date
       and (p.end_date is null or v_from <= p.end_date)
  loop
    continue when r.leads * r.lead_rate + r.appts * r.appt_rate <= 0;
    insert into public.project_payments (project_id, kind, period, label, due_date, amount, leads, appts)
    values (r.project_id, 'monthly', v_from, to_char(v_from, 'FMMonth YYYY'),
            make_date(extract(year from p_day)::int, extract(month from p_day)::int, coalesce(r.due_day, extract(day from r.first_due)::int, 15)),
            r.leads * r.lead_rate + r.appts * r.appt_rate, r.leads, r.appts)
    on conflict (project_id, period) where kind = 'monthly' do nothing;
    if found then v_count := v_count + 1; end if;
  end loop;
  return v_count;
end $$;
revoke execute on function public.bill_project_months(date) from public, anon, authenticated;

-- 5 days before a payment is due (and not yet paid), its client's Sales Rep is told, with how the
-- project is doing; the administrators when the client has no Sales Rep. Once for each payment.
insert into public.alert_rules (name, trigger, channel)
select 'Payment due in 5 days', 'payment_due', 'inapp'
 where not exists (select 1 from public.alert_rules r where r.trigger = 'payment_due');

create or replace function public.send_payment_reminders(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer := 0;
  v_to bigint[];
  v_done record;
  r record;
begin
  for r in
    select pp.id, pp.label, pp.amount, pp.due_date, pp.project_id, p.name as project, c.name as client, c.sales_rep_id,
           f.leads as bought_leads, f.appts as bought_appts
      from public.project_payments pp
      join public.projects p on p.id = pp.project_id and p.deleted_at is null
      join public.companies c on c.id = p.company_id
      left join public.project_funding f on f.project_id = pp.project_id
     where pp.paid_at is null and pp.rep_reminded_at is null
       and pp.due_date between p_day and p_day + 5
     for update of pp skip locked
  loop
    v_to := case when r.sales_rep_id is not null then array[r.sales_rep_id]
                 else array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null) end;
    select * into v_done from public.project_delivered(r.project_id);
    perform public.notify_users(
      v_to, 'system',
      left(format('Payment due %s: %s · %s', to_char(r.due_date, 'FMMon FMDD'), r.client, to_char(r.amount, 'FM$999,999,990.00')), 160),
      left(concat_ws(' · ', r.project, r.label,
        format('Leads %s%s delivered', v_done.leads, case when coalesce(r.bought_leads, 0) > 0 then format(' of %s', r.bought_leads) else '' end),
        format('appointments %s%s', v_done.appts, case when coalesce(r.bought_appts, 0) > 0 then format(' of %s', r.bought_appts) else '' end)), 1000),
      '/payments', 'payment_due');
    update public.project_payments set rep_reminded_at = now() where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;
revoke execute on function public.send_payment_reminders(date) from public, anon, authenticated;

-- The daily alerts, with the month's bills and the payment reminders.
create or replace function public.run_daily_alerts()
returns integer
language plpgsql security definer set search_path = public as $function$
declare
  v_now timestamp := now() at time zone public.business_tz();
begin
  if extract(hour from v_now) < 7 then
    return 0;
  end if;
  return public.send_xdate_warnings(v_now::date) + public.send_appointment_reminders(v_now::date)
       + public.send_celebrations(v_now::date)
       + public.bill_project_months(v_now::date) + public.send_payment_reminders(v_now::date);
end $function$;
revoke execute on function public.run_daily_alerts() from public, anon, authenticated;

-- ==============================================================================================================
-- 20270114100000_program_funding_stop_twice_monthly.sql
-- ==============================================================================================================

-- Program Funding, the client's follow-ups (Nov 2026):
--
--   A client stopping their program: its upcoming payments removed, one at a time
--   (set_payment_removed()) or all at once with the program marked stopped
--   (stop_project_funding()), which bills nothing more. A removed payment is kept,
--   struck through, out of what is owed and with no reminders; it can be put back.
--
--   Billed twice a month (the 1st and the 15th): project_funding.billing. On the 15th, for
--   the 1st to the 14th; on the 1st, for the 15th to the month's end; each due the day it is
--   billed. Once a month, as before: on the 1st for the month before, due on the due day.
--
-- Safe to run again.

alter table public.project_payments
  add column if not exists removed_at timestamptz,
  add column if not exists removed_by bigint references public.users(id) on delete set null;
comment on column public.project_payments.removed_at is 'Not owed after all (the client stopped their program): kept, out of the totals and reminders.';

alter table public.project_funding
  add column if not exists billing text not null default 'monthly',
  add column if not exists stopped_at timestamptz,
  add column if not exists stopped_by bigint references public.users(id) on delete set null;
alter table public.project_funding drop constraint if exists project_funding_billing_check;
alter table public.project_funding add constraint project_funding_billing_check check (billing in ('monthly', 'semimonthly'));
comment on column public.project_funding.billing is 'What is billed for what was produced: monthly (on the 1st) or semimonthly (the 1st and the 15th).';
comment on column public.project_funding.stopped_at is 'The client stopped their program: nothing more is billed.';

drop index if exists public.project_payments_due;
create index if not exists project_payments_due on public.project_payments (due_date) where paid_at is null and removed_at is null;

-- The plan and its installments, as before, with how often production is billed; payments paid
-- or removed stay as they were.
create or replace function public.save_project_funding(p_project bigint, p_funding jsonb, p_payments jsonb)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
  v_count integer := 0;
  r jsonb;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator sets a program''s funding' using errcode = '42501';
  end if;
  if not exists (select 1 from public.projects where id = p_project) then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;

  insert into public.project_funding as f (project_id, plan, leads, appts, appts_included, setup_fee, list_fee, payments, first_leads, first_due, due_day, billing, updated_at, updated_by)
  values (p_project, coalesce(p_funding->>'plan', 'monthly'), coalesce((p_funding->>'leads')::int, 0), coalesce((p_funding->>'appts')::int, 0),
          coalesce((p_funding->>'appts_included')::boolean, false), coalesce((p_funding->>'setup_fee')::numeric, 0), coalesce((p_funding->>'list_fee')::numeric, 0),
          coalesce((p_funding->>'payments')::int, 1), (p_funding->>'first_leads')::int, (p_funding->>'first_due')::date, (p_funding->>'due_day')::int,
          case when p_funding->>'billing' = 'semimonthly' then 'semimonthly' else 'monthly' end, now(), v_me)
  on conflict (project_id) do update set
    plan = excluded.plan, leads = excluded.leads, appts = excluded.appts, appts_included = excluded.appts_included,
    setup_fee = excluded.setup_fee, list_fee = excluded.list_fee, payments = excluded.payments, first_leads = excluded.first_leads,
    first_due = excluded.first_due, due_day = excluded.due_day, billing = excluded.billing, updated_at = now(), updated_by = v_me;

  for r in select * from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) loop
    insert into public.project_payments as p (project_id, kind, seq, label, due_date, amount, leads, appts, fees)
    values (p_project, 'installment', (r->>'seq')::int, left(coalesce(r->>'label', 'Payment'), 80), (r->>'due')::date,
            (r->>'amount')::numeric, coalesce((r->>'leads')::int, 0), coalesce((r->>'appts')::int, 0), coalesce((r->>'fees')::numeric, 0))
    on conflict (project_id, seq) where kind = 'installment' do update set
      label = excluded.label, due_date = excluded.due_date, amount = excluded.amount, leads = excluded.leads,
      appts = excluded.appts, fees = excluded.fees,
      rep_reminded_at = case when p.due_date is not distinct from excluded.due_date and p.amount = excluded.amount then p.rep_reminded_at end,
      client_reminded_at = case when p.due_date is not distinct from excluded.due_date and p.amount = excluded.amount then p.client_reminded_at end
    where p.paid_at is null and p.removed_at is null;
    v_count := v_count + 1;
  end loop;
  delete from public.project_payments
   where project_id = p_project and kind = 'installment' and paid_at is null and removed_at is null
     and seq not in (select (x->>'seq')::int from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) x);
  return v_count;
end $$;
revoke execute on function public.save_project_funding(bigint, jsonb, jsonb) from public, anon;
grant execute on function public.save_project_funding(bigint, jsonb, jsonb) to authenticated;

-- Paid, or not after all (a removed one paid after all is put back).
create or replace function public.set_payment_paid(p_payment bigint, p_paid boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v public.project_payments;
begin
  select * into v from public.project_payments where id = p_payment for update;
  if not found then
    raise exception 'That payment no longer exists' using errcode = 'P0002';
  end if;
  if not public.sees_project_funding(v.project_id) then
    raise exception 'Only an administrator or the client''s Sales Rep marks a payment paid' using errcode = '42501';
  end if;
  update public.project_payments
     set paid_at = case when p_paid then coalesce(paid_at, now()) end,
         paid_by = case when p_paid then coalesce(paid_by, public.app_user_id()) end,
         removed_at = case when p_paid then null else removed_at end,
         removed_by = case when p_paid then null else removed_by end
   where id = p_payment
  returning * into v;
  return jsonb_build_object('id', v.id, 'paid_at', v.paid_at);
end $$;
revoke execute on function public.set_payment_paid(bigint, boolean) from public, anon;
grant execute on function public.set_payment_paid(bigint, boolean) to authenticated;

-- An unpaid payment removed (not owed after all), or put back: an administrator or the client's Sales Rep.
create or replace function public.set_payment_removed(p_payment bigint, p_removed boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v public.project_payments;
begin
  select * into v from public.project_payments where id = p_payment for update;
  if not found then
    raise exception 'That payment no longer exists' using errcode = 'P0002';
  end if;
  if not public.sees_project_funding(v.project_id) then
    raise exception 'Only an administrator or the client''s Sales Rep removes a payment' using errcode = '42501';
  end if;
  if p_removed and v.paid_at is not null then
    raise exception 'That payment is paid: mark it unpaid first' using errcode = '22023';
  end if;
  update public.project_payments
     set removed_at = case when p_removed then coalesce(removed_at, now()) end,
         removed_by = case when p_removed then coalesce(removed_by, public.app_user_id()) end
   where id = p_payment
  returning * into v;
  return jsonb_build_object('id', v.id, 'removed_at', v.removed_at);
end $$;
revoke execute on function public.set_payment_removed(bigint, boolean) from public, anon;
grant execute on function public.set_payment_removed(bigint, boolean) to authenticated;

-- The client stopped their program: every payment not yet paid removed, and nothing more billed.
-- Or started again: billing goes on (the removed payments stay removed, each can be put back).
-- An administrator or the client's Sales Rep; how many payments were removed.
create or replace function public.stop_project_funding(p_project bigint, p_stop boolean)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
  v_count integer := 0;
begin
  if not public.sees_project_funding(p_project) then
    raise exception 'Only an administrator or the client''s Sales Rep stops a program' using errcode = '42501';
  end if;
  update public.project_funding
     set stopped_at = case when p_stop then coalesce(stopped_at, now()) end,
         stopped_by = case when p_stop then coalesce(stopped_by, v_me) end
   where project_id = p_project;
  if not found then
    raise exception 'That project has no funding plan' using errcode = 'P0002';
  end if;
  if p_stop then
    update public.project_payments set removed_at = now(), removed_by = v_me
     where project_id = p_project and paid_at is null and removed_at is null;
    get diagnostics v_count = row_count;
  end if;
  return v_count;
end $$;
revoke execute on function public.stop_project_funding(bigint, boolean) from public, anon;
grant execute on function public.stop_project_funding(bigint, boolean) to authenticated;

-- A payment's details for a reminder to the client, as before, with whether it was removed.
create or replace function public.payment_reminder(p_payment bigint, p_sent boolean default false)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v public.project_payments;
  v_out jsonb;
begin
  select * into v from public.project_payments where id = p_payment;
  if not found then
    raise exception 'That payment no longer exists' using errcode = 'P0002';
  end if;
  if not public.sees_project_funding(v.project_id) then
    raise exception 'Only an administrator or the client''s Sales Rep sends a payment reminder' using errcode = '42501';
  end if;
  if p_sent then
    update public.project_payments set client_reminded_at = now() where id = p_payment;
    return jsonb_build_object('id', p_payment);
  end if;
  select jsonb_build_object(
           'id', v.id, 'label', v.label, 'amount', v.amount, 'due', v.due_date, 'paid', v.paid_at is not null, 'removed', v.removed_at is not null,
           'project', p.name, 'client', c.name, 'on', c.payment_reminders,
           'to', coalesce((select jsonb_agg(jsonb_build_object('name', nullif(concat_ws(' ', u.first_name, u.last_name), ''), 'email', u.email) order by u.id)
                             from public.users u
                            where u.company_id = c.id and u.role = 'client' and u.status = 'active' and u.deleted_at is null and u.email is not null), '[]'::jsonb))
    into v_out
    from public.projects p join public.companies c on c.id = p.company_id
   where p.id = v.project_id;
  return v_out;
end $$;
revoke execute on function public.payment_reminder(bigint, boolean) from public, anon;
grant execute on function public.payment_reminder(bigint, boolean) to authenticated;

-- The bills for what was produced: once a month (on the 1st, for the month before, due on the
-- plan's due day) or twice (on the 15th for the 1st to the 14th, on the 1st for the 15th to the
-- month's end, each due that day). Not for a stopped program. Otherwise as before.
create or replace function public.bill_project_months(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_month date := date_trunc('month', p_day)::date;
  v_late boolean := extract(day from p_day) >= 15;
  m_from date := (date_trunc('month', p_day) - interval '1 month')::date;
  m_to date := (date_trunc('month', p_day) - interval '1 day')::date;
  s_from date := case when v_late then v_month else m_from + 14 end;
  s_to date := case when v_late then v_month + 13 else m_to end;
  s_due date := case when v_late then v_month + 14 else v_month end;
  v_count integer := 0;
  r record;
begin
  for r in
    with ev as (
      select 'monthly'::text as billing, e.project_id,
             count(*) filter (where e.kind = 'lead' and e.invalid is not true) as leads,
             count(*) filter (where e.kind = 'appointment' and e.invalid is not true) as appts
        from public.report_events(m_from, m_to) e group by e.project_id
      union all
      select 'semimonthly', e.project_id,
             count(*) filter (where e.kind = 'lead' and e.invalid is not true),
             count(*) filter (where e.kind = 'appointment' and e.invalid is not true)
        from public.report_events(s_from, s_to) e
       where exists (select 1 from public.project_funding x where x.billing = 'semimonthly' and x.stopped_at is null)
       group by e.project_id
    ), plans as (
      select f.*, p.start_date, p.end_date,
             coalesce(p.bill_lead_rate, 0) as lead_rate, coalesce(p.bill_appointment_rate, 0) as appt_rate,
             case when f.billing = 'semimonthly' then s_from else m_from end as period_from
        from public.project_funding f
        join public.projects p on p.id = f.project_id and p.deleted_at is null
       where f.stopped_at is null
    )
    select pl.project_id, pl.billing, pl.period_from, pl.due_day, pl.first_due, pl.lead_rate, pl.appt_rate,
           case when pl.plan = 'monthly' then coalesce(ev.leads, 0) else 0 end as leads,
           case when pl.plan = 'monthly' or not pl.appts_included then coalesce(ev.appts, 0) else 0 end as appts
      from plans pl
      left join ev on ev.project_id = pl.project_id and ev.billing = pl.billing
     where pl.period_from >= date_trunc('month', coalesce(pl.first_due, pl.start_date, pl.period_from))::date
       and (pl.end_date is null or pl.period_from <= pl.end_date)
  loop
    continue when r.leads * r.lead_rate + r.appts * r.appt_rate <= 0;
    insert into public.project_payments (project_id, kind, period, label, due_date, amount, leads, appts)
    values (r.project_id, 'monthly', r.period_from,
            case when r.billing = 'semimonthly' then format('%s–%s', to_char(s_from, 'FMMon FMDD'), to_char(s_to, 'FMDD, YYYY'))
                 else to_char(m_from, 'FMMonth YYYY') end,
            case when r.billing = 'semimonthly' then s_due
                 else make_date(extract(year from p_day)::int, extract(month from p_day)::int, coalesce(r.due_day, extract(day from r.first_due)::int, 15)) end,
            r.leads * r.lead_rate + r.appts * r.appt_rate, r.leads, r.appts)
    on conflict (project_id, period) where kind = 'monthly' do nothing;
    if found then v_count := v_count + 1; end if;
  end loop;
  return v_count;
end $$;
revoke execute on function public.bill_project_months(date) from public, anon, authenticated;

-- The Sales Rep's 5 days' notice, as before, not for a removed payment.
create or replace function public.send_payment_reminders(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer := 0;
  v_to bigint[];
  v_done record;
  r record;
begin
  for r in
    select pp.id, pp.label, pp.amount, pp.due_date, pp.project_id, p.name as project, c.name as client, c.sales_rep_id,
           f.leads as bought_leads, f.appts as bought_appts
      from public.project_payments pp
      join public.projects p on p.id = pp.project_id and p.deleted_at is null
      join public.companies c on c.id = p.company_id
      left join public.project_funding f on f.project_id = pp.project_id
     where pp.paid_at is null and pp.removed_at is null and pp.rep_reminded_at is null
       and pp.due_date between p_day and p_day + 5
     for update of pp skip locked
  loop
    v_to := case when r.sales_rep_id is not null then array[r.sales_rep_id]
                 else array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null) end;
    select * into v_done from public.project_delivered(r.project_id);
    perform public.notify_users(
      v_to, 'system',
      left(format('Payment due %s: %s · %s', to_char(r.due_date, 'FMMon FMDD'), r.client, to_char(r.amount, 'FM$999,999,990.00')), 160),
      left(concat_ws(' · ', r.project, r.label,
        format('Leads %s%s delivered', v_done.leads, case when coalesce(r.bought_leads, 0) > 0 then format(' of %s', r.bought_leads) else '' end),
        format('appointments %s%s', v_done.appts, case when coalesce(r.bought_appts, 0) > 0 then format(' of %s', r.bought_appts) else '' end)), 1000),
      '/payments', 'payment_due');
    update public.project_payments set rep_reminded_at = now() where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;
revoke execute on function public.send_payment_reminders(date) from public, anon, authenticated;

-- ==============================================================================================================
-- 20270115100000_reminders_own_clock.sql
-- ==============================================================================================================

-- Reminders on the person's own clock (client, Nov 2026: a manager in California set a call-back
-- for 4:30 PM at 4:06 PM and was told it had passed: the time was read on the business's clock,
-- Arizona's, an hour ahead).
--
-- A reminder keeps the time zone it was set in (the browser's, e.g. America/Los_Angeles):
-- the time chosen is read there, the notification says the time there, and moving it keeps it
-- there. Without one (older reminders, the appointment confirmation reminders), the business's.
-- A lead sent to someone with a time to call is read on the sender's clock the same way.
--
-- Safe to run again.

alter table public.reminders add column if not exists time_zone text;
comment on column public.reminders.time_zone is 'The clock the reminder was set on (IANA, the browser''s); null: the business''s.';

-- A time zone's name when Postgres knows it, else null.
create or replace function public.known_tz(p_tz text)
returns text
language plpgsql stable set search_path = public as $$
begin
  if nullif(btrim(coalesce(p_tz, '')), '') is null or length(p_tz) > 64 then
    return null;
  end if;
  perform now() at time zone p_tz;
  return p_tz;
exception when others then
  return null;
end $$;
grant execute on function public.known_tz(text) to authenticated;

drop function if exists public.set_reminder(bigint, date, text, text);
create or replace function public.set_reminder(p_lead_id bigint, p_date date, p_time text, p_note text default null, p_tz text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  v_tz   text := coalesce(public.known_tz(p_tz), public.business_tz());
  v_time time;
  v_at   timestamptz;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  r      public.reminders;
begin
  if v_me is null or not (public.can_work_lead(p_lead_id)
       or (public.app_role() = 'client' and exists (select 1 from public.leads l where l.id = p_lead_id and l.deleted_at is null
             and (l.project_id in (select public.client_project_ids()) or l.source_project_id in (select public.client_project_ids()))))) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;
  begin
    v_time := to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time;
  exception when others then
    raise exception 'Choose a time like 2:00 PM' using errcode = '22023';
  end;
  if p_date is null or v_time is null then
    raise exception 'Choose the day and time to be reminded' using errcode = '22023';
  end if;
  v_at := (p_date + v_time) at time zone v_tz;
  if v_at < now() - interval '1 minute' then
    raise exception 'That time has already passed' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 300 then
    raise exception 'Keep the note under 300 characters' using errcode = '22023';
  end if;
  insert into public.reminders (lead_id, user_id, remind_at, note, time_zone)
  values (p_lead_id, v_me, v_at, v_note, public.known_tz(p_tz))
  returning * into r;
  return jsonb_build_object('id', r.id, 'remind_at', r.remind_at);
end $$;
revoke execute on function public.set_reminder(bigint, date, text, text, text) from public, anon;
grant execute on function public.set_reminder(bigint, date, text, text, text) to authenticated;

-- Moved on the dashboard: the new day and time on the reminder's own clock.
create or replace function public.move_reminder(p_id bigint, p_date date, p_time text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_at timestamptz;
  r    public.reminders;
begin
  if p_date is null then
    raise exception 'Choose the day to be reminded' using errcode = '22023';
  end if;
  select * into r from public.reminders where id = p_id and user_id = public.app_user_id() for update;
  if r.id is null then
    raise exception 'This is not one of your reminders' using errcode = '42501';
  end if;
  v_at := (p_date + public.parse_clock_time(p_time)) at time zone coalesce(public.known_tz(r.time_zone), public.business_tz());
  if v_at < now() - interval '1 minute' then
    raise exception 'That time has already passed' using errcode = '22023';
  end if;
  if r.sent_at is not null then
    raise exception 'This reminder has already gone off' using errcode = '22023';
  end if;
  update public.reminders set remind_at = v_at where id = r.id returning * into r;
  return jsonb_build_object('id', r.id, 'remind_at', r.remind_at);
end $$;

-- "Reminder for 4:30 PM": on the reminder's own clock.
create or replace function public.deliver_reminders()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  r     record;
  v_id  bigint;
  n     integer := 0;
begin
  for r in
    select m.id, m.user_id, m.lead_id, m.note, m.remind_at, m.appointment_id, l.company_name, u.role,
           coalesce(public.known_tz(m.time_zone), public.business_tz()) as tz
      from public.reminders m
      join public.leads l on l.id = m.lead_id and l.deleted_at is null
      left join public.users u on u.id = m.user_id
     where m.sent_at is null and m.remind_at <= now()
     order by m.remind_at
     for update of m skip locked
  loop
    insert into public.notifications (user_id, kind, title, body, link)
    values (
      r.user_id, 'reminder',
      left(case when r.appointment_id is not null then 'Confirm tomorrow''s appointment: '
                when r.role = 'client' then 'Reminder: ' else 'Call back: ' end
           || coalesce(r.company_name, 'a lead'), 120),
      left(case when r.appointment_id is not null then coalesce(r.note, '')
                else concat_ws(' · ', 'Reminder for ' || to_char(r.remind_at at time zone r.tz, 'FMHH12:MI AM'), r.note) end, 1000),
      '/leads/' || r.lead_id
    )
    returning id into v_id;
    update public.reminders set sent_at = now(), notification_id = v_id where id = r.id;
    n := n + 1;
  end loop;
  return n;
end $$;
revoke execute on function public.deliver_reminders() from public, anon, authenticated;

-- A lead sent with a time to call: the time on the sender's clock (p_tz), kept with the reminder.
drop function if exists public.send_lead(bigint, bigint, text, date, text, boolean);
create or replace function public.send_lead(p_lead bigint, p_to bigint, p_note text default null, p_date date default null, p_time text default null, p_assign boolean default true, p_tz text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  v_lead public.leads;
  v_to   public.users;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_own  text := public.known_tz(p_tz);
  v_tz   text := coalesce(public.known_tz(p_tz), public.business_tz());
  v_time time;
  v_at   timestamptz;
begin
  if v_me is null or public.app_role() not in ('admin', 'manager') then
    raise exception 'Only administrators and managers send a lead to someone' using errcode = '42501';
  end if;
  select * into v_lead from public.leads where id = p_lead and deleted_at is null;
  if v_lead.id is null then
    raise exception 'That lead is no longer there' using errcode = 'P0002';
  end if;
  select * into v_to from public.users
   where id = p_to and status = 'active' and deleted_at is null and role in ('admin', 'manager', 'agent');
  if v_to.id is null then
    raise exception 'Choose someone on the team to send it to' using errcode = '22023';
  end if;
  if v_to.id = v_me then
    raise exception 'Choose someone other than yourself' using errcode = '22023';
  end if;
  if length(v_note) > 1000 then
    raise exception 'Keep the note under 1,000 characters' using errcode = '22023';
  end if;
  -- A time to call, on the sender's clock, as a call-back reminder reads one.
  if p_date is not null or nullif(btrim(coalesce(p_time, '')), '') is not null then
    begin
      v_time := to_timestamp(upper(btrim(p_time)), 'HH12:MI AM')::time;
    exception when others then
      raise exception 'Choose a time like 2:00 PM' using errcode = '22023';
    end;
    if p_date is null or v_time is null then
      raise exception 'Choose both the day and the time to call' using errcode = '22023';
    end if;
    v_at := (p_date + v_time) at time zone v_tz;
    if v_at < now() - interval '1 minute' then
      raise exception 'That time has already passed' using errcode = '22023';
    end if;
  end if;

  if p_assign and v_lead.assigned_user_id is distinct from v_to.id then
    perform set_config('lighthouse.quiet_assign', 'on', true);
    update public.leads set assigned_user_id = v_to.id where id = v_lead.id;
    perform set_config('lighthouse.quiet_assign', 'off', true);
  end if;
  if v_at is not null then
    insert into public.reminders (lead_id, user_id, remind_at, note, time_zone)
    values (v_lead.id, v_to.id, v_at, left(coalesce(v_note, 'Sent by ' || coalesce(public.actor_name(), 'a manager')), 300), v_own);
  end if;
  perform public.notify_users(
    array[v_to.id], 'lead',
    left('Lead to call: ' || coalesce(v_lead.company_name, 'a lead'), 160),
    left(concat_ws(' · ',
      'From ' || coalesce(public.actor_name(), 'a manager'),
      case when p_assign then 'It is yours to work' end,
      case when v_at is not null then 'Call ' || to_char(v_at at time zone v_tz, 'Dy MM/DD/YYYY FMHH12:MI AM') end,
      v_note), 1000),
    '/leads/' || v_lead.id,
    'lead_assigned');
  return jsonb_build_object('lead', v_lead.id, 'to', v_to.id, 'assigned', p_assign, 'remind_at', v_at);
end $$;
revoke execute on function public.send_lead(bigint, bigint, text, date, text, boolean, text) from public, anon;
grant execute on function public.send_lead(bigint, bigint, text, date, text, boolean, text) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270116100000_notifications_unread_clear.sql
-- ==============================================================================================================

-- Notifications (client, Nov 2026): mark one unread again, to keep it for later (read_at back to
-- null: the update already allowed on one's own), and Clear history: the ones already read taken
-- out of one's inbox. Cleared, not deleted: a sender's read receipts and a reminder's link to its
-- notification stay as they were; unread ones are never cleared.
--
-- Safe to run again.

alter table public.notifications add column if not exists cleared_at timestamptz;
comment on column public.notifications.cleared_at is 'Taken out of its recipient''s inbox (Clear history); kept for read receipts.';
create index if not exists notifications_inbox on public.notifications (user_id, created_at desc) where cleared_at is null;

-- The signed-in person's read notifications cleared from their inbox; how many.
create or replace function public.clear_read_notifications()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
  v_count integer;
begin
  if v_me is null then
    raise exception 'Sign in again to do that' using errcode = '42501';
  end if;
  update public.notifications set cleared_at = now()
   where user_id = v_me and read_at is not null and cleared_at is null;
  get diagnostics v_count = row_count;
  return v_count;
end $$;
revoke execute on function public.clear_read_notifications() from public, anon;
grant execute on function public.clear_read_notifications() to authenticated;

-- ==============================================================================================================
-- 20270117100000_disabled_sign_in_notice.sql
-- ==============================================================================================================

-- Signing in to a disabled account (Nov 2026): say the account is disabled, rather than that
-- the email and password don't match. Supabase refuses a disabled (banned) sign-in before it
-- checks the password, so the server checks it here first: only someone who knows the right
-- password learns the account is disabled; anyone else still gets "don't match".
--
-- The server's (service role) alone.
--
-- Safe to run again.

create or replace function public.disabled_account_password(p_email text, p_password text)
returns boolean
language sql stable security definer set search_path = public, extensions as $$
  select exists (
    select 1
      from auth.users a
      join public.users u on u.auth_id = a.id
     where lower(a.email) = lower(btrim(p_email))
       and u.status = 'disabled'
       and a.encrypted_password is not null and a.encrypted_password <> ''
       and a.encrypted_password = extensions.crypt(p_password, a.encrypted_password)
  );
$$;
revoke execute on function public.disabled_account_password(text, text) from public, anon, authenticated;
grant execute on function public.disabled_account_password(text, text) to service_role;

-- ==============================================================================================================
-- 20270118100000_production_hours.sql
-- ==============================================================================================================

-- The dashboard's Leads and Appointments tiles on Day (client, Nov 2026): the day's figures by the
-- hour, so the chart can name the hours along its foot. Counted as production_report() counts
-- them (pay_events, chargebacks aside), and for the same people: an administrator everyone (or
-- p_user), anyone else their own.
--
-- Safe to run again.

create or replace function public.production_hours(p_day date, p_user bigint default null)
returns table (hour integer, leads bigint, appointments bigint)
language plpgsql stable security invoker set search_path = public as $$
declare
  v_tz   text   := public.business_tz();
  v_user bigint := case when public.is_admin() then p_user else public.app_user_id() end;
begin
  if p_day is null then
    raise exception 'Choose a day' using errcode = '22023';
  end if;
  return query
  select extract(hour from pe.created_at at time zone v_tz)::integer,
         count(*) filter (where pe.kind = 'lead'),
         count(*) filter (where pe.kind = 'appointment')
    from public.pay_events pe
   where pe.created_at >= (p_day::timestamp at time zone v_tz)
     and pe.created_at <  ((p_day + 1)::timestamp at time zone v_tz)
     and pe.user_id is not null and not pe.is_chargeback
     and pe.kind in ('lead', 'appointment')
     and (v_user is null or pe.user_id = v_user)
   group by 1
   order by 1;
end $$;
revoke execute on function public.production_hours(date, bigint) from public, anon;
grant execute on function public.production_hours(date, bigint) to authenticated;

-- ==============================================================================================================
-- 20270119100000_funding_sales_rep_level.sql
-- ==============================================================================================================

-- Program Funding seen at the Sales Rep's level (client, Nov 2026: "Mike & I are admins, but will
-- also be sales reps for our own clients. As Admins, we'd want to have access to all client info
-- within the system, but ... only show the project funding info for us at the sales rep level").
--
-- Who sees a project's funding (its plan and payments, Payments Due, marking paid, removing,
-- stopping, reminders, setting the plan):
--   its client's Sales Rep, whatever their role;
--   an administrator who is nobody's Sales Rep (the office): every client's;
--   an administrator who is a Sales Rep: their own clients', and those with no Sales Rep yet
--     (so no client's funding is out of everyone's sight).
-- Everything else stays as it was: administrators see all of every client otherwise.
--
-- Safe to run again.

-- Someone who is a Sales Rep for at least one client (not deleted).
create or replace function public.is_sales_rep(p_user bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select p_user is not null and exists (select 1 from public.companies c where c.sales_rep_id = p_user and c.deleted_at is null);
$$;
revoke execute on function public.is_sales_rep(bigint) from public, anon;
grant execute on function public.is_sales_rep(bigint) to authenticated;

create or replace function public.sees_project_funding(p_project bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.projects p join public.companies c on c.id = p.company_id
     where p.id = p_project
       and ((c.sales_rep_id is not null and c.sales_rep_id = public.app_user_id())
            or (public.is_admin() and (c.sales_rep_id is null or not public.is_sales_rep(public.app_user_id())))));
$$;
revoke execute on function public.sees_project_funding(bigint) from public, anon;
grant execute on function public.sees_project_funding(bigint) to authenticated;

-- Setting a plan: an administrator, for a program whose funding they see.
create or replace function public.save_project_funding(p_project bigint, p_funding jsonb, p_payments jsonb)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
  v_count integer := 0;
  r jsonb;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator sets a program''s funding' using errcode = '42501';
  end if;
  -- An administrator who is a Sales Rep: their own clients' programs (and those with no Sales Rep).
  if not public.sees_project_funding(p_project) then
    raise exception 'Only that client''s Sales Rep sets its program''s funding' using errcode = '42501';
  end if;
  if not exists (select 1 from public.projects where id = p_project) then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;

  insert into public.project_funding as f (project_id, plan, leads, appts, appts_included, setup_fee, list_fee, payments, first_leads, first_due, due_day, billing, updated_at, updated_by)
  values (p_project, coalesce(p_funding->>'plan', 'monthly'), coalesce((p_funding->>'leads')::int, 0), coalesce((p_funding->>'appts')::int, 0),
          coalesce((p_funding->>'appts_included')::boolean, false), coalesce((p_funding->>'setup_fee')::numeric, 0), coalesce((p_funding->>'list_fee')::numeric, 0),
          coalesce((p_funding->>'payments')::int, 1), (p_funding->>'first_leads')::int, (p_funding->>'first_due')::date, (p_funding->>'due_day')::int,
          case when p_funding->>'billing' = 'semimonthly' then 'semimonthly' else 'monthly' end, now(), v_me)
  on conflict (project_id) do update set
    plan = excluded.plan, leads = excluded.leads, appts = excluded.appts, appts_included = excluded.appts_included,
    setup_fee = excluded.setup_fee, list_fee = excluded.list_fee, payments = excluded.payments, first_leads = excluded.first_leads,
    first_due = excluded.first_due, due_day = excluded.due_day, billing = excluded.billing, updated_at = now(), updated_by = v_me;

  for r in select * from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) loop
    insert into public.project_payments as p (project_id, kind, seq, label, due_date, amount, leads, appts, fees)
    values (p_project, 'installment', (r->>'seq')::int, left(coalesce(r->>'label', 'Payment'), 80), (r->>'due')::date,
            (r->>'amount')::numeric, coalesce((r->>'leads')::int, 0), coalesce((r->>'appts')::int, 0), coalesce((r->>'fees')::numeric, 0))
    on conflict (project_id, seq) where kind = 'installment' do update set
      label = excluded.label, due_date = excluded.due_date, amount = excluded.amount, leads = excluded.leads,
      appts = excluded.appts, fees = excluded.fees,
      rep_reminded_at = case when p.due_date is not distinct from excluded.due_date and p.amount = excluded.amount then p.rep_reminded_at end,
      client_reminded_at = case when p.due_date is not distinct from excluded.due_date and p.amount = excluded.amount then p.client_reminded_at end
    where p.paid_at is null and p.removed_at is null;
    v_count := v_count + 1;
  end loop;
  delete from public.project_payments
   where project_id = p_project and kind = 'installment' and paid_at is null and removed_at is null
     and seq not in (select (x->>'seq')::int from jsonb_array_elements(coalesce(p_payments, '[]'::jsonb)) x);
  return v_count;
end $$;
revoke execute on function public.save_project_funding(bigint, jsonb, jsonb) from public, anon;
grant execute on function public.save_project_funding(bigint, jsonb, jsonb) to authenticated;

-- ==============================================================================================================
-- 20270120100000_email_templates.sql
-- ==============================================================================================================

-- Email templates (client, Nov 2026: "pre-defined templates they can chose from that will fill in
-- the body of the email and subject line ... Admins can create the different email templates and
-- attachments and they can be available to pick from when managers send emails").
--
--   email_templates   a name, a subject and a message (with {first_name}, {company} and {my_name}
--                     filled in when picked), and the files that go with it: kept in the private
--                     email-templates bucket under template/<id>/, listed in `attachments`
--                     ([{ path, name, size, type }]). Administrators keep them; the staff who
--                     email leads (administrators, managers, agents) pick from the active ones.
--   lead_emails       each email now says which template it came from and the files it carried.
--
-- The server attaches the files when it sends (its own role reads them), so a sender can only
-- send a template's own files, never a path of their choosing.
--
-- Safe to run again.

create table if not exists public.email_templates (
  id          bigint generated always as identity primary key,
  name        text not null check (length(btrim(name)) between 1 and 80),
  subject     text not null default '' check (length(subject) <= 200),
  body        text not null default '' check (length(body) <= 10000),
  attachments jsonb not null default '[]'::jsonb check (jsonb_typeof(attachments) = 'array'),
  active      boolean not null default true,
  created_by  bigint references public.users(id) on delete set null,
  updated_by  bigint references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create unique index if not exists email_templates_name on public.email_templates (lower(btrim(name)));

alter table public.email_templates enable row level security;
drop policy if exists email_templates_read on public.email_templates;
create policy email_templates_read on public.email_templates for select to authenticated
  using (public.is_admin() or (public.is_staff() and active));
drop policy if exists email_templates_write on public.email_templates;
create policy email_templates_write on public.email_templates for all to authenticated
  using (public.is_admin()) with check (public.is_admin());
grant select, insert, update, delete on public.email_templates to authenticated;

alter table public.lead_emails
  add column if not exists template_id bigint references public.email_templates(id) on delete set null,
  add column if not exists attachments text[] not null default '{}';

-- The templates' files: up to 10 MB each, the kinds a prospect can open.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('email-templates', 'email-templates', false, 10485760,
        array['application/pdf', 'image/*', 'text/plain', 'text/csv',
              'application/msword', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
              'application/vnd.ms-excel', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
              'application/vnd.ms-powerpoint', 'application/vnd.openxmlformats-officedocument.presentationml.presentation'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists email_templates_files_write on storage.objects;
create policy email_templates_files_write on storage.objects for insert to authenticated
  with check (bucket_id = 'email-templates' and (storage.foldername(name))[1] = 'template' and public.is_admin());
drop policy if exists email_templates_files_delete on storage.objects;
create policy email_templates_files_delete on storage.objects for delete to authenticated
  using (bucket_id = 'email-templates' and public.is_admin());
drop policy if exists email_templates_files_read on storage.objects;
create policy email_templates_files_read on storage.objects for select to authenticated
  using (bucket_id = 'email-templates' and public.is_staff());

-- ==============================================================================================================
-- 20270121100000_call_recordings.sql
-- ==============================================================================================================

-- Call recordings (Nov 2026): Record on the phone during a call made Twilio record it, kept only in
-- the Twilio account, and Lighthouse never heard of it again. Now Twilio says when a recording is
-- done (app/api/twilio/voice?step=recorded); it is kept here, and the person who recorded it is told,
-- with a player, as a voicemail is (notifications/[id]).
--
--   phone_recordings          one row per recording: whose call, with which number, how long, the lead
--   phone_recording_saved()   what the server writes it with, telling the person (the server's own key)
--
-- Who may play one (app/api/phone/recordings/[sid]): an administrator, or the person who recorded it.
--
-- Safe to run more than once.

create table if not exists public.phone_recordings (
  recording_sid text primary key check (recording_sid ~* '^RE[0-9a-f]{32}$'),
  call_sid      text not null,
  user_id       bigint references public.users(id) on delete set null,
  number        text,
  seconds       integer not null default 0 check (seconds >= 0),
  lead_id       bigint references public.leads(id) on delete set null,
  created_at    timestamptz not null default now()
);

create index if not exists phone_recordings_user_idx on public.phone_recordings (user_id, created_at);
create index if not exists phone_recordings_lead_idx on public.phone_recordings (lead_id);

alter table public.phone_recordings enable row level security;
revoke all on public.phone_recordings from anon, authenticated;
grant select on public.phone_recordings to service_role;

/**
 * A recording done: kept, and its person told (once: Twilio may say so more than once). The
 * notification's title and body are the server's (lib voicemail.js reads them back). Returns
 * whether it was new.
 */
create or replace function public.phone_recording_saved(
  p_sid text, p_call text, p_user bigint, p_number text, p_seconds integer, p_lead bigint,
  p_title text, p_body text, p_link text
) returns boolean
language plpgsql security definer set search_path = public as $$
declare
  v_new boolean;
begin
  insert into public.phone_recordings (recording_sid, call_sid, user_id, number, seconds, lead_id)
  values (p_sid, p_call, p_user, p_number, greatest(coalesce(p_seconds, 0), 0), p_lead)
  on conflict (recording_sid) do nothing;
  v_new := found;
  if v_new and p_user is not null then
    insert into public.notifications (user_id, kind, title, body, link)
    select u.id, 'system', left(p_title, 200), left(p_body, 2000), p_link
      from public.users u
     where u.id = p_user and u.status = 'active';
  end if;
  return v_new;
end $$;

