-- ==============================================================================================================
-- 20270127100000_reminder_calendar_link.sql
-- ==============================================================================================================

-- The morning's appointment reminder opens on its appointments (client, Nov 2026). "1 to confirm for
-- tomorrow" → Open calendar went to today's day view, where tomorrow's appointment isn't: the calendar
-- looked empty. Now it opens on the day that needs doing, those appointments highlighted (?a=<id>,…):
--   something to confirm   tomorrow, with each one still to confirm
--   only today's           today, with each of today's
-- Built on the function as it stands (follow-ups go to whoever was handed them, hand_over_work).
-- And the reminders of the last few days, still around, are pointed the same way.
--
-- Safe to run more than once.

create or replace function public.send_appointment_reminders(p_day date)
 returns integer
 language plpgsql
 security definer
 set search_path to 'public'
as $function$
declare
  r record;
  n integer := 0;
begin
  for r in
    with live as (
      select a.id, coalesce(a.follow_up_user_id, a.user_id) as user_id, a.appt_date, a.appt_time, a.confirmed_at, l.company_name
        from public.appointments a
        join public.leads l on l.id = a.lead_id and l.deleted_at is null
        left join public.appointment_statuses s on s.id = a.status_id
       where coalesce(a.follow_up_user_id, a.user_id) is not null and a.invalid_at is null and a.deleted_at is null
         and coalesce(s.name, '') not in ('Cancelled', 'No Show', 'Invalid')
         and a.appt_date in (p_day, p_day + 1)
    )
    select user_id,
           count(*) filter (where appt_date = p_day) as today,
           count(*) filter (where appt_date = p_day + 1 and confirmed_at is null) as to_confirm,
           array_to_string((array_agg(coalesce(appt_time || ' ', '') || company_name order by appt_time)
                             filter (where appt_date = p_day))[1:5], ', ') as today_list,
           array_to_string((array_agg(company_name order by company_name)
                             filter (where appt_date = p_day + 1 and confirmed_at is null))[1:5], ', ') as confirm_list,
           array_to_string((array_agg(id order by appt_time) filter (where appt_date = p_day))[1:25], ',') as today_ids,
           array_to_string((array_agg(id order by appt_time)
                             filter (where appt_date = p_day + 1 and confirmed_at is null))[1:25], ',') as confirm_ids
      from live
     group by user_id
  loop
    if r.today = 0 and r.to_confirm = 0 then continue; end if;
    if exists (select 1 from public.alert_sends where rule = 'appt_reminder' and key = r.user_id || ':' || p_day) then
      continue;
    end if;
    insert into public.alert_sends (rule, key) values ('appt_reminder', r.user_id || ':' || p_day);
    n := n + public.notify_users(
      array[r.user_id], 'appointment',
      concat_ws(', ',
        case when r.today > 0 then r.today || ' appointment' || case when r.today = 1 then '' else 's' end || ' today' end,
        case when r.to_confirm > 0 then r.to_confirm || ' to confirm for tomorrow' end),
      concat_ws(' · ',
        case when r.today > 0 then 'Today: ' || r.today_list end,
        case when r.to_confirm > 0 then 'Confirm: ' || r.confirm_list end),
      -- The day that needs doing, with those appointments highlighted.
      case when r.to_confirm > 0
        then '/calendar?view=day&d=' || (p_day + 1) || '&a=' || r.confirm_ids
        else '/calendar?view=day&d=' || p_day || '&a=' || r.today_ids end,
      'appt_reminder');
  end loop;
  return n;
end $function$;

-- The reminders already sent these last days: to tomorrow's appointments still to confirm, when they
-- had some (else today's, highlighted).
with sent as (
  select n.id, n.user_id, substring(n.link from 'd=(\d{4}-\d{2}-\d{2})$')::date as day,
         n.title like '%to confirm for tomorrow%' as confirming
    from public.notifications n
   where n.kind = 'appointment'
     and n.link ~ '^/calendar\?view=day&d=\d{4}-\d{2}-\d{2}$'
     and (n.title like '%to confirm for tomorrow%' or n.title like '% today')
     and n.created_at > now() - interval '4 days'
),
pointed as (
  select s.id,
         '/calendar?view=day&d=' || case when s.confirming then s.day + 1 else s.day end
           || coalesce('&a=' || (select string_agg(a.id::text, ',' order by a.appt_time)
                                   from public.appointments a
                                  where coalesce(a.follow_up_user_id, a.user_id) = s.user_id
                                    and a.deleted_at is null and a.invalid_at is null
                                    and a.appt_date = case when s.confirming then s.day + 1 else s.day end
                                    and (not s.confirming or a.confirmed_at is null)), '') as link
    from sent s
)
update public.notifications n set link = p.link from pointed p where n.id = p.id and n.link is distinct from p.link;

-- ==============================================================================================================
-- 20270128100000_project_manager.sql
-- ==============================================================================================================

-- A project's manager, changed from the Projects list (client, Nov 2026: pick another account manager in
-- the Manager column, confirm, done). set_project_manager() puts that person on the project in place of
-- the account managers (and administrators) on it now; the agents working it stay. The project's names
-- still to call are then shared out again, in the same transaction, as set_project_rep() does.
--
-- Safe to run more than once.

create or replace function public.set_project_manager(p_project_id bigint, p_user_id bigint)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user public.users;
begin
  if not public.is_manager() then
    raise exception 'Only administrators and account managers can change who manages a project' using errcode = '42501';
  end if;
  perform 1 from public.projects where id = p_project_id and deleted_at is null for update;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  select * into v_user from public.users where id = p_user_id;
  if not found then
    raise exception 'That person no longer has an account' using errcode = 'P0002';
  end if;
  if v_user.role not in ('admin', 'manager') then
    raise exception 'Only an account manager or administrator can manage a project' using errcode = '22023';
  end if;
  if v_user.status is distinct from 'active' then
    raise exception '% cannot manage a project until their account is active',
      coalesce(nullif(concat_ws(' ', v_user.first_name, v_user.last_name), ''), v_user.email) using errcode = '22023';
  end if;

  -- The managers on it now come off (a row that also links a client contact keeps that link); agents stay.
  update public.project_assignments pa set ae_user_id = null
    from public.users u
   where pa.project_id = p_project_id and u.id = pa.ae_user_id and u.id <> p_user_id
     and u.role in ('admin', 'manager') and pa.cl_user_id is not null;
  delete from public.project_assignments pa
   using public.users u
   where pa.project_id = p_project_id and u.id = pa.ae_user_id and u.id <> p_user_id
     and u.role in ('admin', 'manager');

  insert into public.project_assignments (project_id, ae_user_id)
  select p_project_id, p_user_id
   where not exists (select 1 from public.project_assignments
                      where project_id = p_project_id and ae_user_id = p_user_id);

  return public.distribute_names(p_project_id);
end $$;
revoke execute on function public.set_project_manager(bigint, bigint) from public, anon;
grant execute on function public.set_project_manager(bigint, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270129100000_calls_by_lead.sql
-- ==============================================================================================================

-- A call, and its recording, on the lead it was made from (Sean, Nov 2026: "recordings crossing over to
-- different leads/projects"). A lead's Conversation found its calls by number, so a number on several
-- leads (the same business called for two clients, or a test number) showed every one of them on each.
-- Now each call keeps the lead it was dialed from (phone_calls.lead_id, sent by the phone with the call),
-- and the Conversation shows a lead only its own.
--
--   a call out      the lead it was dialed from
--   a call in       the lead last called on that number (calling back); its legs, as the call
--   calls before    from work_activity: the lead the same person started a call on that minute, with that
--                   number; a call in, as above. Any left without one show only where the number is on
--                   one lead alone (src/features/texts/conversation.js).
--
-- Safe to run more than once.

alter table public.phone_calls add column if not exists lead_id bigint references public.leads(id) on delete set null;
create index if not exists phone_calls_lead_idx on public.phone_calls (lead_id, started_at);
create index if not exists phone_calls_number_idx on public.phone_calls (number, started_at);

drop function if exists public.phone_call_event(text, text, bigint, text, text, text, integer);

/**
 * A leg's news from Twilio (as before), and the lead it is on: a call out's, as the phone sent it; a call
 * in's, its call's, or the lead last called on that number.
 */
create or replace function public.phone_call_event(
  p_sid text, p_parent text, p_user bigint, p_direction text, p_number text, p_status text, p_duration integer,
  p_lead bigint default null
) returns void
language plpgsql security definer set search_path = public as $$
declare
  v_ended  boolean := p_status in ('completed', 'busy', 'no-answer', 'failed', 'canceled');
  v_talk   integer := case when p_status = 'completed' then greatest(coalesce(p_duration, 0), 0) else 0 end;
  v_lead   bigint := (select id from public.leads where id = p_lead);
begin
  if v_lead is null and p_direction = 'in' then
    v_lead := coalesce(
      (select lead_id from public.phone_calls where call_sid = p_parent and lead_id is not null),
      (select lead_id from public.phone_calls
        where direction = 'out' and number = p_number and lead_id is not null
        order by started_at desc limit 1));
  end if;

  insert into public.phone_calls as c (call_sid, parent_sid, user_id, direction, number, status, rang_at, answered_at, ended_at, talk_seconds, lead_id)
  values (
    p_sid, p_parent, p_user, p_direction, p_number, p_status,
    case when p_status in ('ringing', 'in-progress', 'completed') then now() end,
    case when p_status = 'in-progress' then now() when p_status = 'completed' then now() - make_interval(secs => v_talk) end,
    case when v_ended then now() end,
    v_talk,
    v_lead
  )
  on conflict (call_sid) do update set
    parent_sid   = coalesce(c.parent_sid, excluded.parent_sid),
    user_id      = coalesce(c.user_id, excluded.user_id),
    number       = coalesce(c.number, excluded.number),
    status       = case when c.ended_at is null then excluded.status else c.status end,
    rang_at      = coalesce(c.rang_at, excluded.rang_at),
    answered_at  = coalesce(c.answered_at, excluded.answered_at),
    ended_at     = coalesce(c.ended_at, excluded.ended_at),
    talk_seconds = case when c.ended_at is null then excluded.talk_seconds else c.talk_seconds end,
    lead_id      = coalesce(c.lead_id, excluded.lead_id);
end $$;

revoke execute on function public.phone_call_event(text, text, bigint, text, text, text, integer, bigint) from public, anon, authenticated;
grant execute on function public.phone_call_event(text, text, bigint, text, text, text, integer, bigint) to service_role;

-- Calls before: a call out on the lead its caller started a call on, that minute or the one either side,
-- whose numbers have the one dialed (the nearest, when there are more).
update public.phone_calls c set lead_id = (
    select a.lead_id
      from public.work_activity a
      join public.leads l on l.id = a.lead_id
     where a.kind = 'call' and a.user_id = c.user_id
       and a.minute between date_trunc('minute', c.started_at) - interval '2 minutes' and date_trunc('minute', c.started_at) + interval '1 minute'
       and l.search_text ilike '%' || right(regexp_replace(c.number, '\D', '', 'g'), 10) || '%'
     order by abs(extract(epoch from (a.minute - date_trunc('minute', c.started_at)))), a.lead_id desc
     limit 1)
 where c.lead_id is null and c.direction = 'out' and c.user_id is not null
   and length(regexp_replace(coalesce(c.number, ''), '\D', '', 'g')) >= 10;

-- …a call in, on the lead last called on its number before it; its legs, as the call.
update public.phone_calls c set lead_id = (
    select o.lead_id from public.phone_calls o
     where o.direction = 'out' and o.number = c.number and o.lead_id is not null and o.started_at < c.started_at
     order by o.started_at desc limit 1)
 where c.lead_id is null and c.direction = 'in' and c.call_sid = c.parent_sid;
update public.phone_calls c set lead_id = p.lead_id
  from public.phone_calls p
 where c.lead_id is null and c.direction = 'in' and c.call_sid <> c.parent_sid
   and p.call_sid = c.parent_sid and p.lead_id is not null;

-- A recording on the lead its call is on (it was the first lead with the number).
update public.phone_recordings r set lead_id = c.lead_id
  from public.phone_calls c
 where (c.call_sid = r.call_sid or c.parent_sid = r.call_sid) and c.lead_id is not null
   and c.direction = 'out' and r.lead_id is distinct from c.lead_id;
update public.phone_recordings r set lead_id = c.lead_id
  from public.phone_calls c
 where c.call_sid = r.call_sid and c.direction = 'in' and c.lead_id is not null and r.lead_id is distinct from c.lead_id;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270130100000_pay_extras.sql
-- ==============================================================================================================

-- =============================================================================
-- Pay and bonus additions (Sean, Nov 2026: "items my team sent me that I never addressed")
--
--   1. Dec Sheet Pay      a manager ticks "Dec sheet received" on a lead with a file attached (the
--                         prospect's policy information): the project's dec sheet rate, once a lead
--                         (projects.dec_sheet_rate, $10 unless an administrator or the client's Sales Rep
--                         sets another); unticked, it is taken back. set_dec_sheet().
--   2. Lead-Corrected     the developer's lead pay moves to whoever corrects the lead (record_call_result:
--                         p_lead_manager names the developer of a lead with none on record).
--   3. A manager's rates  pay_profiles.appointment_rate / confirmation_rate: theirs on every project, in
--                         place of the project's (pay()).
--   4. Special Pay requests  a manager asks the project's Sales Rep (administrators when it has none) for
--                         an amount on a lead; approved, as asked or adjusted, it is paid. special_pay_requests.
--   5. Bonuses            each manager's plan (pay_profiles.bonus_plan): a lead manager's units for each
--                         half of a pay period (lead 1, appointment 2, dec sheet 1), paid that period; an
--                         appointment manager's valid appointments set in each half, paid the period
--                         after, and in a month, paid once the tier is reached (the appointments' dates
--                         passed). The tiers in Settings (app_settings 'bonus_plans', bonus_rules()).
--                         Worked out from what is on record each time (pay_bonuses()), so an appointment
--                         or lead found invalid later counts against it. A tier hit: a notification.
--   pay_report            + dec sheets, corrections, Special Pay requests and bonuses; a bonus is on top
--                         of the pay (a hybrid's too).
--
-- Safe to run more than once.
-- =============================================================================

-- ---------------------------------------------------------------------------
-- The new kinds of pay
-- ---------------------------------------------------------------------------

alter table public.pay_events drop constraint if exists pay_events_kind_check;
alter table public.pay_events add constraint pay_events_kind_check
  check (kind in ('lead', 'appointment', 'confirmation', 'special', 'dec_sheet', 'corrected', 'request'));

-- ---------------------------------------------------------------------------
-- 1. Dec Sheet Pay
-- ---------------------------------------------------------------------------

alter table public.projects add column if not exists dec_sheet_rate numeric(10,2) not null default 10;
alter table public.projects drop constraint if exists projects_dec_sheet_rate_check;
alter table public.projects add constraint projects_dec_sheet_rate_check check (dec_sheet_rate between 0 and 1000);
comment on column public.projects.dec_sheet_rate is 'Dec Sheet Pay: USD to the manager who gets a prospect''s policy information, once a lead';

alter table public.leads add column if not exists dec_sheet_at timestamptz;
alter table public.leads add column if not exists dec_sheet_by bigint references public.users(id) on delete set null;
alter table public.leads add column if not exists dec_sheet_document_id bigint references public.documents(id) on delete set null;

-- Only through set_project_dec_sheet_rate() (administrators, the client's Sales Rep), or an administrator.
create or replace function public.tg_projects_dec_sheet_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user = 'authenticated' and not public.is_admin()
     and (tg_op = 'INSERT' and new.dec_sheet_rate is distinct from 10
          or tg_op = 'UPDATE' and new.dec_sheet_rate is distinct from old.dec_sheet_rate) then
    raise exception 'Only administrators and the client''s Sales Rep set the dec sheet rate' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists projects_dec_sheet_guard on public.projects;
create trigger projects_dec_sheet_guard before insert or update on public.projects
  for each row execute function public.tg_projects_dec_sheet_guard();

create or replace function public.tg_leads_dec_sheet_guard()
returns trigger
language plpgsql set search_path = public as $$
begin
  if current_user = 'authenticated' and not public.is_admin()
     and (tg_op = 'INSERT' and (new.dec_sheet_at is not null or new.dec_sheet_by is not null)
          or tg_op = 'UPDATE' and (new.dec_sheet_at, new.dec_sheet_by, new.dec_sheet_document_id)
                                   is distinct from (old.dec_sheet_at, old.dec_sheet_by, old.dec_sheet_document_id)) then
    raise exception 'A dec sheet is marked with its checkbox' using errcode = '42501';
  end if;
  return new;
end $$;
drop trigger if exists leads_dec_sheet_guard on public.leads;
create trigger leads_dec_sheet_guard before insert or update on public.leads
  for each row execute function public.tg_leads_dec_sheet_guard();

/** A project's dec sheet rate: an administrator, or the Sales Rep of the project's client. */
create or replace function public.set_project_dec_sheet_rate(p_project_id bigint, p_rate numeric)
returns numeric
language plpgsql security definer set search_path = public as $$
declare
  v_me bigint := public.app_user_id();
begin
  if v_me is null or not (public.is_admin() or exists (
       select 1 from public.projects pr join public.companies c on c.id = pr.company_id
        where pr.id = p_project_id and c.sales_rep_id = v_me)) then
    raise exception 'Only administrators and the client''s Sales Rep set the dec sheet rate' using errcode = '42501';
  end if;
  if p_rate is null or p_rate < 0 or p_rate > 1000 then
    raise exception 'Choose a dec sheet rate from $0 to $1,000' using errcode = '22023';
  end if;
  update public.projects set dec_sheet_rate = round(p_rate, 2) where id = p_project_id and deleted_at is null;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  return round(p_rate, 2);
end $$;
revoke execute on function public.set_project_dec_sheet_rate(bigint, numeric) from public, anon;
grant execute on function public.set_project_dec_sheet_rate(bigint, numeric) to authenticated;

/**
 * "Dec sheet received" on a lead (p_on), or taken off. Ticked: a file must be on the lead (its policy
 * information), and the one who ticks it is paid the project's dec sheet rate, once a lead however many
 * files come. Unticked (by whoever ticked it, or an administrator): the pay is taken back.
 */
create or replace function public.set_dec_sheet(p_lead_id bigint, p_on boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  v_role text   := public.app_role();
  l      public.leads;
  v_doc  bigint;
  v_amt  numeric(10,2);
  v_pay  jsonb := '[]'::jsonb;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff mark a dec sheet' using errcode = '42501';
  end if;
  select * into l from public.leads where id = p_lead_id and deleted_at is null for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;

  if p_on then
    if l.dec_sheet_at is not null then
      raise exception 'The dec sheet on this lead is already marked' using errcode = '22023';
    end if;
    select d.id into v_doc from public.documents d where d.lead_id = l.id and d.deleted_at is null order by d.created_at desc, d.id desc limit 1;
    if v_doc is null then
      raise exception 'Attach the policy information to the lead first (Files)' using errcode = '22023';
    end if;
    update public.leads set dec_sheet_at = now(), dec_sheet_by = v_me, dec_sheet_document_id = v_doc where id = l.id;
    -- Once a lead: a dec sheet paid and not taken back.
    if not exists (select 1 from public.pay_events pe where pe.lead_id = l.id and pe.kind = 'dec_sheet' and not pe.is_chargeback
                    and not exists (select 1 from public.pay_events x where x.reverses_id = pe.id)) then
      select coalesce(dec_sheet_rate, 0) into v_amt from public.projects where id = l.project_id;
      insert into public.pay_events (user_id, project_id, lead_id, kind, amount, note, created_by)
      values (v_me, l.project_id, l.id, 'dec_sheet', coalesce(v_amt, 0), 'Dec sheet received', v_me);
      v_pay := jsonb_build_array(jsonb_build_object('user_id', v_me, 'kind', 'dec_sheet', 'amount', coalesce(v_amt, 0)));
    end if;
    perform public.bonus_notify(v_me);
  else
    if l.dec_sheet_at is null then
      return jsonb_build_object('on', false, 'pay', v_pay);
    end if;
    if l.dec_sheet_by is distinct from v_me and v_role <> 'admin' then
      raise exception 'Only whoever marked the dec sheet, or an administrator, can take it off' using errcode = '42501';
    end if;
    update public.leads set dec_sheet_at = null, dec_sheet_by = null, dec_sheet_document_id = null where id = l.id;
    v_pay := public.charge_back(l.id, null, array['dec_sheet'], null, 'Dec sheet unmarked');
  end if;
  return jsonb_build_object('on', p_on, 'pay', v_pay);
end $$;
revoke execute on function public.set_dec_sheet(bigint, boolean) from public, anon;
grant execute on function public.set_dec_sheet(bigint, boolean) to authenticated;

-- ---------------------------------------------------------------------------
-- 3. A manager's own rates, and their bonus plan
-- ---------------------------------------------------------------------------

alter table public.pay_profiles add column if not exists appointment_rate numeric(10,2);
alter table public.pay_profiles add column if not exists confirmation_rate numeric(10,2);
alter table public.pay_profiles add column if not exists bonus_plan text;
alter table public.pay_profiles drop constraint if exists pay_profiles_extras_check;
alter table public.pay_profiles add constraint pay_profiles_extras_check
  check ((appointment_rate is null or appointment_rate between 0 and 1000)
     and (confirmation_rate is null or confirmation_rate between 0 and 1000)
     and (bonus_plan is null or bonus_plan in ('lead', 'appointment')));
comment on column public.pay_profiles.appointment_rate is 'Their appointment pay on every project, in place of the project''s (null: the project''s)';
comment on column public.pay_profiles.confirmation_rate is 'Their confirmation pay on every project, in place of the project''s (null: the project''s)';
comment on column public.pay_profiles.bonus_plan is 'lead: the lead manager weekly units bonus; appointment: the appointment manager weekly and monthly bonuses';

create or replace function public.pay(p_user bigint, p_project bigint, p_kind text, p_lead bigint,
                                      p_appointment bigint, p_call bigint, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_amount numeric(10,2);
  v_id bigint;
begin
  -- A lead is developed once: no second payment for it unless the first was
  -- charged back (a lead moved back to its DBDev project and promoted again).
  if p_kind = 'lead' and exists (
       select 1 from public.pay_events pe
        where pe.lead_id = p_lead and pe.kind = 'lead' and not pe.is_chargeback
          and not exists (select 1 from public.pay_events r where r.reverses_id = pe.id)) then
    return '[]'::jsonb;
  end if;
  -- A manager's own appointment and confirmation rates, when they have them, in place of the project's.
  select case p_kind when 'lead' then pr.lead_rate
                     when 'appointment' then coalesce(pp.appointment_rate, pr.appointment_rate)
                     else coalesce(pp.confirmation_rate, pr.confirmation_rate) end
    into v_amount
    from public.projects pr left join public.pay_profiles pp on pp.user_id = p_user
   where pr.id = p_project;
  insert into public.pay_events (user_id, project_id, lead_id, appointment_id, call_record_id, kind, amount, note, created_by)
  values (p_user, p_project, p_lead, p_appointment, p_call, p_kind, coalesce(v_amount, 0), p_note, public.app_user_id())
  returning id into v_id;
  if p_kind = 'lead' then
    perform public.award_special_pay(p_user, p_project);
  end if;
  return jsonb_build_object('id', v_id, 'user_id', p_user, 'kind', p_kind, 'amount', coalesce(v_amount, 0));
end $$;
revoke execute on function public.pay(bigint, bigint, text, bigint, bigint, bigint, text) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. Special Pay requests
-- ---------------------------------------------------------------------------

create table if not exists public.special_pay_requests (
  id              bigint generated always as identity primary key,
  lead_id         bigint not null references public.leads(id) on delete cascade,
  project_id      bigint references public.projects(id) on delete set null,
  user_id         bigint not null references public.users(id) on delete cascade,
  decider_id      bigint references public.users(id) on delete set null,
  amount          numeric(10,2) not null check (amount > 0 and amount <= 10000),
  reason          text not null check (length(reason) between 1 and 500),
  status          text not null default 'pending' check (status in ('pending', 'approved', 'declined')),
  approved_amount numeric(10,2) check (approved_amount is null or (approved_amount > 0 and approved_amount <= 10000)),
  decision_note   text check (length(coalesce(decision_note, '')) <= 500),
  decided_by      bigint references public.users(id) on delete set null,
  decided_at      timestamptz,
  pay_event_id    bigint references public.pay_events(id) on delete set null,
  created_at      timestamptz not null default now()
);
create index if not exists special_pay_requests_lead_idx on public.special_pay_requests (lead_id, created_at desc);
create index if not exists special_pay_requests_decider_idx on public.special_pay_requests (decider_id, status);
create index if not exists special_pay_requests_user_idx on public.special_pay_requests (user_id, created_at desc);

alter table public.special_pay_requests enable row level security;
revoke all on public.special_pay_requests from anon;
grant select on public.special_pay_requests to authenticated;
drop policy if exists special_pay_requests_read on public.special_pay_requests;
create policy special_pay_requests_read on public.special_pay_requests
  for select to authenticated
  using ((select public.is_admin()) or user_id = (select public.app_user_id()) or decider_id = (select public.app_user_id()));

/** Ask for Special Pay on a lead: to the Sales Rep of its project's client, else the administrators. */
create or replace function public.request_special_pay(p_lead_id bigint, p_amount numeric, p_reason text)
returns bigint
language plpgsql security definer set search_path = public as $$
declare
  v_me     bigint := public.app_user_id();
  v_role   text   := public.app_role();
  l        public.leads;
  v_rep    bigint;
  v_id     bigint;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_to     bigint[];
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff ask for Special Pay' using errcode = '42501';
  end if;
  if p_amount is null or p_amount <= 0 or p_amount > 10000 then
    raise exception 'Enter the amount asked for, up to $10,000' using errcode = '22023';
  end if;
  if v_reason is null then
    raise exception 'Say what the Special Pay is for' using errcode = '22023';
  end if;
  if length(v_reason) > 500 then
    raise exception 'Keep the reason under 500 characters' using errcode = '22023';
  end if;
  select * into l from public.leads where id = p_lead_id and deleted_at is null;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select c.sales_rep_id into v_rep
    from public.projects pr join public.companies c on c.id = pr.company_id
    join public.users u on u.id = c.sales_rep_id and u.status = 'active' and u.deleted_at is null
   where pr.id = l.project_id;
  -- Nobody asks themselves: an administrator decides then.
  if v_rep = v_me then v_rep := null; end if;
  insert into public.special_pay_requests (lead_id, project_id, user_id, decider_id, amount, reason)
  values (l.id, l.project_id, v_me, v_rep, round(p_amount, 2), v_reason)
  returning id into v_id;
  v_to := case when v_rep is not null then array[v_rep]
               else (select array_agg(id) from public.users where role = 'admin' and status = 'active' and deleted_at is null and id <> v_me) end;
  if v_to is not null then
    perform public.notify_users(v_to, 'lead',
      'Special Pay asked for: ' || to_char(round(p_amount, 2), 'FM$999,990.00') || ' · ' || coalesce(l.company_name, 'a lead'),
      concat_ws(' · ', public.actor_name() || ' asks', v_reason), '/leads/' || l.id || '#special-pay');
  end if;
  return v_id;
end $$;
revoke execute on function public.request_special_pay(bigint, numeric, text) from public, anon;
grant execute on function public.request_special_pay(bigint, numeric, text) to authenticated;

/** A Special Pay request decided: approved (as asked, or the amount adjusted) and paid, or declined. */
create or replace function public.decide_special_pay(p_request_id bigint, p_approve boolean, p_amount numeric default null, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me   bigint := public.app_user_id();
  q      public.special_pay_requests;
  v_amt  numeric(10,2);
  v_ev   bigint;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_co   text;
begin
  select * into q from public.special_pay_requests where id = p_request_id for update;
  if not found then
    raise exception 'That request no longer exists' using errcode = 'P0002';
  end if;
  if v_me is null or not (public.is_admin() or q.decider_id = v_me) then
    raise exception 'Only the project''s Sales Rep or an administrator decides this request' using errcode = '42501';
  end if;
  if q.user_id = v_me and not public.is_admin() then
    raise exception 'Someone else decides your own request' using errcode = '42501';
  end if;
  if q.status <> 'pending' then
    raise exception 'This request has already been decided' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 500 then
    raise exception 'Keep the note under 500 characters' using errcode = '22023';
  end if;
  select company_name into v_co from public.leads where id = q.lead_id;
  if p_approve then
    v_amt := round(coalesce(p_amount, q.amount), 2);
    if v_amt <= 0 or v_amt > 10000 then
      raise exception 'Enter the amount approved, up to $10,000' using errcode = '22023';
    end if;
    insert into public.pay_events (user_id, project_id, lead_id, kind, amount, note, created_by)
    values (q.user_id, q.project_id, q.lead_id, 'request', v_amt, concat_ws(' · ', 'Special Pay', q.reason), v_me)
    returning id into v_ev;
    update public.special_pay_requests
       set status = 'approved', approved_amount = v_amt, decision_note = v_note, decided_by = v_me, decided_at = now(), pay_event_id = v_ev
     where id = q.id;
    perform public.notify_users(array[q.user_id], 'lead',
      'Special Pay approved: ' || to_char(v_amt, 'FM$999,990.00') || ' · ' || coalesce(v_co, 'a lead'),
      concat_ws(' · ', case when v_amt <> q.amount then 'Adjusted from ' || to_char(q.amount, 'FM$999,990.00') end,
                'Added to this pay period by ' || public.actor_name(), v_note), '/leads/' || q.lead_id || '#special-pay');
  else
    update public.special_pay_requests
       set status = 'declined', decision_note = v_note, decided_by = v_me, decided_at = now()
     where id = q.id;
    perform public.notify_users(array[q.user_id], 'lead',
      'Special Pay declined · ' || coalesce(v_co, 'a lead'),
      concat_ws(' · ', 'Declined by ' || public.actor_name(), v_note), '/leads/' || q.lead_id || '#special-pay');
  end if;
  return jsonb_build_object('status', case when p_approve then 'approved' else 'declined' end, 'amount', v_amt);
end $$;
revoke execute on function public.decide_special_pay(bigint, boolean, numeric, text) from public, anon;
grant execute on function public.decide_special_pay(bigint, boolean, numeric, text) to authenticated;

-- ---------------------------------------------------------------------------
-- 5. Bonuses
-- ---------------------------------------------------------------------------

/**
 * The bonus plans, with the defaults filled in for any an administrator has not set (app_settings
 * 'bonus_plans'). Tiers: [{ at, amount }], the amount for reaching `at` (the highest reached counts).
 *   lead_weekly     units in each half of a pay period: lead 1, appointment 2, dec sheet 1
 *   appt_weekly     valid appointments set in each half, paid the period after
 *   appt_monthly    valid appointments set in a month; `total`: a higher tier's amount is the whole
 *                   bonus (the lower one's already paid comes off it), else each is paid in full
 *   first_days      the days of a period's first half (the rest are its second)
 */
create or replace function public.bonus_rules()
returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'first_days',   coalesce((r->>'first_days')::int, 5),
    'units',        coalesce(r->'units', '{"lead": 1, "appointment": 2, "dec_sheet": 1}'::jsonb),
    'lead_weekly',  coalesce(r->'lead_weekly', '[{"at": 50, "amount": 50}, {"at": 75, "amount": 75}]'::jsonb),
    'appt_weekly',  coalesce(r->'appt_weekly', '[]'::jsonb),
    'appt_monthly', coalesce(r->'appt_monthly', '[{"at": 100, "amount": 300}, {"at": 150, "amount": 500}]'::jsonb),
    'monthly_total', coalesce((r->>'monthly_total')::boolean, true))
  from (select coalesce((select s.value from public.app_settings s where s.key = 'bonus_plans'), '{}'::jsonb) as r) x;
$$;
revoke execute on function public.bonus_rules() from public, anon;
grant execute on function public.bonus_rules() to authenticated;

/** The highest tier's amount reached by `n`. */
create or replace function public.bonus_tier(p_tiers jsonb, p_n numeric)
returns numeric
language sql immutable set search_path = public as $$
  select coalesce(max((t->>'amount')::numeric), 0)
    from jsonb_array_elements(coalesce(p_tiers, '[]'::jsonb)) t
   where p_n >= (t->>'at')::numeric;
$$;

/** A lead manager's units on the business's days p_from..p_to. */
create or replace function public.bonus_units(p_user bigint, p_from date, p_to date)
returns numeric
language sql stable set search_path = public as $$
  with u as (select public.bonus_rules()->'units' as w)
  select coalesce(sum(case when pe.is_chargeback then -1 else 1 end * coalesce((u.w->>pe.kind)::numeric, 0)), 0)
    from public.pay_events pe, u
   where pe.user_id = p_user and pe.kind in ('lead', 'appointment', 'dec_sheet')
     and pe.created_at >= (p_from::timestamp at time zone public.business_tz())
     and pe.created_at <  ((p_to + 1)::timestamp at time zone public.business_tz());
$$;

/** An appointment manager's valid appointments set on the business's days p_from..p_to (not invalid, not failed QA). */
create or replace function public.bonus_appointments(p_user bigint, p_from date, p_to date)
returns bigint
language sql stable set search_path = public as $$
  select count(*)
    from public.appointments a
   where a.user_id = p_user and a.deleted_at is null and a.invalid_at is null
     and a.qa_status is distinct from 'failed'
     and a.created_at >= (p_from::timestamp at time zone public.business_tz())
     and a.created_at <  ((p_to + 1)::timestamp at time zone public.business_tz());
$$;

/**
 * The bonuses paid in the pay periods that end on p_from..p_to, one row each: whose, which plan, the
 * days counted, how many, the amount, and the pay period it is paid in.
 *   lead          each half of a period: units, paid that period
 *   appt_weekly   each half of a period: valid appointments set, paid the period after
 *   appt_monthly  a month's valid appointments set, a tier paid in the period its last appointment's
 *                 date passes (the month over by then)
 */
create or replace function public.pay_bonuses(p_from date, p_to date, p_user bigint default null)
returns table (user_id bigint, plan text, label text, from_day date, to_day date, counted numeric, amount numeric, paid_from date, paid_to date)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_rules  jsonb := public.bonus_rules();
  v_first  int   := greatest(coalesce((v_rules->>'first_days')::int, 5), 1);
  v_today  date  := (now() at time zone public.business_tz())::date;
  per      record;
  nxt      record;
  u        record;
  h        record;
  m        date;
  t        record;
  v_n      numeric;
  v_prev   numeric;
  v_at     date;
  v_paid   record;
begin
  for per in
    select distinct (public.pay_period_of(d::date)).starts_on as s, (public.pay_period_of(d::date)).ends_on as e
      from generate_series(p_from - 70, p_to, interval '1 day') d
     order by 1
  loop
    for h in
      select per.s as hs, least(per.s + v_first - 1, per.e) as he, 1 as half
      union all
      select per.s + v_first, per.e, 2 where per.s + v_first <= per.e
    loop
      -- A lead manager's units, paid the same period.
      if per.e between p_from and p_to then
        for u in select pp.user_id as uid from public.pay_profiles pp
                  where pp.bonus_plan = 'lead' and (p_user is null or pp.user_id = p_user) loop
          v_n := public.bonus_units(u.uid, h.hs, h.he);
          if public.bonus_tier(v_rules->'lead_weekly', v_n) > 0 then
            user_id := u.uid; plan := 'lead'; label := 'Units'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := public.bonus_tier(v_rules->'lead_weekly', v_n); paid_from := per.s; paid_to := per.e;
            return next;
          end if;
        end loop;
      end if;
      -- An appointment manager's week, paid the period after.
      select * into nxt from public.pay_period_of(per.e + 1);
      if nxt.ends_on between p_from and p_to and jsonb_array_length(v_rules->'appt_weekly') > 0 then
        for u in select pp.user_id as uid from public.pay_profiles pp
                  where pp.bonus_plan = 'appointment' and (p_user is null or pp.user_id = p_user) loop
          v_n := public.bonus_appointments(u.uid, h.hs, h.he);
          if public.bonus_tier(v_rules->'appt_weekly', v_n) > 0 then
            user_id := u.uid; plan := 'appt_weekly'; label := 'Valid appointments'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := public.bonus_tier(v_rules->'appt_weekly', v_n); paid_from := nxt.starts_on; paid_to := nxt.ends_on;
            return next;
          end if;
        end loop;
      end if;
    end loop;
  end loop;

  -- An appointment manager's month: each tier paid in the period its last appointment's date passes.
  for m in select generate_series(date_trunc('month', p_from - 150)::date, date_trunc('month', p_to)::date, interval '1 month')::date loop
    for u in select pp.user_id as uid from public.pay_profiles pp
              where pp.bonus_plan = 'appointment' and (p_user is null or pp.user_id = p_user) loop
      v_n := public.bonus_appointments(u.uid, m, (m + interval '1 month')::date - 1);
      v_prev := 0;
      for t in select (x->>'at')::int as at_n, (x->>'amount')::numeric as amt
                 from jsonb_array_elements(v_rules->'appt_monthly') x order by 1 loop
        exit when v_n < t.at_n;
        -- The date the tier is reached: the month over, and the t.at_n-th appointment's date passed.
        select greatest((m + interval '1 month')::date,
                        coalesce(a.appt_date, (a.created_at at time zone public.business_tz())::date) + 1) into v_at
          from public.appointments a
         where a.user_id = u.uid and a.deleted_at is null and a.invalid_at is null and a.qa_status is distinct from 'failed'
           and a.created_at >= (m::timestamp at time zone public.business_tz())
           and a.created_at <  (((m + interval '1 month')::date)::timestamp at time zone public.business_tz())
         order by coalesce(a.appt_date, (a.created_at at time zone public.business_tz())::date), a.id
         offset t.at_n - 1 limit 1;
        if v_at is not null and v_at <= v_today then
          select * into v_paid from public.pay_period_of(v_at);
          if v_paid.ends_on between p_from and p_to then
            user_id := u.uid; plan := 'appt_monthly'; label := to_char(m, 'FMMonth') || ' valid appointments';
            from_day := m; to_day := (m + interval '1 month')::date - 1; counted := t.at_n;
            amount := case when coalesce((v_rules->>'monthly_total')::boolean, true) then t.amt - v_prev else t.amt end;
            paid_from := v_paid.starts_on; paid_to := v_paid.ends_on;
            if amount > 0 then return next; end if;
          end if;
        end if;
        v_prev := t.amt;
      end loop;
    end loop;
  end loop;
end $$;
revoke execute on function public.pay_bonuses(date, date, bigint) from public, anon;
grant execute on function public.pay_bonuses(date, date, bigint) to authenticated;

-- Each tier a manager is told of once.
create table if not exists public.bonus_notices (
  user_id    bigint not null references public.users(id) on delete cascade,
  key        text not null,
  created_at timestamptz not null default now(),
  primary key (user_id, key)
);
alter table public.bonus_notices enable row level security;
revoke all on public.bonus_notices from anon, authenticated;

/** A tier just reached in this half of the pay period: its manager congratulated, once. */
create or replace function public.bonus_notify(p_user bigint)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_rules jsonb := public.bonus_rules();
  v_first int   := greatest(coalesce((v_rules->>'first_days')::int, 5), 1);
  v_today date  := (now() at time zone public.business_tz())::date;
  v_plan  text;
  per     record;
  v_hs    date;
  v_he    date;
  v_n     numeric;
  t       record;
  v_new   boolean;
begin
  select bonus_plan into v_plan from public.pay_profiles where user_id = p_user;
  if v_plan is null then return; end if;
  select * into per from public.pay_period_of(v_today);
  if v_today < per.starts_on + v_first then
    v_hs := per.starts_on; v_he := least(per.starts_on + v_first - 1, per.ends_on);
  else
    v_hs := per.starts_on + v_first; v_he := per.ends_on;
  end if;
  v_n := case v_plan when 'lead' then public.bonus_units(p_user, v_hs, v_he) else public.bonus_appointments(p_user, v_hs, v_he) end;
  for t in select (x->>'at')::numeric as at_n, (x->>'amount')::numeric as amt
             from jsonb_array_elements(case v_plan when 'lead' then v_rules->'lead_weekly' else v_rules->'appt_weekly' end) x
            order by 1 loop
    continue when v_n < t.at_n;
    insert into public.bonus_notices (user_id, key) values (p_user, v_plan || ':' || v_hs || ':' || t.at_n)
    on conflict do nothing returning true into v_new;
    if v_new then
      -- Written straight in: notify_users() leaves out whoever is acting, and here that is the manager themselves.
      insert into public.notifications (user_id, kind, title, body, link)
      values (p_user, 'system',
        'Congrats! You hit your ' || to_char(t.amt, 'FM$999,990') || ' bonus',
        case v_plan when 'lead'
          then t.at_n || ' units ' || to_char(v_hs, 'FMMM/FMDD') || '–' || to_char(v_he, 'FMMM/FMDD') || ' · on this pay period''s check'
          else t.at_n || ' valid appointments set ' || to_char(v_hs, 'FMMM/FMDD') || '–' || to_char(v_he, 'FMMM/FMDD') || ' · on next pay period''s check, if they stay valid' end,
        '/reports/pay');
    end if;
    v_new := null;
  end loop;
end $$;
revoke execute on function public.bonus_notify(bigint) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Lead-Corrected pay: record_call_result() with the developer named when none is on record
-- ---------------------------------------------------------------------------

drop function if exists public.record_call_result(bigint, bigint, text, jsonb, date, date, text);
create or replace function public.record_call_result(p_lead_id bigint, p_result_id bigint, p_notes text DEFAULT NULL::text, p_appointment jsonb DEFAULT NULL::jsonb, p_corrected_xdate date DEFAULT NULL::date, p_ultimate_xdate date DEFAULT NULL::date, p_client_note text DEFAULT NULL::text, p_lead_manager bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me       bigint := public.app_user_id();
  v_role     text   := public.app_role();
  v_notes    text   := nullif(btrim(coalesce(p_notes, '')), '');
  l          public.leads;
  r          public.call_results;
  a_r        public.call_results;      -- the appointment-stage twin of a DBDev result
  p          public.projects;          -- the project the call is made on
  v_type     text;
  v_appt     public.appointments;
  v_open     public.appointments;      -- an appointment the name already holds, which this one moves
  v_call     bigint;
  v_status   bigint;
  v_rep      bigint;
  v_old_xdate date;
  v_pay      jsonb := '[]'::jsonb;
  v_date     date;
  v_time     text;
  v_dev      bigint;                   -- Lead-Corrected: the lead manager who developed it
  v_back     jsonb;
  v_amt      numeric(10,2);
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff can record call results' using errcode = '42501';
  end if;
  if length(coalesce(v_notes, '')) > 1000 then
    raise exception 'Keep call notes under 1,000 characters' using errcode = '22023';
  end if;
  if length(coalesce(p_client_note, '')) > 2000 then
    raise exception 'Keep the note for the client under 2,000 characters' using errcode = '22023';
  end if;

  select * into l from public.leads where id = p_lead_id for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select * into r from public.call_results where id = p_result_id;
  if not found then
    raise exception 'Unknown call result' using errcode = '22023';
  end if;
  if r.applies_to = 'report' then
    raise exception '% is recorded automatically, not from a call', r.name using errcode = '22023';
  end if;

  select * into p from public.projects where id = l.project_id;
  if not found then
    raise exception 'This name is not in a project yet' using errcode = '22023';
  end if;
  v_type := public.project_type_code(p.id);

  -- An appointment follow-up acts on the name's open appointment, recorded
  -- against the stage that appointment was set at so each project counts it.
  if r.applies_to = 'appointment' then
    select * into v_appt from public.appointments
     where lead_id = l.id and invalid_at is null
     order by appt_create_date desc, id desc
     limit 1
     for update;
    if not found then
      raise exception 'This name has no appointment to %', case r.effect when 'confirm' then 'confirm' else 'mark invalid' end
        using errcode = '22023';
    end if;
    if r.effect = 'confirm' and v_appt.confirmed_at is not null then
      raise exception 'This appointment is already confirmed' using errcode = '22023';
    end if;
    select * into r from public.call_results
     where name = r.name and project_type = case coalesce(v_appt.set_stage, l.stage) when 'dbdev' then 'DBDV' else 'APPT' end;
  elsif r.project_type <> v_type then
    raise exception '% is not a result for % projects', r.name,
      case v_type when 'DBDV' then 'database-development' else 'appointment' end using errcode = '22023';
  end if;

  if v_role <> 'admin'
     and l.assigned_user_id is distinct from v_me
     and not exists (select 1 from public.project_assignments pa where pa.project_id = l.project_id and pa.ae_user_id = v_me)
     and not (r.applies_to = 'appointment' and coalesce(v_appt.follow_up_user_id, v_appt.user_id) = v_me) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;

  -- The call itself.
  insert into public.call_records (lead_id, project_id, user_id, call_result, notes, result_id, stage, call_date)
  values (l.id, l.project_id, v_me, r.name, v_notes, r.id, l.stage, now())
  returning id into v_call;

  select id into v_status from public.lead_statuses where code = r.status_code;

  update public.leads set
    result_id        = r.id,
    call_result_dbdv = case when r.project_type = 'DBDV' then r.name else call_result_dbdv end,
    call_result_appt = case when r.project_type = 'APPT' then r.name
                            when r.effect = 'appointment_invalid' and stage = 'appt' then r.name
                            else call_result_appt end,
    call_weight      = call_weight + case when r.applies_to = 'name' then 1 else 0 end,
    date_last_worked = now(),
    status_id        = coalesce(v_status, status_id),
    resolved_at      = case when r.viable then null else coalesce(resolved_at, now()) end,
    assigned_user_id = case when r.effect = 'pending' then null else assigned_user_id end
  where id = l.id;

  -- What the result does.
  if r.effect in ('promote', 'appointment') then
    -- A name becomes a Lead or an Appointment only with its renewal date
    -- confirmed: the Ultimate X-Date, entered (or corrected) with this result,
    -- or already on the record. A date on a policy line alone is a potential
    -- renewal the account manager has not confirmed yet.
    if p_ultimate_xdate is not null then
      update public.insurance_details set ultimate_xdate = p_ultimate_xdate where lead_id = l.id;
      if not found then
        insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_ultimate_xdate);
      end if;
    end if;
    if not exists (select 1 from public.insurance_details i where i.lead_id = l.id and i.ultimate_xdate is not null) then
      raise exception 'Enter the Ultimate X-Date: a name becomes a Lead or an Appointment only with its renewal date'
        using errcode = '22023';
    end if;

    -- What the client is told, with the lead sheet: written as the name is
    -- set (given empty, it is cleared). The call notes stay internal.
    if p_client_note is not null then
      update public.leads set client_note = nullif(btrim(p_client_note), '') where id = l.id;
    end if;

    if r.effect = 'appointment' then
      v_date := nullif(p_appointment->>'date', '')::date;
      v_time := nullif(btrim(coalesce(p_appointment->>'time', '')), '');
      if v_date is null then
        raise exception 'Choose the appointment date' using errcode = '22023';
      end if;
      if v_date < current_date - 1 then
        raise exception 'The appointment date has passed' using errcode = '22023';
      end if;
      if v_time is null then
        raise exception 'Choose the appointment time' using errcode = '22023';
      end if;
      if v_time !~* '^\d{1,2}:\d{2}\s?(AM|PM)$' then
        raise exception 'Give the time like 9:30 AM' using errcode = '22023';
      end if;
    end if;

    -- A name that already holds an appointment still to come, or still
    -- waiting for QA, has that one moved: one appointment, paid once.
    -- (Recording the result again is how a rep reschedules from the sheet.)
    -- One that failed QA does not count: the rep sets a real one instead.
    if r.effect = 'appointment' then
      select * into v_open from public.appointments
       where lead_id = l.id and invalid_at is null and qa_status is distinct from 'failed'
         and (qa_status = 'pending' or appt_date >= (now() at time zone public.business_tz())::date)
       order by appt_create_date desc, id desc
       limit 1
       for update;
    end if;

    if v_open.id is not null then
      update public.appointments set
        appt_date    = v_date,
        appt_time    = v_time,
        duration_min = coalesce(nullif(p_appointment->>'duration', '')::int, duration_min),
        rep_name     = coalesce(nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), rep_name),
        status_id    = case when status_id = (select id from public.appointment_statuses where name = 'Scheduled')
                             and (appt_date, coalesce(appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                            then (select id from public.appointment_statuses where name = 'Rescheduled')
                            else status_id end,
        status_update_date = now()
      where id = v_open.id
      returning * into v_appt;
      -- "Moved" only when the day or the time changed.
      update public.call_records set
        appointment_id = v_appt.id,
        notes = case when (v_open.appt_date, coalesce(v_open.appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                     then concat_ws(E'\n', notes, 'Appointment moved from ' || to_char(v_open.appt_date, 'Mon FMDD')
                            || coalesce(' ' || v_open.appt_time, '') || ' to ' || to_char(v_date, 'Mon FMDD') || coalesce(' ' || v_time, ''))
                     else notes end
      where id = v_call;
    else

      -- From DBDev, the name moves to the linked appointment project.
      if v_type = 'DBDV' then
        if p.appt_project_id is null then
          raise exception 'Link % to an appointment project before promoting its names', p.name using errcode = '22023';
        end if;
        select * into a_r from public.call_results
         where project_type = 'APPT' and name = case r.effect when 'promote' then 'Lead-No Contact' else r.name end;
        -- A new lead goes to the appointment manager with the fewest names; an
        -- appointment stays with the rep who set it, who confirms it.
        v_rep := case r.effect when 'promote' then public.least_loaded_rep(p.appt_project_id) else v_me end;
        update public.leads set
          stage             = 'appt',
          project_id        = p.appt_project_id,
          source_project_id = coalesce(source_project_id, l.project_id),
          dbdv_user_id      = v_me,
          assigned_user_id  = v_rep,
          result_id         = a_r.id,
          call_result_appt  = a_r.name,
          call_weight       = 0,
          promoted_at       = now(),
          resolved_at       = case when a_r.viable then null else now() end
        where id = l.id;
        -- Nobody is on the appointment project to take a new lead: the administrators
        -- hear of it, so a hot lead never waits unseen (Sean, Oct 2026).
        if r.effect = 'promote' and v_rep is null then
          perform public.notify_users(
            array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null),
            'lead',
            left(case when r.status_code = 'hot' then 'Hot lead waiting: ' else 'Lead waiting: ' end || coalesce(l.company_name, 'a lead'), 160),
            'Nobody is assigned to ' || coalesce((select pp.name from public.projects pp where pp.id = p.appt_project_id), 'its appointment project')
              || ' to take it. Add an appointment manager to that project, or send the lead to one.',
            '/leads/' || l.id,
            case when r.status_code = 'hot' then 'hot_lead' else 'lead_assigned' end);
        end if;
      end if;

      if r.effect = 'appointment' then
        insert into public.appointments
          (lead_id, user_id, rep_name, appt_date, appt_time, duration_min, status_id, list_source,
           call_result_dbdv, project_id, set_project_id, set_stage, call_record_id, qa_status)
        values
          (l.id, v_me, nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), v_date, v_time,
           coalesce(nullif(p_appointment->>'duration', '')::int, 30),
           (select id from public.appointment_statuses where name = 'Scheduled'),
           l.list_source,
           case when v_type = 'DBDV' then r.name end,
           coalesce(p.appt_project_id, p.id), p.id, l.stage, v_call, 'pending')
        returning * into v_appt;
        update public.leads set appt_created_date = now() where id = l.id;
        update public.call_records set appointment_id = v_appt.id where id = v_call;
      end if;

      v_pay := v_pay || public.pay(v_me, p.id, r.pay_kind, l.id, v_appt.id, v_call);

    end if;

  elsif r.effect = 'confirm' then
    update public.appointments set
      status_id    = (select id from public.appointment_statuses where name = 'Confirmed'),
      confirmed_at = now(),
      confirmed_by = v_me,
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := v_pay || public.pay(v_me, coalesce(v_appt.set_project_id, p.id), 'confirmation', l.id, v_appt.id, v_call);
    -- The client hears now only if QA has already let them see it.
    if coalesce(v_appt.qa_status, 'passed') = 'passed' then
      perform public.notify_client_appointment(v_appt.id, true);
    end if;

  elsif r.effect = 'appointment_invalid' then
    update public.appointments set
      invalid_at = now(),
      status_id  = (select id from public.appointment_statuses where name = 'Invalid'),
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := public.charge_back(l.id, v_appt.id, array['appointment', 'confirmation'], v_call, 'Appointment invalid');

  elsif r.effect = 'lead_invalid' then
    update public.leads set call_result_dbdv = 'Lead-Invalid' where id = l.id and source_project_id is not null;
    v_pay := public.charge_back(l.id, null, array['lead'], v_call, 'Lead invalid');
    -- No record of the original payment (an older lead): charge the developer at today's rate.
    if jsonb_array_length(v_pay) = 0 and l.dbdv_user_id is not null and l.source_project_id is not null then
      insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
      select l.dbdv_user_id, l.source_project_id, l.id, v_call, 'lead', -sp.lead_rate, 'Lead invalid (no original payment on record)', v_me
        from public.projects sp where sp.id = l.source_project_id;
      v_pay := jsonb_build_array(jsonb_build_object('user_id', l.dbdv_user_id, 'kind', 'lead',
                 'amount', -(select lead_rate from public.projects where id = l.source_project_id)));
    end if;
    if l.dbdv_user_id is not null then
      perform public.notify_users(
        array[l.dbdv_user_id], 'lead', 'Lead marked invalid: ' || coalesce(l.company_name, 'a lead'),
        concat_ws(' · ', 'Charged back on your production report', 'marked by ' || public.actor_name()),
        '/leads/' || l.id, 'lead_invalid');
    end if;

  elsif r.effect = 'correct_xdate' then
    if p_corrected_xdate is null then
      raise exception 'Enter the corrected renewal date' using errcode = '22023';
    end if;
    v_old_xdate := public.lead_renewal_date(l.id);
    -- The corrected date becomes the lead's ultimate X-date, which is its
    -- renewal; the dates on the individual policy lines are left as recorded.
    update public.insurance_details set ultimate_xdate = p_corrected_xdate where lead_id = l.id;
    if not found then
      insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_corrected_xdate);
    end if;
    update public.leads set original_xdate = coalesce(original_xdate, v_old_xdate) where id = l.id;
    update public.call_records
       set notes = concat_ws(E'\n', notes, 'Renewal corrected from '
                   || coalesce(to_char(v_old_xdate, 'FMMonth YYYY'), 'none') || ' to ' || to_char(p_corrected_xdate, 'FMMonth YYYY'))
     where id = v_call;

    -- Lead-Corrected pay (Sean, Nov 2026): the lead pay of the lead manager who developed it moves to
    -- whoever corrected it, once a lead. A lead with no developer on record names one (p_lead_manager:
    -- the lead manager picked, kept as its developer; 0: nobody, a lead we didn't develop, so no pay moves).
    v_dev := coalesce(l.dbdv_user_id, nullif(p_lead_manager, 0));
    if l.dbdv_user_id is null and p_lead_manager is null then
      raise exception 'Choose the lead manager who developed this lead' using errcode = '22023';
    end if;
    if l.dbdv_user_id is null and v_dev is not null then
      if not exists (select 1 from public.users where id = v_dev and role in ('admin', 'manager', 'agent')) then
        raise exception 'Choose a lead manager from the list' using errcode = '22023';
      end if;
      update public.leads set dbdv_user_id = v_dev where id = l.id;
    end if;
    if v_dev is not null and v_dev <> v_me and not exists (
         select 1 from public.pay_events pe
          where pe.lead_id = l.id and pe.kind = 'corrected' and not pe.is_chargeback
            and not exists (select 1 from public.pay_events x where x.reverses_id = pe.id)) then
      v_back := public.charge_back(l.id, null, array['lead'], v_call, 'Lead corrected by ' || public.actor_name());
      v_amt := coalesce(-(select sum((e->>'amount')::numeric) from jsonb_array_elements(v_back) e where e->>'kind' = 'lead'), 0);
      -- No record of the original payment (an older or imported lead): the developer is charged the project's lead rate.
      if v_amt = 0 then
        select pr.lead_rate into v_amt from public.projects pr where pr.id = coalesce(l.source_project_id, l.project_id);
        v_amt := coalesce(v_amt, 0);
        if v_amt > 0 then
          insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
          values (v_dev, coalesce(l.source_project_id, l.project_id), l.id, v_call, 'lead', -v_amt, 'Lead corrected (no original payment on record)', v_me);
          v_back := v_back || jsonb_build_array(jsonb_build_object('user_id', v_dev, 'kind', 'lead', 'amount', -v_amt));
        end if;
      end if;
      if v_amt > 0 then
        insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
        values (v_me, p.id, l.id, v_call, 'corrected', v_amt,
                'Lead corrected, developed by ' || coalesce((select nullif(concat_ws(' ', first_name, last_name), '') from public.users where id = v_dev), 'another manager'), v_me);
        v_pay := v_pay || v_back || jsonb_build_array(jsonb_build_object('user_id', v_me, 'kind', 'corrected', 'amount', v_amt));
        perform public.notify_users(
          array[v_dev], 'lead', 'Lead corrected: ' || coalesce(l.company_name, 'a lead'),
          concat_ws(' · ', 'Its lead pay moves to ' || public.actor_name() || ', who corrected it', 'see the call on its Conversation'),
          '/leads/' || l.id);
      end if;
    end if;
  end if;

  -- A bonus hit with this result: its manager congratulated (Sean, Nov 2026).
  perform public.bonus_notify(v_me);

  -- What was said on the call joins the lead's internal notes, their running
  -- history (as the old system kept them), stamped as the rep wrote it.
  if v_notes is not null then
    insert into public.lead_notes (lead_id, notes)
    select l.id, btrim(c.notes) from public.call_records c where c.id = v_call
    on conflict (lead_id) do update
      set notes = concat_ws(E'\n', nullif(btrim(public.lead_notes.notes), ''), excluded.notes);
  end if;

  select * into l from public.leads where id = l.id;
  return jsonb_build_object(
    'call_record_id', v_call,
    'lead_id',        l.id,
    'result',         r.name,
    'stage',          l.stage,
    'project_id',     l.project_id,
    'promoted',       l.project_id is distinct from p.id,
    'on_list',        (select viable and callable from public.call_results where id = l.result_id) and l.assigned_user_id is not null,
    'appointment_id', v_appt.id,
    'rescheduled',    v_open.id is not null,
    'pay',            v_pay);
end $function$;

revoke execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text, bigint) from public, anon;
grant execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text, bigint) to authenticated;

-- ---------------------------------------------------------------------------
-- The pay report: + dec sheets, corrections, Special Pay requests, bonuses
-- ---------------------------------------------------------------------------

drop function if exists public.pay_report(date, date, bigint);
create or replace function public.pay_report(p_from date, p_to date, p_user bigint default null)
returns table (user_id bigint, first_name text, last_name text, email text, role text, pay_model text, hourly_rate numeric,
               worked_minutes integer, paid_minutes integer, hourly_pay numeric, commission numeric, pay numeric, calls bigint,
               leads bigint, appointments bigint, confirmations bigint, chargebacks bigint, specials bigint, special_goal_pay numeric,
               dec_sheets bigint, dec_sheet_pay numeric, corrected bigint, corrected_pay numeric, requests bigint, request_pay numeric,
               bonus numeric, bonus_plan text)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_tz   text   := public.business_tz();
  v_user bigint := case when public.is_admin() then p_user else public.app_user_id() end;
begin
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'Choose a start date on or before the end date' using errcode = '22023';
  end if;
  if p_to - p_from > 366 then
    raise exception 'Choose a range of a year or less' using errcode = '22023';
  end if;
  if v_user is null and not public.is_admin() then
    return;
  end if;

  return query
  with t as (
    select wd.user_id as uid, sum(wd.worked)::int as worked, sum(wd.paid)::int as paid
      from public.work_days(p_from, p_to, v_user) wd
     group by 1
  ), m as (
    select pe.user_id as uid,
           sum(pe.amount) as commission,
           count(*) filter (where pe.kind = 'lead'         and not pe.is_chargeback) as leads,
           count(*) filter (where pe.kind = 'appointment'  and not pe.is_chargeback) as appts,
           count(*) filter (where pe.kind = 'confirmation' and not pe.is_chargeback) as confirms,
           count(*) filter (where pe.is_chargeback) as backs,
           -- Special Pay net of any charged back: the leads it is still paid on, and what it comes to.
           count(*) filter (where pe.kind = 'special' and not pe.is_chargeback) - count(*) filter (where pe.kind = 'special' and pe.is_chargeback) as specials,
           sum(pe.amount) filter (where pe.kind = 'special') as special_amt,
           -- Dec sheets, corrections and Special Pay requests, net of any taken back.
           count(*) filter (where pe.kind = 'dec_sheet' and not pe.is_chargeback) - count(*) filter (where pe.kind = 'dec_sheet' and pe.is_chargeback) as decs,
           sum(pe.amount) filter (where pe.kind = 'dec_sheet') as dec_amt,
           count(*) filter (where pe.kind = 'corrected' and not pe.is_chargeback) - count(*) filter (where pe.kind = 'corrected' and pe.is_chargeback) as fixes,
           sum(pe.amount) filter (where pe.kind = 'corrected') as fix_amt,
           count(*) filter (where pe.kind = 'request' and not pe.is_chargeback) - count(*) filter (where pe.kind = 'request' and pe.is_chargeback) as reqs,
           sum(pe.amount) filter (where pe.kind = 'request') as req_amt
      from public.pay_events pe
     where pe.created_at >= (p_from::timestamp at time zone v_tz)
       and pe.created_at <  ((p_to + 1)::timestamp at time zone v_tz)
       and pe.user_id is not null
       and (v_user is null or pe.user_id = v_user)
     group by 1
  ), c as (
    select cr.user_id as uid, count(*) as n
      from public.call_records cr
     where cr.call_date >= (p_from::timestamp at time zone v_tz)
       and cr.call_date <  ((p_to + 1)::timestamp at time zone v_tz)
       and cr.user_id is not null
       and (v_user is null or cr.user_id = v_user)
     group by 1
  ), b as (
    select pb.user_id as uid, sum(pb.amount) as bonus
      from public.pay_bonuses(p_from, p_to, v_user) pb
     group by 1
  ), people as (
    select u.id
      from public.users u
     where (v_user is null or u.id = v_user)
       and ((u.role in ('manager', 'agent') and u.status = 'active')
            or u.id in (select t.uid from t) or u.id in (select m.uid from m) or u.id in (select c.uid from c) or u.id in (select b.uid from b))
  ), figures as (
    select u.id, u.first_name, u.last_name, u.email, u.role,
           coalesce(pp.pay_model, 'commission') as model, pp.hourly_rate as rate,
           coalesce(t.worked, 0) as worked, coalesce(t.paid, 0) as paid,
           round(coalesce(t.paid, 0) / 60.0 * coalesce(pp.hourly_rate, 0), 2) as hourly,
           round(coalesce(m.commission, 0), 2) as commission,
           coalesce(c.n, 0) as calls, coalesce(m.leads, 0) as leads, coalesce(m.appts, 0) as appts,
           coalesce(m.confirms, 0) as confirms, coalesce(m.backs, 0) as backs,
           coalesce(m.specials, 0) as specials, round(coalesce(m.special_amt, 0), 2) as special_amt,
           coalesce(m.decs, 0) as decs, round(coalesce(m.dec_amt, 0), 2) as dec_amt,
           coalesce(m.fixes, 0) as fixes, round(coalesce(m.fix_amt, 0), 2) as fix_amt,
           coalesce(m.reqs, 0) as reqs, round(coalesce(m.req_amt, 0), 2) as req_amt,
           round(coalesce(b.bonus, 0), 2) as bonus, pp.bonus_plan as plan
      from people pl
      join public.users u on u.id = pl.id
      left join public.pay_profiles pp on pp.user_id = u.id
      left join t on t.uid = u.id
      left join m on m.uid = u.id
      left join c on c.uid = u.id
      left join b on b.uid = u.id
  )
  select f.id, f.first_name, f.last_name, f.email, f.role, f.model, f.rate::numeric,
         f.worked, f.paid, f.hourly, f.commission,
         -- A bonus is on top of the pay, a hybrid's too.
         (case when f.model = 'hybrid' then greatest(f.hourly, f.commission) else f.commission end) + f.bonus,
         f.calls, f.leads, f.appts, f.confirms, f.backs, f.specials, f.special_amt,
         f.decs, f.dec_amt, f.fixes, f.fix_amt, f.reqs, f.req_amt, f.bonus, f.plan
    from figures f
   order by f.first_name, f.last_name, f.id;
end $$;
revoke execute on function public.pay_report(date, date, bigint) from public, anon;
grant execute on function public.pay_report(date, date, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270131100000_bonus_scale.sql
-- ==============================================================================================================

-- Bonus plans, as Sean set them out (Nov 2026):
--
--   Appointment manager, each half of a pay period: a scale, not tiers. Each valid appointment set from
--     the 21st to the 30th is $5, and from the 31st on $10 (21 = $5, 28 = $40, 30 = $50, 32 = $70,
--     50 = $250). The same scale for each half, so a poor first half doesn't spoil the second.
--     app_settings 'bonus_plans' -> 'appt_weekly_scale': [{ from, each }].
--   Appointment manager, each month: 100 to 149 valid = $300; 150 or more = $500 in all (as before).
--   Lead manager, each half: units counted on the half they were earned in. A lead found invalid (or
--     corrected) later comes off the half its pay was earned in, not the half it is found in. When that
--     takes an already paid half under its tier, what was paid over is taken back on the pay period it
--     is found in (a 'lead_adjust' line, a minus amount).
--
-- Safe to run more than once.

-- ---------------------------------------------------------------------------
-- The plans
-- ---------------------------------------------------------------------------

create or replace function public.bonus_rules()
returns jsonb
language sql stable security invoker set search_path = public as $$
  select jsonb_build_object(
    'first_days',   coalesce((r->>'first_days')::int, 5),
    'units',        coalesce(r->'units', '{"lead": 1, "appointment": 2, "dec_sheet": 1}'::jsonb),
    'lead_weekly',  coalesce(r->'lead_weekly', '[{"at": 50, "amount": 50}, {"at": 75, "amount": 75}]'::jsonb),
    'appt_weekly_scale', coalesce(r->'appt_weekly_scale', '[{"from": 21, "each": 5}, {"from": 31, "each": 10}]'::jsonb),
    'appt_monthly', coalesce(r->'appt_monthly', '[{"at": 100, "amount": 300}, {"at": 150, "amount": 500}]'::jsonb),
    'monthly_total', coalesce((r->>'monthly_total')::boolean, true))
  from (select coalesce((select s.value from public.app_settings s where s.key = 'bonus_plans'), '{}'::jsonb) as r) x;
$$;
revoke execute on function public.bonus_rules() from public, anon;
grant execute on function public.bonus_rules() to authenticated;

/** What a scale [{ from, each }] pays for `n`: each step's rate for every one from its start to the next step's. */
create or replace function public.bonus_scale(p_scale jsonb, p_n numeric)
returns numeric
language sql immutable set search_path = public as $$
  with s as (
    select (x->>'from')::numeric as f, (x->>'each')::numeric as each_,
           lead((x->>'from')::numeric) over (order by (x->>'from')::numeric) as nf
      from jsonb_array_elements(coalesce(p_scale, '[]'::jsonb)) x
     where (x->>'from')::numeric > 0 and (x->>'each')::numeric > 0
  )
  select coalesce(sum(greatest(0, least(floor(p_n), coalesce(nf - 1, floor(p_n))) - f + 1) * each_), 0) from s;
$$;
revoke execute on function public.bonus_scale(jsonb, numeric) from public, anon;
grant execute on function public.bonus_scale(jsonb, numeric) to authenticated;

-- ---------------------------------------------------------------------------
-- A lead manager's units, on the half they were earned in, as they stood at a moment
-- ---------------------------------------------------------------------------

drop function if exists public.bonus_units(bigint, date, date);

/**
 * A lead manager's units earned on the business's days p_from..p_to, as they stood at p_as_of: each
 * lead, appointment and dec sheet paid by then, less those charged back by p_as_of (a chargeback
 * counted on the half of the pay it takes back).
 */
create or replace function public.bonus_units(p_user bigint, p_from date, p_to date, p_as_of timestamptz default now())
returns numeric
language sql stable set search_path = public as $$
  with w as (select public.bonus_rules()->'units' as w),
       b as (select (p_from::timestamp at time zone public.business_tz()) as s,
                    ((p_to + 1)::timestamp at time zone public.business_tz()) as e)
  select coalesce(sum(coalesce((w.w->>pe.kind)::numeric, 0)
           * case when pe.reverses_id is not null or pe.is_chargeback then -1 else 1 end), 0)
    from public.pay_events pe
    cross join w cross join b
    left join public.pay_events o on o.id = pe.reverses_id
   where pe.user_id = p_user and pe.kind in ('lead', 'appointment', 'dec_sheet')
     and pe.created_at <= p_as_of  -- inclusive: now() is the transaction's start, when what it pays is written
     and case when pe.reverses_id is not null
              then o.created_at >= b.s and o.created_at < b.e
              else pe.created_at >= b.s and pe.created_at < b.e end;
$$;
revoke execute on function public.bonus_units(bigint, date, date, timestamptz) from public, anon;
grant execute on function public.bonus_units(bigint, date, date, timestamptz) to authenticated;

-- ---------------------------------------------------------------------------
-- The bonuses
-- ---------------------------------------------------------------------------

/**
 * The bonuses paid in the pay periods that end on p_from..p_to, one row each: whose, which plan, the
 * days counted, how many, the amount, and the pay period it is paid in.
 *   lead          each half of a period: units, paid that period (as they stood at its end)
 *   lead_adjust   an earlier half's units bonus taken back (a minus amount) on the period that found the
 *                 leads invalid that took it under its tier
 *   appt_weekly   each half of a period: valid appointments set, on the scale, paid the period after
 *   appt_monthly  a month's valid appointments set, a tier paid in the period its last appointment's
 *                 date passes (the month over by then)
 */
create or replace function public.pay_bonuses(p_from date, p_to date, p_user bigint default null)
returns table (user_id bigint, plan text, label text, from_day date, to_day date, counted numeric, amount numeric, paid_from date, paid_to date)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_rules  jsonb := public.bonus_rules();
  v_first  int   := greatest(coalesce((v_rules->>'first_days')::int, 5), 1);
  v_tz     text  := public.business_tz();
  v_today  date  := (now() at time zone public.business_tz())::date;
  per      record;
  nxt      record;
  q        record;
  u        record;
  h        record;
  m        date;
  t        record;
  v_n      numeric;
  v_amt    numeric;
  v_was    numeric;
  v_prev   numeric;
  v_at     date;
  v_paid   record;
  v_end    timestamptz;
begin
  for per in
    select distinct (public.pay_period_of(d::date)).starts_on as s, (public.pay_period_of(d::date)).ends_on as e
      from generate_series(p_from - 70, p_to, interval '1 day') d
     order by 1
  loop
    -- As things stood when the period closed (or now, while it is open).
    v_end := least(now(), (per.e + 1)::timestamp at time zone v_tz);
    for h in
      select per.s as hs, least(per.s + v_first - 1, per.e) as he, 1 as half
      union all
      select per.s + v_first, per.e, 2 where per.s + v_first <= per.e
    loop
      -- A lead manager's units, paid the same period.
      if per.e between p_from and p_to then
        for u in select pp.user_id as uid from public.pay_profiles pp
                  where pp.bonus_plan = 'lead' and (p_user is null or pp.user_id = p_user) loop
          v_n := public.bonus_units(u.uid, h.hs, h.he, v_end);
          if public.bonus_tier(v_rules->'lead_weekly', v_n) > 0 then
            user_id := u.uid; plan := 'lead'; label := 'Units'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := public.bonus_tier(v_rules->'lead_weekly', v_n); paid_from := per.s; paid_to := per.e;
            return next;
          end if;
        end loop;
      end if;
      -- An appointment manager's half, on the scale, paid the period after.
      select * into nxt from public.pay_period_of(per.e + 1);
      if nxt.ends_on between p_from and p_to then
        for u in select pp.user_id as uid from public.pay_profiles pp
                  where pp.bonus_plan = 'appointment' and (p_user is null or pp.user_id = p_user) loop
          v_n := public.bonus_appointments(u.uid, h.hs, h.he);
          v_amt := public.bonus_scale(v_rules->'appt_weekly_scale', v_n);
          if v_amt > 0 then
            user_id := u.uid; plan := 'appt_weekly'; label := 'Valid appointments'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := v_amt; paid_from := nxt.starts_on; paid_to := nxt.ends_on;
            return next;
          end if;
        end loop;
      end if;
    end loop;
  end loop;

  -- An earlier half's units bonus taken back: leads found invalid during period q, from a half paid before it.
  for q in
    select distinct (public.pay_period_of(d::date)).starts_on as s, (public.pay_period_of(d::date)).ends_on as e
      from generate_series(p_from - 31, p_to, interval '1 day') d
  loop
    continue when q.e < p_from or q.e > p_to or q.s > v_today;
    for u in select pp.user_id as uid from public.pay_profiles pp
              where pp.bonus_plan = 'lead' and (p_user is null or pp.user_id = p_user) loop
      for per in
        select distinct (public.pay_period_of(d::date)).starts_on as s, (public.pay_period_of(d::date)).ends_on as e
          from generate_series(q.s - 180, q.s - 1, interval '1 day') d
      loop
        continue when per.e >= q.s;
        for h in
          select per.s as hs, least(per.s + v_first - 1, per.e) as he
          union all
          select per.s + v_first, per.e where per.s + v_first <= per.e
        loop
          v_was := public.bonus_tier(v_rules->'lead_weekly', public.bonus_units(u.uid, h.hs, h.he, q.s::timestamp at time zone v_tz));
          continue when v_was = 0;
          v_n := public.bonus_units(u.uid, h.hs, h.he, least(now(), (q.e + 1)::timestamp at time zone v_tz));
          v_amt := public.bonus_tier(v_rules->'lead_weekly', v_n);
          if v_amt < v_was then
            user_id := u.uid; plan := 'lead_adjust'; label := 'Units bonus taken back'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := v_amt - v_was; paid_from := q.s; paid_to := q.e;
            return next;
          end if;
        end loop;
      end loop;
    end loop;
  end loop;

  -- An appointment manager's month: each tier paid in the period its last appointment's date passes.
  for m in select generate_series(date_trunc('month', p_from - 150)::date, date_trunc('month', p_to)::date, interval '1 month')::date loop
    for u in select pp.user_id as uid from public.pay_profiles pp
              where pp.bonus_plan = 'appointment' and (p_user is null or pp.user_id = p_user) loop
      v_n := public.bonus_appointments(u.uid, m, (m + interval '1 month')::date - 1);
      v_prev := 0;
      for t in select (x->>'at')::int as at_n, (x->>'amount')::numeric as amt
                 from jsonb_array_elements(v_rules->'appt_monthly') x order by 1 loop
        exit when v_n < t.at_n;
        -- The date the tier is reached: the month over, and the t.at_n-th appointment's date passed.
        select greatest((m + interval '1 month')::date,
                        coalesce(a.appt_date, (a.created_at at time zone public.business_tz())::date) + 1) into v_at
          from public.appointments a
         where a.user_id = u.uid and a.deleted_at is null and a.invalid_at is null and a.qa_status is distinct from 'failed'
           and a.created_at >= (m::timestamp at time zone public.business_tz())
           and a.created_at <  (((m + interval '1 month')::date)::timestamp at time zone public.business_tz())
         order by coalesce(a.appt_date, (a.created_at at time zone public.business_tz())::date), a.id
         offset t.at_n - 1 limit 1;
        if v_at is not null and v_at <= v_today then
          select * into v_paid from public.pay_period_of(v_at);
          if v_paid.ends_on between p_from and p_to then
            user_id := u.uid; plan := 'appt_monthly'; label := to_char(m, 'FMMonth') || ' valid appointments';
            from_day := m; to_day := (m + interval '1 month')::date - 1; counted := t.at_n;
            amount := case when coalesce((v_rules->>'monthly_total')::boolean, true) then t.amt - v_prev else t.amt end;
            paid_from := v_paid.starts_on; paid_to := v_paid.ends_on;
            if amount > 0 then return next; end if;
          end if;
        end if;
        v_prev := t.amt;
      end loop;
    end loop;
  end loop;
end $$;
revoke execute on function public.pay_bonuses(date, date, bigint) from public, anon;
grant execute on function public.pay_bonuses(date, date, bigint) to authenticated;

/**
 * A bonus just reached in this half of the pay period: its manager congratulated, once. A lead manager
 * at each units tier; an appointment manager at each step of the scale (the 21st valid, the 31st…).
 */
create or replace function public.bonus_notify(p_user bigint)
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_rules jsonb := public.bonus_rules();
  v_first int   := greatest(coalesce((v_rules->>'first_days')::int, 5), 1);
  v_today date  := (now() at time zone public.business_tz())::date;
  v_plan  text;
  per     record;
  v_hs    date;
  v_he    date;
  v_n     numeric;
  t       record;
  v_new   boolean;
  v_days  text;
begin
  select bonus_plan into v_plan from public.pay_profiles where user_id = p_user;
  if v_plan is null then return; end if;
  select * into per from public.pay_period_of(v_today);
  if v_today < per.starts_on + v_first then
    v_hs := per.starts_on; v_he := least(per.starts_on + v_first - 1, per.ends_on);
  else
    v_hs := per.starts_on + v_first; v_he := per.ends_on;
  end if;
  v_days := to_char(v_hs, 'FMMM/FMDD') || '–' || to_char(v_he, 'FMMM/FMDD');
  if v_plan = 'lead' then
    v_n := public.bonus_units(p_user, v_hs, v_he);
    for t in select (x->>'at')::numeric as at_n, (x->>'amount')::numeric as amt
               from jsonb_array_elements(v_rules->'lead_weekly') x order by 1 loop
      continue when v_n < t.at_n;
      insert into public.bonus_notices (user_id, key) values (p_user, 'lead:' || v_hs || ':' || t.at_n)
      on conflict do nothing returning true into v_new;
      if v_new then
        -- Written straight in: notify_users() leaves out whoever is acting, and here that is the manager themselves.
        insert into public.notifications (user_id, kind, title, body, link)
        values (p_user, 'system', 'Congrats! You hit your ' || to_char(t.amt, 'FM$999,990') || ' bonus',
          t.at_n || ' units ' || v_days || ' · on this pay period''s check', '/reports/pay');
      end if;
      v_new := null;
    end loop;
  else
    v_n := public.bonus_appointments(p_user, v_hs, v_he);
    for t in select (x->>'from')::numeric as at_n, (x->>'each')::numeric as each_
               from jsonb_array_elements(v_rules->'appt_weekly_scale') x order by 1 loop
      continue when v_n < t.at_n;
      insert into public.bonus_notices (user_id, key) values (p_user, 'appointment:' || v_hs || ':' || t.at_n)
      on conflict do nothing returning true into v_new;
      if v_new then
        insert into public.notifications (user_id, kind, title, body, link)
        values (p_user, 'system',
          'Congrats! You hit your ' || to_char(public.bonus_scale(v_rules->'appt_weekly_scale', t.at_n), 'FM$999,990') || ' bonus',
          t.at_n || ' valid appointments set ' || v_days || ' · ' || to_char(t.each_, 'FM$999,990') || ' more for each one after this · on next pay period''s check, if they stay valid',
          '/reports/pay');
      end if;
      v_new := null;
    end loop;
  end if;
end $$;
revoke execute on function public.bonus_notify(bigint) from public, anon, authenticated;

-- ==============================================================================================================
-- 20270201100000_call_activity_team.sql
-- ==============================================================================================================

-- Call Activity, as Sean asked (Nov 2026): on a manager's dashboard their own line to begin with, and
-- the team to open (the account managers only: no administrators, and no client's Sales Rep); and the
-- time of each person's first call.
--
--   p_scope  'all'   everyone on the phone (administrators' default; a manager asking for it gets 'team')
--            'team'  active account managers who are not a client's Sales Rep
--            'me'    p_user's line alone (a manager's own, whatever p_user they give)
--   first_call  the start of their first call out in the days asked for
--
-- Safe to run more than once.

drop function if exists public.phone_call_report(date, date);
drop function if exists public.phone_call_report(date, date, text, bigint);

create function public.phone_call_report(p_from date, p_to date, p_scope text default 'all', p_user bigint default null)
returns table (
  user_id bigint, first_name text, last_name text, role text,
  total bigint, out_handled bigint, out_cancelled bigint, in_handled bigint, missed bigint,
  talk_seconds bigint, on_call boolean, first_call timestamptz
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz    text    := public.business_tz();
  v_admin boolean := public.is_admin();
  v_scope text    := coalesce(nullif(p_scope, ''), 'all');
  v_user  bigint  := p_user;
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only administrators and account managers see call activity' using errcode = '42501';
  end if;
  if v_scope not in ('all', 'team', 'me') then v_scope := 'all'; end if;
  if not v_admin then
    if v_scope = 'all' then v_scope := 'team'; end if;
    v_user := public.app_user_id();
  end if;
  if v_scope = 'me' and v_user is null then v_user := public.app_user_id(); end if;

  return query
  with c as (
    select pc.user_id, pc.call_sid, pc.parent_sid, pc.direction, pc.talk_seconds, pc.answered_at, pc.ended_at, pc.started_at,
           case
             when pc.direction = 'out' then
               case when pc.answered_at is not null then 'out_handled' when pc.ended_at is not null then 'out_cancelled' end
             -- The call in itself (no one's): missed by no one in particular when it ended having rung nobody.
             when pc.user_id is null then
               case when pc.call_sid = pc.parent_sid and pc.ended_at is not null
                     and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.call_sid and s.call_sid <> pc.call_sid and s.rang_at is not null)
                 then 'missed' end
             when pc.answered_at is not null then 'in_handled'
             -- A person's leg: missed when it rang them and nobody took the call.
             when pc.ended_at is not null and pc.rang_at is not null
                  and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.parent_sid and s.answered_at is not null)
               then 'missed'
           end as kind
      from public.phone_calls pc
     where pc.started_at >= (p_from::timestamp at time zone v_tz)
       and pc.started_at <  ((p_to + 1)::timestamp at time zone v_tz)
  ),
  reps as (
    select distinct co.sales_rep_id as id from public.companies co
     where co.sales_rep_id is not null and co.deleted_at is null
  ),
  people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where case v_scope
             when 'me' then u.id = v_user
             when 'team' then u.role = 'manager' and u.status = 'active' and u.deleted_at is null
                              and u.id not in (select r.id from reps r)
             else (u.role = 'manager' and u.status = 'active') or u.id in (select c.user_id from c where c.kind is not null)
           end
  )
  select p.id, p.first_name, p.last_name, p.role,
         count(c.kind),
         count(*) filter (where c.kind = 'out_handled'),
         count(*) filter (where c.kind = 'out_cancelled'),
         count(*) filter (where c.kind = 'in_handled'),
         count(*) filter (where c.kind = 'missed'),
         coalesce(sum(c.talk_seconds) filter (where c.kind in ('out_handled', 'in_handled')), 0)::bigint,
         coalesce(bool_or(c.answered_at is not null and c.ended_at is null and c.started_at > now() - interval '4 hours'), false),
         min(c.started_at) filter (where c.direction = 'out')
    from people p
    left join c on c.user_id = p.id
   group by p.id, p.first_name, p.last_name, p.role
  union all
  -- Calls in that rang no one: on everyone's view only.
  select null, null, null, null, count(*), 0, 0, 0, count(*), 0, false, null
    from c
   where v_scope = 'all' and c.user_id is null and c.call_sid = c.parent_sid and c.kind = 'missed'
  having count(*) > 0;
end $$;

revoke execute on function public.phone_call_report(date, date, text, bigint) from public, anon;
grant execute on function public.phone_call_report(date, date, text, bigint) to authenticated;

-- ==============================================================================================================
-- 20270202100000_call_times.sql
-- ==============================================================================================================

-- Call Activity's chart (Sean, Nov 2026): a day's calls on the Lighthouse phone by the half hour, for
-- everyone on the card or one manager, to see where a day's calls stopped and started again. The calls
-- and the people are counted as phone_call_report() counts them (its 'all', 'team' and 'me').
--
-- Safe to run more than once.

drop function if exists public.phone_call_times(date, text, bigint);

/** p_day's calls by person and half hour: slot (minutes past midnight, business time, 0, 30, 60…) and how many. */
create function public.phone_call_times(p_day date, p_scope text default 'all', p_user bigint default null)
returns table (user_id bigint, slot int, calls bigint)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz    text    := public.business_tz();
  v_admin boolean := public.is_admin();
  v_scope text    := coalesce(nullif(p_scope, ''), 'all');
  v_user  bigint  := p_user;
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only administrators and account managers see call activity' using errcode = '42501';
  end if;
  if v_scope not in ('all', 'team', 'me') then v_scope := 'all'; end if;
  if not v_admin then
    if v_scope = 'all' then v_scope := 'team'; end if;
    v_user := public.app_user_id();
  end if;
  if v_scope = 'me' and v_user is null then v_user := public.app_user_id(); end if;

  return query
  with c as (
    select pc.user_id, pc.started_at,
           case
             when pc.direction = 'out' then
               case when pc.answered_at is not null then 'out_handled' when pc.ended_at is not null then 'out_cancelled' end
             when pc.user_id is null then null
             when pc.answered_at is not null then 'in_handled'
             when pc.ended_at is not null and pc.rang_at is not null
                  and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.parent_sid and s.answered_at is not null)
               then 'missed'
           end as kind
      from public.phone_calls pc
     where pc.user_id is not null
       and pc.started_at >= (p_day::timestamp at time zone v_tz)
       and pc.started_at <  ((p_day + 1)::timestamp at time zone v_tz)
  ),
  reps as (
    select distinct co.sales_rep_id as id from public.companies co
     where co.sales_rep_id is not null and co.deleted_at is null
  ),
  people as (
    select u.id from public.users u
     where case v_scope
             when 'me' then u.id = v_user
             when 'team' then u.role = 'manager' and u.status = 'active' and u.deleted_at is null
                              and u.id not in (select r.id from reps r)
             else true
           end
  )
  select c.user_id,
         (floor(extract(epoch from ((c.started_at at time zone v_tz) - p_day::timestamp)) / 1800) * 30)::int,
         count(*)
    from c
    join people p on p.id = c.user_id
   where c.kind is not null
   group by 1, 2
   order by 2, 1;
end $$;

revoke execute on function public.phone_call_times(date, text, bigint) from public, anon;
grant execute on function public.phone_call_times(date, text, bigint) to authenticated;

-- ==============================================================================================================
-- 20270203100000_manager_time_zones.sql
-- ==============================================================================================================

-- Call Activity on each manager's own clock (Sean, Nov 2026): the time zone on a user's account is now
-- a real clock. Each person's first call, and their line on the chart, read in their time zone; the
-- whole team's chart stays on the business's clock. Mountain is split in two: Arizona keeps standard
-- time all year, Utah and Montana move their clocks.
--
-- Safe to run more than once.

alter table public.timezones add column if not exists iana text;
comment on column public.timezones.iana is 'The clock (IANA name, e.g. America/Chicago); null: the business''s.';

update public.timezones set iana = case
    when upper(btrim(name)) in ('EST', 'EDT', 'ET', 'EASTERN')  then 'America/New_York'
    when upper(btrim(name)) in ('CST', 'CDT', 'CT', 'CENTRAL')  then 'America/Chicago'
    when upper(btrim(name)) in ('MST', 'MOUNTAIN')              then 'America/Phoenix'
    when upper(btrim(name)) in ('MDT', 'MT')                    then 'America/Denver'
    when upper(btrim(name)) in ('PST', 'PDT', 'PT', 'PACIFIC')  then 'America/Los_Angeles'
    when upper(btrim(name)) in ('AKST', 'AKDT', 'ALASKA')       then 'America/Anchorage'
    when upper(btrim(name)) in ('HST', 'HAWAII')                then 'Pacific/Honolulu'
  end
 where iana is null;

-- MST is Arizona's (no daylight saving); Mountain with daylight saving is its own.
update public.timezones set name = 'MST (Arizona)'
 where upper(btrim(name)) = 'MST' and not exists (select 1 from public.timezones where name = 'MST (Arizona)');
insert into public.timezones (name, iana)
select 'MT (Utah, Montana)', 'America/Denver'
 where not exists (select 1 from public.timezones where name = 'MT (Utah, Montana)');

/** The person's clock: their account's time zone, else the business's. */
create or replace function public.user_tz(p_user bigint)
returns text
language sql stable security definer set search_path = public as $$
  select coalesce((select public.known_tz(z.iana) from public.users u join public.timezones z on z.id = u.timezone_id where u.id = p_user),
                  public.business_tz())
$$;
revoke execute on function public.user_tz(bigint) from public, anon;
grant execute on function public.user_tz(bigint) to authenticated;

drop function if exists public.phone_call_report(date, date);
drop function if exists public.phone_call_report(date, date, text, bigint);

create function public.phone_call_report(p_from date, p_to date, p_scope text default 'all', p_user bigint default null)
returns table (
  user_id bigint, first_name text, last_name text, role text,
  total bigint, out_handled bigint, out_cancelled bigint, in_handled bigint, missed bigint,
  talk_seconds bigint, on_call boolean, first_call timestamptz, time_zone text
)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz    text    := public.business_tz();
  v_admin boolean := public.is_admin();
  v_scope text    := coalesce(nullif(p_scope, ''), 'all');
  v_user  bigint  := p_user;
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only administrators and account managers see call activity' using errcode = '42501';
  end if;
  if v_scope not in ('all', 'team', 'me') then v_scope := 'all'; end if;
  if not v_admin then
    if v_scope = 'all' then v_scope := 'team'; end if;
    v_user := public.app_user_id();
  end if;
  if v_scope = 'me' and v_user is null then v_user := public.app_user_id(); end if;

  return query
  with c as (
    select pc.user_id, pc.call_sid, pc.parent_sid, pc.direction, pc.talk_seconds, pc.answered_at, pc.ended_at, pc.started_at,
           case
             when pc.direction = 'out' then
               case when pc.answered_at is not null then 'out_handled' when pc.ended_at is not null then 'out_cancelled' end
             -- The call in itself (no one's): missed by no one in particular when it ended having rung nobody.
             when pc.user_id is null then
               case when pc.call_sid = pc.parent_sid and pc.ended_at is not null
                     and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.call_sid and s.call_sid <> pc.call_sid and s.rang_at is not null)
                 then 'missed' end
             when pc.answered_at is not null then 'in_handled'
             -- A person's leg: missed when it rang them and nobody took the call.
             when pc.ended_at is not null and pc.rang_at is not null
                  and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.parent_sid and s.answered_at is not null)
               then 'missed'
           end as kind
      from public.phone_calls pc
     where pc.started_at >= (p_from::timestamp at time zone v_tz)
       and pc.started_at <  ((p_to + 1)::timestamp at time zone v_tz)
  ),
  reps as (
    select distinct co.sales_rep_id as id from public.companies co
     where co.sales_rep_id is not null and co.deleted_at is null
  ),
  people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where case v_scope
             when 'me' then u.id = v_user
             when 'team' then u.role = 'manager' and u.status = 'active' and u.deleted_at is null
                              and u.id not in (select r.id from reps r)
             else (u.role = 'manager' and u.status = 'active') or u.id in (select c.user_id from c where c.kind is not null)
           end
  )
  select p.id, p.first_name, p.last_name, p.role,
         count(c.kind),
         count(*) filter (where c.kind = 'out_handled'),
         count(*) filter (where c.kind = 'out_cancelled'),
         count(*) filter (where c.kind = 'in_handled'),
         count(*) filter (where c.kind = 'missed'),
         coalesce(sum(c.talk_seconds) filter (where c.kind in ('out_handled', 'in_handled')), 0)::bigint,
         coalesce(bool_or(c.answered_at is not null and c.ended_at is null and c.started_at > now() - interval '4 hours'), false),
         min(c.started_at) filter (where c.direction = 'out'),
         (select public.known_tz(z.iana) from public.users u join public.timezones z on z.id = u.timezone_id where u.id = p.id)
    from people p
    left join c on c.user_id = p.id
   group by p.id, p.first_name, p.last_name, p.role
  union all
  -- Calls in that rang no one: on everyone's view only.
  select null, null, null, null, count(*), 0, 0, 0, count(*), 0, false, null, null
    from c
   where v_scope = 'all' and c.user_id is null and c.call_sid = c.parent_sid and c.kind = 'missed'
  having count(*) > 0;
end $$;

revoke execute on function public.phone_call_report(date, date, text, bigint) from public, anon;
grant execute on function public.phone_call_report(date, date, text, bigint) to authenticated;

-- phone_call_times: each half hour on the business's clock (slot) and on the person's own (local_slot).
drop function if exists public.phone_call_times(date, text, bigint);

create function public.phone_call_times(p_day date, p_scope text default 'all', p_user bigint default null)
returns table (user_id bigint, slot int, local_slot int, calls bigint)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz    text    := public.business_tz();
  v_admin boolean := public.is_admin();
  v_scope text    := coalesce(nullif(p_scope, ''), 'all');
  v_user  bigint  := p_user;
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only administrators and account managers see call activity' using errcode = '42501';
  end if;
  if v_scope not in ('all', 'team', 'me') then v_scope := 'all'; end if;
  if not v_admin then
    if v_scope = 'all' then v_scope := 'team'; end if;
    v_user := public.app_user_id();
  end if;
  if v_scope = 'me' and v_user is null then v_user := public.app_user_id(); end if;

  return query
  with c as (
    select pc.user_id, pc.started_at,
           case
             when pc.direction = 'out' then
               case when pc.answered_at is not null then 'out_handled' when pc.ended_at is not null then 'out_cancelled' end
             when pc.user_id is null then null
             when pc.answered_at is not null then 'in_handled'
             when pc.ended_at is not null and pc.rang_at is not null
                  and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.parent_sid and s.answered_at is not null)
               then 'missed'
           end as kind
      from public.phone_calls pc
     where pc.user_id is not null
       and pc.started_at >= (p_day::timestamp at time zone v_tz)
       and pc.started_at <  ((p_day + 1)::timestamp at time zone v_tz)
  ),
  reps as (
    select distinct co.sales_rep_id as id from public.companies co
     where co.sales_rep_id is not null and co.deleted_at is null
  ),
  people as (
    select u.id from public.users u
     where case v_scope
             when 'me' then u.id = v_user
             when 'team' then u.role = 'manager' and u.status = 'active' and u.deleted_at is null
                              and u.id not in (select r.id from reps r)
             else true
           end
  )
  select c.user_id,
         (floor(extract(epoch from ((c.started_at at time zone v_tz) - p_day::timestamp)) / 1800) * 30)::int,
         (floor(extract(epoch from ((c.started_at at time zone public.user_tz(c.user_id))::time)) / 1800) * 30)::int,
         count(*)
    from c
    join people p on p.id = c.user_id
   where c.kind is not null
   group by 1, 2, 3
   order by 2, 1;
end $$;

revoke execute on function public.phone_call_times(date, text, bigint) from public, anon;
grant execute on function public.phone_call_times(date, text, bigint) to authenticated;

-- ==============================================================================================================
-- 20270204100000_appointment_special_pay.sql
-- ==============================================================================================================

-- =============================================================================
-- Special Pay on appointment projects (Sean, Nov 2026: "add the same 'special pay' section that Lead
-- projects have to the Appt projects ... Goal for Appts per pay period with special pay that will apply")
--
-- As on a DB dev project, with appointments in place of leads: an appointment project's goal is so many
-- appointments one rep sets on it in a pay period, and its Special Pay so much more for each. Once the
-- goal is hit, each of those appointments earns it, and each one after it that pay period; the rep is
-- told when they hit it. An appointment found invalid (charged back) takes its Special Pay back with it.
--
--   set_project_special_pay()   a DB dev or an appointment project
--   award_special_pay()         leads on a DB dev project; appointments on an appointment project
--   pay()                       as before, Special Pay looked at after an appointment's pay too
--   charge_back()               a lead's chargeback takes back its lead Special Pay; an appointment's, its own
--
-- Safe to run more than once.
-- =============================================================================

comment on column public.projects.special_goal is 'Special Pay: leads (DB dev) or appointments (appointment project) one rep makes on this project in a pay period to earn it (null: none)';
comment on column public.projects.special_rate is 'Special Pay: USD more for each of those leads or appointments, once the goal is hit';

/** An administrator sets a DB dev or appointment project's Special Pay: the goal (leads or appointments a pay period) and the pay each; both null/0 for none. */
create or replace function public.set_project_special_pay(p_project_id bigint, p_goal int, p_rate numeric)
returns jsonb
language plpgsql security invoker set search_path = public as $$
declare
  v_type text;
  v_what text;
  v_row  public.projects;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can set pay rates' using errcode = '42501';
  end if;
  select t.code into v_type from public.projects p left join public.project_types t on t.id = p.project_type_id where p.id = p_project_id;
  if not found then
    raise exception 'That project no longer exists' using errcode = 'P0002';
  end if;
  v_what := case when v_type = 'APPT' then 'appointment' else 'lead' end;
  if p_goal is not null and (p_goal < 1 or p_goal > 1000) then
    raise exception 'Special Pay goal: a number of %s from 1 to 1,000', v_what || 's' using errcode = '22023';
  end if;
  if coalesce(p_rate, 0) < 0 or coalesce(p_rate, 0) > 1000 then
    raise exception 'Special Pay must be between $0.00 and $1,000.00 a %', v_what using errcode = '22023';
  end if;
  if (p_goal is null) <> (coalesce(p_rate, 0) = 0) then
    raise exception 'Special Pay needs both a goal and an amount a % (or neither)', v_what using errcode = '22023';
  end if;
  if p_goal is not null and v_type is distinct from 'DBDV' and v_type is distinct from 'APPT' then
    raise exception 'Special Pay is for DB dev and appointment projects' using errcode = '22023';
  end if;
  update public.projects set special_goal = p_goal, special_rate = round(coalesce(p_rate, 0), 2)
   where id = p_project_id
  returning * into v_row;
  return jsonb_build_object('id', v_row.id, 'special_goal', v_row.special_goal, 'special_rate', v_row.special_rate);
end $$;
revoke execute on function public.set_project_special_pay(bigint, int, numeric) from public, anon;
grant execute on function public.set_project_special_pay(bigint, int, numeric) to authenticated;

/**
 * Pays Special Pay once p_user hits p_project's goal this pay period: on a DB dev project, its leads; on an
 * appointment project, its appointments. Each one counted earns it once (an appointment's Special Pay kept
 * with the appointment). Tells the rep the first time in a pay period. Returns how many were paid now.
 */
create or replace function public.award_special_pay(p_user bigint, p_project bigint)
returns int
language plpgsql security definer set search_path = public as $$
declare
  v_tz    text := public.business_tz();
  v_goal  int;
  v_rate  numeric(10,2);
  v_name  text;
  v_type  text;
  v_kind  text;
  v_what  text;
  v_from  date;
  v_to    date;
  v_had   int;
  v_count int;
  v_new   int;
  v_rule  bigint;
  v_on    boolean;
begin
  select p.special_goal, p.special_rate, p.name, t.code into v_goal, v_rate, v_name, v_type
    from public.projects p left join public.project_types t on t.id = p.project_type_id
   where p.id = p_project;
  if p_user is null or v_type not in ('DBDV', 'APPT') or coalesce(v_goal, 0) < 1 or coalesce(v_rate, 0) <= 0 then
    return 0;
  end if;
  v_kind := case v_type when 'APPT' then 'appointment' else 'lead' end;
  v_what := v_kind || 's';
  -- One rep and project at a time, so two saved together never pay one twice.
  perform pg_advisory_xact_lock(hashtextextended(format('special_pay:%s:%s', p_user, p_project), 0));
  select pp.starts_on, pp.ends_on into v_from, v_to from public.pay_period_of((now() at time zone v_tz)::date) pp;

  -- Their leads (or appointments) on it this period, any charged back left out.
  create temp table if not exists special_pay_earned (lead_id bigint, appointment_id bigint, ord bigint) on commit drop;
  truncate special_pay_earned;
  insert into special_pay_earned
  select pe.lead_id, case when v_kind = 'appointment' then pe.appointment_id end, pe.id
    from public.pay_events pe
   where pe.user_id = p_user and pe.project_id = p_project and pe.kind = v_kind and not pe.is_chargeback
     and not exists (select 1 from public.pay_events r where r.reverses_id = pe.id)
     and (v_kind = 'lead' or pe.appointment_id is not null)
     and pe.created_at >= (v_from::timestamp at time zone v_tz)
     and pe.created_at <  ((v_to + 1)::timestamp at time zone v_tz);
  select count(*) into v_count from special_pay_earned;
  if v_count < v_goal then
    return 0;
  end if;

  -- Already hit this period? (Then this is one more, and no second message.)
  select count(*) into v_had
    from public.pay_events b
   where b.user_id = p_user and b.project_id = p_project and b.kind = 'special' and not b.is_chargeback
     and not exists (select 1 from public.pay_events r where r.reverses_id = b.id)
     and b.created_at >= (v_from::timestamp at time zone v_tz)
     and b.created_at <  ((v_to + 1)::timestamp at time zone v_tz);

  insert into public.pay_events (user_id, project_id, lead_id, appointment_id, kind, amount, note, created_by)
  select p_user, p_project, e.lead_id, e.appointment_id, 'special', v_rate,
         format('Special Pay: %s %s on this project in the pay period %s – %s', v_goal, v_what, to_char(v_from, 'FMMM/FMDD'), to_char(v_to, 'FMMM/FMDD')),
         public.app_user_id()
    from special_pay_earned e
   where (v_kind = 'lead' and e.lead_id is not null
          and not exists (select 1 from public.pay_events b
                           where b.kind = 'special' and b.lead_id = e.lead_id and b.appointment_id is null and b.user_id = p_user and not b.is_chargeback
                             and not exists (select 1 from public.pay_events r where r.reverses_id = b.id)))
      or (v_kind = 'appointment'
          and not exists (select 1 from public.pay_events b
                           where b.kind = 'special' and b.appointment_id = e.appointment_id and b.user_id = p_user and not b.is_chargeback
                             and not exists (select 1 from public.pay_events r where r.reverses_id = b.id)))
   order by e.ord;
  get diagnostics v_new = row_count;

  if v_new > 0 and v_had = 0 then
    select r.id, r.enabled into v_rule, v_on from public.alert_rules r where r.trigger = 'special_pay' order by r.id limit 1;
    if v_rule is null or v_on then
      insert into public.notifications (user_id, kind, title, body, link)
      select u.id, 'lead',
             left(format('Special Pay: you hit %s %s on %s', v_goal, v_what, v_name), 160),
             left(format('That is %s more for each of your %s %s there this pay period (%s so far), and for each one after it until %s. It is on your pay summary as Special Pay.',
                         to_char(v_rate, 'FM$999,990.00'), v_count, v_what, to_char(v_rate * v_new, 'FM$999,990.00'), to_char(v_to, 'FMMM/FMDD')), 1000),
             '/reports/pay'
        from public.users u where u.id = p_user and u.status = 'active';
      if found and v_rule is not null then
        insert into public.alert_log (rule_id, subject, detail, status)
        values (v_rule, left(format('Special Pay: %s %s on %s', v_goal, v_what, v_name), 200), 'In-app to 1 person', 'sent');
      end if;
    end if;
  end if;
  return v_new;
end $$;
revoke execute on function public.award_special_pay(bigint, bigint) from public, anon, authenticated;

-- pay(): as before (20270130), Special Pay looked at after an appointment's pay as well as a lead's.
create or replace function public.pay(p_user bigint, p_project bigint, p_kind text, p_lead bigint,
                                      p_appointment bigint, p_call bigint, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_amount numeric(10,2);
  v_id bigint;
begin
  -- A lead is developed once: no second payment for it unless the first was
  -- charged back (a lead moved back to its DBDev project and promoted again).
  if p_kind = 'lead' and exists (
       select 1 from public.pay_events pe
        where pe.lead_id = p_lead and pe.kind = 'lead' and not pe.is_chargeback
          and not exists (select 1 from public.pay_events r where r.reverses_id = pe.id)) then
    return '[]'::jsonb;
  end if;
  -- A manager's own appointment and confirmation rates, when they have them, in place of the project's.
  select case p_kind when 'lead' then pr.lead_rate
                     when 'appointment' then coalesce(pp.appointment_rate, pr.appointment_rate)
                     else coalesce(pp.confirmation_rate, pr.confirmation_rate) end
    into v_amount
    from public.projects pr left join public.pay_profiles pp on pp.user_id = p_user
   where pr.id = p_project;
  insert into public.pay_events (user_id, project_id, lead_id, appointment_id, call_record_id, kind, amount, note, created_by)
  values (p_user, p_project, p_lead, p_appointment, p_call, p_kind, coalesce(v_amount, 0), p_note, public.app_user_id())
  returning id into v_id;
  if p_kind in ('lead', 'appointment') then
    perform public.award_special_pay(p_user, p_project);
  end if;
  return jsonb_build_object('id', v_id, 'user_id', p_user, 'kind', p_kind, 'amount', coalesce(v_amount, 0));
end $$;
revoke execute on function public.pay(bigint, bigint, text, bigint, bigint, bigint, text) from public, anon, authenticated;

-- charge_back(): as before; a lead's chargeback takes back its lead's Special Pay, an appointment's its own.
create or replace function public.charge_back(p_lead bigint, p_appointment bigint, p_kinds text[], p_call bigint, p_note text)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  e record;
  v_out jsonb := '[]'::jsonb;
  v_id bigint;
  v_lead boolean := 'lead' = any(p_kinds);
  v_appt boolean := 'appointment' = any(p_kinds);
  v_kinds text[] := case when 'lead' = any(p_kinds) or 'appointment' = any(p_kinds) then p_kinds || array['special'] else p_kinds end;
begin
  for e in
    select pe.* from public.pay_events pe
     where pe.kind = any(v_kinds)
       and pe.reverses_id is null
       and (p_lead is null or pe.lead_id = p_lead)
       and (p_appointment is null or pe.appointment_id = p_appointment)
       -- Special Pay goes with what earned it: a lead's (no appointment), or an appointment's.
       and (pe.kind <> 'special' or 'special' = any(p_kinds)
            or (v_lead and pe.appointment_id is null)
            or (v_appt and pe.appointment_id is not null))
       and not exists (select 1 from public.pay_events x where x.reverses_id = pe.id)
     order by pe.id
     for update
  loop
    insert into public.pay_events (user_id, project_id, lead_id, appointment_id, call_record_id, kind, amount, reverses_id, note, created_by)
    values (e.user_id, e.project_id, e.lead_id, e.appointment_id, p_call, e.kind, -e.amount, e.id, p_note, public.app_user_id())
    returning id into v_id;
    v_out := v_out || jsonb_build_object('id', v_id, 'user_id', e.user_id, 'kind', e.kind, 'amount', -e.amount, 'reverses', e.id);
  end loop;
  return v_out;
end $$;
revoke execute on function public.charge_back(bigint, bigint, text[], bigint, text) from public, anon, authenticated;

-- ==============================================================================================================
-- 20270205100000_import_old_appt_results.sql
-- ==============================================================================================================

-- The old system's appointment results, read right on import (Sean, Nov 2026):
--   "-$Appointment" and "-$Survey Appointment" were its invalid appointments: they come in as
--   Appointment-Invalid (they were read as Appointment, and counted as appointments).
--   "Appt From X-Date" is read on a DB dev project's column too, as on an appointment project's.
-- (An appointment result with no appointment date comes in as Lead-No Contact: src/features/imports/actions.js.)
--
-- Safe to run more than once.

-- Off Appointment.
update public.call_results
   set aliases = array(select a from unnest(aliases) a where a not in ('-$appointment', '-$survey appointment', '-$phone appointment', '-$appt from x-date'))
 where name = 'Appointment' and project_type in ('APPT', 'DBDV');

-- Onto Appointment-Invalid, on both kinds of project.
update public.call_results
   set aliases = array(select distinct a from unnest(coalesce(aliases, '{}') || array['-$appointment', '-$survey appointment', '-$phone appointment', '-$appt from x-date']) a order by a)
 where name = 'Appointment-Invalid' and project_type in ('APPT', 'DBDV');

-- "Appt From X-Date" on a DB dev project's column too.
update public.call_results
   set aliases = array(select distinct a from unnest(coalesce(aliases, '{}') || array['appt from x-date']) a order by a)
 where name = 'Appointment' and project_type = 'DBDV';

-- ==============================================================================================================
-- 20270206100000_delete_sent_names.sql
-- ==============================================================================================================

-- Deleting a lead project, and the names it sent on (Sean, Nov 2026: "removes the lists from the lead project
-- I delete and also pulls out those names from the appt project"): a DB dev project's names promoted to its
-- appointment project (as leads or appointments) stay there when the DB dev project is deleted. Asked to, they
-- go with it: only those from that project (each lead keeps the project it came from, source_project_id), never
-- the names other DB dev projects sent to the same appointment project. They go as the project's own names do,
-- with their appointments, marked as taken by it, so restoring the project under Settings › Deleted records
-- brings them back too. Calls made and pay earned stay as they are.
--
--   project_sent_counts(ids)   how many names each DB dev project has on another project now (for the delete box)
--   remove_sent_names(id)      takes them off with the (deleted) project
--
-- Safe to run more than once.

/** How many of each project's names it sent on are on another project now, not deleted. */
create or replace function public.project_sent_counts(p_ids bigint[])
returns table (project_id bigint, sent bigint)
language sql stable security invoker set search_path = public as $$
  select l.source_project_id, count(*)
    from public.leads l
   where l.source_project_id = any(p_ids)
     and l.project_id is distinct from l.source_project_id
     and l.deleted_at is null
   group by l.source_project_id
$$;
revoke execute on function public.project_sent_counts(bigint[]) from public, anon;
grant execute on function public.project_sent_counts(bigint[]) to authenticated;

/**
 * Takes the names p_project sent on to another project off with it (it is deleted, or being deleted): each
 * lead and its appointments, marked as gone with the project. Returns how many names.
 */
create or replace function public.remove_sent_names(p_project bigint)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me  bigint := public.app_user_id();
  v_now timestamptz := now();
  v_via text := 'projects:' || p_project;
  v_n   integer;
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only an administrator can delete a project' using errcode = '42501';
  end if;
  update public.appointments a set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
   where a.deleted_at is null
     and a.lead_id in (select l.id from public.leads l
                        where l.source_project_id = p_project and l.project_id is distinct from p_project and l.deleted_at is null);
  update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
   where source_project_id = p_project and project_id is distinct from p_project and deleted_at is null;
  get diagnostics v_n = row_count;
  return v_n;
end $$;
revoke execute on function public.remove_sent_names(bigint) from public, anon;
grant execute on function public.remove_sent_names(bigint) to authenticated;

-- ==============================================================================================================
-- 20270207100000_lead_reference_indexes.sql
-- ==============================================================================================================

-- Indexes on the columns that point at a lead and had none (Nov 2026). Deleting a lead makes the database check
-- each of them for rows still pointing at it; unindexed, that is a pass over the whole table per lead deleted.
-- Removing the ~19,000 names of five test lists took over 7 minutes without finishing (leads.matched_from_lead_id
-- reads all of leads each time) and 6 seconds with these: the test-data wipe before going live, a project deleted
-- with its names, a list taken off.
--
-- Safe to run more than once.

create index if not exists leads_matched_from on public.leads (matched_from_lead_id) where matched_from_lead_id is not null;
create index if not exists feedback_lead on public.feedback (lead_id);
create index if not exists bulletin_board_lead on public.bulletin_board (lead_id);
create index if not exists documents_lead on public.documents (lead_id);
create index if not exists work_activity_lead on public.work_activity (lead_id);

-- ==============================================================================================================
-- 20270208100000_duplicate_result.sql
-- ==============================================================================================================

-- Duplicate (Sean, Nov 2026): "There's a high probability that we call a business that will end up being a duplicate
-- and should be marked accordingly (a business is under a DBA and other biz name, one has a work phone and the other a
-- mobile #, neither record has a contact name…): it wouldn't be flagged as a duplicate unless we actually called."
--
--   Duplicate / Lead-Duplicate   a result for each stage, as Branch / Lead-Branch are: off the call lists,
--                                reported as resolved, a button to give on a call. Not put on the client's
--                                removal list: the business is still on the list, as its other record.
--   The old system's "Duplicate" / "XD-Duplicate" come in as them on an import.
--
-- Safe to run more than once.

insert into public.call_results
  (project_type, name, sort_order, viable, callable, sort_last, effect, pay_kind, applies_to, status_code, action, aliases, delivers, client_removal)
values
  ('DBDV', 'Duplicate', 125, false, true, false, 'none', null, 'name', 'removed',
   'Another record of a business already on the list. Removed from DBDev call lists and reported as resolved by result type for DBDev project',
   array['duplicate', 'dup', 'dupe'], false, null),
  ('APPT', 'Lead-Duplicate', 132, false, true, false, 'none', null, 'name', 'removed',
   'Another record of a business already on the list. Removed from Appt project call lists',
   array['xd-duplicate', 'lead-duplicate', 'lead duplicate', 'xd duplicate'], false, null)
on conflict (project_type, name) do update set
  sort_order = excluded.sort_order, viable = excluded.viable, callable = excluded.callable,
  sort_last = excluded.sort_last, effect = excluded.effect, pay_kind = excluded.pay_kind,
  applies_to = excluded.applies_to, status_code = excluded.status_code,
  action = excluded.action, aliases = excluded.aliases, delivers = excluded.delivers, client_removal = excluded.client_removal;

-- ==============================================================================================================
-- 20270209100000_valid_not_updated.sql
-- ==============================================================================================================

-- Valid-Not Updated (Sean, Oct 29 and Nov 2026): "If no update was made by the client or an Admin for that appt by the
-- due date, can the system automatically change the Update Status to Valid-Not Updated (we'd need to add that result
-- for reporting). The red overdue date that's already listed will stay", "…and send the sales rep a notification."
--
--   client_result 'valid_not_updated'   Valid-Not Updated: given by the system, not offered to pick. The client (or an
--                                       administrator) can still give it a status afterwards, Sold and the rest.
--   mark_appointments_not_updated()     every hour: an appointment held, past its update's due date (update_due_on: 5
--                                       business days after it) with no status yet, is Valid-Not Updated, kept in its
--                                       update history as "Not updated by the due date". Not one found invalid (it
--                                       needs no update), nor one still waiting for QA (the client hasn't seen it).
--                                       The client's watchers (its Sales Rep) are told of one due in the last week;
--                                       the ones overdue before this ran (and an import's old appointments) quietly.
--   client_dashboard()                  counts them among the appointment results.
--
-- Safe to run more than once. It runs once at the end, so the appointments already overdue change straight away.

alter table public.appointments drop constraint if exists appointments_client_result_check;
alter table public.appointments add constraint appointments_client_result_check check (client_result in ('pending_appointment', 'no_status',
  'valid', 'valid_quoting', 'valid_not_quoting', 'quoted_not_sold', 'sold', 'invalid', 'reschedule', 'valid_not_updated'));

create or replace function public.appointment_update_label(p_status text)
returns text
language sql immutable set search_path = public as $$
  select case p_status
    when 'pending_appointment' then 'Pending Appointment' when 'no_status' then 'No Status'
    when 'valid' then 'Valid Appointment' when 'valid_quoting' then 'Valid-Quoting'
    when 'valid_not_quoting' then 'Valid-Not Quoting' when 'quoted_not_sold' then 'Quoted-Not Sold'
    when 'sold' then 'Sold Account' when 'invalid' then 'Invalid' when 'reschedule' then 'Please Reschedule'
    when 'valid_not_updated' then 'Valid-Not Updated'
    else p_status end;
$$;

-- The client dashboard's appointment results: Valid-Not Updated among them.
do $$
declare
  def text;
begin
  select pg_get_functiondef(p.oid) into def from pg_proc p where p.proname = 'client_dashboard' and p.pronamespace = 'public'::regnamespace;
  if def is not null and def not like '%valid_not_updated%' then
    execute replace(def, '''reschedule'']', '''reschedule'', ''valid_not_updated'']');
  end if;
end $$;

create or replace function public.mark_appointments_not_updated()
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_today   date := public.business_today();
  v_invalid bigint;
  v_n       integer := 0;
  r         record;
begin
  select id into v_invalid from public.appointment_statuses where name = 'Invalid';
  for r in
    select a.id, a.lead_id, a.appt_date, coalesce(a.project_id, a.set_project_id) as project_id, p.company_id,
           l.company_name, public.update_due_on(a.appt_date) as due
      from public.appointments a
      join public.leads l on l.id = a.lead_id and l.deleted_at is null
      join public.projects p on p.id = coalesce(a.project_id, a.set_project_id) and p.deleted_at is null
     where a.deleted_at is null and a.appt_date is not null
       and a.invalid_at is null and a.status_id is distinct from v_invalid
       and coalesce(a.qa_status, 'passed') = 'passed'
       and public.appointment_update_status(a.client_result, a.appt_date, a.appt_time) = 'no_status'
       and v_today > public.update_due_on(a.appt_date)
       for update of a skip locked
  loop
    update public.appointments
       set client_result = 'valid_not_updated', client_result_at = now(), client_result_by = null
     where id = r.id;
    insert into public.appointment_updates (appointment_id, lead_id, project_id, company_id, status, previous_status, note, created_by)
    values (r.id, r.lead_id, r.project_id, r.company_id, 'valid_not_updated', 'no_status',
            'Not updated by the due date, ' || to_char(r.due, 'FMMM/FMDD/YYYY'), null);
    if r.due >= v_today - 7 then
      perform public.notify_client_watchers(r.company_id, 'appointment',
        left('Not updated by the due date · ' || coalesce(r.company_name, 'an appointment'), 160),
        'Appointment ' || to_char(r.appt_date, 'FMMM/FMDD/YYYY') || ' · was due ' || to_char(r.due, 'FMMM/FMDD/YYYY')
          || ' · now Valid-Not Updated',
        '/leads/' || r.lead_id || '?tab=updates');
    end if;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;
revoke execute on function public.mark_appointments_not_updated() from public, anon, authenticated;

do $$
begin
  if to_regclass('cron.job') is null then
    raise notice 'pg_cron is not enabled: appointments are not marked Valid-Not Updated on a schedule';
    return;
  end if;
  if exists (select 1 from cron.job where jobname = 'mark-appointments-not-updated') then
    perform cron.unschedule('mark-appointments-not-updated');
  end if;
  perform cron.schedule('mark-appointments-not-updated', '20 * * * *', 'select public.mark_appointments_not_updated()');
end $$;

-- The ones already overdue, now.
select public.mark_appointments_not_updated();

-- ==============================================================================================================
-- 20270210100000_phone_lines.sql
-- ==============================================================================================================

-- The phone lines (Sean, Nov 2026), as the office has them on PanTerra, moved to Twilio:
--
--   "One of the toll-free #s is for Signature Marketing (rings to Mike or I) and the other toll-free # is for
--   managers… that auto-attendant says You've reached the insurance office with prompts to transfer to a direct
--   extension." "If a caller doesn't dial an extension: straight to a general voicemail, and 1-2 managers get those
--   messages." Managers call all over the country from a local caller ID, "changing it 2-3x per hour".
--
--   phone_lines        the account's Twilio numbers and what each is for:
--                        main       rings the people chosen (ring_user_ids), then their voicemail
--                        attendant  the "insurance office" greeting: an extension rings that manager, then their
--                                   voicemail; none dialed, the general voicemail
--                        local      a local caller ID for calls out (by area code); a call back to it rings the
--                                   manager who last called that number, else the attendant
--                      A number not listed (the one in TWILIO_CALLER_ID before this) rings as before.
--   users.phone_ext    a manager's extension (already on the user form)
--   users.voicemail_*  their voicemail greeting: an AI voice reading their words (or the usual ones), or a
--                      recording of their own (voicemail-greetings bucket, played to callers through a link
--                      that lasts minutes)
--   app_settings phone: attendant_greeting, general_voicemail_users (the people the general voicemail goes to)
--   phone_voicemail_notice_to(users, …)   a voicemail's notice to the people its box is for (none: the admins)
--   phone_voicemail_access                who may play a voicemail (its box's people); admins may play any
--
-- Safe to run more than once.

create table if not exists public.phone_lines (
  id            bigserial primary key,
  number        text not null unique check (number ~ '^\+1[2-9][0-9]{2}[2-9][0-9]{6}$'),
  kind          text not null check (kind in ('main', 'attendant', 'local')),
  label         text check (length(label) <= 80),
  ring_user_ids bigint[] not null default '{}',
  area_code     text generated always as (substr(number, 3, 3)) stored,
  created_at    timestamptz not null default now(),
  created_by    bigint references public.users(id) on delete set null
);
create index if not exists phone_lines_area on public.phone_lines (area_code) where kind = 'local';

alter table public.phone_lines enable row level security;
-- The staff who call read them (to pick a caller ID); administrators set them.
drop policy if exists phone_lines_read on public.phone_lines;
create policy phone_lines_read on public.phone_lines for select to authenticated using ((select public.is_staff()));
drop policy if exists phone_lines_write on public.phone_lines;
create policy phone_lines_write on public.phone_lines for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists mfa_required on public.phone_lines;
create policy mfa_required on public.phone_lines as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
drop policy if exists active_account_required on public.phone_lines;
create policy active_account_required on public.phone_lines as restrictive for all to authenticated
  using ((select public.app_user_id()) is not null) with check ((select public.app_user_id()) is not null);
revoke all on public.phone_lines from anon;
grant select, insert, update, delete on public.phone_lines to authenticated, service_role;
grant usage on sequence public.phone_lines_id_seq to authenticated, service_role;

alter table public.users add column if not exists voicemail_greeting text check (length(voicemail_greeting) <= 500);
alter table public.users add column if not exists voicemail_audio_path text;
alter table public.users add column if not exists voicemail_use_recording boolean not null default false;

-- A manager's own greeting, recorded in the browser (a WAV) or uploaded: read by the server alone.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('voicemail-greetings', 'voicemail-greetings', false, 5242880, array['audio/wav', 'audio/x-wav', 'audio/mpeg', 'audio/mp3'])
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

create table if not exists public.phone_voicemail_access (
  recording_sid text not null,
  user_id       bigint not null references public.users(id) on delete cascade,
  created_at    timestamptz not null default now(),
  primary key (recording_sid, user_id)
);
alter table public.phone_voicemail_access enable row level security;
revoke all on public.phone_voicemail_access from anon, authenticated;
grant select, insert, delete on public.phone_voicemail_access to service_role;

/**
 * A voicemail left in a box: a notice to its people (active ones), who may then play it; with nobody to tell
 * (none chosen, or none active), the administrators, as every voicemail went before.
 */
create or replace function public.phone_voicemail_notice_to(p_users bigint[], p_sid text, p_title text, p_body text, p_link text)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_to bigint[];
begin
  select array_agg(u.id) into v_to from public.users u
   where u.status = 'active' and u.deleted_at is null and u.id = any(coalesce(p_users, '{}'));
  if v_to is null then
    select array_agg(u.id) into v_to from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null;
  end if;
  if v_to is null then return 0; end if;
  insert into public.notifications (user_id, kind, title, body, link)
  select x, 'system', left(p_title, 200), left(p_body, 2000), p_link from unnest(v_to) x;
  if p_sid is not null then
    insert into public.phone_voicemail_access (recording_sid, user_id) select p_sid, x from unnest(v_to) x on conflict do nothing;
  end if;
  return cardinality(v_to);
end $$;
revoke execute on function public.phone_voicemail_notice_to(bigint[], text, text, text, text) from public, anon, authenticated;
grant execute on function public.phone_voicemail_notice_to(bigint[], text, text, text, text) to service_role;

-- ==============================================================================================================
-- 20270211100000_pipeline_unassigned.sql
-- ==============================================================================================================

-- The Pipeline Report counts the names no manager holds (Sean, Nov 2026: "the pipeline report section at the bottom
-- of the page stays blank for any months I filter", on BTC Ins Services_2026_Appts). It had a row for each project
-- and manager, and so left out every name with no manager: an imported list's names all, which the chart above it
-- counts. Those names are now a "No manager" row of their project, whose last appointment set, last call and
-- calls this month are anyone's on it, and which every manager on it shares.
--
-- Safe to run more than once.

create or replace function public.pipeline_report(
  p_months int[] default null, p_project_ids bigint[] default null, p_company_id bigint default null,
  p_type text default null, p_rep_id bigint default null, p_user_ids bigint[] default null)
returns table (project_id bigint, project text, project_type text, time_zone text, state text,
               manager_id bigint, manager_first text, manager_last text, last_appt_set date, last_worked timestamptz,
               calls bigint, months jsonb, total bigint, appts bigint, off_list bigint, viable_left bigint,
               pay numeric, special_pay numeric, sales_rep_first text, sales_rep_last text, shared_with jsonb, special_goal int)
language plpgsql stable security definer set search_path = public as $$
declare
  v_me     bigint := public.app_user_id();
  v_tz     text := public.business_tz();
  v_today  date := (now() at time zone public.business_tz())::date;
  v_months int[] := p_months;
  v_allowed bigint[];
begin
  if v_me is null or not public.is_staff() then
    raise exception 'The Pipeline Report is for staff' using errcode = '42501';
  end if;
  if v_months is null or cardinality(v_months) = 0 then
    v_months := array(select ((extract(month from v_today)::int - 1 + i) % 12) + 1 from generate_series(1, 3) i);
  end if;
  -- The projects this person may read: every one (an administrator), or those they are assigned to.
  if public.is_admin() then
    v_allowed := p_project_ids;
  else
    v_allowed := array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = v_me
                        and (p_project_ids is null or pa.project_id = any(p_project_ids)));
  end if;

  return query
  with names as (
    -- Every name renewing in the months, a manager's or nobody's (uid null).
    select x.project_id as pid, x.user_id as uid, x.month as m, x.bucket
      from public.xdate_names(v_allowed, p_company_id, p_type, p_rep_id, p_user_ids) x
     where x.month = any(v_months)
  ), per_month as (
    select n.pid, n.uid, n.m, count(*) as c from names n group by 1, 2, 3
  ), per_row as (
    select n.pid, n.uid, count(*) as total,
           count(*) filter (where n.bucket = 'appointment') as appts,
           count(*) filter (where n.bucket = 'off') as off_list,
           count(*) filter (where n.bucket = 'viable') as viable_left
      from names n group by 1, 2
  )
  select pr.id, pr.name, t.code,
         tz.name, coalesce(nullif(pr.state, ''), c.state),
         u.id, u.first_name, u.last_name,
         (select max((coalesce(a.appt_create_date, a.created_at) at time zone v_tz)::date) from public.appointments a
           where (r.uid is null or a.user_id = r.uid) and coalesce(a.set_project_id, a.project_id) = r.pid and a.deleted_at is null),
         (select max(cr.call_date) from public.call_records cr where (r.uid is null or cr.user_id = r.uid) and cr.project_id = r.pid),
         (select count(*) from public.call_records cr where (r.uid is null or cr.user_id = r.uid) and cr.project_id = r.pid
             and cr.call_date >= (date_trunc('month', v_today)::timestamp at time zone v_tz)),
         (select jsonb_object_agg(pm.m, pm.c) from per_month pm where pm.pid = r.pid and pm.uid is not distinct from r.uid),
         r.total, r.appts, r.off_list, r.viable_left,
         case when t.code = 'DBDV' then pr.lead_rate else pr.appointment_rate end,
         case when t.code = 'DBDV' then pr.special_rate else pr.confirmation_rate end,
         sr.first_name, sr.last_name,
         coalesce((select jsonb_agg(jsonb_build_object('first', o.first_name, 'last', o.last_name) order by o.first_name, o.last_name)
                     from public.project_assignments pa join public.users o on o.id = pa.ae_user_id
                    where pa.project_id = r.pid and pa.ae_user_id is distinct from r.uid and o.status = 'active' and o.deleted_at is null), '[]'::jsonb),
         case when t.code = 'DBDV' then pr.special_goal end
    from per_row r
    join public.projects pr on pr.id = r.pid
    left join public.users u on u.id = r.uid
    left join public.project_types t on t.id = pr.project_type_id
    left join public.companies c on c.id = pr.company_id
    left join public.timezones tz on tz.id = pr.timezone_id
    left join public.users sr on sr.id = c.sales_rep_id;
end $$;
revoke execute on function public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]) from public, anon;
grant execute on function public.pipeline_report(int[], bigint[], bigint, text, bigint, bigint[]) to authenticated;

-- ==============================================================================================================
-- 20270212100000_delivery_holds_stuck.sql
-- ==============================================================================================================

-- Held leads and appointments stuck in QA (Sean, Nov 2026: "this list of leads/appts are still sitting in QA from
-- 11/13 & 11/14"). A clearing claimed every held one at once ('sending') and then emailed them one by one; cut off
-- part way (the server's time limit on a long backlog), the rest stayed 'sending' for good: never sent by the
-- schedule, nor by Send, which take 'held' ones. Each is now claimed as it is sent, with the time (sending_at);
-- one 'sending' for more than ten minutes is held again, and the hourly clearing runs for those too.
--
-- Safe to run more than once.

alter table public.delivery_holds add column if not exists sending_at timestamptz;

-- The ones already stuck: back in the queue.
update public.delivery_holds set status = 'held' where status = 'sending';

create or replace function public.flush_held_deliveries()
returns void
language plpgsql security definer set search_path = public as $$
declare
  v_url text;
  v_secret text;
begin
  if not exists (select 1 from public.delivery_holds where status = 'held'
                    or (status = 'sending' and coalesce(sending_at, created_at) < now() - interval '10 minutes')) then
    return;
  end if;
  select decrypted_secret into v_url from vault.decrypted_secrets where name = 'push_deliver_url';
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'push_deliver_secret';
  if v_url is null or v_secret is null or v_url not like '%/api/push/deliver' then
    raise warning 'held deliveries: push_deliver_url / push_deliver_secret are not in the vault';
    return;
  end if;
  perform net.http_post(
    url := replace(v_url, '/api/push/deliver', '/api/delivery/flush'),
    body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-push-secret', v_secret),
    timeout_milliseconds := 60000
  );
exception when others then
  raise warning 'held deliveries: % (%)', sqlerrm, sqlstate;
end $$;
revoke execute on function public.flush_held_deliveries() from public, anon, authenticated;

-- ==============================================================================================================
-- 20270213100000_delete_client.sql
-- ==============================================================================================================

-- Deleting a client (Sean, Nov 2026: "How do I delete clients? I deleted projects, but don't see a way"): the
-- client's page has Delete now. It already took the client's projects, names and appointments with it; its own
-- people's logins now go too (disabled, so they can't sign in to an empty account), each back as it was when the
-- client is restored. Its deletion lists, goals and other settings stay with it, hidden, for a restore.
--
-- Safe to run more than once.

alter table public.users add column if not exists status_before_delete text;

CREATE OR REPLACE FUNCTION public.tg_soft_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me    bigint := public.app_user_id();
  v_now   timestamptz := now();
  v_via   text := tg_table_name || ':' || old.id;
  v_other text;
begin
  if old.deleted_at is not null then
    return null;
  end if;

  if tg_table_name = 'projects' then
    -- Leads promoted from a DB dev project would land on a project nobody can see.
    select p.name into v_other from public.projects p
     where p.appt_project_id = old.id and p.id <> old.id and p.deleted_at is null limit 1;
    if v_other is not null then
      raise exception '% promotes its leads to this project. Delete that project first, or have it promote to another.', v_other
        using errcode = '23503';
    end if;
    update public.appointments a set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where a.deleted_at is null
       and a.lead_id in (select l.id from public.leads l where l.project_id = old.id and l.deleted_at is null);
    update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where project_id = old.id and deleted_at is null;
    update public.projects set deleted_at = v_now, deleted_by = v_me, deleted_via = null where id = old.id;

  elsif tg_table_name = 'companies' then
    update public.appointments a set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where a.deleted_at is null
       and a.lead_id in (select l.id from public.leads l join public.projects p on p.id = l.project_id
                          where p.company_id = old.id and p.deleted_at is null and l.deleted_at is null);
    update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where deleted_at is null
       and project_id in (select p.id from public.projects p where p.company_id = old.id and p.deleted_at is null);
    update public.projects set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where company_id = old.id and deleted_at is null;
    -- Its own people's logins go with it, signed out of Lighthouse; restored with it, as they were (Nov 2026).
    update public.users set status_before_delete = status, status = 'disabled', deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where company_id = old.id and role = 'client' and deleted_at is null;
    update public.companies set deleted_at = v_now, deleted_by = v_me, deleted_via = null where id = old.id;

  elsif tg_table_name = 'leads' then
    update public.appointments set deleted_at = v_now, deleted_by = v_me, deleted_via = v_via
     where lead_id = old.id and deleted_at is null;
    update public.leads set deleted_at = v_now, deleted_by = v_me, deleted_via = null where id = old.id;

  elsif tg_table_name = 'users' then
    -- The account no longer counts as active anywhere; its sign-in is removed by the app.
    update public.users set deleted_at = v_now, deleted_by = v_me, deleted_via = null, status = 'disabled' where id = old.id;

  else
    execute format('update public.%I set deleted_at = $1, deleted_by = $2, deleted_via = null where id = $3', tg_table_name)
      using v_now, v_me, old.id;
  end if;

  -- The row stays.
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.restore_record(p_table text, p_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_via  text := p_table || ':' || p_id;
  v_n    integer;
  v_held text;
begin
  if not public.is_admin() then
    raise exception 'Only an administrator can restore a deleted record' using errcode = '42501';
  end if;
  if p_table not in ('companies', 'projects', 'leads', 'appointments', 'agencies', 'documents', 'bulletin_board', 'users') then
    raise exception 'Not a kind of record that can be restored' using errcode = '22023';
  end if;

  if p_table = 'projects' then
    select c.name into v_held from public.projects p join public.companies c on c.id = p.company_id
     where p.id = p_id and c.deleted_at is not null;
    if v_held is not null then
      raise exception 'Its client, %, is deleted. Restore the client first.', v_held using errcode = '23503';
    end if;
  elsif p_table = 'leads' then
    select p.name into v_held from public.leads l join public.projects p on p.id = l.project_id
     where l.id = p_id and p.deleted_at is not null;
    if v_held is not null then
      raise exception 'Its project, %, is deleted. Restore the project first.', v_held using errcode = '23503';
    end if;
  elsif p_table = 'appointments' then
    select l.company_name into v_held from public.appointments a join public.leads l on l.id = a.lead_id
     where a.id = p_id and l.deleted_at is not null;
    if v_held is not null then
      raise exception 'Its lead, %, is deleted. Restore the lead first.', v_held using errcode = '23503';
    end if;
  end if;

  -- Only what was deleted in its own right: what went with something comes back with that.
  execute format('update public.%I set deleted_at = null, deleted_by = null where id = $1 and deleted_at is not null and deleted_via is null', p_table)
    using p_id;
  get diagnostics v_n = row_count;
  if v_n = 0 then
    return false;
  end if;

  update public.projects set deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  update public.leads set deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  update public.appointments set deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  update public.users set status = coalesce(status_before_delete, status), status_before_delete = null,
         deleted_at = null, deleted_by = null, deleted_via = null where deleted_via = v_via;
  return true;
end $function$;

-- ==============================================================================================================
-- 20270214100000_producer_texts.sql
-- ==============================================================================================================

-- Texts to a client's producers (Sean, Nov 2026: "the option to receive text messages in addition to emails for new
-- appointments, appointment confirmations, & reschedules … a huge selling point for clients"). Project Info's
-- producers each have a mobile and a Texts tick now (in its producers jsonb: mobile, texts); as an appointment's
-- email goes to the client (held in QA with it), each producer ticked gets a short text from Lighthouse's number.
-- Each text is kept here, with how Twilio says it went (app/api/twilio/sms?step=status).
--
-- Safe to run more than once.

create table if not exists public.producer_texts (
  id             bigint generated always as identity primary key,
  lead_id        bigint references public.leads(id) on delete cascade,
  call_record_id bigint references public.call_records(id) on delete set null,
  project_id     bigint references public.projects(id) on delete set null,
  kind           text not null check (kind in ('new', 'confirmed', 'rescheduled')),
  to_number      text not null check (length(to_number) <= 20),
  to_name        text check (length(to_name) <= 90),
  body           text not null check (length(body) <= 1600),
  twilio_sid     text unique,
  status         text not null default 'queued' check (length(status) <= 20),
  error          text check (length(error) <= 500),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz
);
create index if not exists producer_texts_lead on public.producer_texts (lead_id, created_at desc);
-- One text per producer per call, however many times its delivery runs.
create unique index if not exists producer_texts_once on public.producer_texts (call_record_id, to_number) where call_record_id is not null;

alter table public.producer_texts enable row level security;
-- Administrators read them; the server writes them.
drop policy if exists producer_texts_read on public.producer_texts;
create policy producer_texts_read on public.producer_texts for select to authenticated using ((select public.is_admin()));
drop policy if exists mfa_required on public.producer_texts;
create policy mfa_required on public.producer_texts as restrictive for all to authenticated
  using ((select public.mfa_satisfied())) with check ((select public.mfa_satisfied()));
revoke all on public.producer_texts from anon, authenticated;
grant select on public.producer_texts to authenticated;
grant select, insert, update, delete on public.producer_texts to service_role;

-- ==============================================================================================================
-- 20270215100000_dashboard_speed.sql
-- ==============================================================================================================

-- A manager's dashboard, opened from Daily Production, slow to come up (client, Nov 2026). Daily Production and
-- the hours worked (work_minutes(), under work_days()) read the business's clock from a CTE, so the time window
-- was not one an index could use: every minute of work_activity ever kept, and every call, read to find the
-- day's. Each now works its window out first (plpgsql), and the date indexes these "everyone's day" questions
-- need are added. Same answers, same signatures.
--
-- Safe to run more than once.

create index if not exists work_activity_minute on public.work_activity (minute);
create index if not exists call_records_call_date on public.call_records (call_date);
create index if not exists pay_events_created_at on public.pay_events (created_at);

create or replace function public.work_minutes(p_from date, p_to date, p_user bigint default null)
returns table (user_id bigint, day date, hour integer, minutes integer)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_rules   jsonb   := public.pay_rules()->'time';
  v_tz      text    := public.business_tz();
  v_idle    int     := greatest(coalesce((v_rules->>'idle_minutes')::int, 5), 0);
  v_cap     int     := greatest(coalesce((v_rules->>'call_minutes')::int, 30), 0);
  v_t0      timestamptz := (p_from::timestamp at time zone v_tz);
  v_t1      timestamptz := ((p_to + 1)::timestamp at time zone v_tz);
  v_uid     bigint  := case when public.is_admin() then p_user else public.app_user_id() end;
  v_allowed boolean := public.is_admin() or public.app_user_id() is not null;
  v_from    timestamptz := v_t0 - make_interval(mins => v_idle);
  v_calls   timestamptz := v_t0 - make_interval(mins => v_cap);
begin
  if not v_allowed then return; end if;
  return query
  with marks as (
    select a.user_id as uid, a.minute as m
      from public.work_activity a
     where a.minute >= v_from and a.minute < v_t1
       and (v_uid is null or a.user_id = v_uid)
    union
    select c.user_id, date_trunc('minute', c.call_date)
      from public.call_records c
     where c.call_date >= v_from and c.call_date < v_t1
       and c.user_id is not null and (v_uid is null or c.user_id = v_uid)
    union
    select a.user_id, gs.m
      from public.work_activity a
      cross join lateral (
        select min(c.call_date) as ended
          from public.call_records c
         where c.user_id = a.user_id and c.lead_id = a.lead_id
           and c.call_date >= a.at and c.call_date <= a.at + make_interval(mins => v_cap)
      ) e
      cross join lateral generate_series(a.minute, date_trunc('minute', e.ended), interval '1 minute') as gs(m)
     where a.kind = 'call' and v_cap > 0 and e.ended is not null
       and a.minute >= v_calls and a.minute < v_t1
       and (v_uid is null or a.user_id = v_uid)
  ), ordered as (
    select d.uid, d.m, lag(d.m) over (partition by d.uid order by d.m) as prev
      from (select distinct mk.uid, mk.m from marks mk) d
  ), covered as (
    select o.uid, o.m from ordered o
    union
    select o.uid, gs.m
      from ordered o
      cross join lateral generate_series(o.prev + interval '1 minute', o.m - interval '1 minute', interval '1 minute') as gs(m)
     where o.prev is not null and o.m - o.prev <= make_interval(mins => v_idle)
  )
  select c.uid, (c.m at time zone v_tz)::date, extract(hour from c.m at time zone v_tz)::int, count(*)::int
    from covered c
   where c.m >= v_t0 and c.m < v_t1
   group by 1, 2, 3;
end $$;

create or replace function public.daily_production(p_day date default null)
returns table (user_id bigint, first_name text, last_name text, role text, started_at timestamptz, calls bigint, leads bigint,
               appointments bigint, worked_minutes integer, paid_minutes integer, leads_goal integer, appts_goal integer)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_tz  text := public.business_tz();
  v_day date := coalesce(p_day, (now() at time zone public.business_tz())::date);
  v_t0  timestamptz := (v_day::timestamp at time zone v_tz);
  v_t1  timestamptz := ((v_day + 1)::timestamp at time zone v_tz);
  v_admin boolean := public.is_admin();
  v_me  bigint := public.app_user_id();
begin
  return query
  with pr as (
    select p.user_id, sum(p.calls)::bigint as calls, sum(p.leads)::bigint as leads, sum(p.appointments)::bigint as appts
      from public.production_report(v_day, v_day) p
     group by 1
  ), wd as (
    select w.user_id, w.worked, w.paid from public.work_days(v_day, v_day) w
  ), st as (
    select a.user_id, min(a.minute) as started
      from public.work_activity a
     where a.minute >= v_t0 and a.minute < v_t1
     group by 1
  ), people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where u.status = 'active'
       and (v_admin or u.id = v_me)
       and (u.role = 'manager'
            or u.id in (select st.user_id from st) or u.id in (select pr.user_id from pr))
  )
  select p.id, p.first_name, p.last_name, p.role, st.started,
         coalesce(pr.calls, 0), coalesce(pr.leads, 0), coalesce(pr.appts, 0),
         coalesce(wd.worked, 0), coalesce(wd.paid, 0), g.leads_goal, g.appts_goal
    from people p
    left join pr on pr.user_id = p.id
    left join wd on wd.user_id = p.id
    left join st on st.user_id = p.id
    left join public.daily_goals g on g.user_id = p.id and g.day = v_day
   order by p.first_name, p.last_name, p.id;
end $$;

create or replace function public.production_days(p_from date, p_to date)
returns table (user_id bigint, first_name text, last_name text, role text, day date, started_at timestamptz, calls bigint,
               leads bigint, appointments bigint, worked_minutes integer, paid_minutes integer, leads_goal integer, appts_goal integer)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_tz  text := public.business_tz();
  v_t0  timestamptz := (p_from::timestamp at time zone v_tz);
  v_t1  timestamptz := ((p_to + 1)::timestamp at time zone v_tz);
  v_admin boolean := public.is_admin();
  v_me  bigint := public.app_user_id();
begin
  return query
  with pr as (
    select p.user_id, p.day, sum(p.calls)::bigint as calls, sum(p.leads)::bigint as leads, sum(p.appointments)::bigint as appts
      from public.production_report(p_from, p_to) p
     group by 1, 2
  ), wd as (
    select w.user_id, w.day, w.worked, w.paid from public.work_days(p_from, p_to) w
  ), st as (
    select a.user_id, (a.minute at time zone v_tz)::date as day, min(a.minute) as started
      from public.work_activity a
     where a.minute >= v_t0 and a.minute < v_t1
     group by 1, 2
  ), g as (
    select g.user_id, g.day, g.leads_goal, g.appts_goal
      from public.daily_goals g
     where g.day between p_from and p_to
  ), days as (
    select pr.user_id, pr.day from pr
    union select wd.user_id, wd.day from wd
    union select st.user_id, st.day from st
    union select g.user_id, g.day from g
  ), people as (
    select u.id, u.first_name, u.last_name, u.role
      from public.users u
     where u.status = 'active'
       and (v_admin or u.id = v_me)
       and (u.role = 'manager' or u.id in (select days.user_id from days))
  )
  select p.id, p.first_name, p.last_name, p.role, x.day, st.started,
         coalesce(pr.calls, 0), coalesce(pr.leads, 0), coalesce(pr.appts, 0),
         coalesce(wd.worked, 0), coalesce(wd.paid, 0), g.leads_goal, g.appts_goal
    from people p
    left join days x on x.user_id = p.id
    left join pr on pr.user_id = p.id and pr.day = x.day
    left join wd on wd.user_id = p.id and wd.day = x.day
    left join st on st.user_id = p.id and st.day = x.day
    left join g  on g.user_id  = p.id and g.day  = x.day
   order by p.first_name, p.last_name, p.id, x.day;
end $$;

revoke execute on function public.work_minutes(date, date, bigint) from public, anon;
grant execute on function public.work_minutes(date, date, bigint) to authenticated;
revoke execute on function public.daily_production(date) from public, anon;
grant execute on function public.daily_production(date) to authenticated;
revoke execute on function public.production_days(date, date) from public, anon;
grant execute on function public.production_days(date, date) to authenticated;

-- ==============================================================================================================
-- 20270216100000_call_log.sql
-- ==============================================================================================================

-- Call Log (Sean, Nov 2026): "drill down by manager to show all of their outbound & inbound calls for the
-- selected date/range … a full listing of all the calls", and "look up a phone # that called in or was
-- dialed out … a prospect can call in from their cell and it's not noted in the database on a lead".
--
--   phone_call_log()   the calls Call Activity counts (phone_call_report()), one row each, newest first:
--                      by person, by kind, by number (any part of it, three digits or more), over days or
--                      all time; with the lead it is on (or, where it is on none, a lead with that number),
--                      and its recording for whoever may play it. Each kind's count over the filters.
--
-- Administrators see everyone's; an account manager their own. Safe to run more than once.

create index if not exists phone_recordings_call_idx on public.phone_recordings (call_sid);
create index if not exists phone_calls_number_trgm on public.phone_calls using gin (number extensions.gin_trgm_ops);

drop function if exists public.phone_call_log(date, date, bigint, text, text, integer, integer);

/**
 * p_from, p_to  the business's days (either null: no bound)
 * p_user        whose calls: null everyone's; 0 the calls in that rang no one (a manager: always their own)
 * p_kind        null all; 'out' or 'in'; or one of Call Activity's: out_handled, out_cancelled, in_handled, missed
 * p_number      digits of the number called or calling, in any form (fewer than three: not a filter)
 * Each row carries the counts of every kind over the same filters (n_*), and n_all; `total` the rows p_kind leaves.
 */
create function public.phone_call_log(
  p_from date default null, p_to date default null, p_user bigint default null, p_kind text default null,
  p_number text default null, p_limit integer default 100, p_offset integer default 0
)
returns table (
  call_sid text, user_id bigint, first_name text, last_name text, direction text, kind text, number text,
  started_at timestamptz, answered_at timestamptz, ended_at timestamptz, talk_seconds integer,
  lead_id bigint, lead_company text, lead_by_number boolean, recording_sid text, recording_seconds integer,
  total bigint, n_all bigint, n_out_handled bigint, n_out_cancelled bigint, n_in_handled bigint, n_missed bigint
)
language plpgsql stable security definer set search_path = public as $$
#variable_conflict use_column
declare
  v_tz     text    := public.business_tz();
  v_admin  boolean := public.is_admin();
  v_me     bigint  := public.app_user_id();
  v_user   bigint  := p_user;
  v_t0     timestamptz := case when p_from is not null then p_from::timestamp at time zone public.business_tz() end;
  v_t1     timestamptz := case when p_to is not null then (p_to + 1)::timestamp at time zone public.business_tz() end;
  v_digits text    := regexp_replace(coalesce(p_number, ''), '\D', '', 'g');
  v_kind   text    := nullif(p_kind, '');
begin
  if not (public.is_manager() and public.mfa_satisfied()) then
    raise exception 'Only administrators and account managers see the call log' using errcode = '42501';
  end if;
  if not v_admin then v_user := v_me; end if;
  if length(v_digits) = 11 and v_digits like '1%' then v_digits := substr(v_digits, 2); end if;
  if length(v_digits) < 3 then v_digits := null; end if;
  if v_kind is not null and v_kind not in ('out', 'in', 'out_handled', 'out_cancelled', 'in_handled', 'missed') then v_kind := null; end if;

  return query
  with c as (
    select pc.*,
           case
             when pc.direction = 'out' then
               case when pc.answered_at is not null then 'out_handled' when pc.ended_at is not null then 'out_cancelled' end
             when pc.user_id is null then
               case when pc.call_sid = pc.parent_sid and pc.ended_at is not null
                     and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.call_sid and s.call_sid <> pc.call_sid and s.rang_at is not null)
                 then 'missed' end
             when pc.answered_at is not null then 'in_handled'
             when pc.ended_at is not null and pc.rang_at is not null
                  and not exists (select 1 from public.phone_calls s where s.parent_sid = pc.parent_sid and s.answered_at is not null)
               then 'missed'
           end as k
      from public.phone_calls pc
     where (v_t0 is null or pc.started_at >= v_t0)
       and (v_t1 is null or pc.started_at < v_t1)
       and (v_digits is null or pc.number like '%' || v_digits || '%')
       and case when v_user is null then true when v_user = 0 then pc.user_id is null and pc.call_sid = pc.parent_sid else pc.user_id = v_user end
  ), counted as (
    select c.*,
           count(*) over () as n_all,
           count(*) filter (where c.k = 'out_handled') over () as n_oh,
           count(*) filter (where c.k = 'out_cancelled') over () as n_oc,
           count(*) filter (where c.k = 'in_handled') over () as n_ih,
           count(*) filter (where c.k = 'missed') over () as n_m
      from c
     where c.k is not null
  ), picked as (
    select x.*, count(*) over () as total
      from counted x
     where v_kind is null or x.k = v_kind or (v_kind = 'out' and x.direction = 'out') or (v_kind = 'in' and x.direction = 'in')
     order by x.started_at desc, x.id desc
     limit greatest(least(coalesce(p_limit, 100), 500), 1) offset greatest(coalesce(p_offset, 0), 0)
  )
  select p.call_sid, p.user_id, u.first_name, u.last_name, p.direction, p.k, p.number,
         p.started_at, p.answered_at, p.ended_at, p.talk_seconds,
         coalesce(p.lead_id, m.id), coalesce(l.company_name, m.company_name), p.lead_id is null and m.id is not null,
         case when v_admin or r.user_id = v_me then r.recording_sid end, r.seconds,
         p.total, p.n_all, p.n_oh, p.n_oc, p.n_ih, p.n_m
    from picked p
    left join public.users u on u.id = p.user_id
    left join public.leads l on l.id = p.lead_id
    -- On no lead: one with that number, so a call from a number not yet tied to it can be traced.
    left join lateral (
      select ld.id, ld.company_name from public.leads ld
       where p.lead_id is null and ld.deleted_at is null
         and length(regexp_replace(coalesce(p.number, ''), '\D', '', 'g')) >= 10
         and ld.search_text ilike '%' || right(regexp_replace(p.number, '\D', '', 'g'), 10) || '%'
       order by ld.updated_at desc nulls last
       limit 1
    ) m on true
    -- A call out's recording is on the phone's own leg (its parent); a call taken, on the leg that took it.
    left join lateral (
      select rr.recording_sid, rr.seconds, rr.user_id from public.phone_recordings rr
       where rr.call_sid = case when p.direction = 'out' then p.parent_sid else p.call_sid end
       order by rr.created_at
       limit 1
    ) r on true
   order by p.started_at desc, p.id desc;
end $$;

revoke execute on function public.phone_call_log(date, date, bigint, text, text, integer, integer) from public, anon;
grant execute on function public.phone_call_log(date, date, bigint, text, text, integer, integer) to authenticated;

-- ==============================================================================================================
-- 20270217100000_pay_speed.sql
-- ==============================================================================================================

-- Pay & Hours over a long range ("This year") ran until the page gave up (client, Nov 2026). The bonuses
-- (pay_bonuses(), under pay_report()) worked out each day's pay period twice, for every day of the range, and,
-- for every period in it and every lead manager, every day of the 180 before it again, with each earlier
-- half's units counted twice: tens of thousands of lookups for a year. The periods are now walked once
-- (pay_periods_in()), and a period is looked into for a units bonus taken back only when that manager had
-- a lead, appointment or dec sheet taken back during it (nothing else can lower an earlier half: a new one
-- counts on its own day). Same answers, same signature.
--
-- Safe to run more than once.

/** The pay periods touching the business's days p_from..p_to, in order: each looked up once, not each day. */
create or replace function public.pay_periods_in(p_from date, p_to date)
returns table (s date, e date)
language plpgsql stable set search_path = public as $$
declare
  d     date := p_from;
  per   record;
  last_ date;
begin
  while d <= p_to loop
    select * into per from public.pay_period_of(d);
    if last_ is distinct from per.starts_on then
      s := per.starts_on; e := per.ends_on;
      return next;
      last_ := per.starts_on;
    end if;
    -- The day after the period (a custom schedule with a gap: the next day).
    d := greatest(per.ends_on, d) + 1;
  end loop;
end $$;
revoke execute on function public.pay_periods_in(date, date) from public, anon;
grant execute on function public.pay_periods_in(date, date) to authenticated;

do $$ begin
  create type public.pay_period_span as (s date, e date);
exception when duplicate_object then null; end $$;

/**
 * The bonuses paid in the pay periods that end on p_from..p_to, one row each: whose, which plan, the
 * days counted, how many, the amount, and the pay period it is paid in.
 *   lead          each half of a period: units, paid that period (as they stood at its end)
 *   lead_adjust   an earlier half's units bonus taken back (a minus amount) on the period that found the
 *                 leads invalid that took it under its tier
 *   appt_weekly   each half of a period: valid appointments set, on the scale, paid the period after
 *   appt_monthly  a month's valid appointments set, a tier paid in the period its last appointment's
 *                 date passes (the month over by then)
 */
create or replace function public.pay_bonuses(p_from date, p_to date, p_user bigint default null)
returns table (user_id bigint, plan text, label text, from_day date, to_day date, counted numeric, amount numeric, paid_from date, paid_to date)
language plpgsql stable set search_path = public as $$
#variable_conflict use_column
declare
  v_rules  jsonb := public.bonus_rules();
  v_first  int   := greatest(coalesce((v_rules->>'first_days')::int, 5), 1);
  v_tz     text  := public.business_tz();
  v_today  date  := (now() at time zone public.business_tz())::date;
  per      record;
  nxt      record;
  q        record;
  u        record;
  h        record;
  m        date;
  t        record;
  v_n      numeric;
  v_amt    numeric;
  v_was    numeric;
  v_prev   numeric;
  v_at     date;
  v_paid   record;
  v_end    timestamptz;
  v_back   public.pay_period_span[];
  v_q0     timestamptz;
  v_q1     timestamptz;
begin
  for per in select pp.s, pp.e from public.pay_periods_in(p_from - 70, p_to) pp loop
    -- As things stood when the period closed (or now, while it is open).
    v_end := least(now(), (per.e + 1)::timestamp at time zone v_tz);
    for h in
      select per.s as hs, least(per.s + v_first - 1, per.e) as he, 1 as half
      union all
      select per.s + v_first, per.e, 2 where per.s + v_first <= per.e
    loop
      -- A lead manager's units, paid the same period.
      if per.e between p_from and p_to then
        for u in select pp.user_id as uid from public.pay_profiles pp
                  where pp.bonus_plan = 'lead' and (p_user is null or pp.user_id = p_user) loop
          v_n := public.bonus_units(u.uid, h.hs, h.he, v_end);
          if public.bonus_tier(v_rules->'lead_weekly', v_n) > 0 then
            user_id := u.uid; plan := 'lead'; label := 'Units'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := public.bonus_tier(v_rules->'lead_weekly', v_n); paid_from := per.s; paid_to := per.e;
            return next;
          end if;
        end loop;
      end if;
      -- An appointment manager's half, on the scale, paid the period after.
      select * into nxt from public.pay_period_of(per.e + 1);
      if nxt.ends_on between p_from and p_to then
        for u in select pp.user_id as uid from public.pay_profiles pp
                  where pp.bonus_plan = 'appointment' and (p_user is null or pp.user_id = p_user) loop
          v_n := public.bonus_appointments(u.uid, h.hs, h.he);
          v_amt := public.bonus_scale(v_rules->'appt_weekly_scale', v_n);
          if v_amt > 0 then
            user_id := u.uid; plan := 'appt_weekly'; label := 'Valid appointments'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := v_amt; paid_from := nxt.starts_on; paid_to := nxt.ends_on;
            return next;
          end if;
        end loop;
      end if;
    end loop;
  end loop;

  -- An earlier half's units bonus taken back: leads found invalid during period q, from a half paid before it.
  -- The periods worked out once (not a lookup a day for every period), and a period q looked into only for
  -- a manager with a lead, appointment or dec sheet taken back during it: nothing else lowers an earlier half.
  v_back := array(select row(pp.s, pp.e)::public.pay_period_span from public.pay_periods_in(p_from - 31 - 180 - 62, p_to) pp);
  for q in select pp.s, pp.e from public.pay_periods_in(p_from - 31, p_to) pp loop
    continue when q.e < p_from or q.e > p_to or q.s > v_today;
    v_q0 := q.s::timestamp at time zone v_tz;
    v_q1 := least(now(), (q.e + 1)::timestamp at time zone v_tz);
    for u in select pp.user_id as uid from public.pay_profiles pp
              where pp.bonus_plan = 'lead' and (p_user is null or pp.user_id = p_user)
                and exists (select 1 from public.pay_events pe
                             where pe.user_id = pp.user_id and pe.kind in ('lead', 'appointment', 'dec_sheet')
                               and (pe.is_chargeback or pe.reverses_id is not null)
                               and pe.created_at > v_q0 and pe.created_at <= v_q1) loop
      for per in
        select b.s, b.e from unnest(v_back) b where b.e < q.s and b.e >= q.s - 180 order by b.s
      loop
        for h in
          select per.s as hs, least(per.s + v_first - 1, per.e) as he
          union all
          select per.s + v_first, per.e where per.s + v_first <= per.e
        loop
          v_was := public.bonus_tier(v_rules->'lead_weekly', public.bonus_units(u.uid, h.hs, h.he, q.s::timestamp at time zone v_tz));
          continue when v_was = 0;
          v_n := public.bonus_units(u.uid, h.hs, h.he, least(now(), (q.e + 1)::timestamp at time zone v_tz));
          v_amt := public.bonus_tier(v_rules->'lead_weekly', v_n);
          if v_amt < v_was then
            user_id := u.uid; plan := 'lead_adjust'; label := 'Units bonus taken back'; from_day := h.hs; to_day := h.he;
            counted := v_n; amount := v_amt - v_was; paid_from := q.s; paid_to := q.e;
            return next;
          end if;
        end loop;
      end loop;
    end loop;
  end loop;

  -- An appointment manager's month: each tier paid in the period its last appointment's date passes.
  for m in select generate_series(date_trunc('month', p_from - 150)::date, date_trunc('month', p_to)::date, interval '1 month')::date loop
    for u in select pp.user_id as uid from public.pay_profiles pp
              where pp.bonus_plan = 'appointment' and (p_user is null or pp.user_id = p_user) loop
      v_n := public.bonus_appointments(u.uid, m, (m + interval '1 month')::date - 1);
      v_prev := 0;
      for t in select (x->>'at')::int as at_n, (x->>'amount')::numeric as amt
                 from jsonb_array_elements(v_rules->'appt_monthly') x order by 1 loop
        exit when v_n < t.at_n;
        -- The date the tier is reached: the month over, and the t.at_n-th appointment's date passed.
        select greatest((m + interval '1 month')::date,
                        coalesce(a.appt_date, (a.created_at at time zone public.business_tz())::date) + 1) into v_at
          from public.appointments a
         where a.user_id = u.uid and a.deleted_at is null and a.invalid_at is null and a.qa_status is distinct from 'failed'
           and a.created_at >= (m::timestamp at time zone public.business_tz())
           and a.created_at <  (((m + interval '1 month')::date)::timestamp at time zone public.business_tz())
         order by coalesce(a.appt_date, (a.created_at at time zone public.business_tz())::date), a.id
         offset t.at_n - 1 limit 1;
        if v_at is not null and v_at <= v_today then
          select * into v_paid from public.pay_period_of(v_at);
          if v_paid.ends_on between p_from and p_to then
            user_id := u.uid; plan := 'appt_monthly'; label := to_char(m, 'FMMonth') || ' valid appointments';
            from_day := m; to_day := (m + interval '1 month')::date - 1; counted := t.at_n;
            amount := case when coalesce((v_rules->>'monthly_total')::boolean, true) then t.amt - v_prev else t.amt end;
            paid_from := v_paid.starts_on; paid_to := v_paid.ends_on;
            if amount > 0 then return next; end if;
          end if;
        end if;
        v_prev := t.amt;
      end loop;
    end loop;
  end loop;
end $$;
revoke execute on function public.pay_bonuses(date, date, bigint) from public, anon;
grant execute on function public.pay_bonuses(date, date, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270218100000_appointment_rescheduled.sql
-- ==============================================================================================================

-- =============================================================================
-- Appointment-Rescheduled (Sean, Nov 2026): "something I never covered for when they have to reschedule an
-- appointment that was already set (either after they received negative pay for it being invalid or when they
-- call to confirm an appt and the prospect needs to reschedule to a different date/time)."
--
-- A follow-up on the name's appointment, beside Appointment-Confirmed and Appointment-Invalid:
--   * the same appointment moves to its new day and time (status Rescheduled), to be confirmed again;
--   * one marked invalid is an appointment again: its pay back to whoever set it, as a new appointment,
--     with the confirmation pay still to come; one already confirmed has its confirmation pay taken back
--     until it is confirmed again (never paid twice);
--   * the client is told: the lead sheet emailed as "Appointment - <company> (RESCHEDULED)" with the new
--     day's calendar links (the app sends it), the producers texted, and a notification in Lighthouse;
--   * counted against whoever set it (appointments.rescheduled_count; rescheduled_appointments()), the trend
--     of how many of a manager's appointments need setting again, on Daily Production.
--
-- Safe to run more than once.
-- =============================================================================

alter table public.call_results drop constraint if exists call_results_effect_check;
alter table public.call_results add constraint call_results_effect_check
  check (effect in ('none', 'promote', 'appointment', 'confirm', 'reschedule',
                    'appointment_invalid', 'lead_invalid', 'correct_xdate', 'pending'));

alter table public.appointments add column if not exists rescheduled_at timestamptz;
alter table public.appointments add column if not exists rescheduled_count integer not null default 0;
comment on column public.appointments.rescheduled_count is 'Times set again on another day with Appointment-Rescheduled';

-- Right after Appointment-Confirmed, as the client's sheet lists them. It sends the client the lead sheet.
insert into public.call_results
  (project_type, name, sort_order, viable, callable, sort_last, effect, pay_kind, applies_to, status_code, action, aliases, delivers)
values
  ('DBDV', 'Appointment-Rescheduled', 85, false, true, false, 'reschedule', null, 'appointment', null,
   'Appointment moved to its new date/time on the client calendar, notification sent to Client marked Rescheduled, to be confirmed again; an invalid appointment set again has its Appt pay added back (Confirmation pay pending), and is tracked as a reschedule for the Account Mgr who set it',
   array['rescheduled', 'appointment rescheduled', 'reschedule'], false),
  ('APPT', 'Appointment-Rescheduled', 65, false, true, false, 'reschedule', null, 'appointment', null,
   'Appointment moved to its new date/time on the client calendar, notification sent to Client marked Rescheduled, to be confirmed again; an invalid appointment set again has its Appt pay added back (Confirmation pay pending), and is tracked as a reschedule for the Account Mgr who set it',
   array['rescheduled', 'appointment rescheduled', 'reschedule'], false)
on conflict (project_type, name) do update set
  sort_order = excluded.sort_order, viable = excluded.viable, callable = excluded.callable, sort_last = excluded.sort_last,
  effect = excluded.effect, pay_kind = excluded.pay_kind, applies_to = excluded.applies_to,
  status_code = excluded.status_code, action = excluded.action, aliases = excluded.aliases;

/**
 * How many of each person's appointments were set again on another day (Appointment-Rescheduled) on the
 * business's days p_from..p_to, by whoever set them. An administrator sees everyone's; anyone else their own.
 */
create or replace function public.rescheduled_appointments(p_from date, p_to date)
returns table (user_id bigint, rescheduled bigint)
language plpgsql stable security definer set search_path = public as $$
declare
  v_tz   text   := public.business_tz();
  v_user bigint := case when public.is_admin() then null else public.app_user_id() end;
begin
  if not public.is_admin() and v_user is null then return; end if;
  return query
  select ap.user_id, count(*)
    from public.call_records c
    join public.call_results r on r.id = c.result_id and r.effect = 'reschedule'
    join public.appointments ap on ap.id = c.appointment_id
   where c.call_date >= (p_from::timestamp at time zone v_tz)
     and c.call_date <  ((p_to + 1)::timestamp at time zone v_tz)
     and ap.user_id is not null
     and (v_user is null or ap.user_id = v_user)
   group by ap.user_id;
end $$;
revoke execute on function public.rescheduled_appointments(date, date) from public, anon;
grant execute on function public.rescheduled_appointments(date, date) to authenticated;

create or replace function public.record_call_result(p_lead_id bigint, p_result_id bigint, p_notes text DEFAULT NULL::text, p_appointment jsonb DEFAULT NULL::jsonb, p_corrected_xdate date DEFAULT NULL::date, p_ultimate_xdate date DEFAULT NULL::date, p_client_note text DEFAULT NULL::text, p_lead_manager bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_me       bigint := public.app_user_id();
  v_role     text   := public.app_role();
  v_notes    text   := nullif(btrim(coalesce(p_notes, '')), '');
  l          public.leads;
  r          public.call_results;
  a_r        public.call_results;      -- the appointment-stage twin of a DBDev result
  p          public.projects;          -- the project the call is made on
  v_type     text;
  v_appt     public.appointments;
  v_open     public.appointments;      -- an appointment the name already holds, which this one moves
  v_call     bigint;
  v_status   bigint;
  v_rep      bigint;
  v_old_xdate date;
  v_pay      jsonb := '[]'::jsonb;
  v_date     date;
  v_time     text;
  v_dev      bigint;                   -- Lead-Corrected: the lead manager who developed it
  v_back     jsonb;
  v_amt      numeric(10,2);
  v_was      public.appointments;      -- Appointment-Rescheduled: the appointment as it stood
  v_set      public.call_results;      -- …and the result it was set with (Appointment, Appointment-Phone)
begin
  if v_me is null or v_role not in ('admin', 'manager', 'agent') then
    raise exception 'Only staff can record call results' using errcode = '42501';
  end if;
  if length(coalesce(v_notes, '')) > 1000 then
    raise exception 'Keep call notes under 1,000 characters' using errcode = '22023';
  end if;
  if length(coalesce(p_client_note, '')) > 2000 then
    raise exception 'Keep the note for the client under 2,000 characters' using errcode = '22023';
  end if;

  select * into l from public.leads where id = p_lead_id for update;
  if not found then
    raise exception 'That lead no longer exists' using errcode = 'P0002';
  end if;
  select * into r from public.call_results where id = p_result_id;
  if not found then
    raise exception 'Unknown call result' using errcode = '22023';
  end if;
  if r.applies_to = 'report' then
    raise exception '% is recorded automatically, not from a call', r.name using errcode = '22023';
  end if;

  select * into p from public.projects where id = l.project_id;
  if not found then
    raise exception 'This name is not in a project yet' using errcode = '22023';
  end if;
  v_type := public.project_type_code(p.id);

  -- An appointment follow-up acts on the name's open appointment, recorded
  -- against the stage that appointment was set at so each project counts it.
  if r.applies_to = 'appointment' then
    if r.effect = 'reschedule' then
      -- Appointment-Rescheduled (Sean, Nov 2026): the name's latest appointment, one marked invalid too
      -- (set again on another day), never one that failed QA.
      select * into v_appt from public.appointments
       where lead_id = l.id and deleted_at is null and qa_status is distinct from 'failed'
       order by appt_create_date desc, id desc
       limit 1
       for update;
    else
      select * into v_appt from public.appointments
       where lead_id = l.id and invalid_at is null
       order by appt_create_date desc, id desc
       limit 1
       for update;
    end if;
    if not found then
      raise exception 'This name has no appointment to %', case r.effect when 'confirm' then 'confirm' when 'reschedule' then 'reschedule' else 'mark invalid' end
        using errcode = '22023';
    end if;
    if r.effect = 'confirm' and v_appt.confirmed_at is not null then
      raise exception 'This appointment is already confirmed' using errcode = '22023';
    end if;
    select * into r from public.call_results
     where name = r.name and project_type = case coalesce(v_appt.set_stage, l.stage) when 'dbdev' then 'DBDV' else 'APPT' end;
  elsif r.project_type <> v_type then
    raise exception '% is not a result for % projects', r.name,
      case v_type when 'DBDV' then 'database-development' else 'appointment' end using errcode = '22023';
  end if;

  if v_role <> 'admin'
     and l.assigned_user_id is distinct from v_me
     and not exists (select 1 from public.project_assignments pa where pa.project_id = l.project_id and pa.ae_user_id = v_me)
     and not (r.applies_to = 'appointment' and coalesce(v_appt.follow_up_user_id, v_appt.user_id) = v_me) then
    raise exception 'This name is not on your call list' using errcode = '42501';
  end if;

  -- The call itself.
  insert into public.call_records (lead_id, project_id, user_id, call_result, notes, result_id, stage, call_date)
  values (l.id, l.project_id, v_me, r.name, v_notes, r.id, l.stage, now())
  returning id into v_call;

  select id into v_status from public.lead_statuses where code = r.status_code;

  update public.leads set
    result_id        = r.id,
    call_result_dbdv = case when r.project_type = 'DBDV' then r.name else call_result_dbdv end,
    call_result_appt = case when r.project_type = 'APPT' then r.name
                            when r.effect = 'appointment_invalid' and stage = 'appt' then r.name
                            else call_result_appt end,
    call_weight      = call_weight + case when r.applies_to = 'name' then 1 else 0 end,
    date_last_worked = now(),
    status_id        = coalesce(v_status, status_id),
    resolved_at      = case when r.viable then null else coalesce(resolved_at, now()) end,
    assigned_user_id = case when r.effect = 'pending' then null else assigned_user_id end
  where id = l.id;

  -- What the result does.
  if r.effect in ('promote', 'appointment') then
    -- A name becomes a Lead or an Appointment only with its renewal date
    -- confirmed: the Ultimate X-Date, entered (or corrected) with this result,
    -- or already on the record. A date on a policy line alone is a potential
    -- renewal the account manager has not confirmed yet.
    if p_ultimate_xdate is not null then
      update public.insurance_details set ultimate_xdate = p_ultimate_xdate where lead_id = l.id;
      if not found then
        insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_ultimate_xdate);
      end if;
    end if;
    if not exists (select 1 from public.insurance_details i where i.lead_id = l.id and i.ultimate_xdate is not null) then
      raise exception 'Enter the Ultimate X-Date: a name becomes a Lead or an Appointment only with its renewal date'
        using errcode = '22023';
    end if;

    -- What the client is told, with the lead sheet: written as the name is
    -- set (given empty, it is cleared). The call notes stay internal.
    if p_client_note is not null then
      update public.leads set client_note = nullif(btrim(p_client_note), '') where id = l.id;
    end if;

    if r.effect = 'appointment' then
      v_date := nullif(p_appointment->>'date', '')::date;
      v_time := nullif(btrim(coalesce(p_appointment->>'time', '')), '');
      if v_date is null then
        raise exception 'Choose the appointment date' using errcode = '22023';
      end if;
      if v_date < current_date - 1 then
        raise exception 'The appointment date has passed' using errcode = '22023';
      end if;
      if v_time is null then
        raise exception 'Choose the appointment time' using errcode = '22023';
      end if;
      if v_time !~* '^\d{1,2}:\d{2}\s?(AM|PM)$' then
        raise exception 'Give the time like 9:30 AM' using errcode = '22023';
      end if;
    end if;

    -- A name that already holds an appointment still to come, or still
    -- waiting for QA, has that one moved: one appointment, paid once.
    -- (Recording the result again is how a rep reschedules from the sheet.)
    -- One that failed QA does not count: the rep sets a real one instead.
    if r.effect = 'appointment' then
      select * into v_open from public.appointments
       where lead_id = l.id and invalid_at is null and qa_status is distinct from 'failed'
         and (qa_status = 'pending' or appt_date >= (now() at time zone public.business_tz())::date)
       order by appt_create_date desc, id desc
       limit 1
       for update;
    end if;

    if v_open.id is not null then
      update public.appointments set
        appt_date    = v_date,
        appt_time    = v_time,
        duration_min = coalesce(nullif(p_appointment->>'duration', '')::int, duration_min),
        rep_name     = coalesce(nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), rep_name),
        status_id    = case when status_id = (select id from public.appointment_statuses where name = 'Scheduled')
                             and (appt_date, coalesce(appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                            then (select id from public.appointment_statuses where name = 'Rescheduled')
                            else status_id end,
        status_update_date = now()
      where id = v_open.id
      returning * into v_appt;
      -- "Moved" only when the day or the time changed.
      update public.call_records set
        appointment_id = v_appt.id,
        notes = case when (v_open.appt_date, coalesce(v_open.appt_time, '')) is distinct from (v_date, coalesce(v_time, ''))
                     then concat_ws(E'\n', notes, 'Appointment moved from ' || to_char(v_open.appt_date, 'Mon FMDD')
                            || coalesce(' ' || v_open.appt_time, '') || ' to ' || to_char(v_date, 'Mon FMDD') || coalesce(' ' || v_time, ''))
                     else notes end
      where id = v_call;
    else

      -- From DBDev, the name moves to the linked appointment project.
      if v_type = 'DBDV' then
        if p.appt_project_id is null then
          raise exception 'Link % to an appointment project before promoting its names', p.name using errcode = '22023';
        end if;
        select * into a_r from public.call_results
         where project_type = 'APPT' and name = case r.effect when 'promote' then 'Lead-No Contact' else r.name end;
        -- A new lead goes to the appointment manager with the fewest names; an
        -- appointment stays with the rep who set it, who confirms it.
        v_rep := case r.effect when 'promote' then public.least_loaded_rep(p.appt_project_id) else v_me end;
        update public.leads set
          stage             = 'appt',
          project_id        = p.appt_project_id,
          source_project_id = coalesce(source_project_id, l.project_id),
          dbdv_user_id      = v_me,
          assigned_user_id  = v_rep,
          result_id         = a_r.id,
          call_result_appt  = a_r.name,
          call_weight       = 0,
          promoted_at       = now(),
          resolved_at       = case when a_r.viable then null else now() end
        where id = l.id;
        -- Nobody is on the appointment project to take a new lead: the administrators
        -- hear of it, so a hot lead never waits unseen (Sean, Oct 2026).
        if r.effect = 'promote' and v_rep is null then
          perform public.notify_users(
            array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null),
            'lead',
            left(case when r.status_code = 'hot' then 'Hot lead waiting: ' else 'Lead waiting: ' end || coalesce(l.company_name, 'a lead'), 160),
            'Nobody is assigned to ' || coalesce((select pp.name from public.projects pp where pp.id = p.appt_project_id), 'its appointment project')
              || ' to take it. Add an appointment manager to that project, or send the lead to one.',
            '/leads/' || l.id,
            case when r.status_code = 'hot' then 'hot_lead' else 'lead_assigned' end);
        end if;
      end if;

      if r.effect = 'appointment' then
        insert into public.appointments
          (lead_id, user_id, rep_name, appt_date, appt_time, duration_min, status_id, list_source,
           call_result_dbdv, project_id, set_project_id, set_stage, call_record_id, qa_status)
        values
          (l.id, v_me, nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), v_date, v_time,
           coalesce(nullif(p_appointment->>'duration', '')::int, 30),
           (select id from public.appointment_statuses where name = 'Scheduled'),
           l.list_source,
           case when v_type = 'DBDV' then r.name end,
           coalesce(p.appt_project_id, p.id), p.id, l.stage, v_call, 'pending')
        returning * into v_appt;
        update public.leads set appt_created_date = now() where id = l.id;
        update public.call_records set appointment_id = v_appt.id where id = v_call;
      end if;

      v_pay := v_pay || public.pay(v_me, p.id, r.pay_kind, l.id, v_appt.id, v_call);

    end if;

  elsif r.effect = 'confirm' then
    update public.appointments set
      status_id    = (select id from public.appointment_statuses where name = 'Confirmed'),
      confirmed_at = now(),
      confirmed_by = v_me,
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := v_pay || public.pay(v_me, coalesce(v_appt.set_project_id, p.id), 'confirmation', l.id, v_appt.id, v_call);
    -- The client hears now only if QA has already let them see it.
    if coalesce(v_appt.qa_status, 'passed') = 'passed' then
      perform public.notify_client_appointment(v_appt.id, true);
    end if;

  elsif r.effect = 'reschedule' then
    -- Appointment-Rescheduled (Sean, Nov 2026): the same appointment, on its new day and time. One marked
    -- invalid is an appointment again: its pay back to whoever set it, as a new appointment, and its
    -- confirmation still to come. One already confirmed is to be confirmed again, its confirmation pay
    -- taken back until it is. Counted against whoever set it (how many of theirs need rescheduling).
    v_date := nullif(p_appointment->>'date', '')::date;
    v_time := nullif(btrim(coalesce(p_appointment->>'time', '')), '');
    if v_date is null then
      raise exception 'Choose the new appointment date' using errcode = '22023';
    end if;
    if v_date < (now() at time zone public.business_tz())::date then
      raise exception 'The appointment date has passed' using errcode = '22023';
    end if;
    if v_time is null then
      raise exception 'Choose the new appointment time' using errcode = '22023';
    end if;
    if v_time !~* '^\d{1,2}:\d{2}\s?(AM|PM)$' then
      raise exception 'Give the time like 9:30 AM' using errcode = '22023';
    end if;
    if v_appt.invalid_at is null and (v_appt.appt_date, coalesce(v_appt.appt_time, '')) = (v_date, v_time) then
      raise exception 'Choose the new appointment date or time: it is set for then already' using errcode = '22023';
    end if;
    v_was := v_appt;

    update public.appointments set
      appt_date    = v_date,
      appt_time    = v_time,
      duration_min = coalesce(nullif(p_appointment->>'duration', '')::int, duration_min),
      rep_name     = coalesce(nullif(btrim(coalesce(p_appointment->>'rep_name', '')), ''), rep_name),
      status_id    = coalesce((select id from public.appointment_statuses where name = 'Rescheduled'), status_id),
      invalid_at   = null,
      confirmed_at = null,
      confirmed_by = null,
      rescheduled_at    = now(),
      rescheduled_count = coalesce(rescheduled_count, 0) + 1,
      status_update_date = now()
    where id = v_appt.id
    returning * into v_appt;

    update public.call_records set
      appointment_id = v_appt.id,
      notes = concat_ws(E'\n', notes, 'Appointment moved from ' || to_char(v_was.appt_date, 'Mon FMDD')
                || coalesce(' ' || v_was.appt_time, '') || case when v_was.invalid_at is not null then ' (marked invalid)' else '' end
                || ' to ' || to_char(v_date, 'Mon FMDD') || ' ' || v_time)
    where id = v_call;

    if v_was.invalid_at is not null then
      v_pay := v_pay || public.pay(v_appt.user_id, coalesce(v_appt.set_project_id, p.id), 'appointment', l.id, v_appt.id, v_call, 'Appointment rescheduled');
    elsif v_was.confirmed_at is not null then
      v_pay := v_pay || public.charge_back(l.id, v_appt.id, array['confirmation'], v_call, 'Appointment rescheduled: paid again when confirmed');
    end if;

    -- The name is an appointment again, as it was set (the lead's result is what the reports count it by):
    -- off the call list, any call back cancelled. The call itself stays Appointment-Rescheduled.
    select cr.* into v_set from public.call_records c join public.call_results cr on cr.id = c.result_id
     where c.id = v_appt.call_record_id;
    select * into v_set from public.call_results
     where project_type = case l.stage when 'dbdev' then 'DBDV' else 'APPT' end
       and name = case when v_set.name in ('Appointment', 'Appointment-Phone') then v_set.name else 'Appointment' end;
    update public.leads set
      result_id        = v_set.id,
      call_result_appt = case when stage = 'appt' then v_set.name else call_result_appt end,
      call_result_dbdv = case when v_appt.set_stage = 'dbdev' or stage = 'dbdev' then v_set.name else call_result_dbdv end,
      status_id        = coalesce((select s.id from public.lead_statuses s where s.code = v_set.status_code), status_id),
      resolved_at      = coalesce(resolved_at, now()),
      call_back_on     = null
    where id = l.id;

    -- The client's people hear in Lighthouse too (their email says RESCHEDULED), once QA has let them see it.
    if coalesce(v_appt.qa_status, 'passed') = 'passed' then
      perform public.notify_users(
        array(select u.id from public.users u
               where u.role = 'client' and u.company_id = (select pr.company_id from public.projects pr where pr.id = coalesce(v_appt.project_id, l.project_id))),
        'appointment',
        'Appointment rescheduled: ' || coalesce(l.company_name, 'a lead'),
        concat_ws(' · ', 'Now ' || to_char(v_date, 'Dy Mon FMDD') || ' at ' || v_time, 'was ' || to_char(v_was.appt_date, 'Mon FMDD') || coalesce(' ' || v_was.appt_time, '')),
        '/calendar?view=day&d=' || v_date::text || '&a=' || v_appt.id,
        'appt_confirmed', null, v_appt.user_id);
    end if;

  elsif r.effect = 'appointment_invalid' then
    update public.appointments set
      invalid_at = now(),
      status_id  = (select id from public.appointment_statuses where name = 'Invalid'),
      status_update_date = now()
    where id = v_appt.id;
    update public.call_records set appointment_id = v_appt.id where id = v_call;
    v_pay := public.charge_back(l.id, v_appt.id, array['appointment', 'confirmation'], v_call, 'Appointment invalid');

  elsif r.effect = 'lead_invalid' then
    update public.leads set call_result_dbdv = 'Lead-Invalid' where id = l.id and source_project_id is not null;
    v_pay := public.charge_back(l.id, null, array['lead'], v_call, 'Lead invalid');
    -- No record of the original payment (an older lead): charge the developer at today's rate.
    if jsonb_array_length(v_pay) = 0 and l.dbdv_user_id is not null and l.source_project_id is not null then
      insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
      select l.dbdv_user_id, l.source_project_id, l.id, v_call, 'lead', -sp.lead_rate, 'Lead invalid (no original payment on record)', v_me
        from public.projects sp where sp.id = l.source_project_id;
      v_pay := jsonb_build_array(jsonb_build_object('user_id', l.dbdv_user_id, 'kind', 'lead',
                 'amount', -(select lead_rate from public.projects where id = l.source_project_id)));
    end if;
    if l.dbdv_user_id is not null then
      perform public.notify_users(
        array[l.dbdv_user_id], 'lead', 'Lead marked invalid: ' || coalesce(l.company_name, 'a lead'),
        concat_ws(' · ', 'Charged back on your production report', 'marked by ' || public.actor_name()),
        '/leads/' || l.id, 'lead_invalid');
    end if;

  elsif r.effect = 'correct_xdate' then
    if p_corrected_xdate is null then
      raise exception 'Enter the corrected renewal date' using errcode = '22023';
    end if;
    v_old_xdate := public.lead_renewal_date(l.id);
    -- The corrected date becomes the lead's ultimate X-date, which is its
    -- renewal; the dates on the individual policy lines are left as recorded.
    update public.insurance_details set ultimate_xdate = p_corrected_xdate where lead_id = l.id;
    if not found then
      insert into public.insurance_details (lead_id, ultimate_xdate) values (l.id, p_corrected_xdate);
    end if;
    update public.leads set original_xdate = coalesce(original_xdate, v_old_xdate) where id = l.id;
    update public.call_records
       set notes = concat_ws(E'\n', notes, 'Renewal corrected from '
                   || coalesce(to_char(v_old_xdate, 'FMMonth YYYY'), 'none') || ' to ' || to_char(p_corrected_xdate, 'FMMonth YYYY'))
     where id = v_call;

    -- Lead-Corrected pay (Sean, Nov 2026): the lead pay of the lead manager who developed it moves to
    -- whoever corrected it, once a lead. A lead with no developer on record names one (p_lead_manager:
    -- the lead manager picked, kept as its developer; 0: nobody, a lead we didn't develop, so no pay moves).
    v_dev := coalesce(l.dbdv_user_id, nullif(p_lead_manager, 0));
    if l.dbdv_user_id is null and p_lead_manager is null then
      raise exception 'Choose the lead manager who developed this lead' using errcode = '22023';
    end if;
    if l.dbdv_user_id is null and v_dev is not null then
      if not exists (select 1 from public.users where id = v_dev and role in ('admin', 'manager', 'agent')) then
        raise exception 'Choose a lead manager from the list' using errcode = '22023';
      end if;
      update public.leads set dbdv_user_id = v_dev where id = l.id;
    end if;
    if v_dev is not null and v_dev <> v_me and not exists (
         select 1 from public.pay_events pe
          where pe.lead_id = l.id and pe.kind = 'corrected' and not pe.is_chargeback
            and not exists (select 1 from public.pay_events x where x.reverses_id = pe.id)) then
      v_back := public.charge_back(l.id, null, array['lead'], v_call, 'Lead corrected by ' || public.actor_name());
      v_amt := coalesce(-(select sum((e->>'amount')::numeric) from jsonb_array_elements(v_back) e where e->>'kind' = 'lead'), 0);
      -- No record of the original payment (an older or imported lead): the developer is charged the project's lead rate.
      if v_amt = 0 then
        select pr.lead_rate into v_amt from public.projects pr where pr.id = coalesce(l.source_project_id, l.project_id);
        v_amt := coalesce(v_amt, 0);
        if v_amt > 0 then
          insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
          values (v_dev, coalesce(l.source_project_id, l.project_id), l.id, v_call, 'lead', -v_amt, 'Lead corrected (no original payment on record)', v_me);
          v_back := v_back || jsonb_build_array(jsonb_build_object('user_id', v_dev, 'kind', 'lead', 'amount', -v_amt));
        end if;
      end if;
      if v_amt > 0 then
        insert into public.pay_events (user_id, project_id, lead_id, call_record_id, kind, amount, note, created_by)
        values (v_me, p.id, l.id, v_call, 'corrected', v_amt,
                'Lead corrected, developed by ' || coalesce((select nullif(concat_ws(' ', first_name, last_name), '') from public.users where id = v_dev), 'another manager'), v_me);
        v_pay := v_pay || v_back || jsonb_build_array(jsonb_build_object('user_id', v_me, 'kind', 'corrected', 'amount', v_amt));
        perform public.notify_users(
          array[v_dev], 'lead', 'Lead corrected: ' || coalesce(l.company_name, 'a lead'),
          concat_ws(' · ', 'Its lead pay moves to ' || public.actor_name() || ', who corrected it', 'see the call on its Conversation'),
          '/leads/' || l.id);
      end if;
    end if;
  end if;

  -- A bonus hit with this result: its manager congratulated (Sean, Nov 2026).
  perform public.bonus_notify(v_me);

  -- What was said on the call joins the lead's internal notes, their running
  -- history (as the old system kept them), stamped as the rep wrote it.
  if v_notes is not null then
    insert into public.lead_notes (lead_id, notes)
    select l.id, btrim(c.notes) from public.call_records c where c.id = v_call
    on conflict (lead_id) do update
      set notes = concat_ws(E'\n', nullif(btrim(public.lead_notes.notes), ''), excluded.notes);
  end if;

  select * into l from public.leads where id = l.id;
  return jsonb_build_object(
    'call_record_id', v_call,
    'lead_id',        l.id,
    'result',         r.name,
    'stage',          l.stage,
    'project_id',     l.project_id,
    'promoted',       l.project_id is distinct from p.id,
    'on_list',        (select viable and callable from public.call_results where id = l.result_id) and l.assigned_user_id is not null,
    'appointment_id', v_appt.id,
    'rescheduled',    v_open.id is not null or r.effect = 'reschedule',
    'pay',            v_pay);
end $function$;


revoke execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text, bigint) from public, anon;
grant execute on function public.record_call_result(bigint, bigint, text, jsonb, date, date, text, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270219100000_call_summaries.sql
-- ==============================================================================================================

-- A recorded call's AI summary (client, Nov 2026): on "AI summary" under a transcribed call, Claude
-- reads its transcript and writes a short summary, kept with the recording so it's written once.
-- The server writes it with its own key (lib/server/call-summaries.js); it is read with the
-- recording, by whoever may play it.
--
--   summary          { "overview": "…", "points": ["…"], "next_step": "…" | null }
--   summary_at       when it was written
--   summary_model    the Claude model that wrote it
--
-- Safe to run more than once.

alter table public.phone_recordings
  add column if not exists summary       jsonb,
  add column if not exists summary_at    timestamptz,
  add column if not exists summary_model text;

grant update (summary, summary_at, summary_model) on public.phone_recordings to service_role;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270220100000_page_speed.sql
-- ==============================================================================================================

-- Pages faster on a full database (Nov 2026: "sometimes when I load other pages it takes too long").
-- Measured on a local copy with 200,000 names, 500,000 calls, 250,000 phone calls and 20,000
-- appointments; each function returns exactly what it did before (compared row for row).
--
--   projects_lead_stats   the Projects page: names matched to projects with an "or" join, every
--                         name against every project (16 million comparisons); now two plain
--                         matches over the names read once. 1.16 s -> 0.20 s
--   dashboard_stats       the Dashboard: one pass for the totals and windows, and the eight weeks
--                         counted once each (they were counted again for every week). 0.38 s -> 0.16 s
--   lead_explore          Lead Explorer: the employees check only when a range is given (it ran on
--                         every name, half the time), and only what the totals need kept for every
--                         match, the page's rows read in full. 1.2 s -> 0.43 s
--   lead_explore_options  Lead Explorer's pickers: only the columns counted, not every column of every
--                         name, and each carrier name's key worked out once. 1.0 s -> 0.5 s
--   user_workload         Account Managers: each person's names counted in one pass, not four
--                         lookups (one through every name's class) for every person. 0.92 s -> 0.08 s
--   report_stats          Reports: the six months' leads, appointments and ratings counted in one
--                         pass (each month went through every name again). 0.80 s -> 0.30 s
--   work_projects         a lead sheet and a call list: one project of My Projects worked out, not
--                         every one of the person's to find it (p_project_id). 0.30 s -> 0.015 s
--   appointments index    the Pipeline Report's "last appointment set" for each project and manager
--                         read through an index, not the whole table each row
--
-- Safe to run more than once.

create or replace function public.projects_lead_stats(p_companies bigint[] default null)
returns table(project_id bigint, names bigint, names_left bigint, leads bigint, leads_active bigint, developed bigint)
language sql stable set search_path = public as $$
  with ps as (
    select p.id from public.projects p where p_companies is null or p.company_id = any(p_companies)
  ), cls as materialized (
    -- The names, read once (Row Level Security decides whose).
    select c.project_id, c.source_project_id, c.stage, c.viable, c.developed from public.lead_classes c
  ), scoped as (
    -- A project's names: those on it, and those it sent on to another (as lead_stats() has them).
    select cls.project_id as pid, true as here, cls.stage, cls.viable, cls.developed
      from cls where cls.project_id in (select id from ps)
    union all
    select cls.source_project_id, false, cls.stage, cls.viable, cls.developed
      from cls where cls.source_project_id <> cls.project_id and cls.source_project_id in (select id from ps)
  )
  select pid, count(*),
         count(*) filter (where here and stage = 'dbdev' and viable),
         count(*) filter (where stage = 'appt'),
         count(*) filter (where stage = 'appt' and viable),
         count(*) filter (where developed)
    from scoped group by pid
  union all
  -- Every lead once, whichever projects it passed through (of those clients, when given).
  select null, count(*),
         count(*) filter (where stage = 'dbdev' and viable),
         count(*) filter (where stage = 'appt'),
         count(*) filter (where stage = 'appt' and viable),
         count(*) filter (where developed)
    from cls c
   where p_companies is null or c.project_id in (select id from ps);
$$;
revoke execute on function public.projects_lead_stats(bigint[]) from public, anon;
grant execute on function public.projects_lead_stats(bigint[]) to authenticated;

create or replace function public.dashboard_stats()
returns jsonb
language sql stable security invoker set search_path = public as $$
  with z as (
    select (now() at time zone public.business_tz())::date as today, now() as t
  ), per_project as (
    -- One pass over the leads: each project's count, and the dashboard's windows within it.
    select l.project_id, count(*) as n,
           count(*) filter (where coalesce(l.lead_date, l.created_at) >= z.t - interval '30 days') as d30,
           count(*) filter (where coalesce(l.lead_date, l.created_at) >= z.t - interval '60 days'
                              and coalesce(l.lead_date, l.created_at) < z.t - interval '30 days') as d30_60
      from public.leads l, z group by l.project_id
  ), lead_weeks as materialized (
    -- Each of the last eight weeks (0 the oldest; 7 ends now), from the same instants as before.
    select 7 - (ceil(extract(epoch from (z.t - coalesce(l.lead_date, l.created_at))) / 604800)::int - 1) as i, count(*) as n
      from public.leads l, z
     where coalesce(l.lead_date, l.created_at) >= z.t - interval '56 days' and coalesce(l.lead_date, l.created_at) < z.t
     group by 1
  ), ac as (
    select count(*) as total,
           count(*) filter (where a.appt_date = z.today) as today,
           count(*) filter (where a.appt_date between z.today - 6 and z.today) as d7,
           count(*) filter (where a.appt_date between z.today - 13 and z.today - 7) as d7_14
      from public.appointments a, z where a.invalid_at is null
  ), appt_weeks as materialized (
    select 7 - (z.today - a.appt_date) / 7 as i, count(*) as n
      from public.appointments a, z
     where a.invalid_at is null and a.appt_date between z.today - 55 and z.today
     group by 1
  )
  select jsonb_build_object(
    'leads_total',    (select coalesce(sum(n), 0) from per_project),
    'leads_30d',      (select coalesce(sum(d30), 0) from per_project),
    'leads_30_60d',   (select coalesce(sum(d30_60), 0) from per_project),
    'appts_total',    (select total from ac),
    'appts_today',    (select today from ac),
    'appts_7d',       (select d7 from ac),
    'appts_7_14d',    (select d7_14 from ac),
    'active_clients', (select count(*) from public.companies where status = 'active'),
    'weeks',          (select jsonb_agg(jsonb_build_object(
                          'leads', coalesce((select n from lead_weeks lw where lw.i = w.i), 0),
                          'appts', coalesce((select n from appt_weeks aw where aw.i = w.i), 0)
                        ) order by w.i) from generate_series(0, 7) as w(i)),
    'project_leads',  (select coalesce(jsonb_agg(coalesce(c.n, 0) order by p.id), '[]'::jsonb)
                         from public.projects p left join per_project c on c.project_id = p.id),
    'reps',           public.rep_workload()
  );
$$;

CREATE OR REPLACE FUNCTION public.lead_explore(criteria jsonb DEFAULT '{}'::jsonb, page integer DEFAULT 1, per_page integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  with seen as (
    -- A manager sees only the projects they are assigned to, shared ones too (client, Nov 2026); everyone else every project.
    select public.app_role() = 'manager' as limited,
           array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = public.app_user_id()) as ids
  ),
  c as (
    select
      array(select jsonb_array_elements_text(coalesce(criteria->'sic',       '[]'::jsonb)))          as sic,
      array(select jsonb_array_elements_text(coalesce(criteria->'states',    '[]'::jsonb)))          as states,
      array(select jsonb_array_elements_text(coalesce(criteria->'zips',      '[]'::jsonb)))          as zips,
      array(select jsonb_array_elements_text(coalesce(criteria->'counties',  '[]'::jsonb)))          as counties,
      array(select jsonb_array_elements_text(coalesce(criteria->'results',   '[]'::jsonb)))          as results,
      array(select (jsonb_array_elements_text(coalesce(criteria->'months',   '[]'::jsonb)))::int)    as months,
      array(select (jsonb_array_elements_text(coalesce(criteria->'clients',  '[]'::jsonb)))::bigint) as clients,
      array(select (jsonb_array_elements_text(coalesce(criteria->'projects', '[]'::jsonb)))::bigint) as projects,
      array(select (jsonb_array_elements_text(coalesce(criteria->'groups',   '[]'::jsonb)))::bigint) as groups,
      array(select jsonb_array_elements_text(coalesce(criteria->'carriers',  '[]'::jsonb)))          as carriers,
      array(select (jsonb_array_elements_text(coalesce(criteria->'reps',     '[]'::jsonb)))::bigint) as reps,
      case when criteria->>'emp_min' ~ '^\d{1,7}$' then (criteria->>'emp_min')::int end           as emp_min,
      case when criteria->>'emp_max' ~ '^\d{1,7}$' then (criteria->>'emp_max')::int end           as emp_max,
      coalesce(criteria->>'emp_not', '') = '1'                                                  as emp_not,
      public.search_patterns(public.search_words(criteria->>'q'))    as pats,
      public.search_lead_pattern(public.search_words(criteria->>'q')) as first_pat
  ),
  carrier_keys as (
    select coalesce(array_agg(distinct k) filter (where k is not null), '{}') as keys
      from (
        select public.carrier_key(v) as k from c, unnest(c.carriers) v where v !~ '^[0-9]+$'
        union all
        select public.carrier_key(a.name) from public.agencies a, c
         where a.id::text = any(array(select v from unnest(c.carriers) v where v ~ '^[0-9]{1,18}$'))
      ) t
  ),
  m as materialized (
    -- What the totals and breakdowns need, for every name that matches: narrow, so a full list stays quick
    -- (the page's rows are read in full below, not every match).
    select l.id, ins.id as ins_id, l.lead_date, l.state, l.sic_code,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name,
           r.name as result_name, r.viable as result_viable
      from public.leads l
      cross join c
      cross join carrier_keys ck
      cross join seen
      left join public.insurance_details ins on ins.lead_id = l.id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.call_results r on r.id = l.result_id
     -- Leads that have been promoted to an appointment project: a name still being developed is not one yet,
     -- whatever renewal dates it carries.
     where l.stage = 'appt'
       and (not seen.limited or l.project_id = any(seen.ids))
       and (cardinality(c.sic)      = 0 or l.sic_code         = any(c.sic))
       and (cardinality(c.states)   = 0 or l.state            = any(c.states))
       and (cardinality(c.zips)     = 0 or left(l.zip, 5)     = any(c.zips))
       and (cardinality(c.counties) = 0 or l.county           = any(c.counties))
       and (cardinality(c.results)  = 0 or coalesce(r.name, 'Not called yet') = any(c.results))
       and (cardinality(c.clients)  = 0 or co.id              = any(c.clients))
       and (cardinality(c.projects) = 0 or l.project_id       = any(c.projects))
       and (cardinality(c.groups)   = 0 or co.agency_group_id = any(c.groups))
       and (cardinality(c.carriers) = 0 or public.carrier_key(coalesce(ag.name, ins.agency_name)) = any(ck.keys))
       and (cardinality(c.reps)     = 0 or l.assigned_user_id = any(c.reps))
       -- Employees (the total) in a range, or not in it; a lead with no count is in no range.
       -- (Checked only when a range is given: without one every lead is in, and checking each one was half the search's time.)
       and (c.emp_min is null and c.emp_max is null
            or public.employees_in(jsonb_build_object('min', c.emp_min, 'max', c.emp_max, 'exclude', c.emp_not), l.employees))
       and (cardinality(c.months)   = 0 or extract(month from coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate,
              ins.health_xdate, ins.dental_xdate, ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)))::int = any(c.months))
       -- The longest word first, which the trigram index can answer; then every word.
       and (cardinality(c.pats)     = 0 or (l.search_text like c.first_pat and l.search_text like all (c.pats)))
  ),
  page as (
    select m.id, m.ins_id, m.lead_date from m
     order by m.lead_date desc nulls last, m.id desc
     limit greatest(least(coalesce(per_page, 10), (select case when limited then 100 else 10000 end from seen)), 1)
    offset least(greatest(coalesce(page, 1) - 1, 0)::bigint * greatest(least(coalesce(per_page, 10), (select case when limited then 100 else 10000 end from seen)), 1), 1000000000)
  ),
  win as (
    -- The page's rows in full, in the same order.
    select l.id, l.company_name, l.contact_name, l.contact_title, l.phone, l.contact_mobile, l.email,
           l.decision_maker, l.dm_title, l.dm_phone, l.dm_mobile, l.dm_email,
           l.contact2_name, l.contact2_title, l.contact2_phone, l.contact2_mobile, l.contact2_email, l.producer_name,
           l.city, l.state, l.zip, l.county, l.sic_code, l.lead_date,
           ins.ultimate_xdate,
           coalesce(ins.ultimate_xdate, least(ins.pkg_xdate, ins.wc_xdate, ins.auto_xdate, ins.health_xdate, ins.dental_xdate,
                                              ins.vision_xdate, ins.prof_liab_xdate, ins.do_xdate, ins.eo_xdate)) as renewal_date,
           co.id as client_id, co.name as client_name, grp.name as agency_group,
           coalesce(ag.name, nullif(btrim(ins.agency_name), '')) as carrier_name,
           r.id as result_id, r.name as result_name, r.viable as result_viable,
           l.project_id, p.name as project_name,
           -- When it was last called or changed.
           l.date_last_worked as last_worked,
           nullif(concat_ws(' ', u.first_name, u.last_name), '') as rep_name
      from page pg
      join public.leads l on l.id = pg.id
      left join public.insurance_details ins on ins.id = pg.ins_id
      left join public.projects p   on p.id  = l.project_id
      left join public.companies co on co.id = p.company_id
      left join public.agencies grp on grp.id = co.agency_group_id
      left join public.agencies ag  on ag.id = l.agency_id
      left join public.call_results r on r.id = l.result_id
      left join public.users u      on u.id  = l.assigned_user_id
     order by pg.lead_date desc nulls last, pg.id desc
  )
  select jsonb_build_object(
    'total',    (select count(*) from m),
    'rows',     (select coalesce(jsonb_agg(to_jsonb(win) order by win.lead_date desc nulls last, win.id desc), '[]'::jsonb) from win),
    'by_client', (select coalesce(jsonb_agg(jsonb_build_object('id', t.client_id, 'label', coalesce(t.client_name, 'Unassigned'), 'count', t.n)
                                            order by t.n desc, coalesce(t.client_name, 'zzz')), '[]'::jsonb)
                    from (select client_id, client_name, count(*) as n from m group by client_id, client_name) t),
    'by_state',  (select coalesce(jsonb_agg(jsonb_build_object('label', coalesce(t.state, '—'), 'count', t.n)
                                            order by t.n desc, coalesce(t.state, 'zz')), '[]'::jsonb)
                    from (select state, count(*) as n from m group by state) t),
    'by_month',  (select coalesce(jsonb_agg(jsonb_build_object('month', t.mon, 'label', to_char(to_date(t.mon::text, 'MM'), 'Mon'), 'count', t.n)
                                            order by t.mon), '[]'::jsonb)
                    from (select extract(month from renewal_date)::int as mon, count(*) as n
                            from m where renewal_date is not null group by 1) t),
    'by_industry', (select coalesce(jsonb_agg(jsonb_build_object('code', t.sic_code, 'label', coalesce(s.description, t.sic_code, '—'), 'count', t.n)
                                              order by t.n desc), '[]'::jsonb)
                      from (select sic_code, count(*) as n from m group by sic_code) t
                      left join public.sic_codes s on s.code = t.sic_code),
    'by_result', (select coalesce(jsonb_agg(jsonb_build_object('label', t.label, 'count', t.n)
                                            order by t.n desc, t.label), '[]'::jsonb)
                    from (select coalesce(result_name, 'Not called yet') as label, count(*) as n from m group by 1) t),
    'clients_touched', (select count(distinct client_id) from m where client_id is not null),
    'with_xdate',      (select count(*) from m where renewal_date is not null),
    -- Still to call for an appointment: a call result that leaves the lead viable (none yet counts).
    'viable',          (select count(*) from m where coalesce(result_viable, true))
  );
$function$;

CREATE OR REPLACE FUNCTION public.lead_explore_options()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with seen as (
    -- A manager sees only the projects they are assigned to, shared ones too (client, Nov 2026); everyone else every project.
    select public.app_role() = 'manager' as limited,
           array(select pa.project_id from public.project_assignments pa where pa.ae_user_id = public.app_user_id()) as ids
  ),
  l as materialized (
    -- Only what the pickers count, read once (every column of every name made this slow on a full list).
    select l.id, l.sic_code, l.state, l.county, l.result_id, l.project_id, l.agency_id
      from public.leads l, seen where l.stage = 'appt' and (not seen.limited or l.project_id = any(seen.ids))
  ),
  co as (
    select c.* from public.companies c, seen
     where not seen.limited or c.id in (select p.company_id from public.projects p where p.id = any(seen.ids))
  )
  select jsonb_build_object(
    'industries', (select coalesce(jsonb_agg(jsonb_build_object('value', t.sic_code, 'label', coalesce(s.description, t.sic_code), 'count', t.n)
                                             order by t.n desc), '[]'::jsonb)
                     from (select sic_code, count(*) as n from l where sic_code is not null group by sic_code) t
                     left join public.sic_codes s on s.code = t.sic_code),
    'states',     (select coalesce(jsonb_agg(jsonb_build_object('value', t.state, 'label', t.state, 'count', t.n)
                                             order by t.state), '[]'::jsonb)
                     from (select state, count(*) as n from l where state is not null group by state) t),
    'counties',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.county, 'label', t.county, 'count', t.n)
                                             order by t.county), '[]'::jsonb)
                     from (select county, count(*) as n from l where county is not null group by county) t),
    'results',    (select coalesce(jsonb_agg(jsonb_build_object('value', t.label, 'label', t.label, 'count', t.n) order by t.n desc, t.label), '[]'::jsonb)
                     from (select coalesce(r.name, 'Not called yet') as label, count(*) as n
                             from l left join public.call_results r on r.id = l.result_id
                            group by 1) t),
    'clients',    (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', name) order by name), '[]'::jsonb)
                     from co),
    'projects',   (select coalesce(jsonb_agg(jsonb_build_object('value', p.id, 'label', p.name, 'count', t.n) order by p.name), '[]'::jsonb)
                     from (select project_id, count(*) as n from l where project_id is not null group by 1) t
                     join public.projects p on p.id = t.project_id),
    'groups',     (select coalesce(jsonb_agg(jsonb_build_object('value', g.id, 'label', g.name, 'count', t.n) order by g.name), '[]'::jsonb)
                     from (select agency_group_id, count(*) as n from co where agency_group_id is not null group by 1) t
                     join public.agencies g on g.id = t.agency_group_id),
    'carriers',   (select coalesce(jsonb_agg(jsonb_build_object('value', t.k, 'label', t.label, 'count', t.n) order by t.k), '[]'::jsonb)
                     from (select k, (array_agg(label order by rec desc, label))[1] as label, sum(n)::bigint as n
                             from (select public.carrier_key(a.name) as k, btrim(a.name) as label, true as rec, 0 as n
                                     from public.agencies a
                                   union all
                                   -- The names' carriers counted by name first: each one's key worked out once, not once a lead.
                                   select public.carrier_key(c.name), btrim(c.name), false, c.n
                                     from (select coalesce(ag.name, ins.agency_name) as name, count(*) as n
                                             from l
                                             left join public.agencies ag on ag.id = l.agency_id
                                             left join public.insurance_details ins on ins.lead_id = l.id
                                            group by 1) c) x
                            where k is not null
                            group by k) t),
    'reps',       (select coalesce(jsonb_agg(jsonb_build_object('value', id, 'label', nullif(concat_ws(' ', first_name, last_name), '')) order by first_name, last_name), '[]'::jsonb)
                     from public.users where role in ('admin', 'manager', 'agent'))
  );
$function$;

-- The Pipeline Report's last appointment set, for each project (the one it was set on) and manager.
create index if not exists appointments_set_project on public.appointments ((coalesce(set_project_id, project_id)), user_id)
  where deleted_at is null;

create or replace view public.user_workload with (security_invoker = true) as
 select u.id as user_id,
        coalesce(l.lead_count, 0::bigint) as lead_count,
        coalesce(a.appt_count, 0::bigint) as appt_count,
        coalesce(l.names_left, 0::bigint) as names_left,
        coalesce(l.leads_held, 0::bigint) as leads_held
   from public.users u
   left join (
     -- Each manager's names, counted in one pass (it was four passes for every person).
     select l.assigned_user_id as uid, count(*) as lead_count,
            count(*) filter (where l.stage = 'appt') as leads_held,
            count(*) filter (where l.stage = 'dbdev' and r.viable) as names_left
       from public.leads l join public.call_results r on r.id = l.result_id
      where l.assigned_user_id is not null
      group by 1
   ) l on l.uid = u.id
   left join (
     select ap.user_id as uid, count(*) as appt_count from public.appointments ap
      where ap.invalid_at is null and ap.user_id is not null group by 1
   ) a on a.uid = u.id;

CREATE OR REPLACE FUNCTION public.report_stats()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with z as (
    select public.business_tz() as tz
  ), l as (
    select state, status_id, result_id, to_char(coalesce(lead_date, created_at) at time zone z.tz, 'YYYY-MM') as ym from public.leads, z
  ), a as (
    select status_id, to_char(appt_date, 'YYYY-MM') as ym from public.appointments where invalid_at is null
  ), f as (
    select rating, to_char(created_at at time zone z.tz, 'YYYY-MM') as ym from public.feedback, z where rating is not null
  ), months as (
    select i, date_trunc('month', now() at time zone z.tz) - (i * interval '1 month') as m
      from generate_series(0, 5) as i, z
  ), by_month as materialized (
    -- Each month's leads, appointments and ratings counted once (each month went through every name again).
    select ym, sum(leads)::bigint as leads, sum(appts)::bigint as appts, round(sum(rating_sum) / nullif(sum(ratings), 0), 1) as rating
      from (select ym, 1 as leads, 0 as appts, 0::numeric as rating_sum, 0 as ratings from l
            union all select ym, 0, 1, 0, 0 from a
            union all select ym, 0, 0, rating, 1 from f) x
     group by ym
  )
  select jsonb_build_object(
    'leads',          (select count(*) from l),
    'appts',          (select count(*) from a),
    'projects',       (select count(*) from public.projects),
    'held',           (select count(*) from a join public.appointment_statuses s on s.id = a.status_id where s.name = 'Held'),
    'ratings',        (select jsonb_build_object('count', count(rating), 'avg', coalesce(avg(rating), 0)) from f),
    -- Where the names stand, by call result (by name: the two stages share some).
    'by_status',      (select coalesce(jsonb_object_agg(c.name, c.n), '{}'::jsonb)
                         from (select r.name, count(*) as n from l join public.call_results r on r.id = l.result_id group by r.name) c),
    -- The same, each stage's results apart: { "APPT": {name: n}, "DBDV": {name: n} }.
    'by_result',      (select coalesce(jsonb_object_agg(t.project_type, t.results), '{}'::jsonb)
                         from (select c.project_type, jsonb_object_agg(c.name, c.n) as results
                                 from (select r.project_type, r.name, count(*) as n
                                         from l join public.call_results r on r.id = l.result_id
                                        group by r.project_type, r.name) c
                                group by c.project_type) t),
    'by_state',       (select coalesce(jsonb_agg(jsonb_build_array(t.state, t.n) order by t.n desc, t.state), '[]'::jsonb)
                         from (select state, count(*) as n from l where state is not null group by state order by n desc, state limit 8) t),
    'appt_by_status', (select coalesce(jsonb_object_agg(s.name, c.n), '{}'::jsonb)
                         from (select status_id, count(*) as n from a group by status_id) c
                         join public.appointment_statuses s on s.id = c.status_id),
    'months',         (select jsonb_agg(jsonb_build_object(
                          'key',    to_char(m.m, 'YYYY-MM'),
                          'label',  to_char(m.m, 'Mon'),
                          'leads',  coalesce(bm.leads, 0),
                          'appts',  coalesce(bm.appts, 0),
                          'rating', bm.rating
                        ) order by m.i desc) from months m left join by_month bm on bm.ym = to_char(m.m, 'YYYY-MM'))
  );
$function$;

-- work_projects: a lead sheet and a call list need one project of My Projects; every one of the person's
-- projects was worked out (an administrator's every project, four counts each) to find it.
drop function if exists public.work_projects();
CREATE OR REPLACE FUNCTION public.work_projects(p_project_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(id bigint, name text, client text, company_id bigint, type text, timezone text, state text, status text, appt_project_id bigint, names_left bigint, names_left_all bigint, follow_ups bigint, last_worked timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with me as materialized (select public.app_user_id() as uid, coalesce(public.is_admin(), false) as admin)
  select p.id, p.name, co.name, p.company_id, t.code, tz.name, p.state, ps.name, p.appt_project_id,
         (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
           where l.project_id = p.id and l.assigned_user_id = me.uid and r.viable and r.callable and (l.call_back_on is null or l.call_back_on <= public.business_today())),
         (select count(*) from public.leads l join public.call_results r on r.id = l.result_id
           where l.project_id = p.id and r.viable and r.callable and (l.call_back_on is null or l.call_back_on <= public.business_today())),
         (select count(*) from public.appointments a
           where a.set_project_id = p.id and coalesce(a.follow_up_user_id, a.user_id) = me.uid and a.confirmed_at is null and a.invalid_at is null
             and a.appt_date >= current_date - 1),
         (select max(c.call_date) from public.call_records c where c.project_id = p.id and c.user_id = me.uid)
    from public.projects p
    cross join me
    left join public.companies co        on co.id = p.company_id
    left join public.project_types t     on t.id = p.project_type_id
    left join public.timezones tz        on tz.id = p.timezone_id
    left join public.project_statuses ps on ps.id = p.status_id
   where me.uid is not null
     -- One project (a lead sheet's, a call list's): only it worked out, not every one of theirs.
     and (p_project_id is null or p.id = p_project_id)
     and (me.admin or exists (select 1 from public.project_assignments pa
                               where pa.project_id = p.id and pa.ae_user_id = me.uid))
   order by p.name;
$function$;
grant execute on function public.work_projects(bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270221100000_document_names.sql
-- ==============================================================================================================

-- Documents keep whose they are (Sean, Nov 2026: "I deleted those lists… can we set it up so the other data
-- will stay there so we know who the files belong to and what project?"). A file kept its lead, project and
-- client only as links, cleared when those are deleted (or hidden from the list when soft-deleted), so the
-- Documents page lost the business, project, agent and client. Now each file keeps their names as well:
--
--   business_name   the lead's business            project_name   its project
--   agent_name      the lead's producer, else the project's agent    client_name   the project's client
--
-- Filled as a file is added (tg_documents_from_lead, as it fills the project and client), and now for the
-- files already kept, from their leads, projects and clients, deleted ones included. The page shows the names
-- as they are now while those are there, these once they are gone, and filters by project and client on them.
--
-- Safe to run more than once.

alter table public.documents
  add column if not exists business_name text,
  add column if not exists project_name  text,
  add column if not exists agent_name    text,
  add column if not exists client_name   text;

create index if not exists documents_project_name on public.documents (project_name) where deleted_at is null;
create index if not exists documents_client_name on public.documents (client_name) where deleted_at is null;

create or replace function public.tg_documents_from_lead()
returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if new.lead_id is not null then
    select l.project_id, p.company_id into new.project_id, new.company_id
      from public.leads l left join public.projects p on p.id = l.project_id
     where l.id = new.lead_id;
    -- Whose it is, by name, kept with it (Sean, Nov 2026): it stays should the lead, project or client go.
    select l.company_name, p.name, coalesce(nullif(btrim(l.producer_name), ''), p.contact_name), c.name
      into new.business_name, new.project_name, new.agent_name, new.client_name
      from public.leads l
      left join public.projects p on p.id = l.project_id
      left join public.companies c on c.id = p.company_id
     where l.id = new.lead_id;
  elsif new.project_id is not null then
    select p.name, p.contact_name, c.name into new.project_name, new.agent_name, new.client_name
      from public.projects p left join public.companies c on c.id = p.company_id
     where p.id = new.project_id;
  end if;
  if new.client_name is null and new.company_id is not null then
    select c.name into new.client_name from public.companies c where c.id = new.company_id;
  end if;
  -- Whoever is signed in added it; the server's own role keeps what it was given.
  new.uploaded_by := coalesce(public.app_user_id(), new.uploaded_by);
  return new;
end $$;

-- The files already kept: their names from their leads, projects and clients, deleted (hidden) ones too.
-- Only where a name isn't kept yet.
update public.documents d set
  business_name = coalesce(d.business_name, l.company_name),
  project_name  = coalesce(d.project_name, p.name),
  agent_name    = coalesce(d.agent_name, nullif(btrim(l.producer_name), ''), p.contact_name),
  client_name   = coalesce(d.client_name, c.name)
  from public.documents x
  left join public.leads l on l.id = x.lead_id
  left join public.projects p on p.id = coalesce(x.project_id, l.project_id)
  left join public.companies c on c.id = coalesce(x.company_id, p.company_id)
 where d.id = x.id
   and (d.business_name is null or d.project_name is null or d.agent_name is null or d.client_name is null)
   and (l.id is not null or p.id is not null or c.id is not null);

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270222100000_team_for_clients.sql
-- ==============================================================================================================

-- Meet the Team for a client (Sean, Nov 2026: "only show them the team/managers that are assigned to their
-- projects. I don't want clients to see how many callers we have or see the manager names that aren't
-- associated with their projects"). A client's team_directory() is the people assigned to their projects
-- and their Sales Rep, each with what they do on their projects (and "Sales Rep"); no one else. Their
-- team_spotlight() is empty: it names the team's top people, theirs or not. Staff see what they did before.
-- works_with_client() counts their Sales Rep too, so a client can message and thank the people they see.
--
-- Safe to run more than once.

CREATE OR REPLACE FUNCTION public.team_directory()
 RETURNS TABLE(id bigint, name text, role text, photo_path text, bio text, mine boolean, does text, since date, status text, last_call timestamp with time zone, kudos bigint, birthday_today boolean, gifts_today bigint, leads_month bigint, appts_month bigint, leads_total bigint, appts_total bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select public.app_user_id() as uid, public.app_role() as role, public.business_tz() as tz
  ), day as (
    select (now() at time zone me.tz)::date as today, date_trunc('month', now() at time zone me.tz) as month_start, me.tz from me
  ), staff as (
    select u.* from public.users u, me
     where me.uid is not null and u.role in ('admin', 'manager', 'agent') and u.status = 'active' and u.deleted_at is null
       -- A client sees only their own team (Sean, Nov 2026): those assigned to their projects, and their Sales Rep;
       -- not how many callers there are, nor managers who aren't on their projects.
       and (me.role <> 'client'
            or u.id in (select pa.ae_user_id from public.project_assignments pa
                         where pa.project_id in (select public.client_project_ids()))
            or u.id in (select c.sales_rep_id from public.companies c where c.id = public.app_company_id()))
  ), theirs as (
    select p.id from public.projects p, me where me.role = 'client' and p.id in (select public.client_project_ids())
  ), rep as (
    -- A client's Sales Rep (Sean, Nov 2026): on their team with those on their projects.
    select c.sales_rep_id as uid from public.companies c, me where me.role = 'client' and c.id = public.app_company_id()
  ), kinds as (
    -- What each does: on a client's own projects, for a client (Nov 2026); on any, for staff.
    select pa.ae_user_id as uid, bool_or(t.code = 'DBDV') as dbdv, bool_or(t.code = 'APPT') as appt
      from public.project_assignments pa join public.projects p on p.id = pa.project_id and p.deleted_at is null
      join public.project_types t on t.id = p.project_type_id
      cross join me
     where me.role <> 'client' or p.id in (select id from theirs)
     group by 1
  ), calls as (
    select c.user_id, max(c.call_date) as last_call from public.call_records c, day
     where c.call_date >= (day.today::timestamp at time zone day.tz) group by 1
  ), dev as (
    select e.user_id,
           count(*) filter (where e.kind = 'lead' and e.created_at >= (day.month_start at time zone day.tz)) as leads_month,
           count(*) filter (where e.kind = 'appointment' and e.created_at >= (day.month_start at time zone day.tz)) as appts_month,
           count(*) filter (where e.kind = 'lead') as leads_total,
           count(*) filter (where e.kind = 'appointment') as appts_total
      from public.pay_events e, day, me
     where e.kind in ('lead', 'appointment') and not e.is_chargeback
       and (me.role <> 'client' or e.project_id in (select id from theirs))
       and (me.role = 'client' or e.created_at >= (day.month_start at time zone day.tz))
     group by 1
  ), k as (
    select to_user, count(*) filter (where kind = 'thanks') as thanks,
           count(*) filter (where kind = 'birthday' and created_at >= (day.today::timestamp at time zone day.tz)) as gifts_today
      from public.kudos, day group by 1
  )
  select s.id, nullif(btrim(concat_ws(' ', s.first_name, s.last_name)), ''), s.role, s.photo_path, s.bio,
         me.role = 'client',
         case when me.role = 'client' then
                -- A client's team: what each does on their projects, and their Sales Rep.
                nullif(concat_ws(' · ',
                  case when kd.dbdv and kd.appt then 'Lead development & appointment setting'
                       when kd.appt then 'Appointment setting' when kd.dbdv then 'Lead development' end,
                  case when s.id in (select uid from rep) then 'Sales Rep' end), '')
              when s.role = 'admin' then 'Administration'
              when kd.dbdv and kd.appt then 'Lead development & appointment setting'
              when kd.appt then 'Appointment setting' when kd.dbdv then 'Lead development' end,
         s.created_at::date,
         case when c.last_call > now() - interval '15 minutes' then 'calling'
              when c.last_call is not null or (s.last_login at time zone day.tz)::date = day.today then 'active'
              else 'away' end,
         c.last_call, coalesce(k.thanks, 0), public.birthday_on(s.birthday, day.today), coalesce(k.gifts_today, 0),
         coalesce(d.leads_month, 0), coalesce(d.appts_month, 0),
         case when me.role = 'client' then coalesce(d.leads_total, 0) end,
         case when me.role = 'client' then coalesce(d.appts_total, 0) end
    from staff s cross join me cross join day
    left join kinds kd on kd.uid = s.id
    left join calls c on c.user_id = s.id
    left join dev d on d.user_id = s.id
    left join k on k.to_user = s.id
   order by 6 desc, 12 desc, s.first_name, s.last_name;
$function$;

CREATE OR REPLACE FUNCTION public.team_spotlight()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with z as (
    select public.business_tz() as tz,
           (date_trunc('week', now() at time zone public.business_tz()))::timestamp at time zone public.business_tz() as since
  ), people as (
    select u.id, nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), '') as name, u.photo_path
      from public.users u where u.role in ('admin', 'manager', 'agent') and u.status = 'active' and u.deleted_at is null
  ), ev as (
    select e.user_id, count(*) filter (where e.kind = 'appointment') as appts, count(*) filter (where e.kind = 'lead') as leads
      from public.pay_events e, z where e.created_at >= z.since and not e.is_chargeback and e.kind in ('lead', 'appointment')
     group by 1
  ), ca as (
    select c.user_id, count(*) as calls from public.call_records c, z where c.call_date >= z.since group by 1
  ), top as (
    select 'appointments' as what, p.id, p.name, p.photo_path, ev.appts as n from ev join people p on p.id = ev.user_id where ev.appts > 0
    union all
    select 'leads', p.id, p.name, p.photo_path, ev.leads from ev join people p on p.id = ev.user_id where ev.leads > 0
    union all
    select 'calls', p.id, p.name, p.photo_path, ca.calls from ca join people p on p.id = ca.user_id where ca.calls > 0
  ), best as (
    select distinct on (what) what, id, name, photo_path, n from top order by what, n desc, name
  )
  select case when coalesce((select (value->>'spotlight')::boolean from public.app_settings where key = 'team'), true) is false then null
              when public.app_user_id() is null then null
              -- Not for a client (Sean, Nov 2026): it names the team's top people, theirs or not.
              when public.app_role() = 'client' then null
              else coalesce((select jsonb_object_agg(what, jsonb_build_object('id', id, 'name', name, 'photo', photo_path, 'count', n)) from best), '{}'::jsonb) end;
$function$;

CREATE OR REPLACE FUNCTION public.works_with_client(p_user_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.pay_events e where e.user_id = p_user_id and not e.is_chargeback
                    and e.project_id in (select public.client_project_ids()))
      or exists (select 1 from public.project_assignments pa where pa.ae_user_id = p_user_id
                    and pa.project_id in (select public.client_project_ids()))
      -- Their Sales Rep (Nov 2026): on their team, to message and thank.
      or exists (select 1 from public.companies c where c.id = public.app_company_id() and c.sales_rep_id = p_user_id);
$function$;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270223100000_lead_email_replies.sql
-- ==============================================================================================================

-- Email replies on the lead (Sean, Nov 2026: "the reply email is not attaching to this thread"). Each email
-- sent from a lead has a Reply-To address of its own (reply-<reply_token>@ the reply domain); Resend
-- receives the reply and tells Lighthouse (app/api/email/inbound), which keeps it here with the email it
-- answers, tells whoever sent that one, and sends them a copy.
--
--   direction        'out' an email sent from the lead; 'in' a reply to one
--   reply_token      an email sent: the token in its Reply-To address
--   from_address     a reply: who it is from ("Dana Reyes <dana@x.com>")
--   in_reply_to_id   a reply: the email it answers
--   resend_id        a reply: Resend's id for it (each kept once)
--
-- Safe to run more than once.

alter table public.lead_emails
  add column if not exists direction      text not null default 'out',
  add column if not exists reply_token    text,
  add column if not exists from_address   text,
  add column if not exists in_reply_to_id bigint references public.lead_emails(id) on delete set null,
  add column if not exists resend_id      text;

alter table public.lead_emails drop constraint if exists lead_emails_direction_check;
alter table public.lead_emails add constraint lead_emails_direction_check check (direction in ('out', 'in'));
alter table public.lead_emails drop constraint if exists lead_emails_status_check;
alter table public.lead_emails add constraint lead_emails_status_check check (status in ('sent', 'failed', 'received'));
alter table public.lead_emails drop constraint if exists lead_emails_from_address_check;
alter table public.lead_emails add constraint lead_emails_from_address_check check (length(from_address) <= 320);

create unique index if not exists lead_emails_reply_token on public.lead_emails (reply_token) where reply_token is not null;
create unique index if not exists lead_emails_resend_id on public.lead_emails (resend_id) where resend_id is not null;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270224100000_team_spotlight_for_clients.sql
-- ==============================================================================================================

-- Meet the Team's Spotlight for a client, on their own projects (Sean, Nov 2026: "Can it be set to only show
-- the stats for the managers on that specific client? I'd prefer not to show a client totals for a manager
-- across all clients"). For a client, the week's most appointments, leads and calls count only what was done
-- on their projects, by the people on their team (those assigned to their projects, and their Sales Rep);
-- a kind no one has done for them this week says so. Staff see the whole team's week, as before.
--
-- Safe to run more than once.

CREATE OR REPLACE FUNCTION public.team_spotlight()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with z as (
    select public.business_tz() as tz,
           (date_trunc('week', now() at time zone public.business_tz()))::timestamp at time zone public.business_tz() as since,
           public.app_role() = 'client' as client
  ), theirs as (
    -- A client's projects (none for staff: theirs is everyone's).
    select p.id from public.projects p, z where z.client and p.id in (select public.client_project_ids())
  ), people as (
    select u.id, nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), '') as name, u.photo_path
      from public.users u, z
     where u.role in ('admin', 'manager', 'agent') and u.status = 'active' and u.deleted_at is null
       -- A client's team only: those assigned to their projects, and their Sales Rep.
       and (not z.client
            or u.id in (select pa.ae_user_id from public.project_assignments pa where pa.project_id in (select id from theirs))
            or u.id in (select c.sales_rep_id from public.companies c where c.id = public.app_company_id()))
  ), ev as (
    select e.user_id, count(*) filter (where e.kind = 'appointment') as appts, count(*) filter (where e.kind = 'lead') as leads
      from public.pay_events e, z
     where e.created_at >= z.since and not e.is_chargeback and e.kind in ('lead', 'appointment')
       and (not z.client or e.project_id in (select id from theirs))
     group by 1
  ), ca as (
    select c.user_id, count(*) as calls from public.call_records c, z
     where c.call_date >= z.since and (not z.client or c.project_id in (select id from theirs))
     group by 1
  ), top as (
    select 'appointments' as what, p.id, p.name, p.photo_path, ev.appts as n from ev join people p on p.id = ev.user_id where ev.appts > 0
    union all
    select 'leads', p.id, p.name, p.photo_path, ev.leads from ev join people p on p.id = ev.user_id where ev.leads > 0
    union all
    select 'calls', p.id, p.name, p.photo_path, ca.calls from ca join people p on p.id = ca.user_id where ca.calls > 0
  ), best as (
    select distinct on (what) what, id, name, photo_path, n from top order by what, n desc, name
  )
  select case when coalesce((select (value->>'spotlight')::boolean from public.app_settings where key = 'team'), true) is false then null
              when public.app_user_id() is null then null
              else coalesce((select jsonb_object_agg(what, jsonb_build_object('id', id, 'name', name, 'photo', photo_path, 'count', n)) from best), '{}'::jsonb) end;
$function$;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270225100000_signature_select.sql
-- ==============================================================================================================

-- Signature Select (Sean, Nov 2026): the fee a client pays for Lighthouse, exclusivity on the leads we call for
-- them and appointment confirmations, one fee for all their projects, monthly or yearly. Kept term by term:
--
--   select_terms   a client's terms: monthly (an amount a month from its start; runs until an end date is put
--                  in, when they stop) or annual (an amount a year, for its start to its end). A renewal or a
--                  new rate is a new term; the earlier ones stay, for what has come in.
--
--   select_access_ended(company)   a client on Signature Select whose last term has ended and that has none
--                  now: its people's access to Lighthouse stops (client_project_ids() gives them nothing; the
--                  app says why). A client never on it is as before.
--   my_select()    a client's own: the term now and when it ends, for their renewal notice.
--   select_charges(from, to, company)   what is charged in a time: each month of a monthly term (on its start
--                  day), each annual term (on its start): the Signature Select report. Administrators.
--   send_select_reminders(day)     the Sales Rep (else the administrators) told two weeks before a term ends,
--                  once, unless a later term follows it already. Daily, with the other alerts.
--
-- Administrators and the client's Sales Rep see and change its terms. Safe to run more than once.

create table if not exists public.select_terms (
  id          bigint generated always as identity primary key,
  company_id  bigint not null references public.companies(id) on delete cascade,
  plan        text not null check (plan in ('monthly', 'annual')),
  amount      numeric(10, 2) not null check (amount > 0 and amount < 1000000),
  starts_on   date not null,
  ends_on     date,
  note        text check (length(note) <= 500),
  reminded_at timestamptz,
  created_by  bigint references public.users(id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint select_terms_annual_end check (plan = 'monthly' or ends_on is not null),
  constraint select_terms_dates check (ends_on is null or ends_on >= starts_on)
);
create index if not exists select_terms_company on public.select_terms (company_id, starts_on desc);

alter table public.select_terms enable row level security;
drop policy if exists select_terms_rw on public.select_terms;
create policy select_terms_rw on public.select_terms for all to authenticated
  using ((select public.is_admin()) or exists (select 1 from public.companies c where c.id = company_id and c.sales_rep_id = (select public.app_user_id())))
  with check ((select public.is_admin()) or exists (select 1 from public.companies c where c.id = company_id and c.sales_rep_id = (select public.app_user_id())));
grant select, insert, update, delete on public.select_terms to authenticated;

create or replace function public.select_access_ended(p_company bigint)
returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.select_terms t where t.company_id = p_company)
     and not exists (select 1 from public.select_terms t where t.company_id = p_company
                      and (t.ends_on is null or t.ends_on >= public.business_today()));
$$;
grant execute on function public.select_access_ended(bigint) to authenticated;

-- A client's people see their projects only while their Signature Select is on (or they were never on it).
create or replace function public.client_project_ids()
 returns setof bigint
 language sql stable security definer set search_path = public as $$
  select p.id from public.projects p
  where p.company_id = public.app_company_id() and p.deleted_at is null
    and not public.select_access_ended(p.company_id)
  union
  select pa.project_id from public.project_assignments pa
  where pa.cl_user_id = public.app_user_id()
    and exists (select 1 from public.projects p where p.id = pa.project_id and p.deleted_at is null
                 and not public.select_access_ended(p.company_id));
$$;

create or replace function public.my_select()
returns table (plan text, starts_on date, ends_on date, ended boolean)
language sql stable security definer set search_path = public as $$
  with mine as (select public.app_company_id() as company)
  select t.plan, t.starts_on, t.ends_on, public.select_access_ended(mine.company)
    from mine
    left join lateral (
      -- The term on now, else the last one.
      select * from public.select_terms t where t.company_id = mine.company
       order by (t.starts_on <= public.business_today() and (t.ends_on is null or t.ends_on >= public.business_today())) desc,
                t.starts_on desc limit 1
    ) t on true
   where mine.company is not null and t.plan is not null;
$$;
grant execute on function public.my_select() to authenticated;

create or replace function public.select_charges(p_from date, p_to date, p_company bigint default null)
returns table (term_id bigint, company_id bigint, client text, plan text, charged_on date, amount numeric)
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'The Signature Select report is for administrators' using errcode = '42501';
  end if;
  return query
  select t.id, t.company_id, c.name, t.plan, d.day::date, t.amount
    from public.select_terms t
    join public.companies c on c.id = t.company_id
    cross join lateral (
      select (t.starts_on + make_interval(months => m))::date as day
        from generate_series(0, case when t.plan = 'monthly' then 600 else 0 end) m
    ) d
   where (p_company is null or t.company_id = p_company)
     and d.day between p_from and p_to
     and d.day <= coalesce(t.ends_on, d.day)
     and d.day <= public.business_today()
   order by d.day, c.name;
end $$;
revoke execute on function public.select_charges(date, date, bigint) from public, anon;
grant execute on function public.select_charges(date, date, bigint) to authenticated;

create or replace function public.send_select_reminders(p_day date)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_count integer := 0;
  v_to bigint[];
  r record;
begin
  for r in
    select t.id, t.plan, t.amount, t.ends_on, c.id as company_id, c.name as client, c.sales_rep_id
      from public.select_terms t join public.companies c on c.id = t.company_id and c.deleted_at is null
     where t.reminded_at is null and t.ends_on between p_day and p_day + 14
       and not exists (select 1 from public.select_terms n where n.company_id = t.company_id and n.id <> t.id and n.starts_on > t.starts_on)
     for update of t skip locked
  loop
    v_to := case when r.sales_rep_id is not null then array[r.sales_rep_id]
                 else array(select u.id from public.users u where u.role = 'admin' and u.status = 'active' and u.deleted_at is null) end;
    perform public.notify_users(
      v_to, 'system',
      left(format('Signature Select ends %s: %s', to_char(r.ends_on, 'FMMon FMDD'), r.client), 160),
      left(format('%s · %s. Their access to Lighthouse stops after %s unless it is renewed.',
        initcap(r.plan), to_char(r.amount, 'FM$999,999,990.00') || case when r.plan = 'monthly' then ' a month' else ' a year' end,
        to_char(r.ends_on, 'FMMonth FMDD, YYYY')), 1000),
      '/payments#select', 'payment_due');
    update public.select_terms set reminded_at = now() where id = r.id;
    v_count := v_count + 1;
  end loop;
  return v_count;
end $$;

create or replace function public.run_daily_alerts()
 returns integer
 language plpgsql security definer set search_path = public as $$
declare
  v_now timestamp := now() at time zone public.business_tz();
begin
  if extract(hour from v_now) < 7 then
    return 0;
  end if;
  return public.send_xdate_warnings(v_now::date) + public.send_appointment_reminders(v_now::date)
       + public.send_celebrations(v_now::date)
       + public.bill_project_months(v_now::date) + public.send_payment_reminders(v_now::date)
       + public.send_select_reminders(v_now::date);
end $$;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270226100000_client_login_projects.sql
-- ==============================================================================================================

-- Which of a client's projects each of its logins sees (Sean, Nov 2026: "A client is the parent account that
-- should view all of the projects the client is paying for. An agent are the child accounts for the projects
-- they are assigned to by the client... so an agent should only see the projects the client is buying for
-- them"). A client login is set, on Users, to see:
--
--   all    every project of its client (as before: the parent account)
--   only   only the projects ticked for it (client_user_projects): a producer of the client's
--
-- client_project_ids() follows it, so everything a client login reaches (projects, their names, appointments,
-- documents, reports) does. Administrators set it. Safe to run more than once.

alter table public.users add column if not exists project_scope text not null default 'all';
do $$ begin
  alter table public.users add constraint users_project_scope check (project_scope in ('all', 'only'));
exception when duplicate_object then null; end $$;
-- The users table grants its columns one by one.
grant update (project_scope) on public.users to authenticated;

create table if not exists public.client_user_projects (
  user_id    bigint not null references public.users(id) on delete cascade,
  project_id bigint not null references public.projects(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, project_id)
);
create index if not exists client_user_projects_project on public.client_user_projects (project_id);
alter table public.client_user_projects enable row level security;
drop policy if exists client_user_projects_admin on public.client_user_projects;
create policy client_user_projects_admin on public.client_user_projects for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
drop policy if exists client_user_projects_own on public.client_user_projects;
create policy client_user_projects_own on public.client_user_projects for select to authenticated
  using (user_id = (select public.app_user_id()));
grant select, insert, update, delete on public.client_user_projects to authenticated;

-- Only an administrator changes which projects a login sees (as its role and client account).
CREATE OR REPLACE FUNCTION public.tg_users_guard_protected_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user <> 'authenticated' then
    return new;
  end if;
  if public.is_admin() then
    return new;
  end if;
  if (new.role, new.status, new.company_id, new.auth_id, new.email, new.user_type_id, new.must_change_password, new.project_scope)
     is distinct from
     (old.role, old.status, old.company_id, old.auth_id, old.email, old.user_type_id, old.must_change_password, old.project_scope) then
    raise exception 'Only an administrator can change a user''s role, status, client account, projects or sign-in identity'
      using errcode = '42501';
  end if;
  return new;
end $function$;

-- A client login's projects: all its client's, or only those ticked for it (of its client's); either way
-- while its Signature Select is on. Projects assigned to it by name (project_assignments) as before.
create or replace function public.client_project_ids()
 returns setof bigint
 language sql stable security definer set search_path = public as $$
  with me as (
    select u.id, coalesce(u.project_scope, 'all') as scope from public.users u where u.id = public.app_user_id()
  )
  select p.id from public.projects p, me
  where me.scope = 'all' and p.company_id = public.app_company_id() and p.deleted_at is null
    and not public.select_access_ended(p.company_id)
  union
  select p.id from public.client_user_projects cup
    join me on me.id = cup.user_id and me.scope = 'only'
    join public.projects p on p.id = cup.project_id
  where p.company_id = public.app_company_id() and p.deleted_at is null
    and not public.select_access_ended(p.company_id)
  union
  select pa.project_id from public.project_assignments pa
  where pa.cl_user_id = public.app_user_id()
    and exists (select 1 from public.projects p where p.id = pa.project_id and p.deleted_at is null
                 and not public.select_access_ended(p.company_id));
$$;

-- What a client login sees beyond its projects (its client's own records: goals, removal requests): only a
-- login that sees all its client's projects.
create or replace function public.client_sees_all()
returns boolean
language sql stable security definer set search_path = public as $$
  select coalesce((select u.project_scope = 'all' from public.users u where u.id = public.app_user_id()), true);
$$;
grant execute on function public.client_sees_all() to authenticated;

-- Appointment updates, documents and removal requests: a login kept to some projects sees those projects' only.
drop policy if exists appointment_updates_read on public.appointment_updates;
create policy appointment_updates_read on public.appointment_updates for select to authenticated
  using ((select public.is_staff())
         or (company_id = (select public.app_company_id()) and ((select public.client_sees_all()) or project_id in (select public.client_project_ids()))));
drop policy if exists documents_read on public.documents;
create policy documents_read on public.documents for select to authenticated
  using ((select public.is_staff())
         or (company_id = (select public.app_company_id()) and (select public.client_sees_all()))
         or project_id in (select public.client_project_ids()));
drop policy if exists client_removals_read on public.client_removals;
create policy client_removals_read on public.client_removals for select
  using ((select public.is_staff())
         or (company_id = (select public.app_company_id())
             and ((select public.client_sees_all())
                  or exists (select 1 from public.leads l where l.id = lead_id and l.project_id in (select public.client_project_ids())))));

create or replace function public.lead_client_updates(p_lead_id bigint)
 RETURNS TABLE(id bigint, appointment_id bigint, status text, previous_status text, note text, potential_premium numeric, sold_lines jsonb, total_premium numeric, created_at timestamp with time zone, by_name text, by_client boolean, appt_date date, appt_time text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select x.id, x.appointment_id, x.status, x.previous_status, x.note, x.potential_premium, x.sold_lines, x.total_premium, x.created_at,
         nullif(btrim(concat_ws(' ', u.first_name, u.last_name)), ''), u.role = 'client', a.appt_date, a.appt_time
    from public.appointment_updates x
    left join public.users u on u.id = x.created_by
    left join public.appointments a on a.id = x.appointment_id
   where x.lead_id = p_lead_id
     and public.app_user_id() is not null
     and (public.is_staff()
          or (x.company_id = public.app_company_id() and (public.client_sees_all() or x.project_id in (select public.client_project_ids()))))
   order by x.created_at desc, x.id desc
   limit 300;
$function$;

-- Taking names off: a client login, only names on the projects it sees.
CREATE OR REPLACE FUNCTION public.mark_names(p_ids bigint[], p_reason text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role    text := public.app_role();
  v_company bigint := public.app_company_id();
  v_me      bigint := public.app_user_id();
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
  v_label   text := case p_reason when 'deletion' then 'Deletion' when 'dont_call' then 'Don''t call' else 'Current customer' end;
  v_stamp   text := public.note_stamp();
  v_by      text;
  r         public.call_results;
  l         record;
  v_marked  int := 0;
  v_kept    int := 0;
begin
  if v_me is null or v_role not in ('admin', 'manager', 'client') then
    raise exception 'Only a client''s people, administrators and account managers can take names off' using errcode = '42501';
  end if;
  if p_reason is null or p_reason not in ('deletion', 'dont_call', 'current_customer') then
    raise exception 'Choose why these names come off' using errcode = '22023';
  end if;
  if coalesce(array_length(p_ids, 1), 0) = 0 then
    raise exception 'Choose the names to take off' using errcode = '22023';
  end if;
  if array_length(p_ids, 1) > 5000 then
    raise exception 'Take off up to 5,000 names at a time' using errcode = '22023';
  end if;
  select coalesce(nullif(btrim(concat_ws(' ', first_name, last_name)), ''), email) into v_by from public.users where id = v_me;

  for l in
    select x.id, x.project_id, x.result_id, p.company_id, public.project_type_code(x.project_id) as kind, cr.effect
      from public.leads x
      join public.projects p on p.id = x.project_id
      join public.call_results cr on cr.id = x.result_id
     where x.id = any(p_ids) and x.deleted_at is null
     order by x.id
       for update of x
  loop
    -- A client login: its client's names, on the projects it sees (Nov 2026: a login kept to some projects).
    if v_role = 'client' and (l.company_id is distinct from v_company or l.project_id not in (select public.client_project_ids())) then
      raise exception 'Those names are not on your lists' using errcode = '42501';
    end if;
    if l.effect not in ('none', 'pending', 'correct_xdate') then
      v_kept := v_kept + 1;
      continue;
    end if;
    select * into r from public.call_results
     where project_type = l.kind and applies_to = 'name' and client_removal = p_reason
     order by sort_order limit 1;
    if not found then
      raise exception 'No call result to mark these names with' using errcode = 'P0002';
    end if;
    if l.result_id is distinct from r.id then
      update public.leads
         set result_id = r.id,
             status_id = coalesce((select s.id from public.lead_statuses s where s.code = r.status_code), status_id),
             resolved_at = coalesce(resolved_at, now())
       where id = l.id;
    end if;
    perform public.add_name_note(l.id, v_stamp || ' Taken off the list by ' || coalesce(v_by, 'the client') || ': ' || v_label
                                      || coalesce(' (' || v_note || ')', '') || '.');
    update public.client_removals
       set reason = p_reason, note = coalesce(v_note, note), removed_by = v_me
     where lead_id = l.id;
    v_marked := v_marked + 1;
  end loop;
  return jsonb_build_object('marked', v_marked, 'kept', v_kept, 'reason', v_label);
end $function$;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270227100000_old_result_names.sql
-- ==============================================================================================================

-- The old system's call results, as Sean's test import showed them (Nov 2026):
--
--   "Call 0" … "Call 9"   a name called that many times with no contact: Viable-No Contact (now Viable-CallBack)
--                         on a DB Dev list; "XD-Call 0" … "XD-Call 9", Lead-No Contact on an appointment list.
--   "X-Date-Lead"         a lead: Lead-Hot Lead, as "X-Date Hot Lead" ("should be importing as Lead-Hot Lead").
--
-- Each old name belongs to one result of its kind of list: taken off any other first. Results are found by
-- their name or the old names they already answer to, so one renamed in Settings is still found.
-- Safe to run more than once.

do $$
declare
  v_calls text[] := array(select 'call ' || i from generate_series(0, 9) i)
                 || array(select 'call' || i from generate_series(0, 9) i)
                 || array(select 'call-' || i from generate_series(0, 9) i);
  v_xd_calls text[] := array(select 'xd-call ' || i from generate_series(0, 9) i)
                    || array(select 'xd call ' || i from generate_series(0, 9) i)
                    || array(select 'xd-call' || i from generate_series(0, 9) i);
  v_lead text[] := array['x-date-lead', 'x-date lead', 'xdate lead', 'xdate-lead'];
  v_target bigint;
begin
  -- DB Dev: Call 0–9.
  select id into v_target from public.call_results
   where project_type = 'DBDV' and (name in ('Viable-CallBack', 'Viable-No Contact') or 'viable-no contact' = any (aliases))
   order by (name = 'Viable-CallBack') desc limit 1;
  if v_target is not null then
    update public.call_results set aliases = array(select a from unnest(aliases) a where a <> all (v_calls))
     where project_type = 'DBDV' and id <> v_target and aliases && v_calls;
    update public.call_results set aliases = array(select distinct a from unnest(aliases || v_calls) a order by a) where id = v_target;
  end if;

  -- Appointment lists: XD-Call 0–9.
  select id into v_target from public.call_results
   where project_type = 'APPT' and (name = 'Lead-No Contact' or 'lead no contact' = any (aliases))
   order by (name = 'Lead-No Contact') desc limit 1;
  if v_target is not null then
    update public.call_results set aliases = array(select a from unnest(aliases) a where a <> all (v_xd_calls))
     where project_type = 'APPT' and id <> v_target and aliases && v_xd_calls;
    update public.call_results set aliases = array(select distinct a from unnest(aliases || v_xd_calls) a order by a) where id = v_target;
  end if;

  -- DB Dev: X-Date-Lead is a Lead-Hot Lead.
  select id into v_target from public.call_results
   where project_type = 'DBDV' and (name = 'Lead-Hot Lead' or 'x-date hot lead' = any (aliases))
   order by (name = 'Lead-Hot Lead') desc limit 1;
  if v_target is not null then
    update public.call_results set aliases = array(select a from unnest(aliases) a where a <> all (v_lead))
     where project_type = 'DBDV' and id <> v_target and aliases && v_lead;
    update public.call_results set aliases = array(select distinct a from unnest(aliases || v_lead) a order by a) where id = v_target;
  end if;
end $$;

-- ==============================================================================================================
-- 20270228100000_dashboard_conversion.sql
-- ==============================================================================================================

-- The administrator's dashboard tiles (Sean, Nov 2026):
--
--   A Sales Rep to show: the Leads and Appointments tiles count what the managers developed on that rep's
--   clients' projects (production_hours gains p_rep, for a day by the hour), and Active Clients counts their
--   clients (rep_client_stats).
--
--   Conversion by renewal month (renewal_conversion): "how many appts did we set vs leads that have/had a Jan
--   renewal month … this year vs last year … all or by sales rep clients". For a renewal month M of a year Y:
--     leads         the leads on appointment projects whose renewal month is M (their Ultimate X-date, else
--                   their soonest line's), developed before M/Y was out, and not closed out before its calling
--                   window began (still in the pipeline for that renewal);
--     appointments  those of them with an appointment set in its calling window: the four months before M/Y
--                   and M/Y itself (as the Match Tool's "renew in the next four months").
--   By renewal month, not the date itself: renewal dates are moved on a year as they come round.
--
-- Administrators only. Safe to run more than once.

drop function if exists public.production_hours(date, bigint);
create or replace function public.production_hours(p_day date, p_user bigint default null, p_rep bigint default null)
 returns table(hour integer, leads bigint, appointments bigint)
 language plpgsql
 stable
 set search_path to 'public'
as $function$
declare
  v_tz   text   := public.business_tz();
  v_user bigint := case when public.is_admin() then p_user else public.app_user_id() end;
  v_rep  bigint := case when public.is_admin() then p_rep else null end;
begin
  if p_day is null then
    raise exception 'Choose a day' using errcode = '22023';
  end if;
  return query
  select extract(hour from pe.created_at at time zone v_tz)::integer,
         count(*) filter (where pe.kind = 'lead'),
         count(*) filter (where pe.kind = 'appointment')
    from public.pay_events pe
   where pe.created_at >= (p_day::timestamp at time zone v_tz)
     and pe.created_at <  ((p_day + 1)::timestamp at time zone v_tz)
     and pe.user_id is not null and not pe.is_chargeback
     and pe.kind in ('lead', 'appointment')
     and (v_user is null or pe.user_id = v_user)
     -- A Sales Rep's clients' projects (Nov 2026).
     and (v_rep is null or pe.project_id in (select p.id from public.projects p join public.companies c on c.id = p.company_id where c.sales_rep_id = v_rep))
   group by 1
   order by 1;
end $function$;
grant execute on function public.production_hours(date, bigint, bigint) to authenticated;

-- A Sales Rep's clients for the Active Clients tile: how many are active, and each of their projects' leads.
create or replace function public.rep_client_stats(p_rep bigint)
returns jsonb
language plpgsql stable security definer set search_path = public as $$
begin
  if not public.is_admin() then
    raise exception 'For administrators' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'active_clients', (select count(*) from public.companies c where c.status = 'active' and c.deleted_at is null and c.sales_rep_id = p_rep),
    'project_leads', (select coalesce(jsonb_agg(n order by pid), '[]'::jsonb) from (
        select p.id as pid, (select count(*) from public.leads l where l.project_id = p.id and l.deleted_at is null) as n
          from public.projects p join public.companies c on c.id = p.company_id
         where c.sales_rep_id = p_rep and p.deleted_at is null and c.deleted_at is null) x));
end $$;
grant execute on function public.rep_client_stats(bigint) to authenticated;

create or replace function public.renewal_conversion(p_year integer, p_rep bigint default null)
returns table(year integer, month integer, leads bigint, appointments bigint)
language plpgsql stable security definer set search_path = public set work_mem = '64MB' as $$
begin
  if not public.is_admin() then
    raise exception 'For administrators' using errcode = '42501';
  end if;
  if p_year is null or p_year < 2000 or p_year > 2100 then
    raise exception 'Choose a year' using errcode = '22023';
  end if;
  return query
  with cohorts as (
    -- Each renewal month of the year chosen and the year before, with its calling window.
    select y::int as year, m::int as month,
           (make_date(y::int, m::int, 1) - interval '4 months')::date as opens,
           (make_date(y::int, m::int, 1) + interval '1 month')::date as closes
      from generate_series(p_year - 1, p_year) y, generate_series(1, 12) m
  ), pipeline as (
    -- The leads on appointment projects (a Sales Rep's clients' only, when one is chosen), each with its renewal month.
    select l.id, coalesce(l.promoted_at, l.created_at) as developed, l.resolved_at,
           extract(month from r.renewal)::int as month
      from public.leads l
      join public.projects p on p.id = l.project_id and p.deleted_at is null
      join public.project_types t on t.id = p.project_type_id and t.code = 'APPT'
      left join public.companies c on c.id = p.company_id
      cross join lateral (
        select min(coalesce(i.ultimate_xdate, least(i.pkg_xdate, i.wc_xdate, i.auto_xdate, i.health_xdate, i.dental_xdate,
                                                     i.vision_xdate, i.prof_liab_xdate, i.do_xdate, i.eo_xdate))) as renewal
          from public.insurance_details i where i.lead_id = l.id
      ) r
     where l.deleted_at is null and l.stage = 'appt' and r.renewal is not null
       and (p_rep is null or c.sales_rep_id = p_rep)
  ), set_on as (
    -- When each of those leads had an appointment set (not one found invalid).
    select a.lead_id, a.appt_create_date as at
      from public.appointments a
     where a.deleted_at is null and a.invalid_at is null and a.lead_id in (select id from pipeline)
  )
  select k.year, k.month,
         count(pl.id)::bigint,
         count(pl.id) filter (where exists (
           select 1 from set_on s where s.lead_id = pl.id and s.at >= k.opens and s.at < k.closes))::bigint
    from cohorts k
    left join pipeline pl on pl.month = k.month
                         and pl.developed < k.closes
                         and (pl.resolved_at is null or pl.resolved_at >= k.opens)
   group by k.year, k.month
   order by k.year, k.month;
end $$;
revoke execute on function public.renewal_conversion(integer, bigint) from public, anon;
grant execute on function public.renewal_conversion(integer, bigint) to authenticated;

notify pgrst, 'reload schema';

-- ==============================================================================================================
-- 20270301100000_campaign_types.sql
-- ==============================================================================================================

-- Campaign Types (Sean, Nov 2026): a lead sheet's layout for an industry other than insurance (IT/MSPs first, and
-- Signature's own calls to agents). An administrator builds one in Settings from the insurance fields (each
-- renamed or turned off: the tabs, the Business details, the key date, the policy lines) and fields of their own;
-- a client is given one, and its leads show that layout, to staff and to the client. A client with none: Insurance,
-- as before. Call results, appointments and everything else stay as they are.
--
--   campaign_types            name, fields: { builtin: { <key>: { label, hidden } }, custom: [{ id, label, type, options }] }
--   companies.campaign_type_id   the client's (none: Insurance)
--   leads.custom              the answers to a campaign type's own fields, by field id
--
-- Everyone signed in reads the types (a client's lead sheet is laid out by its own); administrators change them.
-- Safe to run more than once.

create table if not exists public.campaign_types (
  id         bigint generated always as identity primary key,
  name       text not null check (length(btrim(name)) between 1 and 60),
  fields     jsonb not null default '{}'::jsonb,
  created_by bigint references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index if not exists campaign_types_name on public.campaign_types (lower(btrim(name)));

alter table public.campaign_types enable row level security;
drop policy if exists campaign_types_read on public.campaign_types;
create policy campaign_types_read on public.campaign_types for select to authenticated using (true);
drop policy if exists campaign_types_admin on public.campaign_types;
create policy campaign_types_admin on public.campaign_types for all to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
grant select, insert, update, delete on public.campaign_types to authenticated;

alter table public.companies add column if not exists campaign_type_id bigint references public.campaign_types(id) on delete set null;
alter table public.leads add column if not exists custom jsonb not null default '{}'::jsonb;

notify pgrst, 'reload schema';

